/* ============ Certified level: the Squire bank ============
   ORIGINAL WORK. Every question here was written from a syllabus in
   rewrite/categories/, never from a source question, and verified against the
   bank it replaces: 0 exact stem matches, maximum sequence ratio 0.560 against
   a 0.60 review threshold, longest shared word run 5 against a flag at 6,
   nothing flagged.
   GENERATED by rewrite/ship.py. Edit the category module, not this file.
   Short answers are graded by matchSA in js/core.js; the accept list is a
   contract, and rewrite/lib.py ports the grader so it can be tested.
   ============ */
var QUESTIONS=[
{"id": "c-sp1g5q2h", "cat": "Alsace", "q": "On paper Alsace's appellation count leapt from three to fifty-three in 2011, with not one new row of vines delimited. What happened?", "opts": ["Bas-Rhin and Haut-Rhin were each given a regional appellation of their own", "Vendanges Tardives and Selection de Grains Nobles were raised from label terms to appellations", "Every grand cru site became a separate appellation, replacing the single shared Alsace Grand Cru", "Cremant d'Alsace was split into separate white and rose appellations"], "a": 2, "exp": "Each of the fifty-one grand cru sites received a cahier des charges of its own in 2011, replacing the single shared Alsace Grand Cru appellation of 1975, while regional Alsace and Cremant d'Alsace carried on unchanged. The vineyards did not move an inch; the point was legal machinery, since a site with its own decree can tighten yields, admit a grape or sanction a blend without dragging fifty others through the amendment."},
{"id": "c-se3gyec3", "cat": "Alsace", "q": "Red wine reached the top of Alsace's hierarchy for the first time with the 2022 vintage, at two grand crus long planted to Pinot Noir; a decree of July 2024 admitted a third. Which three?", "opts": ["Hengst, Kirchberg de Barr and Vorbourg", "Rangen, Kitterle and Zinnkoepfle", "Schlossberg, Sommerberg and Wineck-Schlossberg", "Rosacker, Geisberg and Osterberg"], "a": 0, "exp": "Hengst and Kirchberg de Barr had built serious Pinot Noir reputations across decades in which the grand cru tier admitted only white wine, and their amended decrees let the red carry the site name from the 2022 vintage; Vorbourg joined them when the arrete of 4 July 2024 rewrote its cahier. Each keeps its white rules too, so a Hengst may still be a Gewurztraminer; the red is an addition, not a replacement."},
{"id": "c-6e06db4w", "cat": "Alsace", "q": "A 2005 amendment let one Alsace grand cru, Zotzenberg, write a grape from outside the noble four into its rules, honouring what its growers had always done best. Which grape?", "sa": 1, "accept": ["sylvaner", "silvaner", "sylvaner grape", "it is sylvaner", "gruner sylvaner"], "ans": "Sylvaner", "exp": "Sylvaner had grown on Zotzenberg's marl and limestone for generations while the noble-grape rule kept its name off the label, and the 2005 amendment recognised the tradition rather than inventing one. The concession is strictly local: on no other cru may the word Sylvaner appear, and Zotzenberg keeps the noble four alongside it."},
{"id": "c-rnipehwm", "cat": "Alsace", "q": "Site, vintage and the words Alsace Grand Cru appear on a bottle of Altenberg de Bergheim, yet nowhere does it name a grape. What does that silence say about what is in the bottle?", "sa": 1, "accept": ["it is a blend of varieties", "it is a blend", "blend", "a blend of grapes", "a blend of varieties", "the wine is a blend", "field blend", "a blend of several varieties", "blended from several varieties", "a blend of permitted varieties", "a mix of several grapes", "a mix of varieties", "a mix of grapes", "a mix of grape varieties", "multiple grape varieties", "multiple varieties", "more than one variety"], "ans": "A blend of several grapes", "exp": "Altenberg de Bergheim and Kaefferkopf are the crus whose rules sanction a blend, and a blended grand cru names no variety at all: the site is the whole claim. A single-variety bottling from the same slope still carries its grape, so the absent line is information, not an oversight."},
{"id": "c-m10i6vpa", "cat": "Alsace", "q": "Between plain Alsace and the crus, bottles labelled Alsace Cote de Rouffach or Alsace Ottrott occupy a rung of their own. What are those added names?", "opts": ["Bereich names kept from the German decades for export labels", "Communal denominations added to the appellation rules in 2011", "Fantasy names registered by merchant houses and protected as trademarks", "Grand cru sites relegated for exceeding their permitted yields"], "a": 1, "exp": "The 2011 rules wrote a family of geographic denominations into AOC Alsace, communal names such as Cote de Rouffach, Vallee Noble and Ottrott among them, giving the region the middle ground it lacked between anonymous regional wine and the crus. Several are tied to Pinot Noir rather than to whites: Ottrott, Rodern and Saint-Hippolyte earned their names on the red."},
{"id": "c-iw1ckejm", "cat": "Alsace", "q": "Below the grand cru tier an Alsace grower may still put a vineyard name on the label, and the rules charge for the privilege. What do they demand of the wine?", "sa": 1, "accept": ["lower yields and higher minimum ripeness", "lower yields and higher ripeness", "lower yields and riper fruit", "lower yields", "lower maximum yields", "reduced yields", "stricter yields and ripeness", "lower yields and higher must weights", "higher minimum ripeness", "a smaller crop and riper grapes", "a lower yield and a higher minimum ripeness", "smaller yields and riper grapes", "stricter yields", "a lower yield ceiling", "higher ripeness"], "ans": "Lower yields and higher minimum ripeness than plain Alsace", "exp": "A lieu-dit bottling must come in under a lower yield ceiling and reach a higher minimum ripeness than plain Alsace, the same bargain the crus strike at a higher pitch. The reward is a specific slope on the label without waiting for a grand cru list that has not grown since 2007."},
{"id": "c-75uok2dx", "cat": "Alsace", "q": "Picking for Vendanges Tardives, a Riesling grower in Alsace needs the must to reach a legal minimum sugar concentration. Give the figure.", "sa": 1, "accept": ["235 grams per litre", "235 grams per liter", "235 grams of sugar per litre", "235 grams of sugar per liter", "235 grams per litre of sugar", "235 g/l", "235g/l", "235 g per litre", "235 g per liter", "235 grams", "235 g", "235", "at least 235 grams per litre", "minimum 235 grams per litre", "235 grams per litre minimum", "at least 235 g/l", "minimum of 235 grams per litre", "235 g/l minimum", "235 grams/litre", "minimum 235 g/l", "at least 235", "minimum 235", "235 g/l of sugar", "235 grams per litre of must", "235 grammes per litre"], "ans": "235 grams per litre", "ex": 1, "exp": "Riesling and Muscat qualify for Vendanges Tardives at 235 grams of natural sugar per litre of must, while Gewurztraminer and Pinot Gris, which fatten far more easily, face 257; the figures were raised to those levels in 2001. Chaptalisation is banned outright for the term, so every gram must hang on the vine into the autumn."},
{"id": "c-00tcucag", "cat": "Alsace", "q": "Shrivelled Gewurztraminer coming in for Selection de Grains Nobles faces the stiffest sugar minimum in the Alsace rulebook. What is the figure?", "sa": 1, "accept": ["306 grams per litre", "306 grams per liter", "306 grams of sugar per litre", "306 grams of sugar per liter", "306 grams per litre of sugar", "306 g/l", "306g/l", "306 g per litre", "306 g per liter", "306 grams", "306 g", "306", "at least 306 grams per litre", "minimum 306 grams per litre", "306 grams per litre minimum", "at least 306 g/l", "minimum of 306 grams per litre", "306 g/l minimum", "306 grams/litre", "minimum of 306 g/l", "minimum 306 g/l", "at least 306", "minimum 306", "306 grammes per litre"], "ans": "306 grams per litre", "ex": 1, "exp": "Gewurztraminer and Pinot Gris must reach 306 grams of sugar per litre of must for Selection de Grains Nobles, against 276 for Riesling and Muscat. At that concentration ferments crawl and stop early of their own accord, which is why an SGN is always frankly sweet where a Vendanges Tardives merely promises ripeness."},
{"id": "c-nkjhjlij", "cat": "Alsace", "q": "A parcel of clean, late-picked Alsace Pinot Gris comes in at 260 grams of sugar per litre of must. Which of the region's two late-harvest terms is within reach?", "opts": ["Selection de Grains Nobles only", "Vendanges Tardives only", "Either term", "Neither term"], "a": 1, "exp": "The Vendanges Tardives floor for Pinot Gris stands at 257 grams per litre, so 260 clears it with a little in hand. Selection de Grains Nobles sits far above such fruit for the same grape and expects shrivelled, nobly rotted berries besides, so clean bunches at this ripeness leave one word open and one out of reach."},
{"id": "c-ur0x5kp7", "cat": "Alsace", "q": "Since the 2021 vintage a dryness indication is compulsory on Alsace's still whites, either as a printed scale or as one of four words. Which four?", "opts": ["Sec, demi-sec, moelleux, doux", "Sec, tendre, moelleux, liquoreux", "Trocken, halbtrocken, feinherb, mild", "Brut, extra-dry, sec, demi-sec"], "a": 0, "exp": "The four words track the European bands: sec up to roughly four grams of residual sugar with some latitude where acidity is high, demi-sec to about twelve, moelleux to about forty-five, doux beyond. A producer who prefers not to print words may use the graduated dryness gauge instead, but one or the other must appear."},
{"id": "c-3i8ky62n", "cat": "Alsace", "q": "Two categories of Alsace white stand outside the 2021 rule that a sweetness level must appear on the label. Which two?", "sa": 1, "accept": ["vendanges tardives and selection de grains nobles", "selection de grains nobles and vendanges tardives", "vendanges tardives and selections de grains nobles", "vt and sgn", "sgn and vt", "vt sgn", "sgn vt", "the late harvest categories", "the two late harvest categories", "vendanges tardives and sgn", "sgn and vendanges tardives", "both vt and selection de grains nobles", "vendange tardive and selection de grains nobles", "the late harvest wines", "the two late harvest wines"], "ans": "Vendanges Tardives and Selection de Grains Nobles", "exp": "Vendanges Tardives and Selection de Grains Nobles stand outside the obligation because each already answers to a legal regime of its own, with must weights and an official tasting behind the words. Every other still white claiming the Alsace name must carry the mention or the printed gauge from the 2021 vintage onward, and the arrete of 9 May 2022 wrote the same obligation, with the same two exceptions, into all fifty-one grand cru cahiers."},
{"id": "c-gkgmlxhx", "cat": "Alsace", "q": "Around Heiligenstein and four neighbouring communes, and nowhere else in France, one old pink-skinned variety keeps a protected mention of its own. Which grape hides behind the name Klevener de Heiligenstein?", "sa": 1, "accept": ["savagnin rose", "savagnin", "traminer", "savagnin rose grape", "it is savagnin rose", "rose savagnin", "pink savagnin", "roter traminer", "savagnin rose or traminer", "traminer or savagnin rose", "traminer rose", "rose traminer"], "ans": "Savagnin Rose", "ex": 1, "exp": "Klevener with the extra syllable is Savagnin Rose, planted around Heiligenstein since the eighteenth century and protected as a mention for five communes of the Bas-Rhin: Heiligenstein, Bourgheim, Gertwiller, Goxwiller and Obernai. The near-identical Klevner names a different and far commoner grape, and the single letter has parted many candidates from an exam mark."},
{"id": "c-sbkl5tsd", "cat": "Alsace", "q": "One guest adored last night's Gewurztraminer but wants something quieter, and the Alsace page of the list offers both Klevner and Klevener de Heiligenstein. Which bottle answers the request, and what makes it kin?", "opts": ["Klevener de Heiligenstein, a plainer cousin of the guest's grape", "Neither, as both name the house blend rather than any variety", "Klevner, a lighter, earlier-picked style of the same Gewurztraminer", "Either one, since the two words are only spellings of a single grape"], "a": 0, "exp": "Klevener de Heiligenstein is Gewurztraminer's quiet relation, pink-skinned but without the perfume engine, so it reads as a gentler take on a familiar register. Klevner, one letter shorter, is merely the old Alsatian word for Pinot Blanc, an amiable everyday white with no family tie to the guest's bottle at all."},
{"id": "c-ornwnapz", "cat": "Alsace", "q": "Chasselas and Sylvaner dominate a tank-blended Alsace white, Pinot Blanc fills it out, and no vintage will go on the bottle. Gentil is out of reach, so what may the label say?", "sa": 1, "accept": ["edelzwicker", "edelzwicker blend", "alsace edelzwicker", "it may say edelzwicker", "label it edelzwicker", "edelzwicker on the label", "edelzwicker with no vintage", "non vintage edelzwicker"], "ans": "Edelzwicker", "ex": 1, "exp": "Edelzwicker takes any mix of Alsace's permitted whites in any proportion, co-pressed or blended in tank, vintage optional, which is exactly the freedom Gentil surrenders: that word requires at least half of the blend from the noble four, each component vinified separately and shown to a panel, with a vintage on the label. The two names split the region's blends into the everyday and the examined. The noble prefix is not decoration: plain Zwicker, the old unregulated name for a blend of ordinary grapes, is not a sanctioned mention, so only the full word earns its place on the label."},
{"id": "c-b2xahg69", "cat": "Alsace", "q": "Perfume rules two of the noble varieties out of Alsace's sparkling cellars, and no Cremant may contain them. Which pair?", "opts": ["Riesling and Muscat", "Riesling and Pinot Gris", "Pinot Gris and Gewurztraminer", "Gewurztraminer and Muscat"], "a": 3, "exp": "The Cremant d'Alsace decree admits Pinot Blanc, Auxerrois, Pinot Gris, Pinot Noir, Riesling and Chardonnay, so of the noble four only the two most perfumed are missing. Gewurztraminer and Muscat would scent a base wine that the traditional method wants lean and neutral, while Chardonnay, unusable in still Alsace, is welcomed here for precisely that neutrality."},
{"id": "c-jj75j9n1", "cat": "Alsace", "q": "Tirage happens in spring; the rules then hold every bottle of Cremant d'Alsace in the cellar for a minimum stretch before sale. How long, counted from tirage?", "sa": 1, "accept": ["twelve months", "12 months", "twelve", "12", "one year", "a year", "twelve months from tirage", "12 months from tirage", "twelve months after tirage", "12 months after tirage", "at least twelve months", "at least 12 months", "twelve months minimum", "12 months minimum", "minimum of twelve months", "a full year", "one year from tirage", "a year from tirage", "one year after tirage", "twelve months before sale", "12 months before sale", "twelve months before release", "twelve months in the cellar", "12 months in the cellar"], "ans": "Twelve months", "ex": 1, "exp": "Twelve months must separate tirage from sale, and most of that time is spent on the lees of the second fermentation; the floor is common to the French Cremant family since their rules were harmonised. Serious houses treat it as a starting point rather than a target, and the difference between the floor and a long-aged cuvee is easy to taste."},
{"id": "c-cwbkyg9g", "cat": "Alsace", "q": "Above Kientzheim, the terraced Schlossberg grows celebrated Riesling on a thin, sandy, fast-draining soil. What rock breaks down into it?", "opts": ["Dolomitic limestone", "Volcanic greywacke", "Granite", "Blue schist"], "a": 2, "exp": "Granite rots into a coarse acid sand, fast to warm, free-draining and poor, so vigour stays low and acidity stays high, which is the Riesling recipe. The same grape on Rosacker's dolomitic limestone or the volcanic rock above Thann turns broader and smokier by turns, which is the case for fifty-one separate delimitations in the first place."},
{"id": "c-pqwwuyzi", "cat": "Alsace", "q": "A dark island of Steige schist above the town of Andlau carries one small Alsace grand cru whose Riesling outlives most of the region's. Name it.", "sa": 1, "accept": ["kastelberg", "the kastelberg cru", "kastelberg andlau"], "ans": "Kastelberg", "exp": "Kastelberg is the only Alsace grand cru on schist, a sliver of the dark Steige belt pinched against the granite above Andlau, and its Riesling is famously slow: austere young, mineral for decades. The abbey town has worked the slope since the early Middle Ages, which is roughly how long the site has held its name."},
{"id": "c-wzuqih6d", "cat": "Alsace", "q": "Granite crus like Brand and Sommerberg sit at the mouths of Vosges valleys, while Alsace's marl and limestone names string along the lower foothills. What arranged them that way?", "opts": ["The abbeys held the marl under ancient planting rights while the towns worked the granite", "Ice-age glaciers ferried granite blocks down from the summits and dumped them where the valleys open", "Limestone was laid down by the Rhine in terraces wherever the slope flattens toward the plain", "Valley streams sawed through the sedimentary skin to the old crystalline rock beneath"], "a": 3, "exp": "The foothill belt is the champ de fractures, a staircase of fault-dropped blocks whose limestone, marl and sandstone once roofed the whole range, and a valley is where a stream has cut clean through that roof into the granite and gneiss beneath. Which rock a cru sits on is therefore mostly a question of how much cover its patch of hillside has lost."},
{"id": "c-1a9mgy6r", "cat": "Australia", "q": "Chianti, Frascati and Beaujolais began disappearing from Australian labels in the 1990s, and in the same decade Australia registered protected place names of its own for the first time. What linked the two changes?", "opts": ["A treaty with Europe: their names came off the labels, and Australia had to build a register of its own names to trade with", "The Label Integrity Program, whose audits had no way to verify a borrowed name", "A High Court ruling that borrowed names such as Chablis had become misleading once Australian wine began exporting at serious scale", "A trademark campaign by the big companies, which had registered Europe's names abroad and wanted them defended at home"], "a": 0, "exp": "The 1994 wine agreement with the European Union committed Australia to phasing Europe's names off its labels, and that first wave went in the 1990s. The most valuable borrowings were not in it: Champagne, Chablis, Burgundy, Claret, Port and Sherry sat on an exempted list with no deadline at all, and only a second agreement retired them, with the last stock selling through in 2011. A country cannot demand protection for names it has never defined, so the law was amended to create a register of Geographical Indications with a committee to determine them, and the register exists to make origin enforceable, at home and in every market the agreement reaches."},
{"id": "c-j3tfw36p", "cat": "Australia", "q": "Before the register will call a district a region, its applicants must show far more than lines on a map. What is the test?", "opts": ["Fifty years of continuous documented viticulture inside the proposed line, proven from parish, council and company records", "Homogeneity in grape growing, at least five independent vineyards of five hectares each, and five hundred tonnes of grapes a year", "A panel tasting finding that wines grown inside the line share a recognisable style that stops at the boundary", "A soil survey establishing that one mapped soil type runs unbroken across the whole area"], "a": 1, "exp": "The regulations ask for a single tract of land, discrete from its neighbours and homogeneous in its growing attributes, with the five-vineyard, five-hectare and five-hundred-tonne figures as the floor of scale: five separately owned vineyards, each of at least five hectares, and in the order of five hundred tonnes of grapes produced in a year. Style and soil are deliberately absent from the test, which is the system in miniature: the law measures where, never how or what."},
{"id": "c-sd2t1i2l", "cat": "Australia", "q": "Fixing one South Australian region's edge took an interim ruling, tribunal hearings, a Federal Court appeal and the better part of a decade, with excluded growers fighting their way inside the line. Name the region.", "sa": 1, "accept": ["coonawarra", "coonawarra region", "coonawarra gi"], "ans": "Coonawarra", "exp": "The committee's first determination hewed close to the famous strip, and the growers drawn outside appealed through the tribunal and the Federal Court until the final boundary of 2003 took in most of the contested land. The case is the system's defining demonstration that when a law promises origin and nothing else, the map is the entire argument."},
{"id": "c-vckozx3u", "cat": "Australia", "q": "Growers spent years and serious money litigating over which paddocks fall inside a GI whose rules dictate nothing about grapes, yields or winemaking. What were they actually buying?", "opts": ["Rates: land inside a declared region is assessed and taxed as premium agricultural ground", "Water: in a shortage, South Australian irrigation allocations are cut along GI boundaries", "A yield ceiling: production caps inside the line prop up the price of every grower's fruit", "The name: origin is all a GI controls, so printing it is the line's whole value"], "a": 3, "exp": "The premium attaches to the word on the label rather than to anything the rules make the wine do, so being drawn outside the line reprices a vineyard overnight. That is the inversion at the heart of the system: French law fights over practices, Australian law only ever fights over maps."},
{"id": "c-eeiwiz7q", "cat": "Australia", "q": "Two Shiraz labels sit side by side, one reading Barossa and the other Barossa Valley, and the difference is not a house abbreviation. What does the shorter name allow?", "opts": ["Fruit from Eden Valley as well as the floor: Barossa is the zone holding both regions", "Fruit from anywhere in South Australia, the way South Eastern Australia works across the east", "Declassified young-vine fruit from the same vineyards, one tier down in the manner of a second label", "Nothing extra: the words are interchangeable in law, and the choice between them is typographic"], "a": 0, "exp": "The Barossa zone holds exactly two regions, the warm valley floor and the high ridges of Eden Valley a couple of hundred metres above it, and a blend across the pair falls back to the zone name. Producers reach for the single word deliberately: floor Shiraz for flesh, hill fruit for line, and a label that stays legally exact about the whole."},
{"id": "c-pecm9x1z", "cat": "Australia", "q": "Old vine appears on labels the world over with no law anywhere defining it, yet in the Barossa the words carry fixed ages. What gives them their teeth there?", "opts": ["Federal labelling law, which sets a national minimum age and audits the claim through vineyard records", "A certification trademark held by the South Australian government, licensed vineyard by vineyard", "A charter the growers wrote themselves, its tiers binding nobody but the producers who sign it", "The Barossa Valley GI, whose registered conditions of use write the age tiers into origin law"], "a": 2, "exp": "Its definitions bind only by signature, because Australian wine law is a law of origin: a GI says where and stops, and no statute anywhere in it defines the age of a vine. The charter exists to make the claim documented and auditable where the law offers nothing at all."},
{"id": "c-542nlnw7", "cat": "Australia", "q": "Seventy years in the ground moves a Barossa block onto the second rung of the Old Vine Charter. Which name does it earn?", "sa": 1, "accept": ["survivor vine", "survivor", "barossa survivor vine", "survivor vines", "survivor vine tier", "survivor tier"], "ans": "Survivor Vine", "exp": "The rungs sit at thirty-five, seventy, one hundred and one hundred and twenty-five years of continuous production, so a Survivor block has stood through at least seventy vintages. Age is counted from planting and has to be documented, which is much of the point: an old vineyard with papers is worth keeping in the ground."},
{"id": "c-7438gxxk", "cat": "Australia", "q": "In the mid-1980s a South Australian government program paid growers to rip vineyards out, and Shiraz planted in the 1880s went with them. Name the program.", "sa": 1, "accept": ["vine pull scheme", "vine pull", "vine pull program", "1985 vine pull scheme", "south australian vine pull scheme"], "ans": "The Vine Pull Scheme", "exp": "A grape glut and the collapse of fortified sales left old dry-grown blocks worth less than the land under them, and the scheme paid for clearance with no regard to age. Barossa Shiraz and Grenache from the 1880s went onto bonfires, and those losses are why the blocks that survived are now counted, documented and priced the way they are."},
{"id": "c-gy2e0avz", "cat": "Australia", "q": "Mid-January, while most of the country's whites hang weeks from picking, pickers strip Hunter Semillon at barely ten and a half baume. What has the winemaker gained by refusing to wait?", "opts": ["Bunches still firm enough for the machine harvesters the contracts require", "Ferocious acid, alcohol near eleven percent, and the crop in before the February rains break", "The green capsicum edge the style is built on, which another fortnight of sun would burn away", "A base lean enough to fortify economically, in the manner of the old Hunter trade"], "a": 1, "exp": "Hunter Semillon is a bet that flavour can be grown in bottle instead of on the vine: picked at ten to eleven baume it goes to tank, never sees oak, and tastes of lemon and little else at release. The same wine at ten years is toast, honey and lanolin, and the early date is also insurance, since the region's subtropical rain arrives in earnest just as the rest of the country starts picking."},
{"id": "c-yu0tfg7l", "cat": "Australia", "q": "Well into the 1980s, bottles of the Hunter's great dry white carried a varietal name that belonged to an entirely different grape. What did the labels say?", "sa": 1, "accept": ["hunter river riesling", "hunter riesling", "hunter valley riesling", "it was labelled hunter river riesling", "labelled hunter river riesling", "labelled as hunter river riesling", "they labelled it hunter river riesling", "they labelled it as hunter river riesling", "semillon labelled hunter river riesling", "semillon labelled as hunter river riesling", "sold as hunter river riesling", "it was sold as hunter river riesling", "marketed as hunter river riesling", "it was marketed as hunter river riesling", "they called it hunter river riesling", "it was called hunter river riesling", "was called hunter river riesling", "semillon sold as hunter river riesling", "labels said hunter river riesling", "label said hunter river riesling", "labels said it was hunter river riesling", "it said hunter river riesling", "they said hunter river riesling", "said hunter river riesling", "called it hunter river riesling"], "ans": "Hunter River Riesling", "ex": 1, "exp": "Varietal truth came late to Australian labels: the Hunter called its Semillon Riesling, Clare called Crouchen the same thing, and the true grape went by Rhine Riesling to keep them apart. The export boom and the label audits of the 1990s finished the habit, and the old name survives only on museum bottles."},
{"id": "c-04y1ddag", "cat": "Australia", "q": "From a Clare cellar comes a pair of bottles of one Riesling from the season its maker changed closures, bottled under both. Twenty years on, what does the pair typically show?", "opts": ["The screwcapped bottle the deeper gold of the pair, metal conducting heat into the wine faster than cork can", "Nothing between them but luck: closures decide taint, and development runs at one pace under both", "The corked bottle the fresher of the two, its slow breath of oxygen keeping the fruit alive", "The screwcapped wine paler and limier, the corked one deeper, broader and scattered bottle to bottle"], "a": 3, "exp": "Under cork the same wine browned faster and no two bottles agreed, which for a wine sold on decade-long ageing made every case a lottery. The screwcap stretched the arc and made it uniform, and Clare and Eden Riesling are now built for exactly that: bone dry and taut at bottling, expected to be opened anywhere along a twenty-year road."},
{"id": "c-jralyu7t", "cat": "Australia", "q": "Ask at an Australian cellar door and the screwcap often answers to a French brand name from the 1970s trials. Give the name.", "sa": 1, "accept": ["stelvin", "stelvin cap", "stelvin closure", "stelvin screwcap"], "ans": "Stelvin", "exp": "The cap was developed in France and trialled on Australian Riesling in the 1970s, a generation before the Clare growers revived it, and the brand went generic the way vacuum flasks became thermoses. Strictly it names one manufacturer's closure, but on an Australian list the word simply means the wine is not under cork."},
{"id": "c-v7zcaxvk", "cat": "Australia", "q": "Slate and shale break through the ground in one Clare Valley district whose Riesling runs flintier and sterner than the limestone valleys manage. Name the district.", "sa": 1, "accept": ["polish hill river", "polish hill", "polish hill river district", "polish hill river valley"], "ans": "Polish Hill River", "exp": "The district takes its name from the Polish families who settled it in the nineteenth century, and its broken slate gives a slower-opening, stonier Riesling than Watervale's limestone, which drinks earlier and rounder. Tasting the two side by side is the standard Clare lesson in how much the ground shows through one grape."},
{"id": "c-dlhxk31r", "cat": "Australia", "q": "A 1965 paper by a Perth agronomist matched an unplanted corner of Western Australia against Bordeaux's climate, and vineyards followed within a couple of years. Who wrote it?", "sa": 1, "accept": ["john gladstones", "gladstones", "dr john gladstones", "the agronomist john gladstones"], "ans": "John Gladstones", "exp": "Gladstones compared temperature, sunshine and rainfall records against Bordeaux and concluded the district would ripen Cabernet more reliably than anywhere then planted in the state; the first vines went in at Vasse Felix in 1967. Margaret River stands among the few celebrated regions anywhere founded on a published scientific argument rather than a settler's hunch."},
{"id": "c-l5sbrf3m", "cat": "Australia", "q": "Ironstone gravel over granite ridges around one brook carries the district where Margaret River's founding Cabernet estates cluster. Name the district.", "sa": 1, "accept": ["wilyabrup", "willyabrup", "wilyabrup district", "wilyabrup valley"], "ans": "Wilyabrup", "exp": "The gravelly loam drains freely and holds vigour down, which is the regional Cabernet claim in miniature, and the plantings of the late 1960s cluster on these ridges between the two capes. Wilyabrup began as growers' usage rather than a line in the register, and it appears on labels anyway because the trade knows what it means."},
{"id": "c-6oxzfynm", "cat": "Australia", "q": "Straggly bunches of tiny seedless berries mixed among normal ones mark the clone most Margaret River Chardonnay is grown on. Name it.", "sa": 1, "accept": ["gin gin clone", "gin gin", "gingin clone", "gingin", "mendoza clone", "mendoza", "gin gin chardonnay clone"], "ans": "The Gin Gin clone", "exp": "The clone came through the Gingin research station north of Perth and carries the Mendoza clone's hen-and-chicken set, which cuts yield and raises the skin-to-juice ratio. A good share of the intensity Margaret River Chardonnay is praised for is planted, not made."},
{"id": "c-1xysmk99", "cat": "Australia", "q": "Serious Australian Pinot Noir comes overwhelmingly from four places, each kept cool by a different lever. Which pairing runs true?", "opts": ["Hills east of Melbourne for the Yarra, altitude for Mornington, water on three sides for the Adelaide Hills, latitude for Tasmania", "Hills east of Melbourne for the Yarra, latitude for Mornington, altitude for the Adelaide Hills, water on three sides for Tasmania", "Hills east of Melbourne for the Yarra, water on three sides for Mornington, altitude for the Adelaide Hills, latitude for Tasmania", "Latitude for the Yarra, water on three sides for Mornington, altitude for the Adelaide Hills, hills east of Melbourne for Tasmania"], "a": 2, "exp": "Each lever buys the same slow ripening a different way: the Yarra climbs into the ranges, Mornington sits in the sea, the Adelaide Hills stand hundreds of metres over a hot city, and Tasmania is simply further south than anywhere on the mainland. Knowing which region pulls which lever is what lets a taster explain why four Pinots off one shelf differ the way they do."},
{"id": "c-8bom7gmj", "cat": "Australia", "q": "Up to four hundred metres at the valley's cool end, Chardonnay roots into deep red volcanic soil that the warmer floor around Coldstream lacks. Which part of the Yarra is that?", "sa": 1, "accept": ["upper yarra", "upper yarra valley", "upper yarra district", "upper yarra region", "upper yarra area", "upper yarra subregion", "upper yarra sub region", "the upper part of the yarra", "the upper part of the yarra valley", "the upper end of the yarra", "the upper end of the yarra valley", "upper yarra victoria", "upper yarra valley victoria"], "ans": "The Upper Yarra", "ex": 1, "exp": "The Upper Yarra around Hoddles Creek and Gladysdale sits higher and cooler than the old estates of the floor, on deep red volcanic ground where the lower valley runs to grey-brown loams. Fruit from up there carries the acid line the Chardonnay and sparkling houses hunt, and it can come off the vine weeks after the floor."},
{"id": "c-ak45j9sx", "cat": "Australia", "q": "Basalt caps the highest planted ground on the Mornington Peninsula, holding its coolest and latest vineyards, and the trade names that whole band of high country after one small township on it. Name the township.", "sa": 1, "accept": ["red hill", "red hill south", "red hill district"], "ans": "Red Hill", "exp": "The township is named for the iron-rich soil the basalt weathers to, which holds water into summer and sits high enough that picking runs weeks behind the sandier country toward Moorooduc, where the fruit ripens earlier and broader. The peninsula's tastings are organised by elevation as much as by producer, and Red Hill is the top of that ladder."},
{"id": "c-yshob13e", "cat": "Australia", "q": "Under trade pressure, Rutherglen's Muscadelle fortified had to stop calling itself Tokay, because the name belonged to a wine region on the other side of the world. Which region?", "sa": 1, "accept": ["tokaj", "tokaji", "hungary", "hungarian tokaj", "hungarian tokay", "tokaj in hungary", "tokay in hungary", "tokaji in hungary", "hungarian region of tokaj", "hungary's tokaj", "hungarys tokaj", "tokaj hegyalja", "tokaj hungary", "tokaji hungary", "tokaj region", "tokaji region", "region of tokaj", "tokaj region of hungary", "tokaj region in hungary", "it was tokaj", "it was hungary"], "ans": "Tokaj", "ex": 1, "exp": "Hungary's Tokaj is protected in every market the European agreements reach, so the borrowed spelling had to go. Rutherglen coined Topaque for its Muscadelle wine, an invented word with no place behind it, while the companion Muscat kept its name because Muscat names the grape rather than anybody's ground; the style never changed, only the passport."},
{"id": "c-w3wa03p4", "cat": "Australia", "q": "A drought summer on the Murray, and some inland growers pick as normal while neighbours let whole blocks burn off unwatered. What decided who farmed?", "opts": ["The water market: allocations trade separately from land, and that year's price beat the crop", "Rainfall: the river districts lie far enough apart that summer storms soak some and miss others entirely", "A federal ballot that shares the river's water among growers in proportion to their planted hectares", "Seniority: licences issued earliest draw first in a shortage, and the newest vineyards queue behind the orchards"], "a": 0, "exp": "Murray-Darling water is held as entitlements separate from land title, with each season's allocation priced on an open market, so in a drought a grower weighs the water's sale value against the crop's. The commercial tier runs on that arithmetic: the inland river regions grow the bulk of the national crush, and their vineyards exist only as long as the sums work."},
{"id": "c-iug1f8il", "cat": "Australia", "q": "In 1965 a Riverland winemaker patented a package that put a gallon of everyday wine in the fridge door, and it still moves a huge share of the commercial tier. What is it called in Australia?", "sa": 1, "accept": ["wine cask", "cask", "cask wine", "bag in box", "bag in box wine", "bag in box wine cask", "cardboard cask", "wine in a box", "goon bag", "goon sack", "goon", "box wine", "boxed wine", "box of wine", "wine box"], "ans": "The wine cask", "ex": 1, "exp": "Thomas Angove of Renmark patented the bag-in-box wine cask: a bladder that collapses as it empties, admitting no air, inside a carton that undercuts glass on every cost that matters. It is the natural package of the irrigated inland tier, and it taught a generation of Australians to buy wine by the litre."},
{"id": "c-8xypdoul", "cat": "Australia", "q": "At a capital-city wine show a single Riesling class ends the day with eleven gold medals, and nobody finds that odd. How are the medals decided?", "opts": ["By quota, with each judging panel issuing one gold for every ten entries that cross its bench", "Against a fixed score line: every wine that clears the mark takes a medal, whatever its class does", "By podium: the class is ranked and the top three take gold, silver and bronze, with ties shared", "By price bracket, the best wine under each price point taking home the gold for it"], "a": 1, "exp": "The capital-city shows judge each class against a score standard, so a medal goes to every wine over the line no matter how many that leaves, and the trophies above them are judged competitively among the golds. Medal stickers move stock off retail shelves, which is why companies enter at industrial scale and why show results have steered Australian style for a century."},
{"id": "c-6om81njd", "cat": "Australia", "q": "One Melbourne trophy for the show's best young red is credited with selling more wine than any review in the country. Name it.", "sa": 1, "accept": ["jimmy watson trophy", "jimmy watson", "jimmy watson memorial trophy"], "ans": "The Jimmy Watson Trophy", "exp": "It has been awarded at the Melbourne show since 1962 in memory of a city wine merchant, and its commercial pull is famous and famously argued over. For decades it could go to an unfinished wine still in barrel, so the bottle a customer eventually bought was a promise rather than the wine the judges tasted."},
{"id": "c-4x4mye7y", "cat": "Austria", "q": "Pepper in a dry Gruner Veltliner was the house style one region staked the entire DAC experiment on, standing alone for years before a second region followed. Name the pioneer.", "sa": 1, "accept": ["weinviertel", "weinviertel dac", "weinviertel region"], "ans": "Weinviertel", "exp": "The Weinviertel carried the first DAC, and its rules bound the name to a single variety so that the region would mean one recognisable thing on a list. The gamble was that a huge, diffuse area could be branded by its best habit, and the system that grew from it is the evidence it worked."},
{"id": "c-5kscg7gt", "cat": "Austria", "q": "Klassik rising to Reserve in one DAC, district narrowing through village to single Ried in another: the two ladders are measuring different things. What?", "opts": ["Sweetness in the first case; alcohol in the second", "Price positioning in both cases, expressed in two different regional vocabularies", "Style and weight in the first case; tightness of origin in the second", "Cask size in the first case; vine age in the second"], "a": 2, "exp": "The older DACs rank the wine itself: a Reserve must be riper, weightier and later to market than the plain bottling below it. The newer ones rank the ground instead, narrowing from the whole district to a village to a single named site, with the rules stiffening at each step. Austria runs both models side by side, which is why two DAC labels can look nothing alike."},
{"id": "c-m3lvw9m3", "cat": "Austria", "q": "Blaufrankisch was the grape trusted with the first DAC ever written for a red wine. Which region wrote it?", "sa": 1, "accept": ["mittelburgenland", "mittelburgenland dac", "blaufrankischland", "blaufraenkischland", "middle burgenland", "mittel burgenland", "mittelburgenland region", "mittelburgenland in burgenland"], "ans": "Mittelburgenland", "ex": 1, "exp": "Mittelburgenland was the first DAC cut for a red wine, resting on Blaufrankisch from deep, water-holding clay. The choice was the easy part: nowhere else in Austria is a single red grape so overwhelmingly the local habit."},
{"id": "c-v0n7g87c", "cat": "Austria", "q": "Somebody decided which grapes a Carnuntum red may carry and when it may be sold. Where does a DAC's rulebook actually come from?", "opts": ["Brussels writes it, since every DAC doubles as a European protected designation of origin", "The region's own wine committee drafts it; the ministry decrees it", "The Austrian Wine Marketing Board, as a condition of its export funding", "The federal tasting panel that assigns the Prufnummer"], "a": 1, "exp": "Each region's wine committee - growers, cellars and the trade together - agrees what is typical of the place, and the agriculture ministry turns that agreement into a binding ordinance. That is why permitted varieties, tiers and release dates differ so sharply from one DAC to the next: every rulebook is written at home first."},
{"id": "c-z2toj408", "cat": "Austria", "q": "Zierfandler and Rotgipfler had to wait longest: their home region was the last to receive a DAC, in 2023. Name it.", "sa": 1, "accept": ["thermenregion", "thermenregion dac", "thermenregion region"], "ans": "Thermenregion", "exp": "The Thermenregion DAC arrived in 2023, the most recent of the roster. Before it, the name was an ordinary Qualitatswein origin with no agreed style behind it; now the region itself defines what may carry it, as the rest of Austria's classic names already did."},
{"id": "c-z0d3nt5o", "cat": "Austria", "q": "A single Loibner Riesling carries both Wachau DAC and the word Federspiel on one label. How do the two claims stand to each other?", "opts": ["Federspiel is the DAC's own name for its village-level wines", "The older term lapsed when the DAC arrived, so the label is out of date", "One is law, one a private codex, and one label may carry both", "Federspiel is the DAC's middle tier, adopted word for word into the ordinance when the region joined"], "a": 2, "exp": "The DAC ordinance built the Wachau's legal pyramid and left Steinfeder, Federspiel and Smaragd untouched: they remain the Vinea Wachau's property, defined by its codex and printable only by its members. The two ladders answer different questions - the law says where and under what rules, the codex word says how ripe and how weighty."},
{"id": "c-j8kyqbip", "cat": "Austria", "q": "One harvest rule binds every tier of the Wachau DAC, from regional wine up to the greatest single Ried. What is it?", "sa": 1, "accept": ["harvest by hand", "hand harvest", "hand harvesting", "hand harvested", "hand picked", "hand picking", "picked by hand", "harvested by hand", "harvesting by hand", "picking by hand", "manual harvest", "manual harvesting", "must be picked by hand", "grapes are picked by hand", "manual picking", "picked manually", "manually picked", "~done by hand", "~be by hand", "~in by hand", "~only by hand", "~all by hand", "~grapes by hand", "~crop by hand", "~fruit by hand", "~harvest is by hand", "~harvesting is by hand", "~hand only", "~be manual", "~is manual", "~harvested manually", "~manually harvested", "~done manually", "~machine harvesting is banned", "~machine harvesting is forbidden"], "ans": "Harvest by hand", "exp": "Hand harvesting is written into the Wachau DAC for every category, which the terraces would demand anyway: no machine can work walled slopes. It is one of the clearest cases of a DAC codifying what the landscape already enforced."},
{"id": "c-orpgggw3", "cat": "Austria", "q": "Climb the Wachau pyramid to a named Ried and the permitted varieties collapse to a pair. Which pair?", "opts": ["Riesling and Weissburgunder", "Gruner Veltliner and Muskateller", "Riesling and Neuburger", "Gruner Veltliner and Riesling"], "a": 3, "exp": "Seventeen names sit on the Wachau's regional list and nine survive to village level, but a wine from one named Ried must be Gruner Veltliner or Riesling. The funnel is the design: the closer the origin, the fewer the styles the region will put its name behind."},
{"id": "c-1158i8x4", "cat": "Austria", "q": "Long the most celebrated holdout, the Wachau eventually took a DAC of its own. Which vintage was the first entitled to the letters?", "sa": 1, "accept": ["2020", "2020 vintage", "vintage 2020", "from 2020", "since 2020", "as of 2020", "from the 2020 vintage", "since the 2020 vintage", "as of the 2020 vintage"], "ans": "2020", "ex": 1, "exp": "The Wachau's DAC applies from the 2020 vintage, nearly two decades after the first of the roster. The delay was self-inflicted in the best sense: the region's own private rules were already stricter than the law in several respects, so the case for joining took years to become pressing."},
{"id": "c-xjynwjpv", "cat": "Austria", "q": "Ried Lamm, Ried Kellerberg: the first word is never decoration. What is the law using it to certify?", "opts": ["That the wine was bottled at the estate, inside the named village", "That the vineyard is a monopole in the hands of a single estate", "That what follows is an officially delimited vineyard site, and the wine Qualitatswein", "That the site has been classified Erste Lage or better under the 2023 ranking rules"], "a": 2, "exp": "Ried marks the name beside it as a registered vineyard site rather than a village, a brand or a fantasy, and vineyard names of that kind are reserved for Qualitatswein. Rank is a separate matter entirely: most Rieden are classified as nothing at all, and the word promises place, not pedigree."},
{"id": "c-lpra2nso", "cat": "Austria", "q": "For years Erste Lage stood on Kamptal labels with no law behind it, a private badge. What did the decree of 2023 change?", "opts": ["Nothing at all; the decree merely fixed how large such words may be printed", "The words became categories of wine law rather than a club's badge", "They were reserved for nobly sweet wines, on the model of the Pradikat ladder", "They were suspended until every region had finished drawing up a ranking of its own, to keep the map fair"], "a": 1, "exp": "The 2023 collective decree wrote Erste Lage and Grosse Lage into wine law, with applications judged on a site's history, its soils and the standing of its wines. Germany's Grosse Lage remains a growers' association's term; Austria's now carries the state behind it, and vineyard classification in statute is something France has and almost nobody else."},
{"id": "c-22ar7ieq", "cat": "Austria", "q": "However famous the site, no Austrian Ried can be born a Grosse Lage. What must come first?", "opts": ["A decade of declared vintages from every producer with rows on the site", "A unanimous vote of the regional wine committee, renewed each spring", "Purchase of the site by a single owner, so the wine speaks with one voice", "Five years standing as an Erste Lage before promotion can even be applied for"], "a": 3, "exp": "A site is appraised first as Erste Lage, and only after five years at that rank may Grosse Lage be applied for. The stagger keeps the top tier from being minted overnight and gives the market time to test the first verdict before the second is passed."},
{"id": "c-xhb310kr", "cat": "Austria", "q": "Erste Lage cannot land on a village wine: the 2023 rules allow classification only for wines of one DAC tier. Name the tier.", "sa": 1, "accept": ["riedenwein", "riedenwein tier", "riedenwein level", "riedenwein category", "ried wine", "ried wines", "ried level", "ried tier", "single vineyard wine", "single vineyard tier", "single vineyard level"], "ans": "Riedenwein", "exp": "Only a Riedenwein - the single-vineyard tier of a DAC's origin pyramid - can carry Erste Lage or Grosse Lage, so a region still ranking its wines by style has no rung for a classified site to stand on. The rule ties the new words to the narrowest origin the system knows: one wine, one named Ried."},
{"id": "c-8pzj5ruq", "cat": "Austria", "q": "Decades before the state moved, growers along the Danube banded together to map, rank and defend their best Rieden. Name their association.", "sa": 1, "accept": ["osterreichische traditionsweingueter", "osterreichische traditionsweinguter", "oesterreichische traditionsweingueter", "oesterreichische traditionsweinguter", "traditionsweingueter", "traditionsweinguter", "traditionsweingueter osterreich", "traditionsweinguter osterreich", "austrian traditional wine estates", "austrian traditional wineries", "otw", "the otw association", "~otw erste lage"], "ans": "Osterreichische Traditionsweingueter", "exp": "The Osterreichische Traditionsweingueter formed in the early 1990s around the Kamptal and Kremstal and, from 2010, ranked its members' sites under a private Erste Lage of its own, beginning with the 2009 vintage. Its maps, criteria and annual tastings supplied the raw material for the official classification that followed."},
{"id": "c-7qte1nlo", "cat": "Austria", "q": "Of three bottles on a shelf - a litre of Wein, a Landwein, a Kamptal Qualitatswein - exactly one wears the red-white-red strip. Which?", "opts": ["The Qualitatswein; nothing below that level wears the strip", "The litre of Wein; the strip stands in for the origin its label cannot state", "The Landwein; the strip marks country wine kept for the domestic market", "All three should wear it, so two of the bottles are out of compliance"], "a": 0, "exp": "The banderole belongs to Qualitatswein and Pradikatswein alone; Landwein and plain Wein never carry it. Its absence is therefore information in itself, telling a buyer at a glance which side of the quality line a bottle stands on."},
{"id": "c-2k9fx5ct", "cat": "Austria", "q": "Under the Leithaberg DAC, what must a red wine contain?", "opts": ["A majority of Zweigelt, seasoned with Blaufrankisch grown on the schist", "Blaufrankisch and nothing else, at every tier of the appellation", "Any red variety the wider Burgenland list allows, blended in whatever proportion the grower prefers", "At least eighty-five percent Blaufrankisch; the rest, Zweigelt, Sankt Laurent or Pinot Noir"], "a": 3, "exp": "The floor is eighty-five percent Blaufrankisch, and the remaining fifteen may come only from Zweigelt, Sankt Laurent or Pinot Noir, with the wine raised in barrel but not flavoured by it. The margin is for seasoning rather than restyling: the appellation wants its hills legible in the glass."},
{"id": "c-rq3lgkza", "cat": "Austria", "q": "A hill range on the border with Lower Austria lends its name to a Burgenland DAC whose rulebook includes a rose. Which?", "opts": ["Rosalia", "Carnuntum", "Leithaberg", "Neusiedlersee"], "a": 0, "exp": "Rosalia DAC takes its name from the Rosaliengebirge, the range along Burgenland's border with Lower Austria, and admits Blaufrankisch and Zweigelt as reds along with a rose, which few DAC rulebooks trouble to mention. Leithaberg is named for a range as well, so it is the pink wine in the rulebook and not the hills that settles which DAC the question means."},
{"id": "c-rm84uzt6", "cat": "Austria", "q": "A Neusiedlersee DAC Reserve may be a blend. What holds it together?", "opts": ["Sixty percent at least of the lead grape, the balance from other local reds", "A spine of Cabernet Sauvignon, the international note export markets ask for", "Equal parts of any two Burgenland reds, decided at the press house", "Whatever the vintage gives, so long as the finished wine clears the alcohol floor"], "a": 0, "exp": "Reserve wines must hold at least sixty percent of the region's lead variety, the balance drawn from other indigenous reds, and they see cask before release. The allowance recognises how the east shore actually farms: mixed red plantings that always found their way into the same vat."},
{"id": "c-wud2y7fg", "cat": "Austria", "q": "Flat sandy country on the lake's eastern shore built its DAC around a single red grape. Which?", "sa": 1, "accept": ["zweigelt", "blauer zweigelt", "rotburger"], "ans": "Zweigelt", "exp": "The Neusiedlersee DAC is built on Zweigelt, from fruity entry-level bottlings to the cask-aged Reserve, where it remains the compulsory backbone of any blend. The warm Seewinkel flats ripen it generously and reliably, which is exactly what a vigorous early ripener asks of a site."},
{"id": "c-hrys3brd", "cat": "Austria", "q": "Nowhere else does an Austrian DAC belong to a single town, and nowhere else is one written for nobly sweet wine alone. Name the DAC that is both.", "sa": 1, "accept": ["ruster ausbruch", "ruster ausbruch dac", "ausbruch dac", "rust ausbruch"], "ans": "Ruster Ausbruch", "exp": "Ruster Ausbruch DAC covers botrytis dessert wine from the free city of Rust and nothing else, the only DAC drawn around one town and the only one devoted wholly to sweet wine. The name it protects is centuries old; the DAC's work was to fence it legally to the place that made it famous."},
{"id": "c-94q7ikwv", "cat": "Austria", "q": "Growers around Deutsch Schutzen and Rechnitz, in Burgenland's far south, sell Blaufrankisch under a DAC named for a hill rather than for their region. Name it.", "sa": 1, "accept": ["eisenberg", "eisenberg dac"], "ans": "Eisenberg", "exp": "The DAC borrowed the name of the green-schist hill at the centre of Sudburgenland rather than the region's own, and its writ runs from Rechnitz in the north down past Deutsch Schutzen. Only here does Austrian Blaufrankisch grow on green schist, which is much of why the wines stand apart from those grown on the deep clay further north."},
{"id": "c-ccitz3db", "cat": "Austria", "q": "In 2018 an entire federal state joined the DAC system in one stroke, three regions at once. Name the trio.", "opts": ["Sudsteiermark, Weststeiermark and Weinland Steiermark", "Sudsteiermark, Vulkanland Steiermark and Weststeiermark", "Steirerland, Vulkanland Steiermark and Weststeiermark", "Sudsteiermark, Mittelsteiermark and Vulkanland Steiermark"], "a": 1, "exp": "Styria's three regions took their DACs together for the 2018 vintage, sharing one architecture drawn up state-wide. Part of the naming was already new: Sud-Oststeiermark had earlier rebranded itself Vulkanland Steiermark, trading a compass direction for its extinct volcanoes."},
{"id": "c-gibxf58w", "cat": "Austria", "q": "Before a single berry is pressed, Vienna's DAC has already been enforced in the row. What must exist on paper for the wine to claim it?", "opts": ["An entry in the city's vineyard register recording the parcel as a mixed planting", "A fresh soil analysis, renewed every five years by the federal cellars inspection", "A harvest date fixed by the city magistrate and posted at the row ends", "Proof that the parcel has carried vines continuously since the Habsburg era"], "a": 0, "exp": "The mixed planting has to exist as a fact of the land, recorded as such in the Viennese vineyard register, before any wine from the parcel can claim the DAC. That is the legal difference between a field blend and a cellar blend: the register can be checked, and a blend of separately grown lots has no entry to point to."},
{"id": "c-n7jfmq6z", "cat": "Austria", "q": "Every Styrian DAC lists it, and its single-Ried bottlings are what carry the state's reputation abroad. Name the white variety.", "sa": 1, "accept": ["sauvignon blanc", "sauvignon", "muskat silvaner", "muskat sylvaner", "sauvignon blanc muskat silvaner", "muskat silvaner sauvignon blanc", "sauvignon blanc or muskat silvaner", "sauvignon blanc grape"], "ans": "Sauvignon Blanc", "ex": 1, "exp": "Sauvignon Blanc is on the permitted list of all three Styrian DACs and is the variety the state's reputation now travels on, from taut regional bottlings up to the smoky, structured wines of a single Ried around villages like Gamlitz. Styria has grown it since the nineteenth century, long enough for the old local name Muskat-Silvaner to survive on cellar doors."},
{"id": "c-nua71d76", "cat": "Austria", "q": "Schilcher with a protected designation of origin can come from exactly one DAC. Which?", "sa": 1, "accept": ["weststeiermark", "weststeiermark dac", "west styria", "western styria", "schilcherland", "west steiermark", "west steiermark dac", "weststeiermark region", "schilcherland dac"], "ans": "Weststeiermark", "ex": 1, "exp": "Weststeiermark, nicknamed Schilcherland, holds the protected right to the style: Blauer Wildbacher pressed pink, screamingly fresh, off the steep hills around Stainz and Deutschlandsberg. The DAC lists white varieties too, but the pink wine is the reason the region has a name abroad."},
{"id": "c-302lj4mg", "cat": "Austria", "q": "A Krems grower interplants five white varieties, harvests them in one pass and ferments them together. Vienna's DAC name is closed to him; which traditional term may his label still carry?", "sa": 1, "accept": ["gemischter satz", "gemischter satz label", "gemischter satz field blend", "call it gemischter satz", "label it gemischter satz"], "ans": "Gemischter Satz", "ex": 1, "exp": "Gemischter Satz is a general Austrian term for a co-planted, co-harvested, co-fermented field blend, and any region may use it. What Krems fruit can never carry is the word Wiener in front of it: the DAC fenced the city's name, not the practice itself."},
{"id": "c-6gjay8xh", "cat": "Beer & Cider", "q": "Part of the mash is pumped to a separate vessel, boiled hard, and returned to lift the whole mass to its next rest temperature. Which mashing regime is that?", "opts": ["Parti-gyle brewing", "Step infusion mashing", "Decoction mashing", "Continuous sparging"], "a": 2, "exp": "Boiling a portion of the grain drove the temperature steps in the centuries before thermometers, and it builds melanoidins an infusion mash never makes, which is why Czech and Bavarian brewers kept the labour long after it stopped being necessary. A step infusion reaches the same rests with hot water additions or heating coils, and never boils grain at all."},
{"id": "c-51hqbsbm", "cat": "Beer & Cider", "q": "This year's bales of a bittering hop assay at 2.9 percent alpha acid where last year's lot ran 4.2. To hold a flagship beer's bitterness on target, what does the head brewer scale?", "opts": ["The mash pH, dropping it with acidulated malt", "The weight of the kettle charge, recalculated from the new assay", "The fermentation temperature, warming it a degree", "The length of the boil, stretching it to extract the missing bitterness"], "a": 1, "exp": "Alpha acid content moves with variety, farm and vintage, so bittering hops are bought and dosed by assay rather than by weight alone, and the charge is recalculated for every lot. Boil length does affect utilisation, but it is fixed by the brewhouse schedule and dragging it out moves colour and volume along with the bitterness."},
{"id": "c-dmz3kpg5", "cat": "Beer & Cider", "q": "Saaz, Hallertau Mittelfrueh, Tettnang and Spalt sell at a premium in spite of unimpressive alpha acid figures, prized for fine, spicy aroma. Under which collective name does the trade group them?", "sa": 1, "accept": ["noble hops", "noble hop varieties", "noble varieties", "noble hop"], "ans": "Noble hops", "exp": "Low alpha acid and a high share of delicate aromatic oils are what the term points at: hops grown for aroma rather than for bittering economy, and the signature of pilsner, helles and Czech lager. The American high-alpha varieties deliver bitterness far more cheaply, but they read citrus and resin, which is a different tradition altogether."},
{"id": "c-mwit6haq", "cat": "Beer & Cider", "q": "Weeks after packaging, a heavily dry-hopped IPA measures stronger and drier than its release spec, and cans have begun to swell. Which phenomenon, introduced with the hops themselves, is at work?", "sa": 1, "accept": ["hop creep", "dry hop creep"], "ans": "Hop creep", "exp": "Hop material carries enzymes that keep cutting unfermentable dextrins into sugars the yeast can eat, so fermentation quietly restarts inside the sealed package and alcohol, carbon dioxide and off-flavours all rise. Cold storage, earlier dry-hop timing or pasteurisation are the defences a production plan reaches for, and a buyer who cellars hazy IPA warm learns the hard way why the date code matters."},
{"id": "c-kewgf9k8", "cat": "Beer & Cider", "q": "Printed proudly on a Munich brewery's menu, the word Reinheitsgebot invites a guest to ask what the 1516 decree still controls. What is the accurate answer?", "opts": ["It survives only through later German law binding domestic brewers; imports have been exempt since a 1987 European ruling", "It was written into European Union law, so every beer brewed in a member state must comply with its ingredient list", "It binds every beer sold in Germany today, imported bottles included", "It lapsed entirely, leaving German brewers free of any ingredient rules"], "a": 0, "exp": "The 1516 Bavarian text is a historical document; what operates now is Germany's provisional beer law of 1993, which holds bottom-fermented beer sold as Bier to malted barley, hops, yeast and water while allowing other malts and sugars in top-fermented styles. The European Court of Justice ruled in 1987 that purity rules could not be used to shut out beer lawfully made elsewhere, so the decree lives on as a domestic standard and a marketing story rather than as a general law."},
{"id": "c-5hu30f99", "cat": "Beer & Cider", "q": "Near the end of a lager's primary fermentation the brewer lets the tank rise a few degrees and holds it there, so the yeast reabsorbs its own vicinal diketones before the long chill. What is that holding step called?", "sa": 1, "accept": ["diacetyl rest", "vdk rest"], "ans": "Diacetyl rest", "exp": "Warm, active yeast takes the diacetyl it made during growth back up and reduces it to near-flavourless butanediol, and the reaction runs many times faster at eighteen degrees than at eight. Large plants confirm completion with a laboratory VDK assay before chilling, because the flavourless precursor still in the beer converts to diacetyl later, and no palate can taste what has not yet formed."},
{"id": "c-9ruw5kcq", "cat": "Beer & Cider", "q": "Forbidden by its own purity rules from priming tanks with sugar, a Bavarian brewery carbonates by dosing finished beer with a measured share of vigorously fermenting young wort. Name the technique.", "sa": 1, "accept": ["krausening", "krausened", "kraeusening", "kraeusened"], "ans": "Krausening", "exp": "The young beer at high krausen brings fermentable sugar and a fresh crop of healthy yeast, so the sealed tank carbonates naturally while the new yeast also scrubs residual compounds from the finished beer. The addition is nothing but beer in the making, which is what keeps the method legal where added sugar is not."},
{"id": "c-sgchk906", "cat": "Beer & Cider", "q": "Delivered filtered bright, force-carbonated and sealed under gas, a firkin is refused a place on a festival's real ale bar. Which requirement did it fail?", "opts": ["It must be dispensed through a handpump behind the bar, since gravity pours straight from the cask tap are not recognised", "It must still be conditioning on its own live yeast in the vessel it is served from, without applied gas pressure", "It must stay below five percent alcohol", "It must be brewed from malted barley alone"], "a": 1, "exp": "Real ale is defined by a secondary fermentation continuing in the container it is served from and by dispense without extraneous carbon dioxide, and a gravity pour straight from the tap qualifies exactly as a handpump does. Brewery filtration, force carbonation or gas pushing the beer to the tap each move it into keg territory, whatever the vessel looks like from outside."},
{"id": "c-4blasq1a", "cat": "Beer & Cider", "q": "Two days before a cask goes on sale the cellar manager taps a porous peg into the shive and lets the excess condition hiss away through it. Name the peg.", "sa": 1, "accept": ["soft spile", "soft spiles", "porous spile", "porous spiles", "soft porous spile", "soft porous spiles", "porous soft spile", "porous soft spiles", "soft peg", "soft spile peg"], "ans": "Soft spile", "ex": 1, "exp": "The soft spile's porous bamboo or cane lets carbon dioxide escape while the beer drops bright on the stillage, and it is swapped for a sealing hard spile once condition is right, then again between sessions to hold what remains. That venting routine is the labour that separates cask from keg, and it is why a broached cask has a working life measured in days."},
{"id": "c-6tpjdhsn", "cat": "Beer & Cider", "q": "Bales left to oxidise in an attic for three years, at a price no pale ale brewer would pay for fresh ones, are exactly what a Brussels lambic house orders. What is that hop charge for?", "opts": ["The cheesy, oxidised note that defines the finished beer's aroma", "Colour, drawn from the browned leaf during the long boil", "A bargain source of bittering, since drying concentrates the alpha acids", "Preservation, with bitterness and aroma deliberately faded away"], "a": 3, "exp": "A wort that will spend years fermenting needs the antiseptic side of the hop without its flavour, so lambic brewers hop heavily with bales whose alpha acids and oils have decayed to almost nothing. Fresh aromatic hops would fight the character the wild fermentation is meant to build, and their bitterness would sit badly in a beer this acidic."},
{"id": "c-nva8jemd", "cat": "Beer & Cider", "q": "Flour-cloudy wort, rich in raw starch and unfermentable dextrin, is exactly what a lambic brewhouse wants: rations for years of slow wild fermentation. Which mashing regime produces it?", "sa": 1, "accept": ["turbid mash", "turbid mashing"], "ans": "Turbid mash", "exp": "Milky, starchy liquid is pulled off early in the mash and the grist leans on a large share of unmalted wheat, leaving material a clean single-strain fermentation could never use. The organisms that arrive over the following years in the barrel can, and the regime remains standard practice in every traditional lambic brewhouse."},
{"id": "c-q248rnmb", "cat": "Beer & Cider", "q": "One word, protected across the EU as a traditional guarantee, sits in front of Geuze or Lambik on serious lists and separates the old-method article from its sweetened, filtered namesakes. Which word?", "sa": 1, "accept": ["oude", "oude geuze", "oude gueuze", "vieille", "oude or vieille"], "ans": "Oude", "exp": "Oude, vieille on French-language labels, is the traditional speciality guaranteed designation, and it requires the old method throughout: wholly spontaneous fermentation, real age in wood behind the bottle, and none of the sweetening and pasteurising the industrial versions lean on. On a list it is the single most reliable word for telling the sharp, cellarable article from the soda-sweet bottle at the same shelf height."},
{"id": "c-kkwbokar", "cat": "Beer & Cider", "q": "Sharps, sweets, bittersharps and bittersweets: the traditional Long Ashton scheme files every cider apple into one of four classes. Which two juice measurements draw the boundaries?", "opts": ["Acidity and tannin", "Pectin and nitrogen", "Sugar and total acidity", "Sugar and tannin"], "a": 0, "exp": "The thresholds sit near two grams a litre of tannin and four and a half of malic acid, and the two lines cut the fruit into four quadrants. Sugar hardly separates cider fruit at all, since nearly everything grown for the press ferments fully; what a blender is balancing is bite against structure."},
{"id": "c-0taarjn1", "cat": "Beer & Cider", "q": "Low in malic acid and heavy in tannin, fruit of one class is the backbone of the classic West Country and Norman blends, giving a structure no dessert apple can. Which class is it?", "sa": 1, "accept": ["bittersweet", "bittersweets", "bittersweet apples", "bittersweet apple", "bittersweet class", "bittersweet category", "bittersweet cider apples", "bitter sweet", "bitter sweets"], "ans": "Bittersweet", "ex": 1, "exp": "Bittersharps carry the same tannin with high acid on top, sharps bring acid alone, and sweets bring neither, so the bittersweet quadrant is the only one that gives body and grip without turning the blend austere. Dabinett and Yarlington Mill are the varieties an orchardist would name first."},
{"id": "c-z7ynx6b4", "cat": "Beer & Cider", "q": "Even when every fermentable sugar is gone, a perry keeps a gentle sweetness, because pear juice carries a sugar alcohol that yeast cannot touch. Name it.", "sa": 1, "accept": ["sorbitol"], "ans": "Sorbitol", "exp": "Sorbitol passes through fermentation untouched, so it survives into the driest perry as softness on the finish, along with the mildly laxative reputation older drinkers joke about. Pears also carry more citric acid than apples do, which is why a perry can taste brighter than a cider even while it finishes rounder."},
{"id": "c-guybagtn", "cat": "Beer & Cider", "q": "Weeks pass in a Norman cider house while a brown pectin cap rises on the juice, the clear middle drawn off beneath it so starved of nutrients that the ferment crawls and stops sweet on its own. Name the technique.", "sa": 1, "accept": ["keeving", "keeved", "defecation"], "ans": "Keeving", "exp": "Pectin sets into a gel that floats off with most of the yeast nutrients, and the cidermaker racks the clean juice from under the chapeau brun. A fermentation that cannot finish is the whole point: the sweetness of a traditional cidre doux is kept by starvation rather than by filtration, pasteurisation or anything added."},
{"id": "c-tf74d69m", "cat": "Beer & Cider", "q": "Held at arm's length overhead, the bottle in an Asturian sidreria is crashed in a thin stream against the lip of a wide glass below, one short culin at a time, drunk off at once. Name that pour.", "sa": 1, "accept": ["escanciado", "escanciar", "escanciando", "throwing the cider"], "ans": "Escanciado", "exp": "The long drop knocks carbon dioxide briefly out of solution, so a still, sharp sidra natural reaches the mouth with a fleeting sparkle it never had in the bottle. Pouring only a swallow at a time follows from the same physics, since the lift is gone within moments and the glass is meant to be emptied before it fades."},
{"id": "c-1i3y9b9q", "cat": "Beer & Cider", "q": "Winter cold, not machinery, does the concentrating for most of Quebec's cidre de glace: autumn-pressed juice stands outdoors until the water locks up as ice and a dense syrup is drawn from beneath. Name that method.", "sa": 1, "accept": ["cryoconcentration", "cryo concentration", "freeze concentration"], "ans": "Cryoconcentration", "exp": "Concentrating the juice before fermentation is what lets ice cider reach its weight of sugar and acid in a climate built for the job. The rarer route presses whole apples left hanging frozen on the tree, and Quebec's rules recognise both while insisting the cold be the winter's own rather than a freezer's."},
{"id": "c-6sldhkaq", "cat": "Beer & Cider", "q": "Twelve degrees Celsius shows on the cellar thermometer, and a guest has just sent back a handpulled best bitter as too warm. What should the director's note to the floor team say?", "opts": ["Apologise and take cask beer off the list for the summer months", "Fit an in-line chiller so every pint reaches the glass at four degrees", "The cellar is right: cask bitter is meant for eleven to thirteen degrees", "Move the casks to the four-degree cold room with the lagers overnight"], "a": 2, "exp": "Cellar temperature is the style's specification rather than a refrigeration failure: at eleven to thirteen degrees the low carbonation and the malt read as intended, while colder service mutes the beer and at lager temperature it tastes flat and empty. The guest-facing answer is a word of explanation and an offered alternative, not chilling a living beer into silence."},
{"id": "c-7rxt7gzu", "cat": "Beer & Cider", "q": "Wide at the rim, usually stemmed, often printed with an abbey crest: one glass shape anchors the service standard for Trappist and abbey ales. Name the shape.", "sa": 1, "accept": ["goblet", "chalice", "goblet or chalice", "chalice or goblet"], "ans": "Goblet", "exp": "A wide mouth lets the dense head settle to a thin cap and lifts the yeast and spice aromatics to the nose, and the open bowl gives a nine percent beer room to warm and unfold as it sits. The stem keeps the hand off the bowl, for the same reason it does on a wine glass: these are beers served closer to cellar than to fridge."},
{"id": "c-l21ytlod", "cat": "Bordeaux", "q": "Brokers working for the 1855 exposition wrote down estate names, not plots of ground. What follows for a classified growth that later buys a neighbouring parcel?", "opts": ["The estate drops a tier until the list is next reviewed", "The parcel keeps the rank of whoever farmed it in 1855", "Fruit from the added land is barred from the classified wine for fifty years after the purchase date", "Fruit from the added land may go into the classified wine if that land holds the appellation"], "a": 3, "exp": "This is the standing complaint against 1855: it ranked commercial names rather than delimited vineyard, so holdings could grow, shrink and swap without the rank moving. The rank travels with the name, and the new parcel has to be inside the appellation the classified wine is sold under before its fruit can go in. A Burgundian classification does the opposite, fixing the boundary and letting the owner change."},
{"id": "c-y2kbp0cy", "cat": "Bordeaux", "q": "A guest insists the red side of the 1855 ranking has never been altered. Which correction is accurate?", "opts": ["It is rebuilt every decade in the same way Saint-Emilion's is", "It has been altered twice, and the second time was in 1973", "It has been altered once, when Haut-Brion was written in during 1953", "It has been altered three times, the last of them in the 1990s"], "a": 1, "exp": "Cantemerle was omitted and inserted within a year of publication, and Mouton Rothschild rose from Second to First in 1973. Those are the only two changes of rank; the rest of the movement on the list has been estates dividing, which is how the 58 chateaux of 1855 became the 61 recognised now. Haut-Brion was in the original list from the start, which is what makes that distractor tempting to anyone who half-remembers the Graves connection."},
{"id": "c-rsefawh7", "cat": "Bordeaux", "q": "Left off the exposition list and restored as a Fifth Growth within the year after its owner objected, which Medoc estate was the first correction ever made?", "sa": 1, "accept": ["cantemerle", "cantemerle in macau", "chateau cantemerle in the haut medoc"], "ans": "Cantemerle", "exp": "The wine had been sold direct to the Dutch trade rather than through the Bordeaux market, so the brokers had no local price record for it. That is a neat illustration of what the list was really measuring: presence on one city's exchange."},
{"id": "c-i64e8urs", "cat": "Bordeaux", "q": "Below Chateau d'Yquem, the Sauternes side of 1855 holds two ranks of classified growth. Name them.", "sa": 1, "accept": ["premier cru and deuxieme cru", "premier cru deuxieme cru", "deuxieme cru and premier cru", "premiers crus and deuxiemes crus", "first growth and second growth", "first growths and second growths", "premier crus and deuxieme crus", "premier cru classe and deuxieme cru classe", "deuxieme cru classe and premier cru classe", "premier cru classe deuxieme cru classe", "premiers crus classes and deuxiemes crus classes"], "ans": "Premier Cru and Deuxieme Cru", "ex": 1, "exp": "Yquem sits alone above them as Premier Cru Superieur, a tier invented for it. The reds got five tiers and the sweet wines two, which tells you how much finer the price gradations were thought to be on the Left Bank."},
{"id": "c-t3j8ph76", "cat": "Bordeaux", "q": "Suppose a classified chateau buys vineyard from an unclassified neighbour. Which national body decides whether that ground is entitled to the appellation the classified wine carries?", "sa": 1, "accept": ["inao", "institut national de l'origine et de la qualite", "the national appellation body", "institut national des appellations d'origine"], "ans": "The INAO", "exp": "The rank is a private nineteenth-century verdict, but the appellation on the same label is a state matter, and parcel eligibility is settled by the INAO against the delimited zone. So the classification cannot be enlarged by purchase alone: the land has to already be inside the right appellation."},
{"id": "c-8c1n3xgp", "cat": "Bordeaux", "q": "Moving an estate between tiers of the 1855 reds needed something the trade could not grant on its own. What instrument finally did it in 1973?", "sa": 1, "accept": ["ministerial decree", "a decree from the agriculture minister", "government decree", "ministerial order", "a decree of the minister of agriculture"], "ans": "A ministerial decree", "exp": "Baron Philippe pressed for fifty years and the change came by decree of the agriculture ministry, not by any vote of brokers. That is precisely why nobody expects a second one: there is no standing mechanism, only a political act."},
{"id": "c-msw7h4kt", "cat": "Bordeaux", "q": "Graves drew up its own classification for reds in 1953 and finished the job with whites in 1959. How is the resulting list arranged?", "opts": ["One tier only, with estates listed for red, white or both", "Two lettered categories, A and B", "Three tiers reviewed every ten years", "Five tiers, deliberately mirroring the 1855 reds"], "a": 0, "exp": "There is no hierarchy inside it: an estate is a Cru Classe de Graves or it is not, and the entry records which colour it was classified for. Haut-Brion is classified for its red alone, so its white, one of the most expensive dry whites in France, carries no rank at all."},
{"id": "c-kftw52v6", "cat": "Bordeaux", "q": "Two bottles from the same Right Bank village read Saint-Emilion Grand Cru and Saint-Emilion Grand Cru Classe. What separates them?", "opts": ["The first is an appellation, the second is a rank held by a named estate", "The first is a rank, the second is a wine from purchased fruit", "The first is declassified wine from a classified estate, the second is the grand vin", "They are two spellings of one thing and mean the same"], "a": 0, "exp": "Saint-Emilion Grand Cru is open to anyone in the zone who meets lower yields, higher minimum alcohol and a longer elevage with an approval tasting. Grand Cru Classe is a place on the classification, held by a specific chateau, and the word Classe is the entire difference on the shelf."},
{"id": "c-43mptsw2", "cat": "Bordeaux", "q": "Every estate on the Graves classified list now sits inside a single appellation carved out in 1987. Which appellation contains them all?", "sa": 1, "accept": ["pessac leognan", "pessac leognan aoc", "the pessac leognan appellation"], "ans": "Pessac-Leognan", "exp": "The classified estates all lie in the northern communes nearest the city, which is exactly the ground the 1987 appellation was drawn around. Nothing in the southern half of Graves was ever classified, so the two lists coincide entirely."},
{"id": "c-lea7vmdh", "cat": "Bordeaux", "q": "Rebuilt after its own annulment, the Medoc ranking outside 1855 now runs to three ascending levels. Name them in order.", "sa": 1, "accept": ["cru bourgeois cru bourgeois superieur and cru bourgeois exceptionnel", "cru bourgeois cru bourgeois superieur cru bourgeois exceptionnel", "cru bourgeois cru bourgeois superieur and exceptionnel", "cru bourgeois superieur and exceptionnel", "cru bourgeois superieur exceptionnel", "cru bourgeois then superieur then exceptionnel", "bourgeois superieur and exceptionnel"], "ans": "Cru Bourgeois, Cru Bourgeois Superieur and Cru Bourgeois Exceptionnel", "ex": 1, "exp": "The tiers were abolished in the 2000s after litigation, leaving a flat annual selection of individual wines, and were restored when the system was rebuilt around estate-level assessment. Exceptionnel is the smallest group and carries requirements on vineyard management and cellar practice, not only on the tasting."},
{"id": "c-bpe5v3sh", "cat": "Bordeaux", "q": "Unlike an 1855 growth, a Cru Bourgeois estate holds its standing only for a fixed run of harvests before it must reapply. How long does the award now run?", "sa": 1, "accept": ["five vintages", "5 vintages", "five years", "5 years", "five consecutive vintages", "five", "5", "five harvests", "5 harvests", "five vintages at a time"], "ans": "Five vintages", "ex": 1, "exp": "Reapplication is the whole point of the exercise: the rank is meant to describe present performance rather than a nineteenth-century price list. It also means the label statement is tied to the vintage in the bottle, not to the chateau in perpetuity."},
{"id": "c-v46nukpw", "cat": "Bordeaux", "q": "Ausone and Cheval Blanc held the top rank of the Saint-Emilion classification alone for decades. In the 2012 revision, which two estates were raised to join them?", "sa": 1, "accept": ["angelus and pavie", "pavie and angelus", "angelus pavie", "pavie angelus"], "ans": "Angelus and Pavie", "ex": 1, "exp": "Both promotions were contested in court, which is the recurring feature of this classification rather than an accident: because rank is revisable it is worth suing over, and because it is written into the appellation rules the state ends up in the argument. The 1855 list attracts no litigation for the opposite reason."},
{"id": "c-eew914t0", "cat": "Bordeaux", "q": "Only one of the Medoc's great communal appellations extends well beyond the village that names it. Which group of communes does Margaux also cover?", "opts": ["Listrac, Moulis and Avensan", "Macau, Ludon and Saint-Laurent", "Cantenac, Soussans, Arsac and Labarde", "Cussac, Lamarque and Arcins"], "a": 2, "exp": "Five communes in all share the name, which is much of why Margaux is the least uniform of the four in soil and in style. An address in Cantenac or Labarde is labelled Margaux with nothing on the bottle to say so."},
{"id": "c-5qtspny2", "cat": "Bordeaux", "q": "One of the four famous Medoc communes holds no First Growth at all, yet nearly all of its vineyard is classified. Which commune is that?", "opts": ["Pauillac", "Margaux", "Saint-Estephe", "Saint-Julien"], "a": 3, "exp": "Saint-Julien is small, tightly drawn and dominated by classified estates, so the average bottle carrying the name is a serious wine. Saint-Estephe is larger and has proportionally far more unclassified land, which is why its name alone tells you less."},
{"id": "c-qp6sudd7", "cat": "Bordeaux", "q": "Wines from the northernmost of the four great communes are firmer and slower than their neighbours because a water-retaining layer sits under the gravel. Name that layer.", "sa": 1, "accept": ["clay", "clay subsoil", "dense clay", "clay beneath the gravel", "cold clay"], "ans": "Clay", "exp": "Saint-Estephe's gravel is shallower and the clay under it holds water, so the vine suffers less drought stress and the wines carry more flesh and more grip. Latour's Enclos in Pauillac shows the same effect in miniature, which is one reason it performs in dry years."},
{"id": "c-r35fwzsl", "cat": "Bordeaux", "q": "Great Medoc sites are almost all built on a low mound of gravel standing a few metres proud of the surrounding land. What is the local term for such a mound?", "sa": 1, "accept": ["croupe", "croupes", "gravel croupe"], "ans": "Croupe", "exp": "The height is trivial in absolute terms and decisive in practice: it puts the water table further below the roots and lets cold air drain away downslope. The old Medoc saying that the best vines see the river is really a statement about being on a croupe."},
{"id": "c-wcivw7md", "cat": "Bordeaux", "q": "Running north from the city, the Haut-Medoc appellation stops where the plain Medoc appellation begins. Which commune marks that northern boundary?", "sa": 1, "accept": ["saint seurin de cadourne", "st seurin de cadourne", "the commune of saint seurin de cadourne"], "ans": "Saint-Seurin-de-Cadourne", "exp": "North of it the peninsula flattens, the gravel thins and clay takes over, which is the physical reason the line falls where it does. Everything beyond is entitled only to Medoc, whatever the quality in the glass."},
{"id": "c-vrnx4gvg", "cat": "Bordeaux", "q": "A Pauillac estate bottles a white wine from Sauvignon Blanc grown among its Cabernet. Which appellation must that bottle carry?", "sa": 1, "accept": ["bordeaux blanc", "bordeaux", "bordeaux aoc", "bordeaux blanc aoc", "aoc bordeaux blanc", "aoc bordeaux", "regional bordeaux blanc", "regional bordeaux", "the bordeaux appellation", "the regional white appellation", "plain bordeaux blanc"], "ans": "Bordeaux Blanc", "ex": 1, "exp": "Every communal appellation in the Medoc is for red wine only, so a white from Pauillac drops straight to the regional level however grand the address. Mouton's Aile d'Argent and the white of Margaux are sold exactly this way."},
{"id": "c-4m1y1h0p", "cat": "Bordeaux", "q": "Four existing cotes appellations were folded into a single umbrella denomination in 2009, each keeping its own name as a prefix. Which four?", "opts": ["Castillon, Francs, Bourg and Graves de Vayres", "Bourg, Blaye, Fronsac and Castillon", "Blaye, Cadillac, Castillon and Francs", "Cadillac, Loupiac, Sainte-Croix-du-Mont and Blaye"], "a": 2, "exp": "Sainte-Foy joined the union later and Cotes de Bourg stayed out of it altogether, which is the detail that catches people. A wine may also be sold as plain Cotes de Bordeaux without any prefix if the fruit is blended across the zones."},
{"id": "c-2fhlohzg", "cat": "Bordeaux", "q": "Two communal appellations of the Medoc sit inland behind the main gravel ridge and hold no classified growth between them. Which pair?", "opts": ["Macau and Arcins", "Moulis and Listrac", "Avensan and Soussans", "Cussac and Lamarque"], "a": 1, "exp": "Both are entitled to their own communal names, so they outrank the surrounding Haut-Medoc while sitting outside the 1855 story entirely. Their clay and limestone gives sterner, less immediately charming wine, which is much of why the brokers of 1855 priced them below the riverside communes."},
{"id": "c-sigwpikr", "cat": "Bordeaux", "q": "A modest stream runs east to west across the Right Bank, marking the northern limit of Pomerol and of Saint-Emilion, with the satellite appellations lying beyond it. Name that stream.", "sa": 1, "accept": ["barbanne", "barbanne stream", "riviere barbanne", "the barbanne river"], "ans": "The Barbanne", "exp": "It is small enough to step across and it is nonetheless one of the most consequential lines in Bordeaux, because Lalande-de-Pomerol and the four Saint-Emilion satellites all begin on the far side of it. Old local lore held that the good wine was on the southern bank and the witches on the northern one."},
{"id": "c-mfdj9hak", "cat": "Bordeaux", "q": "Inside Fronsac sits a smaller appellation drawn around two limestone hills above the Dordogne. Name that inner appellation.", "sa": 1, "accept": ["canon fronsac", "canon fronsac aoc", "the canon fronsac appellation"], "ans": "Canon-Fronsac", "exp": "It covers the slopes of the Canon and Saint-Michel hills, where molasse and limestone replace the sandier ground of Fronsac proper. Any grower in Canon-Fronsac may declassify to Fronsac; the reverse is not possible, which is the practical test of which sits above the other."},
{"id": "c-j7ahkr19", "cat": "Bordeaux", "q": "Looking across the estuary at the Medoc, one Right Bank cotes appellation has kept a real planting of a red variety now scarce elsewhere in Bordeaux. Which variety?", "sa": 1, "accept": ["malbec", "cot", "malbec cot", "malbec or cot", "malbec grape"], "ans": "Malbec", "exp": "Cotes de Bourg is the one place in the region where the grape is still treated as a serious blending component rather than a relic. Its early budding and poor fruit set are why the rest of Bordeaux replanted to Merlot after the 1956 frost."},
{"id": "c-a8lwls9r", "cat": "Bordeaux", "q": "North of the Barbanne lies an appellation of its own that absorbed the neighbouring commune of Neac and is often sold as a cheaper route to Merlot on clay. Name it.", "sa": 1, "accept": ["lalande de pomerol", "lalande de pomerol aoc", "the lalande de pomerol appellation", "lalande"], "ans": "Lalande-de-Pomerol", "exp": "Neac had its own appellation until it was merged in, and the eastern part of the zone on gravel over clay is the part that most resembles Pomerol itself. The western half is sandier and gives the lighter wines that set the price expectation for the whole name."},
{"id": "c-oon0affp", "cat": "Bordeaux", "q": "Rounded stones the size of a fist lie metres deep across the best Medoc vineyards. How did they get there?", "opts": ["They weathered in place out of the limestone bedrock under the vineyards", "Rivers carried them down from the Pyrenees and the Massif Central", "They were dredged from the estuary and spread on the fields by growers", "They blew inland as gravel from the Atlantic dunes"], "a": 1, "exp": "The stones came from the Pyrenees and the Massif Central during the Ice Ages: glacial meltwater moved enormous volumes of them north along the Garonne and dumped them in terraces as the flow slackened. The stones are therefore foreign to the Medoc, which is why the ground changes character the moment you step off a terrace."},
{"id": "c-8ccvt3u5", "cat": "Bordeaux", "q": "Two Saint-Emilion estates lie a kilometre apart, one at the edge of the limestone plateau and one on sand at the foot of the slope. What difference in the wines should you predict?", "opts": ["The plateau gives sweeter wine because limestone raises sugar", "The plateau gives the firmer, longer-lived wine", "The sand gives the more tannic and longer-lived wine of the two", "There is no reliable difference, since both are planted to Merlot"], "a": 1, "exp": "Limestone holds a water reserve and keeps acidity, so the plateau wines have structure and a long life. The sandy foot of the cotes warms fast and drains hard, giving perfumed, supple wine that is ready early and does not repay cellaring."},
{"id": "c-9e26b914", "cat": "Bordeaux", "q": "Under the Pomerol plateau runs a pan of iron-cemented sand, usually called crasse de fer. Growers also give it a blacksmith's name. What is that second term?", "sa": 1, "accept": ["machefer", "machefer clinker", "machefer or clinker"], "ans": "Machefer", "exp": "Machefer is the word for forge clinker, which is what the stuff looks like when a trench cuts through it. The pan slows drainage, so the vine still has water in a dry August, and growers have long credited it with the iron, truffled note of the best of the plateau."},
{"id": "c-3x90ih9v", "cat": "Bordeaux", "q": "Saint-Emilion's plateau is quarried for building stone as well as planted with vines, and its limestone carries a name taken from the fossils in it. Name that limestone.", "sa": 1, "accept": ["calcaire a asteries", "asteries limestone", "starfish limestone", "calcaire a asteries limestone"], "ans": "Calcaire a asteries", "exp": "The asteries are fragments of fossil starfish left in an Oligocene marine deposit. The same rock was cut out from beneath the town for the buildings above it, which is why the plateau is riddled with cellars at a constant temperature."},
{"id": "c-ykulxqet", "cat": "Bordeaux", "q": "Before the seventeenth century the Medoc was largely marsh, and foreign engineers were brought in to drain it and expose the gravel. Which country did they come from?", "sa": 1, "accept": ["netherlands", "holland", "dutch", "dutch engineers", "the low countries"], "ans": "The Netherlands", "exp": "Dutch drainage work is the reason the Medoc has a wine industry at all, and their trade is also why so much early Medoc wine went north rather than to Paris. The drainage channels they cut are still called jalles and still do the job."},
{"id": "c-vfrboo06", "cat": "Bordeaux", "q": "Deep gravel gives a vine no water reserve to speak of, and in a fine year that shortage is a virtue rather than a problem. What is the term for the mild, controlled version of it?", "sa": 1, "accept": ["water stress", "mild water stress", "moderate water stress", "hydric stress", "controlled water deficit", "water deficit"], "ans": "Water stress", "exp": "A vine denied water at veraison stops making leaves and puts its effort into ripening the fruit, which concentrates the berry and thickens the skin. Push it further and the vine shuts down altogether, which is why the same gravel that makes a great dry vintage makes a hard one in drought."},
{"id": "c-q7lz1uq0", "cat": "Bordeaux", "q": "Six new varieties were admitted to the Bordeaux and Bordeaux Superieur appellations in 2021 as an adaptation to a warming climate. What limits came with them?", "opts": ["No limit on planting, but no more than twenty percent of the blend", "They may be used for rose and clairet only", "They may be used in second wines only", "Five percent of the planted area, ten percent of the blend"], "a": 3, "exp": "Those figures are ceilings rather than targets, and they are what make the change conservative: the varieties are there to be trialled, not to remake the blend. They are also confined to the two regional appellations, so a communal wine such as Pauillac or Margaux may not use them at all."},
{"id": "c-va285rz4", "cat": "Bordeaux", "q": "Beyond Sauvignon Blanc, Semillon and Muscadelle, a white Bordeaux may carry a minority of three older accessory varieties. Which trio?", "opts": ["Colombard, Ugni Blanc and Merlot Blanc", "Riesling, Aligote and Melon de Bourgogne", "Petit Manseng, Gros Manseng and Courbu", "Chardonnay, Chenin Blanc and Viognier"], "a": 0, "exp": "They are capped at a minority share and are mostly a legacy of the distilling and bulk trade, since Colombard and Ugni Blanc are the Cognac grapes. Merlot Blanc really is a child of Merlot, a natural crossing with Folle Blanche found in the Gironde in 1891, and it is now nearly gone."},
{"id": "c-o2c87ccg", "cat": "Bordeaux", "q": "Carmenere remains a permitted Bordeaux red and is almost never seen there. What drove it out?", "opts": ["DNA work showed it to be Merlot under another name", "The 1855 brokers struck it from the classified estates", "Its wines were barred from export by the negociants", "It ripens very late and sets its crop badly"], "a": 3, "exp": "Coulure and late ripening made it unreliable in a maritime climate, it grafted poorly, and replanting after phylloxera was the moment growers dropped it. It went to Chile before all this, where it was long mistaken for Merlot, and it ripens there in a way it rarely did at home."},
{"id": "c-2womyva4", "cat": "Bordeaux", "q": "A pink-skinned mutation of Sauvignon Blanc is permitted for white Bordeaux and valued for the weight and stone-fruit character it adds. Name it.", "sa": 1, "accept": ["sauvignon gris", "sauvignon gris grape", "gris de sauvignon"], "ans": "Sauvignon Gris", "exp": "It gives lower acidity and a broader palate than Sauvignon Blanc, so it is used the way Semillon is, to fill out the middle. Several Pessac-Leognan whites carry a few percent of it and never mention it on the label."},
{"id": "c-b42arsxv", "cat": "Bordeaux", "q": "Bordeaux growers have an old local name for Malbec, still used in the Medoc and quite different from the one used on the Right Bank. What is the Medoc name?", "sa": 1, "accept": ["cot", "cot in the medoc", "cot or pressac", "pressac or cot", "cot also called pressac", "cot malbec", "cot the medoc name for malbec"], "ans": "Cot", "ex": 1, "exp": "Pressac is the Right Bank name, said to come from the family that spread the vine around Saint-Emilion, and Auxerrois is what the same grape is called in Cahors. One variety with four names is a standard trap on a blind tasting sheet."},
{"id": "c-bzfvskrf", "cat": "Bordeaux", "q": "Around Saint-Emilion, Cabernet Franc goes by a local name that older growers still use in conversation. What is that name?", "sa": 1, "accept": ["bouchet", "gros bouchet", "bouchet or gros bouchet", "gros bouchet or bouchet", "bouchet in saint emilion", "bouchet on the right bank"], "ans": "Bouchet", "ex": 1, "exp": "Cheval Blanc's plantings were traditionally described in those terms, and the same grape is Breton in the Loire. Petit Bouchet is the local name for Cabernet Sauvignon, so the qualifier carries the whole of the difference, and knowing it is what separates following a Right Bank grower's description of a blend from guessing at it."},
{"id": "c-reqmzzti", "cat": "Bordeaux", "q": "Cellar hands walk the rows of barriques every week or two with a jug, filling each one back up to the bung. Which operation is this?", "opts": ["Collage", "Soutirage", "Ouillage", "Assemblage"], "a": 2, "exp": "Wine evaporates through the staves, and the space left behind would let the wine oxidise and acetify. Topping up keeps the barrel brim full, which is why a traditional cellar is measured in labour as much as in oak."},
{"id": "c-m49q4f6w", "cat": "Bordeaux", "q": "At what point in the cycle does a classified chateau normally settle the proportions of its grand vin?", "opts": ["Only after the first year's sales figures are known", "Immediately before bottling, about two years after the harvest", "In the winter or spring after the harvest", "At the press, so the varieties ferment together"], "a": 2, "exp": "Lots are fermented and kept separate by variety and by parcel, then tasted and assembled early, so what the trade tastes in the spring is already the blend. The lots left out go to the second wine or are sold off in bulk."},
{"id": "c-3t7tw3i2", "cat": "Bordeaux", "q": "Drawing clear wine off its sediment from one barrel to another, a cellarman sets a lit candle behind the glass to watch for the first cloud. Name the operation.", "sa": 1, "accept": ["soutirage", "soutirage a la bougie", "racking", "racking by candle", "candle racking"], "ans": "Soutirage", "exp": "Racking every three months or so in the first year both clarifies the wine and gives it a measured dose of air, which softens tannin. The candle is the oldest gauge there is: the moment the stream turns hazy, the cellarman stops."},
{"id": "c-217v8jn3", "cat": "Bordeaux", "q": "Classified-growth reds are still clarified before bottling with a traditional agent whipped up at five or six per barrique. What is that agent?", "sa": 1, "accept": ["egg white", "egg whites", "fresh egg white", "fresh egg whites", "beaten egg white", "beaten egg whites", "whipped egg white", "whipped egg whites", "albumen", "egg albumen", "white of egg", "whites of egg", "blanc d'oeuf", "blancs d'oeufs"], "ans": "Egg white", "ex": 1, "exp": "The albumen binds the harshest tannins and carries them to the bottom, softening the wine without stripping it the way a heavy filtration would. It is one reason a classified Bordeaux is not usually vegan, and estates that skip it now often bottle unfined instead."},
{"id": "c-wgtxuhei", "cat": "Bordeaux", "q": "Bordeaux has a traditional-method sparkling appellation of its own, and the rules set a floor for time on the lees. How long?", "sa": 1, "accept": ["nine months", "9 months", "nine months on the lees", "9 months on the lees", "nine months ageing on lees", "nine", "9", "nine months minimum", "at least nine months"], "ans": "Nine months", "ex": 1, "exp": "Cremant de Bordeaux is made from the region's own varieties, whites and reds alike, and the nine-month floor is the standard Cremant requirement across France. Non-vintage Champagne must spend twelve months on its lees inside a fifteen-month minimum before release, which is a fair measure of how much of that category's character is bought with time."},
{"id": "c-1te7pel5", "cat": "Bordeaux", "q": "Some estates chill picked bunches until part of the load freezes, then press. What does the technique achieve, and why is it argued over?", "opts": ["It precipitates tartrates and raises acidity, which critics say unbalances the wine", "It kills the botrytis before fermentation, which critics say strips the finished wine of its honeyed aroma", "The wateriest berries freeze, so only the richest juice runs, which critics call selection done in the cellar", "It extracts colour and tannin from the skins, which critics say makes the finished wine too dark"], "a": 2, "exp": "Cryoextraction works on the difference in freezing point between dilute and concentrated juice: the water in the least concentrated berries freezes first, so only the richest juice runs once the press closes. It removes the water a rainy harvest put back into the berries. It is legal, and the objection is that it shifts the selection out of the vineyard and into the cellar, rescuing fruit that selective picking would have left behind."},
{"id": "c-p613nlsk", "cat": "Bordeaux", "q": "Grapes left to raisin on the vine also concentrate their sugar. What does noble rot do beyond that?", "opts": ["It raises the total acidity of the juice", "It removes the need for a selective harvest", "It adds tannin drawn out of the skins", "It consumes tartaric acid and leaves glycerol"], "a": 3, "exp": "Passerillage is pure dehydration, so the juice is simply a more concentrated version of what was there. Botrytis is an organism living in the berry: it eats into the tartaric acid, and it leaves behind glycerol, gluconic acid and the honeyed, saffron aromas of its own that raisined fruit never shows."},
{"id": "c-0tdbku2z", "cat": "Bordeaux", "q": "Sauternes and Barsac name two of the five communes entitled to the appellation. Name the three others.", "sa": 1, "accept": ["bommes fargues and preignac", "bommes fargues preignac", "bommes preignac and fargues", "bommes preignac fargues", "fargues bommes and preignac", "fargues bommes preignac", "fargues preignac and bommes", "fargues preignac bommes", "preignac bommes and fargues", "preignac bommes fargues", "preignac fargues and bommes", "preignac fargues bommes"], "ans": "Bommes, Fargues and Preignac", "ex": 1, "exp": "Yquem is in Sauternes, Rieussec and de Fargues in Fargues, and La Tour Blanche and Lafaurie-Peyraguey in Bommes. Only Barsac holds the right to a name of its own, and the other four have to use the collective one."},
{"id": "c-s5ui9nfp", "cat": "Bordeaux", "q": "Let the autumn stay wet and the same fungus becomes a disaster instead of an asset. What is the destructive form called?", "sa": 1, "accept": ["grey rot", "gray rot", "pourriture grise", "botrytis as grey rot"], "ans": "Grey rot", "exp": "Without dry afternoons the berry never dehydrates, so the fungus keeps spreading, splits the skins and lets acetic bacteria and fruit flies in. The finished wine tastes mouldy and oxidised, which is why a single week of the wrong weather can cost a Sauternes estate its whole crop."},
{"id": "c-9evlugj9", "cat": "Bordeaux", "q": "Between Barsac and the city of Bordeaux, enclaved inside Graves on the same side of the river, lies a third sweet-wine appellation whose growers may also sell dry wine as Graves. Name it.", "sa": 1, "accept": ["cerons", "cerons aoc", "the cerons appellation", "cerons in graves"], "ans": "Cerons", "exp": "It sits within the Graves boundary rather than beside it, so a grower there has two appellations available depending on how the wine finishes. The style is lighter and less sweet than Sauternes, which makes it a useful half-step between a dry Graves and a full Sauternes on a list."},
{"id": "c-dirg5syx", "cat": "Bordeaux", "q": "Botrytised must settles poorly and blocks a filter almost at once, because the fungus leaves a sticky polysaccharide behind in the juice. Name that compound.", "sa": 1, "accept": ["beta glucan", "beta glucans", "glucan", "glucans", "b glucan", "beta 1 3 glucan", "beta 1 3 glucans"], "ans": "Beta-glucan", "ex": 1, "exp": "The molecule is long and gelatinous, so it bridges the pores of a pad or membrane the moment pressure is applied. Cellars deal with it by settling the must cold and long, or with a glucanase enzyme, rather than by pushing harder."},
{"id": "c-y0zm3blu", "cat": "Bordeaux", "q": "Serious dry white Bordeaux is usually denied one conversion that every red in the region undergoes. Which, and for what reason?", "opts": ["Malolactic conversion, blocked to preserve acidity", "Alcoholic fermentation, stopped early to leave a little sugar", "Cold stabilisation, skipped so tartrates remain", "Oxidative racking, avoided so no air reaches the wine"], "a": 0, "exp": "Malic acid is the sharper of the two, and in a maritime climate where whites are picked for freshness it is worth keeping. Chilling the barrel and a dose of sulphur are the usual means, and where the wine is left to go through it, richness is being chosen over tension."},
{"id": "c-xislbazq", "cat": "Bordeaux", "q": "Through the first winter a white barrel is opened and its sediment stirred back up into the wine. What is that operation called?", "sa": 1, "accept": ["batonnage", "lees stirring", "stirring the lees", "batonnage or lees stirring"], "ans": "Batonnage", "exp": "Suspended lees give body and a creamy texture and also consume oxygen, so a stirred barrel is better protected than a still one. Overdone it flattens the aromatics, which is why estates chasing precision now stir far less than they did a generation ago."},
{"id": "c-9jo42nlf", "cat": "Bordeaux", "q": "Graves Superieures on a label promises something other than a better dry white. What is actually in the bottle?", "sa": 1, "accept": ["sweet white wine", "sweet white", "sweet white bordeaux", "sweet white graves", "moelleux", "sweet wine", "semi sweet white wine", "semi sweet wine", "semi sweet white", "sweet white wine from graves", "sweet graves", "white wine with residual sugar", "sweet white wine moelleux"], "ans": "Sweet white wine", "ex": 1, "exp": "The word Superieures marks style, not rank: the appellation is reserved for white with residual sugar from the Graves zone. A guest who orders it expecting a grander version of dry Graves gets a semi-sweet wine, which is a good reason to read the word out loud when the bottle is presented."},
{"id": "c-2dsu1lu0", "cat": "Bordeaux", "q": "Grapefruit and boxwood in a young Sauvignon Blanc come from sulphur-bearing compounds that are locked in the grape and released by the yeast. Name that family of compounds.", "sa": 1, "accept": ["thiols", "thiol", "volatile thiols", "varietal thiols"], "ans": "Thiols", "exp": "They exist in the fruit bound to other molecules and have no smell until fermentation cuts them loose, which is why the choice of yeast changes the aroma so much. They also oxidise readily, and their loss is much of what makes an old bottle of cheap Sauvignon taste of nothing in particular."},
{"id": "c-p7u9bs72", "cat": "Bordeaux", "q": "A customer buys a case as futures in the spring after the harvest. What has he paid for, and when does it arrive?", "opts": ["Wine still in barrel, paid for now and delivered in bottle about two years later", "A share of the vintage settled in cash rather than in wine", "Bottled wine already in the chateau's own cellar, held there until he calls for it", "An option to buy later at whatever the market price turns out to be"], "a": 0, "exp": "The money reaches the chateau long before the wine is bottled, which is the whole commercial point of the system. The buyer takes the risk that the wine will be cheaper on release, and the price is normally quoted in bond, so duty and VAT still fall due when the wine is taken out of the warehouse."},
{"id": "c-40gm5an1", "cat": "Bordeaux", "q": "Standing between a chateau and the merchant who buys from it is a second intermediary who never takes ownership of the wine. What does that party do?", "opts": ["Sets the release price and announces it to the market", "Brokers the sale and samples the wine for a small commission", "Bottles and labels the wine on the chateau's behalf", "Buys the wine outright and resells it at a margin"], "a": 1, "exp": "The courtier knows both cellars and books, matches wine to merchant and guarantees the sample matches the lot, and takes about two percent for it. The negociant is the one taking title and risk, and the chateau alone sets the price."},
{"id": "c-vtb121ox", "cat": "Bordeaux", "q": "Merchants on the Place cannot simply order what they want from a sought-after chateau; a house holds a fixed share of the crop, year in and year out. What is that entitlement called?", "sa": 1, "accept": ["allocation", "allocations", "annual allocation"], "ans": "An allocation", "exp": "The share is historic and jealously guarded, and a merchant who declines a poor vintage risks losing it in a good one. That is why weak years still sell: the entitlement, not the wine, is what the buyer is protecting."},
{"id": "c-agkw1ym9", "cat": "Burgundy", "q": "A grower in Meursault owns slivers of three separate premier cru climats and blends them into a single cuvee. What may the label say?", "opts": ["Meursault Premier Cru followed by all three climat names", "Meursault Premier Cru, with no vineyard named", "The name of the largest of the three climats, followed by Premier Cru", "Nothing above village level, since the blend forfeits the tier"], "a": 1, "exp": "Premier cru standing belongs to the land, so blending across climats within one village keeps the tier and forfeits only the site name. That is why an unnamed premier cru is often the cheapest way into a serious village, and why a grower with many small parcels reaches for it."},
{"id": "c-e8mdwxcy", "cat": "Burgundy", "q": "A negociant blends red from two different communes of the southern Cote d'Or. Which appellation can carry the wine without dropping it to regional level?", "opts": ["Cote de Beaune", "Cote de Beaune-Villages", "Coteaux Bourguignons", "Bourgogne Hautes-Cotes de Beaune"], "a": 1, "exp": "Cote de Beaune-Villages is red only and draws on the Cote de Beaune's village appellations with four excepted: Aloxe-Corton, Beaune, Pommard and Volnay are barred from the blend, which leaves the lesser names, and odd lots of those are exactly what the appellation exists to absorb. Plain Cote de Beaune is a separate and much smaller appellation for vineyards on the hill above the town of Beaune itself, and it is not a blending name."},
{"id": "c-ursvrd2x", "cat": "Burgundy", "q": "Regional Bourgogne may be grown almost anywhere in the region, so growers on the famous escarpment pressed for a regional name that only their own slopes could use. Name it.", "sa": 1, "accept": ["bourgogne cote d'or", "bourgogne cote dor", "bourgogne cote d'or aoc", "aoc bourgogne cote d'or", "the bourgogne cote d'or appellation"], "ans": "Bourgogne Cote d'Or", "ex": 1, "exp": "Created in 2017, it sits above plain Bourgogne and below the village names, and the fruit must come from the Cote de Nuits or the Cote de Beaune. The point is commercial as much as geological: a Bourgogne from the escarpment had no way of saying so, while one from the flat land beyond the motorway carried the same three words."},
{"id": "c-pxs19dyd", "cat": "Burgundy", "q": "Every grand cru site in Burgundy holds an appellation of its own, with Chablis Grand Cru counting once. Give the total.", "sa": 1, "accept": ["thirty three", "33", "thirty three grand crus", "33 grand crus", "thirty three appellations", "33 appellations", "thirty three grand cru appellations"], "ans": "Thirty-three", "ex": 1, "exp": "Thirty-two of them lie on the Cote d'Or and the thirty-third is Chablis Grand Cru, which is a single appellation covering seven climats rather than seven appellations. Counting the Chablis climats separately is the usual way to arrive at the wrong number."},
{"id": "c-m4wp45xr", "cat": "Burgundy", "q": "Bourgogne Grand Ordinaire was retired in 2011, and its replacement now sits at the foot of the hierarchy taking Gamay and Pinot Noir alike from across the region. Name that appellation.", "sa": 1, "accept": ["coteaux bourguignons", "coteaux bourguignon", "the coteaux bourguignons appellation"], "ans": "Coteaux Bourguignons", "exp": "It reaches from Chablis to the bottom of Beaujolais and admits Gamay, Pinot Noir, Chardonnay, Aligote and Melon, which no other Burgundian name does. The rename was a marketing decision: Grand Ordinaire told a shopper the wine was ordinary in a language they could read."},
{"id": "c-5t5lcoh0", "cat": "Burgundy", "q": "On a village-level Chassagne-Montrachet the parcel name must be printed no more than half the height of the appellation name. Which kind of name is being held down that way?", "opts": ["A lieu-dit", "A monopole", "A clos", "A climat"], "a": 0, "exp": "A lieu-dit is simply a name in the land registry, and every scrap of ground has one whether or not it is distinguished. The half-height rule exists so that a village wine naming its parcel cannot be mistaken at a glance for a premier cru, where the vineyard name is printed the same size as the appellation."},
{"id": "c-323kebz3", "cat": "Burgundy", "q": "Monks walled parcels of the Cote d'Or to mark and protect them, and the practice left a word behind on the labels. What does Clos record?", "opts": ["A vineyard ranked between premier cru and grand cru", "A vineyard that is or was enclosed by a wall", "A vineyard held entire by one owner", "A vineyard whose wine is aged wholly in new oak"], "a": 1, "exp": "The wall is the whole of the meaning, and plenty of clos have lost theirs and kept the name. A vineyard in one pair of hands is a monopole, which is a separate idea altogether: Clos de Vougeot is walled and shared among dozens of owners at once."},
{"id": "c-xikd7pl8", "cat": "Burgundy", "q": "Burgundian growers still size a plot in an old unit reckoned as the ground one man could work in a day. Name that unit.", "sa": 1, "accept": ["ouvree", "ouvrees", "an ouvree of vines"], "ans": "Ouvree", "exp": "An ouvree runs to a little over four ares, so eight of them make a journal, the day's work of a man with a horse, and it takes something like twenty-four to make a hectare. The unit survives because Burgundian holdings are small enough that hectares are a clumsy way to describe them, and a sale is still gossiped about in ouvrees."},
{"id": "c-20og80q0", "cat": "Burgundy", "q": "Dry transverse valleys cut back into the Cote d'Or escarpment, swinging aspect around and funnelling cold air down onto the slope. What are they called locally?", "sa": 1, "accept": ["combe", "combes"], "ans": "Combe", "exp": "A combe interrupts the even east-facing wall of the Cote and exposes north and south flanks within a few hundred metres of each other, which is why the vineyard quality can change so abruptly beside one. The cold air draining out of them also explains why the ground directly at a combe mouth is usually village land rather than premier cru."},
{"id": "c-2kj9rnde", "cat": "Burgundy", "q": "Most of one Cote de Nuits grand cru lies in Chambolle-Musigny, with a slice of it falling inside Morey-Saint-Denis. Which grand cru?", "opts": ["Musigny", "Clos de la Roche", "Bonnes-Mares", "Clos Saint-Denis"], "a": 2, "exp": "The commune boundary runs straight through it, so one name covers two soils: pale marl the growers call terres blanches on the Morey side, and redder, iron-stained ground on the Chambolle side. The Morey portion gives the firmer wine, which is much of why Bonnes-Mares tastes stouter than Musigny a few hundred metres away."},
{"id": "c-d10sq7dm", "cat": "Burgundy", "q": "One Gevrey grand cru may be sold under its neighbour's name, though the traffic runs only one way. Which vineyard holds that right?", "opts": ["Chambertin-Clos de Beze", "Charmes-Chambertin", "Latricieres-Chambertin", "Ruchottes-Chambertin"], "a": 0, "exp": "Clos de Beze may be labelled simply Chambertin; Chambertin may not be labelled Clos de Beze. The abbey of Beze was given the land in the seventh century, and the story runs that a man called Bertin planted the field alongside it, which is the order the naming rule still respects."},
{"id": "c-bbj6hk1n", "cat": "Burgundy", "q": "Fixin and Brochon at the northern end, Corgoloin and Prissey at the southern: these communes share one village-level appellation. Name it.", "sa": 1, "accept": ["cote de nuits villages", "cote de nuits village", "cotes de nuits villages", "cote de nuits villages aoc", "the cote de nuits villages appellation"], "ans": "Cote de Nuits-Villages", "ex": 1, "exp": "The name gathers up the ends of the Cote where the escarpment is lower and the ground stonier, and it sits at village level rather than regional level. Fixin also holds a village appellation of its own, so a grower there chooses which of the two to use."},
{"id": "c-zqliqe1u", "cat": "Burgundy", "q": "At the southern end of the Cote de Nuits, one commune is better known for the hard pale limestone cut from its quarries than for its wine. Name the commune.", "sa": 1, "accept": ["comblanchien", "the commune of comblanchien", "comblanchien in the cote de nuits"], "ans": "Comblanchien", "exp": "The stone is polished and sold as a marble substitute, and it has faced buildings across France. The same hard bed is why the vineyard there is thin and stony and sells under Cote de Nuits-Villages rather than under its own name."},
{"id": "c-z8pyzcbs", "cat": "Burgundy", "q": "Gevrey-Chambertin's most sought-after premier cru sits above the village on ground that turns to face east, and its promotion is argued for every few years. Name it.", "sa": 1, "accept": ["clos saint jacques", "clos st jacques", "clos saint jacques in gevrey chambertin"], "ans": "Clos Saint-Jacques", "exp": "It lies north of the grand cru band rather than within it, which is an accident of where the boundary was drawn in the 1930s rather than a verdict on the slope. The wine routinely outprices several of the grand crus it was passed over for, and that is the argument its supporters make."},
{"id": "c-d6r40j8q", "cat": "Burgundy", "q": "Inside the Vougeot commune a walled premier cru has been planted to white grapes since the Cistercians held it. Name that vineyard.", "sa": 1, "accept": ["clos blanc de vougeot", "clos blanc", "vougeot clos blanc", "clos blanc de vougeot premier cru", "the clos blanc de vougeot vineyard"], "ans": "Clos Blanc de Vougeot", "ex": 1, "exp": "It sits just outside the wall of the grand cru and has grown Chardonnay for something close to nine hundred years, which makes it the oldest white plot of the Cote de Nuits. White at grand cru level here is confined to Musigny, so a white Vougeot can rise no higher than premier cru."},
{"id": "c-8x6hdtzr", "cat": "Burgundy", "q": "A hamlet on the boundary of Meursault and Puligny-Montrachet has an appellation covering red wine only, its whites going out under the neighbouring village names. Which appellation?", "opts": ["Auxey-Duresses", "Blagny", "Saint-Romain", "Monthelie"], "a": 1, "exp": "Blagny is red and nothing else. Chardonnay from the identical slope is labelled Meursault or Puligny-Montrachet depending on which commune the row falls in, so a single grower can bottle three appellations off adjoining vines and never move the tractor far."},
{"id": "c-gc9eub7x", "cat": "Burgundy", "q": "Grand cru ground on the Corton hill is shared by more than one commune. Which set of communes holds it?", "opts": ["Beaune, Pommard and Volnay", "Aloxe-Corton and Beaune", "Aloxe-Corton, Savigny-les-Beaune and Chorey-les-Beaune", "Aloxe-Corton, Pernand-Vergelesses and Ladoix-Serrigny"], "a": 3, "exp": "Corton and Corton-Charlemagne wrap around the shoulder of the hill and cross both boundaries, which is why a Ladoix or Pernand grower can own grand cru without their village ever appearing on the bottle. It is also why those two village names are among the best value on the Cote de Beaune: the reputation went to the hill, not to them."},
{"id": "c-pfj8ypbl", "cat": "Burgundy", "q": "Of the five grand crus on the Montrachet hill, Montrachet itself and Batard-Montrachet cross the Puligny-Chassagne boundary. Which one lies wholly inside Chassagne-Montrachet?", "sa": 1, "accept": ["criots batard montrachet", "criots", "criots batard", "criots batard montrachet grand cru", "criots batard montrachet aoc", "the criots batard montrachet vineyard"], "ans": "Criots-Batard-Montrachet", "ex": 1, "exp": "Criots sits at the southern foot of Batard, entirely in Chassagne. Chevalier-Montrachet and Bienvenues-Batard-Montrachet are the mirror case, both wholly inside Puligny, which is why Puligny is usually credited with the finer end of the hill."},
{"id": "c-jl5sig03", "cat": "Burgundy", "q": "Tucked in a valley behind the Montrachet hill, one village sells most of its vineyard at premier cru level and is the standard recommendation for white Burgundy that does not cost a fortune. Name it.", "sa": 1, "accept": ["saint aubin", "st aubin", "saint aubin aoc"], "ans": "Saint-Aubin", "exp": "En Remilly and Les Murgers des Dents de Chien run right up to the Chevalier-Montrachet boundary, and the wines from them are recognisably of the same slope. The village sits in a side valley off the main Cote, which is the whole reason it was never priced with its neighbours."},
{"id": "c-c6gobyql", "cat": "Burgundy", "q": "Past Santenay the Cote de Beaune runs out in one last appellation, created in 1989 from villages that had hyphenated a shared vineyard name onto their own. Name it.", "sa": 1, "accept": ["maranges", "maranges aoc", "the maranges appellation", "maranges in the cote de beaune"], "ans": "Maranges", "ex": 1, "exp": "Cheilly, Dezize and Sampigny had all appended les-Maranges to their names, and the appellation simply took the vineyard name and dropped the villages. The ground faces south rather than east here as the Cote swings round, and it is the last of the Cote d'Or before the Chalonnaise begins."},
{"id": "c-m4k47iq7", "cat": "Burgundy", "q": "Red wine from a premier cru lying inside the commune of Meursault goes to market under the Volnay name instead. Name that climat.", "sa": 1, "accept": ["santenots", "les santenots", "volnay santenots"], "ans": "Santenots", "exp": "Meursault sells white and Volnay sells red, so the rules let the Pinot Noir grown at Santenots take the name that will move it. White from the same rows stays Meursault. It is the plainest case in Burgundy of an appellation following reputation rather than the map."},
{"id": "c-ztkwme5d", "cat": "Burgundy", "q": "A guest asks why they cannot compare one producer's Clos de Tart against another's, the way they might with Clos de Vougeot. What is the answer?", "opts": ["Clos de Tart is a brand rather than a delimited vineyard", "Clos de Tart may only be sold as Morey-Saint-Denis", "Clos de Tart is a monopole, held entire by a single owner", "Clos de Tart is a premier cru, so no producer may print its name"], "a": 2, "exp": "Cistercian nuns planted it in the twelfth century and it has never been divided, so there is exactly one wine to taste in any vintage. Clos de Vougeot is the opposite case: one wall around ground that slopes from the road to the top of the hill, split among dozens of owners who each make something different from it."},
{"id": "c-u3xkhtov", "cat": "Burgundy", "q": "Bressandes, Clos du Roi and Renardes appear on labels appended to a single grand cru name. Which grand cru takes them?", "opts": ["Musigny", "Chambertin", "Montrachet", "Corton"], "a": 3, "exp": "Corton covers a long sweep of hillside, so the decree lets a grower add the climat to the grand cru name and say where on the hill the fruit grew. Gevrey works the other way round: each of its climats is an appellation in its own right, so Charmes-Chambertin is a name rather than a qualification of Chambertin."},
{"id": "c-mkq2e7uv", "cat": "Burgundy", "q": "A white grand cru appellation on the Corton hill is almost never seen on a bottle, because everyone entitled to it prefers a better-known name. Name the unused appellation.", "sa": 1, "accept": ["charlemagne", "the charlemagne appellation", "charlemagne grand cru", "charlemagne aoc"], "ans": "Charlemagne", "ex": 1, "exp": "It remains on the books, and every grower who could use it labels the wine Corton-Charlemagne instead, which the market recognises and pays for. The two appellations cover overlapping ground, so the choice costs nothing and the shorter name has simply died of neglect."},
{"id": "c-67x0bbng", "cat": "Burgundy", "q": "A Morey-Saint-Denis climat was reassembled from scattered parcels over decades and raised from premier cru to grand cru in 1981. Name it.", "sa": 1, "accept": ["clos des lambrays", "lambrays", "the clos des lambrays vineyard"], "ans": "Clos des Lambrays", "exp": "The vineyard had been split among many hands after the Revolution and was patiently bought back into one piece, which is what made the case for promotion arguable at all. A tiny fragment stayed outside the reassembly, so the grand cru is very nearly but not quite a monopole."},
{"id": "c-wi2gx68b", "cat": "Burgundy", "q": "Directly above the most famous monopole in Vosne lies a grand cru of well under a hectare, the smallest appellation in France. Name it.", "sa": 1, "accept": ["la romanee", "la romanee grand cru", "la romanee aoc", "the la romanee vineyard"], "ans": "La Romanee", "ex": 1, "exp": "It is a strip of slope no wider than a tennis court is long, and the whole appellation makes a few hundred cases in a generous year. Answering Romanee-Conti here is the standard error: that is the vineyard immediately below, and it is more than twice the size."},
{"id": "c-1lbl0q9q", "cat": "Burgundy", "q": "Chablis growers spent the 1970s in a public fight over where the appellation's edge should fall. What were the rival criteria?", "opts": ["Whether oak ageing should be compulsory at premier cru and above", "Whether soil alone should qualify, or slope and exposure too", "Whether machine harvesting should be permitted below the premier cru rank", "Whether the river should form the eastern limit of all planting"], "a": 1, "exp": "One camp held that the grey Kimmeridgian marl was the appellation and nothing else could be Chablis; the other argued that a well-sited slope on the younger Portlandian limestone above it ripens perfectly well. The expansionists largely won, which is why the planted area is a multiple of what it was and why the argument still surfaces whenever a poor vintage is discussed."},
{"id": "c-qc1jctt5", "cat": "Burgundy", "q": "Every one of the seven Chablis grand cru climats shares a single slope with the premier cru Montee de Tonnerre. Which bank of the Serein is it on, and which way does it face?", "opts": ["The left bank, facing due south", "The left bank, facing northeast", "The right bank, facing southwest", "The right bank, facing due north"], "a": 2, "exp": "The Serein runs northwest through the town, and the right bank carries the one continuous southwest-facing wall of hillside that holds all seven grand cru climats, with Montee de Tonnerre and Fourchaume continuing it. Left bank climats such as Vaillons and Montmains face the other way and give lighter, quicker wines."},
{"id": "c-1jge3bn7", "cat": "Burgundy", "q": "Twenty kilometres from Chablis, a village appellation makes red from Pinot Noir with a permitted minority of a rare local grape. Which grape may it add?", "opts": ["Cesar", "Tressot", "Gamay", "Sacy"], "a": 0, "exp": "Irancy is the Yonne's red appellation, and Cesar is a dark, tannic relation of Pinot Noir grown essentially nowhere else. A little of it stiffens a Pinot picked at the northern limit of ripeness, and too much of it makes the wine hard, which is why the ceiling is low."},
{"id": "c-fz1q9kpj", "cat": "Burgundy", "q": "One Burgundian village appellation is planted to Sauvignon Blanc rather than Chardonnay, which is much of why it waited until 2003 for recognition. Name it.", "sa": 1, "accept": ["saint bris", "st bris", "saint bris aoc", "sauvignon de saint bris"], "ans": "Saint-Bris", "exp": "It sat as a VDQS for decades because the authorities were reluctant to grant an appellation to a grape with no Burgundian standing. The vineyard is on the same Kimmeridgian ground as Chablis, close enough that a grower may own rows of both."},
{"id": "c-n2gcw9uy", "cat": "Burgundy", "q": "A named parcel straddling Vaudesir and Les Preuses is treated as grand cru without being one of the seven climats. Name that parcel.", "sa": 1, "accept": ["la moutonne", "la moutonne monopole", "la moutonne in chablis"], "ans": "La Moutonne", "exp": "It is a monopole whose name is older than the 1938 decree but does not appear in it, since that decree lists only the seven climats; grand cru standing was granted to the parcel separately at the turn of the 1950s, so the label carries Chablis Grand Cru and the parcel name rather than either of the two climats it lies across. Anyone reciting the seven climats and expecting to have named every grand cru bottling has missed it."},
{"id": "c-5vqe7u7z", "cat": "Burgundy", "q": "Chablis keeps a traditional cask of its own, smaller than the standard Burgundian barrel and still used there as a unit of account. Name it.", "sa": 1, "accept": ["feuillette", "feuillettes", "the chablis feuillette"], "ans": "Feuillette", "exp": "The Chablis feuillette holds a hundred and thirty-two litres against the two hundred and twenty-eight of a Burgundian piece, and confusingly the Cote d'Or has a feuillette of its own at a hundred and fourteen. Crops and contracts in the Yonne are still quoted in them long after the wine went into tank."},
{"id": "c-7p8z7out", "cat": "Burgundy", "q": "Behind the Cote d'Or escarpment, on a plateau appreciably higher and further from the plain, sit two regional appellations. How do their wines read against those of the slope below?", "opts": ["Higher alcohol and markedly lower acidity", "Sweetness from botrytis in most vintages", "Deeper colour and firmer tannin", "Later ripening and higher acidity"], "a": 3, "exp": "The Hautes-Cotes de Nuits and Hautes-Cotes de Beaune sit a couple of hundred metres higher, so budbreak and harvest both run late and the fruit arrives leaner, which shows in the glass as higher acidity and a lighter body. Warm vintages have done more for them than for anywhere else in Burgundy, which is why they now appear on lists that ignored them for a generation."},
{"id": "c-ok1p7ozd", "cat": "Burgundy", "q": "Besides Pouilly-Fuisse, the Maconnais carries the Pouilly name on two much smaller appellations. Which pair?", "opts": ["Pouilly-Solutre and Pouilly-Vergisson", "Pouilly-Fume and Pouilly-sur-Loire", "Pouilly-Chaintre and Pouilly-Davaye", "Pouilly-Loche and Pouilly-Vinzelles"], "a": 3, "exp": "Both are Chardonnay like Pouilly-Fuisse, and a Loche grower may sell the wine as Vinzelles if they prefer. Pouilly-Fume and Pouilly-sur-Loire are three hundred kilometres away on the Loire and made from Sauvignon Blanc and Chasselas, which is the confusion the name invites on every list that carries both."},
{"id": "c-nbda9h7i", "cat": "Burgundy", "q": "The southern Maconnais has a Chardonnay appellation split into blocks lying either side of Pouilly-Fuisse. Name it.", "sa": 1, "accept": ["saint veran", "st veran", "saint veran aoc"], "ans": "Saint-Veran", "exp": "The northern block sits around Davaye and Prisse and the southern around Leynes and Chasselas, with Pouilly-Fuisse wedged between them. Growers in the northern block work the same limestone slopes as Pouilly-Fuisse itself, which is why the appellation is the standard place to look for that style at a lower price."},
{"id": "c-ibjzv6s9", "cat": "Burgundy", "q": "Two Macon-Villages communes were detached in 1999 and given a hyphenated appellation of their own. Name it.", "sa": 1, "accept": ["vire clesse", "vire clesse aoc", "the vire clesse appellation"], "ans": "Vire-Clesse", "exp": "Vire and Clesse had long been the two best-regarded communes entitled to add their names to Macon, and the promotion took them out of that system entirely. The zone also had a tradition of leaving a little residual sugar, which the appellation rules then had to accommodate."},
{"id": "c-ofjxszjs", "cat": "Burgundy", "q": "Wine from the Chalonnaise that does not qualify for one of the five village appellations falls back on a regional name of its own. Give that name.", "sa": 1, "accept": ["bourgogne cote chalonnaise", "cote chalonnaise", "bourgogne cote chalonnaise aoc"], "ans": "Bourgogne Cote Chalonnaise", "exp": "Bouzeron, Rully, Mercurey, Givry and Montagny are the five village names, and everything else on those hills sells under the regional one. It ranks with Bourgogne Cote d'Or and the Hautes-Cotes as a regional appellation restricted to a stated stretch of ground rather than to the whole region."},
{"id": "c-g3y5vco5", "cat": "Burgundy", "q": "A Maconnais red may not use the label form its white neighbours use freely. Which appellation is closed to red wine?", "sa": 1, "accept": ["macon villages", "macon villages aoc", "the macon villages appellation"], "ans": "Macon-Villages", "exp": "Macon-Villages is Chardonnay and nothing else. A red from the same ground goes out as plain Macon, or as Macon followed by its commune where that is permitted, so the word Villages on a Maconnais label is a reliable signal that the wine in the bottle is white."},
{"id": "c-9y6cnsx2", "cat": "Burgundy", "q": "A Beaujolais vat is filled with unbroken bunches and closed, yet no carbon dioxide is added to it. Where does the gas that blankets the fruit come from?", "opts": ["Juice at the base of the vat ferments and gives it off", "Dry ice is added at filling and is not counted as an addition", "The berries respire the oxygen out of the vat before any fermentation begins", "Malolactic bacteria release it before the yeast start work"], "a": 0, "exp": "The juice is there because the weight of the fruit above crushes the bottom bunches, and once it ferments the gas rises through the vat and blankets the whole berries. That is the difference between semi-carbonic and true carbonic maceration: the first makes its own blanket, the second has the gas piped in. In the semi-carbonic vat two fermentations run at once, a conventional yeast ferment in the free-run juice below and an intracellular one inside the whole berries above."},
{"id": "c-al04z7qt", "cat": "Burgundy", "q": "Two Beaujolais crus share a name; one covers the flanks of a single hill of hard blue-green volcanic rock, the other the gentler ground around it. Which is the hillside one?", "opts": ["Chiroubles", "Regnie", "Cote de Brouilly", "Brouilly"], "a": 2, "exp": "Mont Brouilly is a lump of hard blue-tinged rock standing clear of the granite, and wine off its flanks is firmer and more mineral than the wine around its base. Brouilly is the larger appellation on the lower ground, and the two are among the easiest names on a list to transpose."},
{"id": "c-941y2sx9", "cat": "Burgundy", "q": "Morgon's most serious bottlings come off a dome of crumbling schist at the centre of the cru. Name that site.", "sa": 1, "accept": ["cote du py", "cote du py in morgon", "the cote du py slope"], "ans": "Cote du Py", "exp": "The rock there weathers to an orange-brown crumb the growers call roche pourrie, rotten rock, and it gives a denser wine than the sandier ground below. Bottles off it are the usual evidence for the claim that Beaujolais can age, since they take on a dark kirsch and earth character over a decade."},
{"id": "c-2qk7v1gk", "cat": "Burgundy", "q": "One Beaujolais cru is named for the oak wood felled to plant its vines. Name the cru.", "sa": 1, "accept": ["chenas", "chenas cru", "the chenas appellation"], "ans": "Chenas", "exp": "The name comes from chene, oak, and the forest went to make room for the vineyard. Its ground runs into Moulin-a-Vent on one side, which is where a good deal of its fruit historically ended up, and its own name has always been the quieter of the two."},
{"id": "c-rb206bmz", "cat": "Burgundy", "q": "Beaujolais held nine crus until 1988, when a tenth was raised from Beaujolais-Villages. Name the newest of them.", "sa": 1, "accept": ["regnie", "regnie cru", "the regnie appellation"], "ans": "Regnie", "exp": "It sits on pink granite sand between Morgon and Brouilly and gives the lightest and most floral of the crus, which is part of why the promotion was argued about. No eleventh has followed, so the list has been fixed for a generation now."},
{"id": "c-lw1fqemp", "cat": "Burgundy", "q": "A red co-fermented from Pinot Noir and Gamay is sold as Bourgogne Passe-Tout-Grains. What minimum share must the Pinot Noir supply?", "opts": ["Thirty percent", "Fifteen percent", "Fifty percent", "Eighty-five percent"], "a": 0, "exp": "At least thirty percent Pinot Noir and at least fifteen percent Gamay, and the two must go into the vat together rather than be blended afterwards. Eighty-five is the most Pinot the rule leaves room for rather than the least it demands. The name records the old peasant practice of throwing every grape on the holding into one fermenter, which is exactly what the co-fermentation rule preserves."},
{"id": "c-3seiuffu", "cat": "Burgundy", "q": "Bouzeron insists on one of Aligote's two forms, the golden-berried and lower-yielding one. Name it.", "sa": 1, "accept": ["aligote dore", "dore aligote", "the golden aligote dore"], "ans": "Aligote Dore", "exp": "The other form, Aligote Vert, crops far more heavily and gives the thin, sharp wine that gave the grape its reputation as something to drown in cassis. Bouzeron's rules were written around the golden strain precisely to make the case that Aligote can be a serious wine."},
{"id": "c-up3hybzh", "cat": "Burgundy", "q": "Pinot Gris survives in old Burgundian plantings under a local name and may still be blended into a white Burgundy. Give that name.", "sa": 1, "accept": ["pinot beurot", "beurot", "beurot in burgundy"], "ans": "Pinot Beurot", "exp": "It is the same grape as Alsace's Pinot Gris and Italy's Pinot Grigio, a colour mutation of Pinot Noir, and it is permitted in small amounts in several white appellations. The old vineyards were interplanted rather than blocked out by variety, which is how scattered vines of it came to be there at all."},
{"id": "c-akwj3jy4", "cat": "Burgundy", "q": "Two bottles from one village read mis en bouteille au domaine and mis en bouteille par. What does the difference tell a buyer?", "opts": ["The first was bottled in France, the second shipped in bulk and bottled abroad", "The first is a premier cru and the second a village wine", "The first was bottled by the grower of the fruit; the second need not be", "The first was bottled by hand and the second on a mobile line"], "a": 2, "exp": "Au domaine means estate-bottled at the property that farmed the vines, and it is the only one of the two phrases that says anything about who grew the grapes. Mis en bouteille par followed by a name tells you only who filled the bottle, and mis en bouteille dans nos caves says the same thing rather more coyly."},
{"id": "c-kcsngbmi", "cat": "Burgundy", "q": "An owner who no longer farms lets a grower work the vines and takes payment as a share of the crop rather than in cash. Name that arrangement.", "sa": 1, "accept": ["metayage", "en metayage", "metayage sharecropping", "sharecropping", "share cropping", "a moitie"], "ans": "Metayage", "exp": "The share was traditionally half, which is why the arrangement is also described as farming a moitie, and the tenant hands back wine rather than money. Inheritance split Burgundy into parcels too small for their owners to live off, and this is how a great deal of that land is actually worked."},
{"id": "c-cxpoq1zd", "cat": "Burgundy", "q": "A Beaune house buys young wine in barrel, raises it in its own cellars and bottles it under its own label. Give the compound term for such a house.", "sa": 1, "accept": ["negociant eleveur", "a negociant eleveur house", "negociant eleveur in burgundy"], "ans": "Negociant-eleveur", "exp": "Elevage is the raising of the wine between fermentation and bottling, so the second half of the term claims the part of the work that shapes the finished bottle. A house that only buys and resells finished wine has no claim on it, and the distinction is why two negociant bottlings of the same climat can taste unalike."},
{"id": "c-r13s4djx", "cat": "Business of the Sommelier", "q": "Tonight's till holds two bottle sales: one cost the venue 20 and sold for 80, the other cost 100 and sold for 220. The second ran much the worse cost percentage. Why can the ledger still prefer it?", "opts": ["The percentage will right itself when the next vintage arrives at a lower landed cost", "Expensive bottles are customarily excluded from the beverage cost calculation", "It banked 120 against the other bottle's 60, and profit is deposited as cash rather than as a percentage", "Its higher selling price lifts the night's average check, and average check is the number head office watches"], "a": 2, "exp": "A percentage cannot be banked. The cheap bottle ran a flawless 25 percent cost and left 60 behind; the dear one ran about 45 and left 120. Beverage programmes are judged by the first number and live on the second, and confusing the two is how a list ends up refusing money."},
{"id": "c-9s8dbhcu", "cat": "Business of the Sommelier", "q": "Landed at 18 a bottle, a wine sells from the list at 90. Give the cost percentage.", "sa": 1, "accept": ["20 percent", "20", "20%", "20 per cent", "twenty percent", "twenty per cent", "twenty", "one fifth", "a fifth", "0.2"], "ans": "20 percent", "ex": 1, "exp": "Cost divided by selling price: 18 over 90 is 20 percent. The steep multiple is typical of the cheap end of a list, and even so the sale leaves only 72 in cash, which is the other half of the story."},
{"id": "c-j1zp2eyy", "cat": "Business of the Sommelier", "q": "Out of a 150 sale, the venue keeps the 110 left once the bottle's 40 cost is taken out. On the profit and loss, what is that 110 called?", "sa": 1, "accept": ["gross profit", "gross margin", "cash margin", "margin", "contribution", "contribution margin", "gross profit in cash", "gross cash margin", "gross profit line", "gp"], "ans": "Gross profit", "ex": 1, "exp": "Price minus cost is gross profit, and the qualifier carries the meaning: gross is what the beverage operation earns before wages and rent take their share, and the bare word on its own names no line at all. The cost percentage is the same arithmetic read the other way round, and only one of the two can be spent."},
{"id": "c-mo4zz800", "cat": "Business of the Sommelier", "q": "Priced throughout at a 30 percent beverage cost, a list takes on a bottle landed at 24. What does it sell for?", "sa": 1, "accept": ["80", "$80", "80 dollars", "eighty", "eighty dollars", "80 a bottle", "eighty a bottle"], "ans": "80", "ex": 1, "exp": "Divide the cost by the target: 24 over 0.3 is 80. Pricing to a percentage is quick and consistent, which is why a buyer translates a case quote into list prices in their head before agreeing to anything."},
{"id": "c-rnb661bv", "cat": "Business of the Sommelier", "q": "Quarter on quarter the beverage cost percentage creeps upward, yet cash profit climbs with it, and no price, pour or supplier changed. What shifted?", "sa": 1, "accept": ["sales mix", "mix", "product mix", "sales mix shifted", "mix shifted", "sales mix moved", "mix moved", "shift in sales mix", "sales mix changed", "sales mix has changed", "mix changed", "mix has changed", "change in sales mix", "change in mix", "diners are trading up", "customers are trading up", "people are trading up", "customers bought more expensive wine", "sales mix shifted toward dearer bottles", "mix shifted toward dearer bottles", "sales mix shifted toward more expensive bottles", "mix shifted toward more expensive bottles", "guests traded up", "customers traded up", "people traded up", "diners traded up", "guests trading up", "customers trading up", "guests are trading up", "trading up", "traded up", "guests bought more expensive bottles", "guests buying dearer bottles", "diners bought more expensive bottles", "people bought more expensive wine", "bought more expensive bottles", "buying more expensive bottles", "buying more expensive wine", "selling more expensive bottles", "selling dearer bottles", "more expensive bottles", "dearer bottles"], "ans": "The sales mix shifted toward dearer bottles", "ex": 1, "exp": "Nothing went wrong: guests traded up. Dearer bottles carry a higher cost percentage and a bigger cash margin, so a mix moving toward them lifts both lines at once. A percentage read without the cash line beside it punishes exactly the selling a venue most wants."},
{"id": "c-86sjz5x4", "cat": "Business of the Sommelier", "q": "Under the commonest by-the-glass pricing rule, the first glass sold pays back what the venue gave for the whole bottle. What is the rest of the bottle doing?", "opts": ["Funding the complimentary tastes that convention obliges the venue to pour before a guest commits to any glass", "Carrying the programme's spoilage risk and its profit, so even a half-dumped bottle breaks even", "Stepping up in price with every pour, so the last glass out of the bottle is the dearest", "Nothing, because the rule is only used where local licensing forbids selling the same wine by the bottle"], "a": 1, "exp": "The glass is priced at roughly the bottle's wholesale cost, so the first pour clears the outlay and every later one is gain. A bottle that only half sells before it tires has still done no damage, and that safety is what lets a venue open wine on speculation."},
{"id": "c-xat9gr4i", "cat": "Business of the Sommelier", "q": "Glass by glass, a by-the-glass bottle brings in 70; the same wine sells whole from the list for 48. What earns the venue that premium?", "opts": ["Duty and sales tax fall per serving rather than per bottle, and the difference is passed on", "Licensing floors set a minimum per-pour price above the bottle equivalent", "It carries the whole risk of the open bottle, and the guest is spared committing to a full one", "The glass list is deliberately overpriced to push guests toward bottles"], "a": 2, "exp": "Per millilitre the guest pays more and risks less: two people can drink two different wines without owning 750 ml of either. The venue's side of the bargain is the open bottle, which may never sell another pour after tonight."},
{"id": "c-6ku3flih", "cat": "Business of the Sommelier", "q": "Four times cost at the bottom of the list, sliding down to twice cost at the top: on that scale, a bottle landed at 90 sits in the top band. Give its list price.", "sa": 1, "accept": ["180", "$180", "180 dollars", "one hundred and eighty", "one hundred eighty", "180 a bottle", "one eighty"], "ans": "180", "ex": 1, "exp": "Twice 90 is 180. The multiple falls as cost rises because a fine bottle at four times cost would sit unsold forever, while at twice cost its cash margin still dwarfs the house pour's. That slide is why the percentage worsens up a list while the money improves."},
{"id": "c-58lrcf2l", "cat": "Business of the Sommelier", "q": "Five 150 ml pours come out of a by-the-glass bottle that cost the venue 25, and the pours sell at 15 apiece. Give the pour cost percentage.", "sa": 1, "accept": ["33 percent", "33", "33%", "33 per cent", "thirty three percent", "thirty three per cent", "thirty three", "one third", "a third", "about a third", "one in three", "33.3", "33.3%", "about 33 percent", "33.3 percent", "33.3 per cent", "33.33", "33.33%", "33.33 percent", "33.33 per cent"], "ans": "33 percent", "ex": 1, "exp": "The bottle gives five pours, so one pour costs 5 and sells at 15: 5 over 15 is 33 percent. That 33 percent is only the pencil figure: realized pour cost runs higher, because the glass programme carries losses a sealed bottle never suffers."},
{"id": "c-ep852vm2", "cat": "Business of the Sommelier", "q": "For flagship pours the usual deadline on getting a bottle's cost back is loosened, though only slightly. Within how many pours does the trade still expect that money home?", "sa": 1, "accept": ["two pours", "two", "2", "2 pours", "two glasses", "2 glasses", "first two pours", "within two pours", "in two pours"], "ans": "Two pours", "ex": 1, "exp": "One pour is the standard and two is the concession, granted when full recovery in a single glass would price the wine past anyone willing to try it. Past two, the cost is riding on pours nobody can promise, and a flagship bottle is exactly the one a venue cannot afford to guess about."},
{"id": "c-puggcxc3", "cat": "Business of the Sommelier", "q": "Without delisting a single wine, a buyer wants the cellar to swallow less of the venue's cash. Which change in purchasing achieves it?", "opts": ["Quarterly drops big enough to earn case discounts, cutting the landed cost of every bottle", "Settling every invoice on delivery, so early-payment discounts offset the cost of the cellar", "Consolidating with one supplier, so a single monthly order replaces a dozen small deliveries", "Smaller orders placed more often, leaving the stock in the distributor's warehouse"], "a": 3, "exp": "Stock in the distributor's warehouse is the distributor's cash problem; stock in the cellar is the venue's. Frequent small drops trade a little discount away for weeks of freed cash, and most operators come out ahead on the swap."},
{"id": "c-dmecgaag", "cat": "Business of the Sommelier", "q": "Nine bottles of a rose leave the shelf in an average week, deliveries land weekly, and the buyer wants a 3-bottle cushion in hand against a big Saturday. To what count should a delivery restore the shelf?", "sa": 1, "accept": ["twelve bottles", "twelve", "12", "12 bottles", "a dozen", "a dozen bottles"], "ans": "Twelve bottles", "ex": 1, "exp": "A week's sales plus the cushion: nine and three make twelve. Set the standing count higher and the extra bottles are money asleep; set it lower and one busy weekend empties the bin, and the wine is off the list until the truck comes back."},
{"id": "c-wksvm9rw", "cat": "Business of the Sommelier", "q": "Holding 60,000 of stock at cost across the year, a cellar feeds an annual beverage cost of sales of 180,000. How many times did the stock turn?", "sa": 1, "accept": ["three turns a year", "three", "3", "three turns", "3 turns", "three times", "3 times", "three times a year", "3 times a year", "3 turns a year", "three turns per year", "3x", "it turns three times", "three times per year", "3 times per year", "3 turns per year", "three per year", "3 per year", "3x a year"], "ans": "Three turns a year", "ex": 1, "exp": "Cost of sales over average stock: 180,000 over 60,000 turns three times. A grand cellar may turn barely once a year while a bistro turns monthly, and neither is wrong; the figure simply prices what that style of list costs to run."},
{"id": "c-47kjpk28", "cat": "Business of the Sommelier", "q": "Money the venue has already spent on wine still waiting to sell is, the accountant says, tied up rather than gone. Which two-word pool of funds is a deep cellar tying up?", "sa": 1, "accept": ["working capital", "its working capital", "operating capital", "its operating capital"], "ans": "Working capital", "ex": 1, "exp": "Working capital pays the wages, the produce order and the rent between now and the next busy Saturday. A bottle on the shelf still counts in it on paper, but as stock it can settle no bill until it sells and turns back into cash. Tied up, not gone, is the real cost of a deep cellar, and it never appears on the wine list."},
{"id": "c-rzx68alm", "cat": "Business of the Sommelier", "q": "Bottles sold across a period, divided by the bottles that sat available to sell: which measure is that?", "sa": 1, "accept": ["sell through", "sellthrough", "sell through rate", "sell through percentage", "sellthrough rate"], "ans": "Sell-through", "exp": "Ten in the bin at the start and six gone is sixty percent sell-through. It reads the list wine by wine, which a whole-cellar turn figure cannot, and it flags a listing as a passenger long before its first birthday on the page."},
{"id": "c-2nirvkol", "cat": "Business of the Sommelier", "q": "Sorted for the quarterly list review, every wine lands in one of four boxes. Which two measurements draw that grid?", "opts": ["How often it sells, and how much cash each sale leaves behind", "Its score in the press, and its price", "Its age on the list, and the value of the bin it occupies", "Its beverage cost percentage, and its supplier's discount tier"], "a": 0, "exp": "Volume and cash margin sort a list into workhorses, stars, puzzles and passengers, and each box has its own remedy: promote, protect, reprice or replace. Cost percentage appears nowhere in the grid, because a wine can hit its percentage and still earn almost nothing."},
{"id": "c-p27oph0f", "cat": "Business of the Sommelier", "q": "Afraid of looking mean, most tables skip past the cheapest bottle on the page, and trade lore holds that one slot quietly outsells everything around it. Which slot?", "sa": 1, "accept": ["second cheapest", "second cheapest bottle", "second cheapest wine", "second cheapest slot", "second cheapest on the list", "second cheapest bottle on the list", "second cheapest wine on the list", "second from the bottom", "second lowest", "second lowest priced", "second least expensive", "one up from the cheapest", "next cheapest", "next cheapest bottle", "next to cheapest", "second cheapest on the page", "second cheapest bottle on the page", "second cheapest wine on the page", "2nd cheapest", "2nd cheapest bottle", "2nd cheapest wine"], "ans": "The second-cheapest bottle on the list", "ex": 1, "exp": "Nobody wants to read as the table's economist, so the finger settles one line up from the bottom. Buyers know it, which is why that slot so often carries the list's friendliest margin rather than its finest wine."},
{"id": "c-mqpb4ars", "cat": "Business of the Sommelier", "q": "High on the first page sits a bottle priced beyond what almost anyone will pay, and the buyer never expected it to sell. What is it there to do?", "sa": 1, "accept": ["anchoring", "anchor", "price anchoring", "price anchor", "decoy", "decoy pricing", "makes the rest of the list look reasonable", "making the rest of the list look reasonable", "makes the rest look reasonable", "making the rest look reasonable", "makes everything else look cheaper", "making everything else look cheaper", "makes the other bottles look reasonable", "makes the rest of the list look cheaper", "makes the other wines look cheap", "make the other wines look cheap", "makes the other bottles look cheaper", "look cheap by comparison", "look cheaper by comparison"], "ans": "Anchoring: it makes the rest of the list look reasonable", "exp": "Its work is done unsold: beside a 900 bottle, 120 reads as restraint. Placement does the arithmetic on the guest's behalf, and the effect costs the venue nothing so long as the bottle finds one buyer a year."},
{"id": "c-mvsl404g", "cat": "Business of the Sommelier", "q": "Reading down a page priced 40, 48, 58 and 70, a guest can climb toward better wine in small, painless steps. Which pricing tactic built the page?", "sa": 1, "accept": ["laddering", "price laddering", "price ladder", "ladder pricing", "laddered pricing", "ladder"], "ans": "Laddering", "exp": "Each rung asks a little more than the last and never a leap, so the climb from 40 to 70 happens one easy step at a time. Gaps work the other way: a page that jumps from 50 to 95 loses every guest standing at the edge of the jump."},
{"id": "c-ljbqamdz", "cat": "Business of the Sommelier", "q": "Every night a wine bar tips away two open bottles at an average cost of 20, and a 3,000 gas preservation system is proposed. What does the arithmetic say?", "opts": ["Two bottles a night is too small a loss to justify any capital spend", "Payback only arrives if glass prices rise alongside the equipment", "Gas refills will cost more over a year than the wine they save, so the case fails", "About 280 of wine a week stops going down the sink, and 3,000 is eleven weeks of that"], "a": 3, "exp": "Two bottles at 20 is 40 a night and 280 a week, poured away. Against that, 3,000 of kit is under eleven weeks of losses, so the system pays for itself inside three months and everything after that is margin. Preservation is bought with wine that was already being thrown out."},
{"id": "c-v58058x2", "cat": "Business of the Sommelier", "q": "Priced to recover its whole cost in one pour, a rare glass finds no takers; priced where guests bite, recovery takes three pours. What settles the argument for the lower price?", "opts": ["An unsold rare bottle can always go back to the distributor for credit, so the downside was never real", "Under gas the remainder keeps for weeks, so the bottle can earn its cost back slowly", "The lower price still clears the cost, and nothing else about a glass matters", "Three pours from a single bottle is the ceiling most licences allow, so the arithmetic can never get worse"], "a": 1, "exp": "Preservation changes the deadline, and the deadline was the whole argument for aggressive pricing. Once the remainder keeps, the bottle can earn its cost across a week of single pours, and the lower price recruits the guests who make that happen."},
{"id": "c-8tjd4nek", "cat": "Business of the Sommelier", "q": "Sunday night closes with the week's unsold open bottles poured down the sink and their cost value entered in the books. Under which heading does that loss go?", "sa": 1, "accept": ["wastage", "waste", "spoilage", "spoilage loss", "spillage and wastage", "wastage and spillage", "waste and spoilage", "spoilage and waste", "wastage line", "waste line", "as wastage", "under wastage", "recorded as wastage", "wine waste"], "ans": "Wastage", "ex": 1, "exp": "Wastage is the counted, explained loss: wine that tired before it sold, priced at cost and written down. Keeping it as its own line matters, because it is the one component of pour cost a manager can actually attack with equipment and discipline."},
{"id": "c-mla6psej", "cat": "Business of the Sommelier", "q": "Short and quick-selling is the only safe shape for a by-the-glass page poured without any preservation. What is the page's length being matched to?", "sa": 1, "accept": ["how fast each wine sells", "how fast it sells", "how fast the wines sell", "how quickly each wine sells", "how quickly it sells", "sales velocity", "velocity", "rate of sale", "speed of sale", "pace of sale", "pace of sales", "how quickly bottles sell", "how fast bottles sell", "speed at which the wines sell", "speed at which they sell", "how fast bottles empty", "how quickly bottles empty", "how fast each bottle empties", "how fast the wine sells", "how fast they sell", "how quickly the wines sell", "how quickly they sell", "how quickly the wine sells", "sales pace", "selling speed"], "ans": "How fast each wine sells", "exp": "An unprotected open bottle has two or three days of honest life, so the page is sized to what will empty inside that window. Add gas and the constraint relaxes, which is why the length of a by-the-glass page is a statement about the bar's equipment."},
{"id": "c-01t3aebc", "cat": "Business of the Sommelier", "q": "Through the needle of a preservation device, a 400 bottle gives ten 75 ml tastes. To hold a 25 percent cost on the pour, what must one taste sell for?", "sa": 1, "accept": ["160", "$160", "160 dollars", "one hundred and sixty", "one hundred sixty", "one sixty", "160 a taste", "160 a pour", "160 a glass", "160 per taste", "160 per pour", "160 per glass", "160 each"], "ans": "160", "ex": 1, "exp": "Ten tastes from one bottle puts 40 of cost into each; 40 over 0.25 is 160. The arithmetic is the same as any pour cost, only the pour is smaller and the bottle dearer, which is how a 400 wine meets a guest who would never buy it whole."},
{"id": "c-8stjtgtn", "cat": "Business of the Sommelier", "q": "Six bottles a year of a cult Pinot arrive only because the distributor chooses the venue, and the buyer knows the price of staying chosen. What is the venue expected to do in return?", "sa": 1, "accept": ["buy the rest of the book", "the book", "the portfolio", "the range", "~rest of the book", "~rest of the portfolio", "~rest of the range", "~rest of the wines", "~whole book", "~whole portfolio", "~whole range", "~whole of the book", "~whole of the portfolio", "~entire book", "~entire portfolio", "~entire range", "~their book", "~their portfolio", "~their range", "~their list", "~their wines", "~its book", "~its portfolio", "~its range", "~his book", "~his portfolio", "~distributor's book", "~distributors book", "~distributor's portfolio", "~distributors portfolio", "~distributor's range", "~distributors range", "~distributor's list", "~distributors list", "~distributor's wines", "~distributors wines", "the other wines", "the other bottles", "the other labels", "~their other wines", "~its other wines", "~his other wines", "~distributor's other wines", "~distributors other wines", "~their other bottles", "~distributor's other bottles", "~their other labels", "~distributor's other labels", "~everyday wines", "~everyday bottles", "~everyday labels", "~commercial wines", "~bread and butter wines", "~everything else they sell", "~everything else the distributor sells", "~everything else in the book", "~everything else in the portfolio", "~buy the book", "~buys the book", "~buying the book", "~buy the portfolio", "~buys the portfolio", "~buying the portfolio", "~buy the range", "~buys the range", "~buying the range", "~take the book", "~takes the book", "~taking the book", "~take the portfolio", "~takes the portfolio", "~taking the portfolio", "~carry the book", "~carries the book", "~carrying the book", "~carry the portfolio", "~carries the portfolio", "~carrying the portfolio", "~support the book", "~supports the book", "~supporting the book", "~support the portfolio", "~supports the portfolio", "~supporting the portfolio", "~stock the book", "~stocks the book", "~stocking the book", "~stock the portfolio", "~stocks the portfolio", "~stocking the portfolio", "~across the book", "~across the portfolio", "~across the range"], "ans": "Buy the rest of the book", "ex": 1, "exp": "Scarce wine is currency, and the distributor spends it on accounts that carry the everyday bottles as well. Let those go and the cult ones quietly stop arriving; another venue is always happy to take the whole book."},
{"id": "c-xlqtd60h", "cat": "Business of the Sommelier", "q": "One line of beverage spend costs a few open bottles a week and pays for itself in what the floor can say at the table. Which spend is it?", "sa": 1, "accept": ["training", "trainings", "the training budget", "~staff training", "~staff trainings", "~staff wine training", "~wine training", "~server training", "~floor training", "~team training", "~sommelier training", "~somm training", "~beverage training", "~training the staff", "~training our staff", "~training for the staff", "~training of the staff", "~training the floor", "~training for the floor", "~training the team", "~training for the team", "~training the servers", "~training our servers", "~training the new servers", "~training the sommeliers", "~training the somms", "~training the waiters", "~training the front of house", "~training up the staff", "~training up the floor", "~training up the team", "~training up the servers", "~front of house training", "~service training", "~tasting the staff", "~tasting the floor", "~tasting the team", "~tasting the servers", "~tasting the sommeliers", "~staff education", "~staff wine education", "~wine education", "~floor education", "~team education", "~server education", "~beverage education", "~educating the staff", "~educating our staff", "~educating the floor", "~educating the team", "~educating the servers", "~educating our servers", "~educating our floor", "~educating our team", "~educating the sommeliers", "~education for the staff", "~education for the floor", "~staff tastings", "~staff tasting", "~staff wine tastings", "~staff wine tasting", "~team tastings", "~team tasting", "~tastings for the staff", "~tasting for the staff", "~tastings with the staff", "~tasting with the staff", "~pre shift tastings", "~pre shift tasting", "~preshift tastings", "~preshift tasting", "~line up tastings", "~lineup tastings", "~weekly line up", "~weekly lineup", "~staff line up", "~staff lineup", "~training line", "~training spend", "~training programme", "~training program"], "ans": "Staff training", "ex": 1, "exp": "A server who has tasted a wine sells it, and one who has not changes the subject. A weekly line-up costs a few bottles at wholesale and repays in better bottles leaving the cellar and slow bins finally moving, which no other line on the budget does at that price."},
{"id": "c-w9ddn1ou", "cat": "Business of the Sommelier", "q": "On the owner's nod, two bottles go free of charge to a critic's table. How does a clean set of books record them?", "opts": ["At cost, on a promotion line rather than in beverage cost", "As breakage, since the stock left the cellar without any matching sale", "At full list price, rung through the till as a sale and immediately voided by a manager", "Nowhere, because accounts exist to record transactions and no money changed hands"], "a": 0, "exp": "The bottles are a real cost and a deliberate one, so they move at cost value out of beverage cost and into promotion, where the spend was actually made. Left in beverage cost they poison the percentage; recorded nowhere, the stock count comes up short with nothing to say why."},
{"id": "c-3uxsdzsw", "cat": "Business of the Sommelier", "q": "Fourteen bottles left the cellar by the physical count, while the till shows twelve sold and one recorded comp. What does the fourteenth bottle become in the stock report?", "sa": 1, "accept": ["variance", "shrinkage", "variance or shrinkage", "shrinkage or variance", "stock variance", "inventory variance", "unexplained loss", "unaccounted loss", "unaccounted for loss", "unaccounted for", "unexplained shrinkage", "stock discrepancy", "discrepancy", "unexplained variance", "stock loss", "unexplained stock loss", "stock shortage", "shortage"], "ans": "Variance, or shrinkage", "ex": 1, "exp": "Twelve sold and one comped explains thirteen; the fourteenth is variance, the gap between what left and what was accounted for. A steady trickle of it is over-pouring or sloppy recording, a widening one is theft, and neither shows without the count."},
{"id": "c-ahnjmi6a", "cat": "California", "q": "State law obliges any wine using a Napa sub-appellation such as Oakville or Rutherford to print Napa Valley on the same label. What is that requirement called?", "opts": ["Conjunctive labeling", "Nested appellation disclosure", "Compound origin marking", "Appellation transfer"], "a": 0, "exp": "Nothing federal demands it: the TTB approves an AVA boundary and then says nothing about how the name is used alongside a larger one. California legislated it to stop the parent name being diluted by sub-appellations trading on their own, and Sonoma County growers later won the same protection for theirs."},
{"id": "c-6hm1h3bc", "cat": "California", "q": "A back label reads Produced and Bottled by, followed by a winery name and its town. How much of the wine must that winery have fermented itself?", "opts": ["Fifty-one percent of it", "Eighty-five percent of it", "Seventy-five percent of it", "All of it"], "a": 2, "exp": "Produced and Made are the two phrases that carry a fermentation threshold, and the federal rule sets both at 75 percent fermented at the stated address. Cellared and Bottled by, Vinted and Bottled by or Prepared and Bottled by cover wine bought in finished and merely given cellar treatment there, and Blended and Bottled by means only that wines of the same class and type were mixed at that address. None of those four tells the guest who actually made it."},
{"id": "c-d3mz0vyw", "cat": "California", "q": "Eighty percent of a blend comes off Rutherford and the remaining fifth off Oakville, so neither sub-appellation may go on the label. What is the tightest appellation this wine may still claim?", "sa": 1, "accept": ["napa valley", "napa valley ava", "napa valley appellation"], "ans": "Napa Valley", "ex": 1, "exp": "An AVA name needs 85 percent of the fruit from inside its boundary, and no single sub-appellation clears that here. Both benches sit wholly inside Napa Valley, however, so the parent AVA is satisfied at 100 percent and is the tightest claim left. Dropping to Napa County or to California would be legal but needlessly vague."},
{"id": "c-i5gthk13", "cat": "California", "q": "Federal rules would happily let a wine calling itself Sonoma County carry a quarter of its fruit from outside the state altogether. A California statute shuts that door. What does the state demand instead?", "sa": 1, "accept": ["one hundred percent california grown", "100 percent california grown", "100% california grown", "100% california", "100 percent california", "one hundred percent california", "100% california grapes", "100% california fruit", "100 percent california grapes", "100 percent california fruit", "all california grapes", "all california fruit", "entirely california grown", "all of the fruit must be grown in california", "every grape must be grown in california", "all the grapes must come from california", "all the grapes must be grown in california", "all of the grapes must be grown in california", "the grapes must all be grown in california", "every grape must come from california", "all the fruit must come from california", "all the fruit has to come from california", "all fruit grown in california", "every grape grown in california", "100% of the grapes must be grown in california", "100% of the fruit must be grown in california", "100% of the grapes must be from california", "100 percent of the grapes must be grown in california", "one hundred percent of the fruit from california", "one hundred percent of the grapes from california", "every grape has to be grown in california", "all of the fruit has to be grown in california", "the wine must be entirely from california grapes", "one hundred percent californian fruit"], "ans": "One hundred percent California grown", "ex": 1, "exp": "Federal law asks only 75 percent for a county or state name, which would let a Sonoma County bottling be topped up from anywhere. California overrides that: a wine carrying any Californian appellation of origin must be made entirely from Californian fruit. It is one of several places where state law is stricter than the federal floor rather than merely different from it."},
{"id": "c-ijf6g9l0", "cat": "California", "q": "Fruit grown in one state is blended in a cellar with fruit from another, leaving the broadest appellation on the books as the only one available. What may the label no longer state?", "sa": 1, "accept": ["vintage", "vintage date", "vintage year", "year of harvest", "harvest year", "harvest date", "the year the grapes were harvested", "the year the grapes were picked"], "ans": "The vintage", "exp": "Two or three states that are contiguous can share an appellation of their own, with the percentage from each printed on the label, and a wine carrying it keeps its vintage. Where that is not available the wine falls back to American, which is a country-level appellation, and a vintage date is permitted only when the appellation is something other than a country. So the harvest year is the price of the fallback. It is a useful reminder that the appellation on an American label controls far more than geography."},
{"id": "c-uk7y3159", "cat": "California", "q": "Afternoon air off San Pablo Bay passes bare volcanic palisades that give the day's heat back after dark, and the Cabernet grown beneath them is the valley's most supple. Which appellation is this?", "opts": ["Oak Knoll District", "Stags Leap District", "St. Helena", "Yountville"], "a": 1, "exp": "The rock face on the eastern side stores heat and radiates it into the night while the bay air holds the afternoons in check, and the wines are the softest-textured of Napa's Cabernet districts. The appellation is spelled without an apostrophe, a compromise reached because two neighbouring wineries both used one in their own names."},
{"id": "c-ab1o3lmf", "cat": "California", "q": "Andre Tchelistcheff arrived at Beaulieu in 1938 and spent decades insisting that one stretch of valley floor grew Napa's finest Cabernet. Which appellation did he champion?", "opts": ["Calistoga", "Rutherford", "Wild Horse Valley", "Chiles Valley District"], "a": 1, "exp": "It takes Rutherford dust to grow great Cabernet is the line attributed to him, describing the fine, dusty grain of tannin off the alluvial fans on the western side of the river. His influence reaches well past one appellation: he brought controlled cold fermentation and deliberate malolactic conversion to California and trained most of the next generation of winemakers."},
{"id": "c-37d5bajn", "cat": "California", "q": "Hamilton Crabb planted a bench on the western side of Oakville in the 1860s and gave it a Greek name meaning the highest beauty. Which vineyard is that?", "sa": 1, "accept": ["to kalon", "to kalon vineyard", "tokalon", "to kalon in oakville"], "ans": "To Kalon", "exp": "The bench is an alluvial fan spilling off the Mayacamas, deep and gravelly enough that the fruit ripens evenly across a large block, which is why so many separate bottlings come off it. The name has been fought over in trademark court precisely because more than one label carries it."},
{"id": "c-anjlh48a", "cat": "California", "q": "At its northern end the valley narrows sharply beneath Mount St. Helena, and daytime highs on that stretch of floor run the warmest in Napa. Which appellation sits in the neck?", "sa": 1, "accept": ["calistoga", "calistoga ava", "calistoga appellation", "calistoga in napa valley"], "ans": "Calistoga", "exp": "Heat by day is only half of it: cold air drains down off the mountain and in from Knights Valley at night, so the diurnal swing is wide despite the highs. The soils are volcanic sediment and ash washed off the surrounding hills rather than the river gravel of the mid-valley benches."},
{"id": "c-323zkak2", "cat": "California", "q": "A horseshoe of low hills east of the city of Napa opens straight onto San Pablo Bay, and Cabernet there ripens weeks behind Oakville's. Name that appellation.", "sa": 1, "accept": ["coombsville", "coombsville ava", "coombsville appellation", "coombsville in napa valley"], "ans": "Coombsville", "exp": "Nothing stands between it and the water, so bay air arrives undiluted and it is one of the coolest corners of Napa, cooler than any mid-valley bench and behind only Carneros itself. The soils are ash and tuff shed by the long-collapsed Mount George volcano, free-draining and poor, and the wines come in leaner and higher in acid than the mid-valley norm."},
{"id": "c-ii3qfwwq", "cat": "California", "q": "One Napa mountain appellation is planted on uplifted marine sandstone and shale, and fossil seashells turn up between its vineyard rows. Which one?", "opts": ["Howell Mountain", "Atlas Peak", "Mount Veeder", "Diamond Mountain District"], "a": 2, "exp": "The Mayacamas expose old Franciscan seabed here rather than the volcanic material that dominates the ranges either side of the valley. The soils are thin, acidic and low in vigour, which gives tiny berries and a severe young tannin that needs a decade, and it is the standard contrast drawn against the ash and tuff of the Vaca side."},
{"id": "c-9a4zdq9b", "cat": "California", "q": "Glittering fragments of volcanic rock in the soil gave a Mayacamas appellation above Calistoga its name. Which appellation?", "opts": ["Oak Knoll District", "Yountville", "Chiles Valley District", "Diamond Mountain District"], "a": 3, "exp": "The soils are weathered volcanic ash and tuff, red, sharp-draining and shot through with the fragments the name records. It occupies the northern end of the Mayacamas above the warmest part of the valley floor, and the wines are dark and firmly built even by mountain standards."},
{"id": "c-3kcfy81l", "cat": "California", "q": "Water rising out of the Mayacamas hillside above St. Helena named the district planted there, and its vineyards sit in clearings cut from forest rather than in continuous blocks. Name it.", "sa": 1, "accept": ["spring mountain district", "spring mountain", "spring mountain district ava", "spring mountain district in napa"], "ans": "Spring Mountain District", "exp": "It faces the Pacific weather first and is the wettest corner of Napa, so dry farming is realistic there in a way it is not on the valley floor. Its geology is a patchwork of sedimentary and volcanic material rather than one or the other, which is why it resists the neat characterisation its neighbours get."},
{"id": "c-go6sffwk", "cat": "California", "q": "A Vaca-range appellation above St. Helena farms a deep red iron-rich volcanic loam alongside a pale weathered ash that locals miscall tufa. Which appellation?", "sa": 1, "accept": ["howell mountain", "howell mountain ava", "howell mountain appellation", "howell mountain in napa"], "ans": "Howell Mountain", "exp": "The red material is Aiken loam, weathered from old lava flows and unusually deep for a mountain site. The pale material is properly tuff, consolidated volcanic ash; tufa is a calcareous spring deposit and has nothing to do with volcanoes, so the local usage is a misnomer that has stuck. Both soils are poor, acidic and free-draining."},
{"id": "c-8jyjqy4n", "cat": "California", "q": "Sheep grazed the low hills where Napa and Sonoma counties run down to the bay long before vines did, and the appellation there still carries the Spanish word for them. Name it.", "sa": 1, "accept": ["los carneros", "carneros", "los carneros ava", "carneros ava"], "ans": "Los Carneros", "exp": "Carneros is Spanish for rams. The boundary was drawn around the reach of the cold bay air rather than around a county line, so the same appellation appears on Napa labels and Sonoma labels alike. Shallow clay sitting on a dense hardpan keeps roots near the surface and vigour naturally low."},
{"id": "c-ipuppg2b", "cat": "California", "q": "Pale soil underfoot named one Sonoma appellation, though a geologist would not call the material chalk at all. What is it?", "opts": ["Volcanic ash", "Diatomaceous earth", "Wind-blown loess", "Kimmeridgian marl"], "a": 0, "exp": "The white ash weathered out of the Sonoma Volcanics and simply looks chalky to the eye. There is no limestone beneath it, so none of the calcareous virtues the name implies are actually in play, and the appellation sits in the warmer northeastern corner of the Russian River Valley, nested wholly inside it."},
{"id": "c-bp39ogyv", "cat": "California", "q": "Fog lingers longest over one small appellation nested inside the Russian River Valley, on sandy loam that drains fast and holds vine vigour down. Which one?", "opts": ["Green Valley of Russian River Valley", "Pine Mountain-Cloverdale Peak", "Fountaingrove District", "Chalk Hill"], "a": 0, "exp": "It occupies the southwestern corner of the parent AVA, closest to the ocean and to the wind gap south of it, and is the coldest and latest-ripening part of the whole zone. The full name carries the parent appellation because another Green Valley already exists in Solano County, and two AVAs may not share a bare name."},
{"id": "c-6mr6pfdy", "cat": "California", "q": "A grower on a ridge within sight of the Pacific and a grower on warm flats near Carneros may print exactly the same Sonoma appellation. Which one is drawn that broadly?", "opts": ["Northern Sonoma", "Sonoma Coast", "Sonoma Valley", "Dry Creek Valley"], "a": 1, "exp": "It was drawn wide in the 1980s so that estates holding vineyards in several parts of the county could use a single name, and the result spans climates no one label can honestly describe. Fort Ross-Seaview, high on the ridges above the ocean and above the fog line, was later carved out of it for exactly that reason."},
{"id": "c-iuhcsfpw", "cat": "California", "q": "Fine sandy loam weathered out of an uplifted seabed underlies the western Russian River Valley and is the soil named most often on a Sonoma Pinot Noir back label. Name it.", "sa": 1, "accept": ["goldridge", "gold ridge", "goldridge soil"], "ans": "Goldridge", "exp": "It is a light, free-draining loam over sandstone, low in nutrients, so vines set small crops without much persuasion and roots run deep chasing water. The eastern side of the valley runs to heavier clay loams that hold water and push vigour, and growers treat the two as separate farming problems on the same appellation."},
{"id": "c-yi7m43es", "cat": "California", "q": "High above Lake Sonoma, one appellation admits no vineyard below eight hundred feet, which puts every acre of it clear of the fog. Name it.", "sa": 1, "accept": ["rockpile", "rockpile ava", "rockpile appellation", "rockpile in sonoma county"], "ans": "Rockpile", "exp": "An elevation floor written into the boundary is the same device Howell Mountain uses in Napa, and it guarantees full sun and warm nights above the marine layer. The ground is steep, rocky and poor, planted almost entirely to Zinfandel and Cabernet Sauvignon, and the fruit is trucked out because there is nowhere up there to crush it."},
{"id": "c-cr6ze2w7", "cat": "California", "q": "A long break in the coastal hills between Bodega Bay and San Pablo Bay funnels wind rather than merely fog, and the appellation drawn around it rests on that wind. Name it.", "sa": 1, "accept": ["petaluma gap", "petaluma gap ava", "petaluma gap appellation", "petaluma gap in sonoma", "petaluma wind gap"], "ans": "Petaluma Gap", "exp": "Wind was the distinguishing feature the petition argued from, which no American appellation had leaned on before. Persistent afternoon wind thickens skins and shuts photosynthesis down, so fruit hangs late and arrives small-berried, dark and high in acid. The gap crosses the county line into Marin, so the appellation does too."},
{"id": "c-2x4ax5tj", "cat": "California", "q": "Rather than following ridgelines or county lines, one California appellation is bounded by a contour, so a vineyard either sits high enough to qualify or it does not. Which appellation?", "opts": ["San Benito", "Santa Cruz Mountains", "Livermore Valley", "Sierra Foothills"], "a": 1, "exp": "The boundary is drawn largely along the fog line: roughly 400 feet on the ocean side and 800 feet on the bay side, the higher figure needed inland because the marine layer lies deeper there, with roads and section lines closing the stretches where no contour serves. It was among the first American appellations defined by elevation rather than by administrative boundary, and it takes in parts of three counties."},
{"id": "c-fdffwjh3", "cat": "California", "q": "Cold water lies unusually close inshore at Monterey Bay, and the wind that pours up the valley behind it is fiercer than at any comparable latitude. Which offshore feature keeps that water cold?", "opts": ["A chain of offshore islands", "A warm counter-current running north", "A shallow sandbar across the bay mouth", "A submarine canyon close to the shore"], "a": 3, "exp": "The canyon is one of the deepest on the continental margin and its head reaches almost to the shoreline at Moss Landing, so it brings cold water from far below the surface within reach of the shore. The Salinas Valley opens straight onto it, so the afternoon wind is strong enough that row orientation and trellis height are planned around it rather than around sunlight."},
{"id": "c-dxj3rd29", "cat": "California", "q": "Rounded river stones the size of a fist litter one Monterey appellation, and growers there call them Greenfield potatoes. Name that appellation.", "sa": 1, "accept": ["arroyo seco", "arroyo seco ava", "arroyo seco appellation", "arroyo seco in monterey county"], "ans": "Arroyo Seco", "exp": "The cobbles were dropped by the river as it left the Santa Lucia range, and they store heat through the day and give it back at night in a valley that is otherwise cold and wind-scoured. That stored warmth is why aromatic whites ripen there while Pinot Noir does better on the benches above."},
{"id": "c-xq6wo1b0", "cat": "California", "q": "Terraces cut into east-facing benches of the Santa Lucia range sit above the worst of the Salinas Valley wind and have become Monterey's most sought-after Pinot Noir ground. Name that appellation.", "sa": 1, "accept": ["~santa lucia highlands", "~santa lucia highland", "slh"], "ans": "Santa Lucia Highlands", "ex": 1, "exp": "Facing east means the fruit takes the morning sun and is then shaded as the wind builds, which is the reverse of the usual hillside logic and exactly what that valley needs. The benches are gravelly alluvial fans, far better drained than the deep silt of the valley floor below them. Note that the range and the appellation are not the same thing: the Santa Lucias run most of the length of the Central Coast, while the appellation is the strip of benchland on their eastern flank."},
{"id": "c-045vec5m", "cat": "California", "q": "Limestone is scarce under California vineyards, but one appellation high on the Gabilan range east of the Salinas Valley is built on it and on decomposed granite. Name it.", "sa": 1, "accept": ["chalone", "chalone ava", "chalone in monterey county"], "ans": "Chalone", "exp": "The Gabilan range carries a band of limestone that surfaces here and again at Mount Harlan across the county line, which is why the two are so often named in the same breath. Vineyards sit around 1,800 feet, above the fog and clear of the valley wind, on ground poor enough that yields stay minute without any deliberate restriction."},
{"id": "c-txemec8t", "cat": "California", "q": "Paso Robles is picked across a spread of dates wide enough for two separate regions, and the divide runs along the Salinas River. Which half is the cooler and later one?", "opts": ["The northern end, where elevation runs highest", "The southern end, nearest the Cuesta Grade", "The west side, on calcareous shale reached by marine air", "The east side, on deep alluvial soils well away from the fog"], "a": 2, "exp": "Marine air comes through a break in the Santa Lucia range and reaches the western hills first, so they ripen later and hold acidity while the eastern flats bake and finish early. Those western soils are pale and strongly calcareous, weathered out of the Monterey Formation. The appellation was eventually divided into eleven sub-appellations because a single description of it had stopped meaning anything."},
{"id": "c-ciqin333", "cat": "California", "q": "Marine air reaches the western half of Paso Robles through a single break in the Santa Lucia range. Name that break.", "sa": 1, "accept": ["templeton gap", "gap at templeton"], "ans": "The Templeton Gap", "exp": "Cold air off Morro Bay pushes through in the afternoon and evening and can drop temperatures thirty degrees Fahrenheit or more overnight, which is why the west side behaves like a different region from the east. Gaps of this kind are the whole story of cool-climate viticulture in a state that is otherwise walled off from its own ocean."},
{"id": "c-fbsef796", "cat": "California", "q": "A small San Luis Obispo appellation takes an unobstructed sweep of marine air funnelled in from Morro Bay through the Los Osos Valley, and records one of the longest growing seasons in California. Name it.", "sa": 1, "accept": ["edna valley", "edna valley ava", "edna valley appellation", "edna valley in san luis obispo"], "ans": "Edna Valley", "exp": "The bay itself lies some fifteen miles to the northwest, but the Los Osos gap is a wide mouth and the hills around the valley hold what comes through it, so daytime highs stay low and fruit routinely hangs into November. A line of old volcanic plugs known as the Nine Sisters runs through the district, and the soils mix that volcanic material with marine sediment beneath it."},
{"id": "c-erl8k66o", "cat": "California", "q": "One Santa Barbara appellation prints an abbreviated form of its own name on every label, the result of an objection raised from another continent. Whose objection forced it?", "opts": ["A Portuguese quinta of the same name", "An Argentine bodega of the same name", "A Spanish denomination of the same name", "A Chilean estate called Santa Rita"], "a": 3, "exp": "The Chilean house had been selling under that name for well over a century before the appellation was approved, and the abbreviation is the legal settlement that followed rather than a stylistic quirk, which is why it is always written that way and never spelled out in full. The appellation itself occupies the cold, wind-scoured western end of its valley, where the transverse ranges let the ocean straight in."},
{"id": "c-udhbif6x", "cat": "California", "q": "Within the Santa Ynez Valley a sub-appellation was drawn around the strengths of a single red variety, which is unusual for an American appellation. Which variety?", "opts": ["Pinot Noir", "Cabernet Sauvignon", "Syrah", "Grenache"], "a": 2, "exp": "Ballard Canyon runs north to south across the middle of the valley, between the cold western end and the hot eastern one, and the grape ripens there without either losing acidity or staying green. No AVA can legally restrict what is planted inside it, so the focus is a matter of grower agreement and reputation rather than of rule."},
{"id": "c-pxed64rs", "cat": "California", "q": "Planted in 1973, a single Santa Maria Valley vineyard supplies so many producers that its name turns up on labels from all over the state. Name it.", "sa": 1, "accept": ["bien nacido", "bien nacido vineyard", "bien nacido in santa maria valley"], "ans": "Bien Nacido", "exp": "Selling fruit rather than making wine is the whole point of the place, and a vineyard designation of that kind obliges the buyer to take 95 percent of the wine from the named site. The valley is among the coldest growing areas in the state, so the fruit comes in late and with high natural acidity whoever ferments it."},
{"id": "c-pwhjfdlv", "cat": "California", "q": "Santa Ynez is not the only Santa Barbara valley running east to west toward the ocean. Name the northernmost of them.", "sa": 1, "accept": ["santa maria valley", "santa maria", "santa maria valley ava", "santa maria valley appellation"], "ans": "Santa Maria Valley", "exp": "It opens onto the sea near Guadalupe, so the marine layer runs the full length of it with no ridge to stop it, and the Los Alamos Valley lies between it and Santa Ynez. Growing seasons there are among the longest anywhere in California, with fruit hanging into November in an ordinary year."},
{"id": "c-naibhkw2", "cat": "California", "q": "Amador County's best-known Zinfandel appellation had to qualify its name because a far better-known valley on the other side of the country carries the same one. What is the Californian one called?", "opts": ["California Shenandoah Valley", "Fiddletown", "Shenandoah Valley of Virginia", "Fair Play"], "a": 0, "exp": "Two American viticultural areas may not carry the same bare name, and the two Shenandoah Valley petitions sat before the bureau at the same time in the early 1980s. The eastern valley was the nationally recognised name, so the western claimant took the state prefix rather than the other way about. The regulation gives the name as Shenandoah Valley qualified by the word California in direct conjunction with it, and the bureau lists and labels it with the state name leading. The valley sits around 1,500 to 2,000 feet on decomposed granite, and its Zinfandel runs broad, briary and high in alcohol, quite unlike the version grown on the Sonoma benchlands."},
{"id": "c-0e60g7jk", "cat": "California", "q": "Old Vine is printed on Zinfandel from Lodi and from the Sierra Foothills alike. What does that phrase oblige the producer to have done?", "opts": ["Use fruit only from vines growing on their own roots", "Nothing at all, since the phrase is not defined in law", "Use fruit only from vines at least twenty-five years old", "Use fruit only from vines at least fifty years old"], "a": 1, "exp": "There is no federal or state standard behind it, so it means whatever the producer decides, exactly as Reserve does. Estate Bottled, the appellation minimums and the varietal minimum are the American label terms that actually bind. Growers' private conventions vary wildly, some reserving the phrase for pre-Prohibition plantings and others applying it at thirty years."},
{"id": "c-7a5tz5tp", "cat": "California", "q": "Documented as planted in 1869, a block of Zinfandel in Amador County is generally reckoned the oldest of its variety still cropping in California. Name that vineyard.", "sa": 1, "accept": ["grandpere", "grand pere", "grandpere vineyard", "original grandpere vineyard"], "ans": "Grandpere", "exp": "The vines are head-trained, dry-farmed and on their own roots, and they crop a fraction of what a modern trellised block would. Vineyards of that age survive in the foothills because the granite sand they sit in is hostile to phylloxera and because nobody had a commercial reason to pull them out."},
{"id": "c-y5zirl5b", "cat": "California", "q": "Lodi is subdivided, and one of its sub-appellations on deep river sand holds nearly all of the region's century-old vines. Name it.", "sa": 1, "accept": ["mokelumne river", "mokelumne", "mokelumne river ava", "mokelumne river appellation"], "ans": "Mokelumne River", "exp": "The sand was laid down by the river and phylloxera cannot establish in it, so those plantings were never grafted over or torn out during the replanting that reshaped the North Coast. Most of the other Lodi sub-appellations run to heavier clay and to higher ground on the eastern side, though Cosumnes River in the northwest lies lower still on the delta floor and Jahant sits on its own pink loam north of the river."},
{"id": "c-zurfbxg7", "cat": "California", "q": "The rootstock that failed across Napa and Sonoma through the late 1980s had been recommended by the state's own university for decades. What was wrong with it?", "opts": ["It was a pure Vitis riparia selection with roots too shallow to anchor", "It was bred for lime tolerance and could not cope with acid soils", "It had been propagated from virus-infected material", "One of its parents was Vitis vinifera, which has no resistance"], "a": 3, "exp": "AXR number 1 crosses Aramon, a vinifera, with Vitis rupestris, and the vinifera half was always the weak point; a phylloxera biotype eventually found it. French growers had abandoned the cross long before on the same evidence. Rupestris St. George, the older Californian standard, carries no vinifera at all and came through untouched."},
{"id": "c-t8931nxl", "cat": "California", "q": "An Englishman running a wine shop and a wine school in Paris assembled the 1976 tasting that first set California in front of French judges. Name him.", "opts": ["Steven Spurrier", "Michael Broadbent", "Hugh Johnson", "Harry Waugh"], "a": 0, "exp": "He ran the Caves de la Madeleine and the Academie du Vin, put together a panel entirely of French judges who expected the French wines to win, and did not vote himself. A single American journalist happened to be in the room, which is the only reason the result was ever reported."},
{"id": "c-3f05rt5b", "cat": "California", "q": "Robert Mondavi and the proprietor of a Bordeaux First Growth founded a Napa estate together at the end of the 1970s, the first partnership of its kind between the two regions. Name that estate.", "sa": 1, "accept": ["opus one", "opus 1", "opus one winery", "opus one in oakville", "opus one napa"], "ans": "Opus One", "ex": 1, "exp": "The Bordeaux partner was Baron Philippe de Rothschild of Mouton Rothschild, and the wine was priced from the first vintage at a level no Californian bottle had attempted. It is usually read as the commercial consequence of the Paris result: European houses had started treating Napa as somewhere to invest rather than somewhere to dismiss."},
{"id": "c-qf060cmd", "cat": "Champagne", "q": "Verzenay and Verzy face north, away from the sun, and both sit at the top of the village ranking for Pinot Noir. What makes that aspect workable?", "opts": ["The wood on the plateau shelters them and cold air drains away downhill", "They are the lowest vineyards in the district, and the plain below them is the warmest ground in the region", "The river runs directly below and holds enough warmth overnight to finish the ripening", "The chalk lies bare at the surface there and throws back enough light to make up for the aspect"], "a": 0, "exp": "The forest crown on top of the plateau steadies temperature and humidity and takes the edge off the prevailing westerlies, and the slope falls away steeply enough that cold air drains down to the plain rather than settling on the vines. Ripening is slow and never excessive, which is exactly what a base wine wants: modest sugar with the acidity intact. The wines are correspondingly firm and slow to soften, and blenders buy them for structure rather than for charm."},
{"id": "c-kfzynt4g", "cat": "Champagne", "q": "South of the Cote des Blancs the same chalk seam reappears under a shorter run of slopes planted chiefly to Chardonnay, and the fruit off them arrives rounder and riper. Which district is this?", "opts": ["The Vallee de la Marne", "The Cote de Sezanne", "The Massif de Saint-Thierry", "The Cote des Bar"], "a": 1, "exp": "The Sezannaise slopes carry the Cote des Blancs chalk on southwest beyond the Marais de Saint-Gond, but they turn more to the southeast and lie under a deeper cover of clay and silt, so the Chardonnay comes in fatter and less austere. It is the district a blender reaches for when a cuvee wants flesh rather than tension."},
{"id": "c-7far413p", "cat": "Champagne", "q": "Meunier rules most of the Marne valley, but the short stretch either side of Epernay, from Cumieres and Hautvillers on the right bank east through Dizy, Ay and Mareuil-sur-Ay, is Pinot Noir country and is ranked far higher than the rest of it. What is that stretch called?", "sa": 1, "accept": ["grande vallee de la marne", "grande vallee", "grande vallee de la marne in champagne"], "ans": "Grande Vallee de la Marne", "ex": 1, "exp": "The valley narrows here, the slopes swing round to face south and the chalk comes close to the surface, so black grapes ripen properly instead of merely surviving. Houses buy from this stretch for the weight and the dark fruit it puts into a blend, and its villages sit at or near the top of the scale where the villages further downstream do not."},
{"id": "c-wxsm1xsb", "cat": "Champagne", "q": "A delimitation of 1908 drew the Champagne boundary and left one department outside it; growers rioted in 1911, and a law of 1927 brought that department back in. Name it.", "sa": 1, "accept": ["aube", "the aube department", "department of the aube", "l aube", "the aube region"], "ans": "The Aube", "ex": 1, "exp": "The excluded growers were a hundred kilometres south of the Marne heartland, and the disturbances of 1911 turned as much on merchants buying fruit from outside Champagne altogether as on where the line fell. The 1927 law fixed the outer limit commune by commune, and that boundary is essentially the one in force now."},
{"id": "c-oiyojahz", "cat": "Champagne", "q": "The percentage scale that once fixed what a grower was paid per kilogram no longer sets any price at all. What decides the price now?", "opts": ["The yield ceiling declared for the harvest, with the price rising as the permitted crop falls", "A single figure per kilogram published each spring by the trade body and binding on every village in the appellation", "Direct negotiation between the grower and the buyer, contract by contract", "The village rating, converted into a fixed sum per kilogram and revised whenever a village is promoted"], "a": 2, "exp": "The scale survived the loss of its job. Grand cru and premier cru still identify villages and still go on labels, but nothing is calculated from the percentages any more, and prices vary village by village and buyer by buyer. A fashionable grower's fruit can now cost several times what the old rating would ever have allowed."},
{"id": "c-huckacmd", "cat": "Champagne", "q": "A cuvee is drawn from two grand cru villages and one premier cru village, with nothing else in it at all. What rank may the label claim?", "opts": ["No rank at all", "Premier Cru, since every village in the blend holds at least that rank", "Grand Cru, provided the premier cru share is stated on the back label", "Grand Cru, because grand cru villages supply more of the blend than the premier cru village does"], "a": 1, "exp": "Grand Cru may be printed only when every grape came from a grand cru village; Premier Cru may be printed when every grape came from villages ranked premier cru or above. Grand cru fruit can therefore be blended down into a premier cru claim but never the other way, and a single load from an unranked village strips both words off the bottle."},
{"id": "c-qn30vltu", "cat": "Champagne", "q": "Seventeen villages sit at the very top of Champagne's ranking. How many others are ranked immediately below it and no higher?", "sa": 1, "accept": ["forty two", "42", "forty two villages", "42 villages", "forty two premiers crus", "42 premiers crus", "forty two premier crus", "42 premier crus", "forty two premier cru villages", "42 premier cru villages"], "ans": "Forty-two", "ex": 1, "exp": "Forty-two premier cru villages sit between the seventeen at the top and the couple of hundred communes carrying no rank whatever. Some references print forty-four instead, counting twice over the two villages that were rated at the top for one colour of grape and a notch lower for the other. The band is broad enough either way that the wines inside it vary enormously, which is why a premier cru name on its own tells a buyer far less than a grand cru one does."},
{"id": "c-46nsknan", "cat": "Champagne", "q": "Under the old percentage scale a couple of villages were rated at the full hundred for one colour of grape and a few points lower for the other. Name the Cote des Blancs village rated at the top for its Chardonnay alone.", "sa": 1, "accept": ["chouilly", "the village of chouilly", "chouilly in the cote des blancs", "chouilly grand cru", "grand cru chouilly", "chouilly grand cru for chardonnay"], "ans": "Chouilly", "ex": 1, "exp": "It stood at a hundred percent for white grapes and ninety-five for black, so under the scale its Chardonnay ranked at the top and its Pinot Noir did not. Tours-sur-Marne was the mirror case out in the valley, rated at the full hundred for black grapes only. Once the percentages stopped doing any work the distinction went with them: the cahier des charges now simply lists the seventeen communes entitled to grand cru, Chouilly and Tours-sur-Marne among them, without separating them by grape colour. The flat list of villages every student recites is the current legal position, and a simplification of the scale that produced it."},
{"id": "c-oyaji7c1", "cat": "Champagne", "q": "Between one pressing and the next the cake is cut down from the sides of the press and heaped back over the middle. What is that operation called?", "opts": ["Debourbage", "Foulage", "Retrousse", "Egrappage"], "a": 2, "exp": "The cake compacts against the walls and the juice stops finding a way out, so it is broken up and rebuilt before the pressure goes back on. Doing it well is what lets a shallow press take its full legal allowance out of a load without ever leaning on the fruit hard enough to draw colour or bitterness."},
{"id": "c-y4bqdzte", "cat": "Champagne", "q": "Pressing beyond the volume the appellation allows from a load of grapes still yields juice, but that juice may never become Champagne. Name the fraction.", "sa": 1, "accept": ["rebeche", "vin de rebeche", "rebeche fraction"], "ans": "Rebeche", "ex": 1, "exp": "It goes to the distillery, and the requirement exists to stop anyone squeezing the last hard, phenolic juice out of the cake and calling it wine. The producer has to declare it, so the rebeche doubles as the arithmetic proof that the legal yield was respected."},
{"id": "c-c3k3ijra", "cat": "Champagne", "q": "The traditional Champagne press is wide and shallow rather than tall, built to take one load of four thousand kilograms whole, so the juice runs off a thin cake and never sits under its own weight. Name that press.", "sa": 1, "accept": ["coquard", "coquard press", "pressoir coquard", "traditional coquard press", "vertical coquard press", "coquard vertical press"], "ans": "Coquard", "ex": 1, "exp": "A shallow bed means low pressure and a short run for the juice, which is how black grapes are pressed without picking up colour from their skins. Modern pneumatic presses are approved and do the same job on a horizontal axis, but the shape the yield regime was written around is this one."},
{"id": "c-m1adj2rg", "cat": "Champagne", "q": "A Blanc de Blancs house takes only the first-running juice from every load and sells the rest of its allowance on. Of the 2,550 litres permitted, how many litres is it selling?", "sa": 1, "accept": ["five hundred litres", "500 litres", "500", "five hundred", "500 l", "five hundred litres of taille", "500 litres of taille", "500 liters", "five hundred liters", "500l"], "ans": "Five hundred litres", "ex": 1, "exp": "The taille is the last five hundred litres of the allowance and is richer in potassium, pigment and phenolics and lower in acid, so it matures quickly and can coarsen a wine meant to last. Houses buy it cheaply and put it into non-vintage blends and rose, where the colour and the early roundness are useful rather than a liability."},
{"id": "c-zqkb1ppl", "cat": "Champagne", "q": "A generous harvest brings in more fruit than the trade has agreed to market that year. What may a grower do with the surplus, under a provision unusual in French appellation law?", "opts": ["Press it, make it into wine and lock it away in a personal reserve to be released in a short year", "Distil it and sell the spirit under the appellation name", "Sell it as base wine to a cremant producer outside the region", "Carry it forward as a credit against the following harvest's yield ceiling"], "a": 0, "exp": "The reserve individuelle is blocked stock: it cannot be sold until the trade body releases it, which happens after a frost or a rot year when the crop will not fill the demand. It is why Champagne rides out disasters that would wreck a region living harvest to harvest, and it sits alongside, rather than instead of, the reserve wines a house keeps for blending."},
{"id": "c-k6q9jh49", "cat": "Champagne", "q": "One house holds its reserve wines in stainless steel under inert gas; another keeps part of the stock in large old oak casks. What does the oak give the eventual blend?", "opts": ["A second malolactic conversion that a sealed steel tank cannot support", "Higher pressure at tirage, since wood-aged wine holds more dissolved gas", "Vanilla and toast drawn from the staves, which is why such casks are replaced every few vintages", "A slow trickle of oxygen through the wood, which broadens the texture"], "a": 3, "exp": "The casks are old and neutral, and the point is the permeability of the wood rather than any flavour left in it. Oxygen taken up slowly builds texture and steadies the wine against later oxidation, which is why oak-raised reserves are prized for cuvees meant to age. Steel under gas does the opposite job and keeps the wine tight and primary."},
{"id": "c-5e15oycm", "cat": "Champagne", "q": "In the new year the blending table faces a hundred or more lots of still wine, dry, thin and painfully sharp, none of it sparkling yet. What are those wines called?", "sa": 1, "accept": ["vins clairs", "vin clair", "les vins clairs"], "ans": "Vins clairs", "ex": 1, "exp": "One of them on its own is a hard drink and gives very little idea of the finished wine, so blending here is done substantially from experience of how a given village and a given vessel behave over time. The tasting runs for weeks, and the decisions taken at it are the most consequential a house makes all year."},
{"id": "c-n0wy1n3d", "cat": "Champagne", "q": "A grower keeps one vessel that is never emptied: every harvest tops it up and every blend draws from it, so a trace of all the years since it was started stays in the wine. Name that arrangement.", "sa": 1, "accept": ["reserve perpetuelle", "perpetual reserve", "perpetual reserve system"], "ans": "Reserve perpetuelle", "ex": 1, "exp": "It is a solera in everything but the name, and the older the vessel gets the less any single harvest can mark it. The trade-off is that the grower loses the ability to say what is in the blend year by year, and the stock can never be rebuilt from scratch if the vessel is emptied by accident."},
{"id": "c-ghgq460f", "cat": "Champagne", "q": "Two bottles of one cuvee are analysed a year apart and their sugar readings come out a gram or so apart, yet both carry the same sweetness term. What permits that?", "opts": ["A tolerance of three grams per litre between the declared term and the analysed figure", "Sugar is consumed slowly in bottle, and the rules read the figure at the moment of dosage", "The terms are set by each producer rather than by law", "Dosage is measured before disgorgement, so the figure on the label is always an estimate"], "a": 0, "exp": "European law lets the stated category sit within three grams per litre of the wine's actual sugar, which matters most at the boundaries: a wine analysed at thirteen grams can still go out as Brut. It also means the top of one category and the bottom of the next can be indistinguishable in the glass, and that the terms describe bands rather than recipes."},
{"id": "c-0tiv8602", "cat": "Champagne", "q": "Bottling for the second fermentation carries sugar into the bottle, and the amount is calculated to reach the pressure the finished wine has to hold. Roughly how much sugar per litre goes in?", "sa": 1, "accept": ["twenty four grams per litre", "24 grams per litre", "24 g/l", "24 grams", "twenty four grams", "24", "about 24 grams per litre", "roughly 24 grams per litre", "around 24 grams per litre", "approximately 24 grams per litre", "24 grams of sugar per litre", "about 24 g/l", "24 g per litre", "24g/l", "24 grams per liter", "twenty four grams per liter", "roughly twenty four grams per litre", "about 24", "roughly 24", "roughly 24 g/l", "around 24 g/l", "approximately 24 g/l", "about 24 grams", "roughly 24 grams", "around 24 grams", "24g per litre", "24 grams litre", "24 grams sugar per litre", "24 g/l of sugar", "around 24", "approximately 24"], "ans": "Twenty-four grams per litre", "ex": 1, "exp": "Around four grams per litre generates one further atmosphere, so twenty-four takes a bottle to roughly six. The same fermentation lifts the alcohol by a little over one percent and leaves the spent yeast behind as the deposit the wine will then spend years on."},
{"id": "c-fgcif6ll", "cat": "Champagne", "q": "A label reads Extra Brut. Give the band of residual sugar, in grams per litre, that the term permits.", "sa": 1, "accept": ["zero to six grams per litre", "0 to 6 grams per litre", "up to six grams per litre", "up to 6 grams per litre", "no more than six grams per litre", "no more than 6 grams per litre", "six grams per litre or less", "6 grams per litre or less", "0 to 6 g/l", "zero to six g/l", "0-6 g/l", "0-6 grams per litre", "0-6", "0 to 6", "zero to six", "up to 6 g/l", "6 g/l or less", "less than six grams per litre", "less than 6 grams per litre", "under six grams per litre", "under 6 grams per litre", "0 to 6 grams per liter", "zero to six grams per liter", "0-6 grams per liter", "between 0 and 6 grams per litre", "between zero and six grams per litre", "between 0 and 6 g/l", "0 to 6 grams", "zero to six grams"], "ans": "Zero to six grams per litre", "ex": 1, "exp": "Extra Brut sits between Brut Nature and Brut, and a wine at the top of the band is only marginally drier than a lightly dosed Brut. The category has grown because a well-ripened base wine no longer needs much sugar to be palatable, which was not true at all when the scale was written."},
{"id": "c-h8h5o277", "cat": "Champagne", "q": "Cane sugar dissolved in wine is the old way of sweetening a dosage. Name the colourless concentrated grape syrup that many houses now use in its place.", "sa": 1, "accept": ["rectified concentrated grape must", "rectified concentrated must", "concentrated rectified grape must", "mcr", "rectified concentrated grape must mcr", "mout de raisin concentre rectifie", "rcgm", "rectified concentrated grape must rcgm", "rectified grape must concentrate"], "ans": "Rectified concentrated grape must", "ex": 1, "exp": "Rectifying strips the must of colour, acid and aromatics and leaves essentially neutral grape sugar, so the addition sweetens without bringing anything else with it. A house that wants the dosage to bring something else goes the other way and uses an old reserve wine, sometimes held in cask for years expressly for the purpose."},
{"id": "c-khtjhh2j", "cat": "Champagne", "q": "A wine list describes three bottles as prestige cuvees. What does the appellation guarantee about them?", "opts": ["Nothing, since the term has no legal standing", "A declared vintage and riddling done entirely by hand", "Fruit from villages rated at the full hundred on the old percentage scale", "A minimum of six years on the lees and fruit drawn only from grand cru villages"], "a": 0, "exp": "Tete de cuvee and prestige cuvee are trade language for a house's flagship, and each house writes its own rules for what qualifies. In practice such wines are usually vintage-dated, long-aged and drawn from the best crus, but none of that is required and the words on their own promise a buyer nothing."},
{"id": "c-pw3yylcr", "cat": "Champagne", "q": "Even in an outstanding year a house may not turn its whole crop into vintage wine. How much of the harvest has to be held back?", "opts": ["None, provided the house declares its intention before the harvest is pressed", "At least twenty percent, which goes into reserve for non-vintage blending", "At least half, so that the non-vintage blend is never short of base wine", "Whatever the trade body fixes for that year, since the figure moves with the size of the crop"], "a": 1, "exp": "Vintage declaration is capped at eighty percent of a year's crop, so a fifth of even the finest harvest is set aside. The reasoning is commercial: non-vintage is the region's living, and a run of fine years in which every house declared everything would leave the blends starved of good reserve wine exactly when the next poor year arrived."},
{"id": "c-mw3i7er9", "cat": "Champagne", "q": "Champagne's ageing minima are counted in months, and the count begins neither at harvest nor at the end of the first fermentation. From what event does it run?", "sa": 1, "accept": ["tirage", "from tirage", "date of tirage", "at tirage", "from the date of tirage", "bottling for the second fermentation", "the second fermentation bottling", "when the wine is bottled for its second fermentation"], "ans": "Tirage", "ex": 1, "exp": "Fifteen months for a non-vintage and thirty-six for a vintage are both measured from the day the wine went into bottle with its sugar and yeast. That is also why a lot bottled late can hold up a release: the clock starts when the crown cap goes on, not when the fruit came in or when the blend was signed off."},
{"id": "c-xgpxxw4s", "cat": "Champagne", "q": "Side by side stand two bottles of one cuvee, one disgorged eight years ago and one last month. How will they differ?", "opts": ["The recent disgorgement will be the more evolved, having spent longer in the producer's cellar", "The older disgorgement will be the sweeter, because dosage sugar builds up with time in bottle", "They will taste alike, since ageing stops at disgorgement", "The older disgorgement will taste more evolved and nutty, the recent one tighter and more citric"], "a": 3, "exp": "Autolysis is protective and slow; once the lees are gone and oxygen begins to reach the wine past the cork, development speeds up sharply. The bottle disgorged last month spent those eight years under a crown cap on its own deposit, so it arrives at the table younger in character than its neighbour despite being identical on paper. That is the whole reason for printing the date."},
{"id": "c-2ewe55si", "cat": "Champagne", "q": "Under the crown cap sits a small plastic cup that gathers the deposit and comes away with the frozen plug at disgorgement. Name it.", "sa": 1, "accept": ["bidule", "bidule cup", "plastic bidule", "the plastic bidule cup", "bidule plastic cup"], "ans": "Bidule", "ex": 1, "exp": "The word is French for thingamajig, which is about the ceremony it commands, but it does a job the older closures did badly. The sediment settles inside the cup and leaves with it; without one it freezes against the glass and the neck has to be cleaned by hand before the wine can be dosed."},
{"id": "c-kjwfj8b6", "cat": "Champagne", "q": "A producer may buy bottles from another that have finished their second fermentation and are still lying on their lees, then disgorge, dose and label them as its own. Give the term for wine traded in that state.", "sa": 1, "accept": ["sur lattes", "sur latte", "sold sur lattes", "wine sold sur lattes", "bottles sold sur lattes"], "ans": "Sur lattes", "ex": 1, "exp": "The name comes from the wooden laths the bottles rest on while they age. Nothing on the finished label reveals it, which is why the trade dislikes the practice and why the negociant houses agreed among themselves to stop trading sur lattes with one another from 2004, leaving purchases from growers and cooperatives as what survives of it. It is still the usual explanation offered when a brand appears from nowhere in quantity."},
{"id": "c-72feoofy", "cat": "Champagne", "q": "A few houses still run the second fermentation under a natural cork rather than a crown cap, and that cork has to be clamped down against the pressure building beneath it. Name the metal clip that holds it.", "sa": 1, "accept": ["agrafe", "agraffe", "the agrafe clip", "agraffe clip", "agrafe staple", "agraffe staple"], "ans": "Agrafe", "ex": 1, "exp": "The clip is a sprung steel stirrup hooked under the lip of the bottle, and it was universal before the crown cap arrived and made the work quick. Running the second fermentation under cork is now a deliberate choice for a handful of prestige bottlings, argued for on the grounds that the wine takes in a trace of oxygen through the cork across its years on the lees."},
{"id": "c-1h4asld6", "cat": "Champagne", "q": "A merchant registered in Champagne buys wine already in bottle, never handling grape or must at any point, and labels it in its own name on its own premises. Which code appears in the small print?", "opts": ["MA, marque d'acheteur", "ND, negociant distributeur", "NM, negociant manipulant", "CM, cooperative de manipulation"], "a": 1, "exp": "A negociant distributeur is a merchant registered in the region that contributes nothing but the finishing and the label, put on its own premises onto bottles someone else made. The buyer's own brand code is the neighbouring case and a genuinely different one: there the name on the front belongs to an outside purchaser, typically a retailer or a restaurant, while the wine itself was made and labelled by a producer carrying a code of their own."},
{"id": "c-vi9dwzx2", "cat": "Champagne", "q": "A grower sends the whole crop to a cooperative, and the cooperative hands it back as finished bottles which the grower sells under their own name and village. Which code must appear?", "sa": 1, "accept": ["rc", "recoltant cooperateur", "rc recoltant cooperateur", "recoltant cooperateur rc"], "ans": "RC", "ex": 1, "exp": "Recoltant cooperateur. The label reads like a grower's wine and in one sense it is, since the fruit was theirs, but the wine was made in a communal cellar from a communal pool, and a neighbour's bottle may hold exactly the same liquid under a different name and a different village."},
{"id": "c-koxjpxv4", "cat": "Champagne", "q": "Several members of one family pool their vineyards into a company that presses, makes and sells the wine without joining any cooperative. Which code covers that arrangement?", "sa": 1, "accept": ["sr", "societe de recoltants", "sr societe de recoltants", "societe de recoltants sr"], "ans": "SR", "ex": 1, "exp": "Societe de recoltants. It exists because the grower codes assume an individual, and a family firm sharing presses and cellars across several separate holdings fits none of them. The wine is grower Champagne in substance, and this code is the only thing on the bottle that says so."},
{"id": "c-4sg0ohue", "cat": "Champagne", "q": "Still wine from the Champagne vineyard once went out under a name built on the word nature, dropped in 1974 as misleading. What replaced it?", "opts": ["Cremant de Champagne", "Vin de la Marne", "Bouzy Rouge", "Coteaux Champenois"], "a": 3, "exp": "The old name was Vin Nature de la Champagne, and nature had come to mean something quite different in wine talk. Coteaux Champenois covers still red, white and rose from the same delimited vineyard and the same varieties as the sparkling wine, and the reds are what anyone actually hunts for."},
{"id": "c-hwzq46uo", "cat": "Champagne", "q": "In one southern commune a still rose is made by bleeding Pinot Noir off its skins after a short maceration, declared only in years the grower judges good enough, and it holds an appellation of its own. Name that appellation.", "sa": 1, "accept": ["rose des riceys", "rose des riceys aoc", "the rose des riceys appellation", "still rose des riceys", "rose des riceys aop", "rose des riceys appellation d origine protegee"], "ans": "Rose des Riceys", "ex": 1, "exp": "The maceration is watched by eye and stopped the moment the winemaker judges the character has arrived, which is why the wine is not made every year and why quantities are tiny. It is one of the rare French appellations covering a rose alone, and the same vines can make sparkling wine or a still wine instead in a year that does not suit it."},
{"id": "c-qa42u81i", "cat": "Champagne", "q": "Before the region turned to sparkling wine its reputation rested on still wine, and one Montagne de Reims village supplied what seventeenth-century London bought under the village's own name. Name the village.", "sa": 1, "accept": ["sillery", "the village of sillery", "sillery in the montagne de reims", "sillery grand cru", "grand cru sillery"], "ans": "Sillery", "ex": 1, "exp": "It was a byword in London for the still wine of the region long before anyone there had seen a sparkling one, and the family that held the estate promoted it hard at court. The village is still ranked at the top of the scale, but what it sells now is fruit for other people's blends rather than a wine under its own name."},
{"id": "c-8m9lyct2", "cat": "Champagne", "q": "A Champagne grower's planting declaration lists a grey-berried mutation of Pinot Noir under a local synonym rather than under the name the rest of France uses. Which name?", "opts": ["Morillon", "Beaunois", "Fromenteau", "Auvernat"], "a": 2, "exp": "Fromenteau is what Champagne calls Pinot Gris, one of the seven principal varieties the appellation permits. Beaunois is what Chablis calls Chardonnay and Morillon is what Styria calls the same grape, so all of these are regional synonyms; only one of them belongs to this region."},
{"id": "c-j6p46gg1", "cat": "Champagne", "q": "A grower bottling all seven permitted varieties together needs a late-ripening white grape, once widespread in the south of the region and now down to a few hectares, with piercing acidity and a floral, almost herbal scent. Name it.", "sa": 1, "accept": ["arbane", "arbanne", "the arbane grape", "l arbane"], "ans": "Arbane", "ex": 1, "exp": "It ripens so late and crops so unreliably that it was very nearly abandoned, and the handful of growers who keep it do so partly as a museum piece and partly because it puts a nervy top note into a cuvee that nothing else supplies. Petit Meslier, Pinot Blanc and Pinot Gris are the other survivors alongside the famous three."},
{"id": "c-cp46sj3y", "cat": "Classifications & Labels", "q": "A grower resigns from the association whose pyramid ranked his best parcel, and from the next vintage that ranking may not appear on his label. Which kind of classification behaves that way?", "opts": ["One owned by a private association, where the right to print the rank comes with membership", "One enacted by decree, where the rank attaches to the estate itself", "One granted by a government agency after a petition to delimit a boundary, which the agency withdraws only for a breach of the rules", "One written into the production rules of the appellation, where the rank is a condition of the name rather than a benefit of belonging to anything"], "a": 0, "exp": "Membership and the ranking are the same thing in a private scheme, so the words leave with the grower. A rank granted by decree or written into an appellation's rulebook belongs to the estate or to the ground, and no falling out with the neighbours can take it away."},
{"id": "c-9dyi5iiy", "cat": "Classifications & Labels", "q": "Officials of the Prussian state ranked every vineyard along the Mosel in 1868, from the finest slopes down to the poorest, and no wine merchant had asked them to. What was that survey drawn up to do?", "sa": 1, "accept": ["assess land tax", "land tax", "assessing land tax", "taxation", "tax assessment", "to tax the land", "set the land tax", "land taxation", "property tax"], "ans": "Assess land tax", "exp": "The map priced ground for the revenue, so the best sites were taxed hardest and the ranking fell out of the arithmetic. It is still cited when a Mosel site's standing is argued over, which makes it the clearest case of a classification whose authority comes from having been written by people with no stake in wine at all."},
{"id": "c-ml1xzpzo", "cat": "Classifications & Labels", "q": "Italy gives every denomination a body that may police the use of the name, run its seal and put amendments to the ministry, and yet a grower inside the zone can decline to join it. What is such a body called?", "sa": 1, "accept": ["consorzio di tutela", "consorzio", "consorzi di tutela", "protection consortium", "consorzio tutela"], "ans": "A consorzio di tutela", "exp": "Membership is voluntary, so a consorzio speaks for the growers who joined it and its weight depends on how much of the zone that turns out to be. Its powers are delegated rather than inherent: policing the name, issuing the seal and proposing amendments are all done on the ministry's authority and can be withdrawn."},
{"id": "c-fepqp93c", "cat": "Classifications & Labels", "q": "Where a consortium speaks for a large enough majority of a denomination, the state can make its stricter rules bind every producer in the zone, members and refusers alike. What is that extension known as?", "sa": 1, "accept": ["erga omnes", "erga omnes extension", "erga omnes powers", "an erga omnes decree"], "ans": "Erga omnes", "exp": "Latin for towards everyone, and it is the only route by which a voluntary body ends up binding somebody who never signed anything. The threshold is deliberately high, because the alternative is a private club writing law for its competitors."},
{"id": "c-dxbnq3kp", "cat": "Classifications & Labels", "q": "Spain hands the boundary, the yields, the registers and the day-to-day policing of a denomination to a body of its own rather than to a national institute. Name it.", "sa": 1, "accept": ["consejo regulador", "consejo", "regulatory council", "regulating council", "regulatory board"], "ans": "The Consejo Regulador", "exp": "One body proposes the rulebook, keeps the registers and runs the inspections, which makes a Spanish denomination look far more self-contained than a French one. The separation between writing the rules and certifying against them is still there, because European law obliges the control and certification arm to be accredited like any outside certifier and to sit independently of the organs that manage the name, and some denominations hand the job to an external body altogether. The trade-off is the obvious one: the body writing the rules is drawn from the growers who have to live with them."},
{"id": "c-kriof090", "cat": "Classifications & Labels", "q": "For most of the last century the panel deciding whether a French wine could use its appellation was drawn from that appellation's own growers. Who carries out the check now?", "opts": ["Inspectors sent out by the European Commission", "The customs service, at the moment the wine leaves the cellar", "The growers' syndicate, exactly as before", "An independent inspection body, on an approved control plan"], "a": 3, "exp": "The work is done by an independent inspection or certification body, against a control plan the national institute has approved. Separating the people who write the rules from the people who verify compliance is the whole point of the reform, on the plain ground that no body can audit itself. Checks are also risk-based rather than universal, so an estate with a clean record is sampled less often than one that has been in trouble."},
{"id": "c-svh2dr24", "cat": "Classifications & Labels", "q": "A ranking adds a new tier above its old summit, and not one estate is demoted by a single word. What has happened to the estates that stood at the top?", "opts": ["They enter the new tier automatically for one review cycle, after which they must earn it at the next revision like anybody else", "They have been relegated in substance, since the rank they hold is no longer the highest available", "Their rank lapses until they apply for the new one, since a list that gains a tier has to be rebuilt from the applications upwards", "Nothing whatever, because a rank means what its own rulebook says and carries no comparison with anything above it"], "a": 1, "exp": "Adding at the top is the least confrontational way to revise a list, because nobody is demoted and so nobody has an obvious complaint to bring. It also devalues every rank beneath it, which is why a word that used to mean the best now has to be explained to a guest instead of simply read."},
{"id": "c-z6ui8i8q", "cat": "Classifications & Labels", "q": "Published in the spring, a new ranking names the harvest from which it takes effect. Where does that leave bottles of earlier vintages still in the trade?", "opts": ["They keep the ranking that was in force when they were made", "They lose all ranking, since only the current list has force", "The merchant may print whichever of the two rankings he prefers", "They must be relabelled before they can be sold on"], "a": 0, "exp": "A ranking bites on wine made after it takes effect, so a cellar can hold bottles ranked under three or four versions of one list at once. It also means a demotion costs an estate nothing on stock already in glass, which is why the argument is always about the vintages still to come."},
{"id": "c-uaee3v0y", "cat": "Classifications & Labels", "q": "Italy will not consider a wine for its highest denomination until it has served a stated minimum at the tier below. How long is that apprenticeship?", "sa": 1, "accept": ["ten years", "ten years as a doc", "ten years at doc level", "ten years at doc", "10 years", "10 years as a doc", "10 years at doc level", "10 years at doc", "at least ten years", "at least ten years as a doc", "at least ten years at doc level", "at least ten years at doc", "at least 10 years", "at least 10 years as a doc", "at least 10 years at doc level", "at least 10 years at doc", "minimum ten years", "minimum ten years as a doc", "minimum ten years at doc level", "minimum ten years at doc", "minimum 10 years", "minimum 10 years as a doc", "minimum 10 years at doc level", "minimum 10 years at doc", "ten years minimum", "ten years minimum as a doc", "ten years minimum at doc level", "ten years minimum at doc", "10 years minimum", "10 years minimum as a doc", "10 years minimum at doc level", "10 years minimum at doc", "ten", "10", "a decade", "ten full years", "at least a decade", "a decade at doc level", "a decade minimum"], "ans": "Ten years", "ex": 1, "exp": "The waiting period is what stops the top rank being handed to a name invented last season: the wine has to have existed, been made to a rulebook and been checked for a decade before anyone will look at it. The rung below works the same way on a shorter clock, so a new denomination climbs the ladder rather than stepping onto it halfway up."},
{"id": "c-139u3f4s", "cat": "Classifications & Labels", "q": "Every protected European name rests on one document setting out its boundary, its varieties, its yields and its methods, and amending an appellation means amending that document. What is it called?", "sa": 1, "accept": ["product specification", "cahier des charges", "specification", "product specification document", "disciplinare", "disciplinare di produzione", "pliego de condiciones", "technical file"], "ans": "The product specification", "exp": "Nothing about an appellation lives outside it, so the argument about a rule change is an argument about a paragraph, brought by the producer group and approved above them. Because the document is public, it is also the only honest way to answer what a name actually demands rather than what it is reputed to demand."},
{"id": "c-6fgvr417", "cat": "Classifications & Labels", "q": "A rulebook is tightened and a variety already in the ground is struck off the permitted list. Growers are rarely made to pull the vines up that same winter. What is the allowance called?", "sa": 1, "accept": ["transitional period", "transition period", "transitory period", "grandfathering", "grandfather clause", "phasing out period", "a period of transition", "grace period", "a period of grace", "transitional arrangement", "transitional measure"], "ans": "A transitional period", "exp": "A vine takes years to repay its planting, so a rule that bit immediately would confiscate the investment of everyone who had followed the old rules. The allowance is normally counted in vintages rather than years, and it is why a variety can appear in a wine for a decade after it stopped being permitted."},
{"id": "c-20rjgno5", "cat": "Classifications & Labels", "q": "Judging a candidate estate on one bottle would reward a single lucky year, so a classification tasting almost never does it. What does a candidate submit instead?", "sa": 1, "accept": ["run of consecutive vintages", "consecutive vintages", "several consecutive vintages", "a series of vintages", "run of vintages", "sequence of vintages", "successive vintages", "several vintages", "multiple vintages", "a number of vintages", "vintages in a row"], "ans": "A run of consecutive vintages", "exp": "A run catches the wet years and the hot ones, which is exactly the point: a rank is meant to describe what an estate does reliably rather than what it managed once. It also raises the cost of applying, since the estate has to have kept the wine, which quietly favours the established over the new."},
{"id": "c-ejjw2v4u", "cat": "Classifications & Labels", "q": "Demoted at a revision, an estate goes to court insisting its wine is plainly better than several that were promoted. What will the judges actually examine?", "opts": ["Whether the estate's sales have fallen since the revision", "Whether the decision was reached by the procedure the rules laid down", "Whether the wine tastes better than those ranked above it, on expert evidence", "Whether the classification body was entitled to exist at all"], "a": 1, "exp": "Courts review legality and not merit, so an argument about how good a wine is happens to be the one argument that cannot succeed. A judge asks whether the decision was properly made, which means the challenge has to be built out of the paperwork rather than out of the glass."},
{"id": "c-xkvnbwir", "cat": "Classifications & Labels", "q": "Suppose a court quashes the order that enacted a new ranking. Which list governs the following morning?", "opts": ["No ranking at all, until a fresh one is published, because quashing an order leaves the field empty instead of reviving anything", "The ranking the quashed one replaced, since an annulment wipes out the new list from the start", "The quashed ranking, until the legislature replaces it, since a court may criticise an order without stopping it from operating", "Whichever of the two rankings an estate prefers to print, the choice resting with the producer while the position is unsettled"], "a": 1, "exp": "An annulment works backwards rather than forwards: the act is treated as never having been made, so the earlier position revives of its own accord. That is what makes it so disruptive in trade, because labels, price lists and cartons all refer overnight to a rank that has ceased to exist."},
{"id": "c-yf2hdr09", "cat": "Classifications & Labels", "q": "Wine rankings are undone in court on procedure far more often than on substance, and one objection recurs above all others: somebody judging had a stake in the result. Name that objection.", "sa": 1, "accept": ["conflict of interest", "conflicts of interest", "bias", "apparent bias", "partiality", "an interest in the outcome"], "ans": "Conflict of interest", "exp": "The problem is structural rather than personal, because a small region has few people qualified to judge and most of them own or sell wine inside it. The usual answers are outside panellists, recusal and tasting under numbers, so that the judging can be shown to have been fair as well as being fair."},
{"id": "c-vkqvhwry", "cat": "Classifications & Labels", "q": "Not everybody who dislikes a ranking may challenge it; a claimant has to show that the decision actually affects him. What is that threshold requirement called?", "sa": 1, "accept": ["standing", "locus standi", "legal standing", "sufficient interest", "an interest in bringing the claim"], "ans": "Standing", "exp": "A merchant who merely sells the wine, or a neighbour who never applied, is usually turned away at that first hurdle however strong the complaint. It is why nearly every challenge comes from the estates immediately below a line, and why a revision that promotes without demoting is so rarely tested."},
{"id": "c-8za6pdph", "cat": "Classifications & Labels", "q": "Litigation runs for years while the estates promoted at a revision go on printing their new rank. What must a challenger win early to stop that happening in the meantime?", "sa": 1, "accept": ["suspension", "an interim suspension", "interim relief", "injunction", "an interim injunction", "a stay", "interim order"], "ans": "A suspension", "exp": "Without it the ranking stays in force throughout, and by the time judgment arrives the promoted wines have been sold under the new rank for several vintages. A judgment cannot unprint a label, which is the practical reason challengers go for the early order and settle for it when they get it."},
{"id": "c-anc2yar3", "cat": "Classifications & Labels", "q": "Refused a rank, a candidate is entitled to more than the bare result, and without it a challenge could never be framed at all. What must the body provide?", "sa": 1, "accept": ["reasons", "reasons for the decision", "a statement of reasons", "grounds for the decision", "written reasons"], "ans": "Its reasons", "exp": "A decision given without them is unreviewable, because there is nothing on the record for a court to test the outcome against. Bodies that resisted the duty generally lost, and the modern practice of returning a scored sheet to every candidate, successful or not, is the direct consequence."},
{"id": "c-5o523smd", "cat": "Classifications & Labels", "q": "Judging candidates against a standard that was never published leaves a ranking indefensible the moment anyone objects. What has to be in the open before the tasting begins?", "sa": 1, "accept": ["criteria", "the criteria for admission", "published criteria", "the standards to be applied", "the criteria and their weightings"], "ans": "The criteria", "exp": "Publishing them in advance is what converts a private opinion into a decision that can be defended, and it also disciplines the body, which cannot invent a requirement once it sees who applied. The weightings matter as much as the headings, because a scheme that scores reputation heavily will simply return the ranking it started with."},
{"id": "c-xwvn5ixy", "cat": "Classifications & Labels", "q": "Inside a classified zone sits a celebrated property carrying no rank whatever, and its wine outsells most of those that hold one. What is the likeliest explanation?", "opts": ["It was demoted at the last revision, and a demotion bars an estate from ever being considered again", "Its wines are sold outside the appellation system altogether", "It never entered, because a classification ranks the estates that applied to it", "Estates above a certain size are excluded by rule, a ranking being meant to reward small holdings"], "a": 2, "exp": "A classification is a list of candidates and not a survey of a region, so an estate that stays out simply does not appear and its absence proves nothing about the wine. Where entry costs money, opens the cellar to inspectors and risks a public demotion, a property that already sells everything it makes has a real calculation to run."},
{"id": "c-uj4jdmmb", "cat": "Classifications & Labels", "q": "Asked whether a grand cru from one country beats a grand cru from another, since both sit at the top of their ladders, what is the honest reply?", "opts": ["Yes, because European law sets one standard for the words", "No, because the term belongs in law to a single region", "Yes, because the top of any ladder means the same thing", "Neither, each was awarded by a different body's criteria"], "a": 3, "exp": "Each rank was awarded by a different authority against different criteria, so the two cannot be compared as ranks. A classification is a closed system: it orders the candidates on its own list against its own criteria and says nothing whatever about anything outside it. Shared words look like a common currency and are not one, so the first question at the table is which list a word came from and the second is what that list was measuring."},
{"id": "c-k29qfpw1", "cat": "Classifications & Labels", "q": "A rank is printed as an addition to something else on the label, and a wine that loses that other claim may not print its rank either. Which claim is it?", "sa": 1, "accept": ["appellation", "appellation of origin", "protected designation of origin", "denomination", "denomination of origin", "the protected name"], "ans": "The appellation", "exp": "A rank rides on a protected name rather than standing on its own, so it can only appear where the wine qualified for the name in that vintage. Anything declassified for any reason takes its rank down with it, which is why a classification has nothing to say about the wine an estate failed to get through the year's checks."},
{"id": "c-spias59e", "cat": "Classifications & Labels", "q": "A bottle reaches the shelf printing a rank its producer never held. Which body of law is reached for to punish that label?", "sa": 1, "accept": ["consumer protection law", "consumer protection", "consumer law", "trading standards law", "misleading practices law", "consumer protection rules", "unfair commercial practices", "false advertising", "misleading advertising"], "ans": "Consumer protection law", "exp": "A false rank is a misleading commercial claim, and it is pursued by whoever polices misleading claims in that market rather than by anyone in wine. The classification body's own sanction is narrower and slower, since all it can withdraw is the right to use its words in future."},
{"id": "c-t0vsimiz", "cat": "Classifications & Labels", "q": "A classification's boundary runs between rows of vines on ground that does not change at all across the line. Which lines did the mapmakers follow?", "sa": 1, "accept": ["land registry boundaries", "land registry", "cadastral boundaries", "cadastral lines", "property boundaries", "the existing parcel boundaries", "cadastre"], "ans": "The land registry boundaries", "exp": "A boundary has to be walkable and enforceable, so it follows parcels somebody already owns rather than a line a geologist would draw. It is the standard reason a classification looks arbitrary at its edges, and the standard defence is that a boundary a surveyor cannot mark is a boundary nobody can police."},
{"id": "c-esu9p1ai", "cat": "Classifications & Labels", "q": "One country's cru is a delimited parcel of ground, another's a whole village and a third's a business with a name and an address. What follows for anyone reading the word cold?", "opts": ["It is reliable for vineyards and unreliable for villages, since a parcel can be surveyed while a parish is too large to hold to any standard", "It means nothing at all outside France, every other country having borrowed the word as decoration rather than writing it into a rulebook", "It always means the same thing, being fixed for the whole union in European law, which sets one meaning for cru wherever it is printed", "It names a rank without saying what was ranked, so the system behind it has to be identified first"], "a": 3, "exp": "The unit is the entire content of the claim, so grand cru can mean four hectares of hillside in one glass and a whole parish in the next. Burgundy ranks ground and Beaujolais uses the word for whole appellations, while other systems rank villages or companies, and none of that is visible on the bottle."},
{"id": "c-gr6zed71", "cat": "Classifications & Labels", "q": "Premier cru and grand cru cross into English untranslated, and the noun they share began life as the past participle of a French verb. Rendered literally, what does that noun mean?", "sa": 1, "accept": ["growth", "grown", "what grew there", "the thing that grew", "growth in the sense of what grew there"], "ans": "Growth", "exp": "Cru is the past participle of croitre, to grow, so a cru is literally a growth: the thing that grew, and by extension the ground that grew it. English says it both ways without noticing, keeping the French noun in premier cru and translating that same noun in first growth. The word carries no rank of its own until a classification attaches one, which is why it turns up in systems that rank nothing at all."},
{"id": "c-eyt91ln8", "cat": "Classifications & Labels", "q": "Italian law lets one word stand in front of a vineyard name, and only where the plot is on the denomination's register and its fruit was vinified apart from everything else. Which word?", "sa": 1, "accept": ["vigna", "vigna followed by the vineyard name", "the word vigna", "vigna plus the plot name"], "ans": "Vigna", "exp": "The register and the separate vinification are the whole of the requirement, and nothing about the ground is assessed, so the word certifies provenance and bookkeeping rather than rank. Anyone reading it as an Italian grand cru has read a great deal more into it than the rulebook contains."},
{"id": "c-vlew38r1", "cat": "Classifications & Labels", "q": "Piedmontese growers keep a dialect word for the slope where the snow goes first, and it stands at the front of some of the most expensive vineyard names in Barbaresco. What is the word?", "sa": 1, "accept": ["sori", "sori slope", "sori in piedmont", "sori a south facing slope"], "ans": "Sori", "exp": "It names a south-facing pitch that thaws and ripens ahead of its neighbours, so the word does the work a cru name does anywhere else: this ground is not the ground beside it. Nothing in law ranks any of them, which is why the names were famous for a generation before any register existed to hold them."},
{"id": "c-ntpgcyei", "cat": "Classifications & Labels", "q": "Estates rather than vineyards were ranked by a decree of 1955 in a region that has never revised the list, and the number of holders has only ever fallen. Which region?", "sa": 1, "accept": ["provence", "cotes de provence", "provence in southern france"], "ans": "Provence", "exp": "A rank there attaches to the property as it stood in 1955 and does not survive it being broken up or absorbed, so holders drop off and none is ever added. It is the purest form of a closed list: no review, no promotion, no appeal, and a slow shrinking that nobody ever has to decide on."},
{"id": "c-r535wqbu", "cat": "Classifications & Labels", "q": "Ageing minimums are almost never counted from the day the wine was actually made. What do they run from instead?", "opts": ["A fixed calendar date following the harvest", "The day the wine is first offered for sale", "The day the wine was pressed off its skins", "The day the producer declares the wine finished"], "a": 0, "exp": "The date is written into the rulebook and is the same for every producer in the denomination. A fixed date is auditable: an inspector reads a bottling record against a calendar rather than establishing when fermentation stopped in each cellar. It also holds two wines of one harvest to the same clock though one was pressed a fortnight earlier, which is the only way a requirement can mean the same thing twice."},
{"id": "c-frc3yeq7", "cat": "Classifications & Labels", "q": "Beyond the length of the ageing and the vessel it happens in, a rulebook commonly fixes one more thing, and it is the one an importer's diary turns on. What is it?", "sa": 1, "accept": ["release date", "the earliest release date", "the date of release", "when the wine may be sold", "earliest date of sale", "the first day it may be sold"], "ans": "A release date", "exp": "Fixing the first day of sale brings a whole region to market at once, which is why a wine can be finished, bottled and still unavailable. It also gives the inspectors a single date to police instead of thousands of separate bottling records."},
{"id": "c-8ki9ylp6", "cat": "Classifications & Labels", "q": "Sold as twenty years old, a fortified wine carries a number that no ledger in the lodge could ever prove. Who decides whether the blend deserves it?", "sa": 1, "accept": ["tasting panel", "panel of tasters", "an official tasting panel", "a panel", "the chamber of tasters", "a tasting committee"], "ans": "A tasting panel", "exp": "The figure describes a style and an average rather than an audited fact, so it is settled by tasting against reference samples instead of by reading a cellar book. It is the one corner of wine law where an age claim rests on a palate, which is also why the categories jump in decades rather than in single years."},
{"id": "c-4cysi1tp", "cat": "Classifications & Labels", "q": "Spain fixes national minimums for its ageing words and lets a denomination demand more, which several do. How long must a red spend in oak to be sold as Gran Reserva under the national rule?", "sa": 1, "accept": ["eighteen months", "eighteen months in oak", "eighteen months in barrel", "eighteen months in cask", "eighteen months in wood", "18 months", "18 months in oak", "18 months in barrel", "18 months in cask", "18 months in wood", "at least eighteen months", "at least eighteen months in oak", "at least eighteen months in barrel", "at least eighteen months in cask", "at least eighteen months in wood", "at least 18 months", "at least 18 months in oak", "at least 18 months in barrel", "at least 18 months in cask", "at least 18 months in wood", "minimum eighteen months", "minimum eighteen months in oak", "minimum eighteen months in barrel", "minimum eighteen months in cask", "minimum eighteen months in wood", "minimum 18 months", "minimum 18 months in oak", "minimum 18 months in barrel", "minimum 18 months in cask", "minimum 18 months in wood", "eighteen months minimum", "eighteen months minimum in oak", "eighteen months minimum in barrel", "eighteen months minimum in cask", "eighteen months minimum in wood", "18 months minimum", "18 months minimum in oak", "18 months minimum in barrel", "18 months minimum in cask", "18 months minimum in wood", "eighteen", "18", "a year and a half", "one and a half years", "eighteen months in oak barrels", "18 months in oak barrels"], "ans": "Eighteen months", "ex": 1, "exp": "Sixty months in all, of which at least eighteen in wood and the rest largely in glass. Denominations that built their name on ageing set a longer clock than that, so the national figure describes the least a producer can have done and never what the serious ones actually do."},
{"id": "c-98bsicrk", "cat": "Classifications & Labels", "q": "An ageing minimum is worth exactly as much as the paperwork behind it. Which record does an inspector read to establish when a lot went into wood and when it came out?", "sa": 1, "accept": ["cellar register", "cellar records", "cellar book", "cellar ledger", "the cellar log", "movement records of the cellar", "cellar movement records", "records of the cellar", "register of the cellar", "winery records", "winery register"], "ans": "The cellar register", "exp": "Every movement of a lot is entered as it happens, so the requirement is tested against a document written months before anyone came to check it. It is the same principle that carries origin claims: nothing in the glass proves how long a wine sat in a barrel, and only the written record does."},
{"id": "c-altmfm8d", "cat": "Classifications & Labels", "q": "An ageing rule fixes how long and often where, and leaves untouched the one variable that changes a bottle more than either. What is it?", "sa": 1, "accept": ["temperature", "storage temperature", "the temperature of the cellar", "how warm the wine is kept", "cellar temperature", "the temperature it is stored at"], "ans": "The temperature it is kept at", "exp": "Two cellars can satisfy the same rule and hand a guest two different wines, because heat is what actually moves a wine along and no rulebook measures it. It is also why a bottle that met its minimum in a warm warehouse can taste older than one that spent twice as long somewhere cold."},
{"id": "c-ulcvpe4x", "cat": "Classifications & Labels", "q": "A guest holding a Spanish Reserva and a Californian Reserve asks whether the two words promise the same thing. What do you tell them?", "opts": ["The American word carries the longer requirement of the two, federal rules setting a floor in oak that the Spanish ladder never reaches", "Both carry the same minimum ageing, the term having been harmonised by treaty, so the word can be read once and applied to either bottle", "The Spanish word carries minimum times in cask and in bottle, and the American one carries no requirement at all", "Neither carries any requirement, both being marketing words a producer may print at will"], "a": 2, "exp": "Spain writes its ageing words into law and audits them, which is what lets a guest compare one bodega with another. In the United States the word is unregulated, so it is worth precisely what the producer's own reputation is worth, and on a few labels that is a great deal."},
{"id": "c-xw7vvhyn", "cat": "Classifications & Labels", "q": "Austria hangs its Reserve on a number that has nothing to do with time in cask. Which threshold must the wine reach?", "sa": 1, "accept": ["13%", "13% alcohol", "13% abv", "13 percent", "13 percent alcohol", "13 percent abv", "13 per cent", "13 per cent alcohol", "13 per cent abv", "thirteen percent", "thirteen percent alcohol", "thirteen percent abv", "thirteen per cent", "thirteen per cent alcohol", "thirteen per cent abv", "at least 13%", "at least 13% alcohol", "at least 13% abv", "at least 13 percent", "at least 13 percent alcohol", "at least 13 percent abv", "at least 13 per cent", "at least 13 per cent alcohol", "at least 13 per cent abv", "at least thirteen percent", "at least thirteen percent alcohol", "at least thirteen percent abv", "at least thirteen per cent", "at least thirteen per cent alcohol", "at least thirteen per cent abv", "minimum 13%", "minimum 13% alcohol", "minimum 13% abv", "minimum 13 percent", "minimum 13 percent alcohol", "minimum 13 percent abv", "minimum 13 per cent", "minimum 13 per cent alcohol", "minimum 13 per cent abv", "minimum thirteen percent", "minimum thirteen percent alcohol", "minimum thirteen percent abv", "minimum thirteen per cent", "minimum thirteen per cent alcohol", "minimum thirteen per cent abv", "13 %", "13 % alcohol", "13 % abv", "13", "thirteen", "13 abv", "thirteen abv", "13% alcohol by volume", "13 percent alcohol by volume", "13 per cent alcohol by volume", "thirteen percent alcohol by volume", "thirteen per cent alcohol by volume", "a minimum of 13%", "a minimum of 13 percent", "a minimum of 13% alcohol", "a minimum of 13 percent alcohol", "a minimum of thirteen percent", "a minimum of thirteen percent alcohol", "13% minimum", "13 percent minimum", "thirteen percent minimum", "13 percent alcohol minimum", "thirteen percent alcohol minimum"], "ans": "Thirteen percent alcohol", "ex": 1, "exp": "Reserve there is a ripeness claim, reachable on a good site in a warm year and out of reach in a cool one, which is the opposite of a rule counted in months. It comes with a later release than an ordinary Qualitatswein, and that is the only part of the definition resembling the ageing words used elsewhere."},
{"id": "c-xhh2lcm6", "cat": "Classifications & Labels", "q": "Reserve and Grande Reserve are legal ageing terms with fixed spells in cask and in bottle, and the country using them is not one usually taught for its ageing rules. Which country?", "sa": 1, "accept": ["greece", "greek", "greek wine law"], "ans": "Greece", "exp": "Both terms sit on top of a Greek protected designation and each demands a stated time in wood followed by a stated time in glass, with reds held longer than whites. The reserve family of words is legislated far more widely than the two or three systems usually taught, which is why the word alone settles nothing."},
{"id": "c-w580ac09", "cat": "Classifications & Labels", "q": "Riserva is a qualifier attached to a denomination rather than a word standing on its own, so the tier immediately below the denominations may never print it. Which tier is that?", "sa": 1, "accept": ["igt wines", "igt", "igp wines", "igp", "indicazione geografica tipica", "indicazione geografica protetta", "wines at igt level", "igt and igp wines", "igt tier", "igt level", "igt category", "igp tier"], "ans": "IGT wines", "exp": "The word is only available where a rulebook fixes what it demands, and the rules at that tier fix no ageing minimum for it to be stricter than. It is also why the same word can mean two years in one denomination and twice that in another: the number lives in each rulebook rather than in the word."},
{"id": "c-35imqkzm", "cat": "Classifications & Labels", "q": "Four months in barrel leaves a Spanish red short of the lowest rung of the ageing ladder, and the bodega still wants the oak mentioned on the label. Which word does it reach for?", "sa": 1, "accept": ["roble", "vino de roble", "the word roble"], "ans": "Roble", "exp": "Roble simply means oak, and the wine does have to have sat in oak vessels of no more than six hundred litres to carry the word, with chips and staves in a tank expressly ruled out. What no national rule fixes is how long, so four months and fourteen both read as roble unless the denomination has written a floor of its own. A guest who hears a junior rung of the crianza ladder in it has heard something that is not there."},
{"id": "c-fdn4uk2z", "cat": "Classifications & Labels", "q": "Estates falling just below the cut-off in a ranking lose far more than the difference in their wine would suggest. Why does that happen?", "opts": ["A ranking turns a continuous spread of quality into a few fixed steps", "Buyers are told which estates were nearly promoted and avoid them", "The rules oblige estates just below the line to be marked as such", "Estates near the line are inspected more often and pay higher levies"], "a": 0, "exp": "The steps are few and the spread is continuous, so a hair's difference lands on one side of a line. Any classification draws lines through a distribution that has none, and the wines either side of a line are always more alike than the ranks make them look. That is where the value on a list usually sits, in the bottle just under the cut-off, sold at the price of its rank rather than at the price of its quality."},
{"id": "c-6e9u6rip", "cat": "Classifications & Labels", "q": "Ranking ground is only enforceable because every planted parcel in the European Union sits on one compulsory record showing who farms it, what is planted and when it went in. Name that record.", "sa": 1, "accept": ["vineyard register", "vine register", "vineyard registry", "register of vineyards", "vineyard cadastre"], "ans": "The vineyard register", "exp": "Without it a claim about a parcel could not be checked at all, since the wine itself carries no evidence of which rows it came from. The register is also what makes a boundary change bite immediately: the parcel is either inside the line on the day of the harvest declaration or it is not."},
{"id": "c-lk9rs1ha", "cat": "Classifications & Labels", "q": "Somewhere with no delimited wine-growing area at all decides to rank its best sites. What has to be settled before any ranking can mean anything?", "sa": 1, "accept": ["delimitation", "delimitation of the area", "delimiting the area", "delimitation of the zone", "delimiting the region", "drawing the boundary first", "delimit the area", "the area must be delimited", "delimiting the vineyard area", "~delimiting the growing area", "~delimiting the growing areas", "~the area has to be delimited", "the area has to be delimited first", "the zone has to be delimited first", "settling the delimitation"], "ans": "Delimitation of the area", "exp": "A rank is a statement about somewhere, so somewhere has to exist in law before anything inside it can be ranked. That order is why young regions spend a decade arguing over a boundary that looks obvious afterwards, and why the ranking, if it comes at all, arrives a generation later."},
{"id": "c-q6mic88o", "cat": "Classifications & Labels", "q": "Cava added a tier at the top in 2017 for wine off one delimited plot, vinified separately and held on its lees for at least three years. What is that tier called?", "sa": 1, "accept": ["cava de paraje calificado", "paraje calificado", "paraje calificado tier"], "ans": "Cava de Paraje Calificado", "exp": "The rank belongs to the plot rather than to the house, which is unusual in a denomination built on blending across half a country. It also requires the same producer to have farmed, pressed and bottled the wine, so it is a single-vineyard claim in the Burgundian sense rather than a longer-aged version of the wines beneath it."},
{"id": "c-40smcjmc", "cat": "Classifications & Labels", "q": "One Catalan denomination on slate built a Burgundian ladder of its own, climbing from the region through a named village to individually classified single vineyards. What is the village rung called?", "sa": 1, "accept": ["vi de vila", "vins de vila", "vi de vila priorat", "village wine vi de vila"], "ans": "Vi de Vila", "exp": "The rungs above it narrow to a named place and then to a classified single vineyard, so the ladder ranks ground rather than producers. Bierzo and Rioja wrote ground-based tiers of their own in 2017, so it is no longer the only Spanish scheme of the kind, but it remains the fullest. It was written by the denomination itself in deliberate imitation of Burgundy, and it is the clearest modern case of the cru idea being imported whole."},
{"id": "c-tj5cdi70", "cat": "Classifications & Labels", "q": "Vineyards were sorted into first, second and third class in a Hungarian region during the eighteenth century, generations before any French list did the same. Which region?", "sa": 1, "accept": ["tokaj", "tokaji", "tokaj hegyalja", "tokaj in hungary"], "ans": "Tokaj", "exp": "The survey graded the ground rather than the producers, and it was made for a crown that wanted to protect and to tax a valuable export. Its classes were carried into the region's later rules, which is why it is usually cited as the earliest vineyard classification still recognisable in its modern form."},
{"id": "c-dlcxb3u6", "cat": "Classifications & Labels", "q": "Four phrases turn up across a shelf of European bottles: Grand Cru Classe, Vieilles Vignes, Riserva and Cuvee. Which pair may anybody print without meeting any rule at all?", "opts": ["Grand Cru Classe and Cuvee", "Riserva and Vieilles Vignes", "Vieilles Vignes and Cuvee", "Grand Cru Classe and Riserva"], "a": 2, "exp": "Grand Cru Classe and Riserva are protected terms with rulebooks and inspectors behind them, and the other two are the producer's own prose: cuvee means a vatful, and old vines means whatever the estate thinks old is. The habit worth building is to sort every word on a label into those two piles before saying anything about the wine."},
{"id": "c-nzyna6l9", "cat": "Classifications & Labels", "q": "Two Spanish denominations have been promoted to the rung above DO in more than thirty years of the system, one writing the extra word in Castilian and the other in Catalan. Name them.", "sa": 1, "accept": ["rioja and priorat", "priorat and rioja", "rioja priorat", "priorat rioja", "rioja doca and priorat doq", "doca rioja and doq priorat", "priorat doq and rioja doca", "rioja calificada and priorat qualificada"], "ans": "Rioja and Priorat", "exp": "Rioja took the qualified rank first and Priorat followed a decade later, and nothing has joined them since, which is a fair measure of how rarely the top rung opens. The requirements reach past the wine into how the denomination polices its own members, so the promotion is as much about the body as about the bottles."},
{"id": "c-sfgb4fja", "cat": "Classifications & Labels", "q": "Leaving a Spanish denomination, every bottle carries a numbered label on its back, issued by the regulating body and counted against what the bodega declared. Name it.", "sa": 1, "accept": ["contraetiqueta", "contraetiquetas", "contra etiqueta", "contraetiqueta seal", "contraetiqueta back label"], "ans": "The contraetiqueta", "ex": 1, "exp": "Issuing the seals in a fixed quantity is how a denomination polices volume, because the number handed out cannot exceed what the registered vineyard could lawfully have produced. It also carries the ageing tier, so the claim on the front is matched by a strip on the back that the body itself printed. A plain etiqueta is any label at all, and it is the contra that makes this one the regulator's."},
{"id": "c-ntv1p7hw", "cat": "Classifications & Labels", "q": "Nothing in wine law stands behind a private ranking, and yet its owner can stop an outsider printing the same words. Which body of law does that work?", "sa": 1, "accept": ["trademark law", "trade mark law", "trademark", "trade mark registration", "law of trademarks", "intellectual property law"], "ans": "Trademark law", "exp": "A ranking that is not a law is a name, and a name is protected by registering it, which is why private schemes register their words and their emblems and go to court as brand owners rather than as appellations. It also shapes how they behave: an owner who tolerates a copy risks the mark going generic, so a private scheme has to police its words far more visibly than a state body ever does."},
{"id": "c-jx4x4uzk", "cat": "Classifications & Labels", "q": "Caught breaking the rules attached to a private association's top rank, a member faces the only real sanction such a body holds. What is it?", "sa": 1, "accept": ["expulsion", "expelled", "expelling the member", "expulsion from the association", "expelled from the association", "losing membership", "loss of membership", "removal from the association"], "ans": "Expulsion", "exp": "A private scheme cannot fine anybody and has no inspectorate with a statutory footing, so its whole leverage is the right to use the mark and the company of the other members. That is why such schemes are often stricter than the law on paper and slower than the law in practice, since throwing out a famous name is a public act with consequences in both directions."},
{"id": "c-94hoghba", "cat": "Food & Pairing", "q": "Name the two broad strategies for pairing, one matching like with like and the other setting them against each other.", "sa": 1, "accept": ["complement and contrast", "contrast and complement", "complementary and contrasting", "matching and contrasting"], "ans": "Complement and contrast", "exp": "Complement echoes a quality the dish already has; contrast supplies what it lacks. Most classic pairings are one or the other stated plainly."},
{"id": "c-36srm90k", "cat": "Food & Pairing", "q": "Before any question of flavour, which single structural quality should be matched between dish and wine?", "sa": 1, "accept": ["weight or body", "body or weight", "weight and body", "weight body", "body weight", "weighty", "body"], "ans": "Weight, or body", "exp": "A delicate wine disappears under a heavy dish and a heavy wine flattens a delicate one. Weight is the first filter and it settles most bad pairings before flavour is considered."},
{"id": "c-i9biur1c", "cat": "Food & Pairing", "q": "A dish's sweetness sets a floor for the wine. What follows from that?", "opts": ["The wine must be at least as sweet", "The wine should be drier, to cut the dish's sweetness", "A high-acid dry wine will balance the sweetness", "Sweetness in food has no bearing on the pairing"], "a": 0, "exp": "Sweeter food strips a wine of fruit and leaves acid and alcohol exposed. Matching or exceeding the dish's sweetness is the one near-inviolable rule of dessert pairing, and acidity is no substitute for it: a dry high-acid wine set against a sweet dish is left tasting sour rather than refreshing."},
{"id": "c-q7tsbnp9", "cat": "Food & Pairing", "q": "A dish high in acidity demands what of the wine, if the wine is not to taste flat?", "sa": 1, "accept": ["matching acidity", "equal or higher acidity", "more acid than the dish", "at least as much acidity"], "ans": "At least as much acidity", "exp": "Acid in the dish resets the palate and makes a lower-acid wine taste dull and flabby. Meeting it keeps the wine tasting fresh."},
{"id": "c-0nn04c75", "cat": "Food & Pairing", "q": "Which food element most reliably softens the perception of tannin?", "sa": 1, "accept": ["protein and fat", "fat and protein", "protein or fat", "fat or protein", "protein fat", "fat protein"], "ans": "Protein and fat", "ex": 1, "exp": "Tannin binds with protein, which is why a rare steak makes a young tannic red seem rounder. Fat coats the palate and blunts the same astringency."},
{"id": "c-tdrdgmjy", "cat": "Food & Pairing", "q": "Salt in a dish does what to a wine's perceived tannin and fruit?", "sa": 1, "accept": ["softens tannin and lifts fruit", "reduces tannin", "makes it seem fruitier", "tames tannin and brings out fruit"], "ans": "Softens tannin and lifts fruit", "exp": "Salt is the most reliably wine-friendly thing on a plate: it suppresses bitterness and astringency and makes fruit read more clearly."},
{"id": "c-hp7nhw5k", "cat": "Food & Pairing", "q": "Why is a high-alcohol wine a poor partner for a very spicy dish?", "opts": ["Alcohol amplifies the burn of capsaicin", "Alcohol has no effect on heat", "Alcohol numbs the palate before the chilli registers", "Alcohol coats the palate the way dairy fat does"], "a": 0, "exp": "Ethanol and capsaicin both stimulate the same heat receptors, so each intensifies the other. Lower alcohol and a little sugar are the way out. Alcohol neither numbs the palate nor coats it: it is the casein and fat in dairy that bind capsaicin and carry it off."},
{"id": "c-dmqcaws5", "cat": "Food & Pairing", "q": "Bitterness in the food and bitterness in the wine combine in what way?", "sa": 1, "accept": ["they amplify each other", "additive", "they add up", "increases bitterness"], "ans": "Additively, amplifying each other", "exp": "Unlike salt or acid, bitterness does not cancel. Two bitter elements compound, which is why radicchio or charred greens punish a tannic red."},
{"id": "c-cqyity5s", "cat": "Food & Pairing", "q": "Umami in a dish, with no salt to balance it, tends to do what to a red wine's tannin?", "sa": 1, "accept": ["makes it seem harder and more bitter", "makes tannin harsher", "harsher", "more bitter and drying", "accentuates tannin"], "ans": "Makes it seem harder and more bitter", "exp": "Glutamates push tannin toward bitterness and metal. Adding salt to the dish is often the quickest repair to a pairing failing this way."},
{"id": "c-6anbexh9", "cat": "Food & Pairing", "q": "Identified in Japan and associated with glutamates, which taste makes wine pairing hardest?", "sa": 1, "accept": ["umami taste", "umaminess"], "ans": "Umami", "exp": "Umami is the savoury depth in mushroom, aged cheese, cured fish, tomato and stock. It is the least wine-friendly of the basic tastes."},
{"id": "c-a9jtg4si", "cat": "Food & Pairing", "q": "A dessert sweeter than the wine served with it produces which effect?", "opts": ["The wine tastes sweeter, since the sugar carries across", "The wine tastes thin and sour", "No perceptible change", "The wine's fruit is lifted, as a salty dish would lift it"], "a": 1, "exp": "Relative sweetness governs the perception. Out-sweetened, a wine loses its fruit and shows only acid and alcohol. Salt on the plate lifts fruit; sugar on the plate strips it, and none of the dish's sweetness transfers to the glass."},
{"id": "c-7ky9wsxh", "cat": "Food & Pairing", "q": "Which two food tastes are broadly wine-friendly, tending to make most wines taste better?", "sa": 1, "accept": ["salt and acid", "acid and salt", "salt and acidity", "saltiness and acidity"], "ans": "Salt and acid", "exp": "Both suppress bitterness and lift fruit. It is why a squeeze of lemon or a pinch of salt can rescue a pairing that seemed wrong."},
{"id": "c-n8s2e49m", "cat": "Food & Pairing", "q": "Which two food tastes are broadly wine-hostile?", "sa": 1, "accept": ["sweetness and umami", "umami and sweetness", "sweet and umami", "sugar and umami"], "ans": "Sweetness and umami", "exp": "Each strips fruit and exposes structure. Both can be managed, sweetness by matching it and umami usually by adding salt."},
{"id": "c-ft0o9d72", "cat": "Food & Pairing", "q": "Fat in a dish invites which two possible responses in the wine?", "sa": 1, "accept": ["acidity to cut it, or tannin to scour it", "acidity or tannin", "tannin or acidity", "acid or tannin", "high acid or firm tannin"], "ans": "Acidity to cut it, or tannin to scour it", "exp": "Two routes to the same end. Acidity refreshes the palate between bites; tannin binds the fat and clears it."},
{"id": "c-r26oeq5o", "cat": "Food & Pairing", "q": "How does residual sugar in a wine interact with chilli heat?", "opts": ["Sugar has no effect on perceived heat", "Sugar makes the dish taste saltier", "Sugar tempers the burn", "Sugar intensifies the burn the way alcohol does"], "a": 2, "exp": "A little sweetness is the standard counter to capsaicin, which is why off-dry aromatic whites are the reflex recommendation for spicy food. It is the alcohol in a wine that drives the burn upward, never the sugar."},
{"id": "c-6eypoycg", "cat": "Food & Pairing", "q": "Serving a red too cold does what to its tannin and bitterness?", "sa": 1, "accept": ["increases both", "increases tannin and bitterness", "makes them more prominent", "accentuates them"], "ans": "Increases both", "exp": "Cold hardens tannin and sharpens bitterness while muting aroma. An over-chilled red often reads as a bad pairing when it is only a service fault."},
{"id": "c-z0si1q7a", "cat": "Food & Pairing", "q": "Name the compound in artichoke that makes a wine tasted after it seem distortedly sweet.", "sa": 1, "accept": ["cynarin", "cynarine"], "ans": "Cynarin", "ex": 1, "exp": "Cynarin interferes with the sweet receptors, so the next sip reads sweeter than it is. It is the reason artichoke has a reputation as unpairable."},
{"id": "c-zmjltf8j", "cat": "Food & Pairing", "q": "Asparagus is difficult with wine because of which family of compounds, also prominent in Sauvignon Blanc?", "sa": 1, "accept": ["methoxypyrazines", "pyrazines", "methoxypyrazine"], "ans": "Methoxypyrazines", "exp": "The green, vegetal pyrazines in the vegetable meet the same compounds in the wine and compound each other. A herbaceous Sauvignon is the usual escape rather than the problem."},
{"id": "c-xtpeoejy", "cat": "Food & Pairing", "q": "Why is a sharply vinegar-dressed salad hard to pair?", "opts": ["It coats the palate in fat", "It is far too salty for any wine to carry", "It carries more tannin than most reds", "Acetic acid dominates and flattens the wine"], "a": 3, "exp": "Vinegar is volatile and aggressive in a way that ordinary food acid is not, and it dominates the palate so the wine after it tastes dull. Softening the dressing is a better fix than changing the wine."},
{"id": "c-wyt9rwrh", "cat": "Food & Pairing", "q": "Faced with a fiercely hot curry, which style of wine would you pour?", "sa": 1, "accept": ["off-dry, low-alcohol aromatic white", "off dry white", "low alcohol off dry white", "off dry aromatic white", "slightly sweet aromatic white"], "ans": "Off-dry, low-alcohol aromatic white", "exp": "Sugar tempers capsaicin and low alcohol avoids feeding it. Tannin and high alcohol are the two things to avoid outright."},
{"id": "c-i5db573l", "cat": "Food & Pairing", "q": "Oily fish such as mackerel with a heavily tannic red produces which specific fault?", "sa": 1, "accept": ["metallic taste", "metallic", "fishy metallic taste", "tinny"], "ans": "A metallic, fishy taste", "exp": "Iron in the wine reacting with the fish oils is the usual explanation. The effect is unmistakable and it is why the old white-with-fish rule persists."},
{"id": "c-6jsn5ubj", "cat": "Food & Pairing", "q": "Egg yolk is awkward with wine chiefly because of which property?", "sa": 1, "accept": ["coats the palate", "palate coating", "it coats the mouth", "coating texture"], "ans": "It coats the palate", "exp": "A coated palate blunts everything after it. Acidity and bubbles are the usual counter, which is much of why Champagne suits egg dishes."},
{"id": "c-495v2qxh", "cat": "Food & Pairing", "q": "Which fortified wine is the traditional partner for dark chocolate?", "sa": 1, "accept": ["ruby or lbv port", "ruby port", "lbv port", "late bottled vintage port", "ruby or late bottled vintage port", "port"], "ans": "Ruby or LBV Port", "ex": 1, "exp": "Chocolate's bitterness and fat need sweetness and body to stand against them. A young, fruit-forward Port has both."},
{"id": "c-fucu9t8h", "cat": "Food & Pairing", "q": "Duck confit and haricot beans bake for hours under a crust in the French southwest, and all that fat is what the local red was built for: its Tannat tannin has more grip than a lean dish could carry. Which appellation is being poured?", "sa": 1, "accept": ["madiran", "madiran aoc", "madiran aop", "madiran appellation"], "ans": "Madiran", "ex": 1, "exp": "Tannat is among the most tannic red varieties grown in France, and the protein in the confit and the sausage binds enough of that tannin, with the fat coating the palate against what is left, for the wine to read as generous rather than punishing. Pour the same bottle beside a lean grilled fish and the tannin finds nothing to bind to, which is why this pairing only makes sense in one direction."},
{"id": "c-lcwzurcx", "cat": "Food & Pairing", "q": "Which Loire white, especially when bottled sur lie, is the traditional match for oysters?", "sa": 1, "accept": ["muscadet", "muscadet sevre et maine", "muscadet sur lie"], "ans": "Muscadet", "ex": 1, "exp": "High acid, low alcohol, no oak and a faint saline lees character. It is close to a neutral frame around the oyster."},
{"id": "c-poy7dsky", "cat": "Food & Pairing", "q": "Sauternes with foie gras is chiefly an example of which strategy?", "opts": ["A deliberate mismatch of weight and intensity", "Complement, sweetness meeting richness", "Tannin binding with the liver's protein", "Contrast, a dry wine cutting the fat"], "a": 1, "exp": "The pairing works by matching opulence with opulence, the wine's sweetness and weight meeting the richness of the liver, with its acidity keeping the combination from cloying. Nothing here is dry and nothing here is tannic."},
{"id": "c-orsqw9zp", "cat": "Food & Pairing", "q": "Port and which English blue cheese make one of the classic sweet-and-salty pairings?", "sa": 1, "accept": ["stilton", "blue stilton", "stilton cheese"], "ans": "Stilton", "ex": 1, "exp": "Sweetness against salt and pungency, with enough body on both sides that neither is overwhelmed."},
{"id": "c-kreedxvu", "cat": "Food & Pairing", "q": "White truffle shaved over pasta in Piedmont is classically served with which local red?", "sa": 1, "accept": ["barolo or barbaresco", "barolo", "barbaresco", "nebbiolo"], "ans": "Barolo or Barbaresco", "exp": "Nebbiolo's perfume and savoury edge meet the truffle rather than competing with it, and the pairing is regional to the point of being local."},
{"id": "c-wc6x6xjp", "cat": "Food & Pairing", "q": "A tomato-based sauce demands high acidity. Which Tuscan red is the standard answer?", "sa": 1, "accept": ["chianti", "chianti classico", "chianti classico riserva", "sangiovese"], "ans": "Chianti", "ex": 1, "exp": "Tomato is acidic enough to flatten a soft red. Sangiovese meets it, which is why the pairing is a regional reflex."},
{"id": "c-qq07ci5e", "cat": "Food & Pairing", "q": "What makes Champagne so effective with fried food?", "opts": ["Its tannin binds the frying oil the way a red's would", "Acidity and bubbles cut through the fat", "Its low alcohol cools the palate", "Its sweetness balances the salt"], "a": 1, "exp": "Carbonation and acid together scour fat from the palate between mouthfuls, which resets it for the next bite. There is effectively no tannin in a Champagne to do the job a red's tannin would."},
{"id": "c-825hnfrv", "cat": "Food & Pairing", "q": "Aromatic Southeast Asian dishes are usually matched with which Alsace or German style?", "sa": 1, "accept": ["off dry riesling", "gewurztraminer", "riesling", "off dry gewurztraminer"], "ans": "Off-dry Riesling or Gewurztraminer", "exp": "Aromatic intensity to meet the dish, sweetness to handle chilli, and low alcohol so the heat is not amplified."},
{"id": "c-p0pk0hrf", "cat": "Food & Pairing", "q": "Muscadet, Chablis and Champagne share which structural feature that suits raw shellfish?", "sa": 1, "accept": ["high acidity with no oak", "high acidity and no oak", "high acidity no oak", "high acidity", "crisp unoaked acidity", "acid and no oak", "high acid and no oak"], "ans": "High acidity with no oak", "ex": 1, "exp": "Oak and shellfish rarely agree, and acidity does the work a squeeze of lemon would. The three wines differ in everything else."},
{"id": "c-dn5ujza9", "cat": "Food & Pairing", "q": "Why is white wine often a better partner for cheese than red?", "opts": ["White wine is generally sweeter than red", "Cheese contains no fat to speak of", "Red wine is always served too cold for cheese", "Acidity cuts fat where umami hardens tannin"], "a": 3, "exp": "The red-wine-with-cheese habit is largely convention. The umami of an aged cheese pushes tannin toward bitterness and dryness, while a white's acidity cuts the fat with nothing to harden."},
{"id": "c-eusfnlnf", "cat": "Food & Pairing", "q": "Blue cheese is classically paired with which category of wine?", "sa": 1, "accept": ["sweet wine", "sweet wines", "dessert wine", "sweet fortified wine"], "ans": "Sweet wine", "exp": "Sweetness balances the salt and the pungency. Sauternes with Roquefort and Port with Stilton are the same idea in two regions."},
{"id": "c-100giccw", "cat": "Food & Pairing", "q": "Which Burgundian washed-rind cheese is traditionally served with Marc de Bourgogne, the same spirit used to wash it?", "sa": 1, "accept": ["epoisses", "epoisses de bourgogne"], "ans": "Epoisses", "ex": 1, "exp": "Washed-rind cheeses are pungent enough to defeat most wine. Matching the cheese to the spirit it was washed in sidesteps the problem."},
{"id": "c-iuuwcez3", "cat": "Food & Pairing", "q": "Hard aged cheeses such as Comte suit which character in a wine particularly well?", "sa": 1, "accept": ["oxidative", "nutty oxidative wine", "oloroso", "vin jaune"], "ans": "Nutty, oxidative character", "exp": "The nuttiness of a long-aged cheese meets the nuttiness of an oxidatively aged wine. Vin Jaune with Comte is the regional case."},
{"id": "c-cqn1vrv8", "cat": "Food & Pairing", "q": "Goat cheese and Sauvignon Blanc succeed because both carry which pair of qualities?", "sa": 1, "accept": ["tanginess and a herbaceous, grassy note", "tanginess and grassiness", "acidity and herbaceousness", "tangy and grassy", "sharpness and green notes"], "ans": "Tanginess and a herbaceous, grassy note", "exp": "The pairing is complementary on both counts, which is why it survives outside its home region as well as within it."},
{"id": "c-6bk7r8s1", "cat": "Food & Pairing", "q": "Manchego alongside which fortified wine is a fixture of the tapas table?", "sa": 1, "accept": ["sherry", "manchego and sherry", "jerez", "dry sherry"], "ans": "Sherry", "ex": 1, "exp": "Fino for the younger cheese and Amontillado as it ages. Salt and nuttiness sit on both sides, and the wine's bite keeps the sheep's-milk richness from settling."},
{"id": "c-ggd2l4sd", "cat": "Food & Pairing", "q": "Serving a very salty cheese with a sweet wine is which strategy?", "sa": 1, "accept": ["contrasting", "by contrast", "opposition", "opposing"], "ans": "Contrast", "exp": "Neither element is echoed; each supplies what the other lacks. It is the most reliable route with strong cheeses."},
{"id": "c-3w72lm3h", "cat": "Food & Pairing", "q": "When a dish carries a dominant sauce, what should the wine be matched to?", "opts": ["The sauce", "The starch", "The garnish", "The protein"], "a": 0, "exp": "The sauce usually carries more flavour intensity than the protein under it. Match the loudest element on the plate."},
{"id": "c-07ppwrvn", "cat": "Food & Pairing", "q": "The same chicken poached and then grilled calls for different wines. Which variable changed?", "sa": 1, "accept": ["cooking method", "preparation", "the method of cooking", "how it was cooked"], "ans": "The cooking method, and with it weight and flavour intensity", "exp": "Protein alone is a poor guide. Method decides whether the dish is delicate or browned and assertive."},
{"id": "c-74gwvl2h", "cat": "Food & Pairing", "q": "Grilling and searing add which flavour dimension that suits oak-aged reds?", "sa": 1, "accept": ["char and browned maillard flavours", "char", "maillard", "maillard flavours", "char and maillard", "seared crust", "grill char", "char and browning"], "ans": "Char and browned, Maillard flavours", "ex": 1, "exp": "Browning creates the roasted, savoury compounds that echo barrel toast. It is why the same cut suits a different wine off the grill."},
{"id": "c-2weskw25", "cat": "Food & Pairing", "q": "A young tannic red with rare beef works partly through which chemical interaction?", "sa": 1, "accept": ["tannin binding with protein", "tannin binds protein", "tannin and protein bind", "tannin protein binding", "protein binds tannin"], "ans": "Tannin binding with protein", "exp": "The bound tannin is no longer available to grip the palate, so the wine reads softer and rounder than it would alone."},
{"id": "c-hy3t6w4w", "cat": "Food & Pairing", "q": "Smoked foods sit badly with heavily oaked wine for what reason?", "sa": 1, "accept": ["the smoke and the oak compound each other", "smoke and oak clash", "they compound", "oak amplifies the smoke", "too much smoke together"], "ans": "The smoke and the oak compound each other", "exp": "Two smoky elements do not balance, they accumulate. An unoaked or lightly oaked wine leaves room for the food's own smoke."},
{"id": "c-5mq8b5ev", "cat": "Food & Pairing", "q": "Poaching, steaming and raw preparations call for wines of what character?", "sa": 1, "accept": ["light-bodied, delicate and unoaked", "light and delicate", "light bodied and unoaked", "delicate unoaked wines", "lighter wines"], "ans": "Light-bodied, delicate and unoaked", "exp": "Nothing has been added by browning, so the dish stays quiet and the wine must too or it will bury it."},
{"id": "c-j2yqxbdw", "cat": "Food & Pairing", "q": "Which is most likely to leave a fine old red tasting stripped and hollow?", "opts": ["A hard aged cheese", "A plain roast joint", "A sweet chutney served alongside", "Lightly salted bread"], "a": 2, "exp": "Sweetness on the plate out-sweetens a dry mature wine and takes its fruit with it. The other three are neutral or helpful."},
{"id": "c-qri3motf", "cat": "Food & Pairing", "q": "Beyond vinegar, which common raw salad ingredient is a frequent wine-killer?", "sa": 1, "accept": ["raw onion", "onion", "raw garlic", "garlic"], "ans": "Raw onion, or strong raw garlic", "exp": "Both are pungent and sulphurous raw, and both flatten a wine. Cooking either one largely removes the problem."},
{"id": "c-ynn65g0f", "cat": "Food & Pairing", "q": "Mint sauce with lamb is difficult for which reason?", "sa": 1, "accept": ["menthol", "sharp acidity and mint", "vinegar and mint", "the mint and vinegar"], "ans": "Its sharp acidity and cooling menthol cut across the wine", "exp": "It is really a vinegar problem with a cooling aromatic on top. Redcurrant or a simple jus leaves the wine far more room."},
{"id": "c-eqit4zii", "cat": "Food & Pairing", "q": "Which treatment can turn a wine-hostile vegetable into a wine-friendly one?", "sa": 1, "accept": ["roasting", "roasting them", "charring", "browning them"], "ans": "Roasting, which adds sweetness and browning", "exp": "Roasting drives off water, concentrates sugar and browns the surface, moving the vegetable toward the wine rather than against it."},
{"id": "c-fmoxh80h", "cat": "Food & Pairing", "q": "A fiercely hot dish with a tannic, high-alcohol red fails because which two elements amplify each other?", "sa": 1, "accept": ["heat and alcohol", "capsaicin and alcohol", "chilli and alcohol", "heat and tannin"], "ans": "Capsaicin heat and alcohol", "exp": "Alcohol intensifies the burn and the burn sharpens the tannin. Every element is pulling the same wrong direction."},
{"id": "c-e9dvqht1", "cat": "Food & Pairing", "q": "A table of six has ordered six different dishes and wants one bottle. What is the soundest recommendation?", "opts": ["A heavily oaked white", "A sweet wine to cover everything", "A versatile, high-acid, low-tannin wine", "The most powerful red on the list, so it can stand up to anything"], "a": 2, "exp": "With no single dish to match, the goal shifts from best pairing to fewest collisions. Acid is friendly and tannin is not, so the biggest red on the list fights more of these dishes than it suits."},
{"id": "c-wirkdnvu", "cat": "Food & Pairing", "q": "When a guest's stated preference conflicts with the textbook pairing, which should prevail?", "sa": 1, "accept": ["the guest", "guest preference", "what the guest wants", "the guests wishes"], "ans": "The guest's preference", "exp": "Hospitality outranks theory. Offer the pairing once if invited, then pour what was asked for without further comment."},
{"id": "c-mzjqj1gp", "cat": "Food & Pairing", "q": "Across a tasting menu, how should the wines generally progress?", "opts": ["Heavier to lighter, while the palate is still fresh", "Sweeter to drier, so the meal finishes clean", "In no particular order", "Lighter to heavier, drier to sweeter"], "a": 3, "exp": "Each pour should not be diminished by the one before it. A big wine poured first flattens everything after it, and a sweet wine poured early leaves the dry wines that follow tasting sour. The same logic governs flights and comparative tastings."},
{"id": "c-1akg8lus", "cat": "Food & Pairing", "q": "Why is a by-the-glass programme built around food-friendly wines rather than distinctive ones?", "sa": 1, "accept": ["each glass has to work with many different dishes", "they must suit many dishes", "one wine many dishes", "it has to match anything", "each glass meets every dish"], "ans": "Each glass has to work with many different dishes", "exp": "A by-the-glass pour is ordered without knowing what it will meet. Breadth beats brilliance in that slot."},
{"id": "c-e2tug4zw", "cat": "Food & Pairing", "q": "A guest orders a big Cabernet with sole. What is the correct response?", "sa": 1, "accept": ["serve what they ordered", "give them what they asked for", "serve it graciously", "pour it and say nothing"], "ans": "Serve it graciously, offering an alternative only if invited", "exp": "Correcting a guest costs more than the pairing is worth. The exception is a fault in the bottle, which is a different conversation."},
{"id": "c-33w4o071", "cat": "Food & Pairing", "q": "When one wine must serve a table sharing many dishes, which attribute matters most?", "sa": 1, "accept": ["versatility", "versatile", "flexibility", "being versatile", "adaptability"], "ans": "Versatility", "ex": 1, "exp": "High acidity, moderate alcohol and restrained tannin or oak. The wine's job is to be unobjectionable everywhere rather than perfect once."},
{"id": "c-wgifeyxj", "cat": "Food & Pairing", "q": "Which service adjustment can rescue a red that is showing too tannic against the food?", "sa": 1, "accept": ["serve it cooler", "chill it slightly", "decant it", "lower the temperature"], "ans": "Serve it slightly cooler, or decant it", "exp": "Warmth exaggerates alcohol and cold hardens tannin, so the useful range is narrow. Air softens young tannin as well."},
{"id": "c-harod75j", "cat": "Food & Pairing", "q": "Pedro Ximenez Sherry is near-black, viscous and intensely sweet. What is it classically poured over?", "opts": ["Vanilla ice cream", "A dry water biscuit", "Raw oysters", "A citrus sorbet"], "a": 0, "exp": "At that concentration it behaves more like a sauce than a drink, and the cold cream keeps its raisined sweetness from becoming overwhelming."},
{"id": "c-gs56t1zp", "cat": "Food & Pairing", "q": "Which Sherry styles are the classic aperitif with olives, almonds and salted fish?", "sa": 1, "accept": ["fino or manzanilla", "fino", "manzanilla"], "ans": "Fino or Manzanilla", "exp": "Bone dry, saline and low in alcohol for a fortified wine. Salt on the plate and salt in the glass reinforce each other."},
{"id": "c-gp7qj8t4", "cat": "Food & Pairing", "q": "Melon with which style of sweet French fortified wine is a traditional first course?", "sa": 1, "accept": ["vin doux naturel", "muscat de beaumes de venise", "muscat"], "ans": "Vin doux naturel, such as Muscat de Beaumes-de-Venise", "exp": "Grapey sweetness against the melon's own perfume, at a weight that does not overwhelm a first course."},
{"id": "c-2y0ud35g", "cat": "Food & Pairing", "q": "Why does a dry sparkling wine struggle against a sweet dessert?", "sa": 1, "accept": ["the dessert leaves it tasting sour and thin", "it tastes sour", "tastes thin and acidic", "the wine seems sour", "it turns austere"], "ans": "The dessert leaves it tasting sour and thin", "exp": "Brut Champagne with wedding cake is the standard illustration of the rule being broken by convention."},
{"id": "c-tdjq973t", "cat": "Food & Pairing", "q": "A fruit tart, as opposed to a chocolate one, is the standard match for which category?", "sa": 1, "accept": ["botrytised sweet white", "late harvest white", "sauternes", "noble rot wine"], "ans": "A late-harvest or botrytised sweet white", "exp": "Fruit and acid on the plate meet fruit and acid in the glass. Chocolate's bitterness and fat instead call for something fortified."},
{"id": "c-zm47hoio", "cat": "Food & Pairing", "q": "Which wine component binds with salivary proteins to produce the drying grip that food fat relieves?", "sa": 1, "accept": ["tannins", "condensed tannin", "condensed tannins"], "ans": "Tannin", "exp": "Astringency is a tactile sensation rather than a taste: tannin stripping the lubricating proteins from saliva."},
{"id": "c-0id076ta", "cat": "Food & Pairing", "q": "Which structural element in white wine performs the palate-cleansing role that tannin plays in red?", "sa": 1, "accept": ["acidity", "acid", "high acidity", "high acid", "crisp acidity", "fresh acidity"], "ans": "Acidity", "ex": 1, "exp": "Both cut richness, by different mechanisms. It is why an unoaked high-acid white can handle food a soft red cannot."},
{"id": "c-a3et3lw0", "cat": "Food & Pairing", "q": "What is the term for flavours combining to an effect greater than either alone, for better or worse?", "sa": 1, "accept": ["synergy", "synergism", "synergistic effect", "synergistic"], "ans": "Synergy", "ex": 1, "exp": "Worth naming because it runs both ways: the best pairings and the worst are both synergies rather than simple sums."},
{"id": "c-uxxjvbc2", "cat": "Fortified Wines", "q": "Before a single grape is picked, a figure is fixed for how much must may be turned into Port across the whole valley that year. What is that figure set against?", "opts": ["The area under vine, at a fixed number of litres per hectare planted", "The stocks the trade already holds and what it sold last year", "The rainfall recorded between flowering and harvest", "The average must weight measured in the week before picking"], "a": 1, "exp": "The beneficio is a market control before it is a quality control: the authorities weigh the stock sitting in the lodges against what the trade has been selling, release only that much fortification, and then divide it among growers by the graded score of each parcel. Whatever is not licensed is fermented out dry and sold as unfortified Douro wine, which is why one vineyard feeds two entirely separate trades."},
{"id": "c-3hjzxb76", "cat": "Fortified Wines", "q": "Roughly one part spirit goes into four or five parts of fermenting must, and the distillate is bought at a strength the regulations fix rather than one the shipper prefers. Which strength?", "opts": ["Seventy-seven percent", "Forty percent", "Sixty percent", "Ninety-six percent"], "a": 0, "exp": "Aguardente vinica at that strength is deliberately not neutral. It carries congeners of its own, so the choice of spirit seasons the wine and is argued over in the trade as hotly as the fruit is. A spirit taken up to ninety-six, which is about as neutral as a spirit can be made, would add alcohol and nothing else, and that is what a producer wants when the grape is supposed to do all the talking."},
{"id": "c-dqa3jyr1", "cat": "Fortified Wines", "q": "Douro stocks, contracts and the annual fortification allowance are all counted in a traditional cask measure of five hundred and fifty litres. Name that measure.", "sa": 1, "accept": ["pipe", "pipa", "port pipe", "porto pipe", "pipe cask", "pipes", "pipe of port", "pipe or pipa", "pipa or pipe", "pipe 550 litres", "pipe of 550 litres", "550 litre pipe", "pipe pipa", "pipa 550 litres", "pipa of 550 litres", "550 litre pipa", "port pipe of 550 litres"], "ans": "The pipe", "ex": 1, "exp": "It works as a unit of account rather than as a description of any particular barrel, and the casks a lodge actually ages wine in vary around it. Holdings, licences and bottling runs are all quoted this way, so a shipper's entire position is described in a measure no drinker ever meets."},
{"id": "c-os9c4xfv", "cat": "Fortified Wines", "q": "However much stock a shipper is sitting on, only a set fraction of it may be released to the market in any one year. Give the fraction.", "sa": 1, "accept": ["one third", "third", "33 percent", "33 per cent", "33%", "1/3", "one third of stock", "one third of its stock", "one third of their stock", "one third of the total stock", "a third of the stock", "a third of their stock", "a third of the stock held", "one third each year", "a third each year", "one third a year", "one third per year", "one third of stock each year", "no more than one third", "up to one third", "a third per year", "up to a third", "no more than a third", "a third of its stock", "a third of his stock", "one third of the total", "one third of it", "one third annually", "one third of holdings", "one third of stock per year", "one third of the stock held"], "ans": "One third", "ex": 1, "exp": "The rule is a brake on the whole trade. It stops a run of fine harvests being dumped into the market at once, and it forces every house to carry reserves far deeper than a year's trading needs, which is the only reason a blend of genuinely old cask wine can exist at all. What is on sale this year was settled by a stock ledger years ago."},
{"id": "c-dls2idn5", "cat": "Fortified Wines", "q": "Whatever the style in the bottle, the finished wine has to land inside a narrow alcohol band written into the Port regulations. Give that band.", "sa": 1, "accept": ["nineteen to twenty two percent", "nineteen to twenty two per cent", "nineteen to twenty two", "between nineteen and twenty two percent", "nineteen to twenty two percent alcohol", "nineteen to twenty two percent abv", "19 to 22 percent", "19 to 22 per cent", "19 to 22", "between 19 and 22 percent", "between 19 and 22%", "19% to 22%", "19-22%", "19%-22%", "19-22 percent", "19 to 22%", "19 to 22 percent alcohol", "19 to 22% alcohol", "19 to 22 percent abv", "19 to 22% abv", "19-22", "19-22 percent abv", "19 to 22 abv", "between 19 and 22 percent abv", "between 19% and 22%", "from 19 to 22 percent", "19 and 22 percent", "19% abv to 22% abv", "19 to 22 percent by volume", "19 to 22 percent alcohol by volume", "nineteen and twenty two percent"], "ans": "Nineteen to twenty-two percent", "ex": 1, "exp": "A wine that ferments too far to take enough spirit, or takes too little, is simply not Port and has to be sold as something else. The one exception the rules make is for the light dry white, which may come in at sixteen and a half so that it can be poured long over ice without flooring a guest before dinner."},
{"id": "c-k395ruo0", "cat": "Fortified Wines", "q": "Two casks are filled from one lot of young Port; one goes down to a cool damp lodge on the estuary at Vila Nova de Gaia and the other stays in a store up the valley. Ten years on, how do they compare?", "opts": ["The Gaia cask has aged faster, since damp sea air drives oxygen through the wood", "Neither has moved, as a cask works on the wine only through the age of its own oak", "The valley cask has aged faster and given back far less wine", "The valley cask has aged more slowly, since dry heat seals the staves and keeps air out"], "a": 2, "exp": "Heat drives everything a cask does, and a Douro summer up the valley is far fiercer than one at the river mouth. Wine raised up the valley browns sooner, concentrates faster and loses far more to evaporation, while the estuary lodges are cool and humid enough to hold a wine for decades without cooking it. That is why the trade grew up at the river mouth in the first place, and why choosing where to lay a lot down is a decision about style rather than about storage."},
{"id": "c-gevq4ont", "cat": "Fortified Wines", "q": "Red colour drains out of a Port ageing in cask while a wine bottled at two years holds its own for decades. What is becoming of the pigment?", "opts": ["Heat bleaches it into a colourless compound", "Air polymerises it and it falls out as sediment in the cask", "The spirit dissolves it, and it is lost at the next racking", "The wood absorbs it into the staves, which is why old casks look stained"], "a": 1, "exp": "Oxygen reaching the wine through the wood links the colour molecules into chains too heavy to stay in solution, so they settle and are racked away, leaving an amber wine that has thrown its deposit before it ever reaches glass. A wine sealed in bottle at two years has no such supply of air, so it keeps its colour and its sediment for the customer to deal with. Both a tawny with an indication of age and a colheita go through this; what separates them is only whether the casks held one harvest or many."},
{"id": "c-25nlquu1", "cat": "Fortified Wines", "q": "A ruby, a tawny or a white judged by the tasting panel to stand clearly above the standard grade may add one word to its category name. Give the word.", "sa": 1, "accept": ["reserve", "reserva", "reserve or reserva", "reserva or reserve", "reserve reserva", "word reserve", "word reserva", "reserve port", "reserva port", "ruby reserve", "tawny reserve", "white reserve", "white reserva", "ruby reserva", "tawny reserva", "reserva reserve", "porto reserve", "reserve designation"], "ans": "Reserve", "ex": 1, "exp": "It is a quality claim rather than a stated age: the sample either passes the tasting panel or it does not, and a tawny carrying the word puts no number of years on the label, whatever spell in wood its own colour category demands before the claim is allowed. It occupies the step between the cheapest bottling and the wines that declare an age, which is where most of the trade in serious Port actually sits."},
{"id": "c-3sezgtjg", "cat": "Fortified Wines", "q": "One rare Port style spends a few years in wood and then many years in sealed glass demijohns rather than cask, so it develops with almost no air at all. Name the style.", "sa": 1, "accept": ["garrafeira", "garrafeira port", "port garrafeira", "garrafeira style"], "ans": "Garrafeira", "exp": "Glass gives up none of the oxygen wood does, so the wine stops taking on cask character and goes somewhere neither a bottle-aged nor a cask-aged Port arrives at, keeping fruit while turning silky. The rules ask for a spell in wood and then a long minimum in demijohn before the wine may be sold, and the two or three houses that still bother routinely leave it there for decades longer than that."},
{"id": "c-1npxknbt", "cat": "Fortified Wines", "q": "Casks from an outstanding harvest are tasted through the following winter, and a house that means to declare must give notice to the authorities inside a fixed window. When does that window fall?", "opts": ["In the fourth year, once the wine has passed three winters in wood", "In the harvest year itself, before the ferment has even been muted", "At bottling, whenever in the wine's life the house chooses to bottle", "In the second year after the harvest"], "a": 3, "exp": "Notice goes in during the second year and the wine must be in bottle before the third year is out, which is what makes a Vintage Port bottle-aged by definition rather than by anyone's choice. A house that declines to declare may still bottle a vintage-dated wine from one of its own properties, and those single quinta bottlings run to exactly the same calendar."},
{"id": "c-fu76anhu", "cat": "Fortified Wines", "q": "Two late bottled vintages of one year sit on the list, and the dearer of the two says unfiltered. What follows for the guest who orders it?", "opts": ["It will be paler, since filtration is what fixes colour in a young Port", "It will taste sweeter, since filtration takes sugar out along with the sediment", "It will throw a deposit, so it wants decanting, and it can still improve", "It must be drunk inside a year, since an unfiltered wine is unstable in glass"], "a": 2, "exp": "Filtration removes what would otherwise settle, and it removes the wine's capacity to go on developing with it, so a filtered LBV is finished on the day it is released while an unfiltered one behaves much more like a young vintage wine. Producers who bottle unfiltered say so on the label, sometimes as bottle matured, because the extra work at the table has to be justified to the buyer."},
{"id": "c-7x0sk231", "cat": "Fortified Wines", "q": "Several harvests are blended together, bottled without filtration and then given a long rest in glass before release. Which Port style is that?", "sa": 1, "accept": ["crusted port", "crusted", "crusted porto", "crusted ports"], "ans": "Crusted Port", "exp": "It is the only Port that blends years and still behaves like a vintage wine in the bottle, which is exactly what the name warns: it deposits. The style was invented by the British trade as a way of getting the character of a declared wine without the price or the wait, and the three years in glass are what the rules ask in place of a declaration."},
{"id": "c-4noc85ma", "cat": "Fortified Wines", "q": "A pink Port poured cold over ice is the newest thing in the category. Which description fits the way it is made?", "opts": ["A tawny is drawn off the cask before it has finished browning", "White Port is blended with a little ruby just before bottling", "A short maceration draws just enough colour, and the wine sees no wood at all", "The wine rests in old red casks until it takes up their pigment"], "a": 2, "exp": "Everything about it is aimed at colour and fruit rather than at development: brief skin contact, protection from air throughout, early bottling and no cask ageing whatever. It is the one Port the rules treat as a wine to be drunk on release and never laid down."},
{"id": "c-jogzc9nn", "cat": "Fortified Wines", "q": "At the sweet end of the white Port range sits a style whose name means tear. Name it.", "sa": 1, "accept": ["lagrima", "lagrima port", "porto lagrima", "lagrimas"], "ans": "Lagrima", "exp": "It carries well over a hundred grams of sugar a litre and is the one white Port that works as a dessert pour rather than long with tonic and ice. Drier whites are declared seco, and they get there by letting the ferment run further before the spirit goes in, which is the same lever that sets sweetness in every Port."},
{"id": "c-gpk6wbpk", "cat": "Fortified Wines", "q": "High on the plateau above the river at Favaios, growers fortify a Muscat that is not Port at all and carries a denomination of its own. Name that wine.", "sa": 1, "accept": ["moscatel do douro", "moscatel douro", "moscatel de favaios", "favaios moscatel", "moscatel of favaios", "douro moscatel", "moscatel do douro doc"], "ans": "Moscatel do Douro", "exp": "The grape is Moscatel Galego Branco, the small-berried aromatic Muscat, grown at around six hundred metres on the plateau rather than on the terraced valley slopes, and muted much as a Port is before ageing in wood. It is bottled both young and grapey and as an old cask wine, and it is the standing reminder that fortification in the Douro is not confined to the wine the valley is famous for."},
{"id": "c-s74kk5rg", "cat": "Fortified Wines", "q": "Casks in a Madeira lodge begin their life on the top floor under the roof and are moved down the building as the years pass. What is the reasoning?", "opts": ["Light through the roof windows is what drives the ageing", "The oldest casks are the heaviest and can no longer be lifted safely", "The roof space is the hottest part of the building, and heat drives the ageing", "The lower floors are damper, and the wine needs that moisture as it ages"], "a": 2, "exp": "Warmth is the engine of everything the island's wine does, so where a cask sits in the building is a decision about how fast it will develop. The youngest wine takes the strongest heat up under the roof and then matures more gently the further it descends. A lot may spend twenty years working its way down to the ground floor, and the lodge's own summer does all of it."},
{"id": "c-1wqv57fb", "cat": "Fortified Wines", "q": "Nothing may be bottled and sold as Madeira until it has served a minimum period of ageing. How long?", "opts": ["Three years", "Five years", "Ten years", "One year"], "a": 0, "exp": "That is a floor rather than an average, so a wine on the bottom rung may well hold older material blended into it without being allowed to say so. The ladder above climbs in fives and tens, and each step up it is a claim the certifying body has to approve before the label may carry it."},
{"id": "c-vg94coqx", "cat": "Fortified Wines", "q": "A blend that has come out drier than the house wants can be sweetened with must that was fortified before it ever fermented. Give the island's name for that sweetening wine.", "sa": 1, "accept": ["vinho surdo", "surdo", "surdo wine", "vinho surdo madeira"], "ans": "Vinho surdo", "exp": "Muting a must before the yeast touches it keeps every gram of its sugar, and what strength it has comes from the spirit rather than from fermentation, so a small dose lifts sweetness without watering the blend down. It is the ordinary tool for holding a house style steady from one harvest to the next, and something equivalent exists in every region that fortifies."},
{"id": "c-12b6o67e", "cat": "Fortified Wines", "q": "Certification of the island's wine sits with a public institute whose remit also covers embroidery and handicrafts. Give the initials it goes by.", "sa": 1, "accept": ["ivbam", "i.v.b.a.m.", "ivbam institute", "instituto do vinho do bordado e do artesanato da madeira"], "ans": "IVBAM", "exp": "Wine, embroidery and handicrafts are the island's three protected trades, its wickerwork among the last of them, and one body certifies all of it, so the seal on a bottle comes from the same office as the seal on a tablecloth. Nothing may leave the island as Madeira without passing through it."},
{"id": "c-59f97myv", "cat": "Fortified Wines", "q": "Printing a grape name on a Madeira label commits the producer to a minimum share of that variety in the bottle. What does the rule ask for?", "opts": ["Eighty-five percent from the named grape", "All of it, since no blending is allowed here", "Three quarters of it, and no less than that", "Half, with the balance from any permitted grape"], "a": 0, "exp": "Whatever makes up the balance is nearly always Tinta Negra, which can be vinified at any sweetness and disappears into a blend without argument. The threshold is why a wine sold under a variety and a wine sold under a sweetness term can start from very similar material and still taste unalike."},
{"id": "c-ltwj2ani", "cat": "Fortified Wines", "q": "A lodge sets aside a lot it hopes to sell one day with a harvest year on the label. Which ageing route must that wine have taken?", "opts": ["Either route, provided the wine is old enough by the time it is bottled", "Three months in the heated tanks, then cask", "Six months in a gently warmed store, then cask", "Cask on the lodge racks, with no artificial heat at any stage"], "a": 3, "exp": "Heated tanks are for the everyday blends and cannot produce anything worth keeping for decades, so colheita and frasqueira are both restricted to slow cask ageing in the lodge. What separates those two claims from each other is only the number of years demanded before bottling, and one of them asks for a great many more than the other."},
{"id": "c-v5wloo6x", "cat": "Fortified Wines", "q": "Sweetness on a Madeira label is declared in four steps rather than left to a grape name to imply. Give the step that sits one drier than doce.", "sa": 1, "accept": ["meio doce", "medium sweet", "medium rich", "meio doce medium sweet", "medium sweet meio doce", "meio doce medium rich", "medium rich meio doce", "meio doce or medium sweet", "medium sweet or meio doce", "meio doce or medium rich", "medium rich or meio doce", "meio doce step"], "ans": "Meio doce", "ex": 1, "exp": "The scale runs seco, meio seco, meio doce, doce, and English labels render those as dry, medium dry, medium rich and sweet. It matters because most of the island's wine comes from a variety that implies no sweetness at all, so the label has to say in words what a noble variety name once said by itself."},
{"id": "c-s311sjpv", "cat": "Fortified Wines", "q": "A Madeiran saying warns that its grapes should be neither eaten nor given away, since God made them for wine. The variety nearly died out with phylloxera, and its wines finish dry and faintly bitter after a sweet attack. Name it.", "sa": 1, "accept": ["terrantez", "terrantez madeira", "terrantez grape", "madeira terrantez"], "ans": "Terrantez", "exp": "It sits outside the four varieties the sweetness ladder was built around, and the surviving rows amount to very little, so old bottles fetch prices out of all proportion to their fame. The shape of the wine is its own: sweet at the front, then dry and gently bitter at the finish, which is precisely why it never fitted the ladder."},
{"id": "c-151ieccf", "cat": "Fortified Wines", "q": "One member of Madeira's noble set is a black grape, and the Jura bottles the same variety dry as Trousseau. Give its Madeiran name.", "sa": 1, "accept": ["bastardo", "bastardo madeira", "bastardo grape", "madeira bastardo"], "ans": "Bastardo", "exp": "It all but vanished from the island after phylloxera and survives in a handful of rows and in very old bottles. Mainland Portugal grows it too, in the Douro and the Dao, and its presence in the noble set is the reminder that those varieties were never all white."},
{"id": "c-fmpbu9ae", "cat": "Fortified Wines", "q": "At the top of the Marsala ageing ladder sits a wine that must spend longer in wood than anything else in the denomination. How long?", "opts": ["Four years", "Two years", "Twenty years", "Ten years"], "a": 3, "exp": "Vergine Stravecchio, also sold as Vergine Riserva, takes ten years where plain Vergine takes five, Superiore Riserva four, Superiore two and the entry grade one. The ladder is entirely a matter of time, most of which each step has to spend in wood, which is how one base wine can appear at four different points on the same list."},
{"id": "c-whjimf2a", "cat": "Fortified Wines", "q": "A Marsala label reads Rubino rather than Oro. Which grapes must have been in the vat?", "opts": ["Black varieties such as Perricone and Nero d'Avola", "Grillo and Catarratto, pressed off the skins at once", "White varieties darkened by many years in cask", "Any permitted variety, since the word records sweetness rather than colour"], "a": 0, "exp": "Oro and Ambra are both made from the island's white grapes, so no taster can separate those two by variety. Rubino is the only one of the three colour categories the fruit itself decides, and it is much the rarest of them on a list."},
{"id": "c-avekfzav", "cat": "Fortified Wines", "q": "One year of ageing is all the entry grade of Marsala has to serve, and its one-word name reads like praise. Name the grade.", "sa": 1, "accept": ["fine", "marsala fine", "fine marsala", "fine grade", "fine ip", "fine i p", "fine italia particolare", "italia particolare", "fine one year", "marsala fine ip", "marsala fine i p", "marsala fine italia particolare"], "ans": "Fine", "ex": 1, "exp": "Most of it is made to be cooked with rather than drunk, and that is the reputation the denomination has spent decades trying to shake off. The word is a grade and not a compliment, and everything above it on the ladder is defined by how many more years of ageing it has to serve before it may be sold."},
{"id": "c-numn85ze", "cat": "Fortified Wines", "q": "Colour and a burnt-sugar note in an amber Marsala come from a preparation of grape must reduced over heat. Give its Italian name.", "sa": 1, "accept": ["mosto cotto", "cooked must", "cooked grape must", "boiled must", "boiled grape must", "cooked down must", "mosto cotto cooked must", "cooked must mosto cotto", "mosto cotto boiled must", "boiled must mosto cotto", "mosto cotto or cooked must", "cooked must or mosto cotto", "mosto cotto or boiled must", "boiled must or mosto cotto", "il mosto cotto"], "ans": "Mosto cotto", "ex": 1, "exp": "It is must boiled down until it caramelises, and it goes in as one part of the concia, the blending preparation that also carries fortified must and spirit. Because it darkens and sweetens at once, colour and sweetness have to be declared separately on the label: the same wine can be adjusted for either."},
{"id": "c-9cagtgnf", "cat": "Fortified Wines", "q": "In a Banyuls cellar the spirit goes into the vat with the skins still in it, and the mass is left together for weeks afterwards. What is that buying?", "opts": ["A paler wine, since alcohol bleaches the pigment out of the skins", "Protection from oxygen, since the floating cap seals the surface of the vat", "A second fermentation, since the added spirit brings sugar of its own", "Colour and tannin, which the alcohol draws out of the skins"], "a": 3, "exp": "Fermentation here is stopped after two or three days, which is nowhere near long enough to build a red wine, so the extraction is done afterwards by the alcohol, which is a better solvent than must is. Muting off the skins instead gives a lighter and fruitier wine, and the same appellation uses both routes for different bottlings."},
{"id": "c-6cjpr3fb", "cat": "Fortified Wines", "q": "Leaving the Muscats aside, a Roussillon vin doux naturel draws its base only from a short list of varieties. Which set?", "opts": ["Cinsault and Grenache Gris only", "Grenache in its three colours, plus Macabeu and Malvoisie du Roussillon", "Syrah, Mourvedre and Carignan, exactly as in the dry reds made on the same hills", "Whatever the dry Cotes du Roussillon appellation permits"], "a": 1, "exp": "Grenache Noir carries the dark styles, Grenache Blanc and Gris and their two partners the pale ones, and Malvoisie du Roussillon is the local name for Tourbat rather than for any Malvasia. The list is short because these wines depend on a variety that will pile up sugar in a stony, drought-stricken vineyard and still taste of something."},
{"id": "c-u7r99bpo", "cat": "Fortified Wines", "q": "Adding Grand Cru to a Banyuls label commits the wine to a minimum spell in wood the plain appellation does not ask for. Give it.", "sa": 1, "accept": ["thirty months", "30 months", "thirty months in wood", "30 months in wood", "thirty months in cask", "30 months in cask", "thirty months in oak", "30 months in oak", "two and a half years", "two and a half years in wood", "2.5 years", "at least thirty months", "at least 30 months", "minimum of thirty months", "minimum thirty months", "minimum 30 months", "thirty months minimum", "30 months minimum", "at least thirty months in wood", "at least 30 months in wood", "at least 30 months in cask", "at least 30 months in oak", "minimum 30 months in wood", "minimum 30 months in cask", "minimum of 30 months", "minimum of 30 months in wood", "thirty months minimum in wood", "thirty months minimum in cask", "30 months minimum in wood", "30 months minimum in cask", "30 months in wood minimum", "30 months of cask ageing", "thirty months of cask ageing", "thirty months in barrel", "30 months in barrel", "at least two and a half years", "30 months two and a half years"], "ans": "Thirty months", "ex": 1, "exp": "The Grand Cru also demands a higher proportion of Grenache Noir than the ordinary appellation, so it is a rule about grape and time together. Those years in wood change the wine altogether: a Grand Cru tastes of dried fig and cocoa where a young bottling tastes of kirsch and crushed berry."},
{"id": "c-k0pd9df9", "cat": "Fortified Wines", "q": "A Rivesaltes or a Maury held five years or more before release may carry a phrase that says so without naming a number. Give the phrase.", "sa": 1, "accept": ["hors d'age", "hors dage", "hors d'age mention"], "ans": "Hors d'age", "exp": "It means beyond age, and it suits a producer who wants to claim maturity without committing to a vintage or to a stated count of years. It is one of several mentions the appellations regulate, Rancio and the colour terms among them, and each carries conditions of its own, so the words on these labels are not interchangeable."},
{"id": "c-ydml4xua", "cat": "Fortified Wines", "q": "A Charentais grower who wants to make Pineau des Charentes cannot simply buy in a case of brandy for the job. What does the rule demand?", "opts": ["Cognac and juice from the grower's own holding", "Neutral spirit at ninety-six percent, the same as a vin doux naturel takes", "Any Cognac bought inside the delimited region, from whichever house has it", "Armagnac of at least three years"], "a": 0, "exp": "Spirit and juice have to come off the same property, which makes Pineau a farm product in a way that very little fortified wine is. The Cognac must carry some age before it is used and the blend then spends time in cask, so a bottle represents two crops from one holding rather than a purchase."},
{"id": "c-xpy213of", "cat": "Fortified Wines", "q": "Walnut, coffee and old wood are welcomed in an old fortified wine and would condemn a table wine. What produces them?", "opts": ["Long, cold, airless storage in a deep cellar", "Air and heat together, working on the wine over years", "A film of living yeast sealing the surface away from the air", "Bacteria converting the malic acid in the wine into lactic acid"], "a": 1, "exp": "Warmth accelerates oxidation and the slow chemistry that follows it, so a part-empty cask in a hot loft does in five years what a cool cellar would not manage in fifty. Producers court it deliberately, leaving casks ullaged or standing glass jars outdoors through summer and winter, and the trade's name for the result is rancio."},
{"id": "c-r87lanuw", "cat": "Fortified Wines", "q": "In the Languedoc a grower mixes unfermented juice with grape spirit, often a local marc, and rests the result in wood. Name that drink.", "sa": 1, "accept": ["cartagene", "carthagene", "cartagene languedoc", "languedoc cartagene"], "ans": "Cartagene", "exp": "It belongs to the same family as Pineau des Charentes and Floc de Gascogne: spirit into juice that never ferments, so all the sweetness is grape sugar and all the alcohol came out of a still. It was a farmhouse tradition for generations before anyone regulated it, and most of it is still drunk within a few kilometres of where it was made."},
{"id": "c-xcjq5jlf", "cat": "Germany", "q": "Two German bottles from one estate, a village wine and a single-vineyard wine off the same hill, are ranked in that order by the law rewritten in 2021. Which principle puts them there?", "opts": ["The longer the wine is held back before release, the higher it ranks", "The smaller the holding that made it, the higher it ranks", "The riper the fruit was at picking, the higher the wine ranks", "The narrower the stated origin, the higher the wine ranks"], "a": 3, "exp": "The reform borrowed the Romance idea that a place, tightly drawn, is itself the quality claim, and set the steps as Anbaugebiet, then Region, then Ort, then Einzellage. Germany's older ladder measured sugar in the juice instead, so the two systems answer different questions and both still appear on labels."},
{"id": "c-65q5k9y3", "cat": "Germany", "q": "A label from the early 2000s carries a variety, a vintage and the single word Classic, and names no vineyard at all. What did that word commit the producer to?", "opts": ["A blend of at least three permitted varieties", "Fruit picked by hand from one delimited site, named on the label", "A single traditional variety of the region, in a dry style", "A wine held in cask for at least two years before it may be sold"], "a": 2, "exp": "Classic arrived in 2000 to give a dry wine one plain word a shopper could read, with the alcohol a point above the region's Qualitatswein minimum, the residual sugar capped at fifteen grams a litre and the vineyard name deliberately left off. That cap sits above what trocken itself allows, which is why the style is described as harmoniously dry rather than simply dry. It was never widely taken up: an estate that wanted to say dry simply wrote trocken, which everyone already understood."},
{"id": "c-gswwzvtb", "cat": "Germany", "q": "Under the reformed law the lower of the ranked classes of site has a protected term of its own for the dry wine grown there. Give that term.", "sa": 1, "accept": ["erstes gewachs", "erstes gewaechs", "the erstes gewachs term"], "ans": "Erstes Gewachs", "exp": "The Rheingau had run a legal version of this idea of its own since the late 1990s, and the reform generalised it to the whole country. Each region's producers' body decides which sites qualify and what the wine must do, so the bar behind the words is set locally rather than in Berlin, and the term above it is one a growers' association had used for decades before the law adopted it."},
{"id": "c-128jqd67", "cat": "Germany", "q": "One dry-wine term added to German law in 2000 demanded a hand harvest, a single named vineyard and fruit at Auslese ripeness, and almost nobody used it. Name that term.", "sa": 1, "accept": ["selection", "selection wine", "selection designation", "selection label term", "term selection", "selection term", "word selection"], "ans": "Selection", "ex": 1, "exp": "It asked for a yield well under the ordinary ceiling, a wine finished dry, and no release until the September after the harvest. That is a great deal of discipline in exchange for a word no drinker outside Germany recognised, and the estates capable of meeting it mostly had better-known words of their own to use."},
{"id": "c-puc66z63", "cat": "Germany", "q": "Below the single vineyard the reformed law admits a still smaller named parcel, a strip of ground a grower may now print underneath the vineyard name. What is that unit called?", "sa": 1, "accept": ["gewann", "gewanne", "gewann parcel", "gewann within an einzellage"], "ans": "Gewann", "exp": "A Gewann is a traditional field name inside an Einzellage, sometimes only a few rows across, and the wine has to come wholly from within it. It is the bottom rung of the origin pyramid and the narrowest claim a German label is allowed to make."},
{"id": "c-hgqig9js", "cat": "Germany", "q": "A Rheingau label carries a district name borrowed from one of the region's famous estates, and that district takes in every vineyard the region has. Which name is it?", "opts": ["Schloss Bockelheim", "Nierstein", "Johannisberg", "Bernkastel"], "a": 2, "exp": "The Rheingau is a single Bereich, so Bereich Johannisberg means the whole region rather than the ground around the estate whose name it took. Bernkastel and Nierstein are districts in the Mosel and in Rheinhessen, and both of those regions are cut into several. Schloss Bockelheim was one on the Nahe until 1993, when it was folded together with Kreuznach into a single district, Nahetal, so the Nahe now has exactly one as well."},
{"id": "c-6ncxet9w", "cat": "Germany", "q": "Schloss Vollrads and the Steinberg print no village name at all, though the ordinary Rheingau label must carry one. What is the legal status that allows it?", "sa": 1, "accept": ["ortsteil", "ortsteile", "ortsteil status", "recognised as an ortsteil"], "ans": "Ortsteil", "exp": "An Ortsteil is a recognised part of a municipality that may stand where the village name normally stands, so the estate or walled-site name does that work instead. It is why such bottles look nothing like the usual village-plus-vineyard construction, and why a reader cannot tell from them which commune the fruit grew in. The Rheingau recognises only a handful of them, Schloss Reichartshausen among the others. Schloss Reinhartshausen at Erbach is not one of them and prints its village like everybody else, which is how close two of those names run."},
{"id": "c-8uctdt8g", "cat": "Germany", "q": "Downstream of Zell the valley narrows and the vineyards have to be carried on dry-stone terraces rather than laid on open slate slopes, and growers there market under a name of their own. Give it.", "sa": 1, "accept": ["terrassenmosel", "terrassen mosel", "die terrassenmosel", "terrassenmosel in the lower mosel"], "ans": "Terrassenmosel", "ex": 1, "exp": "The stretch between Zell and Koblenz sits in the Bereich Burg Cochem, where the rock will not hold a continuous slope and every row stands on a wall somebody built. A wall knocked out by a hard winter has to be rebuilt by hand before anything can be pruned above it, and that cost is written into the price of every bottle the stretch sells."},
{"id": "c-tpehvwe6", "cat": "Germany", "q": "Faced with a site name on an older German label, a buyer cannot tell from the wording whether it belongs to one hillside or to forty villages. Which official register settles it?", "sa": 1, "accept": ["weinbergsrolle", "amtliche weinbergsrolle", "die weinbergsrolle"], "ans": "Weinbergsrolle", "exp": "Each federal state keeps the roll, and it records every delimited site and every collective name with its boundaries. Nothing in the label wording does that job, which is precisely the flaw the 2021 reform set out to close."},
{"id": "c-skvwj65n", "cat": "Germany", "q": "Zeller Schwarze Katz and Kroever Nacktarsch were shipped by the tanker for decades and read on a label exactly like a great single site. What kind of vineyard name is each of them?", "opts": ["A Grosslage, one name gathering the vineyards of many villages", "A shipper's brand with no vineyard behind it", "A Bereich, the district a region is divided into", "An Einzellage of unusually large area"], "a": 0, "exp": "A collective name can run across thousands of hectares and a dozen parishes, and the older label form gives a reader nothing whatever to tell it apart from a single site. Both of these gather in the ground around a Mosel village that had a memorable name and not a great deal of memorable vineyard."},
{"id": "c-o9ilai5q", "cat": "Germany", "q": "One Mosel collective name was the reverse of the usual complaint: it took in only a handful of the steepest sites around a single town, so the wine under it was reliably serious. Which name?", "opts": ["Graacher Munzlay", "Piesporter Michelsberg", "Bernkasteler Badstube", "Bernkasteler Kurfurstlay"], "a": 2, "exp": "Badstube covered the steep slate immediately around Bernkastel and behaved more like a village name than a regional blend, and in 2025 the growers there had it dissolved and the name remade as a single vineyard. Kurfurstlay wraps around it and reaches far up the valley and out onto the flat, and on a shelf the two looked identical in form."},
{"id": "c-5m22djzo", "cat": "Germany", "q": "The most notorious collective name in Rheinhessen borrows a celebrated river village's name for a blend drawn mostly from villages well inland of it. Name that collective site.", "sa": 1, "accept": ["niersteiner gutes domtal", "gutes domtal", "nierstein gutes domtal", "grosslage gutes domtal"], "ans": "Niersteiner Gutes Domtal", "exp": "The fruit may come from around fifteen parishes, most of them back from the river on gentle ground that grows nothing like the wine the name suggests. It became the standard cheap German white of the export trade, and it did as much harm to the reputation of the village it names as anything else in the century."},
{"id": "c-atmetus0", "cat": "Germany", "q": "When thousands of German vineyard names were struck off in 1971, a surviving single site had to clear a minimum area. What was that floor?", "sa": 1, "accept": ["five hectares", "5 hectares", "5 ha", "five ha", "5ha", "5 hectare", "five hectare", "at least five hectares", "at least 5 hectares", "at least 5 ha", "minimum of five hectares", "minimum of 5 hectares", "minimum of 5 ha", "minimum five hectares", "minimum 5 hectares", "minimum 5 ha", "five hectares or more", "5 hectares or more", "5 hectares minimum", "5 ha minimum", "five hectare minimum", "five hectares minimum"], "ans": "Five hectares", "ex": 1, "exp": "The floor was meant to make the map legible, and its side effect was to erase exactly the small distinctions the old names had recorded, since anything under it was absorbed into a neighbour. A handful of celebrated sites were let through beneath it, which is why one or two of the most expensive vineyards in Germany are also among the smallest."},
{"id": "c-qyzqzilv", "cat": "Germany", "q": "A VDP member's dry wines are named by where they came from, while one older vocabulary is held back for a different sort of wine altogether. What does the association reserve Kabinett, Spatlese and Auslese for?", "opts": ["Wines held back five years after the vintage", "Wines offered at the autumn auctions", "Wines from its top classified sites only", "Wines that keep noticeable residual sugar"], "a": 3, "exp": "Members label dry wine by origin - estate, then village, then the two classes of site - and keep the ripeness words for bottles where sugar survives into the glass, so the word is a promise about taste rather than about juice. German law asks for nothing of the sort, which is why a Spatlese trocken from a non-member is perfectly correct."},
{"id": "c-28idtqjw", "cat": "Germany", "q": "A member estate wants to bottle Sauvignon Blanc off its best classified parcel and is told the top tier is closed to it. What rule stops the wine?", "opts": ["The vines must have stood on that particular parcel for at least fifty years before the tier opens", "Classified sites admit only the varieties the association counts as traditional in that region", "The top tier is closed to any variety bred in a laboratory", "The top tier is open to Riesling alone, in every region of Germany"], "a": 1, "exp": "The permitted list changes from region to region: Riesling in the Rheingau, Silvaner in Franken, the Pinot family in Baden. A grower planting outside it keeps the vineyard's rank and loses the right to print it on that particular wine, which is the clearest way the rulebook is stricter than the law, since the law cares about ripeness and not at all about what is planted."},
{"id": "c-2nourok8", "cat": "Germany", "q": "Fruit for a VDP Grosse Lage wine must be picked by hand and cropped well below what German law would allow. What yield ceiling does the association set for that class?", "sa": 1, "accept": ["fifty hectolitres per hectare", "50 hectolitres per hectare", "50 hl/ha", "fifty hl/ha", "50 hl per ha", "fifty hl per ha", "fifty hectolitres a hectare", "50 hectolitres a hectare", "50 hectoliters per hectare", "fifty hectoliters per hectare", "50 hectoliters a hectare", "50 hectolitres", "fifty hectolitres", "50 hl", "fifty hl", "maximum of 50 hectolitres per hectare", "maximum of 50 hl/ha", "max 50 hl/ha", "50 hl/ha maximum", "50 hectolitres per hectare maximum", "50 hectolitres to the hectare", "no more than 50 hl/ha", "no more than 50 hectolitres per hectare"], "ans": "Fifty hectolitres per hectare", "ex": 1, "exp": "That is roughly half of what the law permits a Qualitatswein in most regions, and it comes bundled with the hand harvest and a stated minimum ripeness. The class below is allowed sixty, and the estate wine at the foot of the pyramid seventy-five."},
{"id": "c-snh4pk8v", "cat": "Germany", "q": "Before a dry wine may go out as Grosses Gewachs it has to reach a stated ripeness at picking, given as one of the rungs of the older ladder. Which rung?", "sa": 1, "accept": ["spatlese", "spaetlese", "spatlese ripeness", "spaetlese ripeness", "spatlese must weight", "spaetlese must weight", "at least spatlese", "at least spaetlese", "at least spatlese ripeness", "minimum spatlese", "minimum of spatlese", "spatlese minimum", "spatlese or higher", "spatlese or above", "spatlese level", "spatlese or more"], "ans": "Spatlese", "ex": 1, "exp": "The must weight behind that rung differs by region and by grape, so the requirement is a floor that moves rather than one figure on the Oechsle scale. It matters because the wine is dry: the sugar the rung records is fermented away, and what the estate has bought with it is ripeness of flavour."},
{"id": "c-dfm7v11n", "cat": "Germany", "q": "Leading German estates banded together in 1910 to sell wine at auction under a name that promised one thing about how it had been made. Which practice did that name rule out?", "sa": 1, "accept": ["chaptalisation", "chaptalization", "chaptalising", "chaptalizing", "adding sugar", "addition of sugar", "sugar addition", "beet sugar", "enrichment", "sugaring the must", "adding sugar to the must"], "ans": "Chaptalisation", "exp": "The founding name described its members as auctioneers of Naturwein, and the word then meant a wine that had reached its alcohol from the vineyard alone rather than from the sugar sack. The eagle on the capsule descends from that association, and the autumn auctions it was founded to run are still held."},
{"id": "c-pbsk7plo", "cat": "Germany", "q": "Between Bingen and Bonn the river runs through a gorge lined with castles, and the terraces above it are so steep that a great deal of the vineyard has gone out of production. Which Anbaugebiet is this?", "opts": ["Nahe", "Sachsen", "Ahr", "Mittelrhein"], "a": 3, "exp": "The Mittelrhein runs from the edge of Rheinhessen down past the Lorelei toward the Siebengebirge, and it is Riesling on slate almost throughout. It is the clearest case in Germany of a region whose vineyard keeps shrinking while the wine from what survives keeps improving."},
{"id": "c-u1r4o1x2", "cat": "Germany", "q": "The western end of Franken sits on red sandstone rather than on the shell limestone around Wurzburg, and it grows a surprising amount of Spatburgunder. Which of the region's districts is that?", "sa": 1, "accept": ["mainviereck", "main viereck", "bereich mainviereck", "mainviereck district"], "ans": "Mainviereck", "exp": "Mainviereck, the square of the Main, is the stretch around Miltenberg and Klingenberg where Buntsandstein comes to the surface. Maindreieck, the triangle, holds Wurzburg and its limestone, and Steigerwald further east sits on gypsum-bearing marl, so the region changes rock three times along one river."},
{"id": "c-salep8y5", "cat": "Germany", "q": "A Wurttemberg carafe wine is neither a rose nor a blend of finished wines: red and white grapes go into the fermenter together. What is that wine called?", "sa": 1, "accept": ["schillerwein", "schiller wein", "schillerwein rotling", "wurttemberg schillerwein"], "ans": "Schillerwein", "exp": "Fermenting the two colours together makes a Rotling, and Schillerwein is the Wurttemberg version of it, protected to that region and permitted only at Qualitatswein level or above. The name records the shifting colour rather than the poet, and Baden sells its own version of the idea as Badisch Rotgold."},
{"id": "c-ifrdxkfx", "cat": "Germany", "q": "Almond and apricot blossom opens early along an old road on the western flank of the Odenwald, and the vineyards strung along it make up one of the thirteen. Name that Anbaugebiet.", "sa": 1, "accept": ["hessische bergstrasse", "hessische bergstrasse anbaugebiet", "the hessische bergstrasse region"], "ans": "Hessische Bergstrasse", "exp": "The Bergstrasse is the old route at the foot of the Odenwald between Darmstadt and Heidelberg, sheltered from the west and among the mildest ground in the country. The Hessian stretch is an Anbaugebiet in its own right; the Baden stretch of the same road is only a district inside Baden, which is the trap the name sets."},
{"id": "c-9zlqr0vs", "cat": "Germany", "q": "Several Mosel sites carry Sonnenuhr in their names, and each has a real one built into the slope. Why were they put there?", "opts": ["So that workers on the hill could tell the time", "To measure how much sun the site takes in over a season", "To mark where one owner's parcel ended and the next began", "To display the owner's arms to the river"], "a": 0, "exp": "They went up in the nineteenth century for pickers and pruners who were a long walk from any church clock, and the wall carrying the dial is usually the warmest stone on the slope. The names then stuck to the ground around them, so Wehlen and Zeltingen each have a Sonnenuhr on the label as well as on the hill."},
{"id": "c-1d2dcj0w", "cat": "Germany", "q": "Erbach and Hattenheim spent much of the nineteenth century arguing over which of them could print the name of the vineyard around a boundary spring between them. Name the vineyard.", "sa": 1, "accept": ["marcobrunn", "erbacher marcobrunn", "markobrunn", "marcobrunner"], "ans": "Marcobrunn", "exp": "The Markbrunnen was a well on the line between the two villages, and Erbach won: the wine goes out as Erbacher Marcobrunn. The site is a narrow strip of deep, clay-rich ground close to the river, which is why it gives the broadest and slowest-developing wine in the village."},
{"id": "c-r4jj3ip7", "cat": "Germany", "q": "Above a single farmstead outside Wiltingen rises the slope most often called the finest ground on the Saar. Name the vineyard.", "sa": 1, "accept": ["scharzhofberg", "scharzhofberger", "der scharzhofberg", "scharzhofberg in the saar", "the scharzhofberg vineyard", "wiltinger scharzhofberg", "wiltinger scharzhofberger", "scharzhofberg wiltingen", "scharzhofberg in wiltingen", "scharzhofberg saar"], "ans": "Scharzhofberg", "ex": 1, "exp": "The Scharzhof stands below it and gives the site its name, and the vineyard is blue Devonian slate at an angle that makes every pass up it real work. Its wines were among the most expensive in the world before the First World War, and the reputation rests on the vintages where the Saar ripens fully, which it does not always manage."},
{"id": "c-4125cpmy", "cat": "Germany", "q": "A cliff of red slate shelters a sliver of vineyard barely above the water at Erden, and it is reckoned the warmest pocket on the Mosel. Name that site.", "sa": 1, "accept": ["erdener pralat", "pralat", "erdener praelat", "praelat"], "ans": "Erdener Pralat", "exp": "The Pralat lies at the foot of a sheer crag of red slate that throws the afternoon heat back onto a sliver of scree, and some of the vines standing in it are old and ungrafted. Treppchen, the little staircase, adjoins it along the same hillside and gives a firmer, later wine off cooler ground."},
{"id": "c-9ry03qut", "cat": "Germany", "q": "Opposite the village of Brauneberg the slope steepens around an old dial, and the block of ground about it is treated as the core of the much larger vineyard there. Name that block.", "sa": 1, "accept": ["juffer sonnenuhr", "brauneberger juffer sonnenuhr", "juffer sonnenuhr brauneberg", "brauneberger juffer sonnenuhr einzellage"], "ans": "Juffer-Sonnenuhr", "ex": 1, "exp": "The Juffer runs a long way along the hill, and the Juffer-Sonnenuhr is the steepest part of it, looking straight across the water at the village. A wine from the whole site and a wine from the block inside it are labelled almost identically, so the extra word carries the difference and is worth reading twice."},
{"id": "c-7c7v0n59", "cat": "Germany", "q": "One bottle on a by-the-glass list reads halbtrocken and the next feinherb, and a guest asks which of the pair is sweeter. What can be said with confidence?", "opts": ["Only that halbtrocken is capped by law and feinherb is not", "That halbtrocken is the sweeter, since it names a measured band", "That both sit inside the same statutory range, which the two words simply label differently", "That feinherb is the sweeter, since it is the softer-sounding word"], "a": 0, "exp": "Halbtrocken is capped by statute; feinherb was never defined at all, and an estate may hang it on anything from a whisper of sugar to a wine most drinkers would call sweet outright. So the honest answer is to taste them or to ask the estate, because the word describes house style rather than grams."},
{"id": "c-a0l06n23", "cat": "Germany", "q": "In September a German bakery sells cloudy, faintly sweet, barely alcoholic bottles under a loose cap, with a warning not to lay them down. What is in them?", "opts": ["A dry wine sweetened with juice held back from the harvest", "Must still in mid-fermentation, throwing carbon dioxide as it goes", "A light sparkling wine made in a sealed tank", "Wine drawn from the cask before filtration or fining"], "a": 1, "exp": "Federweisser is sold while the yeast is still working, which is why the cap has to vent and why the bottle will not travel or wait. It is drunk with onion tart within days of being filled, and the same liquid a fortnight later is simply young wine."},
{"id": "c-t2rf1xms", "cat": "Germany", "q": "Residual sugar on a German still wine climbs past forty-five grams a litre, so lieblich is no longer the term available. Which word takes over?", "sa": 1, "accept": ["suss", "suess", "suss sweet", "the word suss"], "ans": "Suss", "ex": 1, "exp": "German still wine runs trocken, halbtrocken, lieblich and suss, and the last of the four begins where lieblich stops. They are EU sweetness categories wearing German names, so an Italian dolce and a French doux start at exactly the same place."},
{"id": "c-ftwazdm6", "cat": "Germany", "q": "German law lets a Qualitatswein made wholly from Riesling, and picked appreciably riper than its region's minimum, add one further word to the label. Which word?", "sa": 1, "accept": ["hochgewachs", "hochgewaechs", "riesling hochgewachs", "hochgewachs riesling"], "ans": "Hochgewachs", "exp": "The wine has to beat the ordinary Qualitatswein must weight for its region by a set margin and score above a bare pass in the official tasting. It is a modest distinction dating from the 1980s that never carried abroad, and it turns up mostly on Mosel labels."},
{"id": "c-lpos1vck", "cat": "Germany", "q": "A bottle reads simply Sekt, with a German producer's address and no region named anywhere on it. What may the base wine be?", "opts": ["Wine from any of the thirteen German regions, blended together", "Wine from anywhere in the European Union", "Wine from one German region, which need not be named on the label", "Wine from German fruit alone, of a vintage the producer need not print"], "a": 1, "exp": "Sekt on its own is a category rather than an origin, and the base is very often bought elsewhere in Europe, tankered in and made sparkling on arrival. Deutscher Sekt is the tighter claim, demanding German fruit throughout, so the word standing in front of Sekt is where all the information sits."},
{"id": "c-tvm5ljyv", "cat": "Germany", "q": "Fruit for one class of German sparkling wine must come entirely from a single one of the thirteen regions, which then has to appear on the label. Give the name of that class.", "sa": 1, "accept": ["sekt bestimmter anbaugebiete", "sekt b.a.", "sekt ba", "bestimmter anbaugebiete sekt"], "ans": "Sekt bestimmter Anbaugebiete", "exp": "It ties a sparkling wine to one Anbaugebiet the way a still Qualitatswein is tied, and the region must be printed. It says nothing at all about method: such a wine may be tank-fermented, and a great deal of it is. Winzersekt is the tighter claim, demanding the grower's own fruit and a second fermentation in the bottle."},
{"id": "c-dqtamrx8", "cat": "Germany", "q": "A German bottle shows a light prickle rather than a mousse, sits well under the pressure a sparkling wine has to hold, and is often closed with a crown cap. Which category is it?", "sa": 1, "accept": ["perlwein", "perlwein semi sparkling", "perlwein category", "german perlwein"], "ans": "Perlwein", "exp": "Perlwein carries between one and two and a half bar against the three and a half a Sekt must reach, and much of it is made by dissolving carbon dioxide into a finished still wine rather than by a second fermentation. The lower pressure keeps it clear of the sparkling wine duty, which is a good deal of why the category persists."},
{"id": "c-7sxjjn90", "cat": "Germany", "q": "A crossing released from a German vine-breeding institute in the 1990s was taken up by organic growers above all, because it needs a fraction of the spraying its neighbours do. Which variety?", "opts": ["Regent", "Trollinger", "Portugieser", "Dornfelder"], "a": 0, "exp": "Regent came out of the institute at Geilweilerhof in the Pfalz, carrying American vine species well back in its pedigree, through the French-American hybrid Chambourcin, for resistance to mildew. It gives a deeply coloured, soft red, and it is the disease-resistant variety that got furthest in Germany before the newer generation of them arrived."},
{"id": "c-7qauqojg", "cat": "Germany", "q": "A Wurttemberg grower pours a pale, soft red and says it is the grape a Champagne house would call Meunier. What name does the German label use?", "sa": 1, "accept": ["schwarzriesling", "mullerrebe", "muellerrebe", "muller rebe", "schwarzriesling or mullerrebe", "schwarzriesling also called mullerrebe"], "ans": "Schwarzriesling", "ex": 1, "exp": "The name means black Riesling and has nothing whatever to do with Riesling; the grape is a member of the Pinot family, and both its German alternative Mullerrebe and its French name record the flour-dusted look of the young leaves. Wurttemberg and Baden bottle it as a still red, which is the one place a drinker is likely to meet it under a name of its own."},
{"id": "c-ko3naxnd", "cat": "Germany", "q": "Crossing Trollinger with Riesling at Weinsberg in 1929 produced a white grape named after a local physician who wrote drinking songs. Name the variety.", "sa": 1, "accept": ["kerner", "the kerner grape", "kerner crossing"], "ans": "Kerner", "exp": "It ripens more dependably than Riesling and keeps a good deal of acidity while doing so, which is how it spread through the Pfalz and Rheinhessen and then, improbably, up into the Alto Adige. German crossings often carry a person's name, Dornfelder and Scheurebe among them, but those two honour men who worked in wine, while Justinus Kerner was a doctor and poet in the town who had nothing to do with vines beyond writing songs about drinking what came off them."},
{"id": "c-624pms7x", "cat": "Hungary & Greece", "q": "Cellar walls in Tokaj carry a thick black felt that the growers take care never to scrub off. What is growing there?", "opts": ["A crust of tartrate thrown out of the wine by the cold", "A mould that lives on the alcohol evaporating through the casks", "Soot laid down by centuries of candle smoke", "Botrytis carried in from the vineyard on the fruit"], "a": 1, "exp": "Cladosporium cellare is the cellar's own fungus and it feeds on what a wooden cask loses through its staves. Growers read a good coat of it as proof that the humidity is right, and it darkens any bottle left standing in the tunnel long enough, which is why old bottles from the region come up looking as though they were dug out of the ground."},
{"id": "c-kglxt08b", "cat": "Hungary & Greece", "q": "Vines at Tokaj root into ground weathered from the worn stumps of old volcanoes, and the pale rock beneath the topsoil is consolidated ash rather than cooled lava. Which rock is that?", "opts": ["Slate", "Rhyolite tuff", "Chalk", "Alluvial gravel"], "a": 1, "exp": "Rhyolite is a pale silica-rich volcanic rock, and the ash it threw settled and hardened into a tuff soft enough to be cut by hand. That is why the region's cellars are tunnels rather than buildings, and the same rock weathers into a light soil that drains hard while the clay and loess over it hold water."},
{"id": "c-x8btafal", "cat": "Hungary & Greece", "q": "Tokaji labels increasingly print the name of one delimited site instead of a village or a blend. What is the Hungarian word for such a site?", "sa": 1, "accept": ["dulo", "dulok", "dulo vineyard", "dulo site", "named dulo"], "ans": "Dulo", "exp": "A dulo is a bounded and registered piece of ground, so the word does the work climat does in Burgundy and Einzellage does in Germany. Szarvas, Mezes Maly, Betsek and Szent Tamas are among the names a buyer meets, and a wine carrying one of them is picked, made and bottled apart rather than blended into a house cuvee."},
{"id": "c-l9o071jv", "cat": "Hungary & Greece", "q": "Sheltered from the north by a range of wooded hills that marks the edge of the Hungarian plain, the Tokaj vineyards face south and southeast off its lower slopes. Name the range.", "sa": 1, "accept": ["zemplen mountains", "zemplen", "zemplen hills", "zemplen range", "zemplen mountain range"], "ans": "The Zemplen Mountains", "exp": "Tokaj-Hegyalja means the foothills of Tokaj, and the vineyards sit on exactly that skirt of ground where the hills run out into the flat. The barrier keeps the worst of the northern weather off and the slopes hold their warmth into autumn, which is what lets fruit shrivel on the vine rather than simply spoil."},
{"id": "c-bvvexc7x", "cat": "Hungary & Greece", "q": "A Tokaji Aszu bottled under the rules in force since 2013 has to reach a stated residual sugar before it may carry the name. Which figure?", "opts": ["150 grams per litre", "30 grams per litre", "120 grams per litre", "90 grams per litre"], "a": 2, "exp": "Sweetness is now written into the rulebook as a number rather than counted in hods tipped into a barrel. A wine short of the figure cannot be sold as Aszu at all and goes out as a late harvest or as the sweet form of szamorodni instead, so the reform tightened the name rather than merely relabelling it."},
{"id": "c-tu50swzo", "cat": "Hungary & Greece", "q": "Sweetness rungs below a certain number of hods disappeared from Tokaji Aszu labels with the 2013 reform. Give the lowest number a bottle may now carry.", "sa": 1, "accept": ["five puttonyos", "5 puttonyos", "five", "5", "puttonyos five", "at least five puttonyos", "at least 5 puttonyos", "a minimum of five puttonyos", "a minimum of 5 puttonyos", "five puttonyos minimum", "5 puttonyos minimum", "minimum five puttonyos", "minimum 5 puttonyos", "five puttonyos or more", "5 puttonyos or more", "five hods", "5 hods"], "ans": "Five puttonyos", "ex": 1, "exp": "Three and four puttonyos went, leaving only the top of the old scale in use, and the indication itself became optional, so plenty of bottles now print no number at all. Anything below the surviving level is sold under a different name rather than as a weaker Aszu, which is the change the reform was really making."},
{"id": "c-bj0gjlof", "cat": "Hungary & Greece", "q": "Before a Tokaji Aszu may be bottled the rules set a floor on its time in wood, and that floor was shortened when the region was reformed. How long is it?", "sa": 1, "accept": ["eighteen months", "18 months", "eighteen months in wood", "18 months in wood", "eighteen months in barrel", "18 months in barrel", "eighteen months in oak", "18 months in oak", "eighteen months in cask", "18 months in cask", "a minimum of eighteen months", "a minimum of 18 months", "at least eighteen months", "at least 18 months", "minimum eighteen months", "minimum 18 months", "eighteen months minimum", "18 months minimum", "at least eighteen months in wood", "at least 18 months in wood", "at least eighteen months in oak", "at least 18 months in oak", "at least eighteen months in barrel", "at least 18 months in barrel", "at least eighteen months in cask", "at least 18 months in cask", "a minimum of eighteen months in wood", "a minimum of 18 months in wood", "a minimum of eighteen months in oak", "a minimum of 18 months in oak", "a minimum of eighteen months in barrel", "a minimum of 18 months in barrel", "a minimum of eighteen months in cask", "a minimum of 18 months in cask", "eighteen months in wood minimum", "18 months in wood minimum", "eighteen months in oak minimum", "18 months in oak minimum", "eighteen months in barrel minimum", "18 months in barrel minimum", "eighteen months in cask minimum", "18 months in cask minimum", "one and a half years", "a year and a half", "1.5 years", "a year and a half in barrel"], "ans": "Eighteen months", "ex": 1, "exp": "The wine must also wait until the third year after the harvest before it is released, so the barrel floor is not the whole of the ageing. Cutting it back from the older two years in cask was pressed for by makers who wanted fresher, fruitier Aszu and resisted by those who held that the oxidative character was the point of the style."},
{"id": "c-jx1eerd7", "cat": "Hungary & Greece", "q": "The sweet form of szamorodni is separated from the dry one by a number rather than by a taste. What residual sugar must the sweet version reach?", "sa": 1, "accept": ["60 grams per litre", "60 grams per liter", "sixty grams per litre", "sixty grams per liter", "60 g/l", "60g/l", "60 g per litre", "60 g per liter", "60 grams", "sixty grams", "60", "at least 60 grams per litre", "at least 60 grams per liter", "at least 60 g/l", "a minimum of 60 grams per litre", "a minimum of 60 grams per liter", "minimum 60 grams per litre", "minimum 60 grams per liter", "60 grams per litre minimum", "60 grams per liter minimum", "60 grams of residual sugar per litre", "60 grams per litre of residual sugar", "60 grams residual sugar", "60 grams per litre residual sugar"], "ans": "60 grams per litre", "ex": 1, "exp": "Above the figure the wine is edes, the sweet one, while szaraz, the dry version, is held to a fraction of that sugar, so no szamorodni is bottled in the gap between them. The floor used to sit at the generic European figure for any wine called sweet and was lifted well clear of it, which changed the label on almost nothing, since the category is in practice bottled a good deal sweeter than either number. The same picking can give either style, so the year decides which the cellar ends up with rather than the maker."},
{"id": "c-ppeiqtok", "cat": "Hungary & Greece", "q": "One Tokaji category stood above Aszu in sweetness and was abolished outright by the 2013 reform. Which name went?", "opts": ["Szamorodni", "Aszu-Eszencia", "Forditas", "Tokaji Late Harvest"], "a": 1, "exp": "It occupied the ground between the sweetest Aszu and the syrup that runs from the berries under nothing but their own weight, and the reformers took the view that it duplicated both ends of that gap. It was the only whole category the reform struck out, since Szamorodni, Forditas, Maslas and late harvest all stayed, though the Aszu sweetness scale itself was trimmed at the same time."},
{"id": "c-yaq5xgsb", "cat": "Hungary & Greece", "q": "Tokaj's aromatic permitted variety is the grape Italy bottles as Moscato Bianco and Greece as Moschato Aspro. Which Hungarian name does it carry?", "opts": ["Koverszolo", "Kabar", "Sarga Muskotaly", "Budai Zold"], "a": 2, "exp": "Sarga means yellow, which is how Hungary marks out the small-berried, finest member of the Muscat family from its coarser relatives. It is permitted in a blend and on its own account, and a varietal bottling is dry, light and scented of orange blossom, which surprises anyone expecting the region to taste only of sweet wine."},
{"id": "c-mulws7yu", "cat": "Hungary & Greece", "q": "Bred from Furmint and Bouvier, one permitted Tokaj variety rots early and readily, which is exactly why growers keep a little of it. Name that crossing.", "sa": 1, "accept": ["zeta", "zeta grape", "zeta variety", "zeta crossing"], "ans": "Zeta", "exp": "It carried the name Oremus until it was renamed at the end of the 1990s, and it botrytises ahead of everything else on the estate, so a picking crew can start work on it while the Furmint is still sound. Its own wine is unremarkable and it earns its place by delivering shrivelled fruit early in a short autumn."},
{"id": "c-akqvxk6d", "cat": "Hungary & Greece", "q": "Furmint gives Tokaj its acid spine but little scent, so a second variety is planted for perfume and body, and its name means linden leaf. Name it.", "sa": 1, "accept": ["harslevelu", "harslevelu grape", "harslevelu variety"], "ans": "Harslevelu", "exp": "The leaf is broad and heart-shaped like a linden's, which is all the name records. It ripens later and to a higher sugar than its partner and brings honey and orange peel into a blend, and bottled on its own it makes a rounder, softer wine than the region's reputation would suggest."},
{"id": "c-98c4i3oo", "cat": "Hungary & Greece", "q": "No single grape may take over an Egri Bikaver: the rules cap what any one variety may contribute to the blend. Where does that ceiling sit?", "opts": ["Fifty per cent", "Seventy-five per cent", "Thirty per cent", "Ten per cent"], "a": 0, "exp": "The cap makes the wine a blend by construction rather than by custom, which is the whole point of a name that has been sold as a blend for well over a century. Above the everyday version sit stricter tiers asking for more varieties, lower yields and, at the top, fruit from one named site."},
{"id": "c-yxpmmedc", "cat": "Hungary & Greece", "q": "One red variety is compulsory in every Egri Bikaver and supplies the acid and the peppery frame the blend is built on. Name it.", "sa": 1, "accept": ["kekfrankos", "kek frankos", "blaufrankisch", "lemberger"], "ans": "Kekfrankos", "exp": "The same grape is Blaufrankisch across the Austrian border and Lemberger in Germany, and it is the backbone of Hungarian red wine wherever the ground is cool enough. It holds its acidity through a hot year, which is what keeps a blend fresh where Merlot and Cabernet on their own would turn soft and jammy."},
{"id": "c-po5f0oil", "cat": "Hungary & Greece", "q": "Eger answered its famous red with a white blend launched in the 2010s, and the name means star. Give that name.", "sa": 1, "accept": ["egri csillag", "star of eger", "egri csillag blend"], "ans": "Egri Csillag", "exp": "The rules ask for several varieties with the majority drawn from grapes native to the Carpathian basin, so the category was designed to sell Hungarian white grapes rather than international ones. It is meant to be drunk young and aromatic, a deliberate contrast with the barrel-aged red it was built to sit beside."},
{"id": "c-k67mvaz1", "cat": "Hungary & Greece", "q": "The name Bikaver is a plain compound of ordinary Hungarian words rather than a place. Translate it.", "sa": 1, "accept": ["bull s blood", "bulls blood", "bull blood", "blood of the bull"], "ans": "Bull's blood", "exp": "The story attached to it puts the defenders of Eger's castle through the siege of 1552 on red wine, with the Turkish besiegers reading their stained beards as evidence that they were drinking the blood of bulls. The tale is a great deal younger than the siege and the name itself surfaces only in the nineteenth century, which has not slowed either of them down."},
{"id": "c-vdgzm17x", "cat": "Hungary & Greece", "q": "In Hungary's warmest corner, on a limestone ridge running east to west against the Croatian border, growers built a modern reputation on one Bordeaux variety and won a protected name for it. Which variety?", "opts": ["Cabernet Franc", "Cabernet Sauvignon", "Carmenere", "Merlot"], "a": 0, "exp": "Villany is the region and Villanyi Franc the designation, which fixes a style as well as a grape: ripe, dark and oak-aged rather than leafy and cool. The variety reaches full ripeness there in a way it does not on the Loire, and that is the argument the growers made for giving it a name of its own."},
{"id": "c-1wg1grfc", "cat": "Hungary & Greece", "q": "Thin skins, late ripening and pale colour made one old Hungarian red hard to grow and easy to lose, and it survives now mostly in the south, where it lends spice rather than weight. Name the grape.", "sa": 1, "accept": ["kadarka", "kadarka grape", "kadarka variety"], "ans": "Kadarka", "exp": "It came up through the Balkans and carried Hungarian red wine before phylloxera, when it was planted in enormous quantity and too often picked before it was ready. Growers who persist with it get a perfumed, light-coloured wine with a paprika edge that no international variety supplies, and that is the whole case for the trouble it causes."},
{"id": "c-wc9ijnk2", "cat": "Hungary & Greece", "q": "Bikaver is not Eger's alone; one other Hungarian district may print the word on its labels. Name that district.", "sa": 1, "accept": ["szekszard", "szekszardi", "szekszard district"], "ans": "Szekszard", "exp": "Its hills are deep wind-blown silt rather than the volcanic ground of the north, and they lie further south and warmer, so the wine comes out rounder and softer than the northern version of the same name. They are separate protected designations with separate rulebooks, and no third district may use the word at all."},
{"id": "c-dvaz4xkw", "cat": "Hungary & Greece", "q": "Growers ruined by phylloxera replanted in quantity on the sandy plain between the Danube and the Tisza, and ungrafted vines still stand there. Which Hungarian region occupies that ground?", "opts": ["Balatonfured-Csopak", "Villany", "Badacsony", "Kunsag"], "a": 3, "exp": "The louse needs a soil it can tunnel through and cannot manage sand of that kind, which is why the plain was the safe place to plant. It is flat, hot and enormous, and its trade has always been in everyday wine rather than in the bottles the hill regions are known for."},
{"id": "c-drp3o2g3", "cat": "Hungary & Greece", "q": "A bunch that curls like a sheep's tail gave one white variety its name, and it grows on a single isolated hill in western Hungary that is a wine district in its own right. Name the grape.", "sa": 1, "accept": ["juhfark", "juhfark grape", "juhfark variety"], "ans": "Juhfark", "exp": "Somlo is the hill, the eroded plug of an old volcano standing out of flat farmland, and the wine off it is smoky, hard and so high in acid that it needs years before it gives anything up. It was long prescribed to couples wanting a son, which is the sort of story a wine of that size attracts."},
{"id": "c-ldt7srah", "cat": "Hungary & Greece", "q": "Flowers on one Badacsony white cannot fertilise themselves, so a pollinating variety has to stand among the rows or the crop never sets. Name that grape.", "sa": 1, "accept": ["keknyelu", "kek nyelu", "keknyelu grape"], "ans": "Keknyelu", "exp": "The name means blue stalk, and Budai Zold is the variety usually planted to do the fertilising. The arrangement makes it awkward and shy-cropping, so plantings on the basalt above Lake Balaton are small and the wine is hard to find, full-bodied and stony when it turns up."},
{"id": "c-v3zvcx5c", "cat": "Hungary & Greece", "q": "A Greek bottle carries the word Cava and the guest assumes it must be sparkling. What does the word actually promise there?", "opts": ["That the wine is sweet and fortified", "That the fruit came from one delimited vineyard", "That the wine was made sparkling by a second fermentation in bottle", "That the wine was aged for a set minimum before release"], "a": 3, "exp": "Greek law uses it as an ageing claim on wines outside the protected designations, with reds held longer than whites and a stated share of the time spent in barrel. It carries no method claim whatever, and it predates the confusion with the Spanish sparkling wine that now sits beside it on the same shelf."},
{"id": "c-3vyo49an", "cat": "Hungary & Greece", "q": "Pine resin rather than a place defines one protected Greek wine name, and it may be produced across much of the country. What kind of protection does that name hold?", "opts": ["A trademark held by a growers' association", "A protected designation of origin shared by three regions", "A traditional designation rather than an origin claim", "A protected geographical indication covering the whole country"], "a": 2, "exp": "Retsina is defined by the addition of Aleppo pine resin to the fermenting must, so it names a practice rather than a vineyard, and versions tied to a particular area exist alongside it as geographical indications. The resin began as a preservative and a by-product of sealing amphorae, and it stayed on as a taste long after it had stopped being necessary."},
{"id": "c-v1k2iqkq", "cat": "Hungary & Greece", "q": "Most of the Attica vineyard is planted to one hardy white grape, and it is also the usual base for resinated wine. Name it.", "sa": 1, "accept": ["savatiano", "savvatiano", "savatiano grape"], "ans": "Savatiano", "exp": "It is drought-tolerant and generous, which is how it survived a century of being asked for quantity on the hot plain outside Athens. Old bush vines of it, picked early and made without any resin at all, give a nutty, textured dry white that has changed a good many opinions of the variety."},
{"id": "c-uzhg06ny", "cat": "Hungary & Greece", "q": "Below the protected designations sits the Greek regional tier, and it is where most experiments with international varieties and unorthodox blends are bottled. Give the Greek term for it.", "sa": 1, "accept": ["topikos oinos", "topikos oenos", "topikos inos", "regional wine", "greek regional wine", "regional wine tier", "local wine", "greek local wine", "topikos oinos regional wine", "topikos oenos regional wine", "topikos inos regional wine", "topikos oinos regional wine tier", "regional wine topikos oinos", "local wine topikos oinos", "topikos oinos pgi", "topikos oinos greek pgi", "greek pgi", "topikos oinos igp", "topikos oinos greek regional wine", "topikos oinos local wine", "topikos oinos or regional wine", "topikos oinos or local wine", "topikos oinos regional wine pgi"], "ans": "Topikos Oinos", "ex": 1, "exp": "It corresponds to the European protected geographical indication, and the freedom is the point: a designation works from a short list of varieties, while this tier works from a long one that admits international grapes, so a producer wanting Syrah beside Assyrtiko bottles it here. A good many of the country's most admired wines sit at this level by choice rather than by failure."},
{"id": "c-9uwk6gch", "cat": "Hungary & Greece", "q": "Vines on Santorini are woven flat into low coiled baskets lying on the ground, with the bunches hanging on the inside of the coil. Name that training system.", "sa": 1, "accept": ["kouloura", "kouloures", "kouloura basket", "basket training"], "ans": "Kouloura", "exp": "The wind is constant and salt-laden and a vine standing upright would be stripped, so the coil shelters the fruit inside it and collects what moisture the night brings. The baskets are rewoven by hand as they grow and nothing about the work can be mechanised, which is a large part of why the wine costs what it does."},
{"id": "c-bzkceka6", "cat": "Hungary & Greece", "q": "A Santorini white is not required to be pure Assyrtiko: the designation admits a pair of other island whites alongside it. Which pair?", "opts": ["Athiri and Aidani", "Malagousia and Vidiano", "Vilana and Dafni", "Mandilaria and Mavrotragano"], "a": 0, "exp": "Assyrtiko has to supply the great bulk of the blend and the other two fill out the rest, Aidani bringing perfume and Athiri softening the attack. The red varieties of the island are bottled outside the designation altogether, so a Santorini red is a regional wine however good it is."},
{"id": "c-3hy60qlj", "cat": "Hungary & Greece", "q": "Never grafted and often very old, a Santorini vine is renewed by burying one of its own canes to take root rather than by planting a new one. Name that technique.", "sa": 1, "accept": ["layering", "layering a cane", "layering the canes", "cane layering", "ground layering", "simple layering", "vine layering", "layering a shoot", "layering technique", "provignage", "marcottage", "layering provignage", "layering or provignage", "provignage layering", "layering marcottage", "layering or marcottage", "marcottage layering", "ground layering provignage", "ground layering marcottage", "propagation by layering", "layering propagation"], "ans": "Layering", "ex": 1, "exp": "The trunk above ground is replaced while the root system underneath it carries on, so the plant can be far older than anything visible, and phylloxera has never taken hold in the loose volcanic sand to force a grafted replant. The cane stays joined to its parent the whole time it is rooting, which is what separates the practice both from taking a cutting and from the air layering done above ground on standing wood. It is also why nobody on the island can tell you the age of a vineyard with any confidence."},
{"id": "c-92a73oy9", "cat": "Hungary & Greece", "q": "A dry white Santorini bottled at no less than 13.5 per cent and given time in oak carries a name meaning work done through the night. Give the name.", "sa": 1, "accept": ["nykteri", "nichteri", "nychteri", "nikteri", "nykteri santorini"], "ans": "Nykteri", "exp": "The picking and pressing were done in the dark so the fruit did not heat up on the way to the cellar, and the name records the labour rather than the style. The wine is fuller, riper and more textured than the island's ordinary dry white, which is the point of holding the fruit out for extra ripeness."},
{"id": "c-g9k7i7ty", "cat": "Hungary & Greece", "q": "Sun-dried Assyrtiko is pressed into a sweet wine on Santorini, and the rules will not release it until it has done a stated spell in oak. How long?", "opts": ["Twenty years", "Two years", "Five years", "Six months"], "a": 1, "exp": "The must is so thick with sugar that fermentation runs slowly and never far, and the barrel time is what turns the wine mahogany and builds the coffee, dried fig and caramel character. Bottlings held for a decade or two beyond the minimum are a claim the producer makes on the label rather than anything the rulebook demands."},
{"id": "c-or23v6jr", "cat": "Hungary & Greece", "q": "Pale garnet in the glass, smelling of dried tomato, olive and sun-dried herb, gripping with high acid and firm tannin, and mistaken for Nebbiolo by half the room. Which Greek variety?", "opts": ["Xinomavro", "Mandilaria", "Limnio", "Mavrotragano"], "a": 0, "exp": "The name is a compound of the words for sour and black, which describes the wine better than the colour in the glass does: it is pale from the start and browns early while carrying tannin that wants a decade. The Nebbiolo comparison is drawn so routinely that it has become the standard way of selling the grape abroad."},
{"id": "c-o4pb6xli", "cat": "Hungary & Greece", "q": "Rapsani blends Xinomavro in equal parts with two other Thessalian reds grown on the same slopes. Name them.", "sa": 1, "accept": ["krassato and stavroto", "stavroto and krassato", "krassato stavroto", "stavroto krassato", "krasato and stavroto", "krassato and stavrato"], "ans": "Krassato and Stavroto", "exp": "The vineyards climb the lower slopes of Mount Olympus and the blend is written into the designation rather than left to the maker. Krassato brings flesh and alcohol and Stavroto brings colour and aroma, which between them is a fair list of what the leading grape does not supply on its own."},
{"id": "c-o438z1t9", "cat": "Hungary & Greece", "q": "On a cool high plateau in western Macedonia the same red variety as Naoussa gives a lighter wine, and the designation there is the one permitted to make it sparkle. Name that designation.", "sa": 1, "accept": ["amyndeon", "amynteo", "amyndeo", "amindeo", "amyntaio", "amyndaio", "amyntaion", "amynteon", "amyndeon pdo"], "ans": "Amyndeon", "exp": "The plateau sits high, much of it above six hundred metres, and is ringed by four lakes, so the fruit arrives with more acid and less tannin than it does further east, and rose, still and sparkling alike, matters there as much as red. It is the coolest red-wine ground in Greece and the wines are correspondingly pale and nervy."},
{"id": "c-unb1hycn", "cat": "Hungary & Greece", "q": "Naoussa admits no grape but Xinomavro, and its vineyards sit on the southeastern flank of a single mountain. Which mountain?", "opts": ["Mount Parnassos", "Mount Athos", "Mount Vermio", "Mount Taygetos"], "a": 2, "exp": "The slope faces southeast between roughly two and four hundred metres, which is what makes ripening red fruit possible that far north. The designation is red only and unblended, and it asks for a year in oak before the wine may be sold; time in bottle beyond that is the producer's decision rather than something the designation demands."},
{"id": "c-25napd1d", "cat": "Hungary & Greece", "q": "One Macedonian designation tempers Xinomavro by blending in a softer, fleshier local red grown beside it. Name the designation.", "sa": 1, "accept": ["goumenissa", "goumenisa", "goumenissa pdo"], "ans": "Goumenissa", "exp": "Negoska is the blending partner and it fills out the middle of a wine that can be all edges on its own, so the style is rounder and readier to drink. The vineyards lie on the slopes of Mount Paiko north-west of Thessaloniki, on ground lower and gentler than the great Xinomavro sites."},
{"id": "c-6eyw3oim", "cat": "Hungary & Greece", "q": "Nemea's vineyards run from a valley floor up to slopes several hundred metres higher, and a proposal to split the designation by altitude has been argued over for years. Which single red variety must all of it be?", "sa": 1, "accept": ["agiorgitiko", "aghiorgitiko", "agiorghitiko", "aghiorghitiko", "agiorgitico", "agiorgitiko grape"], "ans": "Agiorgitiko", "exp": "The low ground ripens to a soft, dark, low-acid wine and the high ground gives something far tighter and later, and one name currently covers both, which is the whole case for zoning. The grape is named for Saint George, and its deep colour over gentle tannin makes it the most immediately likeable of the Greek reds."},
{"id": "c-k15dab08", "cat": "Hungary & Greece", "q": "Pink-skinned and heavily perfumed, one Peloponnese variety is pressed carefully to keep its wine white, and a cool plateau in Arcadia is its home. Name the grape.", "sa": 1, "accept": ["moschofilero", "moscofilero", "moschofilero grape"], "ans": "Moschofilero", "exp": "Mantinia is the designation, sitting at around six hundred and fifty metres, and the wine is low in alcohol, sharp and floral, with rose petal and citrus peel. The skins carry enough colour that a longer maceration turns the wine pink, which is bottled at regional level rather than under the designation."},
{"id": "c-0c6jy60g", "cat": "Hungary & Greece", "q": "Robola vines on Cephalonia grow straight out of bare limestone scree, and the Venetians who ruled the island left a nickname recording it. What did they call the wine?", "opts": ["Wine of the mountain", "Wine of the fleet", "Wine of the friars", "Wine of stone"], "a": 3, "exp": "Vino di sasso is the phrase, and the vineyards sit on rubble steep enough that every part of the work is done by hand. Robola gives a dry white with a lemon and crushed-stone character and a faintly waxy weight, and it is grown seriously almost nowhere else."},
{"id": "c-4r2iyd0s", "cat": "Hungary & Greece", "q": "Black laurel is what the name of one grape means, and the sweet fortified red of Patras is built on it. Name the grape.", "sa": 1, "accept": ["mavrodaphne", "mavrodafni", "mavrodaphni", "mavrodafne", "mavrodaphne grape", "mavrodafni grape", "mavrodaphni grape", "mavrodafne grape", "mavrodaphne variety", "mavrodafni variety", "mavrodaphni variety", "mavrodafne variety"], "ans": "Mavrodaphne", "ex": 1, "exp": "The wine is fortified during fermentation and then aged oxidatively in cask, frequently by blending across vintages, so it arrives tasting of raisin, coffee and dried fig. A handful of producers make a dry red from the same grape, which is a very different and much rarer thing to meet on a list."},
{"id": "c-eoxcpy2h", "cat": "Hungary & Greece", "q": "A fortified rock town in the southeastern Peloponnese shipped sweet wine across medieval Europe and left its name on a family of grapes still grown from Italy to Madeira. Name the town.", "sa": 1, "accept": ["monemvasia", "monemvassia", "monemvasia in the peloponnese"], "ans": "Monemvasia", "exp": "Malvasia is the name in its travelled form, and much of what the town shipped was probably gathered from the islands and merely sold through its harbour rather than grown behind it. A modern designation has revived the link, and the variety called Monemvasia on Paros is one of the family carrying the name home."},
{"id": "c-v1u6keq4", "cat": "Italy Central & South", "q": "A nineteenth-century formula for Chianti allowed a white grape so the wine would drink well young. Which white was named?", "opts": ["Grechetto", "Vermentino", "Malvasia", "Vernaccia"], "a": 2, "exp": "Bettino Ricasoli set out Sangiovese with Canaiolo for structure and a little Malvasia for early appeal in 1872. He treated the white share as optional, but the 1967 DOC made it compulsory at ten to thirty percent, 1996 made it optional again, and from the 2006 vintage white grapes were banned from Chianti Classico outright."},
{"id": "c-rdllcoig", "cat": "Italy Central & South", "q": "Flaky, friable marl that splits into plates underlies many of the best sites between Florence and Siena. What is that soil called locally?", "opts": ["Ponca", "Albariza", "Galestro", "Terra rossa"], "a": 2, "exp": "Galestro breaks up easily and drains hard, which suits Sangiovese on a slope. Alberese, a hard compact limestone, is the other rock name worth knowing in the same hills."},
{"id": "c-qw643fup", "cat": "Italy Central & South", "q": "Cooler, higher ground in the Sieve valley northeast of Florence gives the Chianti subzone most often singled out for longevity. Which subzone is it?", "opts": ["Colli Senesi", "Rufina", "Colline Pisane", "Montalbano"], "a": 1, "exp": "Altitude and a cool draught out of the Apennines slow ripening and hold acidity. The wines start tighter and reward cellaring more than most Chianti does."},
{"id": "c-z0acy0p9", "cat": "Italy Central & South", "q": "Since the 2006 vintage a whole category of grape has been shut out of the Classico blend. Which category?", "sa": 1, "accept": ["white grapes", "white varieties", "white grape varieties", "white wine grapes"], "ans": "White grapes", "exp": "Trebbiano and Malvasia had been permitted for over a century and were often used to stretch volume. Removing them was the single clearest step in Classico's move upmarket."},
{"id": "c-gr5zhar5", "cat": "Italy Central & South", "q": "A Classico producer wants the denomination's top tier, which demands estate-grown fruit and thirty months of ageing. Which designation is that?", "sa": 1, "accept": ["gran selezione", "chianti classico gran selezione", "classico gran selezione", "gran selezione tier", "gran selezione level", "gran selezione designation"], "ans": "Gran Selezione", "ex": 1, "exp": "Introduced in 2013 above Riserva, and unusual in tying the tier to fruit the estate farmed itself. Riserva by contrast can be built from bought grapes."},
{"id": "c-wpxpyzl1", "cat": "Italy Central & South", "q": "Outside the Classico zone the Sangiovese minimum sits at seventy percent. Inside it, what does the rulebook demand?", "sa": 1, "accept": ["eighty percent", "80 percent", "80%", "eighty percent sangiovese", "at least 80 percent", "at least eighty percent", "80 percent sangiovese", "eighty per cent", "80 per cent", "eighty", "80"], "ans": "Eighty percent Sangiovese", "ex": 1, "exp": "The remaining fifth may be Canaiolo, Colorino or an international variety, and many estates now bottle the wine as pure Sangiovese anyway. The wider Chianti DOCG stays at seventy."},
{"id": "c-6lchw3zi", "cat": "Italy Central & South", "q": "Some producers restart a finished wine with dried, part-raisined grapes to build body and softness. What is that Tuscan practice called?", "sa": 1, "accept": ["governo all'uso toscano", "governo", "governo toscano", "governo method", "governo alluso toscano"], "ans": "Governo all'uso toscano", "exp": "The renewed fermentation adds a little alcohol and glycerol and rounds off hard young tannin. It fell out of favour with the drive for concentration and has been revived by growers chasing drinkability."},
{"id": "c-unntkhmm", "cat": "Italy Central & South", "q": "West of Florence a small DOCG has required Cabernet in its blend since long before anyone spoke of Super Tuscans. Name it.", "sa": 1, "accept": ["carmignano", "carmignano docg", "carmignano in tuscany"], "ans": "Carmignano", "exp": "The rules oblige at least a tenth Cabernet Franc or Sauvignon alongside Sangiovese. Cabernet was growing there under the name uva francesca in Medici times, which makes the zone the oldest precedent for what Bolgheri later made famous."},
{"id": "c-aa5tib1v", "cat": "Italy Central & South", "q": "Ferruccio Biondi-Santi propagated a particular Sangiovese selection in the nineteenth century. What is that selection called locally?", "opts": ["Morellino", "Prugnolo Gentile", "Nielluccio", "Brunello"], "a": 3, "exp": "Brunello means little dark one and refers to the fruit rather than the wine. Prugnolo Gentile, Morellino and Nielluccio are the same grape's names in Montepulciano, the Maremma and Corsica."},
{"id": "c-8pctsjtp", "cat": "Italy Central & South", "q": "A Montalcino estate declassifies younger fruit into a wine it can sell a year after harvest. Which denomination takes it?", "opts": ["Val d'Orcia", "Moscadello di Montalcino", "Sant'Antimo", "Rosso di Montalcino"], "a": 3, "exp": "Rosso is the same grape from the same hill under a much shorter ageing requirement, which lets an estate protect the Brunello in a difficult year. It is often the better value and always the earlier drink."},
{"id": "c-9y8o7kv3", "cat": "Italy Central & South", "q": "Shelter from an extinct volcanic cone keeps this zone drier and warmer than the Chianti hills to its north. Which peak gives that shelter?", "opts": ["Monte Conero", "The Apuan Alps", "Monte Amiata", "Monte Vulture"], "a": 2, "exp": "Amiata breaks up storms coming off the Tyrrhenian, so Montalcino sees markedly less rain than Chianti Classico. Growers there worry about drought where growers further north worry about rot."},
{"id": "c-w0kiniad", "cat": "Italy Central & South", "q": "An estate in Montalcino plants Cabernet and Chardonnay alongside its Sangiovese. Under which local DOC may it bottle them?", "sa": 1, "accept": ["sant'antimo", "santantimo", "sant'antimo doc", "santantimo doc"], "ans": "Sant'Antimo", "exp": "Sant'Antimo is the catch-all denomination covering everything on the hill that is not Brunello, Rosso or Moscadello. It is named for the Romanesque abbey below the town."},
{"id": "c-ynpyqyv4", "cat": "Italy Central & South", "q": "Before Brunello made the town famous, Montalcino was known for a sweet white pressed from Moscato. What is that wine called?", "sa": 1, "accept": ["moscadello di montalcino", "moscadello", "moscadello montalcino", "moscadello wine"], "ans": "Moscadello di Montalcino", "exp": "Moscadello was the commercial wine of the zone for centuries and was traded well beyond Tuscany. It survives as a curiosity in still, frizzante and late-harvest forms."},
{"id": "c-fhccaff6", "cat": "Italy Central & South", "q": "In Montepulciano the local Sangiovese clone must supply at least what proportion of a Vino Nobile?", "sa": 1, "accept": ["seventy percent", "70 percent", "70%", "at least seventy percent", "70 percent sangiovese", "seventy percent sangiovese", "at least 70 percent", "seventy per cent", "70 per cent", "seventy", "70"], "ans": "Seventy percent", "ex": 1, "exp": "The balance may include Canaiolo, Mammolo and other permitted varieties, so a Nobile is more often a blend than a Brunello is. The clone is called Prugnolo Gentile here."},
{"id": "c-zi83sn8k", "cat": "Italy Central & South", "q": "A Nobile Riserva is held longer than the standard bottling before release. How long in total?", "sa": 1, "accept": ["three years", "3 years", "three years of ageing", "36 months", "thirty six months", "three", "3", "three years in total", "three years total"], "ans": "Three years", "ex": 1, "exp": "The standard wine needs two years and the Riserva a third, part of which must be spent in bottle. Both are shorter requirements than Brunello carries."},
{"id": "c-5pbja2pg", "cat": "Italy Central & South", "q": "Antinori first sold a barrique-aged Sangiovese as a table wine rather than a Chianti from the 1971 vintage. Which wine was that?", "opts": ["Ornellaia", "Solaia", "Tignanello", "Sassicaia"], "a": 2, "exp": "Small French oak and a blend outside the rulebook meant it could not be labelled Chianti Classico, so it went out as a vino da tavola. The white grapes left the blend with the 1975 vintage, which is also when Cabernet was written in."},
{"id": "c-pwxt791u", "cat": "Italy Central & South", "q": "Merlot on a vein of blue clay in Bolgheri, in a vineyard first planted by Tenuta dell'Ornellaia, produces which single-variety bottling?", "opts": ["Paleo Rosso", "Masseto", "Guado al Tasso", "Le Serre Nuove"], "a": 1, "exp": "The clay holds water through a hot coastal summer, which is why Merlot behaves there as it does nowhere else in Tuscany. The vineyard is a matter of a few hectares."},
{"id": "c-qflzrnug", "cat": "Italy Central & South", "q": "A sweet red passito from the island of Elba holds DOCG rank. Which grape is dried for it?", "opts": ["Aleatico", "Mammolo", "Ciliegiolo", "Colorino"], "a": 0, "exp": "Aleatico is a red-berried relation of Muscat and keeps that grapey perfume through drying. The wine is sweet, scented and only lightly tannic."},
{"id": "c-jf1kaqyi", "cat": "Italy Central & South", "q": "Guado al Tasso and Ornellaia share a denomination built on Bordeaux varieties. Which two lead it in practice?", "sa": 1, "accept": ["cabernet sauvignon and merlot", "merlot and cabernet sauvignon", "cabernet sauvignon merlot", "merlot cabernet sauvignon"], "ans": "Cabernet Sauvignon and Merlot", "exp": "The rulebook allows Cabernet Sauvignon, Merlot and Cabernet Franc each from nothing up to the whole blend, and caps Syrah and Sangiovese at half, so the first two lead by practice rather than by rule. Bolgheri Sassicaia was carved out as its own DOC in 2013 and sits outside this denomination."},
{"id": "c-aic2omtb", "cat": "Italy Central & South", "q": "Which denomination covers Sangiovese grown broadly across the Maremma, sitting below Morellino di Scansano in the hierarchy?", "sa": 1, "accept": ["maremma toscana", "maremma toscana doc"], "ans": "Maremma Toscana", "exp": "It gathers up the wide coastal plain and its hinterland under one name, in reds, whites and roses. Morellino remains the tighter, hillier zone within that country."},
{"id": "c-gqc2gfjk", "cat": "Italy Central & South", "q": "Tignanello's sister wine from the same hillside leans on Cabernet Sauvignon rather than Sangiovese. Name it.", "sa": 1, "accept": ["solaia", "solaia antinori", "antinori solaia"], "ans": "Solaia", "exp": "The plot faces south and takes its name from the sun, and the wine inverts its neighbour's proportions. A small share of Sangiovese still keeps it recognisably Tuscan."},
{"id": "c-wpkexwn5", "cat": "Italy Central & South", "q": "Before the dry version was ever bottled commercially, Montefalco's Sagrantino was made in which style?", "opts": ["A sweet passito wine", "A pale dry rosato", "A fortified wine", "A lightly sparkling red"], "a": 0, "exp": "The grapes were laid out to dry and then fermented on their skins, and the sweet passito was the traditional Easter wine of the district; the dry bottling only appeared in the 1970s. Drying suits a grape whose tannin is otherwise ferocious."},
{"id": "c-d0ea0grw", "cat": "Italy Central & South", "q": "Which Umbrian DOCG south of Perugia is a Sangiovese-led red released only as a Riserva?", "opts": ["Colli Martani", "Lago di Corbara", "Montefalco Rosso", "Torgiano Rosso Riserva"], "a": 3, "exp": "The plain Torgiano red stays at DOC; only the longer-aged wine was promoted. It is one of the few Italian DOCGs that exists at Riserva level alone."},
{"id": "c-lhywvj93", "cat": "Italy Central & South", "q": "DNA profiling matched Verdicchio to a variety long grown in the Veneto under another name. Which?", "opts": ["Trebbiano Toscano", "Garganega", "Cortese", "Trebbiano di Soave"], "a": 3, "exp": "Verdicchio, Trebbiano di Soave and Trebbiano di Lugana proved to be one variety under three regional names. It is unrelated to the far more widely planted Trebbiano Toscano."},
{"id": "c-payb4fpw", "cat": "Italy Central & South", "q": "Umbria's best-known white grows on tufa beneath a cathedral town and was historically made off-dry. Name the wine.", "sa": 1, "accept": ["orvieto", "orvieto classico", "orvieto doc", "orvieto abboccato"], "ans": "Orvieto", "exp": "The soft volcanic rock under the town was hollowed into cellars that held a steady cool temperature, which favoured wines with sugar left in them. Most Orvieto today is finished dry."},
{"id": "c-243axq94", "cat": "Italy Central & South", "q": "Which native white grape gives Umbrian blends more body and grip than Trebbiano manages?", "sa": 1, "accept": ["grechetto", "grechetto grape", "grechetto di orvieto"], "ans": "Grechetto", "exp": "Grechetto has thicker skins and holds acidity better, so it stands up to lees work and even to oak. It is increasingly bottled on its own rather than used to prop up a blend."},
{"id": "c-abjnrm34", "cat": "Italy Central & South", "q": "Marche grows Verdicchio in a smaller inland valley that never opens to the sea. Name that zone.", "sa": 1, "accept": ["matelica", "verdicchio di matelica", "matelica doc", "matelica in the marche"], "ans": "Matelica", "exp": "The valley runs north to south rather than out to the Adriatic, so it gets a continental swing of temperature the coastal Castelli di Jesi never sees. The wines are leaner and slower to open."},
{"id": "c-qgw7i6ey", "cat": "Italy Central & South", "q": "A Montepulciano-based red comes off a limestone headland rising straight out of the Adriatic near Ancona. Name the wine.", "sa": 1, "accept": ["rosso conero", "conero", "rosso conero doc", "conero riserva"], "ans": "Rosso Conero", "exp": "Monte Conero is the only real promontory on that long flat coast, and its limestone gives a firmer wine than Montepulciano usually makes. Rosso Piceno, further south, blends the grape with Sangiovese instead."},
{"id": "c-bm6hdz2u", "cat": "Italy Central & South", "q": "A bishop's servant is said to have chalked his verdict on inn doors along the road to Rome near Lake Bolsena. Which wine took its name from that tale?", "opts": ["Cesanese del Piglio", "Est! Est!! Est!!! di Montefiascone", "Frascati Superiore", "Aleatico di Gradoli"], "a": 1, "exp": "The scout was sent ahead to mark where the wine was good, and doubled the word twice at Montefiascone. The story has outlived any reputation the wine itself holds."},
{"id": "c-uwewpdli", "cat": "Italy Central & South", "q": "Which grape is grown for Lazio's red DOCG, in the hills southeast of Rome toward Frosinone?", "opts": ["Nero Buono", "Cesanese", "Aleatico", "Ciliegiolo"], "a": 1, "exp": "Cesanese gives a perfumed, medium-bodied red with a faintly bitter finish, and the Piglio zone is its stronghold. Lazio's other DOCGs are both white and both at Frascati."},
{"id": "c-ndvwbnke", "cat": "Italy Central & South", "q": "Much of what reaches the bottle as Trebbiano d'Abruzzo is not Trebbiano Toscano. Which variety is often there instead?", "sa": 1, "accept": ["bombino bianco", "bombino", "bombino bianco grape", "trebbiano abruzzese", "bombino bianco or trebbiano abruzzese", "trebbiano abruzzese or bombino bianco"], "ans": "Bombino Bianco", "ex": 1, "exp": "The denomination permits Bombino Bianco as well as the distinct local Trebbiano Abruzzese, and the two have been confused in the vineyard for generations. The rare wines with real depth come from the local variety, not from Trebbiano Toscano."},
{"id": "c-c9ijyeac", "cat": "Italy Central & South", "q": "Teramo's hills in the north of Abruzzo carry the region's own DOCG for Montepulciano. What is it called?", "sa": 1, "accept": ["montepulciano d'abruzzo colline teramane", "colline teramane", "colline teramane docg", "montepulciano colline teramane", "montepulciano d'abruzzo colline teramane docg", "colline teramane montepulciano"], "ans": "Montepulciano d'Abruzzo Colline Teramane", "ex": 1, "exp": "Higher, cooler sites under the Gran Sasso give a firmer wine than the coastal plain does, and the ageing requirement is longer. The bulk of the region's Montepulciano is bottled at DOC level below it."},
{"id": "c-ieay1n9d", "cat": "Italy Central & South", "q": "A once nearly extinct Abruzzo white, now widely planted, shares its name with a sheep's cheese. Name the grape.", "sa": 1, "accept": ["pecorino", "pecorino grape", "pecorino bianco", "pecorino variety"], "ans": "Pecorino", "exp": "It was down to a handful of vines by the 1980s and is now the region's most fashionable white. Small berries and thick skins give it more weight and alcohol than Trebbiano."},
{"id": "c-rob2csc7", "cat": "Italy Central & South", "q": "Molise's native red variety was nearly lost and now carries a DOC of its own. Name it.", "sa": 1, "accept": ["tintilia", "tintilia del molise", "tintilia grape"], "ans": "Tintilia", "exp": "The name comes from a dialect word for dye, which describes the colour it gives. It grows best high inland, where Molise's hills climb toward the Apennine spine."},
{"id": "c-9k3ywii3", "cat": "Italy Central & South", "q": "Aglianico ripens so late in Irpinia that picking often runs into which month?", "opts": ["September", "November", "July", "August"], "a": 1, "exp": "It is among the last varieties harvested anywhere in Italy, and the long hang keeps acidity high while tannin slowly resolves. That combination is why Taurasi is built to age."},
{"id": "c-75l5978v", "cat": "Italy Central & South", "q": "Vines at Campi Flegrei grow in deep volcanic sand and many still stand on their own roots. What does that sand keep out?", "opts": ["Phylloxera, which cannot live in it", "Downy mildew, which cannot spread in it", "Spring frost, which cannot settle on it", "Botrytis, which cannot take hold in it"], "a": 0, "exp": "The louse cannot travel through loose siliceous sand to reach a root, so ungrafted vines survive there. Sardinia's Sulcis and Colares in Portugal depend on the same accident of soil."},
{"id": "c-f67k75zr", "cat": "Italy Central & South", "q": "Which pair of grapes makes the white and the red of Lacryma Christi del Vesuvio?", "opts": ["Coda di Volpe and Piedirosso", "Fiano and Sciascinoso", "Falanghina and Aglianico", "Greco and Casavecchia"], "a": 0, "exp": "Coda di Volpe means fox's tail and describes the shape of the bunch. Both grapes are grown on the volcano's ash and lava soils inside the national park."},
{"id": "c-m5i0189m", "cat": "Italy Central & South", "q": "The village that gives Greco di Tufo its name was long mined for a mineral used in the cellar. Which mineral?", "sa": 1, "accept": ["sulphur", "sulfur", "sulphur mines", "sulfur mines", "sulphur mining"], "ans": "Sulphur", "exp": "The mines closed decades ago but the smoky, struck-match note in the wine is still routinely traced to them. Sulphur remains the winemaker's principal antioxidant and antiseptic."},
{"id": "c-6m5kgfzl", "cat": "Italy Central & South", "q": "Which Campanian white takes on hazelnut and honey with age and is grown in the hills east of Naples?", "sa": 1, "accept": ["fiano di avellino", "fiano avellino", "fiano di avellino docg", "avellino fiano", "fiano", "fiano d'avellino"], "ans": "Fiano di Avellino", "exp": "Fiano is low-yielding and thick-skinned, and unusually for a southern white it improves for years in bottle. Altitude around Avellino supplies the acidity that makes the ageing possible."},
{"id": "c-lm13p4b1", "cat": "Italy Central & South", "q": "Campania's second red is nicknamed dove's foot for the colour of its stalks at harvest. Name the grape.", "sa": 1, "accept": ["piedirosso", "piedirosso grape", "per' e palummo", "pere e palummo"], "ans": "Piedirosso", "exp": "The stems turn red as the fruit ripens, which is what the dialect name records. It gives a softer, earlier-drinking wine than Aglianico and is often blended in to lighten it."},
{"id": "c-f176oott", "cat": "Italy Central & South", "q": "Vines on the Amalfi coast are worked on narrow terraces held by dry stone walls. Which DOC covers them?", "sa": 1, "accept": ["costa d'amalfi", "costa damalfi", "costa amalfi", "costa d'amalfi doc"], "ans": "Costa d'Amalfi", "exp": "Furore, Ravello and Tramonti are its named subzones, all of them tended by hand because no machine can reach the terraces. Some Tramonti vines are ungrafted and well over a century old."},
{"id": "c-s5wj4enl", "cat": "Italy Central & South", "q": "Head-trained bush vines stand free of wires across much of the Salento. What is that training system called in Italian?", "opts": ["Guyot", "Tendone", "Alberello", "Pergola"], "a": 2, "exp": "The vine forms its own low goblet, shading the fruit and needing no trellis in a dry, windy place. Yields are small and every operation has to be done by hand."},
{"id": "c-eo2dqw1k", "cat": "Italy Central & South", "q": "Castel del Monte takes its name from a thirteenth-century castle in Puglia. Which native red is bottled there at DOCG level as a Riserva?", "opts": ["Nero di Troia", "Primitivo", "Susumaniello", "Negroamaro"], "a": 0, "exp": "Nero di Troia, also called Uva di Troia, ripens late and carries firm tannin, so it needs the extra ageing a Riserva demands. It is the third of Puglia's major reds after Primitivo and Negroamaro."},
{"id": "c-iaxcwtki", "cat": "Italy Central & South", "q": "On the Ionian coast of Calabria, the Ciro zone builds its red on which grape?", "opts": ["Nerello Mascalese", "Nero d'Avola", "Magliocco", "Gaglioppo"], "a": 3, "exp": "Gaglioppo gives a pale, savoury, high-alcohol red with more tannin than its colour suggests. Magliocco is the region's other serious native red, grown further west and south."},
{"id": "c-cfvd04wg", "cat": "Italy Central & South", "q": "Puglia gained a DOCG for a naturally sweet style of Primitivo. Which town names it?", "sa": 1, "accept": ["manduria", "primitivo di manduria", "primitivo di manduria dolce naturale", "manduria in puglia"], "ans": "Manduria", "exp": "The sweet version stops fermentation while sugar remains rather than adding spirit, which is what naturale records. The dry Primitivo di Manduria from the same town stays at DOC."},
{"id": "c-2mk7ltck", "cat": "Italy Central & South", "q": "Salento's leading red carries a name usually read as black and bitter. Name the grape.", "sa": 1, "accept": ["negroamaro", "negro amaro", "negroamaro grape"], "ans": "Negroamaro", "exp": "The everyday reading is black and bitter, though philologists more often trace it to the Latin niger and the Greek mavros, both simply meaning black. It makes deep reds and some of Italy's best-regarded roses."},
{"id": "c-ca7ue8nd", "cat": "Italy Central & South", "q": "Basilicata's DOCG rank applies only to a longer-aged version of its one famous red. Which word marks that on the label?", "sa": 1, "accept": ["superiore", "aglianico del vulture superiore", "vulture superiore", "the word superiore"], "ans": "Superiore", "ex": 1, "exp": "The standard bottling remains a DOC and only the extended-ageing wine was promoted. Volcanic soils and altitude on the Vulture give the acidity that carries the wine through those years."},
{"id": "c-gwo4o1ts", "cat": "Italy Central & South", "q": "A sweet passito made in a town at the southern tip of Calabria carries the town's name. Name the wine.", "sa": 1, "accept": ["greco di bianco", "greco bianco", "greco di bianco doc", "greco di bianco passito"], "ans": "Greco di Bianco", "exp": "The grapes are dried on mats in the sun on a stretch of coast facing Sicily. The wine is amber, orange-scented and made in tiny quantity, and the town really is called Bianco."},
{"id": "c-2yz4dfi7", "cat": "Italy Central & South", "q": "Etna's vineyards are mapped by contrada. What does that term denote?", "opts": ["A named district of the mountain", "A style of low bush training", "A cooperative cellar shared by growers", "A grade of minimum ageing"], "a": 0, "exp": "The contrade are administrative parcels strung along the northern, eastern and southern flanks, the DOC leaving the west out, and growers now use them much as Burgundy uses climats, so many appear on labels. Soil, altitude and lava flow age change sharply between neighbouring ones."},
{"id": "c-ovzebh73", "cat": "Italy Central & South", "q": "One Marsala grade forbids the sweetening additions the others permit. Which grade is it?", "opts": ["Superiore", "Fine", "Superiore Riserva", "Vergine"], "a": 3, "exp": "Vergine takes no cooked must and no mistella, so it is dry and shaped entirely by long oxidative ageing. The other grades may be adjusted for colour and sweetness."},
{"id": "c-p0sfeptr", "cat": "Italy Central & South", "q": "Grillo arose as a crossing of which two Sicilian grapes?", "opts": ["Catarratto and Zibibbo", "Inzolia and Carricante", "Catarratto and Inzolia", "Grecanico and Nero d'Avola"], "a": 0, "exp": "The Muscat parent explains the faint grapey lift in a grape otherwise known for body and resistance to oxidation. Those qualities are why it became the backbone of good Marsala."},
{"id": "c-g07ci2de", "cat": "Italy Central & South", "q": "Etna Bianco Superiore may be grown in one commune only, on the eastern flank. Name it.", "sa": 1, "accept": ["milo", "milo commune", "commune of milo", "milo on etna"], "ans": "Milo", "exp": "Milo faces the Ionian sea and catches most of the rain that reaches the mountain, which suits Carricante's late ripening. The Superiore rules also demand a higher share of that grape."},
{"id": "c-lf68sc81", "cat": "Italy Central & South", "q": "Nerello Mascalese must lead an Etna Rosso, with a softer partner permitted alongside. Name that partner.", "sa": 1, "accept": ["nerello cappuccio", "cappuccio", "nerello mantellato", "nerello cappuccio grape"], "ans": "Nerello Cappuccio", "exp": "Cappuccio brings colour and flesh where Mascalese brings perfume, tannin and acidity. Its name describes the cloak of leaves the vine throws over itself."},
{"id": "c-kc34mg58", "cat": "Italy Central & South", "q": "Sweet passito from the Aeolian islands north of Sicily is named for the largest island of the group. Name the wine.", "sa": 1, "accept": ["malvasia delle lipari", "malvasia di lipari", "malvasia lipari", "malvasia delle lipari doc"], "ans": "Malvasia delle Lipari", "exp": "Salina rather than Lipari itself grows most of it, on volcanic terraces above the sea. The grapes are dried on racks and the wine comes out amber, apricot-scented and lightly herbal."},
{"id": "c-igxh381h", "cat": "Italy Central & South", "q": "Which Sicilian white is the island's most planted variety, long used as base wine for Marsala?", "sa": 1, "accept": ["catarratto", "catarratto bianco", "catarratto grape"], "ans": "Catarratto", "exp": "It crops generously and was for decades sent north or distilled rather than bottled with any ambition. Lower yields and earlier picking have shown it can make a serious dry white."},
{"id": "c-z6e95p7o", "cat": "Italy Central & South", "q": "Ungrafted bush vines more than a century old grow in deep sand in Sardinia's southwest. Which denomination covers them?", "opts": ["Nuragus di Cagliari", "Carignano del Sulcis", "Mandrolisai", "Cannonau di Sardegna"], "a": 1, "exp": "The sand of Sant'Antioco and the Sulcis coast defeated phylloxera, so old own-rooted alberello vines survive. The wine is fuller and riper than Carignan usually manages in France."},
{"id": "c-rfcq4y3d", "cat": "Italy Central & South", "q": "A Sardinian white ages under a film of yeast in part-filled casks in the Tirso valley. Which wine is it?", "opts": ["Nasco di Cagliari", "Vermentino di Sardegna", "Vernaccia di Oristano", "Malvasia di Bosa"], "a": 2, "exp": "The flor works as it does in Jerez, and the wine emerges dry, nutty and high in alcohol without being fortified. It has nothing to do with Vernaccia di San Gimignano in Tuscany."},
{"id": "c-ge32aayd", "cat": "Italy Central & South", "q": "Vermentino reaches its most concentrated form on the island in a northeastern zone of decomposed granite. Name that zone.", "sa": 1, "accept": ["gallura", "vermentino di gallura", "gallura zone", "gallura in the northeast"], "ans": "Gallura", "exp": "Granite sand drains fiercely and holds the vines short of water, which concentrates the fruit. The rest of the island bottles the grape under a broader denomination covering all of Sardinia."},
{"id": "c-9u9vg1ia", "cat": "Italy Central & South", "q": "Sardinia's Spanish centuries left a Catalan-speaking town in the northwest whose name marks a DOC. Name the town.", "sa": 1, "accept": ["alghero", "alghero doc", "alghero in sardinia", "town of alghero"], "ans": "Alghero", "exp": "Aragon repopulated the town from Catalonia in the fourteenth century and the language held. The DOC is unusually permissive, covering a long list of varieties in every colour."},
{"id": "c-18etdwil", "cat": "Italy Central & South", "q": "A white variety brought over from Spain survives almost nowhere but around Alghero. Name it.", "sa": 1, "accept": ["torbato", "torbato grape", "torbato di alghero"], "ans": "Torbato", "exp": "It nearly disappeared and was kept going by a single large producer in the town. The wine is dry, saline and firmer than most Mediterranean whites of its weight."},
{"id": "c-kb9j840l", "cat": "Italy Central & South", "q": "Which red grape gives Sardinia a light everyday DOC bottled under its own varietal name across much of the island?", "sa": 1, "accept": ["monica", "monica di sardegna", "monica grape"], "ans": "Monica", "exp": "Monica makes a soft, low-tannin red for drinking young, quite unlike Cannonau in weight. It is planted widely enough to carry an island-wide denomination of its own."},
{"id": "c-vcdxphco", "cat": "Italy North", "q": "Blue-grey compact marl in the western communes gives a Barolo that perfumes and softens earlier than one off the eastern ridge. Which soil formation supplies it?", "opts": ["Messinian", "Tortonian", "Serravallian", "Langhian"], "a": 1, "exp": "The Tortonian Sant'Agata Fossili marls under La Morra and Barolo hold water and give a rounder, more scented wine. The older Serravallian soils of Serralunga and Monforte carry more sand and sandstone and build a firmer, slower one."},
{"id": "c-z4s2onb3", "cat": "Italy North", "q": "Since 2010 a Barolo label may carry the name of a delimited vineyard site alongside the denomination. What is the official term for such a site?", "opts": ["Menzione Geografica Aggiuntiva", "Contrada", "Climat", "Sori"], "a": 0, "exp": "The MGA map put roughly 170 named sites on a legal footing, ending a century of informal cru names invented by producers. It records boundaries only and makes no claim about quality, unlike Burgundy's hierarchy."},
{"id": "c-1ihmfiw0", "cat": "Italy North", "q": "Iron-firm tannin and glacially slow evolution mark the wines of one narrow eastern ridge in the Barolo zone. Which commune sits along it?", "opts": ["Verduno", "La Morra", "Serralunga d'Alba", "Novello"], "a": 2, "exp": "The Serralunga ridge runs north to south on thin, pale, sandy limestone soils that keep vigour low. La Morra at the opposite edge of the zone gives the most fragrant and earliest-drinking style."},
{"id": "c-zau4p33w", "cat": "Italy North", "q": "Counting from the first of November after harvest, a Barbaresco may not be sold until how much time has passed?", "opts": ["Fifty months", "Thirty-eight months", "Eighteen months", "Twenty-six months"], "a": 3, "exp": "Twenty-six months in total, of which nine must be in wood; the Riserva runs to fifty. Barolo's clock is longer at both tiers, which is the practical difference a guest is most likely to taste."},
{"id": "c-s7q7rn4i", "cat": "Italy North", "q": "Of the thirty-eight months a Barolo must age before release, a fixed part has to pass in wood. How long in cask?", "sa": 1, "accept": ["eighteen months", "18 months", "eighteen months in cask", "eighteen months in wood", "18 months in cask", "18 months in wood"], "ans": "Eighteen months", "ex": 1, "exp": "The remaining time may be spent in bottle or in stainless steel, which is how an estate chasing a fresher style keeps oak influence down. Riserva raises the total to sixty-two months without raising the wood minimum."},
{"id": "c-t4wbz8r4", "cat": "Italy North", "q": "Fruit from a young plot, or a cru declassified in a difficult year, is usually bottled under a broader Nebbiolo denomination created in 1994. Name it.", "sa": 1, "accept": ["langhe nebbiolo", "langhe nebbiolo doc", "nebbiolo langhe doc"], "ans": "Langhe Nebbiolo", "exp": "Langhe is the catch-all denomination for the hills either side of the Tanaro and takes wines that fall outside the cru rules. Nebbiolo d'Alba is a separate and more tightly drawn DOC, and it excludes the Barolo and Barbaresco vineyards entirely."},
{"id": "c-the6agjw", "cat": "Italy North", "q": "Nearly all of the Barbaresco zone lies in three villages, with a fragment of Alba making up the rest. Name the three villages.", "sa": 1, "accept": ["barbaresco neive and treiso", "barbaresco neive treiso", "barbaresco treiso and neive", "barbaresco treiso neive", "neive barbaresco and treiso", "neive barbaresco treiso", "neive treiso and barbaresco", "neive treiso barbaresco", "treiso barbaresco and neive", "treiso barbaresco neive", "treiso neive and barbaresco", "treiso neive barbaresco"], "ans": "Barbaresco, Neive and Treiso", "ex": 1, "exp": "Barbaresco itself sits lowest and warmest by the river, Neive to the east, Treiso highest and coolest to the south. The remainder is the San Rocco Seno d'Elvio quarter of Alba."},
{"id": "c-ap1mnuuj", "cat": "Italy North", "q": "One Langhe vineyard was already being named on bottles in 1752, well over a century before anyone drew a cru map. Name that site.", "sa": 1, "accept": ["cannubi", "cannubi vineyard", "the cannubi site", "cannubi in barolo"], "ans": "Cannubi", "exp": "The hill sits in the middle of the Barolo commune where the Tortonian and Serravallian soils meet, which is the usual explanation for its balance of scent and structure. That 1752 bottle predates Barolo as a dry wine altogether."},
{"id": "c-fohdcgnf", "cat": "Italy North", "q": "Cinchona bark, rhubarb root and spices steeped in a Langhe red produce a digestivo often poured at the end of service. Name that drink.", "sa": 1, "accept": ["barolo chinato", "chinato", "barolo chinato digestivo"], "ans": "Barolo Chinato", "exp": "China is the Italian for cinchona, the quinine bark, which is where the bitterness and the name come from. It began as a nineteenth-century pharmacy tonic and is now the classic partner for dark chocolate."},
{"id": "c-gwnqxy2i", "cat": "Italy North", "q": "Rose petal and a faintly bitter finish mark a red DOCG grown in a handful of communes around Castagnole Monferrato. Which grape gives it?", "opts": ["Freisa", "Malvasia di Casorzo", "Ruche", "Pelaverga"], "a": 2, "exp": "Ruche is aromatic in a way almost no other Italian red is, closer to a Moscato lift than to Nebbiolo tar. It is grown nowhere else of consequence, so the wine and the place are effectively the same thing."},
{"id": "c-idbihki2", "cat": "Italy North", "q": "A pale Piedmontese red carries far more tannin than its colour suggests, because its berries hold an unusual number of pips. Which grape is it?", "opts": ["Uva Rara", "Grignolino", "Vespolina", "Freisa"], "a": 1, "exp": "The name traces to grignole, dialect for pips, and the berries can hold four or five where most grapes hold two. Skin contact therefore has to be brief, which is why the wine stays so light in colour while finishing firm."},
{"id": "c-kkromzge", "cat": "Italy North", "q": "North of Turin one white grape serves for a dry wine, for a metodo classico and for a passito, all under a single denomination. Which grape?", "opts": ["Erbaluce", "Favorita", "Arneis", "Nascetta"], "a": 0, "exp": "Erbaluce di Caluso covers all three styles, which is unusual for one DOCG. High acidity is what makes the grape work in every register, including a passito dried for years."},
{"id": "c-sp3b66nn", "cat": "Italy North", "q": "Raspberry and rose scent a sweet, lightly sparkling red made around Acqui Terme. Which grape is pressed for it?", "opts": ["Freisa", "Croatina", "Bonarda Piemontese", "Brachetto"], "a": 3, "exp": "Brachetto is an aromatic red in the Muscat mould and is fermented only partway, so alcohol stays low and grape perfume survives. It is the red counterpart to Moscato d'Asti in both style and purpose."},
{"id": "c-t79ac2j5", "cat": "Italy North", "q": "One grower in the Colli Tortonesi revived a nearly extinct white from the 1980s, and it now makes Piedmont's longest-lived dry white. Name the grape.", "sa": 1, "accept": ["timorasso", "timorasso grape", "timorasso variety"], "ans": "Timorasso", "exp": "It had been pulled out in favour of easier, higher-cropping varieties and survived in scraps of old vineyard. The wines start closed and waxy and take on a kerosene and honey character over five to ten years, which is why they are so often compared to Riesling."},
{"id": "c-7dsdvpbe", "cat": "Italy North", "q": "Asti's bubbles come from a single fermentation of must in a sealed tank, halted while sugar still remains. What is that tank process called in Italy?", "sa": 1, "accept": ["metodo martinotti", "martinotti", "martinotti method", "charmat", "metodo charmat", "charmat method"], "ans": "Metodo Martinotti", "exp": "Federico Martinotti patented the sealed-tank idea in Asti before Eugene Charmat built the machinery in France, which is why Italy uses the Italian name. Crucially there is no second fermentation here at all: the wine never finishes the first one."},
{"id": "c-oinq7t97", "cat": "Italy North", "q": "Piedmont's traditional-method sparkling DOCG must be vintage-dated and rest at least thirty months on its lees. Name it.", "sa": 1, "accept": ["alta langa", "alta langa docg", "alta langa metodo classico"], "ans": "Alta Langa", "exp": "Pinot Nero and Chardonnay, alone or together, must supply at least ninety percent, with up to a tenth from other non-aromatic Piedmontese varieties. The vines sit high in the hills south of the Langhe where Nebbiolo would never ripen. The compulsory vintage date is the detail that separates it from most Italian metodo classico."},
{"id": "c-q0ep0os0", "cat": "Italy North", "q": "Dolcetto's most structured expression carries a DOCG named for a town in the southern Langhe. Name that town.", "sa": 1, "accept": ["dogliani", "dogliani docg", "dolcetto di dogliani", "dogliani in the langhe"], "ans": "Dogliani", "exp": "Older vines on steeper, poorer slopes give a Dolcetto with real grip and a bitter-almond finish that repays a few years. Diano d'Alba and Ovada are the other zones where the grape is taken seriously rather than treated as an everyday red."},
{"id": "c-9sjb8um6", "cat": "Italy North", "q": "The Sesia river divides Alto Piemonte's two DOCGs between separate provinces. Which of them lies on the western bank?", "opts": ["Boca", "Gattinara", "Lessona", "Ghemme"], "a": 1, "exp": "Gattinara sits west of the Sesia in the province of Vercelli, Ghemme east of it in Novara. Both are Nebbiolo, called Spanna here, and both may be softened with a little Vespolina or Uva Rara."},
{"id": "c-pl5w8keu", "cat": "Italy North", "q": "Pink acidic volcanic rock left by a collapsed supervolcano underlies the vineyards at Boca. What is that rock called?", "opts": ["Schist", "Porphyry", "Gneiss", "Limestone"], "a": 1, "exp": "The Valsesia caldera collapsed and tipped on its side, which exposed the whole plumbing of a volcano at the surface. Porphyry soils are acidic and iron-rich, and the Nebbiolo grown on them comes out paler and more savoury than in the Langhe."},
{"id": "c-l8eslyly", "cat": "Italy North", "q": "Ungrafted vines on low pergolas above a thousand metres beneath Mont Blanc are planted to which white grape?", "opts": ["Nascetta", "Prie Blanc", "Erbaluce", "Moscato Bianco"], "a": 1, "exp": "Blanc de Morgex et de La Salle is among the highest vineyard land in Europe, and the altitude is what has kept phylloxera out. The pergolas are kept knee-high so the stone underneath radiates warmth back at the fruit."},
{"id": "c-itbaia89", "cat": "Italy North", "q": "Stone-pillared pergolas terrace a steep Nebbiolo vineyard at Piedmont's northern boundary with Valle d'Aosta. Which denomination is made there?", "sa": 1, "accept": ["carema", "carema doc", "carema in piedmont", "the carema denomination"], "ans": "Carema", "exp": "The masonry pillars, called pilun, store the day's heat and give it back at night in a place that is marginal for the grape. Everything is worked by hand on terraces too narrow for a machine."},
{"id": "c-boinaakr", "cat": "Italy North", "q": "Crossing out of Piedmont into Valle d'Aosta, Nebbiolo changes name once again. What is it called there?", "sa": 1, "accept": ["picotendro", "picotener", "picoutener", "picotendro or picotener"], "ans": "Picotendro", "exp": "Donnas is the valley's Nebbiolo denomination, sitting just upstream of Carema on the same stretch of the Dora Baltea. Chiavennasca in Valtellina and Spanna in Alto Piemonte are the other regional names for the identical grape."},
{"id": "c-ut5ov620", "cat": "Italy North", "q": "A white variety shared with the Swiss Valais gives Valle d'Aosta a saline, high-acid wine of real concentration. Name that grape.", "sa": 1, "accept": ["petite arvine", "arvine", "petite arvine grape", "arvine grape"], "ans": "Petite Arvine", "exp": "The upper Rhone and the upper Dora Baltea sit either side of the same Alpine watershed, and varieties crossed the passes long before borders mattered. Cornalin made the same journey and is the Valais's Humagne Rouge, while Fumin and Petit Rouge are Aosta natives."},
{"id": "c-9vnolvf8", "cat": "Italy North", "q": "One Franciacorta style is bottled at lower pressure and may use no black grapes at all. What is it called?", "opts": ["Saten", "Rose", "Dosaggio Zero", "Riserva"], "a": 0, "exp": "Saten is made only from Chardonnay and Pinot Bianco and finished under about five atmospheres rather than six, which softens the mousse. It is always Brut, so the silkiness comes from pressure and blend rather than from sugar."},
{"id": "c-qrqhd1vn", "cat": "Italy North", "q": "Sassella, Grumello, Inferno and Valgella are named subzones of one Lombard denomination. Which one?", "opts": ["Oltrepo Pavese", "Valtellina Superiore", "Lugana", "Franciacorta"], "a": 1, "exp": "Maroggia is the fifth. All five sit on the south-facing terraces of the Adda valley, where Nebbiolo is called Chiavennasca and every operation is done by hand."},
{"id": "c-wusonuuh", "cat": "Italy North", "q": "In the Oltrepo Pavese a red sold as Bonarda is pressed from a differently named variety. Which grape is actually in the bottle?", "opts": ["Vespolina", "Barbera", "Croatina", "Uva Rara"], "a": 2, "exp": "The true Bonarda Piemontese is a separate grape grown further west, and the two are regularly confused on a list. Oltrepo Bonarda is Croatina, usually frizzante, soft and faintly bitter."},
{"id": "c-qixzscbh", "cat": "Italy North", "q": "Franciacorta's Riserva tier demands a very long stay on the lees before disgorgement. How long?", "sa": 1, "accept": ["sixty months", "60 months", "five years", "5 years", "sixty months on the lees", "60 months on the lees", "five years on the lees", "sixty", "60"], "ans": "Sixty months", "ex": 1, "exp": "Riserva must also be vintage-dated, so the ageing and the harvest statement travel together. A non-vintage Franciacorta needs eighteen months on lees and a Millesimato thirty."},
{"id": "c-7zyl7br8", "cat": "Italy North", "q": "The white grown on clay flats at the southern end of Lake Garda goes under a local name, though DNA work has tied it to Verdicchio. Name it.", "sa": 1, "accept": ["turbiana", "trebbiano di lugana", "turbiana or trebbiano di lugana", "trebbiano di lugana or turbiana"], "ans": "Turbiana", "exp": "Lugana was long labelled Trebbiano di Lugana, which invited the assumption that it belonged with the undistinguished Trebbiano Toscano. It does not: the grape is Verdicchio, and the heavy clay is what gives the wine its weight and its capacity to age."},
{"id": "c-v6si61cq", "cat": "Italy North", "q": "Dried Moscato grapes make a sweet red with a DOCG of its own in a single commune near Bergamo. Name the wine.", "sa": 1, "accept": ["moscato di scanzo", "moscato di scanzo docg", "scanzo", "moscato scanzo"], "ans": "Moscato di Scanzo", "exp": "The variety is a dark-berried Moscato found essentially nowhere else, dried on racks and then aged for two years. The zone is measured in tens of hectares, so bottles rarely leave the province."},
{"id": "c-2vlwxgrz", "cat": "Italy North", "q": "Nebbiolo dried in ventilated lofts through the autumn gives Valtellina a red of at least fourteen percent alcohol. Name that wine.", "sa": 1, "accept": ["sforzato di valtellina", "sforzato", "sfursat", "sfursat di valtellina", "sforzato valtellina"], "ans": "Sforzato di Valtellina", "exp": "Sfursat is the dialect form and appears on plenty of labels. Both it and Amarone are legally dry, each disciplinare capping residual sugar, and the fourteen percent floor here is written into the rules."},
{"id": "c-8uvk5222", "cat": "Italy North", "q": "Franciacorta sits on stony debris pushed into low hills by a glacier retreating from Lake Iseo. What is that landform called?", "sa": 1, "accept": ["moraine", "glacial moraine", "morainic hills", "moraine amphitheatre"], "ans": "Moraine", "exp": "The amphitheatre of moraine drains hard and warms early, which suits early-picked base wine for sparkling. Lugana on the other side of the lake district sits on the heavy clay the same glaciers left behind instead."},
{"id": "c-nb7s3xai", "cat": "Italy North", "q": "A large-berried Valpolicella grape was long taken for a clone of Corvina and proved to be a variety in its own right. Which is it?", "opts": ["Rondinella", "Corvinone", "Dindarella", "Oseleta"], "a": 1, "exp": "Corvinone ripens later and holds thicker skins, which is why growers value it for drying. The rules now let it stand in for a share of the Corvina in the blend."},
{"id": "c-o29vs5da", "cat": "Italy North", "q": "Besides Classico, only one valley name may be added to a Valpolicella label. Which name?", "opts": ["Illasi", "Marano", "Valpantena", "Negrar"], "a": 2, "exp": "Valpantena runs north from Verona just east of the Classico hills and has its own long-standing reputation. Negrar and Marano are Classico communes and Illasi lies in the eastern valleys, but none of them may appear as a denomination on its own."},
{"id": "c-0x4tqbvt", "cat": "Italy North", "q": "Of the three grapes traditionally written into the Valpolicella blend, one is no longer compulsory. Which one?", "opts": ["Molinara", "Rondinella", "Corvinone", "Corvina"], "a": 0, "exp": "Molinara is pale and low in tannin, and many growers felt it thinned the wine, so it became optional. Corvina still has to lead, with Rondinella filling a defined minority share."},
{"id": "c-faxq1d5x", "cat": "Italy North", "q": "Reckoned from the first of January after the harvest, how long must an Amarone rest before it may be released?", "opts": ["Six months", "Four years", "Two years", "Seven years"], "a": 2, "exp": "Two years for the standard wine on that January clock, while the Riserva runs four years from the first of November of the harvest year. Most estates hold it far longer than the rule asks, because the tannin drawn out of shrivelled fruit takes time to settle."},
{"id": "c-gjyyjtf7", "cat": "Italy North", "q": "Soave Classico covers the hills of the walled town itself and those of one neighbouring commune. Name that commune.", "sa": 1, "accept": ["monteforte d'alpone", "monteforte", "monteforte dalpone", "commune of monteforte d'alpone"], "ans": "Monteforte d'Alpone", "exp": "The Classico zone straddles a boundary between two geologies, calcareous ground on the Soave side and volcanic on the Monteforte side. Everything beyond those hills is plain Soave, much of it grown on the flat."},
{"id": "c-bhrkwrus", "cat": "Italy North", "q": "Dark rock laid down by undersea eruptions underlies Soave's finest hills and is credited for the wine's saline tension. Name that rock.", "sa": 1, "accept": ["basalt", "basaltic rock", "volcanic basalt", "basalt lava"], "ans": "Basalt", "exp": "The eruptions happened underwater in the Eocene, which is why the basalt sits interleaved with marine limestone. Growers separate the two: basalt sites give a tighter, smokier Garganega, limestone a softer and more floral one."},
{"id": "c-erek37i5", "cat": "Italy North", "q": "Veneto's first DOCG, granted in 1998, was not a dry wine at all but a sweet one from dried grapes. Name it.", "sa": 1, "accept": ["recioto di soave", "recioto di soave docg", "recioto soave", "soave recioto"], "ans": "Recioto di Soave", "exp": "Garganega dries well because its skins are thick and its bunches loose, so air moves through them. Recioto della Valpolicella is the red equivalent and a different wine entirely, which is why the second half of the name is the part that matters."},
{"id": "c-2s6py4yb", "cat": "Italy North", "q": "Bunches for Amarone spend the winter in a purpose-built loft with through-draughts on every side. What is that room called in Italian?", "sa": 1, "accept": ["fruttaio", "il fruttaio", "fruttai", "the fruttaio loft"], "ans": "Fruttaio", "exp": "Airflow, not warmth, is what keeps rot off the fruit, so the lofts are built high and open with fans now doing what the wind used to. Bunches are laid in single layers on racks or in shallow crates so nothing touches."},
{"id": "c-uvbvf4to", "cat": "Italy North", "q": "On a Conegliano Valdobbiadene label one word introduces a single steep hillside belonging to a named village. Which word?", "opts": ["Rive", "Sori", "Contrada", "Bricco"], "a": 0, "exp": "There are forty-three of them, and a Rive wine must be hand-harvested and carry a vintage. The word is the local dialect for a steep slope rather than a legal quality tier."},
{"id": "c-earrbh7u", "cat": "Italy North", "q": "A cloudy Prosecco refermented in bottle and left undisgorged on its lees carries which traditional name?", "opts": ["Passito", "Ripasso", "Chiaretto", "Col Fondo"], "a": 3, "exp": "Col fondo means with the bottom, and the sediment is meant to be there. It was the farmhouse style before tanks arrived, and it comes out drier, savoury and gently hazy."},
{"id": "c-0795102m", "cat": "Italy North", "q": "Volcanic hills between Soave and Vicenza grow a white grape so high in acid that it is used almost only for sparkling wine. Which grape?", "opts": ["Vespaiola", "Tai", "Durella", "Garganega"], "a": 2, "exp": "Durella takes its name from the hardness of its skin and keeps searing acidity even when fully ripe. Long lees ageing is what makes the traditional-method wines approachable, though tank method still accounts for the larger share of production."},
{"id": "c-wgii29u8", "cat": "Italy North", "q": "Within Valdobbiadene a single steep hill of about a hundred hectares is the most prized site of the whole denomination. Name it.", "sa": 1, "accept": ["cartizze", "superiore di cartizze", "cartizze hill", "valdobbiadene superiore di cartizze"], "ans": "Cartizze", "exp": "The slope is so steep that everything is carried by hand, and it is traditionally finished slightly sweeter than the rest of the zone. Land there is among the most expensive vineyard in Italy."},
{"id": "c-w10d5lly", "cat": "Italy North", "q": "At Breganze, bunches of Vespaiola are twisted onto wires and hung to shrivel for a sweet wine. Name that wine.", "sa": 1, "accept": ["torcolato", "breganze torcolato", "torcolato di breganze"], "ans": "Torcolato", "exp": "Torcolato comes from torcere, to twist, which is exactly what is done to the bunches before they are hung. The grape keeps ferocious acidity, so the finished wine is sweet without being cloying."},
{"id": "c-twen10fr", "cat": "Italy North", "q": "South of Lake Garda a white blend shares its stretch of morainic hills with Bardolino. Name that denomination.", "sa": 1, "accept": ["bianco di custoza", "custoza", "custoza doc", "bianco di custoza doc"], "ans": "Bianco di Custoza", "exp": "The blend leans on Garganega with Trebbiano Toscano, Friulano and Cortese filling it out, so it drinks rounder than Soave from the same lead grape. The zone sits almost wholly inside the southern half of Bardolino, which runs a good deal further north up the lake, and many estates make both."},
{"id": "c-pvaad5sa", "cat": "Italy North", "q": "Volcanic cones rise straight out of the plain southwest of Padua and carry a DOCG for sweet Moscato Giallo. Name those hills.", "sa": 1, "accept": ["colli euganei", "euganei", "euganean hills", "colli euganei docg"], "ans": "Colli Euganei", "exp": "The wine is Fior d'Arancio, orange blossom, which is exactly what Moscato Giallo smells of. The hills are old volcanic intrusions that never erupted through the surface, so they stand isolated above flat farmland."},
{"id": "c-t77auzj4", "cat": "Italy North", "q": "Layered marl and sandstone flysch underlies the Collio, and growers there have their own word for it. What is that word?", "opts": ["Ponca", "Alberese", "Tufo", "Galestro"], "a": 0, "exp": "Ponca weathers quickly into a shallow, poor, free-draining soil that vines root into readily. It is the same Eocene flysch that continues over the border into Slovenian Brda under the name opoka."},
{"id": "c-4sk3igue", "cat": "Italy North", "q": "A Friulian sweet-wine grape sets only a fraction of the flowers it opens, so its yields are minute. Which grape?", "opts": ["Picolit", "Ribolla Gialla", "Refosco", "Verduzzo"], "a": 0, "exp": "The condition is called floral abortion, and it leaves bunches with a scatter of berries and plenty of air between them. Those loose bunches dry beautifully, which is the one advantage of an otherwise ruinous defect."},
{"id": "c-ct7g4689", "cat": "Italy North", "q": "Verduzzo Friulano dried for a golden sweet wine holds DOCG rank in the hills above Nimis. Name that wine.", "sa": 1, "accept": ["ramandolo", "ramandolo docg", "verduzzo di ramandolo"], "ans": "Ramandolo", "exp": "Verduzzo is unusual among sweet-wine grapes for its tannin, which comes off the skins and gives the wine grip against the sugar. The zone is tiny, steep and among the coldest vineyard land in the region."},
{"id": "c-mq61v321", "cat": "Italy North", "q": "A peppery Friulian red also known as Ribolla Nera was rescued from near extinction in the 1970s. Name the grape.", "sa": 1, "accept": ["schioppettino", "schioppettino grape", "the schioppettino variety"], "ans": "Schioppettino", "exp": "It was left off the permitted list after the war and survived in a few old plots around Prepotto until growers pushed to have it reinstated. The black pepper note comes from rotundone, the same compound that marks cool-climate Syrah."},
{"id": "c-69h8h8il", "cat": "Italy North", "q": "Iron-red soil over fissured limestone on the Slovenian border grows Vitovska and Terrano. Name that plateau.", "sa": 1, "accept": ["carso", "carso doc", "kras", "carso plateau"], "ans": "Carso", "exp": "The karst is riddled with sinkholes and caves, and the little soil there is collects in pockets between bare rock. The bora wind off the northeast is fierce enough to shape how vines are trained."},
{"id": "c-z8cn1q0e", "cat": "Italy North", "q": "Skin-fermented Ribolla Gialla made one border village the address most associated with Friulian orange wine. Name the village.", "sa": 1, "accept": ["oslavia", "oslavia in collio", "village of oslavia"], "ans": "Oslavia", "exp": "Long skin macerations were revived there in the mid-1990s, in wood, and buried Georgian qvevri followed with Gravner's 2001 vintage. Ribolla Gialla suits the treatment because its skins are thick and its acidity high."},
{"id": "c-9pm91mvz", "cat": "Italy North", "q": "Deep-coloured Lagrein has its historic home in one quarter on the edge of Bolzano. Which one?", "opts": ["Termeno", "Cortaccia", "Appiano", "Gries"], "a": 3, "exp": "The alluvial gravel at Gries is warm and free-draining, which suits a late-ripening variety on a valley floor. Lagrein is a descendant of Teroldego and shows the same dark colour and bitter-cherry edge."},
{"id": "c-fe52u3q3", "cat": "Italy North", "q": "Italy's first denomination created specifically for traditional-method sparkling wine sits in the mountains along the upper Adige. Which denomination?", "opts": ["Conegliano Valdobbiadene", "Franciacorta", "Asti", "Trento DOC"], "a": 3, "exp": "Trento was recognised in 1993 for metodo classico alone, drawing on vineyards planted high on both valley walls. Altitude supplies the acidity that a base wine for sparkling needs."},
{"id": "c-bkz54tln", "cat": "Italy North", "q": "Pinot Bianco that stays fresh for decades comes from a village on porphyry sand west of Bolzano. Name that village.", "sa": 1, "accept": ["terlano", "terlan", "terlano doc", "terlaner"], "ans": "Terlano", "exp": "The sandy quartz porphyry soils are unusually rich in potassium, which growers there credit for the wine's structure and longevity. Old bottles are released from the cellar as Rarita after at least ten years on the lees."},
{"id": "c-a8dhg66e", "cat": "Italy North", "q": "Sylvaner, Kerner and Gruner Veltliner grow up a narrow valley running from Bolzano toward the Brenner pass. Name that valley.", "sa": 1, "accept": ["valle isarco", "eisacktal", "eisacktaler", "isarco valley", "valle isarco eisacktal"], "ans": "Valle Isarco", "exp": "It is the coldest and highest of Alto Adige's zones, which is why the grape list reads more Austrian than Italian. The wines are lean, high-acid and aromatic rather than broad."},
{"id": "c-ne2skazq", "cat": "Italy North", "q": "Trentino's one notable native white is dried on racks until Holy Week to make the region's Vino Santo. Name the grape.", "sa": 1, "accept": ["nosiola", "nosiola grape", "nosiola variety"], "ans": "Nosiola", "exp": "The drying runs about six months, far longer than most passito, and botrytis is welcomed on the way. The name comes from nocciola, hazelnut, which is what the dry version tastes of."},
{"id": "c-vz9zxdcb", "cat": "Italy North", "q": "Mozart's Don Giovanni calls for a dark, soft red from Trentino by name in its final act. Name the grape.", "sa": 1, "accept": ["marzemino", "marzemino grape", "marzemino d'isera"], "ans": "Marzemino", "exp": "Isera in the Vallagarina is its stronghold, on basalt soils south of Rovereto. The wine is fragrant and low in tannin, meant to be drunk within a few years rather than kept."},
{"id": "c-lffykapg", "cat": "Italy North", "q": "Pigato turned out under DNA analysis to be the same variety as a white already planted the length of the northwest coast. Which one?", "opts": ["Bosco", "Albarola", "Cortese", "Vermentino"], "a": 3, "exp": "Pigato is a mutation of Vermentino with freckled skins, which is what the name records. Growers still bottle the two separately because the clones behave differently in the vineyard and in the glass."},
{"id": "c-tq9bkub7", "cat": "Italy North", "q": "One Lambrusco sets fruit so poorly that its wine comes out pale pink and unusually sharp. Which one?", "opts": ["Lambrusco Maestri", "Lambrusco Grasparossa di Castelvetro", "Lambrusco di Sorbara", "Lambrusco Salamino di Santa Croce"], "a": 2, "exp": "Sorbara flowers badly and drops much of its crop, leaving thin bunches with little colour to give. Grasparossa at the other end of the scale is dark, tannic and much fuller bodied."},
{"id": "c-nc7pigon", "cat": "Italy North", "q": "The first Italian white ever raised to DOCG, back in 1987, grows in the hills of Romagna. Name the grape.", "sa": 1, "accept": ["albana", "albana di romagna", "romagna albana", "albana grape"], "ans": "Albana", "exp": "The promotion was controversial at the time because the wine was thought not to merit it, and it pushed the authorities to be stricter afterwards. Albana has thick skins, so it takes to both skin contact and drying for passito."},
{"id": "c-2m4oc9oj", "cat": "Italy North", "q": "Grapes dried in lofts above the terraced cliffs of the Cinque Terre make a rare sweet wine sold in small bottles. Name it.", "sa": 1, "accept": ["sciacchetra", "sciacchetra passito", "sciacchetra di cinque terre"], "ans": "Sciacchetra", "exp": "Bosco leads the blend with Albarola and Vermentino alongside, all of it carried off terraces reachable only on foot or by rack railway. Yields after drying are so small that a few bottles come from a whole day's picking."},
{"id": "c-ax53i7uw", "cat": "Jura, Savoie & Corsica", "q": "Green walnut, curry spice and a saline edge: whichever village makes it, vin jaune begins as a single permitted variety. Name it.", "sa": 1, "accept": ["savagnin", "savagnin blanc", "savagnin grape", "only savagnin", "savagnin only", "100 savagnin", "100% savagnin"], "ans": "Savagnin", "ex": 1, "exp": "Savagnin is the whole recipe: not even Chardonnay, the Jura's most planted grape, may enter a vin jaune. A member of the Traminer family, it hangs late into the autumn and keeps the acidity that carries the wine through its long years in cask."},
{"id": "c-szc55k34", "cat": "Jura, Savoie & Corsica", "q": "From harvest to the earliest legal bottling, the wine that will become vin jaune waits longer in cask than any other unfortified wine of France. State the minimum wait.", "sa": 1, "accept": ["six years and three months", "six years three months", "6 years and 3 months", "6 years 3 months", "75 months", "seventy five months", "six and a quarter years", "six years and three months in cask", "six years and three months in barrel", "six years and three months in oak", "six years and three months from harvest", "at least six years and three months", "minimum of six years and three months", "six years and three months minimum", "minimum six years and three months", "six years and three months under the veil", "six years and three months under voile", "6 years and three months", "six years and 3 months", "6 years and 3 months minimum", "minimum 6 years and 3 months", "at least 6 years and 3 months", "minimum of 6 years and 3 months", "6 years and 3 months in cask", "6 years and 3 months in barrel", "6 years and 3 months in oak", "6 years and 3 months from harvest", "at least 75 months", "75 months minimum", "minimum 75 months", "75 months from harvest", "six years and three months of ageing", "six years and three months of aging", "six years and three months ageing", "six years and three months aging", "6 years 3 months minimum", "75 months in cask"], "ans": "Six years and three months", "ex": 1, "exp": "Six years and three months separate the picking from the bottle, and for at least sixty of those months the voile of yeast must be at work on the untopped cask. Nothing is refilled as the level falls, and over a third of the wine is surrendered to the air before a drop is sold."},
{"id": "c-pnihqi3b", "cat": "Jura, Savoie & Corsica", "q": "Just 62 centilitres, squat and heavy-shouldered: the law reserves one bottle for the Jura's vin jaune and permits it no other. Name it.", "sa": 1, "accept": ["clavelin", "clavelin bottle"], "ans": "Clavelin", "exp": "The clavelin holds what is left of a litre, so the story runs, after the years of evaporation under the voile, the missing thirty-eight centilitres having gone to the angels. French law reserves the shape for vin jaune, so the bottle announces the style across the room."},
{"id": "c-tl8iktoo", "cat": "Jura, Savoie & Corsica", "q": "Chardonnay grown inside Chateau-Chalon's boundary can never be sold as Chateau-Chalon. Which appellation takes it as a still, unfortified wine instead?", "opts": ["Arbois", "Cotes du Jura", "L'Etoile", "Macvin du Jura"], "a": 1, "exp": "Chateau-Chalon's decree admits one wine only, Savagnin aged under the voile, so there is no white, red or sparkling version to fall back on. As still wine, Chardonnay from those marls sells under the regional Cotes du Jura, the name that catches what the stricter appellations exclude; the fruit's only other legal exits are the sparkling Cremant du Jura and the mistelle Macvin du Jura."},
{"id": "c-iv4dwqns", "cat": "Jura, Savoie & Corsica", "q": "Pear, white flowers and not a walnut in sight: a modern Arbois Savagnin spent its cask life topped full to the bung. What word on the label announces that choice?", "sa": 1, "accept": ["ouille", "ouillage", "topped up", "kept topped up", "topped up ouille", "ouille topped up", "ouille or topped up", "topped up or ouille", "ouille style"], "ans": "Ouille", "ex": 1, "exp": "Ouille is from ouillage, the topping up of casks: the evaporated share is replaced, no voile forms, and the Savagnin stays pale, floral and tense. Sous-voile is the opposite cellar path, aged under the yeast film that brings walnut and spice, and Jura lists now sort their whites by these two words."},
{"id": "c-atik02zq", "cat": "Jura, Savoie & Corsica", "q": "Pupillin, a hamlet above Arbois, styles itself the world capital of a red grape so thin-skinned its wines pass for dark rose. Name the grape.", "sa": 1, "accept": ["poulsard", "ploussard"], "ans": "Poulsard", "exp": "Poulsard, spelled Ploussard around Pupillin itself, covers more of the Jura's red vineyard than any other variety. Big berries and thin skins give a wine the colour of faded cherry even after weeks on the skins, which is why it drinks as a red that behaves like something lighter."},
{"id": "c-wzfwfb1u", "cat": "Jura, Savoie & Corsica", "q": "Warm gravels around Montigny-les-Arsures suit the Jura's most demanding red grape, darker and firmer than its famous pale neighbour. Name it.", "sa": 1, "accept": ["trousseau", "trousseau noir", "trousseau grape"], "ans": "Trousseau", "ex": 1, "exp": "Trousseau is the Jura's late ripener, and it concentrates on the warm, well-drained gravels around Montigny-les-Arsures, the village that calls itself its capital. It has been a quiet winner from the warming summers, and plantings are creeping up again."},
{"id": "c-0u2bktzz", "cat": "Jura, Savoie & Corsica", "q": "Fossilised star-shaped segments of sea lilies litter the marl around one village near Lons-le-Saunier, and its white-wine appellation is named for them. Which appellation?", "sa": 1, "accept": ["l'etoile", "etoile", "letoile"], "ans": "L'Etoile", "exp": "L'Etoile, the star, takes its name from the five-pointed fossil stems of sea lilies scattered through its marls, with a local embellishment that five hills ring the village in a star as well. The appellation is for white wine only, Chardonnay and Savagnin above all with a little white-pressed Poulsard permitted, in every Jura idiom from ouille to the veil-aged."},
{"id": "c-linr946b", "cat": "Jura, Savoie & Corsica", "q": "Straight from the press, Jura juice meets the region's oak-aged marc before any yeast can work, and the sweet result holds an AOC of its own. Name it.", "sa": 1, "accept": ["macvin du jura", "macvin"], "ans": "Macvin du Jura", "exp": "Macvin du Jura is a mistelle: the marc's strength stops fermentation before it starts, so the sweetness is grape sugar that never met a working yeast. The AOC arrived in 1991, all three colours are made, and most of it is poured cold as an aperitif in its home region."},
{"id": "c-kjm5utxp", "cat": "Jura, Savoie & Corsica", "q": "Five varieties, and only five, may enter the Jura's appellation wines. Savagnin and Chardonnay are two; which trio completes the list?", "opts": ["Poulsard, Trousseau and Pinot Noir", "Poulsard, Mondeuse Noire and Pinot Noir", "Trousseau, Gamay and Mondeuse Noire", "Poulsard, Trousseau and Gamay"], "a": 0, "exp": "Pinot Noir is the fifth, grown in the Jura for centuries as a blending partner and increasingly on its own. Gamay never earned a place despite Burgundy sitting an hour away, and every appellation of the region, still or sparkling, builds from some arrangement of the five."},
{"id": "c-b3qef7kz", "cat": "Jura, Savoie & Corsica", "q": "In November 1248 the face of Mont Granier tore away and buried a string of parishes; vines followed onto the rubble, and two Savoie crus grow on it today. Name the pair.", "sa": 1, "accept": ["apremont and abymes", "abymes and apremont", "apremont abymes", "abymes apremont", "apremont et abymes", "abymes et apremont", "apremont and les abymes", "les abymes and apremont", "apremont les abymes", "les abymes apremont", "apremont and abimes", "abimes and apremont", "apremont abimes", "abimes apremont", "apremont et abimes", "abimes et apremont", "apremont and les abimes", "les abimes and apremont", "apremont les abimes", "les abimes apremont"], "ans": "Apremont and Abymes", "exp": "Apremont, the bitter mountain, and Abymes, the abysses, both remember the night the mountain fell. The rubble weathered into a chaos of broken limestone that drains fast and warms quickly, and the vineyards planted across it now stand at the foot of the scar."},
{"id": "c-00cc5ku1", "cat": "Jura, Savoie & Corsica", "q": "Alongside the fondue pot goes a carafe of Savoie's most planted white, feather-light and faintly alpine, rarely much past eleven degrees. Which grape is it?", "sa": 1, "accept": ["jacquere"], "ans": "Jacquere", "exp": "Jacquere covers more Savoie ground than any other variety, cropped generously and bottled young for wines of snow-water lightness. The style is the region's house pour, and the local advice is to drink it within the year, preferably within sight of the mountains that grew it."},
{"id": "c-81yirqdn", "cat": "Jura, Savoie & Corsica", "q": "Roussanne crossed into the mountains long ago, took the local alias Bergeron, and earned a Savoie cru reserved for it alone. Name the cru.", "sa": 1, "accept": ["chignin bergeron"], "ans": "Chignin-Bergeron", "exp": "Chignin-Bergeron is Roussanne by itself, grown on limestone scree above Chignin and riper, more apricot-fleshed, than anything else the region bottles. Plain Chignin without the hyphen is a different and lighter wine, which makes the pair one of Savoie's small label traps."},
{"id": "c-2a36rgj9", "cat": "Jura, Savoie & Corsica", "q": "Arbin has staked its name on a deep-hued, white-peppered red with real tannin, the exception in a region of featherweights. Name the variety.", "sa": 1, "accept": ["mondeuse", "mondeuse noire", "mondeuse grape"], "ans": "Mondeuse", "ex": 1, "exp": "Mondeuse Noire is Savoie's structural red, dark and peppery where the rest of the region runs light, and Arbin bottles it to the exclusion of everything else. Warm recent vintages have moved the wines from rustic toward genuinely serious, and the cru anchors the case that Savoie can make reds that age."},
{"id": "c-bhzclb2v", "cat": "Jura, Savoie & Corsica", "q": "Apremont, Chignin, Arbin, Jongieux: names like these may follow Vin de Savoie on the label. What does the appended name certify?", "opts": ["An extra year of ageing before the wine is sold", "Membership of that village's cooperative cellar", "Bottling carried out in the named commune", "Fruit from a cru with its own yield and grape rules"], "a": 3, "exp": "The appellation gathers sixteen crus, each a delimited zone with tighter yields and its own permitted grapes, so the appended word does the real work on a Savoie label. What reads as one appellation is really a scatter of separate mountain vineyards, and the cru name says which one is in the bottle."},
{"id": "c-icmxp3ka", "cat": "Jura, Savoie & Corsica", "q": "France's alpine wine country holds one appellation whose vines face each other across the Rhone itself, one bank in Ain and the other in Haute-Savoie. Which is it?", "opts": ["Seyssel", "Ripaille", "Chautagne", "Marignan"], "a": 0, "exp": "Seyssel is two towns of the same name facing each other across the river, and the appellation, granted in 1942, takes in both banks. The local Molette grape survives largely in its traditional sparkling wine, which the town has bottled since the nineteenth century."},
{"id": "c-jso8w6xv", "cat": "Jura, Savoie & Corsica", "q": "Roussette de Savoie, with or without a village after it, must now be pressed from a single variety. Name that grape.", "sa": 1, "accept": ["altesse"], "ans": "Altesse", "exp": "Altesse is the grape behind every Roussette de Savoie, fuller and far more age-worthy than the region's everyday whites, and Roussette is simply its local synonym, so the label names the grape twice over. The tale of an arrival from Cyprus is legend rather than record, but it suits a grape named highness."},
{"id": "c-engl38gg", "cat": "Jura, Savoie & Corsica", "q": "Tuscans would recognise Patrimonio's backbone grape at once and call it Sangiovese. What name do Corsicans use?", "sa": 1, "accept": ["nielluccio", "niellucciu"], "ans": "Nielluccio", "exp": "Nielluccio, Niellucciu in the island's own spelling, is genetically Sangiovese, almost certainly carried across during the centuries when Genoa ruled Corsica. It ripens late, holds its acid, and gives the island's most structured reds along with much of its serious rose."},
{"id": "c-dgixbv08", "cat": "Jura, Savoie & Corsica", "q": "Around the capital, Ajaccio, growers champion a pale, white-peppered red as the most Corsican grape of all. Name it.", "sa": 1, "accept": ["sciaccarello", "sciaccarellu", "sciacarello", "sciacarellu"], "ans": "Sciaccarello", "exp": "Sciaccarello, the name usually glossed as crunchy, makes reds of modest colour with red fruit and white pepper, and some of the island's best rose. France grows it nowhere but Corsica, and Corsica grows it best on its western side, which is why Ajaccio has made it the house grape."},
{"id": "c-9lj3w242", "cat": "Jura, Savoie & Corsica", "q": "Beneath its maquis, Corsica splits into two great blocks of rock, and the island's growers farm both. How does the split run?", "opts": ["Limestone through the west and south, with basalt across the northeast", "Granite along every coastline, with schist confined to the high interior", "Granite through the west and south, schist across the northeast", "Schist through the west and south, with granite across the northeast"], "a": 2, "exp": "Ajaccio and Sartene farm the granite that builds the island's west and south; the Cap Corse and the country at its base work the schist folded across the northeast. The seam between the two runs roughly through Corte, and growers read the texture of their wines by which side of it they farm."},
{"id": "c-0sxm1sl0", "cat": "Jura, Savoie & Corsica", "q": "One amphitheatre of chalky clay behind the gulf of Saint-Florent breaks the island's granite-and-schist monotony, and Corsica's first AOC, granted in 1968, sits on it. Name the appellation.", "sa": 1, "accept": ["patrimonio", "patrimoniu"], "ans": "Patrimonio", "exp": "Patrimonio's pocket of chalky clay is rare rock on an island of granite and schist, and it carries the reds with the firmest grip in Corsica. The appellation led the island into the AOC system in 1968, ahead of every other name on the island."},
{"id": "c-ju8h8a39", "cat": "Jura, Savoie & Corsica", "q": "Along the island's long northern finger, terraces above the sea grow small-berried Muscat for Corsica's lone vin doux naturel. Name the appellation.", "sa": 1, "accept": ["muscat du cap corse", "cap corse muscat", "muscat du cap corse aoc", "aoc muscat du cap corse", "muscat du cap corse vdn", "the muscat du cap corse appellation", "muscat du cap corse vin doux naturel", "muscat du cap corse vin doux naturel appellation"], "ans": "Muscat du Cap Corse", "ex": 1, "exp": "The Cap Corse is the island's northern peninsula, and its sea-facing terraces grow Muscat Blanc a Petits Grains for a golden wine of apricot and candied citrus. It stands as Corsica's only vin doux naturel appellation, made in small volumes and mostly drunk on the island itself."},
{"id": "c-8w73dbd5", "cat": "Jura, Savoie & Corsica", "q": "Liguria and Sardinia grow Corsica's leading white grape as well, but island labels write its name their own way. What do they call it?", "sa": 1, "accept": ["vermentinu", "malvoisie de corse"], "ans": "Vermentinu", "exp": "Vermentinu is the same grape as Italy's Vermentino and Provence's Rolle, and it carries almost all of Corsica's serious white wine. Older islanders and a few labels also call it Malvoisie de Corse, a name surviving from the days when every Mediterranean white of substance was a malvoisie of somewhere."},
{"id": "c-l60cracl", "cat": "Jura, Savoie & Corsica", "q": "Most of the island's harvest never sees an AOC, travelling instead under an IGP whose name is France's compliment to Corsica. Give the IGP.", "sa": 1, "accept": ["ile de beaute", "l'ile de beaute", "igp ile de beaute"], "ans": "Ile de Beaute", "exp": "Ile de Beaute, the isle of beauty, is the mainland's affectionate name for Corsica and the IGP that moves most of the island's wine, from varietal bottlings to the pink staples of the beach season. The appellations keep the prestige sites; the IGP carries the volume."},
{"id": "c-2b8usif0", "cat": "Loire", "q": "A list needs one Loire district able to pour Sauvignon Blanc, Chenin Blanc, Cabernet Franc and Pinot Noir, every one of them from its own appellations. Which district?", "opts": ["Touraine", "The Centre", "Anjou-Saumur", "The Pays Nantais"], "a": 0, "exp": "Touraine reaches from the Cabernet Franc of Chinon and Bourgueil in the west to the light sandy country in the east, where Pinot Noir appears. Anjou-Saumur has Chenin and Cabernet Franc but no Sauvignon of consequence, the Centre has Sauvignon and Pinot Noir but no Chenin anywhere and only one Cabernet Franc appellation, the tiny red-only Orleans-Clery, and the Pays Nantais is in practice a one-grape region."},
{"id": "c-ffc74ti9", "cat": "Loire", "q": "Before the regional country-wine name was standardised as an IGP, unappellated Loire wine went out under a phrase that called the whole valley a garden. Give that phrase.", "sa": 1, "accept": ["jardin de la france", "vin de pays du jardin de la france", "garden of france"], "ans": "Jardin de la France", "exp": "Vin de Pays du Jardin de la France covered the entire basin and became IGP Val de Loire when the category was renamed. The phrase is far older than any wine law: orchards, kitchen gardens and chateau parterres earned the valley the name centuries before anyone printed it on a bottle."},
{"id": "c-vaxy0kvq", "cat": "Loire", "q": "White-only Jasnieres occupies a single south-facing bank on the river Loir, entirely surrounded by a wider appellation that also bottles red and rose from Pineau d'Aunis. Name that wider appellation.", "sa": 1, "accept": ["coteaux du loir", "coteaux du loir aoc", "aoc coteaux du loir", "the coteaux du loir appellation"], "ans": "Coteaux du Loir", "ex": 1, "exp": "The Loir, without its final e, is a separate river running well to the north and reaching the Loire only by way of the Sarthe. Jasnieres is an enclave of Chenin inside Coteaux du Loir, which takes all three colours, so the smaller name is the stricter one and it is where a grower's red cannot go."},
{"id": "c-efpf6cj5", "cat": "Loire", "q": "Cheverny and the eastern Touraine appellations sit on light, acid sands blown off a wooded, pond-strewn country lying south of the river. Name that country.", "sa": 1, "accept": ["sologne", "sologne country", "the sologne region"], "ans": "The Sologne", "exp": "The Sologne is heath, forest and fish ponds rather than farmland, and its sands wash north into the vineyards on the Loire's left bank. Soils there are acid and hungry where the middle Loire's are limestone, which is much of why the wines around Blois are lighter and quicker than those from the tuffeau."},
{"id": "c-uw7cv5tw", "cat": "Loire", "q": "Recognition of village crus reached Muscadet in 2011, and the names approved first all lay at the southern end of Sevre et Maine. Which set was it?", "opts": ["Monnieres-Saint-Fiacre, Mouzillon-Tillieres and Chateau-Thebaud", "Ancenis, Vertou and La Chapelle-Heulin", "Goulaine, Vallet and Champtoceaux", "Clisson, Gorges and Le Pallet"], "a": 3, "exp": "All three sit on hard rock rather than on the sands of the plain, and the cru rules demand a minimum of 17 months on the lees at Le Pallet and 24 at Gorges and Clisson, rather than the single winter that sur lie allows. Further villages have been approved since, so the question is which came first and not which exist."},
{"id": "c-43zyafvd", "cat": "Loire", "q": "Vines run down to a wide, shallow lake south-west of Nantes, and the wine off them carries a Muscadet name of its own. Which?", "opts": ["Muscadet Coteaux de la Loire", "Muscadet Sevre et Maine sur lie", "Muscadet Cotes de Grandlieu", "Coteaux d'Ancenis"], "a": 2, "exp": "Lac de Grand-Lieu is a shallow marshland lake whose area roughly halves between winter and late summer, though even at its lowest it stays one of the largest natural lakes in France, and the vineyard on its shores was given its own name in 1994. The sandy ground there warms quickly and the water moderates the nights, so these are the roundest and earliest-drinking of the Muscadet zones."},
{"id": "c-jzsz0djf", "cat": "Loire", "q": "One Muscadet cru sits on a dark, dense rock that holds water and keeps its wines locked shut for years longer than the granite villages manage. The village is Gorges. Name the rock.", "sa": 1, "accept": ["gabbro", "gabbro bedrock", "gabbro rock"], "ans": "Gabbro", "exp": "Gabbro is a coarse, dark intrusive rock, the deep-cooled equivalent of basalt, and it weathers into a heavy, cold clay that holds its water. The granite villages drain far harder and open sooner, which is the whole argument for putting a village name on a Muscadet label at all."},
{"id": "c-6w8ji4hu", "cat": "Loire", "q": "The Armorican basement under the Pays Nantais throws up a pale, banded relation of granite, squeezed and recrystallised at depth until its light and dark minerals separated into stripes. Name it.", "sa": 1, "accept": ["gneiss", "orthogneiss", "gneiss bedrock"], "ans": "Gneiss", "exp": "Gneiss weathers to a thin, stony, fast-draining soil with almost no water in reserve, so the vine crops lightly and the wine comes out taut. Muscadet is unusual in France for being described by its bedrock rather than by its topsoil, and the reason is that there is so little topsoil to describe."},
{"id": "c-2i3w5exy", "cat": "Loire", "q": "An off-dry white from the vineyards around Ancenis is labelled Malvoisie, a name with no connection to the Malvasia of the Mediterranean. Which grape is in the bottle?", "sa": 1, "accept": ["pinot gris", "pinot grigio", "grauburgunder"], "ans": "Pinot Gris", "exp": "Malvoisie is the local name for Pinot Gris on this stretch of the river, and the wine is usually finished with a little sugar left in. The name travels badly, since Malvoisie and Malvasia are used across Europe for a scatter of unrelated varieties, and here it means one specific grape."},
{"id": "c-rdvo2otj", "cat": "Loire", "q": "A Layon label reads Coteaux du Layon Saint-Aubin-de-Luigne rather than Coteaux du Layon alone. What did the grower have to meet before printing the commune?", "opts": ["Fruit picked entirely by machine in a single pass", "A smaller permitted crop and riper fruit at picking", "A ban on residual sugar above the demi-sec level", "A minimum of three years in bottle before release"], "a": 1, "exp": "Six communes of the Layon may append their names, and the concession is paid for with a smaller crop and riper fruit than plain Coteaux du Layon asks for. The addition sits above plain Coteaux du Layon and below the named crus of the valley, so it is a rung on a ladder rather than a decoration."},
{"id": "c-0m6iuc0q", "cat": "Loire", "q": "Autumn mornings on the Layon are misty and its afternoons dry, while the coast a hundred kilometres west stays wet through October. Which feature of the land accounts for that?", "opts": ["Hills standing between the valley and the ocean, which dry the westerly air", "The width of the Loire, which pushes rain clouds northwards", "A belt of forest planted along the Layon to shelter the vines", "The valley's elevation, which lifts the vineyards clear of coastal weather"], "a": 0, "exp": "The Mauges are the eastern shoulder of the old Armorican massif, and air crossing them arrives at the Layon drier than it left the sea. That rain shadow is what turns noble rot from a gamble into a reasonable expectation, because the fungus needs damp nights and dry afternoons in the same week."},
{"id": "c-lib50odg", "cat": "Loire", "q": "One site above the Layon holds the only Premier Cru rank in the whole valley, a step below the Loire's single sweet Grand Cru. Name that site.", "sa": 1, "accept": ["chaume", "coteaux du layon premier cru chaume", "coteaux du layon chaume", "premier cru chaume", "chaume premier cru", "1er cru chaume", "coteaux du layon chaume premier cru", "coteaux du layon chaume 1er cru", "coteaux du layon 1er cru chaume", "chaume 1er cru", "layon chaume", "layon premier cru chaume", "layon 1er cru chaume", "chaume coteaux du layon"], "ans": "Chaume", "ex": 1, "exp": "Coteaux du Layon Premier Cru Chaume is the full form, and it demands lower yields and riper fruit than a commune-named Layon. The Grand Cru above it takes its name from the same hillside, which is why the shorter name is so often misread as an abbreviation of the longer one."},
{"id": "c-nku6s6si", "cat": "Loire", "q": "Chaptalisation is barred outright in the Loire's sweet Grand Cru, and so is the trick of chilling picked fruit until the wateriest berries freeze and stay behind in the press. Name that barred technique.", "sa": 1, "accept": ["cryoextraction", "cryo extraction", "cryoextraction selective"], "ans": "Cryoextraction", "exp": "The rules forbid it precisely because it manufactures in the press house what the appellation exists to demonstrate in the vineyard, which is fruit concentrated on the vine by rot or by raisining. Chaptalisation is barred for the same reason from the other end: neither the sugar nor the concentration may be bought indoors."},
{"id": "c-oqrzk0ai", "cat": "Loire", "q": "Sweet Chenin grown on the banks of the Loire itself around Angers, rather than up any of its tributaries, has an appellation of its own. Name it.", "sa": 1, "accept": ["anjou coteaux de la loire", "aoc anjou coteaux de la loire", "anjou coteaux de la loire aoc", "the anjou coteaux de la loire appellation"], "ans": "Anjou Coteaux de la Loire", "ex": 1, "exp": "The mists here come off the main river rather than off a tributary, and the wines are lighter and less regularly botrytised than a Layon. Anjou's sweet wine is generally thought of as a Layon speciality, and this is the appellation that shows it is not confined to the tributary valleys."},
{"id": "c-3s7x2muv", "cat": "Loire", "q": "A guest is poured a Savennieres carrying obvious sugar and asks whether the bottle has been mislabelled. What is the correct reply?", "opts": ["Savennieres must be dry, so the bottle has indeed been mislabelled", "Sugar is permitted only where the label declares a late harvest", "The appellation permits demi-sec and moelleux as well as dry wine", "Only the cru appellations inside Savennieres may carry sugar"], "a": 2, "exp": "Off-dry Savennieres was once the norm, and the decree still allows demi-sec and moelleux; bone-dry is a modern preference rather than a rule. The slope can do either, because the schist ripens Chenin hard while the river brings the autumn mists, so the decision is made in the vineyard rather than in the rulebook."},
{"id": "c-ioj4fjqw", "cat": "Loire", "q": "Above the Savennieres slope stands a fortified outcrop that monks planted in the twelfth century, and the cru named after it covers far more ground than its neighbour. Name that cru.", "sa": 1, "accept": ["roche aux moines", "savennieres roche aux moines", "roche aux moines cru"], "ans": "Roche aux Moines", "exp": "Roche aux Moines takes the monks' rock for its name and keeps Savennieres in front of it on the label, while the smaller cru on the same hillside stands alone as Coulee de Serrant. Both are dry Chenin off schist, and the larger is generally the broader and slower to open."},
{"id": "c-vsujqvsi", "cat": "Loire", "q": "Chenin from the Savennieres slope that falls short of the appellation's minimum ripeness cannot be sold as a lesser Savennieres. Which broader appellation takes it instead?", "sa": 1, "accept": ["anjou blanc", "anjou", "aoc anjou", "anjou aoc", "anjou blanc aoc", "aoc anjou blanc"], "ans": "Anjou Blanc", "ex": 1, "exp": "Anjou is the regional appellation underneath the whole district, and declassified whites from Savennieres, the Layon and Saumur alike end up there. The name says nothing about the slope the fruit grew on, which is why a serious grower's Anjou Blanc is often among the better-value whites in the valley."},
{"id": "c-tm40i5yq", "cat": "Loire", "q": "A pink wine from Saumur arrives noticeably sweet on the finish and is made from Cabernet Franc. Which appellation covers it?", "opts": ["Cabernet de Saumur", "Cremant de Loire Rose", "Rose de Loire", "Saumur Rose"], "a": 0, "exp": "Cabernet de Saumur is the medium-dry pink of the zone, the counterpart to Cabernet d'Anjou a little downstream, and both are built on the Cabernets rather than on Grolleau. A Saumur Rose from the same cellar is finished dry, so a list carrying both names is drawing a sweetness distinction and not a geographical one."},
{"id": "c-wzefwzov", "cat": "Loire", "q": "A grower inside the Saumur-Champigny boundary presses Chenin Blanc from a plot lying among the Cabernet Franc. Under which name must that white be sold?", "opts": ["Saumur-Champigny Blanc", "Saumur Blanc", "Touraine Blanc", "Vin de France"], "a": 1, "exp": "Saumur-Champigny is a red appellation and nothing else, so white from inside its boundary falls back on the Saumur name, which covers still white, still red, rose and sparkling alike. The plateau is identical; the rules simply do not recognise a white under the Champigny name."},
{"id": "c-gwm1colt", "cat": "Loire", "q": "A sommelier is asked for a sweet Chenin from Saumur rather than from the Layon. Which appellation should be poured?", "sa": 1, "accept": ["coteaux de saumur", "aoc coteaux de saumur", "the coteaux de saumur appellation"], "ans": "Coteaux de Saumur", "exp": "Coteaux de Saumur is the tuffeau country's answer to the Layon: moelleux Chenin made in very small quantity, and only in vintages that deliver rot or raisining. Most growers make it when the year allows and sell their dry Chenin under the town's ordinary white name the rest of the time, so it turns up on a list only occasionally."},
{"id": "c-nyiugjgq", "cat": "Loire", "q": "Red Cabernet Franc grown on the tuffeau around a hilltop collegiate church south-west of Saumur was given a village appellation of its own in 2009. Name it.", "sa": 1, "accept": ["saumur puy notre dame", "puy notre dame", "aoc saumur puy notre dame"], "ans": "Saumur Puy-Notre-Dame", "exp": "Saumur Puy-Notre-Dame stands above the Saumur zone as Anjou-Villages stands above Anjou, with lower yields and later release. Its ground is the same tuffeau plateau that carries Saumur-Champigny, a good deal further back from the river."},
{"id": "c-b12aptls", "cat": "Loire", "q": "Chenin Blanc must fill a Montlouis-sur-Loire completely, while the appellation facing it across the river may take a few percent of one other old Touraine white. Which grape?", "opts": ["Romorantin", "Sauvignon Blanc", "Orbois", "Folle Blanche"], "a": 2, "exp": "Vouvray admits a small share of Orbois, known locally as Menu Pineau, and Montlouis admits nothing but Chenin. Orbois is a neutral, low-acid old variety surviving mostly in Touraine blends, and the allowance is a relic of the mixed plantings the appellation was drawn around."},
{"id": "c-ywaq0vtp", "cat": "Loire", "q": "Growers on the plateau above Vouvray name their two soils: one is clay over limestone that holds water and slows the vine, the other a flinty clay that warms early. Which naming is correct?", "opts": ["Aubuis is the clay-limestone and perruches the flinty clay", "Perruches is the clay-limestone and aubuis the flinty clay", "Aubuis is the clay-limestone and varennes the flinty clay", "Silex is the clay-limestone and perruches the flinty clay"], "a": 0, "exp": "Aubuis holds its water and keeps Chenin ripening slowly, which is why parcels destined for sweet wine tend to sit on it, while perruches drains and warms fast and suits the earlier styles. Both words belong to Touraine and appear in growers' conversation far more often than on labels."},
{"id": "c-0gttjyr0", "cat": "Loire", "q": "A Montlouis sparkling is bottled before its first fermentation has finished, so there is no second fermentation, no disgorging and no dosage. Which label term does the appellation give it?", "sa": 1, "accept": ["petillant originel", "montlouis petillant originel", "petillant originel montlouis"], "ans": "Petillant Originel", "exp": "Petillant Originel is Montlouis' own designation for the ancestral method, and the wine keeps both its sediment and its low pressure. It sits outside the Cremant de Loire framework altogether, since a Cremant demands hand-picked whole bunches and a second fermentation in bottle, so the two are different wines under different rulebooks rather than two grades of one thing."},
{"id": "c-ne65k86o", "cat": "Loire", "q": "A carafe of Touraine red is poured that is light, purple and juicy, and it holds no Cabernet Franc at all. Which grape fills the district's everyday red?", "sa": 1, "accept": ["gamay", "gamay noir", "gamay noir a jus blanc"], "ans": "Gamay", "exp": "The district appellation leans on Gamay for red and on Sauvignon Blanc for white, which is why a wine labelled simply Touraine tastes nothing like Chinon or Vouvray. Cot appears in the reds as well, and the Gamay is usually the fresher and the cheaper of the two."},
{"id": "c-lh6h0g6t", "cat": "Loire", "q": "August turns dry in Touraine. Vines rooted in porous limestone carry on ripening while those on the river gravels shut down. What is the limestone doing for them?", "opts": ["Draining harder, so the roots must go deeper for water", "Releasing water it has held in its pores back towards the roots", "Reflecting heat off its pale surface onto the bunches", "Raising the soil pH so that the roots take up more nitrogen"], "a": 1, "exp": "Tuffeau is a chalky sandstone riddled with pore space and it behaves as a reservoir, taking water in over winter and giving it back slowly through the summer. Gravel holds almost none, so a terrace vine lives on whatever rain the season happens to bring."},
{"id": "c-9drwtgc8", "cat": "Loire", "q": "South of Tours a very pale pink wine is made from a blend of Pinot Meunier, Pinot Gris and Pinot Noir. Which appellation is it?", "opts": ["Rose de Loire", "Reuilly", "Touraine Noble-Joue", "Touraine-Azay-le-Rideau"], "a": 2, "exp": "Touraine Noble-Joue is a vin gris revived from vineyards that the suburbs of Tours had very nearly swallowed. The fruit is pressed straight off the skins so the colour barely arrives at all, and nothing else in the valley is built from that combination of grapes."},
{"id": "c-7ct0z3wh", "cat": "Loire", "q": "Cabernet Franc fills the reds of Bourgueil, Saint-Nicolas-de-Bourgueil and Chinon, yet the rules let a grower add a small stated share of one other black variety. Name it.", "sa": 1, "accept": ["cabernet sauvignon", "a little cabernet sauvignon", "cabernet sauvignon in a small proportion"], "ans": "Cabernet Sauvignon", "exp": "The allowance is small and most growers use none of it, because Cabernet Sauvignon ripens later than Cabernet Franc and this is close to its northern limit. Where the three appellations really part company is colour: only Chinon may bottle a white."},
{"id": "c-ain5qlp2", "cat": "Loire", "q": "At the eastern edge of Touraine an appellation covers red, white and rose alike, and shares its name with a pyramid-shaped goat cheese. Name it.", "sa": 1, "accept": ["valencay", "valencay aoc", "aoc valencay"], "ans": "Valencay", "exp": "Valencay bottles Sauvignon Blanc whites and reds blended from Gamay, Cot and Pinot Noir, and wine and cheese carry the same appellation name from the same ground. The cheese's flat top has a legend attached to Napoleon's Egyptian campaign, which the cheesemakers repeat and the historians do not."},
{"id": "c-zp98hglk", "cat": "Loire", "q": "A cuvee from vines in the commune of Saint-Nicolas-de-Bourgueil is judged too slight to carry its own village name. Which appellation of the same ground can take it instead?", "sa": 1, "accept": ["bourgueil", "aoc bourgueil", "bourgueil aoc", "aop bourgueil", "bourgueil aop", "bourgueil ac", "the bourgueil appellation", "bourgueil rouge", "red bourgueil"], "ans": "Bourgueil", "ex": 1, "exp": "Saint-Nicolas-de-Bourgueil is one of the communes inside the wider Bourgueil delimitation as well as an appellation in its own right, so the traffic runs one way only. A Saint-Nicolas grower may declassify into Bourgueil; a Bourgueil grower has no claim whatever on the village name."},
{"id": "c-bnus3f15", "cat": "Loire", "q": "Sancerre and Pouilly-Fume look at one another across the Loire. Which sits on which bank?", "opts": ["Both lie on the left bank, with Pouilly-Fume the further north", "Sancerre on the left bank, Pouilly-Fume on the right", "Sancerre on the right bank, Pouilly-Fume on the left", "Both lie on the right bank, with Sancerre the further south"], "a": 1, "exp": "The river runs roughly northwards here, so the left bank is the western side and the hill of Sancerre stands over it, while Pouilly lies across the water on the eastern side. The two appellations touch at no point at all, because the river itself is the boundary between them."},
{"id": "c-qf3j1ram", "cat": "Loire", "q": "A guest asks for a red Pouilly-Fume to set beside a red Sancerre. Why can the sommelier not oblige?", "opts": ["Pouilly-Fume's red has to be sold under the Pouilly-sur-Loire name", "Pouilly-Fume's red is Gamay and is bottled only for the local trade", "Pouilly-Fume's red is made in exceptional vintages and is rarely exported", "Pouilly-Fume is white only, while Sancerre covers all three colours"], "a": 3, "exp": "Pouilly-Fume is Sauvignon Blanc and nothing else, and no red or rose exists under the name. Sancerre by contrast takes white from Sauvignon and red and rose from Pinot Noir, which is the sharpest rulebook difference between two appellations facing each other across the water."},
{"id": "c-x6zir0qk", "cat": "Loire", "q": "Above the hamlet of Chavignol one slope is steep enough that the pickers work it on foot, and its name says the labour damns those who do it. Name the slope.", "sa": 1, "accept": ["les monts damnes", "monts damnes", "monts damnes de chavignol"], "ans": "Les Monts Damnes", "exp": "Les Monts Damnes rises off the heavy Kimmeridgian marl at a gradient no tractor will hold, and the wines are among the broadest and slowest in Sancerre. The appellation ranks no vineyard officially, so a famous name there is reputation rather than classification, and saying so at the table is worth doing."},
{"id": "c-1edepba4", "cat": "Loire", "q": "Around Bue the Sancerre vineyard works shallow, stony ground full of small hard limestone pebbles, and the wine off it is aromatic and quick to show. Give the local name for that soil.", "sa": 1, "accept": ["caillottes", "caillotte", "les caillottes"], "ans": "Caillottes", "exp": "Caillottes are the stony Portlandian limestone soils of the central hills, shallow and warm, and they ripen fruit fast and give wine that drinks early. The heavier clay-limestone west of them and the flint east of them both give slower, longer-lived wine, which is how one appellation comes to taste so unalike from grower to grower."},
{"id": "c-j23quq1r", "cat": "Loire", "q": "On the southern edge of the Centre, an appellation raised from VDQS in 2010 is known above all for a very pale vin gris made from Gamay. Which?", "opts": ["Pouilly-sur-Loire", "Orleans-Clery", "Menetou-Salon", "Chateaumeillant"], "a": 3, "exp": "Chateaumeillant sits south-west of Bourges towards the edge of the Massif Central, and its speciality is a vin gris pressed off Gamay skins almost immediately. A vin gris is not a rose bled from a red vat: it is pressed like a white from black grapes, and this is the Loire appellation that made its name on the style."},
{"id": "c-3c6zm8rq", "cat": "Loire", "q": "Between Sancerre and the town of Gien the vineyard runs along either side of the Loire, making whites from Sauvignon Blanc and reds from Gamay with Pinot Noir. Name the appellation.", "sa": 1, "accept": ["coteaux du giennois", "giennois", "aoc coteaux du giennois"], "ans": "Coteaux du Giennois", "exp": "Coteaux du Giennois reaches north from the Sancerre boundary to Gien and works the same Sauvignon Blanc on far less celebrated ground. Its reds and roses must blend the two black grapes rather than use either on its own, which is a requirement no other appellation of the Centre imposes. So a grower here who wants a straight varietal red has to sell it outside the appellation altogether, and the rule shapes what leaves the cellar rather than merely describing what is planted."},
{"id": "c-p0bz578h", "cat": "Loire", "q": "West of Bourges, away from the Loire altogether, a pair of Centre appellations works sand and gravel terraces on the Cher and its tributary the Arnon. Name them.", "sa": 1, "accept": ["quincy and reuilly", "reuilly and quincy", "quincy reuilly", "reuilly quincy", "quincy aoc and reuilly aoc", "reuilly aoc and quincy aoc"], "ans": "Quincy and Reuilly", "exp": "Quincy is white only, from Sauvignon Blanc on wind-blown sand over gravel, and Reuilly adds red and rose to the same picture a little further west on the Arnon. Both sit well away from Sancerre on quite different ground, and their wines are rounder and quicker to open for it."},
{"id": "c-lad9y0wl", "cat": "New Zealand", "q": "Marlborough wineries holding fruit in both of the province's big valleys crush their Wairau blocks first every vintage; the Awatere lots follow as much as a fortnight later, greener and sharper. What holds the Awatere back?", "opts": ["Higher terraces, nearer the cold open sea", "Heavy clay beneath the whole valley, holding cold water against the roots into summer", "A full degree more latitude, under which autumn light fails sooner", "Pick dates written into grower contracts, staggered to keep the press hall clear"], "a": 0, "exp": "The Awatere climbs onto old uplifted terraces well above the Wairau floor and lies open to cold southerly air off the Pacific, so heat accumulates slowly all season and the tomato-leaf, pyrazine side of the grape survives into the bottle. The two valleys sit at almost the same latitude, and the fortnight is the work of elevation and exposure, not daylength or soil."},
{"id": "c-6khxwt4s", "cat": "New Zealand", "q": "Fairhall, Omaka and Ben Morven leave the stony Wairau flats for cooler, clay-floored country in the hills, and Marlborough's growers know the set of them by one collective name. Give it.", "sa": 1, "accept": ["southern valleys", "southern valleys of marlborough", "marlborough s southern valleys", "southern valleys subregion"], "ans": "The Southern Valleys", "exp": "The Southern Valleys angle into the hills from the Wairau's southern flank, and their clay bottoms hold water that the shingle of the open plain sheds at once, while cooler air drains down them at night. That steadier, cooler ground behaves quite differently from the stony flats, which is precisely the distinction the collective name exists to record."},
{"id": "c-mynp3jsd", "cat": "New Zealand", "q": "Thirty-odd kilometres separate one firm's Pinot Noir blocks at Bendigo from its rows at Gibbston, yet the two picks land weeks apart every autumn and never overlap. What separates the sites?", "opts": ["Elevation: the Gibbston vines stand about a hundred metres higher, and that costs weeks of season", "Crop levels, because Gibbston growers hang double the fruit and heavy crops finish late", "Heavier clay soils under the Gibbston blocks, which hold cold spring water against the roots all season", "A sea breeze that reaches Bendigo up the Clutha but dies before the gorge"], "a": 0, "exp": "Gibbston hangs in the Kawarau gorge, the highest and coolest ground in Central Otago, while Bendigo's terraces are among its warmest, and at the cool margin for Pinot Noir roughly a hundred metres of altitude moves harvest by weeks. No sea breeze reaches any of it; this is New Zealand's one semi-continental climate, where elevation and enclosure do the work that distance from the ocean does everywhere else."},
{"id": "c-5vzj623n", "cat": "New Zealand", "q": "Sluicing for gold in the 1860s stripped whole hillsides above the Kawarau's southern bank, and the scarred, sun-baked amphitheatre the miners left is now the most densely planted ground in Central Otago. Name the subregion.", "sa": 1, "accept": ["bannockburn", "the bannockburn subregion", "bannockburn otago"], "ans": "Bannockburn", "exp": "Bannockburn sits where the Kawarau meets the Cromwell Basin, and the miners' water-cannon history is still legible in bare clay cliffs and tailings among the vines. Hot by day, cold at night and nearly desert-dry, it delivers the dense, dark end of Central Otago Pinot Noir and holds the tightest concentration of plantings in the region."},
{"id": "c-j84ga9mc", "cat": "New Zealand", "q": "Under four hundred millimetres of rain falls in a year on parts of the Cromwell Basin, and Bendigo's deep, free-draining terraces are the thirstiest ground in it. Which intervention makes a vineyard there possible at all?", "opts": ["Shade cloth", "Wind machines", "Irrigation", "Netting"], "a": 2, "exp": "Central Otago is the one New Zealand region where drought rather than rain sets the farming calendar, and drip lines went in with the vines almost everywhere. Wind machines answer spring frost, a real Otago hazard but a different one; netting keeps birds off ripening fruit; shade cloth tempers sun on the berry; and none of them puts water into gravel that cannot hold it."},
{"id": "c-fidc5sec", "cat": "New Zealand", "q": "Barely twenty metres of rise separate Martinborough's celebrated terrace from the paddocks around it, yet nearly every serious Pinot Noir block in the district crowds onto it. What do those few metres, and the deep shingle beneath them, actually buy?", "opts": ["A shallow water table the roots can reach, sparing growers the cost of irrigation", "Shelter from the northwesterly gales that hammer the rest of the valley all the way through flowering", "A degree of extra coolness from altitude, which the district's whole style depends on", "Cold air slides off its edge on frost nights, and rain drains straight through the shingle"], "a": 3, "exp": "The terrace is an old bed of the Huangarua and Ruamahanga rivers, deep in free-draining gravels, and its edge lets cold air drain away to lower ground on still nights. Nothing about it blocks the wind, which still cuts the crop at flowering; what it offers is dry feet and safe hang time, the two things thin-skinned Pinot Noir most needs in a damp country."},
{"id": "c-p2pmwp95", "cat": "New Zealand", "q": "Ripening on one patch of Hawke's Bay runs days ahead of the vineyards nearer the coast, and its Syrah and Cabernet carry a weight coastal growers rarely match. What gives the Gimblett Gravels that head start?", "opts": ["Several hundred metres of altitude, which lifts the vines clear of the marine cloud layer", "The afternoon sea breeze arrives blunted by distance, and the stones bank the day's heat", "An association rule against irrigation, whose drought stress reads on the palate as ripeness", "Beds of dark volcanic ash beneath the shingle, holding warmth that grey stones cannot"], "a": 1, "exp": "The old riverbed lies inland of Hastings, out of the afternoon breeze that cools Te Awanga and the coastal blocks, and its almost soil-free shingle stores heat and releases it into the evening, stretching the warm hours of every ripening day. The same stones are poor and free-draining, so crops stay naturally small, which is the other half of the district's concentration; the land itself is low-lying, and growers there irrigate freely."},
{"id": "c-1uzsgza2", "cat": "New Zealand", "q": "Printing the Gimblett Gravels name on a label takes more than farming inside the district: the growers' association licenses the words only when a wine's sourcing clears a bar stricter than the one national labelling law sets for any stated region. Give that minimum share.", "sa": 1, "accept": ["95 percent", "95", "95%", "95 per cent", "ninety five percent", "ninety five", "at least 95 percent", "at least 95%", "a minimum of 95 percent", "95 percent of the fruit", "ninety five per cent", "at least 95 per cent", "at least ninety five percent", "minimum 95 percent", "95 percent minimum", "95 percent of the grapes", "ninety five percent of the fruit"], "ans": "95 percent", "ex": 1, "exp": "Ninety-five percent of the fruit must come off the mapped shingle itself, and the name is enforced as a trademark held by the growers' association rather than as a registered geographical indication. The rule is the district insisting that its soil boundary is the whole point: a wine drawing meaningfully on other ground may not borrow the address."},
{"id": "c-nkvbg5e6", "cat": "New Zealand", "q": "Three registered geographical indications can all appear truthfully on one grower's wine: Waipara Valley, North Canterbury and Canterbury. How do the three names relate?", "opts": ["Waipara Valley is the widest of the three, reaching across the whole of the old provincial district", "They nest, smallest inside largest, and the producer may claim any of the three", "They are three registered names for a single identical boundary, kept so older labels can stay in print", "Each one covers separate ground, so only one of them can ever be true of a given vineyard"], "a": 1, "exp": "New Zealand's registrations may sit one inside another, and how tightly to pin the wine down is the producer's choice, provided the stated name meets the sourcing threshold that every origin claim carries. Waipara Valley is the smallest of the three and the one with a style attached to it; the broader the name chosen, the less it commits the wine to."},
{"id": "c-zovismb2", "cat": "New Zealand", "q": "Passed in 2006, then left dormant for over a decade until it finally came into force in 2017, one statute lets New Zealand's wine regions register their names. Name it.", "sa": 1, "accept": ["geographical indications wine and spirits registration act", "geographical indications registration act", "geographical indications act", "gi act", "gi registration act", "geographical indications wine and spirits act", "geographical indications wine spirits registration act"], "ans": "The Geographical Indications (Wine and Spirits) Registration Act", "exp": "The Geographical Indications (Wine and Spirits) Registration Act defines a name's boundary and gives its users legal standing to defend it, at home and in trade negotiations abroad, and that is all it does: no variety, yield or winemaking rule attaches to any New Zealand name. Registration is voluntary and paid for by the applying industry body, which is why the register filled up only once export agreements made the protection worth buying."},
{"id": "c-upzo2gd8", "cat": "New Zealand", "q": "One imported selection, bulked up through nursery after nursery as planting outran supply, stands behind almost every Sauvignon Blanc vine in Marlborough. Name the clone.", "sa": 1, "accept": ["ucd1", "ucd 1", "clone ucd1", "clone ucd 1", "ucd clone 1", "davis clone 1", "the davis clone", "uc davis clone 1", "uc davis 1", "ucd1 clone", "it is ucd1", "uc davis clone", "ucd 1 clone", "university of california davis clone 1"], "ans": "UCD1", "ex": 1, "exp": "UCD1 came direct from the University of California at Davis, imported by the government viticulturist and released to a trial block in 1970, and the speed of Marlborough's expansion meant nurseries multiplied the one proven selection rather than diversifying. A single set of genes across tens of thousands of hectares is much of why the style is so consistent at volume, and it concentrates risk the same way, which is why newer plantings finally blend in other material."},
{"id": "c-jye0wrhp", "cat": "New Zealand", "q": "Almost every Sauvignon Blanc vine in Marlborough shares one set of genes, and the industry's own scientists describe that uniformity as its largest structural exposure. What is the worry?", "opts": ["The wines cannot legally be sold as varietal Sauvignon Blanc", "Uniform genetics leave the vines sterile, so nurseries must import fresh budwood every season", "A weakness one vine has, every vine has, so a new pest or virus strikes the whole region at once", "Single-clone vineyards fail sustainability audits, which closes the main export channels"], "a": 2, "exp": "Genetic uniformity means uniform susceptibility: a disease, a pest or a run of unsuitable vintages that finds one vine's weakness finds them all, with no diverse material standing as a fire break. That is why replanting programmes and newer vineyards now spread across additional clones and selections, trading a little of the region's famous consistency for resilience."},
{"id": "c-fvutomw7", "cat": "New Zealand", "q": "Tired of taint and bottle variation, a small band of wineries formed an initiative to move the whole country onto the screwcap, and within a decade the cork had become the exception on New Zealand shelves. Give the year they launched it.", "sa": 1, "accept": ["2001", "in 2001", "the year 2001", "two thousand and one", "two thousand one", "launched in 2001", "it launched in 2001", "launched 2001", "founded in 2001", "it was founded in 2001", "it was 2001", "the year was 2001"], "ans": "2001", "ex": 1, "exp": "The Screwcap Wine Seal Initiative was founded in 2001, Marlborough houses prominent among its members and the Clare Valley's Riesling producers a year ahead of them across the Tasman. Because it was an industry campaign rather than one winery's experiment, adoption ran to the top of the market as quickly as the bottom, and the argument soon moved on from whether to seal wine this way to how much oxygen a liner should admit."},
{"id": "c-jt6oos3r", "cat": "Pacific NW, NY & Canada", "q": "Generic borrowings such as Chablis and Burgundy stayed legal on American labels for decades after one state had already barred them from its own. Which state moved first, at the end of the 1970s?", "opts": ["Ohio", "Oregon", "Idaho", "Washington"], "a": 1, "exp": "The federal government still tolerates a short list of semi-generic European names under a grandfather arrangement, so this was a state legislating well ahead of Washington DC. The package it belonged to was written to force the state's producers to sell on the name of their own grape and their own place rather than on a borrowed one, and it set several minimums above the federal floors at the same time."},
{"id": "c-t6tqlhvn", "cat": "Pacific NW, NY & Canada", "q": "Fruit is trucked across a state line, crushed and bottled at the buyer's own winery, and the label is then refused the appellation the grapes actually grew in. Which federal requirement blocks it?", "opts": ["Grapes may not cross a state line before they are crushed", "An AVA name may only be used by a winery standing inside the appellation's own boundary", "A wine naming an AVA must be fully finished in the state that AVA lies in", "An AVA name requires the producer to own the vineyard"], "a": 2, "exp": "The rule sits beside the fruit percentage in the same body of federal regulation, and it exists so that an appellation claim cannot be assembled in a cellar a thousand miles from the vineyard. Cellar treatment and blending that does not change the class or type of the wine are the only steps allowed elsewhere. Where an appellation straddles a state line, finishing in either of them satisfies the rule, which is why a cross-border name is the usual way around the problem."},
{"id": "c-51qtgqjj", "cat": "Pacific NW, NY & Canada", "q": "Fifteen percent of a Dundee Hills bottling is fruit grown outside that boundary, which federal law would wave through. The state it sits in will not. Where does that state set its own minimum?", "sa": 1, "accept": ["ninety five percent", "95 percent", "95%", "95 per cent", "ninety five per cent", "95", "ninety five", "at least 95 percent", "at least 95%", "at least ninety five percent", "a minimum of 95 percent", "a minimum of ninety five percent", "minimum 95 percent", "minimum 95%", "95 percent minimum", "95 per cent minimum", "95 percent or more", "no less than 95 percent", "must be 95 percent", "95 percent of the fruit", "95 percent of the grapes", "ninety five percent of the fruit", "ninety five percent of the grapes", "95 percent from the appellation", "ninety five percent from the appellation"], "ans": "Ninety-five percent", "ex": 1, "exp": "Federal law asks 85 percent of the fruit for an AVA name and Oregon demands ninety-five, so a blend that would ship happily from another state has to be relabelled to a broader name here. The same instinct runs through the state's other rules, which is why Oregon labels tend to carry either a very precise place or a frankly regional one and little in between."},
{"id": "c-vi4m4cgp", "cat": "Pacific NW, NY & Canada", "q": "Which of these Willamette sub-appellations is wrapped entirely inside another sub-appellation rather than sitting directly in the valley?", "opts": ["Chehalem Mountains", "McMinnville", "Yamhill-Carlton", "Ribbon Ridge"], "a": 3, "exp": "Ribbon Ridge is a spur thrown off the Chehalem Mountains, standing above the valley floor on every side, so its boundary falls wholly within that larger appellation and a grower there may print either name. Chehalem Mountains is the parent rather than a fellow tenant, and Yamhill-Carlton and McMinnville each meet the valley floor directly. Ribbon Ridge is the smallest of the original Willamette sub-appellations and the most uniform, being one landform with one soil type across it, and it was the first of a nested pair: a second sub-appellation, drawn later, sits wholly inside the Chehalem Mountains in the same way."},
{"id": "c-8q75jhfs", "cat": "Pacific NW, NY & Canada", "q": "Before Dijon selections reached Oregon at the end of the 1980s, almost every Pinot Noir vine in the Willamette came from one of two older clones. Which pair?", "opts": ["Pommard and Wadenswil", "Wente and Rued", "Mariafeld and Geisenheim", "Dijon 115 and Dijon 777"], "a": 0, "exp": "Pommard, catalogued at Davis as UCD 5, gives the darker and more structured wine, while Wadenswil, UCD 2, is lighter, higher toned and more aromatic, and old plantings are often a field mix of the two. The Dijon selections that followed ripen earlier and in smaller clusters, which in a valley whose autumn rain arrives on schedule is worth more than any flavour argument."},
{"id": "c-lxeurzrw", "cat": "Pacific NW, NY & Canada", "q": "Uplifted ancient seabed underlies the northern Willamette, weathering to a pale, silty, low-vigour ground quite unlike the red basalt soils of the hills alongside it. That soil series carries a name run together from the rivers of the valley floor. Name it.", "sa": 1, "accept": ["willakenzie", "willakenzie soil", "willakenzie soils", "willakenzie series", "willakenzie soil series", "willakenzie sedimentary soil", "willakenzie marine sedimentary soil"], "ans": "Willakenzie", "ex": 1, "exp": "The name is a contraction of the Willamette and the McKenzie, the two rivers of the valley floor, and the material itself is old marine sandstone and siltstone lifted out of the sea rather than anything volcanic. It is shallower and less fertile than the basalt soils, so vines set smaller crops on it without persuasion, and Yamhill-Carlton is the appellation most often quoted as its home ground."},
{"id": "c-k0r92oag", "cat": "Pacific NW, NY & Canada", "q": "On the northern face of the Chehalem Mountains an ice-age wind laid a deep cap of fine silt over the basalt, thick enough to farm in its own right. Name that soil.", "sa": 1, "accept": ["laurelwood", "laurelwood soil", "laurelwood soils", "laurelwood series", "laurelwood soil series", "laurelwood loess", "laurelwood silt"], "ans": "Laurelwood", "ex": 1, "exp": "Laurelwood is loess, wind-carried dust dropped downwind of the glacial floods and piled up against the north side of the range over many thousands of years. Because the silt sits on basalt rather than replacing it, a vineyard there can have both materials inside the same root zone, which is the argument its growers make for the ground being distinct from either the basalt or the marine sediment on their own."},
{"id": "c-sywx038h", "cat": "Pacific NW, NY & Canada", "q": "Wind pouring through a break in the Coast Range scours one group of basalt hills a few miles east of that gap every afternoon, and the fruit comes in small-berried and firm. Name that sub-appellation.", "sa": 1, "accept": ["eola amity hills", "eola amity", "eola amity hills ava", "eola amity hills appellation", "eola and amity hills", "eola amity hills in the willamette valley"], "ans": "Eola-Amity Hills", "ex": 1, "exp": "The break is the Van Duzer Corridor, a gap where the Coast Range drops low enough for marine air to run straight inland, and it is now an appellation in its own right, sitting on marine sedimentary ground rather than basalt. The wind through it can knock several degrees off an afternoon. Wind of that persistence shuts the stomata and thickens skins, so the wines carry more tannin and more colour than the valley average, and harvest there runs later than in the hills to the north."},
{"id": "c-u096ad7s", "cat": "Pacific NW, NY & Canada", "q": "An umbrella appellation created in 2004 lets a grower in the south of the state blend across two separate river valleys and still name a place. Which two does it gather?", "opts": ["The Umpqua Valley and the Rogue Valley", "The Rogue Valley and the Columbia Gorge", "The Willamette Valley and the Umpqua Valley", "The Willamette Valley and the Columbia Gorge"], "a": 0, "exp": "Southern Oregon was drawn to cover both valleys and everything nested inside them, because producers there were routinely buying across the two and had no legal way of saying so. The country is warmer, drier and far more broken than the Willamette, sheltered by mountains on three sides, and it grows Syrah, Tempranillo and the Bordeaux varieties rather than the Pinot Noir the state is known for."},
{"id": "c-1cv3ha90", "cat": "Pacific NW, NY & Canada", "q": "A tributary valley nested inside the Rogue runs warm and dry enough for Syrah and Cabernet Sauvignon, where the parent appellation is otherwise a patchwork of climates. Name the nested appellation.", "sa": 1, "accept": ["applegate valley", "applegate", "applegate valley ava", "applegate valley appellation", "applegate valley in oregon", "applegate valley in the rogue valley"], "ans": "Applegate Valley", "ex": 1, "exp": "The Applegate River drains north out of the Siskiyou Mountains into the Rogue, and its valley is narrow, sheltered and consistently warmer than the rest of the parent zone, with decomposed granite underfoot. The Rogue Valley appellation around it swings from that heat to the cool, wet Illinois Valley in the west, which is why one description of the parent has never fitted."},
{"id": "c-byck0b8m", "cat": "Pacific NW, NY & Canada", "q": "Vines across the Columbia basin are trained with two or three trunks rising from the ground rather than one, and an own-rooted block can be brought back from the base after the worst nights. Which hazard shapes both practices?", "opts": ["Phylloxera arriving through the graft union", "A hard winter freeze that kills wood above ground", "Wind off the river snapping a single trunk", "Spring frost during flowering"], "a": 1, "exp": "Arctic air spilling south over the Rockies is the one thing that limits where the state can plant, and it arrives every few years rather than every year. A bad night kills a trunk or two, and a spare means the dead one can be cut out without losing the vine; the worst nights take everything above the soil, and because so much of the state is planted on its own roots, a shoot from the insulated crown below is the same variety and can simply be trained up as a replacement. A grafted vine's basal shoot would be rootstock, which is why the same accident costs a Napa grower a replanting."},
{"id": "c-p6pp51i9", "cat": "Pacific NW, NY & Canada", "q": "The Columbia Valley appellation does not stop at the Washington state line. Which neighbouring state does it continue into?", "opts": ["Idaho", "Oregon", "British Columbia", "Montana"], "a": 1, "exp": "The appellation follows the river's basin rather than any political boundary, so it takes in a strip on the Oregon side as well, and Walla Walla Valley and Columbia Gorge both straddle the line in the same way. British Columbia is a province rather than a state and lies well north of the boundary in any case, since an American viticultural area cannot cross an international border."},
{"id": "c-6xyrydx2", "cat": "Pacific NW, NY & Canada", "q": "Where the ice-age floods backed up behind a narrow gap in the basalt, the ponded water dropped its silt in rhythmic layers that now floor the deepest vineyard soils of the Walla Walla Valley. Name those slackwater deposits.", "sa": 1, "accept": ["touchet beds", "touchet bed", "touchet", "touchets", "touchet formation", "touchet beds formation", "touchet silts", "touchet sediments", "touchet deposits", "touchet rhythmites", "touchet slackwater deposits", "touchet slackwater beds", "touchet beds slackwater deposits", "touchet beds of the walla walla valley", "touchet beds in the walla walla valley"], "ans": "The Touchet beds", "ex": 1, "exp": "Wallula Gap is the bottleneck: the floodwater arrived faster than the gap could pass it and ponded back up the tributary valleys, settling out fine material every time it stalled. Each flood left a layer, so the beds are stacked like pages and can be counted in a road cut, and where they are deep the vine roots never reach the cobbles beneath them at all."},
{"id": "c-cz0onehy", "cat": "Pacific NW, NY & Canada", "q": "Under the silt and the flood gravel of eastern Washington lies a stack of lava flows more than a mile thick, poured out long before any ice age. Name that rock formation.", "sa": 1, "accept": ["columbia river basalt group", "columbia river basalt", "columbia river basalts", "columbia river flood basalts", "columbia river flood basalt", "columbia flood basalts", "columbia flood basalt", "columbia river basalt formation", "columbia river basalt group crbg", "crbg"], "ans": "The Columbia River Basalt Group", "ex": 1, "exp": "The flows erupted from long fissures and spread out flat, filling the basin layer on layer and damming rivers as they went. Everything a Washington grower farms sits on that stack: the ridges are folds in it, the cobbles the floods carried are broken pieces of it, and the same rock reappears west of the Cascades as the hills of the northern Willamette."},
{"id": "c-9kd1m5qf", "cat": "Pacific NW, NY & Canada", "q": "The boundary of one American appellation was drawn to follow a single soil series, a fan of dark cobbles dumped where a river leaves the mountains. Which appellation?", "opts": ["Snipes Mountain", "Naches Heights", "The Rocks District of Milton-Freewater", "Ancient Lakes of Columbia Valley"], "a": 2, "exp": "The petition argued the case from the soil survey, so the boundary is the outline of a single soil series on a single alluvial fan and nothing else. The stones are rounded basalt, dark enough to hold the day's heat well into the night, and the wines off them carry a savoury, smoked character growers claim to recognise blind. It lies wholly in Oregon, although the town it is named for sits at the Washington line."},
{"id": "c-815mbm39", "cat": "Pacific NW, NY & Canada", "q": "Washington's first appellation, delimited in 1983, sits as a middle tier with Columbia Valley above it and several smaller appellations nested inside it. Name it.", "sa": 1, "accept": ["yakima valley", "yakima", "yakima valley ava", "yakima valley appellation", "yakima valley in washington"], "ans": "Yakima Valley", "ex": 1, "exp": "Red Mountain, Rattlesnake Hills and Snipes Mountain all sit inside it, and every one of them can also print Columbia Valley, so a single wine may legitimately carry any of three names of decreasing size. The valley is the oldest planted part of the state and runs cooler than the country east of it, which is why so much of the state's white fruit comes from there."},
{"id": "c-3zur8exk", "cat": "Pacific NW, NY & Canada", "q": "Wind rolling up off the Columbia River never lets up on the long Washington slope that falls south from a valley rim to the water, and growers there bank on the small berries and thick skins it gives them. Name that appellation.", "sa": 1, "accept": ["horse heaven hills", "horse heaven", "horse heaven hills ava", "the horse heaven hills appellation"], "ans": "Horse Heaven Hills", "exp": "The ground runs down toward the river in a single tilted sheet, so the aspect is uniform and the wind has nothing to break it. That wind is a working tool rather than a nuisance: it shrinks berries and raises the skin to juice ratio, and it dries the canopy fast enough that fungal disease is close to unknown there."},
{"id": "c-paee39dr", "cat": "Pacific NW, NY & Canada", "q": "One Washington appellation sees barely six inches of rain in a year, and every acre of it is planted where canal water can be lifted onto a single unbroken incline below the Saddle Mountains. Name it.", "sa": 1, "accept": ["wahluke slope", "wahluke", "wahluke slope ava", "the wahluke slope appellation"], "ans": "Wahluke Slope", "exp": "It is among the warmest and driest ground in the state, with the mountains cutting off the north wind and the river below it moderating nothing very much. Nothing grows there without irrigation, which means the grower sets vine vigour entirely by the tap, and the fruit ripens early and dependably enough that it is a major source for red blends made elsewhere in the state."},
{"id": "c-o6tymq39", "cat": "Pacific NW, NY & Canada", "q": "Idaho's vineyards run hot by day, freeze hard in winter and work a short season besides. Which single geographic fact drives all three?", "opts": ["Elevation, in a basin far inland from any ocean", "A rain shadow cast by the Coast Range, which strips the marine air out before it arrives", "A valley floor that opens directly onto the Pacific and takes the weather first", "Latitude north of the forty-seventh parallel, further north than any Washington vineyard"], "a": 0, "exp": "Vineyards there sit well above two thousand feet, higher than anything planted in Washington, and thin air at that height sheds the day's heat fast once the sun goes down. The result is a diurnal swing wide enough to hold acidity through a hot afternoon, a winter cold enough to demand hardy training, and a frost-free window short enough that late-ripening varieties are a gamble."},
{"id": "c-n6gx3rxy", "cat": "Pacific NW, NY & Canada", "q": "Vines in Idaho cluster in one appellation southwest of Boise, floored by the sediments of a lake that drained away in the Pliocene, and it reaches west across the state line. Name it.", "sa": 1, "accept": ["snake river valley", "snake river valley ava", "snake river valley appellation", "snake river valley in idaho"], "ans": "Snake River Valley", "ex": 1, "exp": "The old lake bed left silts and sands over basalt, and the appellation crosses into eastern Oregon because the same basin does. Growers plant on the slopes and terraces above the river rather than on the flat, since cold air pools on the floor in winter and the difference between a bench and the ground below it can decide whether a block survives."},
{"id": "c-y9kh51ed", "cat": "Pacific NW, NY & Canada", "q": "Buds on a slope above a Finger Lake come through a night at ten below zero Fahrenheit while a planting a few miles inland is killed outright. What is the water doing?", "opts": ["Raising the humidity so the buds cannot desiccate", "Reflecting low winter sunlight back onto the slope", "Giving back the heat it stored, and keeping the air moving", "Holding budbreak back until the frost season has ended"], "a": 2, "exp": "A deep lake takes all summer to warm and all winter to give that heat up, so it is still releasing warmth in January when the vineyard needs it most. The stirring matters as much as the warmth: air rising off the water pulls cold air off the slopes instead of letting it settle, which is why the vineyard sits on the sides of the trough and not on the flat ground at either end."},
{"id": "c-f28qgard", "cat": "Pacific NW, NY & Canada", "q": "Prevailing westerlies cross the deepest of the Finger Lakes before they reach the far shore, which is why growers on that side see the mildest winters in the region. Name the lake.", "sa": 1, "accept": ["seneca lake", "lake seneca", "seneca", "seneca lake ava", "lake seneca ava", "seneca lake appellation", "seneca lake in the finger lakes", "seneca lake new york", "seneca lake in new york"], "ans": "Seneca Lake", "ex": 1, "exp": "It runs to more than six hundred feet deep, enough that it effectively never freezes over, and the wind picks up warmth and moisture the whole way across before it reaches the eastern shore. That shore carries the densest planting in the region, and the difference between it and the western side of the same lake is measured in whole degrees rather than fractions."},
{"id": "c-r1i04gcg", "cat": "Pacific NW, NY & Canada", "q": "One of the Finger Lakes forks into a Y, and the region's wine industry began on its shore at Hammondsport in the 1860s. Name that lake.", "sa": 1, "accept": ["keuka lake", "lake keuka", "keuka", "keuka lake ava", "lake keuka ava", "keuka lake appellation", "keuka lake in the finger lakes", "keuka lake new york", "keuka lake in new york"], "ans": "Keuka Lake", "ex": 1, "exp": "The Y shape gives it far more shoreline for its length than a straight trough would, and the bluff between the two branches is planted on both faces. The industry that started there was built on native and hybrid varieties and on sweet sparkling wine, and vinifera only arrived a century later, which is why the oldest cellars in the region look nothing like the newest."},
{"id": "c-0mqtty1y", "cat": "Pacific NW, NY & Canada", "q": "Delimited in 1988, the first appellation ever nested inside the Finger Lakes AVA follows the shoreline slopes of the longest lake in the region. Name it.", "sa": 1, "accept": ["cayuga lake", "lake cayuga", "cayuga", "cayuga lake ava", "lake cayuga ava", "cayuga lake appellation", "cayuga lake in the finger lakes", "cayuga lake new york", "cayuga lake in new york"], "ans": "Cayuga Lake", "ex": 1, "exp": "It runs some thirty-eight miles north to south, longer than any of its neighbours though not the deepest, and the appellation follows its shoreline slopes rather than the country between the lakes. The second nested appellation was drawn fifteen years later around a neighbouring lake, and everything outside the two of them carries the regional name alone."},
{"id": "c-7gg379fv", "cat": "Pacific NW, NY & Canada", "q": "Federal law lets a wine made from Concord or Niagara print its variety at a lower minimum than a Chardonnay needs. What is the figure for those native varieties?", "opts": ["85 percent", "75 percent", "Every grape in the bottle", "51 percent"], "a": 3, "exp": "The allowance exists because labrusca character is so assertive that a bare majority of it already dominates a blend, and the wines were traditionally softened with something neutral. A label using it has to carry an appellation of origin as well, and the ordinary 75 percent minimum still applies to everything else, so a Riesling and a Concord standing side by side on a New York shelf are held to different rules."},
{"id": "c-jh8sw72q", "cat": "Pacific NW, NY & Canada", "q": "Sand and gravel dumped at the edge of an ice sheet floor the strip of Long Island that carries almost all of the island's vineyard, and that strip holds an appellation distinct from the umbrella one. Name it.", "sa": 1, "accept": ["north fork of long island", "north fork", "north fork of long island ava", "north fork of long island appellation", "long island north fork", "north fork ava", "the north fork appellation"], "ans": "The North Fork of Long Island", "ex": 1, "exp": "The forks are the two arms of a terminal moraine and its outwash, left where the ice stalled, so the ground is sandy and drains hard. Water on three sides stretches the autumn out by weeks against anywhere inland, which is why Merlot and Cabernet Franc ripen there and why a tropical storm arriving in September is the hazard growers actually plan around."},
{"id": "c-ogj6yymb", "cat": "Pacific NW, NY & Canada", "q": "A pungent grape-jelly note gives away Concord and its relatives in a blind glass, and one ester carries most of the blame for it. Name that compound.", "sa": 1, "accept": ["methyl anthranilate", "methylanthranilate", "ester methyl anthranilate", "methyl anthranilate ester", "the compound methyl anthranilate"], "ans": "Methyl anthranilate", "ex": 1, "exp": "It is present in labrusca and its hybrids at levels vinifera never reaches, and it is the same compound used to flavour grape soda and sweets, which is why the association runs the way it does. Tasters usually call the character foxy, and a small proportion of a labrusca variety in a blend is enough to make a wine smell of it."},
{"id": "c-9w6hed70", "cat": "Pacific NW, NY & Canada", "q": "In 1988 British Columbia paid its growers to tear out roughly two thirds of the province's vines inside a single season. What forced that?", "opts": ["Phylloxera reached the valley and forced a wholesale replanting on resistant rootstock", "Two winters in a row killed the vineyard outright", "A federal ban on the use of hybrid grapes for wine", "A trade agreement opened the border to cheaper wine"], "a": 3, "exp": "The vineyard at the time was mostly hybrid and labrusca material planted for volume, and it could not survive being priced against imports. The pull-out looks brutal on paper and was the making of the modern industry: what went back in was vinifera on the warmest sites, and the appellation system that followed a couple of years later was written to protect the replanting."},
{"id": "c-6w1pultw", "cat": "Pacific NW, NY & Canada", "q": "Deep windblown sand on the east side of the valley floor south of Oliver carries the ripest Bordeaux reds in Canada. Name that bench.", "sa": 1, "accept": ["black sage bench", "black sage", "black sage bench sub gi", "black sage bench in the okanagan"], "ans": "Black Sage Bench", "ex": 1, "exp": "The sand is deep enough that vines can be planted on their own roots, and it warms fast and drains completely, which at that latitude matters more than any nutrient it lacks. This is the driest end of the valley, close to true desert, and everything there is irrigated from the lakes that run down the middle of it."},
{"id": "c-z4bknzgb", "cat": "Pacific NW, NY & Canada", "q": "The first sub-appellation ever delimited inside the Okanagan Valley sits on the valley's western side above Oliver, where the slopes take the morning sun and fall into shade early. Name it.", "sa": 1, "accept": ["golden mile bench", "golden mile", "golden mile bench sub gi", "golden mile bench appellation", "golden mile bench in the okanagan"], "ans": "Golden Mile Bench", "ex": 1, "exp": "Facing east means the fruit warms early and is then shaded through the hottest part of the afternoon, which holds acidity in a valley that can be punishingly hot in August. The bench sits on an alluvial fan below the mountains, and the neighbouring Similkameen Valley over the ridge to the west is the other place in the province regularly compared with it."},
{"id": "c-9ljj13hh", "cat": "Pacific NW, NY & Canada", "q": "Bulk wine shipped in from abroad and blended with Ontario fruit puts a bottle outside the VQA system altogether, and Canadian labelling rules set out what it has to say about itself instead. Give that label statement.", "sa": 1, "accept": ["international blend from imported and domestic wines", "international blend from domestic and imported wines", "international blend of imported and domestic wines", "international blend", "international canadian blend", "international canadian blends", "international canadian blend icb", "icb"], "ans": "International blend from imported and domestic wines", "ex": 1, "exp": "VQA guarantees that every grape was grown in the province named, that the variety and the ripeness at harvest meet a written standard, and that the wine itself has satisfied a tasting panel before the term may be used, none of which an American appellation asks. A blend carrying imported wine can meet none of that, so the label has to declare it, and the order of the words tracks the blend: imported first when most of the wine came from abroad, domestic first when most of it is Canadian. The trade and the shelf tags still call the category an International Canadian Blend, or ICB, but Cellared in Canada, the wording these bottles carried for years, was retired when the labelling rules changed and is no longer permitted."},
{"id": "c-atb8n93b", "cat": "Pacific NW, NY & Canada", "q": "Temperature at picking is only half of Canada's icewine rule: the juice coming off the press has to reach a stated concentration as well. Give that minimum must weight.", "sa": 1, "accept": ["thirty five degrees brix", "35 degrees brix", "35 brix", "thirty five brix", "35", "minimum 35 brix", "35 brix minimum", "at least 35 brix", "at least thirty five brix", "a minimum of 35 brix", "minimum 35 degrees brix", "35 degrees brix minimum", "a minimum of 35 degrees brix", "at least 35 degrees brix", "at least thirty five degrees brix", "thirty five degrees brix minimum", "35 brix or more", "35 degrees brix or more", "no less than 35 brix", "must weight of 35 brix", "minimum must weight of 35 brix", "35 brix must weight", "35 brix at pressing", "thirty five brix at pressing", "35 degrees brix at the press"], "ans": "Thirty-five degrees Brix", "ex": 1, "exp": "Both halves are enforced, and either one can end a harvest: a mild winter that never delivers the cold means no picking, and fruit that has hung too long in damp weather can arrive dilute even when it is frozen solid. The finished wine carries a residual sugar floor as well, so a producer cannot press to weight and then ferment the sweetness away."},
{"id": "c-sbso69yj", "cat": "Pacific NW, NY & Canada", "q": "Growers in one Ontario appellation lay the canes down and plough soil over them every November, then uncover them in spring, because winter there kills anything left standing. Name that appellation.", "sa": 1, "accept": ["prince edward county", "prince edward county ontario", "prince edward county ontario canada", "prince edward county appellation", "prince edward county in ontario", "prince edward county wine region", "prince edward county ava", "prince edward county vqa", "pec", "prince edward county pec", "pec prince edward county"], "ans": "Prince Edward County", "ex": 1, "exp": "It lies out in Lake Ontario well east of the main Ontario vineyard, and the water lengthens the season there, but the Bay of Quinte behind it and the shallow water inshore freeze in deep winter and stop moderating anything at the moment it is needed. Midwinter lows near thirteen below zero Fahrenheit will kill an exposed vine outright. The soil is a thin, stony loam straight onto limestone, which is what persuades people to bother, and burying the vines by hand every autumn is the price of farming Chardonnay and Pinot Noir there at all."},
{"id": "c-1wcnttzv", "cat": "Portugal", "q": "Beside plain Vinho Verde, an importer's book lists a Vinho Verde Sousa and a Vinho Verde Moncao e Melgaco. What has each of those producers taken on?", "opts": ["A minimum year in bottle before release, to justify the longer name", "A vintage declaration, which plain Vinho Verde is not permitted to carry", "Estate bottling, since subregion names are closed to merchant blends", "Fruit drawn entirely from the named subregion, and from the varieties it recommends"], "a": 3, "exp": "A subregion on the label ties the wine to that ground alone and to the grapes the rules recommend for it, which is the region's own map of quality: Alvarinho around Moncao e Melgaco, Loureiro along the Lima, Avesso inland at Baiao. Plain Vinho Verde may carry a vintage perfectly freely, and merchants blend subregional wine like anyone else."},
{"id": "c-x16dzww3", "cat": "Portugal", "q": "Thirteen percent of alcohol in a Moncao e Melgaco Alvarinho startles a guest who knows Vinho Verde as a feather-light spritz. What makes the wine legal?", "opts": ["Varietal Alvarinho is given its own higher alcohol band than ordinary Vinho Verde", "A dispensation bought vintage by vintage from the regional commission", "The producer declassified it to espumante, where strength is uncapped", "Nothing does; above eleven and a half percent the wine has to leave the DOC and sell as Minho regional"], "a": 0, "exp": "Ordinary Vinho Verde is capped at eleven and a half percent, where its light style lives, while varietal Alvarinho may climb to fourteen. Moncao e Melgaco sits in the warm, dry lee of the mountains along the Spanish border, and the ripeness Alvarinho finds there is the whole reason the exception exists."},
{"id": "c-d8erebz9", "cat": "Portugal", "q": "From Moncao e Melgaco in the north down to Baiao on the Douro's doorstep, subregions partition the whole of Vinho Verde. Give the count.", "sa": 1, "accept": ["nine", "9", "nine subregions", "9 subregions", "nine sub regions", "9 sub regions", "nine in total", "9 in total", "nine in all", "9 in all", "there are nine", "there are 9", "nine of them", "9 of them", "there are nine subregions", "there are 9 subregions", "there are nine sub regions", "there are 9 sub regions", "nine subregions in total", "9 subregions in total", "nine sub regions in total", "9 sub regions in total"], "ans": "Nine", "ex": 1, "exp": "Amarante, Ave, Baiao, Basto, Cavado, Lima, Moncao e Melgaco, Paiva and Sousa make the nine, each following a river or a market town. Only a few of them mean anything on an export label, which is exactly why the ones that do are worth knowing."},
{"id": "c-o6nxljap", "cat": "Portugal", "q": "Old Minho photographs show vines scrambling ten metres up poplars and chestnuts at the field edges. Give the local name for that training.", "sa": 1, "accept": ["vinha de enforcado", "vinhas de enforcado", "enforcado"], "ans": "Vinha de enforcado", "exp": "The enforcado, the hanged vine, climbed a living tree called an uveira: the uveira is the tree itself, the enforcado the vine trained up it, and only enforcado names a way of training. Hanging the fruit ten metres up kept it above the damp air at ground level and left the soil below free for cabbages and maize. Pergolas did the same job along the lanes, and modern cordon rows have replaced both wherever the holding is large enough to bother."},
{"id": "c-ol27vlz5", "cat": "Portugal", "q": "Pale rose now leaves the Vinho Verde region in serious quantity, most of it from one generously cropping black grape kept largely for the purpose. Name it.", "sa": 1, "accept": ["espadeiro", "espadeiro grape", "espadeiro grape variety", "espadeiro variety", "espadeiro rose", "espadeiro rosado", "espadeiro rose grape", "espadeiro rosado grape", "espadeiro black grape", "black grape espadeiro"], "ans": "Espadeiro", "ex": 1, "exp": "Espadeiro crops heavily and colours lightly, which is precisely what a pale, sharp, faintly prickling rose asks of a grape. Padeiro plays the same role around Basto, and neither makes red of any consequence."},
{"id": "c-cca9yl4d", "cat": "Portugal", "q": "One Douro parcel, one grape, two prices: the lot sold for Port fetches several times what the lot sold for dry red does. What is being paid for?", "opts": ["Higher must weights, since Port fruit hangs later and comes in sweeter", "The fortification licence attached to the fruit, the beneficio, rather than the fruit itself", "The cost of the fortifying spirit, which the grower is expected to supply with the grapes", "Hand harvesting, which the Port houses demand and the table-wine cellars do not"], "a": 1, "exp": "The beneficio rations fortification rights across the valley by each parcel's graded score, and the licence, not the grape, carries the premium. For most of a century table wine was simply what the licence left behind, which is the shadow the valley's dry reds grew up under; the best estates now route old-vine fruit to them by choice rather than by default."},
{"id": "c-qxsasasg", "cat": "Portugal", "q": "Persuaded by a hillside parcel of Syrah, a Douro estate bottles it varietally and finds the DOC closed to it. Under which designation does the wine sell?", "opts": ["DOC Tras-os-Montes", "Vinho Regional Transmontano", "Vinho Regional Minho", "Vinho Regional Duriense"], "a": 3, "exp": "The Douro DOC admits an approved list of overwhelmingly native varieties, so anything outside it drops to the regional tier, and Duriense covers the same ground with looser rules. Transmontano and Tras-os-Montes belong to the high country north of the valley, a separate region altogether."},
{"id": "c-izko1vb8", "cat": "Portugal", "q": "Deep in colour and stubborn about keeping its acid through a Douro heatwave, one dark-fleshed grape is the blender's tool for freshness; the Minho grows the same vine as Vinhao. Give the Douro's name for it.", "sa": 1, "accept": ["sousao", "souzao", "sousaos", "souzaos", "sousao or souzao", "souzao or sousao", "sousao and souzao", "souzao and sousao", "sousao also souzao", "sousao also spelled souzao", "sousao also spelt souzao", "~sousao souzao", "~souzao sousao", "~sousao grape", "~souzao grape", "~grape sousao", "~grape souzao", "~sousao variety", "~souzao variety", "~sousao black", "~souzao black", "~sousao red", "~souzao red", "~sousao dark", "~is sousao", "~sousao is", "~is souzao", "~souzao is", "~sousao called", "~sousao known", "~sousao douro", "~douro sousao", "~sousao in the douro"], "ans": "Sousao", "ex": 1, "exp": "Sousao carries pigment in its pulp as well as its skin and holds malic acid that the valley's heat strips from everything else, so a modest share of it steadies a blend. One vine, two careers: bracing young red in the wet north, seasoning grape in the hot east. Sousa, one letter short of it, is a Minho subregion and nothing to do with the grape."},
{"id": "c-xmzrbs1s", "cat": "Portugal", "q": "Its long, loose bunch reminded someone of a cat's tail, and the name stuck to a white grape now prized for the Douro's high-altitude whites. Name it.", "sa": 1, "accept": ["rabigato", "rabigatos", "~rabigato grape", "~grape rabigato", "~rabigato variety", "~rabigato white", "white rabigato", "~rabigato cats tail", "~rabigato cat's tail", "~is rabigato", "~rabigato is", "~douro rabigato", "~rabigato in the douro"], "ans": "Rabigato", "ex": 1, "exp": "Rabigato, the cat's tail, brings acid and a stony austerity to parcels planted five and six hundred metres up, usually alongside Viosinho and Gouveio. It is not to be confused with Rabo de Ovelha, the ewe's tail, nor with Rabigato Franco, which adds a word to the name and is a separate Douro white again."},
{"id": "c-xcf3s3vn", "cat": "Portugal", "q": "Pinhao sits where its own tributary meets the river, ringed by the densest concentration of top-graded quintas in the valley. Which Douro sub-region is this?", "sa": 1, "accept": ["cima corgo", "cima corgo subregion", "cima corgo sub region"], "ans": "Cima Corgo", "exp": "The Cima Corgo is the historic heart of the valley, and the amphitheatres around Pinhao hold more A-graded vineyard than anywhere else on the river. The same slopes that command the best fortification licences now yield many of the most serious dry reds, which is the valley's economics in one view."},
{"id": "c-2s8ueo4v", "cat": "Portugal", "q": "A 2003 rewrite of Bairrada's DOC rules still divides the region's growers. What did it do?", "opts": ["Made Baga compulsory at eighty-five percent of every red carrying the name, squeezing the rest out", "Closed the DOC to purchased fruit, ending the merchant trade overnight", "Opened the DOC's reds to outside varieties, Cabernet Sauvignon and Syrah among them", "Stripped sparkling wine out of the DOC and handed it a separate denomination"], "a": 2, "exp": "Before 2003 a Bairrada red meant Baga above all; the revision admitted Touriga Nacional, Cabernet Sauvignon, Merlot and Syrah, and traditionalists read it as the region trading its identity for easy ripeness. The dissenters' answer was Baga Friends, a growers' alliance pledged to the old grape, and some celebrated estates still prefer the Beira Atlantico regional label to the widened DOC."},
{"id": "c-lsf8njbx", "cat": "Portugal", "q": "Trace Touriga Nacional's paper trail back far enough and it runs home to one region, where old growers still call it Tourigo. Which region?", "opts": ["Bairrada", "The Douro", "The Dao", "The Alentejo"], "a": 2, "exp": "The grape's oldest documented home is the Dao's granite, where Tourigo and Mortagua survive as its local names, and the Douro adopted it from there. Miserly yields nearly finished it before selection work rebuilt the plantings, and the Dao's red blends still lean on it first."},
{"id": "c-fq5o8hha", "cat": "Portugal", "q": "Stricter sourcing and longer ageing than the plain DOC demands let a Dao label add one word, the Portuguese for noble. Give the word.", "sa": 1, "accept": ["nobre", "dao nobre"], "ans": "Nobre", "exp": "Nobre sits above the ordinary appellation and its Reserva, asking for the region's recommended grapes and more time before release, and it is claimed rarely enough that many drinkers have never met one. The Dao was demarcated in 1908, among Portugal's first, and Encruzado whites and Touriga-led reds are the word's natural candidates."},
{"id": "c-h2bt90t5", "cat": "Portugal", "q": "Small, thick-skinned and mean-yielding, Bairrada's defining grape bears a name that is simply the Portuguese for the thing itself. Translate baga.", "sa": 1, "accept": ["berry", "berries", "grape berry", "small berry", "it means berry", "means berry", "single berry", "baga means berry", "baga is berry"], "ans": "Berry", "ex": 1, "exp": "Baga means berry, and the bunches are packed with small, thick-skinned ones, which is where the colour, the fierce tannin and the rot worry on wet clay all begin. The grape covers most of Bairrada's red vineyard and shoulders much of its espumante base besides."},
{"id": "c-osbslgds", "cat": "Portugal", "q": "Dao growers saddled one white grape with the name Borrado das Moscas, fly droppings, for its speckled skins; Bairrada treats the same grape as the backbone of its whites. Give its Bairrada name.", "sa": 1, "accept": ["bical", "bical grape"], "ans": "Bical", "exp": "Bical ripens early, holds its acid on the cold clay, and anchors both the still whites and the traditional-method espumante Bairrada has made since the 1890s. Maria Gomes, its usual partner there, supplies the perfume Bical keeps to itself."},
{"id": "c-c0pdug4d", "cat": "Portugal", "q": "Clay touches a great deal of Alentejo wine; the Vinho de Talha DOC asks for much more than a finishing spell in it. Where does the rule draw the line?", "opts": ["The vessels must predate phylloxera, and wine from new-made clay is disqualified", "Fermentation itself must happen in the clay, skins and all, in the old Roman manner", "Only fruit grown in the Vidigueira subregion may claim it, wherever the cellar stands", "The wine must rest in the clay a full five years, twice what a Reserva serves, before bottling"], "a": 1, "exp": "The designation protects a method rather than a flavour of ageing: the grapes ferment in the talha with their skins, the cap sinking back as the ferment dies, and the wine rests there under a film of olive oil until Saint Martin's Day in November, when tradition taps the first vessel. Amphora wine made any other way sells as plain Alentejo, however much clay it saw."},
{"id": "c-eq87mgob", "cat": "Portugal", "q": "Weeks before vintage an Alentejo cellar warms its empty talhas and melts a dark paste across their insides. What is the paste doing?", "opts": ["Sealing the porous clay with pez, a blend of pine resin and beeswax", "Baking cooked must onto the walls, which darkens the wine and rounds its finish", "Laying down a lime wash to disinfect the clay after last year's lees are scrubbed out", "Building up a wax skin that will be peeled away together with the finished wine"], "a": 0, "exp": "Pez, resin and beeswax in proportions each house keeps to itself, is all that stands between the wine and the open pores of fired clay; the coating is renewed because a failed seal turns a talha into a slow drain. Tasters credit the resin with a quiet part of the style as well, the way the pine speaks in some old Mediterranean wines."},
{"id": "c-zm3hotas", "cat": "Portugal", "q": "Borba, Redondo, Reguengos and Vidigueira head the roll of the Alentejo DOC's subregions. Give the full count.", "sa": 1, "accept": ["eight", "8", "eight subregions", "8 subregions", "eight sub regions", "8 sub regions", "eight in total", "8 in total", "eight in all", "8 in all", "there are eight", "there are 8", "eight of them", "8 of them", "there are eight subregions", "there are 8 subregions", "there are eight sub regions", "there are 8 sub regions", "eight subregions in total", "8 subregions in total", "eight sub regions in total", "8 sub regions in total"], "ans": "Eight", "ex": 1, "exp": "Portalegre, Evora, Granja-Amareleja and Moura complete the eight, every one a delimited DOC subregion inside the wider Alentejo. The spread is greater than one name suggests, from mountain vineyards in the north to some of the hottest ground in Portugal at Granja-Amareleja."},
{"id": "c-ctm9fzcv", "cat": "Portugal", "q": "Great southern landholdings put a word on Alentejo labels where a northern label would say quinta. Give the word.", "sa": 1, "accept": ["herdade", "herdades"], "ans": "Herdade", "exp": "A herdade is the Alentejo's vast agricultural holding, wine one crop among cork, olives and grazing, and the scale is the point: hundreds of hectares where a Douro quinta might count dozens. Monte, which also appears on labels, is strictly the farmhouse standing on the property rather than the property itself."},
{"id": "c-htisxdzp", "cat": "Portugal", "q": "Neighbours a few hundred metres apart near Sintra grow the same grapes, yet one label reads Colares and the other must say Lisboa. What separates the two?", "opts": ["One vineyard stands grafted, and Colares admits only ungrafted stock", "The DOC requires trench planting by hand, and one grower cut corners with a machine auger", "Only vines rooted in the deep dune sand, the chao de areia, may claim the DOC", "One parcel falls inside protected Sintra parkland that the appellation excludes"], "a": 2, "exp": "Colares is delimited by its soil: the DOC belongs to the wind-blown sand that defeated phylloxera, while the firm clay ground behind it, the chao rijo, grows the same Ramisco and Malvasia de Colares for the regional label. The sand is the appellation, and everything else about the place follows from it."},
{"id": "c-uo76ycwq", "cat": "Portugal", "q": "Sharp enough that its name means dog-strangler, the traditional second grape of white Bucelas is the same variety Madeira grows as Sercial. Give the mainland name.", "sa": 1, "accept": ["esgana cao", "esgana"], "ans": "Esgana Cao", "exp": "Esgana Cao keeps its acid in real heat, which earned it both the name and its place beside Arinto, the grape that must itself supply at least seventy-five percent of any white Bucelas. Rabo de Ovelha is the other traditional supporting variety in this small, white-only appellation."},
{"id": "c-ctgcbdrz", "cat": "Portugal", "q": "Between 1931 and the 1990s no grower could sell Colares at all without passing the wine through a single institution's cellars. Name it.", "sa": 1, "accept": ["adega regional de colares", "adega de colares", "colares regional adega", "regional adega of colares", "adega regional of colares"], "ans": "Adega Regional de Colares", "exp": "The Adega Regional de Colares was founded in 1931 and held a legal monopoly on vinifying the appellation for six decades, which is why old Colares carries one cellar's stamp whoever grew the fruit. Liberalisation in the 1990s let independent producers emerge, and the Adega still makes and ages much of what little Colares exists."},
{"id": "c-up9z2yt0", "cat": "Portugal", "q": "Sharing a name across a thousand miles of ocean, the Arinto of Bucelas and the Arinto dos Acores of Pico invite an assumption. What is the truth of it?", "opts": ["They are a single variety, its acid sharpened by the volcanic ground", "The island vine descends from cuttings the first settlers carried out", "The mainland grape is a parent, crossed on the island with a native vine", "They are unrelated; the island grape merely wears a mainland name"], "a": 3, "exp": "Ampelography separates them cleanly: Arinto dos Acores is a variety of its own that happens to wear a borrowed name, and its salty, smoky whites taste nothing like Bucelas. A shared name settles nothing about parentage in Portugal, where growers named vines for what they looked like and the same word turns up two provinces away on something else entirely."},
{"id": "c-5q10panp", "cat": "Portugal", "q": "Grown above Funchal and fermented dry, a still red of Tinta Negra cannot call itself Madeira. What may the label say?", "opts": ["Madeirense under the island's own DOC, with Terras Madeirenses covering the regional tier", "Madeira Seco, the term the rules reserve for the island's unfortified wine", "Nothing at all; the island's table wine may only be sold to visitors on the spot", "Vinho Regional Atlantico, a designation shared with the Azores"], "a": 0, "exp": "The bare name Madeira belongs to the fortified wine, so the island's growing table-wine trade ships as DOC Madeirense or as Terras Madeirenses regional wine. Dry Tinta Negra reds and Verdelho whites lead it, much of the fruit coming off the cooler north coast."},
{"id": "c-usvf5yfc", "cat": "Portugal", "q": "Azorean wine grown outside the demarcated islands' appellations sells under a regional designation covering the whole archipelago. Give it.", "sa": 1, "accept": ["acores", "azores", "vinho regional acores", "vinho regional azores", "regional acores", "regional azores", "igp acores", "igp azores", "vr acores", "vr azores"], "ans": "Acores", "ex": 1, "exp": "The Acores regional designation catches everything the island appellations do not, and a good deal of the modern revival ships under it by choice, varietal labelling being freer there. The volcanic rock and the salt wind mark the wines whichever name they carry."},
{"id": "c-10hyg7tz", "cat": "Portugal", "q": "Pico has its DOC and Terceira has Biscoitos; one more Azorean island carries a wine appellation of its own. Name it.", "sa": 1, "accept": ["graciosa", "ilha graciosa", "graciosa island", "graciosa doc"], "ans": "Graciosa", "exp": "Graciosa, gentler and lower than its neighbours, is the third demarcated wine island, its light dry white drawn from an old field mix rather than from any single variety. Biscoitos is a parish on Terceira's north coast rather than an island of its own, which is the trap: three islands hold an appellation, and Graciosa is the one that gets forgotten."},
{"id": "c-kzempmo1", "cat": "Portugal", "q": "Almost every Portuguese wine region answers to a grower-funded regional commission, but two answer to standing public institutes instead. Which two?", "opts": ["Alentejo and Setubal", "The Douro and Madeira", "Vinho Verde and the Dao", "Bairrada and the Azores"], "a": 1, "exp": "The Douro's institute certifies the valley's unfortified DOC wine as well as Port, one body for both trades, and Madeira keeps a public institute of its own. Everywhere else the tasting panels and the numbered seal on the back label belong to the region's own commission."},
{"id": "c-srsyzoiu", "cat": "Portugal", "q": "Planting rights, the national record of who grows what, and the whole sector's oversight sit with one Lisbon institute above all the regional bodies. Give its initials.", "sa": 1, "accept": ["ivv", "i v v", "instituto da vinha e do vinho", "instituto da vinha e vinho"], "ans": "IVV", "ex": 1, "exp": "The Instituto da Vinha e do Vinho is the national umbrella: it holds the records of what is planted where, manages planting authorisations and answers for Portugal in Brussels, while day-to-day certification is delegated regionally. Nothing about an individual bottle passes through it, which is exactly the division of labour the system intends."},
{"id": "c-3a1cqrsm", "cat": "Portugal", "q": "Three letters, CVR, open the name of most of Portugal's certifying bodies for wine, the ones answering for Lisboa and the Tejo among them. Write the Portuguese out in full.", "sa": 1, "accept": ["comissao vitivinicola regional", "comissoes vitivinicolas regionais"], "ans": "Comissao Vitivinicola Regional", "exp": "Each Comissao Vitivinicola Regional is funded by its growers and trade, runs the tasting panels, and polices both the DOC and the regional wine of its area, issuing the numbered guarantee seals. Two of them wear older names: the Vinho Verde body, founded in 1926 and the model the rest were built on, is still the Comissao de Viticultura da Regiao dos Vinhos Verdes, and the Algarve's certifier is the Comissao Vitivinicola do Algarve, with no Regional in it at all."},
{"id": "c-79x8sovi", "cat": "Producers & Icons", "q": "One French grand cru appellation covers exactly the ground of a single property, so the appellation boundary and the estate map are the same line. Which appellation?", "opts": ["Echezeaux", "Musigny", "Romanee-Conti", "Corton"], "a": 2, "exp": "The appellation runs to a shade under two hectares in Vosne-Romanee and has not been divided in living memory, so a vintage yields one wine and one only. Echezeaux and Corton sit at the other extreme, each of them split among dozens of separate owners, and even Musigny, small as it is, is shared among a handful."},
{"id": "c-v3tuj2ue", "cat": "Producers & Icons", "q": "A narrow strip of vineyard runs straight up the slope between Romanee-Conti and La Tache, and every row of it has long been farmed by one family. Name that climat.", "sa": 1, "accept": ["la grande rue", "la grande rue grand cru", "la grande rue monopole", "the la grande rue climat", "grande rue in vosne romanee", "la grande rue vineyard"], "ans": "La Grande Rue", "ex": 1, "exp": "It was left a premier cru when the grand crus of Vosne-Romanee were drawn up in the 1930s and was promoted only in 1992, late enough that older books still print it a rank below its neighbours. The name records an old road running up the hill rather than any claim about the wine, and the strip is narrow because it follows that route."},
{"id": "c-qzkt8t21", "cat": "Producers & Icons", "q": "Clos Sainte Hune, a walled plot of a little over a hectare and a half at Hunawihr, lies inside one of Alsace's grand crus, though the label has traditionally said nothing about it. Name the grand cru.", "sa": 1, "accept": ["rosacker", "rosacker grand cru", "grand cru rosacker", "the rosacker vineyard", "rosacker at hunawihr", "rosacker in alsace", "rosacker grand cru at hunawihr"], "ans": "Rosacker", "ex": 1, "exp": "Rosacker is limestone and dolomite on the slope above Hunawihr, and the clos sits in the heart of it. The house behind the wine built its reputation long before the grand cru system was delimited at all, which is why the plot name has always carried more weight on that label than the site name would."},
{"id": "c-o2br7e1i", "cat": "Producers & Icons", "q": "A wall dated 1698 encloses just under two hectares of Chardonnay in the middle of the village of Le Mesnil-sur-Oger, and the house that bought it in 1971 bottles the plot on its own in declared years. Name the clos.", "sa": 1, "accept": ["clos du mesnil", "clos du mesnil blanc de blancs", "krug clos du mesnil", "clos du mesnil in le mesnil sur oger", "the clos du mesnil vineyard"], "ans": "Clos du Mesnil", "ex": 1, "exp": "Being walled inside a village rather than open on the slope, it ripens a little differently from the vineyard around it, which is the whole argument for keeping it apart. A single-vineyard Champagne of this kind gives up the blender's usual insurance, so it appears only in years the plot can carry a wine by itself."},
{"id": "c-hmzqy4rb", "cat": "Producers & Icons", "q": "Above the Marne at Mareuil-sur-Ay a walled slope pitches at something close to forty-five degrees, the steepest planted ground in Champagne, and it has been bottled as a vintage wine in nearly every harvest since 1935. Name that clos.", "sa": 1, "accept": ["clos des goisses", "goisses", "philipponnat clos des goisses", "clos des goisses at mareuil sur ay", "clos des goisses monopole"], "ans": "Clos des Goisses", "ex": 1, "exp": "The pitch and the due-south exposure ripen fruit well ahead of the villages around it, which is why the wine can be declared in years its neighbours would not. Goisses comes from a local word for a very steep slope, so the name describes the ground rather than the wine, and the wall marks a holding that has never been broken up."},
{"id": "c-4l80uqzs", "cat": "Producers & Icons", "q": "A guest compares two vintages of one classified Medoc estate and finds the first blend led by Merlot and the second by Cabernet Sauvignon, although no vines were pulled up between them. What accounts for the swing?", "opts": ["The estate replanted a large parcel and did not announce it", "Lots that fell short of the grand vin were left out of it, and which variety fell short differs from one year to the next", "Appellation rules fix a different blend for each vintage according to the season", "The second wine takes a fixed share of every variety, so what remains sets the proportions"], "a": 1, "exp": "Planting is a decision of decades and blending a decision of one winter, so the two never match. A wet September that spoils the Merlot and a cool one that leaves the Cabernet green both show up in the assemblage rather than in the vineyard, and an estate that kept its proportions fixed in spite of the season would be bottling its weather, not correcting for it."},
{"id": "c-i4gif156", "cat": "Producers & Icons", "q": "Alsace's grand cru rules admit only one named site to a label, so a house whose long-lived Riesling cuvee is drawn from parcels in a pair of them prints no grand cru name at all. Which grand crus are blended in that cuvee?", "sa": 1, "accept": ["geisberg and osterberg", "osterberg and geisberg", "geisberg osterberg", "osterberg geisberg", "grand cru geisberg and grand cru osterberg", "geisberg and osterberg above ribeauville", "the geisberg and osterberg grand crus"], "ans": "Geisberg and Osterberg", "ex": 1, "exp": "The pair sit side by side on the slope above Ribeauville, Geisberg the steeper and more terraced of them, and a blend across the two forfeits a mention that either could have carried alone. The house treats its own cuvee name as the stronger claim, which is a fair reading of how Alsace was actually sold before the grand crus were delimited."},
{"id": "c-3d2sajyy", "cat": "Producers & Icons", "q": "One Champagne prestige cuvee is assembled from several declared vintages rather than from a single one, on the argument that a blend of good years beats the best of them alone, and it therefore carries no date. Name that cuvee.", "sa": 1, "accept": ["grand siecle", "laurent perrier grand siecle", "grand siecle laurent perrier", "the grand siecle cuvee"], "ans": "Grand Siecle", "exp": "Each release blends years the house had declared as vintages in their own right, which reverses the usual assumption that a vintage wine outranks a blended one. The house now numbers each release as an iteration in its own sequence, and each is built from a different trio of those years rather than to a fixed recipe."},
{"id": "c-0coqytc6", "cat": "Producers & Icons", "q": "A dry white is pressed at the sole Premier Cru Superieur of Sauternes, from the same rows as its sweet wine, and it goes to market under a single letter of the alphabet. Name that wine.", "sa": 1, "accept": ["ygrec", "y", "y ygrec", "the letter y", "ygrec dry white", "y dry white of yquem", "ygrec the dry white of yquem", "the dry white called y", "y d'yquem", "ygrec d'yquem", "y yquem", "ygrec yquem", "y of yquem", "ygrec of yquem"], "ans": "Ygrec", "ex": 1, "exp": "Ygrec is the French name of the letter Y, and the wine is a Sauvignon and Semillon blend from fruit picked before botrytis takes hold, or from a year in which it never does. It is not declassified sweet wine: the decision is taken at the start of the harvest rather than at the end of it, and the wine is fermented dry on purpose. Yquem stands alone as Premier Cru Superieur above the eleven first growths of 1855, several of which now press a dry white of their own under a single initial, R at Rieussec, S at Suduiraut and G at Guiraud."},
{"id": "c-qlpd15m4", "cat": "Producers & Icons", "q": "Two adjoining Stags Leap District vineyards, S.L.V. and Fay, are normally bottled apart; in years when a barrel selection drawn from both is judged to beat either, one Napa winery releases a third wine instead. Name it.", "sa": 1, "accept": ["cask 23", "cask twenty three", "cask 23 cabernet sauvignon", "the cask 23 bottling", "stag s leap wine cellars cask 23", "cask 23 from stag s leap"], "ans": "Cask 23", "ex": 1, "exp": "The wine began as a single cask set aside in 1974 and has been made only in vintages the cellar thinks justify it. Naming the source vineyards on their own labels and blending them for the flagship is the reverse of the Bordeaux habit, where the blend is the flagship and the parcels are never seen at all."},
{"id": "c-mmw62wod", "cat": "Producers & Icons", "q": "From the 2012 vintage one Pauillac first growth stopped offering its wine as futures and now releases each vintage when it judges the wine ready to drink. What changed for the buyer?", "opts": ["It arrives a year earlier, before the final blend has been settled", "Only the estate may sell it, the negociants of the Place having been cut out of the trade altogether", "The estate's 1855 rank lapses on any vintage sold outside a futures campaign", "It arrives years later, at a price set against the market of the day"], "a": 3, "exp": "Selling futures moves the cash risk from the chateau to the buyer and the storage risk with it, and withdrawing reverses both. The estate holds the stock in its own cellars for a decade and releases in tranches, and the trade still handles the wine, so what disappeared is the barrel sale rather than the merchant."},
{"id": "c-d2nsvzb7", "cat": "Producers & Icons", "q": "A Cote des Blancs house has never made a non-vintage wine, a rose or a blend of villages, and in a year it does not care for it releases nothing at all under its name. Name that house.", "sa": 1, "accept": ["salon", "champagne salon", "maison salon", "salon le mesnil", "salon blanc de blancs", "salon cuvee s", "cuvee s salon", "salon of le mesnil sur oger"], "ans": "Salon", "ex": 1, "exp": "Fewer than fifty vintages have been released since the first in 1905, so in most years the fruit it has contracted goes elsewhere and no bottle appears. The wine is a blanc de blancs from one grand cru village, held far beyond the legal minimum before disgorgement, and the refusal to make anything else is the whole of the house's proposition."},
{"id": "c-h9mftt6b", "cat": "Producers & Icons", "q": "One Champagne house releases the same vintage more than once: at around eight years, and then again after far longer on the lees, with every release presented as a further stage in that wine's life. What does the house call those stages?", "sa": 1, "accept": ["plenitude", "plenitudes", "p2", "p3", "p 2", "p 3", "plenitude p2", "second plenitude", "deuxieme plenitude", "plenitude releases", "plenitude p3", "the plenitude stages"], "ans": "Plenitude", "ex": 1, "exp": "The argument is that a wine on its lees does not develop steadily but arrives at a series of windows, and the cellar disgorges at each of them rather than once. The later releases were sold for years under a different name borrowed from the house's own library before the current one was adopted, so old bottles and new ones carry both."},
{"id": "c-u86xw2t7", "cat": "Producers & Icons", "q": "Growers in one Jura appellation submit their wine to a committee that may refuse the whole vintage, and when it does, not a bottle is sold under the name. Name that appellation.", "sa": 1, "accept": ["chateau chalon", "chateau chalon aoc", "aoc chateau chalon", "the chateau chalon appellation", "chateau chalon vin jaune", "chateau chalon in the jura"], "ans": "Chateau-Chalon", "ex": 1, "exp": "The appellation makes vin jaune and nothing else, and the wine spends more than six years in cask under a veil of yeast before it may be bottled, so a refusal falls on work long since done. Whole vintages were declassified outright in the 1970s and 1980s, and the rejected wine goes to market as plain Cotes du Jura instead."},
{"id": "c-wyk6w0ha", "cat": "Producers & Icons", "q": "Asked at the table what a Bordeaux second wine actually contains, a sommelier should be able to answer without guessing. What governs it?", "opts": ["Fruit from a separate vineyard the estate keeps for the purpose, outside its classified holding", "A share of the crop fixed by the appellation, which is why the proportion barely moves from one vintage to the next", "The press wine, the free-run juice all going into the grand vin", "Whatever the estate left out of its grand vin, most often young vines and parcels that underperformed"], "a": 3, "exp": "Nothing in law fixes the category, so a second wine carries the same appellation as the grand vin and differs from it only by selection. Estates that once sold their surplus lots in bulk now bottle them, and several have added a third wine underneath, which is a commercial judgement about how far the selection can be pushed."},
{"id": "c-kmcq86cg", "cat": "Producers & Icons", "q": "A Margaux third growth presents its junior label not as a strainer for lots that missed the grand vin but as a different reading of the same vineyard, picked and raised its own way. Name that wine.", "sa": 1, "accept": ["alter ego", "alter ego de palmer", "the alter ego of palmer", "alter ego the second label"], "ans": "Alter Ego", "exp": "Palmer makes the point that the wine is not lesser but different: more Merlot, earlier picking, a shorter elevage and a style meant to be drunk sooner. Whether a buyer accepts that or reads it as a second wine with better marketing is exactly the argument the label was built to start."},
{"id": "c-r5pn982f", "cat": "Producers & Icons", "q": "Bahans Haut-Brion disappeared from wine lists after the 2006 vintage, although the wine behind the name did not. What is that second wine called now?", "sa": 1, "accept": ["le clarence de haut brion", "clarence", "clarence of haut brion", "le clarence de haut brion the second wine"], "ans": "Le Clarence de Haut-Brion", "ex": 1, "exp": "The name honours Clarence Dillon, the American financier who bought the property in 1935, and the change lined the second wine up with the family name used across the group. Second labels are renamed often enough that a wine list can be years out of date without anyone noticing, which is reason enough to check the vintage against the name."},
{"id": "c-fhfdt1u9", "cat": "Producers & Icons", "q": "One Ribera del Duero bodega sells a red in its fifth year, drawn from the same vineyards as a flagship it holds back roughly twice as long. Name the wine released early.", "sa": 1, "accept": ["valbuena", "valbuena 5", "valbuena 5o", "valbuena cinco", "vega sicilia valbuena", "valbuena quinto ano", "valbuena 5 ano", "the valbuena bottling"], "ans": "Valbuena", "ex": 1, "exp": "The number in its name counts the years from harvest to release rather than anything about the blend, and the fruit comes off the same estate rather than off lesser ground. Selling a serious wine early is a cash decision as much as a stylistic one, since a cellar holding stock for a decade has to be paid for somehow."},
{"id": "c-amoc86xq", "cat": "Producers & Icons", "q": "A Napa estate founded as a Franco-American partnership sells a second wine blended across several harvests, so it carries no vintage at all. Name it.", "sa": 1, "accept": ["overture", "overture from opus one", "opus one overture", "the overture bottling", "overture napa valley", "overture by opus one"], "ans": "Overture", "ex": 1, "exp": "Blending several years into one red is ordinary in Champagne and rare in Napa, where the vintage date is treated as part of the claim. It is sold largely at the winery rather than through the trade, which is why it turns up on wine lists far less often than the estate's flagship does."},
{"id": "c-5rxvl2uz", "cat": "Producers & Icons", "q": "Printed on a French label the word Chateau is not decoration, and it may be used only where a pair of conditions are met. Which pair?", "opts": ["The grapes all come off the estate's own vines, and the wine is vinified there", "The estate holds a rank in a recognised classification, and a building stands on the land", "The fruit is grown and bottled in the same commune, and the label states the year the estate was founded", "The property sits inside a communal appellation, and its owner farms at least ten hectares"], "a": 0, "exp": "The rule is about the fruit and the winemaking rather than about architecture: every grape must be grown on the named holding and the wine made there, so plenty of chateaux are sheds and plenty of grand houses have no vines at all. It comes from the same body of French law that governs Domaine, Clos, Cru and Abbaye, all of them traditional terms with conditions attached rather than free adjectives."},
{"id": "c-riqvksrt", "cat": "Producers & Icons", "q": "In Jerez a private stockholder buys young wine, ages a few butts of it in a warehouse of his own and sells the result on to the shippers rather than bottling under his own name. What is he called?", "sa": 1, "accept": ["almacenista", "almacenistas", "almacenista stockholder", "a jerez almacenista"], "ans": "Almacenista", "exp": "The word means warehouseman, and the trade grew up because ageing stock is slow money that a small holder can afford to tie up and a shipper would rather buy than carry. Some of those soleras are now bottled under the almacenista's name alongside the shipper's, which is how a category that existed to be invisible became collectable."},
{"id": "c-nbqtlnyu", "cat": "Producers & Icons", "q": "Until 1986 no Port could be exported unless it had first been aged in one town across the river from Oporto, which is why the quintas up the valley shipped nothing under their own names. Name that town.", "sa": 1, "accept": ["vila nova de gaia", "gaia", "villa nova de gaia", "vila nova de gaia across the douro"], "ans": "Vila Nova de Gaia", "exp": "The rule bound the trade to the shippers' lodges and to their entrepot, so a grower who wanted to sell abroad had to sell to a shipper first. Its repeal is why estates up the valley began bottling and exporting under their own names from the late 1980s, and the modern shape of the Douro trade follows from it."},
{"id": "c-xj14c8m6", "cat": "Producers & Icons", "q": "A Burgundian grower who buys grapes as well as farming his own registers a second business for the bought fruit, and by long convention its bottles open with a different word from the estate's. Which word?", "sa": 1, "accept": ["maison", "maison rather than domaine", "the word maison", "maison instead of domaine", "maison followed by the name", "maison on the label", "the maison prefix", "maison not domaine"], "ans": "Maison", "ex": 1, "exp": "Domaine is reserved by law for wine off the grower's own vines and Maison signals a merchant business, even where one family runs both from one cellar. Maison is defined nowhere at all, which is why a house that farms not a single row may call itself one with nobody's permission; what the law polices is the word Domaine, and the merchant word is left to the trade's own convention."},
{"id": "c-vgei16c5", "cat": "Producers & Icons", "q": "Barrels sold at the Hospices de Beaune auction are catalogued under cuvee names that appear on no map of the slope, and the buyer's own cellar raises and bottles the wine afterwards. What do those cuvee names record?", "sa": 1, "accept": ["the benefactors who gave the vineyards", "benefactors", "donors", "the people who donated the vines", "the donors of the vineyards", "benefactors who donated the vines", "the names of the donors", "past donors", "the people who gave the vineyards to the hospices", "the donors who left vines to the hospital"], "ans": "The benefactors who gave the vineyards", "exp": "The hospital has been left vines since the fifteenth century, and each bequest is kept as a named cuvee rather than folded into the rest, so the catalogue reads as a list of benefactors. A cuvee may draw on parcels in more than one climat, which is exactly why those names cannot be found on any vineyard map."},
{"id": "c-bl1htcv1", "cat": "Producers & Icons", "q": "Long before grafting, a grower who lost a vine bent a cane down from the plant beside it, buried the middle of that cane until it took root and then cut it free. Which operation is this?", "opts": ["Palissage", "Ebourgeonnage", "Provignage", "Greffage"], "a": 2, "exp": "The new plant grows on its own roots and carries the parent's material exactly, so a plot renewed this way keeps whatever selection was originally in it. It also explains why old ungrafted parcels are irregularly spaced: a vine put there by layering stands where its parent could reach, not where a surveyor wanted it."},
{"id": "c-o3ac6k48", "cat": "Producers & Icons", "q": "Small walled parcels at Ay carry Pinot Noir that was never grafted onto American rootstock, and the blanc de noirs made from them runs to a few thousand bottles in the years it appears. Name that cuvee.", "sa": 1, "accept": ["vieilles vignes francaises", "vvf", "bollinger vieilles vignes francaises", "vieilles vignes francaises bollinger", "the vieilles vignes francaises cuvee", "bollinger vvf", "vieilles vignes francaises champagne"], "ans": "Vieilles Vignes Francaises", "ex": 1, "exp": "French old vines is all the name claims, and the point of it is the ungrafted stock rather than the age of any particular plant. A third parcel at Bouzy was lost to phylloxera and grubbed up in the 2000s, which is a reminder that such plots survive by constant work rather than by luck."},
{"id": "c-l3ixwno5", "cat": "Producers & Icons", "q": "A single Yountville vineyard planted in the nineteenth century supplies the whole of a Napa red whose name is the Latin for lord and master of the house. Name the vineyard.", "sa": 1, "accept": ["napanook", "napanook vineyard", "napanook in yountville", "the napanook site"], "ans": "Napanook", "exp": "Napanook was among the first vineyards planted in that part of the valley and its fruit was sold to other wineries for most of a century before it was bottled on its own. Yountville sits between the cool of Oak Knoll and the warmth of Oakville, which is much of why the wine is built on structure rather than on ripeness."},
{"id": "c-lc9eawhv", "cat": "Producers & Icons", "q": "A Bordeaux family that had already founded a Napa joint venture set up a second one in the 1990s on Andean gravels in the upper Maipo, and the wine took its name from a character in Beaumarchais. Name it.", "sa": 1, "accept": ["almaviva", "vina almaviva", "almaviva in maipo", "almaviva chile", "the almaviva red"], "ans": "Almaviva", "exp": "Count Almaviva belongs to The Marriage of Figaro, and the label carries a design borrowed from Mapuche art, so the bottle advertises both partners at once. The Chilean partner was already growing Cabernet of the first rank on that stretch of gravel, which is why the ground was settled before the deal was."},
{"id": "c-hl5fhle1", "cat": "Producers & Icons", "q": "A Saint-Emilion first growth and a Mendoza estate share a Malbec-led red grown on stony Andean ground at around a thousand metres. Name that wine.", "sa": 1, "accept": ["cheval des andes", "cheval des andes mendoza", "terrazas cheval des andes", "the cheval des andes joint venture"], "ans": "Cheval des Andes", "exp": "Malbec leads it and Cabernet Sauvignon fills it out, which is the Bordeaux partner's contribution to a grape Argentina had long bottled on its own. Mendoza's old ungrafted Malbec is the material such ventures are really after, since cuttings of that quality no longer exist in the variety's homeland."},
{"id": "c-hln4baio", "cat": "Producers & Icons", "q": "Mosel estates have always aged in a large oval cask of about a thousand litres, and older price lists quote a crop by the number of them filled. Name that cask.", "sa": 1, "accept": ["fuder", "fuders", "fuder cask", "mosel fuder", "german fuder", "a thousand litre fuder", "1000 litre fuder"], "ans": "Fuder", "ex": 1, "exp": "A thousand litres of wine touching that much oak takes almost nothing from the wood, which is exactly the point on a Riesling meant to taste of slate and fruit. The half-size cask is a Halbfuder and the Rhine's equivalent is larger again, and all of them are giving way in many cellars to steel, which does the same job of adding nothing at all."},
{"id": "c-srnjzxpk", "cat": "Producers & Icons", "q": "Bordeaux quotes a crop and a price in a unit that no cellar actually contains: nine hundred litres, or four barriques. Name that unit.", "sa": 1, "accept": ["tonneau", "tonneaux", "one tonneau", "the bordeaux tonneau"], "ans": "Tonneau", "exp": "Nine hundred litres is twelve hundred bottles, or a hundred cases of twelve, so a chateau's crop and an opening price are both still discussed in tonneaux although the wine never sits in one. It is a unit of account inherited from the days when claret travelled in cask, and it survives because everyone in the trade can convert it in their head."},
{"id": "c-6i2c510m", "cat": "Producers & Icons", "q": "Northern Rhone cellars often raise Syrah in a cask of about six hundred litres, larger than a barrique and smaller than a foudre, chosen so that the oak marks the wine less. Name it.", "sa": 1, "accept": ["demi muid", "demi muids", "demimuid", "demi muid cask"], "ans": "Demi-muid", "exp": "Half a muid, the muid being an old measure that varied from town to town, so the name is a fossil of a unit nobody uses any more. The wider stave and the lower ratio of wood to wine give slower oxygen and much less vanilla than a barrique, which is why estates trying to lighten their oak move to this size rather than merely to older barrels."},
{"id": "c-4q6cwbcc", "cat": "Producers & Icons", "q": "Douro contracts and lodge records still count in a cask of roughly five hundred and fifty litres, and a shipper's stock is described in them rather than in litres. Name that cask.", "sa": 1, "accept": ["pipe", "pipes", "port pipe", "the douro pipe", "pipa", "a pipe of port", "port pipes", "pipe cask", "port pipe cask"], "ans": "Pipe", "ex": 1, "exp": "The word covers a family of sizes rather than one exact volume, since the shipping pipe of about 534 litres, the valley pipe of 550 and the larger lodge pipe used for ageing all differ. Production of a declared vintage is still quoted in pipes, which is why the figures in a trade report never look like litres."},
{"id": "c-6ij9t52x", "cat": "Producers & Icons", "q": "Two bottles of one house's multi-vintage cuvee carry different edition numbers on the label, and no vintage appears anywhere on either. What does that number identify?", "opts": ["The particular blend, so one release can be told from the next", "The cellar in which that lot was aged, which the house treats as part of the wine's identity", "How long the wine spent on its lees before it was disgorged", "The dosage in grams per litre, printed as a code rather than a figure"], "a": 0, "exp": "A multi-vintage blend is remade every year and is never quite the same wine twice, which the old convention of calling it simply non-vintage concealed. Numbering the releases lets a buyer, a sommelier and a critic all refer to one specific assembly, and some houses print a further code that resolves to the disgorgement date."},
{"id": "c-l4tqtqtm", "cat": "Producers & Icons", "q": "One Reims house prints on every non-vintage bottle the year in which the blend went down into its cellar, so a buyer can work out how long it lay there before release. Give the French phrase used for that statement.", "sa": 1, "accept": ["mis en cave", "mise en cave", "the mis en cave date", "mis en cave year", "date de mise en cave"], "ans": "Mis en cave", "exp": "The blend is assembled from one harvest and its reserves and then bottled for its second fermentation, and the year printed is the year that happened. A bottle laid down in one year and released six later has therefore spent that whole span on its lees, which the label of an ordinary non-vintage leaves a buyer to guess at."},
{"id": "c-1u8qzqeq", "cat": "Producers & Icons", "q": "Tiny quantities of intensely extracted Right Bank red, made in the 1990s in cellars barely larger than the buildings they were nicknamed after, earned their makers a label they never chose. What were they called?", "sa": 1, "accept": ["garagistes", "garagiste", "garage winemakers", "the garage movement"], "ans": "Garagistes", "exp": "The name began as a jibe about scale and the wines turned it into a marketing category, with prices following critical scores rather than any classification. The style went out of fashion as taste moved back towards freshness, but the argument it started, about whether a small parcel farmed obsessively can outrank a classified estate, has not gone away."},
{"id": "c-ig7f970i", "cat": "Producers & Icons", "q": "Across the top of a bottle of everyday claret run the words Grand Vin de Bordeaux, printed larger than anything else on the label. What does that phrase promise about the wine?", "sa": 1, "accept": ["nothing at all", "nothing", "nothing whatever", "it promises nothing", "no guarantee", "it guarantees nothing", "absolutely nothing", "no promise at all", "nothing it has no legal meaning", "nothing the phrase has no legal force", "nothing whatsoever", "no promise", "it means nothing", "it has no legal meaning", "no legal meaning", "it carries no legal meaning", "it has no legal force", "no legal force", "nothing legally", "it is not defined in law", "no legal definition", "it has no legal definition"], "ans": "Nothing at all", "ex": 1, "exp": "Grand vin has a real use inside a chateau, where it names the estate's first selection as against its second wine, but printed as a slogan on a regional bottling it carries no requirement of any kind. The statements that do bind on that label are the appellation, the vintage and the bottling line, and none of them is usually the largest thing on it."},
{"id": "c-nyvmy41t", "cat": "Producers & Icons", "q": "Merchants who want a case of one Vosne-Romanee domaine's grand crus are obliged to take a spread of its lesser wines in the same shipment. What does that practice achieve for the domaine?", "opts": ["It satisfies a Burgundian rule obliging a producer to offer its whole range to any buyer", "The whole range moves, the famous bottles carrying the rest with them", "It keeps the grand crus out of the auction rooms, where resale is forbidden by the appellation", "It lowers the duty due on the shipment, which is levied on the case rather than on the bottle"], "a": 1, "exp": "A village Vosne-Romanee is a harder sell than a grand cru, and tying the two together means the cellar never has to discount either of them. The buyer's compensation is that the door stays open for the next vintage, which is worth more than the margin lost on the wines they did not especially want."},
{"id": "c-xba125m0", "cat": "Producers & Icons", "q": "One Barossa house has kept a workshop inside its winery since the 1940s, turning out something almost every other winery in the world buys in. What does it make there?", "sa": 1, "accept": ["oak barrels", "barrels", "casks", "oak casks", "wooden barrels", "wooden casks", "barriques", "wine barrels", "its own barrels", "its own oak barrels", "its own casks", "its own oak casks", "its own wooden barrels", "its own wooden casks", "its own barriques", "its own wine barrels", "it makes barrels", "it makes oak barrels", "it makes casks", "it makes oak casks", "it makes wooden barrels", "it makes wooden casks", "it makes barriques", "it makes wine barrels", "it makes its own barrels", "it makes its own oak barrels", "it makes its own casks", "it makes its own oak casks", "it makes its own wooden barrels", "it makes its own wooden casks", "it makes its own barriques", "it makes its own wine barrels", "cooperage", "its own cooperage", "barrels in its own cooperage", "barrel", "oak barrel", "makes barrels", "makes oak barrels", "makes casks", "makes its own barrels", "makes its own oak barrels", "makes its own casks", "it makes its barrels", "it makes all its own barrels", "they make their own barrels", "make their own barrels", "it builds its own barrels", "builds its own barrels", "it makes and repairs barrels", "it still makes its own barrels", "it still makes its own oak barrels", "oak barrels in its own cooperage", "oak casks and barrels", "barrels and casks", "it has its own cooperage", "has its own cooperage", "its cooperage", "a working cooperage", "in house cooperage"], "ans": "Oak barrels", "ex": 1, "exp": "Yalumba is the house, and a working cooperage lets it buy standing timber, season the staves for as long as it likes and build to its own specification rather than take what a supplier offers. Almost nobody else bothers, because the craft takes a cooper's whole working life to learn and one winery needs only a few hundred barrels a year."},
{"id": "c-tnkw4xfz", "cat": "Producers & Icons", "q": "In a vintage judged not strong enough, a Barbaresco cooperative declines to bottle any of the nine single-vineyard Riservas it is known for. What becomes of that fruit?", "sa": 1, "accept": ["the cooperative's straight barbaresco", "the straight barbaresco", "the normale barbaresco", "the normale", "the normal barbaresco", "the regular barbaresco", "the basic barbaresco", "the entry level barbaresco", "the ordinary barbaresco", "the classic barbaresco", "the standard barbaresco", "the plain barbaresco", "one barbaresco", "it goes into the cooperative's straight barbaresco", "it goes into the straight barbaresco", "it goes into the normale barbaresco", "it goes into the normale", "it goes into the normal barbaresco", "it goes into the regular barbaresco", "it goes into the basic barbaresco", "it goes into the entry level barbaresco", "it goes into the ordinary barbaresco", "it goes into the classic barbaresco", "it goes into the standard barbaresco", "it goes into the plain barbaresco", "it goes into one barbaresco", "it all goes into the cooperative's straight barbaresco", "it all goes into the straight barbaresco", "it all goes into the normale barbaresco", "it all goes into the normale", "it all goes into the normal barbaresco", "it all goes into the regular barbaresco", "it all goes into the basic barbaresco", "it all goes into the entry level barbaresco", "it all goes into the ordinary barbaresco", "it all goes into the classic barbaresco", "it all goes into the standard barbaresco", "it all goes into the plain barbaresco", "it all goes into one barbaresco", "all of it goes into the cooperative's straight barbaresco", "all of it goes into the straight barbaresco", "all of it goes into the normale barbaresco", "all of it goes into the normale", "all of it goes into the normal barbaresco", "all of it goes into the regular barbaresco", "all of it goes into the basic barbaresco", "all of it goes into the entry level barbaresco", "all of it goes into the ordinary barbaresco", "all of it goes into the classic barbaresco", "all of it goes into the standard barbaresco", "all of it goes into the plain barbaresco", "all of it goes into one barbaresco", "it is blended into the cooperative's straight barbaresco", "it is blended into the straight barbaresco", "it is blended into the normale barbaresco", "it is blended into the normale", "it is blended into the normal barbaresco", "it is blended into the regular barbaresco", "it is blended into the basic barbaresco", "it is blended into the entry level barbaresco", "it is blended into the ordinary barbaresco", "it is blended into the classic barbaresco", "it is blended into the standard barbaresco", "it is blended into the plain barbaresco", "it is blended into one barbaresco", "it is all blended into the cooperative's straight barbaresco", "it is all blended into the straight barbaresco", "it is all blended into the normale barbaresco", "it is all blended into the normale", "it is all blended into the normal barbaresco", "it is all blended into the regular barbaresco", "it is all blended into the basic barbaresco", "it is all blended into the entry level barbaresco", "it is all blended into the ordinary barbaresco", "it is all blended into the classic barbaresco", "it is all blended into the standard barbaresco", "it is all blended into the plain barbaresco", "it is all blended into one barbaresco", "blended into the cooperative's straight barbaresco", "blended into the straight barbaresco", "blended into the normale barbaresco", "blended into the normale", "blended into the normal barbaresco", "blended into the regular barbaresco", "blended into the basic barbaresco", "blended into the entry level barbaresco", "blended into the ordinary barbaresco", "blended into the classic barbaresco", "blended into the standard barbaresco", "blended into the plain barbaresco", "blended into one barbaresco", "it is declassified into the cooperative's straight barbaresco", "it is declassified into the straight barbaresco", "it is declassified into the normale barbaresco", "it is declassified into the normale", "it is declassified into the normal barbaresco", "it is declassified into the regular barbaresco", "it is declassified into the basic barbaresco", "it is declassified into the entry level barbaresco", "it is declassified into the ordinary barbaresco", "it is declassified into the classic barbaresco", "it is declassified into the standard barbaresco", "it is declassified into the plain barbaresco", "it is declassified into one barbaresco", "it all ends up in the cooperative's straight barbaresco", "it all ends up in the straight barbaresco", "it all ends up in the normale barbaresco", "it all ends up in the normale", "it all ends up in the normal barbaresco", "it all ends up in the regular barbaresco", "it all ends up in the basic barbaresco", "it all ends up in the entry level barbaresco", "it all ends up in the ordinary barbaresco", "it all ends up in the classic barbaresco", "it all ends up in the standard barbaresco", "it all ends up in the plain barbaresco", "it all ends up in one barbaresco"], "ans": "It all goes into the cooperative's straight Barbaresco", "ex": 1, "exp": "The crus are bottled only when the year justifies them, so a weak vintage yields one wine where a strong one yields ten. It runs against the usual incentive, since the cru bottlings are the profitable ones, and it is why the cooperative's ordinary Barbaresco in a lesser year is better than its price suggests."},
{"id": "c-xaoghak9", "cat": "Producers & Icons", "q": "Chateauneuf-du-Pape permits a long list of varieties, and one celebrated estate there ignores all but a single grape, growing it on sand well back from the stony plateau. Which variety fills that red?", "sa": 1, "accept": ["grenache", "grenache noir", "black grenache", "garnacha", "grenache alone", "one hundred percent grenache", "100% grenache", "pure grenache", "only grenache", "nothing but grenache", "grenache noir alone", "all grenache", "100 percent grenache", "100 % grenache", "grenache 100%", "grenache 100 percent", "100% grenache noir"], "ans": "Grenache", "ex": 1, "exp": "Chateau Rayas is the estate, and its red carries no Syrah, no Mourvedre and nothing else the decree allows. Sand, the shade of surrounding pine woods and very low yields give a wine so pale and perfumed that it is regularly mistaken for red Burgundy blind, which is much of the reason it is argued about."},
{"id": "c-th12qpbq", "cat": "Rhône", "q": "Between the 1960s and the 1980s the delimited area above Ampuis grew several times over, and the growers who had stayed on the terraces objected to the ground being added. Where was that ground?", "opts": ["The flat plateau behind the top of the slope", "The left bank of the river, looking back at the terraces", "Alluvial islands and river flats lying at the foot of the terraces", "Terraces already replanted to Viognier for white wine"], "a": 0, "exp": "The terraces had been abandoned by the hundred because no machine can work them, and planting the plateau behind was the only cheap way to enlarge the appellation. Fruit up there ripens later and rarely carries the perfume of the slope, which is why the appellation name alone now tells a buyer less than it once did."},
{"id": "c-ehe1sor3", "cat": "Rhône", "q": "Growers at Ampuis distinguish an old, small-berried, low-cropping local strain of the black grape from the high-yielding clones planted since the 1970s, and some print its name on the label. Give that name.", "sa": 1, "accept": ["serine", "serine syrah", "the serine selection", "serine massal selection"], "ans": "Serine", "exp": "Serine is a massal selection rather than a separate variety, so it is Syrah to an ampelographer and something rather different in the vineyard: tiny bunches, small crops and a firmer, peppery wine. Growers replanting after the clonal wave of the 1970s went back to cuttings taken from old parcels to recover it, which is why the word turns up on labels at all."},
{"id": "c-nz1r5mfe", "cat": "Rhône", "q": "A summer storm at Ampuis can strip the topsoil off a terrace in an hour, and a grower there reckons on more days a year at masonry than at pruning. What is being repaired?", "sa": 1, "accept": ["dry stone walls", "dry stone wall", "dry stone retaining walls", "stone retaining walls", "dry stone terrace walls", "drystone walls", "drystone wall", "drystone retaining walls", "drystone terrace walls"], "ans": "Dry-stone walls", "exp": "The terraces are held by walls laid without mortar, and no machine can rebuild one; the labour is the reason so much of the slope went out of production in the middle of the twentieth century. Water that gets in behind a wall pushes it out, so the gaps between the stones are not sloppy work but the whole design."},
{"id": "c-xd9g81ly", "cat": "Rhône", "q": "A grower at Chavanay picks Viognier off one terrace and Syrah off the next, and bottles the two separately. Which pair of appellations do the wines carry?", "opts": ["Saint-Peray for the white and Crozes-Hermitage for the red", "Chateau-Grillet for the white and Cornas for the red", "Condrieu for the white and Saint-Joseph for the red", "Condrieu for the white and Cote-Rotie for the red"], "a": 2, "exp": "Condrieu and Saint-Joseph overlap across several communes at the northern end of the valley, so a single hillside carries one name or the other according to what is planted on it. Cote-Rotie stops well short of Chavanay to the north, and Chateau-Grillet is a single enclosed amphitheatre a few kilometres upstream of it, at Verin and Saint-Michel-sur-Rhone, that no other grower may use."},
{"id": "c-fe0zuhpx", "cat": "Rhône", "q": "A sweet Condrieu appears on a list and a guest objects that the appellation covers dry white only. What is the position?", "opts": ["The sweet wine exists but must go out as Chateau-Grillet", "The appellation is dry only, so the bottle must be labelled Vin de France", "Sweetness is allowed only in a vintage the syndicat declares for it", "The decree permits a sweet wine from late-picked fruit, and a little is made most years"], "a": 3, "exp": "Condrieu was historically as often sweet as dry and the decree still allows it, but the wines are rare because Viognier's acidity has usually collapsed by the time the sugar is high enough to be worth leaving. Look for moelleux or doux on the label, since the appellation name on its own will not tell you."},
{"id": "c-3d8qkv5n", "cat": "Rhône", "q": "Seven communes make Condrieu, and they fall in three different departments, one of which shares its name with a wine region three hundred kilometres to the north. Name the three departments.", "sa": 1, "accept": ["rhone loire and ardeche", "rhone loire ardeche", "rhone ardeche and loire", "rhone ardeche loire", "loire rhone and ardeche", "loire rhone ardeche", "loire ardeche and rhone", "loire ardeche rhone", "ardeche rhone and loire", "ardeche rhone loire", "ardeche loire and rhone", "ardeche loire rhone", "rhone loire and ardeche departments", "rhone loire ardeche departments", "departments of rhone loire and ardeche", "departments of rhone loire ardeche", "departments of rhone ardeche and loire", "departements of rhone loire and ardeche"], "ans": "Rhone, Loire and Ardeche", "ex": 1, "exp": "The town of Condrieu is in the Rhone, five of the seven communes are in the Loire, and Limony sits across in the Ardeche. The Loire here is the department named for the river's upper course through the Massif Central and has nothing to do with the Loire Valley's wines, and Chateau-Grillet, the enclave inside the Condrieu boundary, lies in it too."},
{"id": "c-d4cch3fl", "cat": "Rhône", "q": "A dessert wine turns up from the northern valley, made from bunches dried indoors on racks for weeks before a very slow pressing. Only one appellation there may produce it. Which?", "opts": ["Crozes-Hermitage", "Saint-Joseph", "Hermitage", "Cornas"], "a": 2, "exp": "The straw wine is made from Marsanne and Roussanne raisined on mats or in ventilated lofts, then pressed through the winter, and the ferment can run for a year. Almost none of it leaves the region, but the Hermitage decree provides for it and no other decree in the valley does."},
{"id": "c-bko8esex", "cat": "Rhône", "q": "Almost all the granite of the northern valley lies on the right bank against the edge of the Massif Central, yet the hill behind Tain and the slopes running north from it stand on the left bank and are cut from the same rock. How did that rock get there?", "opts": ["It is a glacial erratic carried down and dropped by ice off the Alps", "It is an uplifted spur of the Alps with the same mineralogy", "It is a volcanic cone thrown up long after the Massif had formed", "The river shifted west and left a block of the Massif on its east bank"], "a": 3, "exp": "The Rhone once ran east of the hill and later cut a new course to the west of it, marooning a granitic spur of the Massif Central on the left bank. That is also why the hill faces due south while its neighbours face east, and why its fruit ripens so much more completely than theirs. The same stranded block carries on north behind Gervans and Serves, which is why the northern half of Crozes-Hermitage sits on granite while its southern half, out on the flat at Les Chassis, sits on glacial gravel."},
{"id": "c-uv3bz9fl", "cat": "Rhône", "q": "At the very top of the hill above Tain, beside the chapel, lies a climat named for the solitary who is said to have lived up there. Give the name of that parcel.", "sa": 1, "accept": ["l hermite", "lhermite", "hermite", "l ermite", "lermite", "ermite", "the l hermite climat"], "ans": "L'Hermite", "exp": "The hill's name and the parcel's name come from the same hermit. L'Hermite is the highest of the climats, on thin granite under a cap of windblown silt, and its wine is finer-boned than the wine off the bare granite lower down the western end. It is one of the parcel names most often printed under the appellation."},
{"id": "c-pcvfhhyt", "cat": "Rhône", "q": "A white from the hill above Tain reaches the table with the appellation printed a letter shorter than the guest expects, and the importer insists the label is perfectly legal. What is that permitted spelling?", "sa": 1, "accept": ["ermitage", "ermitage aoc", "aoc ermitage", "the spelling ermitage", "spelled ermitage", "the ermitage spelling"], "ans": "Ermitage", "ex": 1, "exp": "The decree allows Hermitage and Ermitage alike, and Crozes-Hermitage may equally appear as Crozes-Ermitage. The older form dropped the initial letter and several estates have kept it. It is a spelling and nothing else, so it says nothing about the parcel, the style or the standing of the wine."},
{"id": "c-6hcxwcag", "cat": "Rhône", "q": "Created in 1956 around a handful of villages, Saint-Joseph was enlarged in 1969 until it ran some fifty kilometres and took in a great deal of flat ground. What has the appellation been doing about that ever since?", "opts": ["Splitting into a northern and a southern appellation under separate names", "Reviewing the delimitation and pushing the vineyard back onto the slopes", "Raising the permitted yield so the flat parcels can pay their way", "Adding a Villages tier for the granite core"], "a": 1, "exp": "The 1969 enlargement was made when planting anywhere at all was encouraged, and it left the name attached to alluvial flats that never ripen Syrah properly. The revision runs parcel by parcel and takes decades, because a grower whose vines fall outside must either uproot them or sell the fruit under a lesser name."},
{"id": "c-spqe2gqw", "cat": "Rhône", "q": "Saint-Peray's vineyard runs up to a crag crowned by a ruined fortress, and the rock of that crag sets the appellation apart from every slope upriver. What rock is it?", "opts": ["Basalt", "Limestone", "Gneiss", "Alluvial gravel"], "a": 1, "exp": "Saint-Peray sits on granite along its northern edge and on limestone and clay beneath the crag of Crussol, which is why its whites carry a chalkier tension than the granite-grown whites further up the valley. Cornas, its immediate neighbour to the north, is the mirror image: granite throughout, one black grape, red wine and nothing else."},
{"id": "c-65np7m74", "cat": "Rhône", "q": "One commune behind the hill of Tain is dug for a white clay that lines the bread ovens and pottery kilns of the region, and its vines sit on the same pale ground. Name the commune.", "sa": 1, "accept": ["larnage", "the commune of larnage", "larnage behind tain"], "ans": "Larnage", "exp": "The white clay at Larnage is a kaolin weathered out of the granite, and growers call the soil terre blanche. It holds water where granite sand does not, so the whites off it are broader and the reds rounder than the wine off bare rock a few kilometres away. The commune carries Hermitage and Crozes-Hermitage vines alike."},
{"id": "c-vkobscg8", "cat": "Rhône", "q": "Syrah from young vines and Viognier grown outside every cru boundary in the northern valley go out under a geographical indication covering the hills either side of the river. Name it.", "sa": 1, "accept": ["collines rhodaniennes", "igp collines rhodaniennes", "the collines rhodaniennes igp", "vin de pays des collines rhodaniennes"], "ans": "Collines Rhodaniennes", "exp": "It is the northern valley's safety net: a grower whose parcel falls outside Saint-Joseph or Cote-Rotie, or whose vines are still too young for the cru, sells the wine under it rather than losing the crop altogether. A good deal of serious northern Syrah appears under the name, so it is worth knowing rather than dismissing as a lesser tier. It is a zone indication and not a regional one: the regional IGP over the same ground is Comtes Rhodaniens, which reaches out to Savoie and the Bugey as well."},
{"id": "c-shn9pl1h", "cat": "Rhône", "q": "A tank of Viognier is fermented on its own at Ampuis and blended into the finished Syrah shortly before bottling, at well under the permitted share. What is the wine now?", "opts": ["Cote-Rotie, provided both parcels lie inside the delimited area and share a vintage", "Not Cote-Rotie: the white must ferment with the black, not be blended in later", "Cote-Rotie, since the Viognier is comfortably under the ceiling", "A rose in the eyes of the law, since blending a white wine into a red makes one"], "a": 1, "exp": "The northern appellations that admit white grapes require them in the vat with the black, and the permission is for a co-ferment rather than for an assemblage. The two are genuinely different wines: white skins carried through the red fermentation change what comes out of it, which is why the rule is written that way rather than as a simple percentage."},
{"id": "c-y6o3i2cq", "cat": "Rhône", "q": "In the northern crus a white grape entering a red is capped at a stated share of the vat. What is the equivalent rule at Chateauneuf-du-Pape?", "opts": ["They are allowed only where the parcel is planted with both colours mixed together", "None: the white varieties sit on the same permitted list as the black", "White grapes are forbidden in the red altogether", "They are capped at five percent of the vat"], "a": 1, "exp": "The decree lists the permitted varieties without separating them by colour or fixing any proportion between them, so a red may legally carry a good deal of Clairette, Bourboulenc or white Grenache. A few estates use a little for lift and most use none, but nothing in the rules obliges them either way."},
{"id": "c-4jlt7xxg", "cat": "Rhône", "q": "A red vinified with a proportion of white skins in the vat comes out deeper in colour than the same fruit without them, not paler. Name the effect responsible.", "sa": 1, "accept": ["co pigmentation", "copigmentation", "colour co pigmentation", "colour copigmentation", "color co pigmentation", "color copigmentation", "co pigmentation of anthocyanins", "copigmentation of anthocyanins", "anthocyanin co pigmentation", "anthocyanin copigmentation", "the co pigmentation effect", "the copigmentation effect"], "ans": "Co-pigmentation", "ex": 1, "exp": "Colourless compounds from the white grape stack with the anthocyanins and stabilise them, so a red co-fermented with a white grape is often deeper and steadier in colour than the same fruit vinified on its own. The aromatic lift growers talk about is a separate effect, and a great deal easier to smell than to measure."},
{"id": "c-ojomknq7", "cat": "Rhône", "q": "One black grape planted in quantity right across the southern valley and the Languedoc is pointedly missing from the Chateauneuf-du-Pape list. Which?", "opts": ["Carignan", "Vaccarese", "Terret Noir", "Counoise"], "a": 0, "exp": "Carignan crops heavily and ripens late, and the growers' charter that became this appellation set out to exclude exactly that sort of vine. It is permitted in Cotes du Rhone and in most of the southern crus, but never here. Counoise, Vaccarese and Terret Noir are all on the list and all barely planted, which is a quite different problem."},
{"id": "c-rdavnsws", "cat": "Rhône", "q": "Bush-trained Grenache at Chateauneuf-du-Pape stands far further apart than a vine in Burgundy or Bordeaux, and the appellation's minimum density is correspondingly low. What forces the wide spacing?", "opts": ["Each vine needs a large volume of dry soil", "The galets must be turned by machine between the rows", "Close planting would stop the mistral drying the canopy", "A gobelet vine cannot be pruned in narrow rows"], "a": 0, "exp": "Water rather than sunlight is the limiting resource on a stony southern plateau, and vines planted close together would leave every one of them short. Irrigation is not flatly banned here, whatever is often said: the decree allows it to be authorised, but an irrigated parcel has its permitted crop cut from 6,000 to 4,500 kilograms per hectare, so growers plant for drought rather than water their way out of it. The decree writes the density floor twice over. A vine in the square planting that gobelet vineyards use may occupy no more than four square metres, which comes out at 2,500 vines per hectare; a parcel planted in rows is held to 3,000 vines per hectare instead. Both sit far under the nine thousand a Cote d'Or village vineyard must carry, and neither rule sets a ceiling: a grower may plant as tightly as they can farm, and on the lighter soils some do."},
{"id": "c-hzpln2p5", "cat": "Rhône", "q": "Every Chateauneuf-du-Pape grower must set aside a portion of the crop, which may not be made into appellation wine at all. Under the decree in force, what is the minimum that portion must reach?", "sa": 1, "accept": ["two percent", "2 percent", "2%", "two per cent", "2 per cent", "two percent of the crop", "2% of the crop", "2 percent of the crop", "2 per cent of the crop", "two per cent of the crop", "two percent of the harvest", "2% of the harvest", "2 percent of the harvest", "2 per cent of the harvest", "two per cent of the harvest", "at least two percent", "at least 2 percent", "at least 2%", "at least two per cent", "at least 2 per cent", "a minimum of two percent", "a minimum of 2 percent", "a minimum of 2%", "minimum 2%", "minimum 2 percent", "minimum two percent", "2% minimum", "2 percent minimum", "two percent minimum", "2% of the volume claimed", "2 percent of the volume claimed"], "ans": "Two percent", "ex": 1, "exp": "The sort is compulsory and may be done in the vineyard or at the cellar, and what it takes out is either destroyed or vinified as the rape, a wine the decree bars from carrying any geographical indication at all. The minimum rape stands at two percent of the volume claimed, in every vintage, so even a faultless year gives up its poorest fruit. Five percent is the figure most study guides still print, and it is not invented: the older rules set the bar there and the number was cut when the cahier des charges was rewritten. Carry the current figure with its date attached, and set it beside the appellation's low yields and its ban on the harvesting machine to see why the harvest regime here is among the most demanding in France."},
{"id": "c-wl49i0tb", "cat": "Rhône", "q": "The boundary of Chateauneuf-du-Pape was drawn in 1923 by a test taken from the wild plants on the ground: land qualified only where two aromatic shrubs of the garrigue grew of their own accord. Name them.", "sa": 1, "accept": ["lavender and thyme", "thyme and lavender", "lavender thyme", "thyme lavender", "wild lavender and thyme", "wild thyme and lavender", "wild lavender and wild thyme", "wild thyme and wild lavender", "wild lavender wild thyme", "wild thyme wild lavender", "lavender and wild thyme", "wild lavender thyme", "wild thyme lavender"], "ans": "Lavender and thyme", "ex": 1, "exp": "The reasoning was agronomic rather than romantic. Only ground poor enough, dry enough and hot enough for those two shrubs would ripen a vine properly, so the plants did the surveying. The same charter fixed a variety list, a minimum ripeness and a compulsory sort, and a decade later the national appellation system was built on that architecture."},
{"id": "c-gmosn5n6", "cat": "Rhône", "q": "A vine on the stone-covered plateau at Chateauneuf carries its crop through a rainless summer without wilting. What lies under the stones that makes that possible?", "opts": ["A deep bed of red clay that holds water in reserve", "A layer of chalk drawing moisture up to the surface", "Fissured granite storing rain in its cracks", "A water table fed year round by the river"], "a": 0, "exp": "The stones are the part you can see, and they do cut evaporation and hold the day's heat, but the reservoir is the red clay underneath them, holding water within reach of the roots. It is why a vine there can finish a summer that would stop a vine on light ground, and much of why the plateau gives the fullest wines of the appellation."},
{"id": "c-f5kuqta6", "cat": "Rhône", "q": "In the lighter sectors of Chateauneuf the topsoil sits on a soft yellow Miocene sandstone that roots drive straight into for water, and growers have a local word for it. Give the word.", "sa": 1, "accept": ["safre", "safres", "the safre subsoil", "safre sandstone", "the safre sand", "safre molasse"], "ans": "Safre", "ex": 1, "exp": "Safre is a weakly cemented marine sand, soft enough to break with a spade, and it is why parcels that look droughted are nothing of the kind. Wine grown over it is paler, more perfumed and finer in tannin than wine off the stone plateau, which is a large part of why single-parcel bottlings from those sectors have such a following."},
{"id": "c-ysa5f5b8", "cat": "Rhône", "q": "Alpine quartzite outcrops nowhere near Chateauneuf-du-Pape, yet the plateau is carpeted in it, standing well above the modern channel and well back from it. Which river's older and higher course laid the stones down there?", "sa": 1, "accept": ["rhone", "river rhone", "rhone river", "the ancient rhone", "the ancestral rhone", "the old rhone", "the ancient course of the rhone", "the old course of the rhone"], "ans": "The Rhone", "ex": 1, "exp": "The Rhone drains the Alps, and through the Quaternary glaciations it ran swollen with meltwater and loaded with rock torn off the mountains. It dropped that load, then cut down and swung west, leaving a staircase of terraces with the oldest and highest of them standing as the stone plateau and the younger gravels lying below it. Quartzite is far harder than any rock hereabouts, which is why the pebbles survived being rolled that distance and why they are still lying on the surface rather than weathered into the soil. The Durance is the usual wrong guess: its fossil delta is the Crau, away to the south, and it does not reach the Rhone until below Avignon."},
{"id": "c-arbflrot", "cat": "Rhône", "q": "A Cotes du Rhone Villages label reads Plan de Dieu where a student expects the name of a village. What is Plan de Dieu?", "opts": ["A single commune that renamed itself after its own plateau", "A brand registered by growers who share a cooperative cellar", "A delimited area covering several communes rather than one village", "A tier ranking above the crus"], "a": 2, "exp": "Most of the named Villages are communes, but a few of the names are geographical units taking in more than one: Plan de Dieu is a stony plain shared by four villages, and Massif d'Uchaux and Signargues work the same way. What the label names is a delimited patch of ground, not a town hall, which is the rule worth carrying away."},
{"id": "c-uhzfu3ip", "cat": "Rhône", "q": "Rasteau's cru covers dry red alone. Name the neighbouring village whose own promotion brought white wine as well as red under the cru name.", "sa": 1, "accept": ["cairanne", "cairanne aoc", "aoc cairanne", "the cairanne appellation", "cairanne cru", "the cru of cairanne", "the village of cairanne"], "ans": "Cairanne", "ex": 1, "exp": "Cairanne had been among the strongest of the named Cotes du Rhone Villages for decades before it was raised in 2016, and its rules cover red and white but no rose. Rasteau's cru, granted six years earlier, is dry red only. Two neighbouring crus can therefore differ in what colours they are even allowed to make."},
{"id": "c-cobm6fpk", "cat": "Rhône", "q": "An appellation on the eastern edge of the valley abandoned the name it had carried since 1973, because that name had come to mean a nuclear site rather than a wine. Give the name it took instead.", "sa": 1, "accept": ["grignan les adhemar", "aoc grignan les adhemar", "grignan les adhemar aoc", "the grignan les adhemar appellation"], "ans": "Grignan-les-Adhemar", "ex": 1, "exp": "Coteaux du Tricastin shared its name with a power station a few kilometres away, and after a leak made the news the growers went to the authorities for another one. Grignan and the Adhemar family belong to the same corner of the Drome. The wine, mostly Grenache and Syrah, did not change in the slightest."},
{"id": "c-v29rqtux", "cat": "Rhône", "q": "The step up from Cotes du Rhone Villages to a cru of its own was taken for the first time in 1971. Which appellation made it?", "sa": 1, "accept": ["gigondas", "gigondas aoc", "aoc gigondas", "the gigondas appellation", "gigondas cru", "the cru of gigondas"], "ans": "Gigondas", "ex": 1, "exp": "It set the pattern every later promotion has followed: a village that has long added its own name to the Villages tier, farming to lower yields inside a tighter boundary than its neighbours, applies to leave the tier altogether. Vacqueyras followed in 1990 and the rest have come along in ones and twos since."},
{"id": "c-8i9ii382", "cat": "Rhône", "q": "Fermentation in a southern Rhone vin doux naturel is arrested by dosing the must with neutral grape spirit of at least ninety-six percent. What proportion of the volume may that spirit make up?", "opts": ["Between twenty and twenty-five percent", "Enough to reach twenty percent alcohol", "Between five and ten percent of the must", "Between one and two percent"], "a": 2, "exp": "The spirit is close to neutral, so it lifts the alcohol without contributing flavour, and the narrow window holds the finished wine in the fifteen to eighteen percent band the category occupies. When it goes in is the decision that sets the style: earlier leaves more grape sugar and less fermented alcohol, later the reverse."},
{"id": "c-tgxve4hh", "cat": "Rhône", "q": "A Rasteau fortified sweet wine bottled early to keep its red fruit and its colour carries one word on the label; a wine given long contact with air until it turns tawny carries another. Give the word for the early-bottled style.", "sa": 1, "accept": ["grenat", "rasteau grenat", "grenat rasteau", "the grenat style", "the grenat mention"], "ans": "Grenat", "ex": 1, "exp": "Grenat is red Grenache muted young and kept away from air, so it stays purple and tastes of kirsch and crushed berry. The oxidative styles take Tuile if the wine was red and Ambre if it was white, and one held for many years in deliberate warmth may add Rancio to either. Note that the fortified wine is not made under the dry red cru of the same village but under a separate and much older appellation, Rasteau Vin Doux Naturel, in force since 1944, so a cru drawn for dry red alone took nothing away from it."},
{"id": "c-slm9zpq8", "cat": "Rhône", "q": "Chateauneuf-du-Pape, Gigondas and Vacqueyras all lie in the Vaucluse. Tavel and Lirac sit across the water in another department, which they share with Costieres de Nimes. Name it.", "sa": 1, "accept": ["gard", "gard department", "departement gard", "the gard in languedoc", "department of gard", "departement of gard"], "ans": "The Gard", "ex": 1, "exp": "The river is the departmental boundary here, so the right bank belongs to the Gard and the administrative map of the Languedoc while the left bank is Vaucluse and Provence. It is part of why the right-bank appellations have always sat slightly apart from the rest of the southern crus."},
{"id": "c-n3py71wi", "cat": "Rhône", "q": "Long before any appellation existed, the words Cote du Rhone named an administrative district whose casks were branded with its initials before shipping. Which bank of the river was that district on?", "opts": ["The left bank, around Chateauneuf-du-Pape and Orange", "The left bank, around Avignon and Sorgues", "Both banks, from Vienne down as far as Valence", "The right bank, around Roquemaure"], "a": 3, "exp": "Roquemaure was the loading port for the district, and the letters burned into a cask head served as a mark of origin and a customs stamp at once. The appellation created in the twentieth century took the phrase and stretched it across the water, which is how a name that once meant one stretch of one bank came to cover the whole valley."},
{"id": "c-urz3ails", "cat": "Rhône", "q": "Beaujolais is not the only French wine released on the third Thursday of November. The Rhone sends out a young wine of its own that day, under its regional appellation. Name it.", "sa": 1, "accept": ["cotes du rhone primeur", "cote du rhone primeur", "cotes du rhone nouveau", "cotes du rhone primeur nouveau", "cotes du rhone primeur or nouveau", "primeur cotes du rhone", "cotes du rhone primeur aoc", "aoc cotes du rhone primeur", "cotes du rhone nouveau primeur", "cotes du rhone nouveau or primeur"], "ans": "Cotes du Rhone Primeur", "ex": 1, "exp": "It is red or rose, made for drinking at once, and a grower must declare the intention at harvest rather than decide later that a tank will be sold that way. The trade in it is small beside Beaujolais Nouveau, but the release date is the same and the label must carry Primeur or Nouveau."},
{"id": "c-pdx36i0e", "cat": "Sake", "q": "Of the eight premium designations, one has carried no minimum polishing requirement at all since a 2004 rule change. Which is it?", "opts": ["Honjozo", "Ginjo", "Junmai", "Junmai ginjo"], "a": 2, "exp": "Until the 2004 revision junmai carried the same 70 percent bar as honjozo; the revision dropped the polishing bar alone, so the rule now asks that the rice be graded, that the koji floor be met, and that nothing but rice, water and koji go in. The change freed brewers to work deliberately low-polish styles, so a junmai with no milling figure on its label is not hiding anything."},
{"id": "c-9dromuwp", "cat": "Sake", "q": "Top daiginjo brewers dose the mash with a little distilled alcohol even when economy is no object. What are they buying with it?", "opts": ["Aroma carried out of the lees and a lighter, drier finish", "Extra volume, since the addition can triple the yield", "Longer shelf life, with no pasteurisation needed", "Sweetness, since the spirit arrests the ferment early"], "a": 0, "exp": "Ginjo esters dissolve more readily in alcohol than in water, so a dose added just before pressing pulls aroma out of the lees that would otherwise be discarded with them, and it dries and lightens the finish. At the premium designations the quantity is tightly capped, which is what separates aruten brewing from the volume-stretching triple sake of the postwar shortage years."},
{"id": "c-sg1nwgsj", "cat": "Sake", "q": "Milling is not the only bar a premium designation must clear: a floor is also set on how much of the total rice must go through the mould room as koji rice. What is that floor?", "sa": 1, "accept": ["fifteen percent", "15 percent", "15%", "15 per cent", "fifteen per cent", "at least 15 percent", "at least fifteen percent", "15 percent or more", "fifteen percent or more", "15", "fifteen", "a minimum of 15 percent", "15 percent minimum", "15 percent koji rice", "fifteen percent koji rice", "15% or more", "15 percent of the rice", "at least 15%", "minimum 15 percent", "15% minimum", "15 percent of total rice"], "ans": "Fifteen percent", "ex": 1, "exp": "The floor stops a brewery skimping on the most laborious stage: koji rice is worked grain by grain in the warm room while the rest of the charge is simply steamed. Fall below fifteen percent and the sake drops out of the premium system entirely, whatever its polish."},
{"id": "c-q8xkptfg", "cat": "Sake", "q": "Junmai, honjozo, ginjo and their compound grades sit together under one collective legal term for premium sake. Give that term.", "sa": 1, "accept": ["tokutei meisho shu", "tokutei meishoshu", "tokutei meisho", "tokutei meisho sake", "special designation sake", "special designation"], "ans": "Tokutei meisho-shu", "exp": "The tokutei meisho system took its present shape in 1990 and holds eight names: junmai, junmai ginjo, junmai daiginjo and tokubetsu junmai on the pure-rice side, honjozo, ginjo, daiginjo and tokubetsu honjozo on the other. Everything outside the eight is futsu-shu, which answers to far looser rules and fills most of the market."},
{"id": "c-u6wcpj71", "cat": "Sake", "q": "Steamed rice turns sweet in the koji room though no sugar has been added. Which enzyme, secreted by the mould as it grows into the grain, is doing the work?", "opts": ["Invertase", "Lipase", "Protease", "Amylase"], "a": 3, "exp": "The mould, Aspergillus oryzae, ferments nothing itself; it secretes amylases as it grows through the grain, and the yeast drinks the glucose those enzymes release. Its proteases work alongside, cutting rice protein into the amino acids behind sake's savoury depth, but the road to alcohol starts at amylase."},
{"id": "c-kb0h7lci", "cat": "Sake", "q": "Between the two traditional starter methods, the only real difference is a step in which workers grind steamed rice to a paste with long poles. Which method keeps that labour, and which gave it up?", "opts": ["Kimoto keeps the pole work; yamahai did away with it", "Yamahai keeps it; kimoto is the one that did away with it", "Neither does; both now acidify with a bottled addition", "Both keep it; only sokujo abandoned the poles"], "a": 0, "exp": "Yamahai is short for yamaoroshi haishi, the abolition of the pole work, after brewers showed early in the twentieth century that the koji's own enzymes dissolve the rice without any mashing. Everything else the two methods share, including the slow wild acidification that leaves their sake broader, gamier and higher in acid than the modern norm."},
{"id": "c-bket7pnx", "cat": "Sake", "q": "Scaled up from the starter with further additions of rice, koji and water, the brew then ferments for weeks in its biggest tank. What is that fermenting mash called?", "sa": 1, "accept": ["moromi", "moromi mash"], "ans": "Moromi", "exp": "The moromi runs three to five weeks at low temperature, saccharification and fermentation proceeding together in the one tank, which is how the strength climbs so high without any addition. Pressing it is what legally turns it into sake, and the solids the press holds back are the kasu."},
{"id": "c-ttiod5wb", "cat": "Sake", "q": "The modern starter method takes its acidity from a bottle; kimoto and yamahai take theirs from organisms that drift in from the brewery's air and timbers. Name those organisms.", "sa": 1, "accept": ["wild lactic acid bacteria", "lactic acid bacteria", "ambient lactic acid bacteria", "airborne lactic acid bacteria", "natural lactic acid bacteria", "naturally occurring lactic acid bacteria", "wild lactic bacteria", "lactic bacteria", "lactobacillus", "lab", "wild lactobacillus", "airborne lactic bacteria", "ambient lactic bacteria"], "ans": "Wild lactic acid bacteria", "ex": 1, "exp": "A kimoto or yamahai starter spends its first weeks as an open ecology, nitrate-reducing bacteria first and then the lactic acid bacteria whose acid clears the field for the sake yeast. That month of succession is what sokujo's bottled lactic acid buys back, and losing it is why the quick starter reads cleaner and slimmer."},
{"id": "c-aqaklfwr", "cat": "Sake", "q": "Stored all summer unpasteurised, then given its single heat treatment only as it goes into the bottle: which label term fits that sake?", "opts": ["Namazake", "Genshu", "Namazume", "Namachozo"], "a": 3, "exp": "Namachozo skips the usual first pasteurisation and keeps the one at shipping; namazume is its mirror, heated once going into storage and bottled raw, and hiyaoroshi, the autumn release, is namazume by another calendar. Only namazake skips both treatments, which is why it alone demands an unbroken cold chain from brewery to glass."},
{"id": "c-ykoz758w", "cat": "Sake", "q": "Fresh from a few days in a newly coopered cask, a festival sake pours with a distinct resinous scent. Which wood put it there?", "sa": 1, "accept": ["japanese cedar", "cedar", "sugi", "cryptomeria", "yoshino cedar", "japanese cedar sugi", "cedar sugi", "yoshino sugi"], "ans": "Japanese cedar (sugi)", "exp": "Taruzake takes its name from the taru, a cask of Japanese cedar classically cut in Yoshino in Nara, and days rather than weeks is the point, because the fresh wood gives up its resin fast. New Year and shrine celebrations are the style's home ground, where the cask lid is broken open with mallets at kagami biraki."},
{"id": "c-5eybknsb", "cat": "Sake", "q": "Years in tank turn a sake amber and push its flavour toward soy, caramel and roasted nuts. Which reaction, between residual sugars and amino acids, is doing that?", "sa": 1, "accept": ["maillard reaction", "maillard", "maillard browning", "amino carbonyl reaction", "amino carbonyl"], "ans": "The Maillard reaction", "exp": "Koshu carries both reactants in unusual quantity, glucose the ferment left behind and amino acids from the rice, so it browns at cellar temperature with no oxygen involved at all. That is what separates its ambering from the oxidative browning of an old wine, and why even a sealed, topped-up tank of it darkens anyway."},
{"id": "c-fwgn9rq8", "cat": "Sake", "q": "Two bottles both read plus three on the sake meter value, yet one tastes markedly drier at the table. What most likely explains the difference?", "opts": ["Higher acidity in the drier one, unseen by the meter", "A misprint, since equal readings must taste identical", "Added alcohol in the drier one, which the meter reads as sugar", "Warmer storage of the sweeter bottle, building extra sugar"], "a": 0, "exp": "The meter is a hydrometer, so residual sugar and density are all it can report, and acid never moves it. Acidity is what turns a given sugar level crisp or cloying on the palate, which is why the trade reads the two figures together and why quoting the meter value alone is guessing."},
{"id": "c-2ln0b4lp", "cat": "Sake", "q": "A guest wants the driest sake on the list, and the menu prints every bottle's meter value. Toward which end of the scale should the recommendation move?", "sa": 1, "accept": ["positive end", "positive", "plus", "plus end", "positive side", "plus side", "positive numbers", "toward positive", "toward positive end", "toward plus", "toward plus end", "higher smv", "positive smv", "plus direction", "positive direction", "higher", "higher end", "high end", "higher numbers", "toward higher numbers", "up the scale", "into positive numbers", "plus territory", "positive territory", "higher sake meter value"], "ans": "The positive end", "ex": 1, "exp": "Zero is anchored at the density of water: sugar-rich sake is denser and buoys the float higher, putting the waterline at the negative figures, while drier sake lets the float sink and the reading climbs into positive ones. Most premium sake sits between about minus two and plus ten, so a plus sign after the number is the quickest dryness signal a list can carry."},
{"id": "c-6c2t9n4j", "cat": "Sake", "q": "Domestic labels print the sake meter value under its Japanese name. Give that name.", "sa": 1, "accept": ["nihonshudo", "nihonshu do", "nihon shudo", "nihon shu do"], "ans": "Nihonshudo", "exp": "Nihonshudo reads literally as Japan sake degree, and export labels translate it as the sake meter value or SMV. Domestic bottles rarely translate it, so recognising the figure beside its plus or minus sign is one of the small literacies a floor sommelier actually uses."},
{"id": "c-13956csf", "cat": "Sake", "q": "Tanrei karakuchi, the light, clean, bone-dry ideal of Niigata brewing, leans on one rice variety that resists dissolving into the mash. Which variety?", "opts": ["Yamada Nishiki", "Gohyakumangoku", "Koshihikari", "Miyama Nishiki"], "a": 1, "exp": "Bred in and for Niigata, Gohyakumangoku has a hard grain that melts reluctantly, so the ferment stays tidy and the sake comes out light and transparent, exactly the local ideal. Yamada Nishiki dissolves generously and builds broader, rounder sake, prized elsewhere and beside the point in tanrei country, while Miyama Nishiki plays a similar workhorse role in cold Nagano."},
{"id": "c-lrqwb7et", "cat": "Sake", "q": "Discovered in Okayama in the mid nineteenth century and never crossbred since, the oldest brewing rice still in commercial use gives deep, earthy, herbal sake. Name it.", "sa": 1, "accept": ["omachi", "omachi rice"], "ans": "Omachi", "exp": "About two-thirds of modern brewing rices, Yamada Nishiki among them, carry Omachi somewhere in their pedigree, but Omachi itself is a pure selection from a wayside find, never crossed with anything. It grows tall, ripens late and lodges in wind, and it repays the trouble with a broad, wild, savoury style that has a devoted following."},
{"id": "c-wmufupfe", "cat": "Sake", "q": "Hired for the season, one figure commands the brewery crew and answers for every tank while the owner keeps to the business side. Give that figure's title.", "sa": 1, "accept": ["toji", "master brewer", "head brewer", "toji master brewer", "brewmaster", "chief brewer"], "ans": "Toji", "exp": "The toji system was seasonal labour: rice farmers travelled to the breweries after their own harvest, worked the winter under a master trained and placed by a regional guild, Nanbu and Echigo the largest, and went home in spring. Year-round hiring and owner-brewers are eroding the arrangement, but the title stays with whoever commands the brewhouse."},
{"id": "c-n3stz04t", "cat": "Sake", "q": "Somewhere on the list is a bottle that gentle warming will flatter rather than flatten. Which is the best candidate?", "opts": ["A junmai daiginjo prized for its fragile aroma", "A lightly sparkling nigori finished sweet", "A yamahai junmai, savoury and high in acidity", "A namazake kept chilled since pressing"], "a": 2, "exp": "Warmth magnifies body and umami, and a yamahai's high acidity keeps the warmed sake in balance, which is exactly the yamahai trade; the same degrees strip the esters a daiginjo was fermented cold to keep. A sake that improves with heat is called kan-agari; namazake and anything carbonated are the reliable losers, one for stability and the other for obvious reasons."},
{"id": "c-wen5h102", "cat": "Sake", "q": "In the United States a restaurant lists sake by the glass. What is the drink's standing under federal law?", "opts": ["Taxed and labelled as a beer in every respect", "Taxed as a beer but labelled under the rules for wine", "Treated as a spirit because of its strength", "Taxed and labelled as a wine, exactly like a grape wine"], "a": 1, "exp": "The Internal Revenue Code writes sake into its definition of beer, since it is brewed from a grain, so it pays brewery excise; the labelling side runs under the Federal Alcohol Administration Act, which treats sake of seven percent or more like a wine. The split is why sake sits on wine lists and in wine competitions while being taxed like an ale."},
{"id": "c-d0p0j8f4", "cat": "Sake", "q": "Japan's Liquor Tax Act refuses the name seishu to any rice brew at or above a certain strength. Where does that ceiling sit?", "sa": 1, "accept": ["twenty two percent", "22 percent", "22%", "22 per cent", "twenty two per cent", "under 22 percent", "below 22 percent", "less than 22 percent", "under twenty two percent", "below twenty two percent", "less than twenty two percent", "22", "twenty two", "22 percent abv", "22 abv", "22 percent alcohol", "22 percent alcohol by volume", "22% abv", "22 degrees", "twenty two degrees", "less than 22%", "under 22%", "below 22%"], "ans": "Twenty-two percent", "ex": 1, "exp": "The same definition demands that the fermenting mash be strained, which is why doburoku, the unstrained farm brew, is legally not sake at all, and why even the murkiest nigori has passed through at least a coarse mesh. The ceiling is also the outer legal wall for undiluted genshu: a rice brew at twenty-two or above changes legal identity, though in practice the yeast gives out first and most genshu land between seventeen and twenty percent."},
{"id": "c-81mla21g", "cat": "Service & Hospitality", "q": "Filled to 50 ml for assessment and holding 215 ml to the brim, which standardised glass does competition tasting specify?", "sa": 1, "accept": ["iso tasting glass", "~iso", "iso glass", "inao glass", "iso standard glass"], "ans": "The ISO tasting glass", "exp": "The ISO glass is a controlled variable rather than a fine drinking vessel. Everyone at the bench is then smelling the same volume under the same headspace."},
{"id": "c-gs7bslwi", "cat": "Service & Hospitality", "q": "A wide, deeply bowled glass is reached for when Pinot Noir is poured. What is that shape doing?", "opts": ["Slowing oxidation once the wine has been poured", "Presenting a large surface of wine so aromatics gather", "Holding the wine several degrees cooler for longer", "Allowing a larger measure without appearing generous"], "a": 1, "exp": "Aromatically subtle, high-acid reds gain from surface area and headspace, and the deep bowl holds what rises off the wine instead of losing it. The narrower Bordeaux shape suits wines whose aromas need no help arriving."},
{"id": "c-jm8o9ino", "cat": "Service & Hospitality", "q": "Handling a poured glass by the bowl rather than the stem creates which pair of problems?", "opts": ["The glass is weakened at its thinnest point and may break", "The wine reads as more tannic and less sweet", "Dissolved gas escapes faster from the surface", "The wine warms and fingermarks obscure the appearance"], "a": 3, "exp": "Both matter at a tasting bench: a white climbs several degrees in a warm hand, and a smeared bowl makes clarity impossible to judge honestly."},
{"id": "c-rbec5kxw", "cat": "Service & Hospitality", "q": "A glass leaves the machine carrying a faint chalky bloom. Which two-step remedy is standard before it goes to a table?", "sa": 1, "accept": ["steam and polish", "steam it and polish", "steaming and polishing", "hold it over steam then polish", "steam then polish with a cloth"], "ans": "Steam and polish with a lint-free cloth", "exp": "Detergent bloom and water spots survive a machine cycle. Steam softens the film so linen lifts it away instead of smearing it around the bowl."},
{"id": "c-nk7u9frs", "cat": "Service & Hospitality", "q": "Serious sparkling lists now pour into a tulip or a white wine glass rather than a narrow flute, chasing which quality the flute suppresses?", "sa": 1, "accept": ["aroma", "aromas", "bouquet", "aromatics", "nose", "smell", "aroma and bouquet", "the smell of the wine"], "ans": "Aroma", "exp": "A flute shows the bead and hides everything else. Vintage Champagne is a wine before it is a spectacle, and it needs room to be smelled."},
{"id": "c-26l4bg5f", "cat": "Service & Hospitality", "q": "Which residue, invisible to a guest, will flatten the mousse of a sparkling wine within seconds of the pour?", "sa": 1, "accept": ["detergent left in the glass", "detergent", "detergent residue", "soap", "soap residue", "soap film", "washing up liquid", "traces of detergent"], "ans": "Detergent left in the glass", "exp": "Surfactants break bubble walls as they form, so a technically clean glass can kill a Champagne. It is the commonest reason a good sparkling wine looks lifeless."},
{"id": "c-wyzj7w6o", "cat": "Service & Hospitality", "q": "The label is turned toward one person at the table before the foil is cut. Why that person?", "opts": ["They are seated closest to the sommelier station", "They ordered the wine and can confirm it", "They are the eldest person among the guests", "They are expected to settle the whole bill"], "a": 1, "exp": "Presentation is the last cheap moment to catch a wrong vintage or a wrong producer, and the person who ordered is the only one at the table who knows what was chosen. Once the capsule is cut the bottle belongs to the restaurant."},
{"id": "c-904bfvmo", "cat": "Service & Hospitality", "q": "A table of ten empties the first bottle and a second of the same wine is fetched. What has to happen before it reaches anyone's glass?", "sa": 1, "accept": ["present and taste the new bottle", "presented and tasted", "taste the new bottle first", "check the new bottle first", "the host tastes the new bottle", "offer the host a fresh taste", "taste it before pouring", "pour a fresh taste for the host"], "ans": "The new bottle is presented and tasted before any is poured", "exp": "Every bottle carries its own risk, so the second is shown and sampled exactly as the first was. The taste goes into a clean glass, since a glass holding the dregs of bottle one will mask a fault in bottle two. Pouring first and checking afterwards spreads a spoiled wine across the whole table at once."},
{"id": "c-3qxu7ia4", "cat": "Service & Hospitality", "q": "From which side of a seated guest is a glass filled in classical restaurant service?", "sa": 1, "accept": ["right", "right side", "right hand side", "from the right", "on the right", "to the right", "right of the guest", "the guests right", "right hand"], "ans": "The right", "exp": "Beverages go to the right, where the glassware sits, and food to the left. Working the wrong side puts an arm across the guest."},
{"id": "c-0ek5yeyv", "cat": "Service & Hospitality", "q": "A guest tastes and says the wine is not to their liking, though nothing is wrong with it. What is the correct handling?", "opts": ["Explain that the wine is sound and ask them to persevere with it", "Replace it without argument and put both bottles on the bill", "Ask the rest of the table to decide whether it stays", "Take it away, offer an alternative, and absorb the cost"], "a": 3, "exp": "Soundness is the test for a fault, but a disliked bottle is a commercial question rather than a technical one. Most of an opened bottle can be recovered by the glass, which is why the wine costs the house far less than an argument at the table does."},
{"id": "c-wkrpmyn2", "cat": "Service & Hospitality", "q": "A firm young red and a fragile old one are poured across a single meal. Which goes into the glass first?", "sa": 1, "accept": ["young wine", "young", "young one", "young red", "young red wine", "younger wine", "younger one", "younger red", "young first", "young wine first", "young red first", "young one first", "young before old", "pour the young wine first", "the young wine goes first", "the young red goes first"], "ans": "The young wine", "ex": 1, "exp": "Order protects the more delicate bottle. A firm young red after an old one flattens it, while the reverse merely flatters the young wine."},
{"id": "c-h4f6pby3", "cat": "Service & Hospitality", "q": "Glasses are exchanged rather than reused when a table moves from a white to a red. What is that avoiding?", "opts": ["A licensing requirement covering glassware", "Residue of the first wine altering the second", "A glass too small to hold a full measure", "The second wine arriving at the wrong temperature"], "a": 1, "exp": "Even a teaspoon of an aromatic white shows in a Pinot Noir. Where a fresh glass is impossible, a splash of the new wine is used to rinse the old one out."},
{"id": "c-n52av6cq", "cat": "Service & Hospitality", "q": "Stations, tools and glassware are set in place before the first guest arrives. Which French term covers that preparation?", "sa": 1, "accept": ["mise en place", "~mise", "mis en place", "~miseenplace"], "ans": "Mise en place", "exp": "The phrase travels from the kitchen to the floor unchanged. A sommelier hunting for a decanter mid-service failed an hour before the doors opened."},
{"id": "c-8tcorn1w", "cat": "Service & Hospitality", "q": "Which corkscrew, carrying a foil blade and a two-step lever, is the tool actually carried in the pocket?", "sa": 1, "accept": ["sommelier knife", "sommeliers knife", "waiters friend", "waiter s friend", "wine key"], "ans": "Sommelier knife", "exp": "The second notch on the lever is what makes it work, letting a long cork come out in two controlled stages rather than one wrenching pull."},
{"id": "c-teq5hqs9", "cat": "Service & Hospitality", "q": "Cutting the capsule below the lower lip rather than above it prevents what?", "opts": ["Wine touching foil on its way into the glass", "The cork breaking apart inside the neck", "Sediment being stirred back into suspension", "The label tearing when the bottle is presented"], "a": 0, "exp": "Old lead capsules made this a health point and modern ones make it a question of taste and tidiness. The cut also looks deliberate rather than hacked."},
{"id": "c-od4bwv9p", "cat": "Service & Hospitality", "q": "The worm has entered off-centre and the cork is beginning to tear. What is the least damaging recovery?", "opts": ["Drive the worm all the way through the cork and pull hard", "Push the remains of the cork into the bottle and pour at once", "Ease off, re-angle the worm down the same channel, and lift slowly", "Warm the neck of the bottle in a hot cloth to loosen the cork"], "a": 2, "exp": "Speed is what destroys a cork. Going back down the channel already cut keeps the remaining cork whole instead of drilling a second hole through it, and the lift comes straight up rather than at an angle."},
{"id": "c-igzatule", "cat": "Service & Hospitality", "q": "A fifty-year-old cork crumbles at the first turn of the worm. Which two-pronged extractor exists for exactly this?", "sa": 1, "accept": ["ah so", "butlers friend", "butler s friend", "~two pronged puller", "~two prong puller", "~twin prong extractor", "two prong cork puller", "two pronged cork puller", "twin prong cork puller"], "ans": "The Ah-So, or butlers friend", "exp": "The blades slide down either side of the cork and grip it whole, which is the only chance with a cork a worm would simply pulverise."},
{"id": "c-jnic570s", "cat": "Service & Hospitality", "q": "The pour is finishing and a drop is about to run down the shoulder. Which movement of the bottle prevents it?", "sa": 1, "accept": ["a twist of the bottle as it is lifted", "~twist of the bottle", "twist the bottle", "twisting the bottle", "rotate the bottle", "rotating the bottle", "turn the bottle", "twist", "twist of the wrist", "turn of the wrist", "twist and lift"], "ans": "A twist of the bottle as it is lifted", "exp": "A small turn as the neck comes up carries the last drop back over the lip. A serviette in the other hand covers whatever the turn misses."},
{"id": "c-5frizssq", "cat": "Service & Hospitality", "q": "Warm from a delivery and opened straight away, a bottle pushes its own cork up the moment the cage comes off. What is the correct move?", "sa": 1, "accept": ["keep a hand on the cork and ease it out slowly", "keep a hand on the cork", "hold the cork and ease it out", "hold it down and ease it out slowly", "keep hold of the cork and ease it out", "ease it out slowly under the thumb", "keep pressure on the cork and let it out slowly", "hold the cork", "hold the cork down and ease it out slowly", "hold the cork down", "keep a hand on it and ease it out slowly", "keep your thumb on it and ease it out", "keep a thumb on the cork and ease it out"], "ans": "Keep a hand on the cork and ease it out slowly", "exp": "Pressure climbs steeply as a bottle warms, and a cork already on the move will not be re-seated. Take the weight of it, point the neck at a wall rather than at the room, and walk it out under the thumb until the gas sighs away. The bottle then goes back into ice before anything is poured, because a warm sparkling wine foams out of the glass as well."},
{"id": "c-vrjvha15", "cat": "Service & Hospitality", "q": "A thumb stays over the cork from the instant the cage is loosened. What is that guarding against?", "opts": ["A cork leaving under six atmospheres of pressure", "The bottle warming in the hand", "Wine foaming out over the lip of the bottle", "The wire scratching the label"], "a": 0, "exp": "A Champagne bottle sits at roughly six atmospheres, pressure comparable to a heavy vehicle tyre, and the cork gives no warning. Eye injuries from sparkling corks are reported every year."},
{"id": "c-3w3livlh", "cat": "Service & Hospitality", "q": "A loud report and a plume of foam mark a badly opened sparkling bottle. Which sound should the opening aim for?", "sa": 1, "accept": ["~sigh", "soft sigh", "quiet sigh", "~whisper", "gentle sigh"], "ans": "A soft sigh", "exp": "The bang is escaping gas that ought to have stayed dissolved in the wine. A controlled release leaves the mousse where the guest can drink it."},
{"id": "c-m7rv44bw", "cat": "Service & Hospitality", "q": "Filling a flute in two stages rather than one achieves what?", "opts": ["The wine is held closer to its serving temperature", "The wine picks up useful oxygen between the two pours", "The first foam subsides so a full measure fits in the glass", "Pressure in the bottle is reduced for the next pour"], "a": 2, "exp": "A single pour into a cold, narrow glass is almost all head and goes over the lip before the measure is in. A small pour, a pause, then the rest, and the glass ends correctly filled to about two thirds."},
{"id": "c-9z2o8ze9", "cat": "Service & Hospitality", "q": "Tilting the glass and pouring down its inner wall does what for a sparkling wine?", "sa": 1, "accept": ["preserves the mousse", "preserve the mousse", "mousse", "keeps the mousse", "preserves the bubbles", "keeps the bubbles", "keep the bubbles", "reduces foaming", "less foam"], "ans": "Preserves the mousse", "exp": "Bubbles break where wine strikes a flat surface hard. Down the side, more gas stays in solution and the wine keeps its texture as well as its look."},
{"id": "c-fq0nuozo", "cat": "Service & Hospitality", "q": "An unfinished bottle of Champagne has to hold its pressure overnight. Which closure does that job?", "sa": 1, "accept": ["champagne stopper", "sparkling wine stopper", "clamping stopper", "pressure stopper", "champagne sealer"], "ans": "A clamping sparkling wine stopper", "exp": "A sprung clamp grips the lip of the bottle and holds several atmospheres. The teaspoon in the neck is folklore and does nothing whatever."},
{"id": "c-f6ur6l7t", "cat": "Service & Hospitality", "q": "A bottle has lain on its side for thirty years and is on tonight's order. What should have been done to it yesterday?", "sa": 1, "accept": ["stood upright a day before service", "stood upright", "stand upright", "stand it upright", "stood it upright", "store it upright", "stored upright", "upright", "standing upright", "left standing upright", "upright for a day", "stand it up", "stood it up", "stand the bottle upright"], "ans": "Stood upright a day before service", "exp": "Sediment lying along the flank of a bottle cannot be decanted cleanly. A day standing pulls it into the punt, where a careful pour can leave it behind."},
{"id": "c-akdajos5", "cat": "Service & Hospitality", "q": "Two decants, a young Barolo and a 1971 Burgundy, differ in handling how?", "opts": ["The old wine is poured hard for air and the young one poured gently", "Neither is poured until the wine has reached room temperature", "Both are poured hard and rested for an hour before service", "The young wine is aired and the old one poured off its deposit"], "a": 3, "exp": "One decant is for air and the other is for sediment, and they call for opposite handling: the Barolo is poured hard and left to open, the Burgundy poured gently and served straight away. A fragile old wine can fall apart in the decanter within twenty minutes."},
{"id": "c-bjqgkk9r", "cat": "Service & Hospitality", "q": "A light is set under the neck of the bottle during a decant. What is the server watching for?", "sa": 1, "accept": ["sediment reaching the neck", "sediment", "deposit", "sediment in the neck", "sediment reaching the shoulder", "deposit approaching the shoulder", "the sediment moving up", "sediment coming up the neck", "the deposit reaching the neck"], "ans": "Sediment reaching the neck", "exp": "A candle is traditional and a phone torch does the same work. The pour stops the moment the cloud arrives at the shoulder, and the last inch stays behind."},
{"id": "c-wmsk4tor", "cat": "Service & Hospitality", "q": "A fifteen-year-old Rioja Gran Reserva is ordered and the table asks whether it wants a decanter. Which reply is soundest?", "opts": ["Never decant Spanish wine, since it has already had long cask ageing", "Taste it first and decant if it is closed or throwing sediment", "Decant anything older than ten years as a matter of house policy", "Decant only when a guest specifically asks for it"], "a": 1, "exp": "Age alone settles nothing. Gran Reserva has usually spent years in cask and may be perfectly open already, in which case air costs it more than it gives. Deposit is the separate question, and a bottle at fifteen years that is dropping any goes into a decanter whether it needs air or not."},
{"id": "c-vv33osow", "cat": "Service & Hospitality", "q": "Bottled unfiltered and throwing a heavy crust, which fortified wine is decanted as a matter of routine?", "sa": 1, "accept": ["vintage port", "vintage ports", "vintage porto", "unfiltered vintage port", "crusted port", "vintage port and crusted port"], "ans": "Vintage Port", "ex": 1, "exp": "The crust forms because the wine goes into bottle young and unfiltered. Tawny, aged in cask and filtered before bottling, needs nothing of the kind."},
{"id": "c-xdokl2gh", "cat": "Service & Hospitality", "q": "Which piece of equipment sits in the neck of the decanter to catch cork fragments and coarse deposit?", "sa": 1, "accept": ["decanting funnel", "~funnel", "wine funnel", "decanter funnel", "funnel with a screen"], "ans": "A decanting funnel", "exp": "The better ones carry an angled spout that runs wine down the wall of the decanter rather than dropping it into the middle, which suits a fragile old red."},
{"id": "c-nao6w6wc", "cat": "Service & Hospitality", "q": "Ice alone chills a bottle slowly and unevenly. What else goes into the bucket?", "sa": 1, "accept": ["water", "cold water", "ice and water", "water and ice", "ice water", "water in the bucket", "half water"], "ans": "Water", "exp": "Air between cubes insulates, so dry ice cubes touch only a fraction of the glass. Half ice and half water chills several times faster."},
{"id": "c-lst6e5kq", "cat": "Service & Hospitality", "q": "The red has stood by the pass all evening and now tastes hot and blurred. What is the remedy?", "opts": ["An ice cube dropped into each glass", "A hard decant to drive off some of the alcohol", "A few minutes in ice to bring it toward sixteen degrees", "A second bottle opened and blended with the first"], "a": 2, "exp": "Above about eighteen degrees alcohol dominates and definition disappears. Five minutes in a bucket rescues a wine that had seemed faulty."},
{"id": "c-klhhcue4", "cat": "Service & Hospitality", "q": "Serving a fine white straight out of a full ice bucket costs the guest what?", "opts": ["Its colour, which fades at low temperature", "Most of its aroma and much of its texture", "Its alcohol, which evaporates in the bucket", "Its acidity, which cold strips away"], "a": 1, "exp": "Aromatic compounds need warmth to volatilise, so a serious white shows least at four degrees. A bucket is for holding a temperature, not for reaching one."},
{"id": "c-h7q2djm9", "cat": "Service & Hospitality", "q": "Cold hardens one structural component of a red and mutes the aromatics. Which component turns harsher?", "sa": 1, "accept": ["~tannin", "~tannins", "~astringency", "~tannic grip"], "ans": "Tannin", "exp": "The same bottle at ten degrees and at sixteen can seem to be two wines. An over-chilled red reads as tough and bitter when nothing at all is wrong with it."},
{"id": "c-6510orvw", "cat": "Service & Hospitality", "q": "Which two Sherry styles are served as cold as a white wine and treated as perishable once opened?", "sa": 1, "accept": ["fino and manzanilla", "manzanilla and fino", "fino manzanilla", "manzanilla fino", "fino and manzanilla sherry"], "ans": "Fino and Manzanilla", "ex": 1, "exp": "Both age under flor and are bottled at modest strength, so they oxidise much as a table wine does. A bottle open for a week has nothing left worth selling."},
{"id": "c-54p6ik94", "cat": "Service & Hospitality", "q": "A restaurant with no cellar keeps its reds in a kitchen at twenty-two degrees. Which single purchase most improves service?", "sa": 1, "accept": ["wine cabinet", "wine fridge", "temperature controlled cabinet", "wine refrigerator", "climate controlled cabinet"], "ans": "A temperature-controlled wine cabinet", "exp": "Wine stored warm is tired before it is opened, and no amount of ice at the table undoes that. Storage decides more about a bottle than service ever can."},
{"id": "c-cuckg1kr", "cat": "Service & Hospitality", "q": "Bottle after bottle of one producer's screwcapped white smells dank and musty, and fresh glasses change nothing. Which source does that pattern implicate?", "sa": 1, "accept": ["contamination in the winery", "contamination in the winery itself", "the winery itself", "winery contamination", "the winery environment", "contamination in the cellar", "cellar contamination", "tainted cellar materials", "cellar timber", "the producer's own cellar", "the winery", "the cellar", "taint in the winery", "something in the winery"], "ans": "Contamination in the winery itself", "exp": "Musty taint compounds form from chlorophenols in cellar timber, cartons and cleaning products, then drift through a building and are taken up by the wine long before bottling. A screwcap closes the closure route and nothing else. Odd single bottles across many wines suggest closures, while a whole run from one address suggests the address."},
{"id": "c-lo1np3c6", "cat": "Service & Hospitality", "q": "A wine smelling of struck match and drains cleans up after ten minutes in the glass. Which condition explains it?", "sa": 1, "accept": ["~reduction", "~reductive", "~reduced", "sulphur compounds"], "ans": "Reduction", "exp": "Volatile sulphur compounds form where a wine has seen too little oxygen. Because air disperses them, a decant is a diagnosis as much as a treatment."},
{"id": "c-7i0cuyny", "cat": "Service & Hospitality", "q": "The same wine has been returned twice as corked and both bottles taste sound to you. What is the professional response?", "opts": ["Decline to open a third bottle of anything", "Replace it again and note the pattern", "Charge for both bottles and say nothing further", "Explain in detail why the guest is mistaken"], "a": 1, "exp": "Nothing is won by litigating at the table, so the third bottle goes out without argument and the pattern is raised with management afterwards. Two sound bottles rejected is a commercial matter for later, and often a guest who dislikes the style rather than the bottle."},
{"id": "c-5qy7ukmc", "cat": "Service & Hospitality", "q": "Sticking plaster, barnyard and a flattening of fruit across a producer's whole range point to which spoilage organism?", "sa": 1, "accept": ["brettanomyces", "brett", "dekkera", "brettanomyces bruxellensis"], "ans": "Brettanomyces", "exp": "The yeast produces 4-ethylphenol and 4-ethylguaiacol. Small amounts divide opinion, and at higher levels every wine in a range starts to smell the same."},
{"id": "c-uj1ds7we", "cat": "Service & Hospitality", "q": "A bottle arrives with wine seeping past the capsule and a fill level well down the shoulder. What does that suggest?", "opts": ["A mark of quality in mature Bordeaux", "Ordinary evaporation in any bottle over five years old", "Heat damage or a failed seal", "A wine deliberately aged under a veil of flor"], "a": 2, "exp": "Wine expands when it gets hot and forces its way past the cork, and it can happen at any point between the winery and the table. Some ullage is normal in a very old bottle, but a sticky capsule and fresh seepage are not."},
{"id": "c-rqk1200t", "cat": "Service & Hospitality", "q": "Open since Monday, a by-the-glass red now tastes flat and bruised. Which process is at work?", "sa": 1, "accept": ["~oxidation", "~oxidised", "~oxidized", "oxygen exposure"], "ans": "Oxidation", "exp": "Acetaldehyde builds while fruit falls away. A by-the-glass programme without gas or vacuum is selling a different wine on Thursday from the one it opened on Monday."},
{"id": "c-m36084ry", "cat": "Service & Hospitality", "q": "Which single property of a beer glass, ruined by grease or detergent film, decides whether the head survives the pour?", "sa": 1, "accept": ["beer clean glass", "cleanliness", "clean glass", "grease free glass"], "ans": "Cleanliness, a beer-clean glass", "exp": "Any residue collapses foam as it forms, exactly as it does with sparkling wine. A glass that leaves bubbles clinging to its sides is not clean."},
{"id": "c-1j5mlxff", "cat": "Service & Hospitality", "q": "Ginjo and daiginjo are separated from ordinary sake by one number on the label. Which measurement is it?", "sa": 1, "accept": ["polishing ratio", "rice polishing ratio", "seimaibuai", "milling rate", "degree of polishing"], "ans": "The rice polishing ratio, or seimaibuai", "exp": "Ginjo requires the grain milled to sixty per cent or less and daiginjo to fifty, stripping the outer layers that carry coarser flavours."},
{"id": "c-ly7s66za", "cat": "Service & Hospitality", "q": "A table orders sake alongside a delicate raw fish course. Which service suits a daiginjo?", "opts": ["Over ice with a twist of citrus", "Heated to about fifty degrees in a tokkuri", "At room temperature in a large balloon", "Chilled, in a small wine glass or an ochoko"], "a": 3, "exp": "Warming suits robust junmai styles and blunts a fragile one. The highly milled grades are served cold and increasingly from a stemmed glass."},
{"id": "c-8ypy4a9k", "cat": "Service & Hospitality", "q": "Warming a brandy balloon over a flame at the table is now regarded as what?", "opts": ["Poor practice, as heat coarsens the aroma", "Essential preparation for any long-aged spirit", "The only correct treatment for an XO", "A legal requirement for Cognac service in France"], "a": 0, "exp": "A flame sends ethanol off the surface ahead of everything else, so the nose is all spirit and nothing underneath it survives. The hand is warmth enough, and most houses now prefer a tulip that concentrates aroma without cooking it. The flame is theatre from another era."},
{"id": "c-2mg4yqxp", "cat": "Service & Hospitality", "q": "Served before a meal to sharpen the appetite rather than satisfy it, a drink of that kind is called what?", "sa": 1, "accept": ["~aperitif", "~apertif", "~aperitivo", "~aperatif"], "ans": "An aperitif", "exp": "Dry, moderate in alcohol, often saline or bitter. Fino, dry sparkling and vermouth all work because they leave the palate hungry rather than full."},
{"id": "c-4ddxnjga", "cat": "Service & Hospitality", "q": "Taken after the meal and often a brandy or a fortified wine, which term applies to that drink?", "sa": 1, "accept": ["~digestif", "~digestive", "~digestivo", "~after dinner drink"], "ans": "A digestif", "exp": "The category is set by its moment rather than its contents. Sweetness and strength both suit a palate that has finished eating."},
{"id": "c-x9ybck2f", "cat": "Service & Hospitality", "q": "Bottles are laid on their sides for a reason that applies to one type of closure only. Which closure?", "sa": 1, "accept": ["natural cork", "cork", "corks", "natural corks", "cork stopper", "natural cork stopper", "one piece natural cork"], "ans": "Natural cork", "ex": 1, "exp": "A cork dries and shrinks in an upright bottle and eventually lets air past. Synthetic and screwcap closures cannot dry out, so the practice does nothing for them."},
{"id": "c-llss3vfb", "cat": "Service & Hospitality", "q": "A cellar holds steady temperature and humidity, yet bottles stored beside the loading bay age badly. Which overlooked factor is likely?", "sa": 1, "accept": ["~vibration", "~vibrations", "~movement", "~shaking"], "ans": "Vibration", "exp": "Constant low-level movement keeps sediment in suspension and is widely held to disturb a wine's development. Compressors, lifts and loading doors are the usual sources."},
{"id": "c-eg0a7xci", "cat": "Service & Hospitality", "q": "Stock is counted and valued at the close of each period. Which figure does that count feed directly?", "opts": ["The service charge shared out among the staff", "The corkage rate charged on bottles brought in", "Cost of goods sold, and the beverage cost percentage", "The number of covers served in the period"], "a": 2, "exp": "Opening stock plus purchases minus closing stock gives what was actually consumed, and the beverage cost percentage is worked out from that figure. Without a count, cost of sales is a guess and so is every margin built on it."},
{"id": "c-6ldkwtpi", "cat": "Service & Hospitality", "q": "Every listed wine has a minimum quantity below which it must be reordered. What is that quantity called?", "sa": 1, "accept": ["par level", "~par", "par stock", "minimum par"], "ans": "The par level", "exp": "Par is set from how fast a wine sells and how long the supplier takes to deliver. Set high it ties up cash, set low it puts the wine off the list."},
{"id": "c-bj2f7v48", "cat": "Service & Hospitality", "q": "The oldest stock of a wine leaves before the newest delivery does. Which four-letter principle is that?", "sa": 1, "accept": ["fifo", "first in first out", "stock rotation", "oldest sold first"], "ans": "FIFO, first in first out", "exp": "It matters most for beer, an open by-the-glass range and anything with a drink-by window. In a cellar of ageworthy reds the reverse is often deliberate."},
{"id": "c-wt4pcnbf", "cat": "Service & Hospitality", "q": "A case of a listed wine has not moved in eighteen months. What is the standard remedy before it becomes dead stock?", "opts": ["Show it by the glass and get the floor staff tasting it", "Return it to the supplier for a credit", "Raise its price so it reads as a serious bottle worth ordering", "Write the whole case off at once"], "a": 0, "exp": "Dead stock is cash sitting on a shelf, and a by-the-glass pour or a flight is the cheapest way to move it. Most slow wines are slow because nobody on the floor has tasted them and can say anything true about them."},
{"id": "c-4gw8zkb1", "cat": "Service & Hospitality", "q": "Pricing every bottle at the same multiple of its cost produces which distortion?", "opts": ["The cheap end loses money and the expensive end subsidises it", "Regional balance across the list collapses", "Margins by the glass fall below margins by the bottle", "The expensive end prices itself off the list"], "a": 3, "exp": "Most lists slide the multiple downward as cost rises, so a fine bottle carries a larger cash margin at a smaller percentage. A flat multiple prices the best wines off the list, while the cheap end keeps its percentage and earns thin cash rather than a loss, and the expensive end, held to that same percentage, subsidises nothing below it."},
{"id": "c-54z3j3bh", "cat": "Service & Hospitality", "q": "Bringing their own bottle, a guest is charged for the glassware, the service and the lost sale. Name that charge.", "sa": 1, "accept": ["~corkage", "corkage fee", "~corkage charge", "byo fee"], "ans": "Corkage", "exp": "It is a policy rather than a rule, and it works best stated plainly on the list. Waiving it for a bottle the restaurant does not stock buys a great deal of goodwill."},
{"id": "c-1ksexqiu", "cat": "Service & Hospitality", "q": "Which single ratio, cost divided by selling price, does management watch to judge a beverage programme?", "sa": 1, "accept": ["beverage cost percentage", "pour cost", "cost percentage", "beverage cost"], "ans": "Beverage cost percentage", "exp": "It is read as a trend rather than as a target. A programme selling more fine wine at a lower percentage can be more profitable in cash than one hitting its number."},
{"id": "c-tcp1av22", "cat": "Service & Hospitality", "q": "Recommending a bottle well below the price a table has named tends to produce what over a season?", "opts": ["Trust, return visits and a larger total spend", "An immediate loss the restaurant cannot recover", "Guests who order nothing else for the rest of the meal", "A reputation for a weak and cautious list"], "a": 0, "exp": "Selling to a budget rather than above it is the durable strategy. A guest who feels worked over remembers that longer than they remember the wine."},
{"id": "c-ynuz76o0", "cat": "Service & Hospitality", "q": "Wines poured by the glass sit half-empty for days. Which gases are used to hold them?", "sa": 1, "accept": ["argon and nitrogen", "argon", "nitrogen", "inert gas", "argon or nitrogen"], "ans": "Argon and nitrogen", "exp": "Argon is denser than air and blankets the surface, while nitrogen displaces the oxygen above the wine. Vacuum systems attack the same problem by removing the headspace."},
{"id": "c-s0br06dh", "cat": "Service & Hospitality", "q": "A regular guest is visibly intoxicated and orders another bottle. What does the sommelier do?", "opts": ["Decline the sale and offer food, water and a taxi", "Serve it, since the guest is well known to the house", "Serve a cheaper wine at the same price", "Take the order and let the kitchen delay it"], "a": 0, "exp": "Refusing service is a legal duty in most jurisdictions and a duty of care everywhere. Done courteously, quietly and without an audience, it rarely costs the relationship."},
{"id": "c-67iecbzw", "cat": "Service & Hospitality", "q": "Asked about a wine they genuinely do not know, which response serves the guest best?", "opts": ["Improvise a plausible description from the region and grape", "Steer the conversation toward a wine they do know", "Say so, then find out and come back with a real answer", "Hand over the list and let the guest decide alone"], "a": 2, "exp": "Guests forgive not knowing and remember being misled. The recovery, made quickly, usually reads as more expert than a smooth invention would."},
{"id": "c-svkhgbox", "cat": "Service & Hospitality", "q": "Which French term names the trolley or side table used for finishing and serving beside the guest?", "sa": 1, "accept": ["gueridon", "gueridon trolley", "gueridon table", "service trolley"], "ans": "The gueridon", "exp": "Decanting, carving and flaming all happen there rather than on the guest's own table. It keeps the work visible without putting equipment among the plates."},
{"id": "c-2rn254i9", "cat": "Service & Hospitality", "q": "One glass of a 1990 first growth is wanted with the rest of the bottle left intact. Which device makes that possible?", "sa": 1, "accept": ["~coravin", "coravin system", "argon needle device", "needle and argon system"], "ans": "A Coravin", "exp": "A fine needle passes through the cork, argon replaces what is drawn out, and the cork reseals behind it. It changed which bottles a list can sensibly open."},
{"id": "c-0dez4xdf", "cat": "Service & Hospitality", "q": "Which phrase describes service that meets a need before the guest has voiced it?", "sa": 1, "accept": ["anticipatory service", "anticipation", "anticipatory", "reading the table"], "ans": "Anticipatory service", "exp": "Water refilled unasked, a glass changed before the next wine arrives, a chair steadied. It is the difference between a table being served and a table being looked after."},
{"id": "c-2krw39ub", "cat": "South Africa", "q": "Drawing a new ward onto the Wine of Origin map takes evidence a new district never has to produce. What must the applicants demonstrate?", "opts": ["That at least ten registered producers already make and bottle wine inside the proposed boundary", "A distinct soil, climate and ecology in the ground itself", "That the area lies wholly within a single registered estate", "That the proposed name has a documented history of use on labels going back fifty years"], "a": 1, "exp": "A district can follow broad geography and even administrative convenience, but the ward is the scheme's terroir tier and its boundary has to be argued from the land. That is why a ward name like Groenekloof carries real information on a label: it is a claim about the ground, not about a map-maker's tidiness."},
{"id": "c-qtrb7buc", "cat": "South Africa", "q": "Records alone cannot win a Cape wine its certification seal. What must the wine itself get through before the seal is granted?", "opts": ["A blind tasting panel and laboratory analysis", "A ballot of its district's producers", "Six months of maturation in tank or barrel before bottling", "A vineyard inspection at harvest"], "a": 0, "exp": "Every certified wine is chemically analysed and tasted blind by the Wine and Spirit Board's panels, and a faulty wine fails whatever its paperwork says. The seal is therefore a statement about the liquid as well as the ledger, which is not true of every origin system in the world."},
{"id": "c-q5md35lv", "cat": "South Africa", "q": "Europe's appellation idea reached the Cape as law in the early 1970s, and one vintage was the first sold under Wine of Origin seals. Give the year.", "sa": 1, "accept": ["1973", "in 1973", "1973 vintage", "nineteen seventy three"], "ans": "1973", "ex": 1, "exp": "The scheme was promulgated in 1972 and certified its first wines with the 1973 harvest, which makes it one of the oldest origin systems outside Europe. It borrowed the layered idea of place from the French model while refusing the link between place and permitted grape: a Cape origin says where the fruit grew, and nothing else."},
{"id": "c-y0w66168", "cat": "South Africa", "q": "One producer, one cellar, and a flagship blend drawing on vineyards forty kilometres apart. Which label claim has the distance cost that wine?", "sa": 1, "accept": ["estate wine", "estate", "single estate", "the estate wine claim", "wine of origin estate wine", "estate wine designation", "the estate designation", "estate wine of origin", "the word estate", "estate bottled"], "ans": "Estate wine", "ex": 1, "exp": "An estate wine must come off land farmed as one contiguous unit, with the wine made in a cellar standing on that unit, so scattered vineyards disqualify the words however good the farming. The claim is about unity of place and production, not quality: a second farm across the valley, or any bought-in fruit, bars a wine that may still be the best in the country."},
{"id": "c-6jydoeox", "cat": "South Africa", "q": "Climbing from the Swartland's rolling grain country to a fold-mountain summit crosses the winelands' three great rocks in a single walk. In what order?", "opts": ["Granite in the low hills, shale across the middle slopes, sandstone capping the top", "Shale in the low hills, granite on the middle slopes, sandstone at the top", "Sandstone in the low hills, granite on the middle slopes, shale at the top", "Shale in the low hills, sandstone across the middle slopes, granite forming the summit"], "a": 1, "exp": "The low country is shale ground, the domes and foot slopes - Paarl Mountain, the Paardeberg, the lower flanks of the Simonsberg - are granite, and the sandstone caps the peaks. Soils creep downhill, so a foot-slope block often farms a mixture of all three, which is one reason Cape growers name the rock rather than the topsoil."},
{"id": "c-yf626msa", "cat": "South Africa", "q": "Every other rock in the winelands is younger than the one the whole Cape stands on, an ocean-floor mud pressed hard more than half a billion years ago. Name it.", "sa": 1, "accept": ["malmesbury shale", "malmesbury", "malmesbury group", "malmesbury shales", "shale of the malmesbury group"], "ans": "Malmesbury shale", "exp": "The Malmesbury Group is Precambrian sediment, hardened before the first shelled creatures existed, and everything else under the vineyards is dramatically younger. It weathers to deep red-brown clay hills that hold winter rain well, and its sheer age is part of why Cape soils run so leached and naturally low in vigour."},
{"id": "c-mz33jgat", "cat": "South Africa", "q": "Mid-century plantings of Chenin Blanc outlived the brandy boom that put them in. Why were so many old blocks never pulled up?", "opts": ["Legislation forbids uprooting any vineyard more than fifty years old", "Phylloxera never crossed into the western districts, so nothing ever forced those vineyards to be replanted", "The KWV paid a premium for fruit off older vines, making them the most valuable blocks on a farm", "They kept bearing a cheap, usable crop on land where replanting promised no return"], "a": 3, "exp": "Nobody preserved them on purpose; they stood where pulling them out was an expense with no return, still yielding distilling and blending fruit at almost no cost. When a newer generation went looking for settled vigour and concentration, that neglect turned out to have banked something money cannot replant quickly, and old-block fruit now commands multiples of the district price."},
{"id": "c-nkm11hn6", "cat": "South Africa", "q": "Vineyards that pass the Old Vine Project's audit may wear a neck seal announcing their standing. What is the seal called?", "sa": 1, "accept": ["certified heritage vineyards", "heritage vineyards", "certified heritage vineyard", "heritage vineyard", "certified heritage vineyards seal", "heritage vineyards seal"], "ans": "Certified Heritage Vineyards", "exp": "The seal certifies blocks of thirty-five years and older and prints the year the vines went into the ground, so a claim most countries make loosely is auditable on a Cape bottle. Certification runs vineyard by vineyard rather than producer by producer, which is why one cellar can hold sealed and unsealed bottlings of the same variety."},
{"id": "c-5g3pitlk", "cat": "South Africa", "q": "A Cape producer can prove a vine's age to the year, because every planting since the 1970s sits in one body's records. Which body keeps them?", "sa": 1, "accept": ["sawis", "south african wine industry information and systems", "south african wine industry information systems", "sa wine industry information and systems"], "ans": "SAWIS", "exp": "SAWIS keeps the national vineyard register, fed by compulsory planting documentation, and the old-vine audits lean on that paper trail rather than on a grower's memory. Few wine countries can date a block so precisely, which is why the Cape's old-vine claim is verifiable where most are marketing."},
{"id": "c-k924bppe", "cat": "South Africa", "q": "A guidebook files Pinotage as 'South Africa's hybrid', and a Certified candidate should wince. What makes the word wrong?", "opts": ["A hybrid must arise by accident in the field, and Pinotage was bred deliberately at a research station", "Hybrids are sterile by definition, and Pinotage sets viable seed in any vineyard", "Both parents are Vitis vinifera, so it is a crossing", "The word hybrid is reserved for rootstocks rather than fruiting varieties"], "a": 2, "exp": "Perold's 1925 cross joined two members of the same species, which makes Pinotage a crossing in exactly the sense the German breeding-station varieties are. Hybrid is reserved for crosses between species, vinifera with an American vine, and the distinction has teeth: hybrids face legal barriers in most European appellations that crossings never meet."},
{"id": "c-q80irpv0", "cat": "South Africa", "q": "Old-style Pinotage drew one criticism above all: a reek of acetone and overripe banana. Which family of fermentation by-products is responsible?", "sa": 1, "accept": ["esters", "isoamyl acetate", "volatile esters", "fruity esters", "ester compounds"], "ans": "Esters", "exp": "Isoamyl acetate is the named culprit, the same ester that flavours banana sweets, and Pinotage ferments throw it more readily than most red varieties. Producers rein it in with riper fruit, sounder ferments and more careful elevage, so the smell now dates a bottle to an era rather than defining the grape."},
{"id": "c-mvqqmg0t", "cat": "South Africa", "q": "Traditional-method Cape sparkling wine once borrowed French words for itself. Why does the category now carry a name of its own?", "opts": ["French wording is barred outright from South African wine labels", "A licence fee was charged for every label carrying the French phrase", "Trade agreements shut Champagne's terms, even methode champenoise, to outsiders", "The Cape's method departs far enough from Champagne's practice that the French term amounted to false description"], "a": 2, "exp": "Producers coined Methode Cap Classique in 1992, ahead of the trade deals with Europe that formally retired methode champenoise along with borrowed names like port and sherry. The wording was deliberate: classique claims the classic method while Cap names the place, and the producers' association that grew around the term now guards it."},
{"id": "c-vr1orfbe", "cat": "South Africa", "q": "After its second fermentation, a Cap Classique must wait before disgorging can even be scheduled. What is the legal minimum time on the lees?", "sa": 1, "accept": ["twelve months", "12 months", "twelve", "12", "one year", "a year", "1 year", "twelve months on the lees", "12 months on the lees", "at least twelve months", "at least 12 months", "minimum of twelve months", "a minimum of 12 months", "twelve months minimum", "12 months minimum", "minimum twelve months", "minimum of 12 months on the lees", "minimum of twelve months on the lees", "minimum 12 months on the lees", "minimum twelve months on the lees", "at least 12 months on the lees", "at least twelve months on the lees", "12 months lees ageing", "twelve months lees ageing", "12 months lees aging", "twelve months lees aging", "one year on the lees", "a year on the lees"], "ans": "Twelve months", "ex": 1, "exp": "The twelve-month floor entered the regulations at the start of the 2020s, replacing the nine months producers had previously worked to, and serious houses go well past it, with three years and more for prestige bottlings. The clock runs on the second fermentation's lees in the same bottle, which is where the category buys its biscuit depth, and it is the rule that most separates Cap Classique from tank-method fizz at the same price."},
{"id": "c-ebpnhqe5", "cat": "South Africa", "q": "For most of the twentieth century the Cape's problem was too much wine, not too little. What did the KWV do with the surplus its members delivered?", "opts": ["Exported it in bulk at prices below the cost of production", "Blended it into a national reserve held back against short harvests", "Bought it up and destroyed it under supervision", "Distilled it, turning the surplus into brandy, fortified wine and spirit stocks"], "a": 3, "exp": "The KWV was founded on the surplus problem, and distillation was its answer: the guaranteed minimum price was pitched at distilling wine, so the pot still and the fortified cellar became the industry's safety valve. That is why brandy and fortified styles loomed so large in the old Cape, and why so much high-cropping white went into the ground."},
{"id": "c-ugalah0x", "cat": "South Africa", "q": "Statutory price floors and quotas ended in the 1990s, yet KWV remains a name on bottles and brandy. What became of the organisation?", "opts": ["It turned itself into an ordinary company and carried on as a producer", "It became the industry's certification authority", "It survives as a growers' union, stripped of any commercial arm", "It was dissolved and its name passed to the state"], "a": 0, "exp": "The co-operative converted into a company in 1997, shedding its statutory powers, and today it competes as one producer among many, best known for brandy. Nothing replaced the quota system at all, and that vacuum is what let the vineyard map redraw itself around quality rather than volume; the replanting of the modern Cape dates from this deregulation."},
{"id": "c-cjl3ve9u", "cat": "South Africa", "q": "Growers around the Paardeberg and Riebeek-Kasteel bound themselves to a code - local fruit only, ambient-yeast ferments, no added acid, restraint with new oak - and badge their bottles for it. Name the group.", "sa": 1, "accept": ["swartland independent producers", "swartland independents", "independent producers", "swartland independent producers group", "swartland independent producers (sip)", "sip"], "ans": "The Swartland Independent Producers", "exp": "Founded at the start of the 2010s by the district's new wave, the group wrote a production charter rather than a marketing club: members' wines must be grown in the Swartland and made within listed limits on additions and new wood. The same circle staged the Swartland Revolution tastings that pulled the world's attention north of Cape Town, and the philosophy of old vines, dry farming and minimal intervention has outlived the festival itself."},
{"id": "c-8exsnpkl", "cat": "South America", "q": "Morning fog off the Pacific reaches a Colchagua vineyard planted in the coastal hills, and the producer wants the label to say so. Which complementary term, written into Chilean law in 2011, applies?", "opts": ["Andes", "Secano Interior", "Entre Cordilleras", "Costa"], "a": 3, "exp": "The 2011 decree added three official zone terms because Chile's valley names run from the mountains to the sea and lump cold coastal fruit in with warm inland fruit. Costa marks the maritime band, so a Colchagua Costa Sauvignon Blanc announces a different wine from one grown an hour inland at Apalta. Secano Interior is a separate legal term for dry-farmed traditional areas, not one of the three zones."},
{"id": "c-puagv108", "cat": "South America", "q": "Snow-fed rivers cross Chile's wine country from the Andes to the ocean, and the valleys they cut run east to west rather than along the country's length. What are these valleys called?", "sa": 1, "accept": ["transverse valleys", "transversal valleys", "transverse river valleys", "east west valleys", "transverse"], "ans": "Transverse valleys", "exp": "Each transverse valley samples every climate Chile has, from fog-cooled coast to Andean foothill, which is why a valley name alone says so little about a wine's style. The complementary zone terms added in 2011 exist to supply exactly the east-west information the valley names miss."},
{"id": "c-qcan4q93", "cat": "South America", "q": "Pinot Noir and Chardonnay ripen slowly around Traiguen, at the cold, rainy southern frontier where Chilean quality planting petered out for decades. Which valley is this?", "sa": 1, "accept": ["malleco", "malleco valley"], "ans": "Malleco", "exp": "Malleco lies south of Bio-Bio in the Araucania, with rainfall Bordeaux would recognise and a season short enough that variety choice narrows to the early ripeners. A handful of pioneering vineyards around Traiguen made its reputation, and planting has since crept even further south."},
{"id": "c-15l3yzc7", "cat": "South America", "q": "Granite hills around Guarilihue carry century-old, dry-farmed bush vines of Moscatel de Alejandria, for generations the backbone of one southern valley's everyday wine. Name the valley.", "sa": 1, "accept": ["itata", "itata valley", "valle del itata", "valle de itata", "itata in the south", "chile's itata valley"], "ans": "Itata", "ex": 1, "exp": "Itata's Moscatel de Alejandria went into bulk blends and the local jug trade for generations, and the same old vines now supply taut, saline whites for producers who farm them exactly as they were always farmed. Cinsault and Pais carry the red half of the same story."},
{"id": "c-l2wzk9gg", "cat": "South America", "q": "A growers' pact in Maule sells old-vine Carignan under one shared trademark. What do its rules demand of the vineyards behind the label?", "opts": ["Old bush vines, dry-farmed, in Maule's secano", "Grafted vines above five hundred metres", "Young drip-irrigated plantings on Andean gravel", "Organic certification and hand harvesting"], "a": 0, "exp": "VIGNO ties the trademark to head-trained, unirrigated vines of serious age in Maule's dry-farmed country, because the whole point is rescuing a patrimony that predates the modern industry. Each member bottles its own wine, so the name guarantees the farming rather than a house style."},
{"id": "c-1q4o3gph", "cat": "South America", "q": "Southern taverns pour a cloudy, tart country wine, mostly Pais, sold young in jugs and demijohns and now fashionable in natural wine bars abroad. What is it called?", "sa": 1, "accept": ["pipeno", "pipeno wine"], "ans": "Pipeno", "exp": "Pipeno is the smallholder wine of Itata, Bio-Bio and Maule, fermented simply and sold without pretension, and the natural wine movement adopted it as proof that Chile's south never stopped making honest wine. Its new cachet has put money back into exactly the old vineyards the revival needs."},
{"id": "c-6ko4gvtt", "cat": "South America", "q": "Green capsicum keeps showing up in a Rapel Carmenere even in warm years. Which change in the vineyard attacks the problem at its source?", "opts": ["Open the canopy, ease late-season water and hold the fruit longer", "Pick earlier to keep the fruit fresh", "Replant on cool coastal ground", "Shade the fruit zone completely so direct sun never touches the skins"], "a": 0, "exp": "Methoxypyrazines break down with sunlight on the fruit and with time on the vine, and Carmenere's late season plus its vigour on fertile, well-watered ground is what keeps them high. Shading and earlier picking both push in the wrong direction, and the cold coast would leave the variety greener still."},
{"id": "c-o3svm4l1", "cat": "South America", "q": "Despite facing no phylloxera at all, plenty of new Chilean vineyards go in grafted onto rootstock. What drives the choice?", "opts": ["Nematodes in old soils, and rootstocks bred for drought", "Grafted vines cost less to establish", "Quarantine rules that admit only pre-grafted imported vines", "European buyers who insist on grafted vineyards before purchase"], "a": 0, "exp": "Root-knot nematodes build up in ground that has carried vines for decades, and no own-rooted vinifera resists them, while the right rootstock also spends scarce water more carefully. Freedom from phylloxera closes off one reason to graft, not every reason."},
{"id": "c-53kxkb5u", "cat": "South America", "q": "Tasted side by side, a Malbec from Gualtallary at sixteen hundred metres stands apart from one grown in Lujan de Cuyo at a thousand. Which shift does the extra height explain?", "opts": ["An earlier harvest by roughly a month", "Deeper colour and softer, riper tannin", "Firmer acidity and a tauter, less fleshy build", "Higher alcohol from the stronger sunlight"], "a": 2, "exp": "Every hundred metres climbed cools the site the way a move poleward would, so the high Uco picks later, holds more natural acid and trades Lujan's plush mid-palate for tension and floral lift. Sunlight does intensify with altitude, but it thickens skins rather than pushing alcohol up."},
{"id": "c-hcjc8o9d", "cat": "South America", "q": "Pale crusts coat the stones under Gualtallary's vineyards, and marketing shorthand calls the district limestone country. Strictly, the pale material is a surface deposit of what?", "sa": 1, "accept": ["calcium carbonate", "caliche", "calcareous crusts", "calcareous crust", "calcrete", "carbonate crusts"], "ans": "Calcium carbonate (caliche)", "exp": "The carbonate arrived dissolved in water and was left coating gravels and binding sand as caliche, rather than lying under the vines as a sedimentary limestone bedrock. It still does what growers want from lime-rich ground, restraining vigour and firming the wines, which is why the shorthand persists."},
{"id": "c-1c9ziwfg", "cat": "South America", "q": "Soil pits and the true edges of an alluvial fan, rather than any administrative line, fixed the boundary of a San Carlos GI in 2013, a first for Argentina. Name it.", "sa": 1, "accept": ["paraje altamira", "altamira"], "ans": "Paraje Altamira", "exp": "Paraje Altamira was drawn around the fan of the Tunuyan river after growers commissioned soil mapping, putting geology above municipal convenience for the first time in an Argentine GI. The precedent stuck, and later Uco Valley GIs followed the same logic."},
{"id": "c-4ac98d34", "cat": "South America", "q": "Beyond the reach of Mendoza's old surface channels, the new plantings high in the Uco had to find their own water. What supplies their drip lines?", "sa": 1, "accept": ["~groundwater", "ground water", "wells", "boreholes", "bore hole", "well water", "aquifer", "underground water", "subterranean water"], "ans": "Groundwater pumped from wells", "exp": "Boreholes sunk deep into the aquifer under the alluvial fans feed the drip network, metering water out vine by vine. Pumping is what made the high Uco plantable at all, and it is why groundwater regulation has become a live argument in Mendoza."},
{"id": "c-rbk9zr6l", "cat": "South America", "q": "High in the Calchaqui Valleys near Molinos, an estate founded in 1831 farms Malbec above 3,000 metres at its Altura Maxima site. Name the estate.", "sa": 1, "accept": ["colome", "bodega colome"], "ans": "Bodega Colome", "exp": "Colome claims standing as Argentina's oldest working winery, and its Altura Maxima terraces are among the highest commercial vineyards anywhere. At that height the ultraviolet load is brutal and the nights are cold, which shows in wines of savage colour and acid."},
{"id": "c-n5ptz8t7", "cat": "South America", "q": "Beyond certifying where the grapes grew, Argentina's two DOCs impose something its ordinary geographical indications do not. What?", "opts": ["Minimum cellar-door prices fixed each vintage", "A ban on irrigation", "Production rules covering varieties, yields and ageing", "A guarantee that the wine was estate-bottled inside the zone"], "a": 2, "exp": "An Indicacion Geografica in Argentina is a delimited origin and nothing more, while the DOC framework adds a rulebook in the European manner. Most producers have preferred the freedom of the IG, which is why only Lujan de Cuyo and San Rafael ever took DOC status and few wines invoke it even there."},
{"id": "c-fh3or3l2", "cat": "South America", "q": "Riojano, Sanjuanino and Mendocino all appear after the word Torrontes in Argentine ampelography. What is the actual relationship among the three?", "opts": ["One identical variety travelling under three provincial trade names", "Three distinct varieties, with Riojano the one that matters", "Three clones of a single variety, selected province by province", "Two table grapes and a wine grape that happen to share a name"], "a": 1, "exp": "DNA work separates them into three different varieties rather than clones or synonyms, and Torrontes Riojano is the aromatic one that built Cafayate's reputation. Sanjuanino and Mendocino mostly feed the domestic and bulk trade, so a bottle labelled simply Torrontes is almost always Riojano."},
{"id": "c-aff4uw4o", "cat": "South America", "q": "Barely three hundred metres above sea level, Rio Negro's vineyards still make taut, fresh-fruited wine. What substitutes for the altitude Mendoza depends on?", "opts": ["Cold Atlantic fog rolling up the valley each morning", "Southerly latitude and the cool season it brings", "Limestone bedrock lying beneath the whole valley floor", "Meltwater irrigation straight off the Andes"], "a": 1, "exp": "At thirty-nine degrees south the season is long, windy and cool, with wide day-night swings doing the freshening work that height does further north. The Atlantic lies hundreds of kilometres away across dry plateau, so no fog ever reaches the Alto Valle."},
{"id": "c-lsbxtzdn", "cat": "South America", "q": "Trevelin and Sarmiento push Argentine viticulture to its southern limit, where a freeze can arrive in any month. Which province are they in?", "sa": 1, "accept": ["chubut", "chubut province"], "ans": "Chubut", "exp": "Chubut sits south of Rio Negro's classic valleys, and its scattered plantings of Pinot Noir, Chardonnay and Riesling gamble on a season that barely closes. Otronia at Sarmiento, beside Lake Musters, farms some of the southernmost vineyards in the world."},
{"id": "c-4mo3yywq", "cat": "South America", "q": "Rain arrives in every season on Uruguay's vineyards, and no mountain wall or cold current shelters them. Which continental habit does the country therefore break?", "opts": ["Building a reputation on one signature grape", "Bottling reds from a thick-skinned variety", "Harvesting in the southern hemisphere autumn", "Farming irrigated desert in a rain shadow"], "a": 3, "exp": "Chile and Argentina both farm arid land in the lee of mountains and supply the water themselves, while Uruguay's Atlantic climate reads more like Bordeaux: real rain, real vintage variation and humidity to manage. Dry-farming is the norm there, and disease pressure rather than drought sets the farming calendar."},
{"id": "c-5imntaa0", "cat": "South America", "q": "Thin soils over granite near Punta del Este, cooled by the open South Atlantic, have drawn ambitious new wineries and Uruguay's best Albarino. Which department is this?", "sa": 1, "accept": ["maldonado", "maldonado department"], "ans": "Maldonado", "exp": "Maldonado's rocky hills and sea wind give whites a salinity the clay of Canelones cannot match, and Albarino, at home on Atlantic granite in Galicia, has proved the shrewdest match for the place. Bodega Garzon put the department on the international map."},
{"id": "c-m9k8c5xn", "cat": "South America", "q": "Tiny, measured doses of oxygen bubbled through young red wine were first engineered to tame Tannat, and Uruguayan cellars adopted the technique early. What is it called?", "sa": 1, "accept": ["micro oxygenation", "micro oxidation", "micro ox", "microbullage", "~microoxygenation"], "ans": "Micro-oxygenation", "exp": "Patrick Ducournau worked it out in Madiran in the early 1990s, polymerising Tannat's tannins softer without waiting years in barrel, and Uruguay took it up for the same grape's same problem. Done well it rounds the wine; overdone it dries the fruit out, which is why the dose is metered in millilitres per litre per month."},
{"id": "c-eznj832j", "cat": "South America", "q": "Juice, jug wine and table grapes soak up most of Serra Gaucha's harvest, drawn from an American hybrid that out-plants any vinifera there. Name it.", "sa": 1, "accept": ["isabel", "isabella", "isabel grape", "isabella grape"], "ans": "Isabel", "ex": 1, "exp": "Isabel, the Isabella of nineteenth-century North America, shrugged off the Serra's rain and fungus where European vines struggled, and the immigrant families never stopped growing it. Brazilian law reserves the term vinho fino for wine made from vinifera, which is precisely the line Isabel cannot cross."},
{"id": "c-1swcinph", "cat": "South America", "q": "Sweet, grapey and gently alcoholic, the espumante of Farroupilha answers Asti rather than Champagne. How is it put together?", "opts": ["Isabel juice carbonated at bottling", "Moscatel grapes, their sparkle raised in a tank", "Riesling Italico finishing its first fermentation inside the bottle", "Chardonnay and Pinot Noir refermented in the bottle"], "a": 1, "exp": "Farroupilha holds a geographical indication specifically for its Moscatels, and fermenting the sparkle up inside a sealed tank preserves the grape's fresh perfume the way it does in Asti. The Serra's traditional-method houses work mostly with Chardonnay and Pinot Noir, so the two styles split the market between them."},
{"id": "c-dz8he7px", "cat": "South America", "q": "Vines climb onto overhead frames well above head height across much of Serra Gaucha, a system the Italian settlers brought and kept for its generous yields. What is the system called there?", "sa": 1, "accept": ["latada", "pergola", "overhead pergola", "pergola trellis"], "ans": "Latada (pergola)", "exp": "The latada, a full overhead pergola, carries the big crops the region's juice and jug trade depends on. Quality-minded estates have been converting to vertical espaldeira rows, trading volume for exposure, and the choice of trellis maps the split between the two industries almost exactly."},
{"id": "c-sef2g0yy", "cat": "Southern France", "q": "Printed alone on a label, the one word Languedoc claims fruit from a wider territory than most buyers guess. How wide?", "opts": ["The Herault department alone, the historic heart of the Midi", "The Aude, the Herault and the Gard, but nothing south of them", "The communes of the former Coteaux du Languedoc and no more", "From the gates of Nimes all the way down to the Spanish border"], "a": 3, "exp": "The name replaced Coteaux du Languedoc in 2007 and was stretched over the appellation communes of the whole of greater Languedoc-Roussillon, so a Cotes du Roussillon grower may declassify into it while nobody can move the other way. It is the floor of the regional pyramid: the named appellations stand on it, and the crus stand on them."},
{"id": "c-7nt7qng6", "cat": "Southern France", "q": "Tasted beside a red off the coastal plain, a Pic Saint-Loup shows cooler fruit and brighter acidity. What accounts for the difference?", "opts": ["It sits far inland under the Cevennes, higher and cooler at night", "Its slopes all face north, away from the midday sun", "Sea air off the Golfe du Lion cools the vineyard through August", "The decree keeps Syrah out of the blend, judging it too heavy for the site"], "a": 0, "exp": "The cru sits in the first folds of the Cevennes well back from the sea, and its summer nights run cold while the coast barely cools, so acidity survives that the plain loses. Syrah in fact leads the reds, the appellation covers red and rose only, and it catches more rain than almost anywhere else in the Languedoc."},
{"id": "c-xkhy6lnk", "cat": "Southern France", "q": "Cold air slides off the Larzac causse onto the vineyards under its cliffs every summer night, and that swing between day and night built the case for a red-only cru promoted in 2014. Name it.", "sa": 1, "accept": ["terrasses du larzac", "les terrasses du larzac", "terrasses du larzac aoc", "the terrasses du larzac cru", "terrasses du larzac appellation"], "ans": "Terrasses du Larzac", "exp": "The causse is the high limestone plateau at the region's back, and the cold air draining off it stretches ripening out in a district that is otherwise seriously hot, which is why the wines keep a freshness the coast cannot manage. The appellation is red only, and it had gathered many of the Languedoc's most ambitious estates before it ever held a decree of its own."},
{"id": "c-1xa2tjj5", "cat": "Southern France", "q": "Roman sailors knew it as an island off Narbonne; the Aude's silt has since tied its limestone bulk to the shore, and its salty whites carry its reputation among the crus. Name the massif.", "sa": 1, "accept": ["la clape", "la clape aoc", "the la clape massif", "massif de la clape", "la clape cru"], "ans": "La Clape", "exp": "Stony garrigue between Narbonne and the sea, it is one of the driest and sunniest corners of France, and the whites must carry a substantial share of late-ripening Bourboulenc, which tastes of salt and fennel here. The reds are solid, but the whites are the reason the massif is counted among the crus."},
{"id": "c-7nkowwz7", "cat": "Southern France", "q": "Beneath every row of one Languedoc cru lies the same folded schist, with no limestone anywhere inside its boundary. Name the cru.", "sa": 1, "accept": ["faugeres", "faugeres aoc", "aoc faugeres", "the faugeres cru", "faugeres appellation"], "ans": "Faugeres", "exp": "The schist runs from one end of the appellation to the other, which no other cru of the region can claim, and the soils above it are thin, acid and fast-draining, holding the vines to small crops. Carignan, Grenache, Syrah and Mourvedre carry the reds, and the rock is the first word every grower there reaches for."},
{"id": "c-hob8ozbh", "cat": "Southern France", "q": "Since 2005 a Saint-Chinian label may carry one of two village names, both earned in the schist north of the appellation. Which pair?", "opts": ["Vieussan and Pierrerue", "Assignan and Creissan", "Berlou and Roquebrun", "Cessenon and Cebazan"], "a": 2, "exp": "Both villages lie in the hill country toward the Orb where the appellation runs onto schist, and both subzones are for red wine held to stricter rules than plain Saint-Chinian. The southern half of the appellation sits on limestone and clay and earns no village name, which is the split the two names exist to mark."},
{"id": "c-m7qpvaq1", "cat": "Southern France", "q": "A hilltop village of the Minervois earned in 1999 a distinction no Languedoc village had ever held. Which distinction?", "opts": ["It alone lies in the Aude, while the rest of the Minervois is Herault", "It was the first village raised to a cru of its own", "Its decree was the first in France to require hand harvesting", "It is the only commune of the Minervois permitted to bottle rose"], "a": 1, "exp": "The promotion came in 1999 as Minervois-La-Liviniere, and the pattern it set, a tighter boundary, lower yields and a village name after the appellation, is the one every later cru has copied. The commune lies on the Petit Causse on the Herault side of the appellation, whose larger share is in the Aude."},
{"id": "c-2f45qwbd", "cat": "Southern France", "q": "Old bush-vine Carignan is not merely tolerated but required, at a minimum of thirty percent of the blend, in a cru created in 2005 inside the Languedoc's largest appellation. Name the cru.", "sa": 1, "accept": ["corbieres boutenac", "boutenac", "corbieres boutenac aoc", "the corbieres boutenac cru", "boutenac cru"], "ans": "Corbieres-Boutenac", "exp": "The rule is a floor in both vineyard and vat: Carignan must hold at least thirty percent of the plantings and of the blend, Carignan with Grenache and Mourvedre must together make at least seventy percent, and no single variety may pass eighty. The low pebbled hills of the zone carry some of the Midi's oldest bush vines, which is precisely what the cru was drawn to keep in the ground."},
{"id": "c-ntl8ustz", "cat": "Southern France", "q": "Two separate blocks of vines, kilometres apart, share the single name Fitou. What occupies the ground between the seaside zone and the high one?", "opts": ["A military zone closed to farming since the war", "A corridor of Corbieres between the two", "The salt lagoon of Leucate", "The city of Narbonne and its suburbs"], "a": 1, "exp": "The seaside parcels lie on clay and limestone by the lagoons at Fitou, La Palme and Leucate, while the high parcels sit under Mont Tauch around Tuchan and Paziols, and the hills between the two belong to Corbieres. One name covers two genuinely different wines, which is why serious producers say which zone a bottling came from."},
{"id": "c-atfvwr6g", "cat": "Southern France", "q": "Decades before its neighbours were promoted, one appellation for red wine was decreed in 1948, the first in the Languedoc. Name it.", "sa": 1, "accept": ["fitou", "fitou aoc", "aoc fitou", "the fitou appellation"], "ans": "Fitou", "exp": "The decree came when most of the Midi still sold anonymous bulk wine, and Carignan with Grenache remains the base of the blend. The fortified Muscats of the coast hold older decrees still, which is why the claim is worded for red wine rather than for the appellation system entire."},
{"id": "c-szi8p0gt", "cat": "Southern France", "q": "Facing the oyster beds of the Etang de Thau grows a white-only appellation whose grape's name is said to mean it stings the lip. Name it.", "sa": 1, "accept": ["picpoul de pinet", "piquepoul de pinet", "picpoul de pinet aoc", "the picpoul de pinet appellation"], "ans": "Picpoul de Pinet", "exp": "Piquepoul Blanc holds sharp acidity at full ripeness beside a warm lagoon, which is exactly what a wine poured with raw shellfish needs, and the appellation stood on its own from 2013 after years as a named white within the regional AOC. The producers even share a tall green bottle, a rare case of the Languedoc building one recognisable package."},
{"id": "c-ui2toxt0", "cat": "Southern France", "q": "High in the cool upper valley of the Aude, the still whites of Limoux obey a cellar rule almost no other French appellation writes into law. Which rule?", "opts": ["A compulsory year on gross lees in tank before any racking", "Bottling is allowed only in the squat regional flask", "Fermentation of the whites must take place in oak barrels", "Malolactic conversion is forbidden in every colour and style"], "a": 2, "exp": "The whites must be fermented and raised in oak, a demand written into the decree rather than left to the house, and the cool upper valley gives fruit with the acidity to carry it. Chardonnay leads most cuvees with Chenin Blanc and the old local grape beside them, and the results taste nearer to Burgundy than to the plain below."},
{"id": "c-pv6cu3s0", "cat": "Southern France", "q": "White down on the underside of its leaves gave the grape of Blanquette de Limoux a local nickname, and the nickname became the wine's name. Which variety is it?", "sa": 1, "accept": ["mauzac", "mauzac blanc", "the mauzac grape", "the grape mauzac", "the mauzac variety", "it is mauzac", "it s mauzac"], "ans": "Mauzac", "ex": 1, "exp": "The word is blanquette, the Occitan for that pale felting, and the sparkling wine of Limoux still rests on the variety. Its flavour runs to bruised apple and fresh-cut hay, and outside the upper Aude and a pocket at Gaillac it has nearly disappeared."},
{"id": "c-1jql7p1g", "cat": "Southern France", "q": "A ledger of 1531 from a Benedictine abbey in the hills above Limoux records white wine taking a sparkle of its own accord, a century before Champagne's earliest claim. Name the abbey.", "sa": 1, "accept": ["saint hilaire", "st hilaire", "abbey of saint hilaire", "saint hilaire abbey", "the abbey of st hilaire"], "ans": "Saint-Hilaire", "exp": "The monks had bottled before the ferment was truly finished, and the wine woke with the spring warmth and sparkled. Limoux has dined out on the date ever since, and its Blanquette still includes a bottling made the old way, finishing its single fermentation in the bottle."},
{"id": "c-grpch7ud", "cat": "Southern France", "q": "No red leaves a Bandol cellar young; the decree sees to it. What must the wine do first?", "opts": ["Spend eighteen months in wooden casks", "Pass a second winter on its lees in tank", "Rest three full years in bottle", "Serve thirty months in new oak barriques"], "a": 0, "exp": "The wood is usually the big old foudre rather than the new barrique, and the rule exists because Mourvedre is harsh, dark and reductive in its youth and needs slow air to open. Rose and white run under no such clock, which is why the pink is poured by Easter while the red of the same harvest is still asleep."},
{"id": "c-5k14bkyk", "cat": "Southern France", "q": "Whatever else goes into the vat, a Bandol red is anchored to Mourvedre by law. Give the minimum share of the blend the decree reserves for it.", "sa": 1, "accept": ["fifty percent", "50 percent", "50%", "fifty per cent", "50 per cent", "half", "one half", "at least half", "at least fifty percent", "at least 50 percent", "at least 50%", "a minimum of fifty percent", "a minimum of 50 percent", "minimum 50 percent", "minimum fifty percent", "50 percent minimum", "fifty percent minimum", "50% minimum", "half the blend", "at least half the blend", "half of the blend", "fifty percent of the blend", "50 percent of the blend", "50% of the blend", "half mourvedre", "at least half mourvedre", "fifty percent mourvedre", "50 percent mourvedre", "50% mourvedre", "50", "fifty", "50 %", "at least 50 per cent", "50 per cent minimum", "at least fifty per cent", "fifty per cent minimum", "a minimum of half", "half minimum"], "ans": "Fifty percent", "ex": 1, "exp": "The floor is half the blend, and serious estates run far past it toward the ceiling the decree also sets. Grenache and Cinsault fill the balance, and the requirement is why Bandol tastes like no other Provencal red: dark, peppery, slow to open and built to age for decades."},
{"id": "c-06cpucs6", "cat": "Southern France", "q": "Under a great rust-red sea cliff east of Marseille, one small port appellation sells most of its wine as white, from Marsanne and Clairette, while its neighbours live on pink. Name it.", "sa": 1, "accept": ["cassis", "cassis aoc", "aoc cassis", "the cassis appellation"], "ans": "Cassis", "exp": "The cliff is Cap Canaille, the highest sea cliff in France, and the terraces beneath it now compete with holiday houses for every square metre. Marsanne this far south is an oddity, the appellation drinks its own crop with the port's sea urchins and bouillabaisse, and the rose economy of the rest of the coast has never tempted it."},
{"id": "c-wzvf26a2", "cat": "Southern France", "q": "Pine woods ring a few dozen hectares of cool north-facing limestone just outside Aix-en-Provence, and one estate has stood for nearly the whole appellation for a century. Name the appellation.", "sa": 1, "accept": ["palette", "palette aoc", "aoc palette", "the palette appellation"], "ans": "Palette", "exp": "Chateau Simone long stood for nearly the whole appellation, still farms about half the delimited ground, and keeps alive dozens of old permitted varieties alongside Grenache, Mourvedre and Clairette. The limestone amphitheatre faces north under pine forest, so the wines come out fresher and stranger than the latitude promises, and they age remarkably."},
{"id": "c-bib6prhv", "cat": "Southern France", "q": "Inside the city limits of Nice, vine terraces climbing toward 300 metres carry Braquet and Folle Noire, grapes hardly grown anywhere else in France. Name the appellation.", "sa": 1, "accept": ["bellet", "bellet aoc", "aoc bellet", "the bellet appellation", "vin de bellet"], "ans": "Bellet", "exp": "The terraces hang above the Var valley at the back of the city, high enough that the wines stay light and perfumed through a Riviera summer. Braquet makes a pale, strawberry-scented rose and Folle Noire a firm, dark red, Rolle carries the whites, and nearly all of it is drunk in the restaurants of Nice itself."},
{"id": "c-it3pllyk", "cat": "Southern France", "q": "Merlot and Chardonnay with the grape named on the front label built the Midi's export revival. What does IGP Pays d'Oc offer that the appellations of the hills do not?", "opts": ["Freedom from any yield limit at all", "The right to buy finished wine from anywhere in France and blend it in", "An exemption from every analysis and tasting control", "Varietal labels, and grapes the appellation decrees shut out"], "a": 3, "exp": "The IGP is where varietal labelling and the international varieties live: Chardonnay has an appellation home at Limoux, while Merlot and Cabernet reach the appellation map only in the Atlantic-facing blends of Cabardes and Malepere, so a wine sold on its grape name needs the IGP either way. Nearly every other appellation works from a fixed Mediterranean variety list, and one region runs two wine economies side by side."},
{"id": "c-31us2hig", "cat": "Southern France", "q": "Down where the Pyrenees drop into the sea, Grenache fermented dry rather than muted goes out as Collioure, once a red alone. Which colours may the label claim today?", "opts": ["Red, rose or white alike", "Red or rose, but never white", "Red or white, but never rose", "Red only, as at the start"], "a": 0, "exp": "The red dates from 1971, the rose followed, and the white joined the decree in 2002, built on Grenache Blanc and Gris. The vineyard is the same terraced schist the sweet wine is drawn from, and a grower decides vat by vat whether to ferment dry or to mute, so one terrace can end the year under either name."},
{"id": "c-38h53dq3", "cat": "Spain", "q": "Selling in bulk to a bottler outside the denomination keeps that wine out of Spain's highest tier for good. Which requirement shuts that door?", "opts": ["Wine at the qualified tier may be sold only inside Spain", "Wine at the qualified tier must age two years before release", "Wine at the qualified tier must be bottled inside the delimited zone", "Wine at the qualified tier must be pressed within a day of picking"], "a": 2, "exp": "Bottling at origin is the point of the rung: once a tanker leaves the zone the regulating body has no way of knowing what reaches the glass, so the qualified tier simply refuses to let it go. Wine may still change hands in bulk between registered bodegas inside the boundary, which is how growers and cooperatives supply the ageing houses, but the last stop before the cork has to be a registered cellar in the zone. The condition falls hardest on houses whose business was built on selling wine by the litre to a bottler somewhere else, which is much of why so few denominations have ever applied."},
{"id": "c-qmj943pv", "cat": "Spain", "q": "A back label carries the mark of Grandes Pagos de Espana, and a guest reads it as a rank above DO. What is it really?", "opts": ["The top rung of the national quality ladder", "A seal issued by each denomination's regulating body after a compulsory tasting of every lot", "A private association of estates, admitted by its own members", "A denomination covering single estates in Castilla-La Mancha"], "a": 2, "exp": "Nothing in Spanish wine law mentions it; the estates set their own standards and vote on who joins, which is a guild rather than a rank. It is worth knowing precisely because the wording sits so close to the legal single-estate category that a guest cannot be expected to tell them apart."},
{"id": "c-uolx1t26", "cat": "Spain", "q": "An estate already holding Spain's single-property denomination happens to lie inside the boundary of a qualified region, and its category picks up an extra word. Give the full name.", "sa": 1, "accept": ["vino de pago calificado", "pago calificado", "vinos de pago calificado", "denominacion de pago calificado", "vino de pago calificado dop", "denominacion de origen de pago calificado"], "ans": "Vino de Pago Calificado", "ex": 1, "exp": "The law provides for it directly: a pago sitting within a qualified denomination, and meeting that denomination's requirements as well as its own, takes the longer name. It is the only place in the Spanish system where two categories are stacked on one bottle, and there are barely a handful of estates it can apply to at all."},
{"id": "c-cjhh4dgy", "cat": "Spain", "q": "Three new rungs went into Rioja's rulebook in 2017, ranking ground instead of counting months in cask. Which set of names is right?", "opts": ["Vino de Pago, Vino de Villa and Vina Clasificada", "Crianza de Zona, Reserva de Municipio and Vinedo Historico", "Vino de Paraje, Vino de Pueblo and Gran Vinedo", "Vino de Zona, Vino de Municipio and Vinedo Singular"], "a": 3, "exp": "The ladder narrows from one of the three zones, to a named town, to a single plot, and it runs alongside the ageing words rather than replacing them, so a bottle can carry a village name and Reserva at once. It was a deliberate answer to the charge that Rioja ranked cellars and not vineyards, and it borrows its shape openly from Burgundy."},
{"id": "c-782bqhfm", "cat": "Spain", "q": "A white Rioja lists Tempranillo Blanco on its back label, and the guest assumes a research station bred it. Where did the variety actually come from?", "opts": ["A crossing of Tempranillo and Viura made at a Logrono research station", "A Bordeaux white brought south during the phylloxera years", "An old white recovered from abandoned plots and identified by DNA", "A single mutated shoot found on a Tempranillo vine in a Rioja vineyard"], "a": 3, "exp": "A grower found one arm of an ordinary black Tempranillo bearing white berries, and the shoot was propagated, tested and eventually written into the rulebook. Rioja authorised it in 2007 in a batch of nine varieties that took in Maturana Blanca and Turruntes alongside Chardonnay, Sauvignon Blanc and Verdejo, so the same reform bought native identity and international insurance at one stroke."},
{"id": "c-seybmmvw", "cat": "Spain", "q": "Fruit off a young plot cannot go into Rioja's single-vineyard bottling however good the wine turns out. How old must the vines be?", "sa": 1, "accept": ["thirty five years", "35 years", "35", "thirty five", "at least thirty five years", "at least 35 years", "minimum thirty five years", "minimum 35 years", "thirty five years old", "35 years old", "at least 35 years old", "thirty five years of age", "vines of thirty five years", "the vines must be thirty five years old", "a minimum of thirty five years", "a minimum of 35 years", "at least thirty five years old", "minimum thirty five years old", "minimum 35 years old", "vines at least 35 years old", "vines at least thirty five years old", "a minimum of 35 years old", "a minimum of thirty five years old", "35 years or more", "thirty five years or more"], "ans": "Thirty-five years", "ex": 1, "exp": "The tier also demands hand harvesting, a yield well below the general limit, and a pass in two separate tastings before the back label is released. Age alone was never going to be enough on its own, because a mediocre old plot is easy to find, but it is the condition that cannot be met by simply farming better next year."},
{"id": "c-c436rybo", "cat": "Spain", "q": "Rioja lets a label name a zone only when the fruit comes wholly from it, and the cellar steps must happen inside that same zone as well. Name the one that comes first.", "sa": 1, "accept": ["vinification", "vinified", "winemaking", "fermentation", "fermented", "vinifying", "fermenting", "making the wine", "wine making", "vinification in the zone", "fermentation in the zone", "winemaking in the zone", "vinified in the zone", "fermented in the zone", "made in the zone", "vinified there", "fermented there", "made there", "the wine must be vinified there", "the wine must be vinified in the zone", "it must be vinified in the zone", "the wine has to be made in the zone", "the wine must be made in the zone", "it must be made in the zone", "must be made in the zone"], "ans": "Vinification", "ex": 1, "exp": "A winery outside the boundary cannot print the zone even if every grape came from inside it, which stops a name being attached to fruit trucked anywhere convenient. Vinification is only the first step the rule catches, since the ageing and the bottling have to happen inside the zone as well. That is why the zone names took so long to appear on labels at all, plenty of established bodegas drawing fruit from more than one of the three."},
{"id": "c-vp3i1cqe", "cat": "Spain", "q": "Whole bunches go uncrushed into an open stone lagar in an Alavesa village, and the wine is sold off before the next vintage comes in. What is a wine made that way called?", "sa": 1, "accept": ["cosechero", "vino de cosechero", "cosecheros", "cosechero wine", "a cosechero from rioja alavesa"], "ans": "Cosechero", "exp": "The bunches ferment under their own weight, partly inside the intact berries, and the wine goes into bottle purple, low in tannin and meant for the winter. It is the oldest commercial style in Rioja and it survived the whole barrel-ageing era in the villages, which is why it turns up in Alavesa bars and almost nowhere on an export list."},
{"id": "c-mzv8rpjr", "cat": "Spain", "q": "A Spanish white has spent four years ageing, six months of that in barrel. Which of the ladder's words may the bodega print?", "opts": ["None of them, the ladder having been written for red wine alone", "Gran Reserva", "Crianza, because only six of the forty-eight months were spent in wood", "Reserva, that word being the highest a white may reach"], "a": 1, "exp": "The white and rosado timetable is shorter than the red one at every rung, and its wood requirement is much lighter: four years in all with six months in cask carries the top word. A red asking for the same word needs five years, and far more of them in oak, which is why a white Gran Reserva costs a fraction of what its name suggests."},
{"id": "c-deqk748m", "cat": "Spain", "q": "Spain's national rulebook asks a red Gran Reserva for sixty months of ageing in all, and fixes a floor for the share of it that must pass in oak. Give that floor.", "sa": 1, "accept": ["eighteen months", "18 months", "18", "eighteen", "at least eighteen months", "at least 18 months", "minimum eighteen months", "minimum 18 months", "a minimum of eighteen months", "a minimum of 18 months", "eighteen months in oak", "18 months in oak", "eighteen months in cask", "18 months in cask", "eighteen months in barrel", "18 months in barrel", "at least eighteen months in oak", "at least 18 months in oak", "at least eighteen months in cask", "at least 18 months in cask", "eighteen months of oak", "18 months of oak", "a year and a half", "eighteen months or more", "18 months or more"], "ans": "Eighteen months", "ex": 1, "exp": "Sixty months in all, at least eighteen of them in an oak cask, is the whole of what the national text asks of a red at the top rung. A denomination may set a harder rule for its own producers and the serious ones have, so the word compares cleanly only inside a single rulebook: two bottles both reading Gran Reserva can differ by a year or more of wood. What is being measured either way is elapsed time and nothing else, which is why the rung says nothing at all about where the fruit grew."},
{"id": "c-bojgndbi", "cat": "Spain", "q": "Spain's ageing words name two places and no third, so a bodega that leaves its Reserva a year in stainless steel gains nothing by it. Which two places?", "sa": 1, "accept": ["in cask and in bottle", "in cask and bottle", "cask and bottle", "in cask and in glass", "in cask and glass", "cask and glass", "in barrel and in bottle", "in barrel and bottle", "barrel and bottle", "in barrel and in glass", "in barrel and glass", "barrel and glass", "in oak and in bottle", "in oak and bottle", "oak and bottle", "in oak and in glass", "in oak and glass", "oak and glass", "in wood and in bottle", "in wood and bottle", "wood and bottle", "in wood and in glass", "in wood and glass", "wood and glass", "in bottle and in cask", "in bottle and cask", "bottle and cask", "in bottle and in barrel", "in bottle and barrel", "bottle and barrel", "in bottle and in oak", "in bottle and oak", "bottle and oak", "in bottle and in wood", "in bottle and wood", "bottle and wood", "in glass and in cask", "in glass and cask", "glass and cask", "in glass and in barrel", "in glass and barrel", "glass and barrel", "in glass and in oak", "in glass and oak", "glass and oak", "in glass and in wood", "in glass and wood", "glass and wood", "casks and bottles", "in casks and in bottles", "barrels and bottles", "in barrels and in bottles", "bottles and casks", "bottles and barrels", "both cask and bottle", "both barrel and bottle", "both oak and bottle", "ageing in cask and in bottle", "aging in cask and in bottle", "ageing in cask and bottle", "aging in cask and bottle", "cask and bottle ageing", "cask and bottle aging", "barrel and bottle ageing", "barrel and bottle aging", "cask and bottle only", "in cask and in bottle only", "cask and bottle time", "time in cask and bottle", "cask ageing and bottle ageing", "cask aging and bottle aging"], "ans": "In cask and in bottle", "ex": 1, "exp": "Both clocks run at once inside a single total, so a rule reading thirty-six months with twelve in cask leaves the remainder to be served in glass. Steel is named nowhere in the definitions, so a bodega holding stock in tank earns neither cask time nor bottle time towards Reserva or Gran Reserva. Crianza is the one loose thread, its definition fixing the total and the cask floor but never saying where the balance must sit, so at that rung alone the months out of the barrel may pass in tank."},
{"id": "c-d6b9ld31", "cat": "Spain", "q": "Reserva asks less of a white than of a red, a full year less in fact. Give the white's total under the national rule.", "sa": 1, "accept": ["twenty four months", "24 months", "24", "twenty four", "two years", "at least twenty four months", "at least 24 months", "at least two years", "minimum twenty four months", "minimum 24 months", "minimum two years", "twenty four months in total", "24 months in total", "two years in total", "twenty four months of ageing", "24 months of ageing", "a minimum of twenty four months", "a minimum of 24 months", "a minimum of two years", "twenty four months total", "24 months total", "two years total"], "ans": "Twenty-four months", "ex": 1, "exp": "Twenty-four months for a white or rosado against thirty-six for a red, and the white needs only six of them in cask. The gap runs the whole length of the ladder, so every one of the three words means something different depending on the colour of what is in the bottle."},
{"id": "c-pae5s8z1", "cat": "Spain", "q": "Old plots around Toro carry untrellised bush vines set very wide apart and never watered. Which constraint dictated that layout?", "opts": ["A denomination rule capping the vines that may be registered on a hectare", "The shallow water table, which every root reaches within a metre of the surface", "The risk of spring frost, which settles more heavily in a trellised canopy", "The low rainfall, which leaves each vine a wide patch to itself"], "a": 3, "exp": "Toro takes little more than a third of a metre of rain in a year, so the vineyard is spaced to the water rather than to the tractor. The same arithmetic explains the goblet: a low free-standing head shades its own fruit and needs no wire, posts and wire being an expense that pays only where there is enough water to grow a canopy worth training."},
{"id": "c-4hy31gcr", "cat": "Spain", "q": "Pale rosado drawn from black and white grapes picked and fermented together made one Castilian denomination's name long before its reds did. Which one?", "opts": ["Cigales", "Arlanza", "Ribera del Duero", "Tierra de Leon"], "a": 0, "exp": "The old field blend was co-fermented rather than blended afterwards, which gives a paler and more savoury wine than a modern rosado bled off a red vat. Cigales sits between Ribera del Duero and Toro on the Pisuerga, and its reds have only lately caught up with the pink wine that carried the name for centuries."},
{"id": "c-lalvjliu", "cat": "Spain", "q": "Putting Verdejo on a Rueda label commits a bodega to more of the grape than the denomination name alone does. Give the minimum a varietal label demands.", "sa": 1, "accept": ["eighty five percent verdejo", "85% verdejo", "85 percent verdejo", "eighty five percent", "85%", "85 percent", "85", "eighty five", "eighty five per cent", "85 per cent", "eighty five per cent verdejo", "85 per cent verdejo", "at least eighty five percent", "at least 85 percent", "at least 85%", "minimum 85%", "minimum eighty five percent", "at least eighty five percent verdejo", "at least 85% verdejo", "a minimum of 85 percent verdejo", "a minimum of eighty five percent verdejo", "a minimum of 85%", "a minimum of eighty five percent", "minimum eighty five percent verdejo", "minimum 85 percent verdejo", "85 percent of the blend"], "ans": "Eighty-five percent Verdejo", "ex": 1, "exp": "Plain Rueda needs half the blend to be Verdejo and the rest may be Viura or another permitted white; naming the grape lifts the floor. The same figure governs a Rueda labelled Sauvignon, so the two claims on a shelf are stronger than they look and the unnamed bottle is the one to ask about."},
{"id": "c-6pdk121a", "cat": "Spain", "q": "White vines are scattered through the oldest Ribera del Duero plantings, and the denomination now authorises a white wine from the local one. Name that variety.", "sa": 1, "accept": ["albillo mayor", "albillo", "albillo mayor grape", "the albillo mayor variety", "blanco albillo mayor"], "ans": "Albillo Mayor", "ex": 1, "exp": "It was interplanted among the black vines for centuries and a little of it still finds its way into the reds, softening them without lifting the colour. Albillo Real, grown around Madrid, is a different variety altogether despite the shared first name, and the confusion is exactly why the rulebook spells out which Albillo it means."},
{"id": "c-nuhfpyh7", "cat": "Spain", "q": "Downstream of Toro the Duero cuts a granite gorge along the Portuguese border, and the denomination there is built on Juan Garcia. Name it.", "sa": 1, "accept": ["arribes", "do arribes", "arribes del duero", "the arribes denomination"], "ans": "Arribes", "exp": "The gorge shelters terraces that would be unworkable anywhere colder, and Juan Garcia gives a pale, high-toned red closer to a Galician wine than to anything in Castile. Port country begins a short way downstream, where the same gorge carries on into Portugal, so the hard rock and the vertiginous terracing are of a piece with what follows."},
{"id": "c-whnto8tr", "cat": "Spain", "q": "Priorat built a ladder of its own climbing from village wine through a named site to a classified vineyard. What stands at the very top of it?", "opts": ["Gran Vinya Classificada", "Paratge Qualificat", "Vinya Historica", "Cru Superior"], "a": 0, "exp": "The scheme ranks ground rather than producers. It is the paratge rung that the rulebook itself names and maps, several hundred of them alongside the named villages, while the two classified rungs above are awarded plot by plot on application, against a long record of single-vineyard bottling and a lasting hold on the land, which is why so few of them exist. Village wine asks that the fruit come wholly from the village named but does not oblige the bottler to have farmed it, so the estate condition belongs to the classified rungs rather than to the whole ladder."},
{"id": "c-qfpyy8hr", "cat": "Spain", "q": "A downy-leaved mutation of Garnacha holds its acidity better in heat, and the Catalan rulebooks list it separately from its parent. What is it called?", "sa": 1, "accept": ["garnatxa peluda", "garnacha peluda", "lledoner pelut", "hairy grenache", "garnatxa peluda hairy grenache"], "ans": "Garnatxa Peluda", "exp": "The underside of the leaf is felted with fine hairs, which is where the name comes from, and growers keep it on the hottest and stoniest parcels because it ripens more slowly than ordinary Garnacha. It is permitted across the Catalan denominations and is a fair share of the old-vine plantings a buyer is actually paying for when a label says Garnacha."},
{"id": "c-gytto2jw", "cat": "Spain", "q": "In Alella, north of Barcelona, the local white goes by Pansa Blanca. Which widely planted Catalan variety is that?", "sa": 1, "accept": ["xarel lo", "xarello", "xarel lo pansa blanca", "pansa blanca xarel lo", "xarel lo grape", "the xarel lo variety", "xarel lo blanc", "xarel lo blanca", "xarel lo also called pansa blanca"], "ans": "Xarel-lo", "ex": 1, "exp": "One vine, two names, and the Alella version is the older of them. Xarel-lo is the most oxidation-resistant of the traditional Catalan whites, which is why it carries the body in a sparkling blend and why it is the one of them most often bottled on its own as a still wine. Watch the pink-skinned Xarel-lo Vermell, a separate variety that Alella calls Pansa Rosada, because the two Pansas are as easy to confuse as the two names of this one."},
{"id": "c-9ps3vyje", "cat": "Spain", "q": "Growers took Bierzo's red for a relative of Cabernet Franc until DNA profiling settled the question. What did the profiling show?", "opts": ["It is a colour mutation of Godello, the white grown on the same slopes", "It is the same variety as Portugal's Jaen", "It is identical to Galicia's Brancellao under a Leonese name", "It is a natural crossing of Tempranillo and Garnacha from the Middle Ages"], "a": 1, "exp": "The Cabernet Franc idea came from the perfume, all violet and graphite, rather than from anything in the vine, and it was repeated in print for decades. Jaen is grown in the Dao, across the mountains from Bierzo, and the match tells you the variety crossed the border long before anyone was recording what they planted."},
{"id": "c-vrqrmp6q", "cat": "Spain", "q": "East on the Leon plateau a thick-skinned black grape gives deeply coloured rosados, made by dropping whole bunches into the fermenting must. Name the variety.", "sa": 1, "accept": ["prieto picudo", "prieto picudo grape", "the prieto picudo variety", "prieto picudo tinto", "the black prieto picudo"], "ans": "Prieto Picudo", "ex": 1, "exp": "The technique is called madreo, and the added bunches restart the ferment and raise a light prickle that the wine keeps into the bottle. The variety takes its name from its dark, pointed berries, its bunches are unusually compact, and it is grown seriously almost nowhere outside the province. A white mutation of it exists and is a different grape, so the rulebooks name the black one in full."},
{"id": "c-zlo7e9pm", "cat": "Spain", "q": "One Galician denomination lies inland against the Portuguese border in a sheltered valley, and it is the warmest and driest of the five. Which?", "opts": ["Monterrei", "Rias Baixas", "Ribeira Sacra", "Ribeiro"], "a": 0, "exp": "The valley of the Tamega sits in a rain shadow, so Monterrei ripens Godello and Treixadura with far less anxiety about rot than the coast has. It is the least exported of the five and the one a Galician list is least likely to carry, which is exactly why it is worth asking about."},
{"id": "c-j64y21pw", "cat": "Spain", "q": "Facing Portugal across the mouth of the Mino, one Rias Baixas subzone traditionally blends Loureira into its Albarino. Name the subzone.", "sa": 1, "accept": ["o rosal", "rosal", "the o rosal subzone", "el rosal"], "ans": "O Rosal", "exp": "The blend gives a more floral and slightly softer wine than the pure Albarino of the northern subzones, and the terraces there run down to the river rather than to the open Atlantic. Condado do Tea, further upstream, is the warmest of the subzones and Val do Salnes on the coast is the coolest, so the appellation spans a real climatic range for so small a place."},
{"id": "c-f5pw6pll", "cat": "Spain", "q": "Inland along the Avia and the Mino, the Ribeiro leans on a later-ripening native that gives more flesh and less bite than Albarino. Name it.", "sa": 1, "accept": ["treixadura", "trajadura", "treixadura grape", "the treixadura variety"], "ans": "Treixadura", "exp": "It buds and ripens late, needs a warmer inland site than the coast can offer, and gives a broader wine usually blended with Godello, Loureira or Torrontes. In northern Portugal the same vine is Trajadura and goes into Vinho Verde for exactly the same reason: weight."},
{"id": "c-5a4c7iec", "cat": "Spain", "q": "Printing Albarino on the front of a Rias Baixas bottle triggers a stricter rule than leaving it off. How much of the grape must the wine then hold?", "sa": 1, "accept": ["one hundred percent albarino", "100% albarino", "100 percent albarino", "one hundred percent", "100%", "100 percent", "100", "all of it", "one hundred per cent", "100 per cent", "one hundred per cent albarino", "100 per cent albarino", "entirely albarino", "wholly albarino", "all albarino", "it must be entirely albarino", "it must be 100% albarino", "it must be 100 percent albarino", "it must be one hundred percent albarino", "it has to be 100% albarino", "a minimum of 100 percent albarino"], "ans": "One hundred percent Albarino", "ex": 1, "exp": "Nothing else may be in the blend, which is a stricter varietal rule than most of Europe uses and is why the name on the front is worth reading. A Rias Baixas without the grape name may perfectly well be a blend with Loureira, Caino Blanco or Treixadura, and in the southern subzones it usually is."},
{"id": "c-yd6fm1lr", "cat": "Spain", "q": "A butt fortified past a certain strength loses its veil of flor for good and turns oxidative. Roughly where does that line fall?", "opts": ["Around 18 percent", "Around 22 percent", "Around 15.5 percent", "Around 12 percent, which is the strength of the unfortified base wine"], "a": 2, "exp": "The yeast that forms the veil stops working somewhere close to fifteen and a half, so a cellar master fortifies to just under that line to keep a wine biological and to just over it to kill the flor deliberately. That single decision, taken on a young wine, is what separates the whole Fino family from the whole Oloroso family."},
{"id": "c-9umk85bv", "cat": "Spain", "q": "Wine drawn off the solera row is topped back up from the criadera above it, in an operation the bodegas name after dew. Give that term.", "sa": 1, "accept": ["rocio", "el rocio", "rocio refill", "rociar"], "ans": "Rocio", "exp": "The word is literal: the younger wine is introduced gently, down the wall of the butt or through a tube, so the veil floating on the surface is not torn. Tearing it would let oxygen at the wine underneath, which is the one thing a biological cellar exists to prevent, and it is why the refill is a slow job rather than a pour."},
{"id": "c-3cqgfe4e", "cat": "Spain", "q": "A cellar hand lifts a sample from beneath the veil without tearing it, using a narrow cup on a long whippy handle. Name the tool.", "sa": 1, "accept": ["venencia", "venencia cup", "silver venencia", "sherry venencia", "jerez venencia"], "ans": "Venencia", "ex": 1, "exp": "The Jerez form is a silver cup on a whalebone or cane rod, long enough to reach the bottom of a butt through the bunghole; Sanlucar uses a lighter one cut from a single piece of cane. The person wielding it is the venenciador, and pours from arm's height into a glass held at the waist, which aerates the wine and is a good deal harder than it looks."},
{"id": "c-c79bpmjy", "cat": "Spain", "q": "One outstanding harvest is set aside and aged in its own casks, never refreshed from a younger scale. What is a Sherry made that way called?", "sa": 1, "accept": ["anada", "vino de anada", "anada sherry", "an anada wine", "vintage sherry", "anada wines", "anadas"], "ans": "Anada", "ex": 1, "exp": "It carries a year on the label, which almost nothing else in Jerez does, because a solera has no vintage to declare. The wines were traditionally kept in the coolest corner of the bodega and drawn on to correct a solera in a difficult year, so bottling one at all is a modern decision rather than an old tradition."},
{"id": "c-j6prsibr", "cat": "Spain", "q": "A Fino goes into bottle with little more than a coarse filter, released in small lots in spring and again in autumn. What has the guest gained, and lost?", "opts": ["A higher strength, the wine having been fortified a second time on its way into the bottle", "More of the veil's yeasty, saline intensity, and much less time before the bottle tires", "Residual sweetness, some of the sugar having been left unfermented", "A deeper colour and walnut character, the wine having oxidised for years after its flor died"], "a": 1, "exp": "Cold stabilisation and tight filtration strip fine solids that carry aroma, so leaving them in gives a fuller and more savoury wine that is also markedly less stable. The release dates are not marketing: the veil is thickest in spring and autumn and thinnest in the heat of August, so the wine underneath is genuinely different at different times of year."},
{"id": "c-0uupg0b0", "cat": "Spain", "q": "At the first classification the capataz chalks a mark on the butt, and one mark sends the young wine down the biological road. Name that mark.", "sa": 1, "accept": ["palma", "una palma", "the palma mark"], "ans": "Palma", "ex": 1, "exp": "A stroke like a palm frond says the wine is delicate and clean and will be lightly fortified to keep its veil alive. A raya, a plain horizontal bar, sends a fuller wine the oxidative way, and the crossed mark that gives Palo Cortado its name is a palma struck through, meaning the cellar master changed his mind about it."},
{"id": "c-uqemofok", "cat": "Spain", "q": "Before the letters VORS may go on a label the regulating body verifies the claimed average age in a laboratory rather than from the cellar book. Which test does it use?", "sa": 1, "accept": ["carbon dating", "carbon 14 dating", "radiocarbon dating", "carbon 14", "c14 dating", "radiocarbon analysis", "carbon dating of the wine"], "ans": "Carbon dating", "exp": "Atmospheric nuclear testing left a spike of radiocarbon in everything grown since the 1950s, and the amount left in a wine gives its age directly, which no ledger could prove for a blend that has never been a single vintage. VOS claims an average of twenty years and VORS thirty, and both are checked this way before the seal is granted."},
{"id": "c-9kk7trij", "cat": "Spain", "q": "Zoning came to Cava so that a label could finally say where the fruit grew rather than only how the wine was made. Which is a genuine Cava zone?", "opts": ["Comtats de Barcelona", "Ribera del Cava", "Camp de Tarragona", "Alt Penedes"], "a": 0, "exp": "The denomination was drawn around a production method and a register of approved plots rather than around a boundary, which is how it came to stretch across half the country, and the zones answer the old complaint that followed from it. A buyer can now tell an Ebro valley bottle from a Catalan one, and a zone may be subdivided further so a district can be named as well."},
{"id": "c-hhrisw7m", "cat": "Spain", "q": "Cava's ageing tiers were sorted into two families, the upper one vintage-dated and starting at eighteen months on the lees. Name that upper family.", "sa": 1, "accept": ["cava de guarda superior", "guarda superior", "the guarda superior tier", "guarda superior cava"], "ans": "Cava de Guarda Superior", "ex": 1, "exp": "Reserva, Gran Reserva and the single-plot tier all sit inside it, and every wine in the family must declare its harvest year, which the entry tier below need not. Because the family carries the vintage, a bottle without one is telling a buyer where it sits without ever printing the word."},
{"id": "c-5znp51hu", "cat": "Spain", "q": "The oldest Basque txakoli denomination is named for a fishing town on the Gipuzkoa coast. Name that denomination.", "sa": 1, "accept": ["getariako txakolina", "getaria", "txakoli de getaria", "chacoli de getaria", "getariako txakolina do", "do getariako txakolina", "getaria txakolina", "txakolina de getaria", "getariako"], "ans": "Getariako Txakolina", "ex": 1, "exp": "Recognised at the end of the 1980s, it covers the steep coastal slopes either side of the town and is the most maritime of the three Basque denominations. The others cover Bizkaia around Bilbao and Araba inland in the Ayala valley, sheltered behind the Sierra Salvada but still on the Atlantic side of the watershed, where the wines are riper and a good deal less salty."},
{"id": "c-imxbqecc", "cat": "Spain", "q": "Txakoli is nearly all white, yet the Basque rulebooks also list a black-berried variety for the rare reds and rosados. Name it.", "sa": 1, "accept": ["hondarrabi beltza", "hondarribi beltza", "ondarrabi beltza", "hondarrabi beltza grape", "hondarrabi beltz"], "ans": "Hondarrabi Beltza", "ex": 1, "exp": "Beltza is Basque for black, and the grape is a small share of the plantings; a little is co-fermented with the white in some villages to give the pink wine its colour. Both varieties trail their canopies on high pergolas above the damp ground, which is the same answer to the same problem the Galicians reached on the other end of the same coast."},
{"id": "c-24i3ytdv", "cat": "Sparkling Wine World", "q": "A pet-nat maker wants a gentle two and a half bar in the finished wine rather than a spumante's six. Where is that decision actually made?", "opts": ["On bottling day, in how much unfermented sugar is still in the wine as it goes under the cap", "At disgorgement, where pressure is vented along with the frozen plug of sediment", "In the cellar's temperature, cold storage setting how much carbon dioxide the finished wine holds", "In the liqueur de tirage, by cutting back the sugar and yeast added for the second fermentation"], "a": 0, "exp": "An ancestral wine has one fermentation and nothing is ever added to provoke another, so the only gas it will ever hold comes from whatever sugar the ferment has not yet eaten when the wine goes into glass. Each four grams or so per litre finishes into roughly one further atmosphere, which is why the style sits naturally at modest pressures and often keeps a touch of sweetness: the tail of a chilled ferment rarely eats the bottle dry. There is no tirage liqueur to adjust and frequently no disgorgement either, so the maker's whole control is the timing of that one bottling."},
{"id": "c-cmj9835u", "cat": "Sparkling Wine World", "q": "Two American sparklers stand together: the back of one reads fermented in this bottle, the other only bottle fermented. What is the shorter phrase quietly admitting?", "opts": ["The second fermentation ran in a sealed tank and the wine was bottled under counter-pressure", "Nothing; American labelling treats the phrases as interchangeable", "The wine left the bottle it fermented in, finished in tank and rebottled: the transfer method", "The bubble was injected on the bottling line, as it would be into a soft drink"], "a": 2, "exp": "American convention reserves fermented in THIS bottle for wine sold in the glass it refermented in, while plain bottle fermented covers transfer wine, which took its bubble and its lees character in bottle and was then emptied under pressure, filtered, dosed and refilled in one batch operation. The economics are the point: the whole run is cleaned up in tank instead of being riddled and disgorged a bottle at a time. The label wording is often the only clue a buyer gets."},
{"id": "c-x7wv6kko", "cat": "Sparkling Wine World", "q": "Five years on from a shared disgorging date, a Brut and its Brut Nature sibling taste further apart than a few grams of sugar explain. What has the dosage been doing all that time?", "opts": ["Nothing beyond sweetness; sugar is inert once dissolved, and the gap is the tasters' expectation", "Reacting slowly with what the yeast left behind, steering the dosed wine toward toast and roast", "Feeding a refermentation that has quietly raised the dosed bottle's pressure", "Fermenting out, so the Brut has been drifting toward its sibling's dryness"], "a": 1, "exp": "Dosage sugar is not inert: over years in bottle it takes part in slow browning chemistry with the nitrogen compounds autolysis left in the wine, and that pushes development toward the roasted, toasted register. The undosed wine ages along a leaner, more saline road rather than simply tasting less sweet, which is why houses speak of dosage needing time to marry and why the choice between the two styles is a choice of trajectory, not just of sugar."},
{"id": "c-66uzlo0y", "cat": "Sparkling Wine World", "q": "Spumante on an Italian label is a legal claim about pressure, not a style note, and there is a floor the dissolved gas must clear. Give that floor.", "sa": 1, "accept": ["three bar", "3 bar", "three bars", "3 bars", "three atmospheres", "3 atmospheres", "three atm", "3 atm", "3", "three", "at least 3 bar", "at least three bar", "at least 3 atmospheres", "at least three atmospheres", "3 bar of pressure", "three bar of pressure", "3 atmospheres of pressure", "three atmospheres of pressure", "3 bar overpressure", "three bar overpressure", "above 3 bar", "above three bar", "more than 3 bar", "more than three bar", "over 3 bar", "over three bar", "minimum 3 bar", "minimum three bar", "3 bar minimum", "three bar minimum", "minimum of 3 bar", "minimum of three bar", "min 3 bar", "3 bar of overpressure", "three bar of overpressure", "3 bar or more", "three bar or more", "at least 3 bars", "at least three bars"], "ans": "Three bar", "ex": 1, "exp": "Three bar of overpressure at twenty degrees is where European law draws the line for a fully sparkling wine, with frizzante occupying the band from one to two and a half. The quality-sparkling category that most Cremant and metodo classico wines sit in actually demands slightly more, three and a half, so a wine at three point two can be spumante and still fail that tier. Below one bar the law reads the wine as still, whatever prickle it shows."},
{"id": "c-jt02wiy9", "cat": "Sparkling Wine World", "q": "Under one bar of pressure French law reads a wine as still, yet lists and back labels keep a word for that faint natural prick in the glass. Give the word.", "sa": 1, "accept": ["perlant", "vin perlant", "perlant wine", "perlant style", "perle", "vin perle", "perlant wines"], "ans": "Perlant", "ex": 1, "exp": "Perlant sits below petillant on the old French ladder: petillant carries a real if gentle sparkle in the one to two and a half bar band, while perlant is barely a whisper of gas, the sort a Muscadet bottled on its lees keeps from the winter's fermentation. The word makes no legal promise at all, which is exactly the point: it names a sensation the law has stopped measuring."},
{"id": "c-gbzinc5o", "cat": "Sparkling Wine World", "q": "Months on yeast inside the pressure tank, rather than the usual quick turnaround, give some tank wines a bready depth the process is not famous for. Italians have a name for that slow variant. Give it.", "sa": 1, "accept": ["charmat lungo", "long charmat", "martinotti lungo", "lungo charmat"], "ans": "Charmat lungo", "exp": "The standard tank turnaround is measured in weeks, which is the whole commercial point of the method, so leaving the finished wine on its fermentation lees under pressure for six months or more is a deliberate trade of throughput for texture. Autolysis proceeds in a tank exactly as it does in a bottle, only spread through a far greater volume of wine, so what the long version buys is a rounder mouthfeel and a suggestion of bread rather than the full biscuit of years in glass."},
{"id": "c-rl8kf8my", "cat": "Sparkling Wine World", "q": "Hambledon's 1950s replanting and most English vineyards for the next four decades leaned on German crossings plus one French-bred hybrid hardy enough for the climate. Which hybrid?", "opts": ["Baco Noir", "Seyval Blanc", "Vidal Blanc", "Villard Blanc"], "a": 1, "exp": "Seyval Blanc, a Seyve-Villard cross, carried the acidity and rot resistance a cold wet season demands and made respectable bottle-fermented wine at estates like Breaky Bottom. Its hybrid parentage kept it outside the European quality-wine categories, which is one reason the industry swung so hard to Chardonnay and the Pinots once the warming climate let them ripen."},
{"id": "c-gclpbsr2", "cat": "Sparkling Wine World", "q": "One English county's name has stood since 2022 as a protected wine origin in its own right, the first drawn at county scale. Which county?", "opts": ["Cornwall", "Essex", "Hampshire", "Sussex"], "a": 3, "exp": "The Sussex PDO took seven years from application to grant and binds its users more tightly than the countrywide English designation, including the traditional method for its sparkling wine. The argument it caused was less about the rules than the map: fruit and presses cross the county line constantly, and growers elsewhere have so far preferred the broader name."},
{"id": "c-xew8txq9", "cat": "Sparkling Wine World", "q": "Most of England's vineyard crowds into the southeastern corner, where the Downs run their chalk toward the Channel, and adjoining counties there hold the bulk of it. Name the pair.", "sa": 1, "accept": ["kent and sussex", "sussex and kent", "kent sussex", "sussex kent", "kent and east sussex", "kent and west sussex"], "ans": "Kent and Sussex", "exp": "Kent and Sussex between them hold the largest share of the national vineyard, with Hampshire next and Essex climbing fastest on its warm clay. The chalk gets the attention, but a surprising number of well-regarded sites actually sit on greensand, so the county and the rock are separate claims and a label naming one is not promising the other."},
{"id": "c-wismgajz", "cat": "Sparkling Wine World", "q": "In 1988 a West Sussex estate planted Chardonnay, Pinot Noir and Meunier and nothing else, a bet on the traditional method made while nearly every English vine was a crossing or a hybrid. Name the estate.", "sa": 1, "accept": ["nyetimber", "nyetimber estate", "nyetimber in west sussex"], "ans": "Nyetimber", "exp": "Its first releases in the mid-1990s took national trophies and did more than any argument on paper to turn the industry toward the Champagne varieties. The founding vineyards sit on greensand rather than the chalk the region is celebrated for, a useful correction to the idea that England's case rests on chalk alone, and the name itself belongs to a manor recorded in Domesday."},
{"id": "c-728z2o4i", "cat": "Sparkling Wine World", "q": "Inky, firmly tannic, and yet almost every sparkling Shiraz leaves the cellar with a generous dosage. What is the sugar doing in a wine like that?", "opts": ["Covering under-ripeness, the style being built on fruit picked early and green for acidity", "Cushioning the tannin, which carbon dioxide sharpens beyond what a still red would show", "Raising the pressure, since a sweeter dosage means a livelier mousse", "Deepening the colour, pigment binding to sugar as the bottle ages"], "a": 1, "exp": "Carbonic acid and the scrub of the bubbles both amplify bitterness and astringency, so tannin that reads supple in a still Shiraz turns aggressive under gas, and the dosage is a counterweight rather than a sweet tooth. The serious versions are traditional method from fully ripe, often old-vine fruit with years on lees, and the sugar is calibrated against the tannin exactly as it is against acidity in colder places."},
{"id": "c-08hwfwkt", "cat": "Sparkling Wine World", "q": "The first bottle-fermented sparkling wine South Africa ever put on sale was made in 1971 under an Afrikaans name, and the label is still poured today. Give that name.", "sa": 1, "accept": ["kaapse vonkel", "simonsig kaapse vonkel", "kaapse vonkel from simonsig"], "ans": "Kaapse Vonkel", "exp": "Frans Malan of Simonsig made it from Chenin Blanc in 1971 and sold it from 1973 once its lees ageing was done, years before the Cape had a category to put it in; the phrase means Cape sparkle. The wine later moved over to the Champagne varieties, and when the industry needed its own term for the method two decades on, this bottle stood as the precedent: claim the method, name the Cape."},
{"id": "c-5d2s2gyr", "cat": "Sparkling Wine World", "q": "A Pipers River label begun in the mid-1980s as a Champagne house's Tasmanian joint venture takes its name from the patronymic of Abel Tasman himself. Name the label.", "sa": 1, "accept": ["jansz", "jansz tasmania", "the jansz label", "jansz of tasmania", "jansz sparkling"], "ans": "Jansz", "ex": 1, "exp": "The partner was Louis Roederer, whose venture with Heemskerk was the first serious Champagne investment in Tasmania and settled the question of whether the island could carry the traditional method. The label later passed to the Hill-Smith family and marketed its wine as Methode Tasmanoise, a joke with a point in it: name the place, borrow nothing."},
{"id": "c-jmvrdnl2", "cat": "Sparkling Wine World", "q": "For the better part of a century Australia's festive sparkling red sold under a borrowed French name, retired once place-name protection reached the shelves. What was the style called?", "sa": 1, "accept": ["sparkling burgundy", "australian sparkling burgundy", "sparkling burgundies"], "ans": "Sparkling Burgundy", "exp": "The style dates to the 1890s at Great Western in Victoria, where a Champagne-trained cellar hand put the local red through a second fermentation, and burgundy in that era was British shorthand for any soft red rather than a claim about Pinot Noir. Agreements with Europe struck the borrowed names off Australian labels, so the wine was rebadged sparkling Shiraz, which had been the grape inside all along."},
{"id": "c-4fk385op", "cat": "Sparkling Wine World", "q": "On the Carneros highway stands a copy of an eighteenth-century Champagne residence, built as the public face of one house's American venture. Which house?", "opts": ["Taittinger", "Louis Roederer", "Moet et Chandon", "Piper-Heidsieck"], "a": 0, "exp": "Domaine Carneros, opened at the end of the 1980s, is modelled on the Chateau de la Marquetterie, the Taittinger property near Epernay, and the theatre is deliberate: a visible chateau announces a long commitment in a landscape of sheds. Moet had led the way into California in 1973 with Domaine Chandon at Yountville but kept the architecture Californian, and Piper-Heidsieck's venture ran under the Piper Sonoma name."},
{"id": "c-e0xdtz3u", "cat": "Sparkling Wine World", "q": "Korbel prints California Champagne on its labels to this day, and no American regulator objects. What protects the wording?", "opts": ["A licence from the Champagne trade body, renewed by a royalty on every bottle sold", "American law treats champagne as a common noun that any producer remains free to adopt for a sparkling wine", "A grandfather clause: labels approved before the 2006 accord with Europe keep semi-generic names beside their origin", "The wine is traditional method, and in American usage the word certifies method rather than place"], "a": 2, "exp": "The 2006 agreement froze the semi-generic names rather than abolishing them: no new label may take up champagne, chablis or burgundy, while brands already holding approval carry on, provided the true origin stands beside the borrowed word. That is why the survivors are old California brands, why the class shrinks by attrition, and why no new producer can ever join it."},
{"id": "c-93orihv9", "cat": "Sparkling Wine World", "q": "A grower family from Bethon in Champagne planted Chardonnay and Pinot Noir at thirteen hundred metres in the high desert of an unlikely American state. Which state?", "sa": 1, "accept": ["new mexico", "the state of new mexico", "new mexico usa"], "ans": "New Mexico", "exp": "Gilbert Gruet planted near Truth or Consequences in 1984, on cheap land whose altitude does what latitude will not: desert nights cold enough to hold acidity through a fierce summer. The family's Albuquerque winery built its reputation on traditional-method Brut priced against far grander addresses, and the lesson travels: a sparkling base is a question of site arithmetic, not postcode."},
{"id": "c-x0t936gk", "cat": "Sparkling Wine World", "q": "Its Champagne parent transplanted the house rules to Anderson Valley whole: every grape from its own ranches, and reserve wines raised in oak for the blend. Name the California estate.", "sa": 1, "accept": ["roederer estate", "roederer estate in anderson valley", "roederer estate california"], "ans": "Roederer Estate", "exp": "Roederer arrived in 1982, chose fog-cooled Anderson Valley over the safer prestige of Napa, and refused bought fruit from the first vintage. The oak-aged reserve wines are the signature it shares with the parent house, and the vintage prestige bottling, L'Ermitage, made the case that American traditional method could age. The operation reads less like a subsidiary than a second house."},
{"id": "c-r7tozsvu", "cat": "Sparkling Wine World", "q": "Same Canelli grower, same Moscato Bianco: one bottle wears a wire cage and reaches about seven percent alcohol, the other a plain straight cork, a soft prickle and five. Which is which?", "opts": ["The caged bottle is Asti, the corked one Moscato d'Asti", "Both are Moscato d'Asti, bottled at the two pressures the rules allow", "The caged bottle is Moscato d'Asti, the corked one Asti", "The caged bottle is Brachetto d'Acqui, the corked one Moscato d'Asti"], "a": 0, "exp": "The two share a denomination and a grape; the fork is how far the single fermentation is allowed to run. Asti ferments on to full spumante pressure and a couple of points more alcohol, so the closure must be the caged mushroom cork, while Moscato d'Asti is arrested sooner, keeping more sugar and staying below the sparkling threshold, which is why it may seal and pour like a still wine."},
{"id": "c-zjvrjwfx", "cat": "Sparkling Wine World", "q": "Dry Lambrusco and sweet Asti both take their sparkle in tank, yet only one of them ever gets a second fermentation. Which one, and why?", "opts": ["Both referment; sparkle made in tank is a second fermentation by definition", "Neither referments; tank sparkle is dissolved into the wine under pressure rather than fermented", "The Asti: reaching full pressure on grape sugar alone takes a second fermentation on top of the first", "The Lambrusco: a finished dry base wine referments in tank, where Asti is one fermentation stopped partway"], "a": 3, "exp": "Asti's tank run starts from must and simply never finishes, which is where its sweetness and low alcohol come from; there is nothing left over for a second act. Lambrusco is made as an ordinary dry wine first and then set going again in tank with a measured addition, which is why it can finish bone dry at normal strength. One name covers two genuinely different sequences, and each wine has the one it needs."},
{"id": "c-9008dsd0", "cat": "Sparkling Wine World", "q": "One member of the Lambrusco family covers more Emilian vineyard than any other. Name it.", "sa": 1, "accept": ["lambrusco salamino", "salamino", "lambrusco salamino di santa croce", "salamino di santa croce"], "ans": "Lambrusco Salamino", "exp": "The name records its tight, cylindrical bunches, shaped like little salami, which in Emilia counts as affectionate. It anchors the workhorse blends around Reggio and Modena and holds a denomination of its own at Santa Croce, and blenders lean on it for colour and easy fruit rather than for structure."},
{"id": "c-m6jffr6u", "cat": "Sparkling Wine World", "q": "Ripeness shows in one Lambrusco's very name: as harvest nears, its stalks and bunch stems flush red. Name it.", "sa": 1, "accept": ["lambrusco grasparossa", "grasparossa", "lambrusco grasparossa di castelvetro", "grasparossa di castelvetro"], "ans": "Lambrusco Grasparossa", "exp": "Graspa is the local word for the stalk, and the red flush runs through stem and leaf as the fruit comes in. It grows on the foothills south of Modena around Castelvetro and gives the fullest and grippiest wine of the family, the one traditionally poured against the fattest plates on the Emilian table."},
{"id": "c-oemdv4ag", "cat": "Spirits & Cocktails", "q": "A tall swan neck with a bulge at its base sends much of the rising vapour back down into the pot before it ever reaches the condenser. What does that do to the spirit?", "opts": ["Lightens it, because heavy compounds fall back", "Raises its congener load, because the vapour condenses twice over", "Darkens it, because copper is stripped from the neck into the vapour", "Lowers its strength, because alcohol condenses before water does"], "a": 0, "exp": "The effect is called reflux: the heavier compounds condense early, drop back into the pot and are distilled all over again, so the spirit that reaches the condenser is the lighter fraction. It is why a tall narrow still gives a more delicate spirit than a short fat one of the same capacity. Contact with copper rises along with it, which strips sulphur compounds out of the vapour as a bonus."},
{"id": "c-izpra5pq", "cat": "Spirits & Cocktails", "q": "Two linked columns, an analyser fed with wash and a rectifier that returns its condensate to be stripped again, let one apparatus run without ever being emptied. Whose patent of 1830 was that?", "opts": ["Robert Stein", "Aeneas Coffey", "Edouard Adam", "Eugene Charmat"], "a": 1, "exp": "Coffey's design is the ancestor of every continuous still working today, and grain whisky, most vodka and most rum all pass through one. Stein's earlier continuous still was superseded within a couple of years, Adam is remembered for condensing apparatus, and Charmat's name belongs to sparkling wine rather than to spirits."},
{"id": "c-gpazk5aq", "cat": "Spirits & Cocktails", "q": "Neither the first nor the last part of a pot still run is thrown away; what is held back goes into the charge for the following run. What is that returned material called?", "sa": 1, "accept": ["feints", "feints and foreshots", "foreshots and feints", "feints returned to the still", "heads and tails", "foreshots and tails"], "ans": "Feints", "exp": "They are rich in the heavy oily compounds the stillman rejected, and redistilling them recovers the alcohol without letting those compounds into the hearts. A still house wastes very little: even the spent wash goes to cattle feed."},
{"id": "c-f69qg2hl", "cat": "Spirits & Cocktails", "q": "European law stops calling a distillate a spirit drink of its raw material, and calls it ethyl alcohol of agricultural origin instead, once it passes a fixed strength. What strength is that?", "sa": 1, "accept": ["96 percent", "96%", "96 per cent", "ninety six percent", "96 percent abv", "96 abv", "96 percent alcohol", "96 percent alcohol by volume", "at least 96 percent", "96 percent or above", "96", "96% abv", "96% vol", "96 percent vol", "96 percent or more", "above 96 percent", "over 96 percent"], "ans": "96 percent", "ex": 1, "exp": "Above that point the distillate has lost the fingerprint of whatever it was made from, which is why vodka can come from grain, potato or grape and taste of none of them. Whisky rules run the other way and cap distillation below 94.8 percent so the cereal survives into the glass."},
{"id": "c-0qqyjfiu", "cat": "Spirits & Cocktails", "q": "A malt bottled at 43 percent turns cloudy the moment a guest adds a splash of water. Which treatment would have prevented that haze, and is often left out on purpose?", "sa": 1, "accept": ["chill filtration", "chill filtering", "chill filtered", "chillfiltering", "chillfiltration", "chillfiltered", "chill filter", "cold filtration", "cold filtering", "cold filtered", "chill filtration before bottling", "chill filtration at bottling", "chill filtering before bottling"], "ans": "Chill filtration", "ex": 1, "exp": "Long-chain fatty esters drop out of solution when a spirit is chilled or watered below about 46 percent, which is a cosmetic problem and nothing more. Filtering them out at low temperature removes the haze and, many argue, some texture with it, so bottlings at 46 percent and above frequently skip it."},
{"id": "c-uhl3ec8a", "cat": "Spirits & Cocktails", "q": "Wash at around eight percent alcohol goes into the wash still and comes off cloudy at roughly twenty-one percent, ready for a further pass. What is that first distillate called?", "sa": 1, "accept": ["low wines", "low wine", "low wines from the wash still"], "ans": "Low wines", "exp": "Only the second run is cut into heads, hearts and tails; the first is collected whole because there is nothing yet worth separating. Irish pot still whiskey adds a third pass, which is where much of its lighter texture comes from."},
{"id": "c-9lqzvfn4", "cat": "Spirits & Cocktails", "q": "A label reads blended malt Scotch whisky and names no distillery anywhere on it. What is in the bottle?", "opts": ["Malt whiskies from more than one distillery, and no grain", "Malt whisky from one distillery, married from several casks", "Malt and grain whisky drawn from one distillery", "Grain whiskies from several distilleries with a little malt added"], "a": 0, "exp": "Not a drop of grain whisky may go in, and the malt has to come from two distilleries or more. The category was called vatted malt until the Scotch Whisky Regulations settled the naming in 2009. Blended Scotch is the different animal: malt whisky married with grain whisky from a column still, which is what the great majority of Scotch sold in the world is."},
{"id": "c-bjzokv5w", "cat": "Spirits & Cocktails", "q": "Five whisky localities and regions are protected under the Scotch Whisky Regulations, and one of them is a single island rather than a stretch of the mainland. Which?", "opts": ["Jura", "Orkney", "Islay", "Skye"], "a": 2, "exp": "The regulations protect five: Highland, Lowland, Speyside, Campbeltown and Islay. Orkney, Skye, Jura, Mull and Arran all distil, but they sit inside the Highland region rather than standing on their own."},
{"id": "c-wf2uzq9h", "cat": "Spirits & Cocktails", "q": "Thirty distilleries once crowded a single harbour town on the Kintyre peninsula, and its name survives as one of Scotland's protected whisky regions. Name the town.", "sa": 1, "accept": ["campbeltown", "campbelltown", "campbeltown on kintyre", "campbeltown kintyre", "campbeltown scotland", "the town of campbeltown"], "ans": "Campbeltown", "ex": 1, "exp": "The town collapsed as a whisky centre in the 1920s and ran for decades on a couple of working distilleries, but the region was never struck off. What survived there also kept practices that vanished elsewhere, floor malting among them."},
{"id": "c-2pp4gni2", "cat": "Spirits & Cocktails", "q": "Dufftown, Rothes and Craigellachie all sit inside the same protected Scotch whisky region, clustered around one river valley. Name the region.", "sa": 1, "accept": ["speyside", "speyside region", "spey valley"], "ans": "Speyside", "exp": "The Spey and its tributaries drain the whole zone, and those towns are its distilling centres. A Speyside whisky may also be labelled Highland, since the zone sits geographically inside the Highland region, but the reverse is not permitted."},
{"id": "c-zgd0j5o2", "cat": "Spirits & Cocktails", "q": "Peating is quoted in parts per million measured on the malt, and the figure counts one family of compounds picked up from the kiln smoke. Name that family.", "sa": 1, "accept": ["phenols", "phenol", "phenolic compounds", "phenolics", "total phenols", "phenol compounds"], "ans": "Phenols", "ex": 1, "exp": "A good deal of the phenol is lost through fermentation and distillation, so the number on a bag of malt overstates what reaches the glass by a wide margin. Guaiacol and the cresols sit within that family and carry the tar, smoke and iodine notes."},
{"id": "c-u8nkgvhg", "cat": "Spirits & Cocktails", "q": "Oak is not the only cask requirement in the Scotch rules, which also set a limit on the size of the vessel. What is that maximum?", "sa": 1, "accept": ["700 litres", "700 liters", "seven hundred litres", "700 litre", "700 litre casks", "a maximum of 700 litres", "700 litre maximum", "not exceeding 700 litres", "no more than 700 litres", "up to 700 litres", "maximum 700 litres", "700", "seven hundred", "700 l"], "ans": "700 litres", "ex": 1, "exp": "Anything larger falls outside the definition, which rules out the great vats used elsewhere for solera-style ageing. Inside the limit the range is wide, from the 200 litre ex-bourbon barrel through the 250 litre hogshead to the 500 litre sherry butt."},
{"id": "c-trq3a3hj", "cat": "Spirits & Cocktails", "q": "Colour is the one adjustment a Scotch producer may still make in the vat, and a single additive is permitted for it. Name that additive.", "sa": 1, "accept": ["spirit caramel", "caramel", "plain caramel", "e150a", "caramel colouring"], "ans": "Spirit caramel", "exp": "Water and spirit caramel are the only permitted additions after maturation, so a Scotch cannot be sweetened or flavoured the way some other categories legally can. The caramel exists to make batches look alike rather than to add taste, though whether it is genuinely tasteless is argued about at length."},
{"id": "c-b3nam0xb", "cat": "Spirits & Cocktails", "q": "Unmalted barley entered the Irish mash bill in the eighteenth century for a reason that had nothing to do with flavour. What drove it?", "opts": ["A duty levied on malted grain", "An excise ban on triple distillation", "A rule requiring imported corn", "A shortage of peat for kilning"], "a": 0, "exp": "The tax was charged on malt, so distillers cut the mash with raw barley and lowered the bill. What began as tax avoidance became the defining texture of Irish single pot still whiskey, which is creamy and spiced in a way an all-malt mash is not."},
{"id": "c-551to5tv", "cat": "Spirits & Cocktails", "q": "American regulations cap the strength at which bourbon may come off the still, and again the strength at which it may go into the barrel. Which pair of figures is correct?", "opts": ["140 proof off the still and 110 proof into the barrel", "160 proof off the still and 125 proof into the barrel", "125 proof off the still and 160 proof into the barrel", "190 proof off the still and 160 proof into the barrel"], "a": 1, "exp": "That is 80 percent alcohol off the still and 62.5 percent into the wood, with a bottling floor of 80 proof. Entry strength matters because a lower one pulls different compounds out of the oak, which is why some distillers barrel well under the ceiling."},
{"id": "c-90y6l4nw", "cat": "Spirits & Cocktails", "q": "The word straight on an American whiskey label carries an ageing requirement that plain bourbon does not have to meet. How long?", "sa": 1, "accept": ["two years", "2 years", "two years in oak", "at least two years", "two years minimum", "minimum two years", "24 months", "two years old", "two years in wood", "two years in barrel", "two years in new charred oak"], "ans": "Two years", "ex": 1, "exp": "Two years in new charred oak, with corn whiskey the single exception, and if a straight whiskey is younger than four years the label has to state its age. Bourbon itself has no ageing minimum at all, so a spirit is legally bourbon the moment it goes into the barrel."},
{"id": "c-whvr7yhp", "cat": "Spirits & Cocktails", "q": "One American designation demands a single distilling season at one distillery, four years in a federally supervised warehouse, and bottling at exactly 100 proof. Name it.", "sa": 1, "accept": ["bottled in bond", "bonded", "bond", "bottled in bond whiskey", "bonded whiskey", "bottled in bond bourbon", "bonded bourbon", "bottled in bond act"], "ans": "Bottled in Bond", "ex": 1, "exp": "The Bottled-in-Bond Act of 1897 was a consumer protection measure at a time when whiskey was routinely adulterated, and the government put its own supervision behind the label. It is why so many bonded bottlings sit at exactly fifty percent alcohol."},
{"id": "c-dg4xvst1", "cat": "Spirits & Cocktails", "q": "A bottle sold as American blended whiskey may be mostly neutral spirit, but a floor is set for the real whiskey in it. What is that floor?", "sa": 1, "accept": ["twenty percent", "20 percent", "20%", "twenty per cent", "20 per cent", "at least twenty percent", "at least 20 percent", "a fifth", "one fifth", "twenty percent straight whiskey", "20 percent straight whiskey", "20", "twenty", "20% straight whiskey", "20 per cent straight whiskey", "20 percent whiskey", "at least a fifth", "one fifth straight whiskey"], "ans": "Twenty percent", "ex": 1, "exp": "The remaining four fifths may be grain neutral spirit, which is why the category sits well below straight whiskey in both price and character. Canadian blends answer to a different rule and Scotch blends to another again, so the word blended means something different in each country."},
{"id": "c-t922zwef", "cat": "Spirits & Cocktails", "q": "An American spirit built on a mash of at least eighty percent corn may be sold with no wood ageing at all, and if it is aged the barrel must be used or uncharred. Name that category.", "sa": 1, "accept": ["corn whiskey", "corn whisky", "american corn whiskey", "corn whiskey category"], "ans": "Corn whiskey", "ex": 1, "exp": "The uncharred or used barrel is the whole point: new charred oak is what makes bourbon, so this category is deliberately kept away from it and stays close to its raw distillate. Most of it is sold white, and it is the legal descendant of American moonshine."},
{"id": "c-4lnrardb", "cat": "Spirits & Cocktails", "q": "A tier was added to the Cognac ladder in 2018, sitting above XO and carrying a fourteen-year floor. What is it called?", "opts": ["Fine Champagne", "Hors d'Age", "Napoleon", "XXO"], "a": 3, "exp": "The same reform lifted XO itself from six years to ten, which left Napoleon standing on the six-year step XO had vacated. Hors d'Age is treated as equal to XO rather than as a step of its own, so it takes the same ten-year floor, and Fine Champagne describes the crus blended rather than any age at all."},
{"id": "c-0a3udkgt", "cat": "Spirits & Cocktails", "q": "Four grapes carry the Armagnac plantings, and one of them is a hybrid, the only such vine allowed in a French appellation spirit. Which?", "opts": ["Ugni Blanc", "Folle Blanche", "Colombard", "Baco Blanc"], "a": 3, "exp": "Baco Blanc, also called Baco 22A, crosses Folle Blanche with an American vine and was bred after phylloxera to work the sandy soils of Bas-Armagnac. It was due to be swept away by the EU ban on hybrid vines and was kept for Armagnac alone."},
{"id": "c-s4t485hr", "cat": "Spirits & Cocktails", "q": "Gascony gained an appellation in 2005 for a spirit that reaches the bottle clear, having never touched wood. Name it.", "sa": 1, "accept": ["blanche armagnac", "armagnac blanche", "blanche d'armagnac", "white armagnac"], "ans": "Blanche Armagnac", "exp": "It rests in glass or stainless steel for at least three months and is bottled at forty percent or more, which puts a purely aromatic distillate on the table. Served very cold it does the work of a good eau-de-vie or a white rum, and it turns up in cocktails for the same reason."},
{"id": "c-803lwz80", "cat": "Spirits & Cocktails", "q": "Cognac's official ageing count begins not on the day the spirit leaves the still but on a fixed date afterwards. Which date?", "sa": 1, "accept": ["1 april", "april 1", "first of april", "april first", "1st april", "april 1st", "1st of april"], "ans": "The first of April", "exp": "The compte runs from the first of April following the harvest, so an eau-de-vie distilled in February sits at compte 00 until then, becomes compte 0 on that date and reaches compte 1 a year later. Distillation itself has to be finished by the thirty-first of March, which is what fixes the date."},
{"id": "c-flogy0v5", "cat": "Spirits & Cocktails", "q": "Pears are not a rounding-off in one Calvados appellation but a legal requirement, at a minimum of thirty percent. Name that appellation.", "sa": 1, "accept": ["domfrontais", "calvados domfrontais", "domfrontais calvados", "pays de domfront"], "ans": "Domfrontais", "exp": "The bocage around Domfront is pear country, and perry pear trees take far longer to come into bearing than apples do. The appellation also insists on a single distillation in a column still, the opposite of the double pot distillation required in the Pays d'Auge."},
{"id": "c-cctba2nh", "cat": "Spirits & Cocktails", "q": "Clay and flint left by decomposed limestone give one compact Cognac cru a violet-scented spirit that comes round faster than the chalk crus do. Name that cru.", "sa": 1, "accept": ["borderies", "les borderies", "borderies cru"], "ans": "Borderies", "exp": "It is the smallest of the six crus and sits just north of the town of Cognac itself. Grande and Petite Champagne are chalkier and much slower, while Fins Bois, Bons Bois and Bois Ordinaires ring the region and give quicker-maturing spirit still."},
{"id": "c-22mqfvgu", "cat": "Spirits & Cocktails", "q": "Jamaican pot still rum is bought and sold on a figure given in grams per hectolitre of pure alcohol, and the heaviest marks smell of overripe banana and glue. What is being counted?", "opts": ["Fusel oils", "Esters", "Aldehydes", "Phenols"], "a": 1, "exp": "Counts run from around 100 up to a legal ceiling of 1600 grams per hectolitre in the heaviest continental flavoured marks, which are blended in tiny proportions rather than drunk neat. Long, deliberately wild fermentations are what build them."},
{"id": "c-ipo0ndl8", "cat": "Spirits & Cocktails", "q": "The acidic liquid left in the still after a Jamaican distillation is not discarded but returned to the next fermentation to build pungency. What is that liquid called?", "sa": 1, "accept": ["dunder", "dunder pit", "dunder from the still"], "ans": "Dunder", "exp": "It works like a sourdough starter, held in pits and topped up rather than made fresh each time. Together with muck, a rotting mass of cane trash and acid, it drives the ester counts that define the heavy Jamaican marks."},
{"id": "c-75xnvd1i", "cat": "Spirits & Cocktails", "q": "Wooden pot and Coffey stills, some of them well over a century old, still work on one river in Guyana, and the rums made on them carry that river's name. Name it.", "sa": 1, "accept": ["demerara", "demerara river", "river demerara", "demerara rum", "demerara in guyana", "demerara guyana"], "ans": "Demerara", "ex": 1, "exp": "The wooden stills survived because their staves are credited with a character no metal still reproduces, so they were moved rather than scrapped as distilleries closed. The rums are dark, heavy and smoky, and were the backbone of the Royal Navy blend."},
{"id": "c-1qy2upks", "cat": "Spirits & Cocktails", "q": "Brazilian law sets a minimum bottling strength for cachaca lower than the forty percent the United States demands of rum. What is it?", "sa": 1, "accept": ["38 percent", "thirty eight percent", "38%", "38 per cent", "thirty eight per cent", "38 percent abv", "38 abv", "thirty eight", "38", "38 percent alcohol"], "ans": "Thirty-eight percent", "ex": 1, "exp": "Cachaca runs from thirty-eight to forty-eight percent and may not be distilled above fifty-four, while rum has to reach forty percent in the United States and 37.5 in the European Union. Up to six grams of sugar per litre is permitted before the drink has to be relabelled as adocada, sweetened."},
{"id": "c-lq6uz5db", "cat": "Spirits & Cocktails", "q": "Ships' pursers proved the strength of the rum ration by wetting gunpowder with it and setting light to the result. Which alcoholic strength does that test correspond to?", "sa": 1, "accept": ["57 percent", "fifty seven percent", "57%", "57 per cent", "about 57 percent", "57", "57 abv", "57 percent abv", "fifty seven per cent", "57 percent alcohol", "57.15 percent", "57 percent alcohol by volume"], "ans": "Fifty-seven percent", "ex": 1, "exp": "Gunpowder will still flash when wetted with spirit at about fifty-seven percent and will not below it, which is where navy strength and the old 100 degrees British proof both come from. It is why a navy strength gin is bottled at 57 rather than at a round number."},
{"id": "c-89mme6ki", "cat": "Spirits & Cocktails", "q": "Every bottle of Tequila carries the letters NOM followed by a four-figure number. What does that number identify?", "opts": ["The number of times the spirit was distilled", "The registered distillery that made the spirit", "The field the agave was cut from", "The year the agave was harvested"], "a": 1, "exp": "NOM stands for Norma Oficial Mexicana, and the four figures are the distillery's registration number with the regulator. One NOM can cover many brands, since a single distillery may produce for dozens of labels, so two bottles with different names and the same NOM came off the same equipment. It is the quickest way for a buyer to see who actually made a spirit."},
{"id": "c-bj9ubry6", "cat": "Spirits & Cocktails", "q": "A Tequila label says nothing about being one hundred percent agave. Where may the rest of its fermentable sugar come from?", "opts": ["Up to forty-nine percent from other agave species", "Up to fifteen percent from grape must", "Up to forty-nine percent from other sugars, usually cane", "Up to twenty-five percent from other sugars, usually cane"], "a": 2, "exp": "That style is known as mixto, though the word never appears on a label and the absence of the hundred percent claim is the only signal. The other sugar is fermented alongside the agave rather than blended in afterwards."},
{"id": "c-vm0lbvjv", "cat": "Spirits & Cocktails", "q": "A great wheel of volcanic stone is dragged around a circular pit to crush cooked agave in the traditional way. What is that wheel called?", "sa": 1, "accept": ["tahona", "tahona wheel", "tahona stone"], "ans": "Tahona", "exp": "The stone crushes rather than shreds, so fibre and juice ferment together and the spirit comes out rounder and more vegetal. A roller mill does the same job in an hour instead of a day, which is why the old method survives only where a producer chooses to pay for it."},
{"id": "c-323ryen5", "cat": "Spirits & Cocktails", "q": "A small wild agave that grows in shade beneath oaks, yields very little sugar and cannot be farmed in rows makes some of the most expensive mezcal. Name it.", "sa": 1, "accept": ["tobala", "agave tobala", "tobala agave"], "ans": "Tobala", "exp": "It grows from seed rather than from the pups that propagate espadin, so every plant harvested is one fewer in the wild. A dozen years or more in the ground yields a fraction of the sugar of a cultivated agave, and the price follows."},
{"id": "c-ch423mwo", "cat": "Spirits & Cocktails", "q": "Mezcal's rules recognise a ladder of production classes, and the strictest bars mechanical shredding altogether and demands a clay pot still. Name that class.", "sa": 1, "accept": ["ancestral", "mezcal ancestral", "ancestral mezcal", "ancestral category"], "ans": "Ancestral", "exp": "Mezcal artesanal sits a step below and allows a copper pot still and mechanical shredding, while plain Mezcal permits column stills, autoclaves and diffusers. The word describes method rather than quality, though in practice the two tend to travel together."},
{"id": "c-6g4e3ft1", "cat": "Spirits & Cocktails", "q": "Sonora makes an agave spirit with a Mexican denomination of its own, so it may not be sold as mezcal however it is made. Name it.", "sa": 1, "accept": ["bacanora", "bacanora from sonora", "sonoran bacanora"], "ans": "Bacanora", "exp": "It is distilled from Agave angustifolia, the same species as espadin, and was outlawed in Mexico for most of the twentieth century. Raicilla in Jalisco and sotol in Chihuahua sit outside the mezcal denomination too, and sotol is not made from agave at all."},
{"id": "c-f37mjkfg", "cat": "Spirits & Cocktails", "q": "Botanicals are steeped in neutral spirit and the result is bottled without going near a still again. Which category does that gin fall into?", "opts": ["London Dry gin", "Distilled gin", "Genever", "Compound gin"], "a": 3, "exp": "Compound gin is perfectly legal and is what bathtub gin always was, but it may not call itself distilled gin. Distilled gin has to be redistilled in the presence of its botanicals, and London Dry adds that nothing beyond water and a trace of sugar may go in afterwards."},
{"id": "c-ci5x5lyt", "cat": "Spirits & Cocktails", "q": "European rules put a floor under the bottling strength of vodka. Where does it sit?", "opts": ["32 percent", "43 percent", "37.5 percent", "40 percent"], "a": 2, "exp": "The United States sets its floor at forty percent, which is why some vodkas are bottled differently for each market. European rules also make a vodka distilled from anything other than cereals or potatoes name its raw material on the label."},
{"id": "c-87m3j1d8", "cat": "Spirits & Cocktails", "q": "A juniper-flavoured spirit from the Low Countries is built on a distillate of malted grain, and is sold as jonge or oude according to how much of that distillate it carries. Name it.", "sa": 1, "accept": ["genever", "jenever", "dutch genever", "genever gin"], "ans": "Genever", "exp": "Oude and jonge describe style rather than age, and the malt wine base is what makes the spirit read closer to a light whisky than to a London Dry. Its protected geographical indication covers the Netherlands, Belgium and small parts of France and Germany."},
{"id": "c-1n5dpd9z", "cat": "Spirits & Cocktails", "q": "After juniper, one seed appears in more gin recipes than any other, bringing lemon peel and a sage-like warmth with it. Name it.", "sa": 1, "accept": ["coriander", "coriander seed", "coriander seeds", "coriandrum sativum"], "ans": "Coriander", "exp": "The seed is rich in linalool, which reads as citrus and lavender and dovetails with the pine and pepper of juniper rather than sitting beside it. Angelica root is the third of the standard trio and works as a fixative, binding the lighter aromatics together."},
{"id": "c-t4n0rk2c", "cat": "Spirits & Cocktails", "q": "Absinthe's early twentieth-century ban was blamed on a compound in wormwood that was later shown to be present in only tiny amounts. Name that compound.", "sa": 1, "accept": ["thujone", "alpha thujone", "thujone from wormwood"], "ans": "Thujone", "exp": "Analysis of surviving pre-ban bottles found it at levels far too low to cause the effects laid at its door; strength, cheap adulteration and simple volume explain the rest. European law now caps it in bitter spirits at thirty-five milligrams per litre, which most absinthe never approached anyway."},
{"id": "c-c0a7mr3t", "cat": "Spirits & Cocktails", "q": "A French aperitif takes its anise character mainly from star anise and liquorice rather than from wormwood, and is poured one part to five of water. Name it.", "sa": 1, "accept": ["pastis", "pastis de marseille", "french pastis"], "ans": "Pastis", "exp": "It appeared after absinthe was banned and stayed on after absinthe returned, because it is a different drink rather than a substitute. Liquorice supplies most of the sweetness, and at forty percent and above it is the water that turns it into a long aperitif rather than a shot."},
{"id": "c-3g6lshcp", "cat": "Spirits & Cocktails", "q": "A bottle of sweet vermouth has stood open on the back bar since the spring. What has happened to it, and what should have been done?", "opts": ["It has thrown a deposit, and an open bottle should be decanted before it goes cloudy", "It has refermented, and an open bottle should be kept sealed and warm to prevent that", "It has oxidised, and an open bottle belongs in the refrigerator for a few weeks at most", "Nothing at all, since fortification keeps an open bottle stable for a year on the bar"], "a": 2, "exp": "Vermouth is wine at around sixteen percent, well short of a Port's nineteen to twenty-two, and no amount of sugar keeps air out of an opened bottle, so it browns and flattens like any other wine. A Martini built on tired vermouth is among the commonest faults on a bar and the cheapest of all to fix."},
{"id": "c-cnqidk0p", "cat": "Spirits & Cocktails", "q": "No aromatised wine may be sold as vermouth unless one particular botanical is present, and the German name for that plant is where the word vermouth came from. Name the plant.", "sa": 1, "accept": ["wormwood", "artemisia", "artemisia absinthium", "wormwood artemisia"], "ans": "Wormwood", "exp": "Wermut is the German, and Artemisia species remain the signature bitter of the category. The rest of the recipe is wide open: a vermouth may carry anything from citrus peel and cinchona to vanilla and rhubarb, but without the Artemisia it is merely an aromatised wine."},
{"id": "c-lr1cfclr", "cat": "Spirits & Cocktails", "q": "Vermouth is a wine before it is anything else, and European law fixes the band of alcoholic strength it must sit inside. What is the lower limit of that band?", "sa": 1, "accept": ["fourteen and a half percent", "14.5 percent", "14.5%", "14.5 per cent", "fourteen point five percent", "fourteen and a half", "14.5", "14.5 abv", "14.5 percent abv", "14.5 percent alcohol", "fourteen and a half per cent", "at least 14.5 percent", "14.5 percent minimum"], "ans": "Fourteen and a half percent", "ex": 1, "exp": "The band runs from there to twenty-two percent, and at least three quarters of the finished drink has to be wine. Below the floor it is not an aromatised wine at all, and above the ceiling it has become a bitter liqueur."},
{"id": "c-u0bmyr5t", "cat": "Spirits & Cocktails", "q": "One style of vermouth carries a geographical indication tying it to a northern Italian city and the region around it. Name that indication.", "sa": 1, "accept": ["vermouth di torino", "vermouth of turin", "torino", "turin", "vermouth di torino ig"], "ans": "Vermouth di Torino", "exp": "The wine must be Italian and the production must happen in Piedmont, with the Superiore tier adding that the Artemisia itself be grown there. Turin is where the commercial category began in the eighteenth century, which is why the aromatised wine trade and the Italian bitters trade grew up in the same city."},
{"id": "c-94nnabtn", "cat": "Spirits & Cocktails", "q": "A family of French aperitif wines takes its name from the bark that bitters it. Name the family.", "sa": 1, "accept": ["quinquina", "quinquinas", "quinquina aperitif"], "ans": "Quinquina", "exp": "Cinchona bark supplies quinine, and these drinks were sold as a tonic against malaria long before anyone thought of them as an aperitif. Lillet, Dubonnet and Byrrh are the surviving names, and all of them are built on wine rather than on spirit."},
{"id": "c-n2bys1lu", "cat": "Spirits & Cocktails", "q": "Suze and Salers draw their bitterness from the root of a yellow alpine flower rather than from cinchona or wormwood. Name that plant.", "sa": 1, "accept": ["gentian", "yellow gentian", "gentian root", "gentiana lutea"], "ans": "Gentian", "exp": "The roots are dug from mountain pasture, take decades to reach a useful size and are protected in some areas as a result. The same root bitters much of the Italian aperitivo family alongside citrus peel, and it is why those drinks taste earthy rather than merely sweet."},
{"id": "c-23lu2dp2", "cat": "Spirits & Cocktails", "q": "An order comes in for a drink of spirit, vermouth and bitters and nothing else, and the bartender reaches for a mixing glass rather than a shaker. What is that choice protecting?", "opts": ["Clarity and a heavier texture, since there is nothing in the glass to emulsify", "The bitters, whose aromatics break apart under agitation", "The strength, since shaking drives off alcohol as the drink warms", "The temperature, since a shaker cannot chill a drink as far as stirring can"], "a": 0, "exp": "Shaking aerates and clouds, which suits a drink carrying citrus, egg or dairy and ruins one made only of spirits. Both methods chill and dilute; stirring simply does it more slowly and leaves the texture heavier."},
{"id": "c-frr4eljb", "cat": "Spirits & Cocktails", "q": "The earliest printed definition of a cocktail, from 1806, names a spirit, sugar, water and one thing more. What is that fourth element?", "sa": 1, "accept": ["bitters", "aromatic bitters", "a dash of bitters", "cocktail bitters"], "ans": "Bitters", "exp": "That definition, printed in a New York newspaper, is why the Old Fashioned is described as the original cocktail: it is exactly those four elements and nothing else. Everything with a name of its own came later, as ingredients were added to that frame."},
{"id": "c-zqvmp4vu", "cat": "Spirits & Cocktails", "q": "Roughly a quarter of the liquid in a properly made stirred drink was never poured out of a bottle. Where did it come from?", "sa": 1, "accept": ["dilution", "melting ice", "melted ice", "water from the ice", "water from melting ice", "dilution from the ice", "ice", "ice melting", "melting of the ice", "ice melt"], "ans": "Dilution from the melting ice", "exp": "Water is an ingredient in every cocktail whether the recipe lists it or not, which is why the same ratios taste different stirred for ten seconds and stirred for thirty. Serving a stirred drink short of dilution leaves it hot, closed and unbalanced."},
{"id": "c-0dyutx4m", "cat": "Spirits & Cocktails", "q": "Rye, sugar, Peychaud's bitters and a rinse of an anise spirit make a New Orleans drink served with no ice in the glass. Name it.", "sa": 1, "accept": ["sazerac", "sazerac cocktail"], "ans": "Sazerac", "exp": "The glass is chilled and rinsed with absinthe or a pastis, and the drink itself is built separately and strained in. It began on Cognac and moved to rye once phylloxera cut the brandy supply, which is why recipes for both survive."},
{"id": "c-8cd2bcqh", "cat": "Spirits & Cocktails", "q": "A spirit and a carbonated mixer over ice in a tall glass, with no citrus and no sugar added, belong to which family?", "sa": 1, "accept": ["highball", "highballs", "highball family"], "ans": "The highball", "exp": "Length is the point: the mixer supplies most of the volume, so the drink is judged on how much soda and how much ice rather than on ounces of spirit. Add citrus and sugar and it becomes a Collins, and shake that same mixture before the soda goes in and it becomes a fizz."},
{"id": "c-hx74ojnt", "cat": "Spirits & Cocktails", "q": "Gin, green Chartreuse, maraschino and lime in equal measures make a Prohibition-era drink revived out of a Detroit club's list. Name it.", "sa": 1, "accept": ["last word", "last word cocktail"], "ans": "The Last Word", "exp": "Equal-parts building is the whole trick: a pair of assertive liqueurs balanced against gin and lime, with nothing able to dominate. The drink disappeared for decades and returned in the 2000s when a bartender found it in a recipe book from 1951."},
{"id": "c-pdajp9y9", "cat": "Sweet Wines", "q": "Side by side on a Pyrenean list sit Jurancon and Jurancon sec. What does the shorter of the two names promise?", "opts": ["Age: sec marks the wine bottled young for early drinking", "Sweetness: the plain name is the moelleux", "Dryness: sweetness is the style that needs the qualifying word here", "A boundary: the two names cover different slopes of the appellation"], "a": 1, "exp": "Jurancon was decreed in 1936 around its sweet wine, so the bare name means moelleux and it is dryness that must announce itself, the sec gaining its own recognition in 1975. That is the reverse of most French labelling, where dry is the default and sugar gets the extra word, and it is exactly the trap a list should brief its floor staff on."},
{"id": "c-tzs110cf", "cat": "Sweet Wines", "q": "Small thick-skinned berries in loose, airy bunches let one Pyrenean variety hang candying on the wire into December without rotting. Name it.", "sa": 1, "accept": ["petit manseng", "petit manseng grape", "petit manseng variety", "petit manseng vine", "manseng petit"], "ans": "Petit Manseng", "ex": 1, "exp": "The skin sheds rain and the open bunch lets wind pass through, which is what makes weeks of passerillage possible where tighter fruit would have split or moulded. The concentration here is drying on the vine rather than noble rot, which the dry Pyrenean autumns rarely deliver."},
{"id": "c-89zr2592", "cat": "Sweet Wines", "q": "Rounded Pyrenean pebbles cemented into a hard conglomerate underlie Jurancon's best slopes, and the rock's French name is borrowed from an English dessert. Give the name.", "sa": 1, "accept": ["poudingue", "poudingues", "pudding stone", "puddingstone", "pudding stones"], "ans": "Poudingue", "exp": "Poudingue is a straight French borrowing of the English pudding stone: torrents off the young Pyrenees dumped rounded pebbles that later cemented into rock. It drains hard and holds little, which suits vines asked to hang ripe fruit deep into the wet months of autumn."},
{"id": "c-snqs24ux", "cat": "Sweet Wines", "q": "Trunks in Jurancon climb head-high before the first fruiting wire, roughly twice the height of a Bordeaux vine. What are the bunches being lifted clear of?", "opts": ["Browsing deer and boar out of the woods", "Spring frost, whose coldest air lies along the ground on a clear night", "Snow sliding off the Pyrenees, which would bury a low cordon in most winters", "Reflected summer heat near the pale soil"], "a": 1, "exp": "Cold air behaves like water, draining downslope and pooling at the ground, so a bud at head height can pass a still, clear night unharmed while one at knee height freezes. The old hautains went further and trained the vines up living trees; the modern trellis keeps the principle without the acrobatics."},
{"id": "c-hc4h3v6a", "cat": "Sweet Wines", "q": "At his birth in Pau in 1553, the story runs, the infant's lips were brushed with garlic and a glass of the local sweet wine. Which future king was the infant?", "sa": 1, "accept": ["henri iv", "henry iv", "henri quatre", "henri de navarre", "henry of navarre", "henri of navarre", "henri iv of france", "henry iv of france", "henri iv de france", "henri de bourbon", "future henri iv", "king henri iv", "king henry iv"], "ans": "Henri IV", "ex": 1, "exp": "The baby was Henri de Navarre, born in the castle at Pau, and the wine in the tale is Jurancon. The legend has been the appellation's calling card for four and a half centuries, and whatever its truth it records how early this corner of Bearn had a court reputation for its sweet wine."},
{"id": "c-5sq9enlt", "cat": "Sweet Wines", "q": "Beyond its standard moelleux, Jurancon reserves a further label mention for lots picked weeks later still, deep into the autumn. Which mention?", "sa": 1, "accept": ["vendanges tardives", "vendange tardive", "late harvest", "jurancon vendanges tardives", "vendanges tardives mention"], "ans": "Vendanges Tardives", "ex": 1, "exp": "The mention demands later passes and riper must than the standard sweet wine, with enrichment forbidden, and in a good year the last lots hang until the frosts. It formalised what the serious growers were already doing, which is how most French mentions begin."},
{"id": "c-vpu8rj34", "cat": "Sweet Wines", "q": "The red-wine appellation of Madiran shares its exact boundaries with a white-wine twin whose harvest runs from October into the depths of winter. Name the twin.", "sa": 1, "accept": ["pacherenc du vic bilh", "pacherenc"], "ans": "Pacherenc du Vic-Bilh", "ex": 1, "exp": "Same communes, two appellations: red goes to market as Madiran, white as Pacherenc du Vic-Bilh, the name usually glossed as old Gascon for posts in a row, after the tall stakes of the traditional vineyards. Its sweet lots come off the vine pass by pass, and the latest fruit hangs far longer than anything red."},
{"id": "c-d608nh3p", "cat": "Sweet Wines", "q": "In the village of Viella the year's final picking has grown into a festival, with the sweetest Pacherenc cut from the vine on one particular evening. Which evening?", "sa": 1, "accept": ["saint sylvestre", "st sylvestre", "new year's eve", "new years eve", "december 31", "31 december", "december 31st", "31st of december", "last day of the year", "31st december", "dec 31", "dec 31st"], "ans": "Saint-Sylvestre, New Year's Eve", "exp": "The Saint-Sylvestre pick on 31 December closes a run of passes that began in October, and fruit that has hung that long is pure passerille concentrate. The date has been kept since the early 1990s, and the torchlit harvest sells the wine's scarcity before a note of it is tasted."},
{"id": "c-bv8uxr52", "cat": "Sweet Wines", "q": "The Mansengs and Petit Courbu fill most Pacherenc rows, but a fourth local white, close to extinct outside this corner of Gascony, keeps its place in the blend. Name it.", "sa": 1, "accept": ["arrufiac", "arrufiat", "ruffiac", "arrufiac grape"], "ans": "Arrufiac", "exp": "Arrufiac survives because Pacherenc's rules kept a seat for it, and its firm, faintly bitter fruit plays the seasoning part against the Mansengs' sugar and perfume. The local growers' union has made a cause of the area's old varieties, and this one is its clearest rescue."},
{"id": "c-14s85wng", "cat": "Sweet Wines", "q": "Botrytis works the Dordogne exactly as it works the Garonne, and the biggest sweet-wine appellation of the Bergerac country sells honeyed richness at a fraction of the Sauternes price. Name it.", "sa": 1, "accept": ["monbazillac", "monbazillac aoc", "monbazillac appellation"], "ans": "Monbazillac", "exp": "Monbazillac's communes rise south of the river opposite the town of Bergerac, and autumn mists off the Dordogne bring the rot in most years. The gap in price owes more to the absence of classified names than to any shortage of noble rot, which is why the appellation is a sommelier's standard answer to a Sauternes budget."},
{"id": "c-mftxsqxk", "cat": "Sweet Wines", "q": "Held to a token share in most Sauternes blends, one of the classic sweet-white trio is planted in earnest across the Bergerac belt. Which grape?", "sa": 1, "accept": ["muscadelle", "muscadelle grape", "muscadelle variety"], "ans": "Muscadelle", "exp": "Muscadelle is awkward in the vineyard and rots the wrong way as readily as the right one, so grand Sauternes mostly gave up on it; around Bergerac it kept real acreage and brings a grapey, floral register the other two lack. It is no relation of Muscat, whatever the nose suggests."},
{"id": "c-z5nzy843", "cat": "Sweet Wines", "q": "Across the Bergerac sweet belt the most prized rows look north over the Dordogne, an aspect planted away from almost everywhere else in France. What does it deliver here?", "opts": ["Shelter from Atlantic rain arriving out of the west", "A longer arc of evening sun through the picking season", "Protection from spring frost, which strikes sun-facing ground first", "Cold misty mornings off the river, which is what a botrytis harvest runs on"], "a": 3, "exp": "A north slope above water holds its morning damp and warms slowly, so fog sits in the rows long enough for the fungus to work before the afternoon dries the fruit. On a dry-wine slope the same properties would be a fault, which is why aspect can only be judged against the wine being attempted."},
{"id": "c-brk1fhsw", "cat": "Sweet Wines", "q": "A cluster of villages west along the Dordogne's left bank holds one of France's smallest appellations, and its decree admits nothing but sweet white wine. Name it.", "sa": 1, "accept": ["saussignac", "saussignac aoc", "cotes de saussignac"], "ans": "Saussignac", "exp": "Saussignac works the same autumn fogs as its bigger neighbour, and its growers were early converts to organic farming for the zone. Dry lots from the same rows simply go out as Bergerac, which is what keeps the appellation itself entirely sweet."},
{"id": "c-nqs5ixsa", "cat": "Sweet Wines", "q": "Early in the 1990s the flagship botrytis name of the Bergerac belt struck one piece of equipment from its rules, pulling itself back toward the Sauternes model. Which equipment?", "sa": 1, "accept": ["harvesting machine", "harvesting machines", "machine harvester", "machine harvesters", "machine harvesting", "mechanical harvesting", "mechanical harvester", "mechanical harvesters", "harvest machines", "harvesting by machine", "machine picking", "mechanical picking", "harvester", "harvesters", "grape harvester", "grape harvesters", "mechanical grape harvester", "mechanical grape harvesters", "picking machine", "picking machines"], "ans": "The harvesting machine", "exp": "A machine takes everything on the vine in a single pass, and a serious botrytis wine needs the opposite: hand crews returning in successive tries for the berries the rot has finished. The ban marked the appellation's turn back to selective picking, and its reputation has climbed ever since."},
{"id": "c-wk26y10k", "cat": "Sweet Wines", "q": "EU law lets most wine labels stay silent about sweetness, yet for one whole category the term is compulsory on every label. Which category?", "opts": ["Wine made from botrytised fruit", "Any wine above fifteen percent alcohol", "Still wine under a protected designation of origin", "Sparkling wine"], "a": 3, "exp": "A sparkling label without brut, extra dry, demi-sec or one of their siblings is not legal, while a still wine may say nothing at all. Silence is the only free choice, though: the moment a still label does print a sweetness word, the word must sit inside the band the regulation defines for it."},
{"id": "c-lhlvmye7", "cat": "Sweet Wines", "q": "Nine grams of sugar sit in a still white that legally wears the word sec. What bought it the room above the usual four-gram line?", "opts": ["Bottling done before the current rule took effect", "A vintage the authorities declared hot enough for a broader band", "Acidity high enough to come within two grams of the sugar", "Alcohol above thirteen percent, which reads dry"], "a": 2, "exp": "Balance is the point of the concession: the band stretches to nine grams when total acidity trails the sugar by no more than two grams per litre, because nine against seven of tartaric tastes drier than five against three. A parallel clause with a looser test, total acidity no more than ten grams below the sugar, stretches demi-sec from twelve grams to eighteen, which is why high-acid Chenin so often carries less sweetness on its label than the palate reports."},
{"id": "c-a2dppufe", "cat": "Sweet Wines", "q": "Thirty grams of residual sugar stand in a still Loire Chenin, and the grower wants the sweetest word the wine has legally earned. Which word goes on the label?", "sa": 1, "accept": ["moelleux", "medium sweet", "medium"], "ans": "Moelleux", "ex": 1, "exp": "The still-wine ladder runs sec, demi-sec, moelleux, doux, and thirty grams sits squarely in the moelleux band, which reaches from the demi-sec ceiling up to forty-five grams. Doux would overstate the wine and demi-sec would undersell it, and either would be an illegal label rather than a stylistic choice."},
{"id": "c-frthglej", "cat": "Sweet Wines", "q": "A demi-sec Champagne stands beside a demi-sec still Vouvray on the same flight. Which bottle actually carries more sugar?", "sa": 1, "accept": ["champagne", "champagne by some distance", "sparkling", "sparkling wine", "fizz"], "ans": "The Champagne, by some distance", "exp": "The sparkling scale is shifted wholesale: demi-sec opens at thirty-two grams there and runs to fifty, while the same word on a still label is capped at twelve, or eighteen where the acidity concession applies. Dosage terms were calibrated for wines whose acidity and carbonation swallow sweetness, so the word on the two labels is a false friend, and demi-sec Champagne is honestly a dessert wine."},
{"id": "c-8kauwh0b", "cat": "Sweet Wines", "q": "One sweet-wine tradition dries its bunches for months in a ventilated loft, another leaves them hanging on the wire. What does bringing the crop indoors chiefly secure?", "opts": ["Control: the fruit is picked at its best and put beyond the autumn weather", "Warmth, which builds sugar beyond what water loss alone can give", "Speed: a loft finishes in days what the vine would take months to do", "Noble rot, which will only take hold under a roof"], "a": 0, "exp": "Drying off the vine separates two decisions the vineyard otherwise welds together: when the fruit is ripe and how long it concentrates. Once the bunches are on the racks the autumn weather can no longer touch them, where fruit left on the wire is at the mercy of every rain that comes. The price is labour and space, plus a winter spent walking the racks pulling out anything that spoils, because one mouldy bunch shares its taint with its neighbours."},
{"id": "c-4yhjjfl8", "cat": "Sweet Wines", "q": "Freshness is Moscato d'Asti's whole sales pitch, yet a bottle filled in June tastes as bright as one filled in November. What allows that?", "opts": ["Pasteurisation at bottling stops the wine developing at all afterwards", "A share of fresh unfermented juice is blended into every bottling run, sussreserve-style", "Its must is held cold and unfermented, with batches fermented to order all year", "Every release is briefly refermented in tank to restore the prickle before it ships"], "a": 2, "exp": "The houses bank the vintage as chilled, sterile-filtered must and run a fermentation only when orders call for one, so the wine's aromatic clock starts weeks before bottling rather than at the harvest. Each ferment is then stopped early by chilling and filtration, which is what leaves the alcohol low and the sugar in the glass."},
{"id": "c-gxq44pcn", "cat": "Sweet Wines", "q": "Tuscan tradition puts the sealed caratelli of Vin Santo not in a cellar but in a room under the roof tiles, where nobody moderates the seasons. What is that room called?", "sa": 1, "accept": ["vinsantaia", "vinsantaia attic", "vinsantaia loft"], "ans": "The vinsantaia", "exp": "The vinsantaia bakes in August and freezes in January, and that cycling drives the wine's slow concentration and its nutty, oxidative depth. A tempered cellar would make a cleaner and duller wine; the room's discomfort is the recipe."},
{"id": "c-u1kvo9vm", "cat": "Sweet Wines", "q": "Most Vin Santo is pressed from white grapes, but a rosy version built on Sangiovese carries a name borrowed from a game bird's eye. Give the name.", "sa": 1, "accept": ["occhio di pernice", "vin santo occhio di pernice", "occhio di pernice vin santo"], "ans": "Occhio di Pernice", "exp": "Occhio di Pernice, the partridge's eye, names the tawny-pink colour the dried red grapes give. The craft is unchanged - the drying, the sealed small casks, the years under the roof - so what changes in the glass is a red-fruit, tea-leaf register laid over the same nutty base."},
{"id": "c-ametc74t", "cat": "Sweet Wines", "q": "Down a well-built dessert list nearly every entry is a 375 millilitre bottle. What is the format's logic?", "opts": ["A dessert pour is small, so a half serves the whole table while it is fresh", "The format signals rarity, and rarity is what the dessert course trades on", "Sweet-wine appellations release only in the small format, leaving lists no choice", "Sweet wines throw heavy sediment, and the small bottle keeps the deposit manageable"], "a": 0, "exp": "A dessert pour runs about half the size of a table pour, so a 375 covers a whole table's course and nothing sits open going stale. The same bottle also lands at a list price a table will actually spend at the end of a meal, which a full bottle of the identical wine rarely does."},
{"id": "c-pt8hz6tw", "cat": "Sweet Wines", "q": "Recorked and refrigerated, a botrytis wine can pour honestly for a week or more after opening, long after a dry white would have faded. What in the wine buys that time?", "sa": 1, "accept": ["sugar", "its sugar", "residual sugar", "high sugar", "sugar content", "all that sugar", "high residual sugar", "sugar level", "sweetness", "its sweetness", "residual sweetness"], "ans": "Its sugar", "exp": "Concentrated sugar is a preservative in the jam sense: it denies microbes the water they need to work in the open bottle, and with the wine's acidity behind it, the sweetness also masks the first flavour costs of oxidation. The practical consequence is that sweet wine is the safest by-the-glass category in the building, holding days longer than anything dry."},
{"id": "c-4fyfptok", "cat": "Sweet Wines", "q": "Left at the back of the main wine list, sweet wine barely sells; printed on one other piece of paper it moves every night. Which piece of paper?", "sa": 1, "accept": ["dessert menu", "dessert card", "pudding menu", "dessert list", "on the dessert menu"], "ans": "The dessert menu", "exp": "A guest choosing dessert is the only guest in the room thinking about sweetness, and a glass of botrytis wine listed beside the tart reads as part of the course rather than as more wine. It is the cheapest merchandising move in the building: same stock, same prices, different page, more sales."},
{"id": "c-a42c0s3d", "cat": "Terroir: Climate & Soil", "q": "Fruit sitting deep inside a dense canopy runs three degrees cooler than fruit on the outside of the same vine on the same afternoon. Which scale of climate has just been measured?", "opts": ["Mesoclimate", "Microclimate", "Macroclimate", "Seasonal climate"], "a": 1, "exp": "Microclimate is the air within and immediately around the canopy, measured in metres and often in centimetres. It is the only one of the three scales a grower can change in an afternoon, which is why leaf removal and shoot positioning alter fruit chemistry without altering the site at all."},
{"id": "c-duqygtll", "cat": "Terroir: Climate & Soil", "q": "One of the interventions listed here alters the air immediately around the bunches and changes nothing else about the site. Which is it?", "opts": ["Removing leaves from the fruiting zone", "Planting the next block higher up the slope", "Choosing a drought-tolerant rootstock", "Delaying the harvest date by ten days"], "a": 0, "exp": "Opening the fruiting zone changes light, temperature and airflow at the bunch, which is microclimate work. Moving up the slope changes the mesoclimate because it changes the site, and rootstock and picking date change the vine's response rather than the air around it."},
{"id": "c-3eok12bl", "cat": "Terroir: Climate & Soil", "q": "A grower points out that his hillside block ripens a full week ahead of the valley-floor block he also owns, though the appellation and the weather station serving them are the same. Which scale of climate is he describing?", "sa": 1, "accept": ["mesoclimate", "mesoclimates", "meso climate", "meso climates", "meso scale", "site climate"], "ans": "Mesoclimate", "exp": "Mesoclimate is the climate of a particular site, running from a few metres to a few kilometres, and it is what site selection is really about. The appellation shares a macroclimate, so anything that separates two blocks inside it is a mesoclimate effect: slope, aspect, elevation, exposure, air drainage."},
{"id": "c-e7emyjel", "cat": "Terroir: Climate & Soil", "q": "Published thirty-year averages from a lowland weather station mislead a producer whose vines sit a hundred and fifty metres above it on a ridge. Which climatic scale do those figures actually describe?", "sa": 1, "accept": ["macroclimate", "macro climate", "regional macroclimate", "the macroclimate scale"], "ans": "Macroclimate", "exp": "A macroclimate covers a whole region and is what published regional averages describe. It cannot resolve a ridge, a lake shore or a frost hollow, so station data is where site assessment starts rather than where it finishes, and a serious buyer asks for on-site loggers instead."},
{"id": "c-0kzozkpa", "cat": "Terroir: Climate & Soil", "q": "Take two regions with an identical mean annual temperature: in one, the hottest and coldest months lie eight degrees apart, in the other twenty-four. Which measure is that gap?", "opts": ["Diurnal range", "Heat summation", "Mean July temperature", "Continentality"], "a": 3, "exp": "Continentality is the spread between the mean temperature of the warmest month and that of the coldest, and it is the figure that separates a continental site from a maritime one when the annual mean cannot. Diurnal range measures the same kind of spread over a day rather than a year, and the two are independent of each other."},
{"id": "c-3lpjtnfd", "cat": "Terroir: Climate & Soil", "q": "Warmest-month mean of twenty-two degrees, coldest-month mean of one degree, rainfall spread fairly evenly through the year. Which climate model do those figures together indicate?", "opts": ["Continental", "Maritime", "Tropical", "Mediterranean"], "a": 0, "exp": "A twenty-one degree annual swing is far too wide for a maritime site, where water damps the extremes at both ends. Even rainfall rules out the Mediterranean model, whose signature is not warmth but a dry summer with the rain concentrated in the mild winter."},
{"id": "c-v6ip3ia9", "cat": "Terroir: Climate & Soil", "q": "Cold nights do not add acid to a berry; they change what the berry does with the acid it already holds. Which process is being slowed?", "opts": ["Malolactic conversion", "Photosynthesis in the leaf", "Respiration of malic acid", "Transpiration through the stomata"], "a": 2, "exp": "Malic acid is a respiratory substrate, and the rate at which the berry burns it climbs steeply with temperature. Tartaric acid is barely respired at all, which is why a warm region loses its malic first and ends up with wines that are flat rather than merely low in total acidity."},
{"id": "c-971j2l8o", "cat": "Terroir: Climate & Soil", "q": "Two heat-summation totals come out identical for a northern site and a southern one, though the northern site enjoys far longer midsummer days. Which index applies a day-length coefficient to correct for that?", "opts": ["The continentality index", "The Winkler index", "Growing season temperature", "The Huglin index"], "a": 3, "exp": "Huglin weights accumulated heat by a latitude coefficient, on the reasoning that a long northern day gives the vine more hours to use the warmth it gets. Winkler counts degree days without any such correction, which is why the two indices rank a German site and a Spanish one differently."},
{"id": "c-t7wij4l3", "cat": "Terroir: Climate & Soil", "q": "Amerine and Winkler summed the daily degrees above ten Celsius from April through October to sort California into bands. What is the resulting quantity called?", "sa": 1, "accept": ["growing degree days", "growing degree day total", "degree days", "accumulated degree days", "degree day accumulation", "heat summation", "growing degree day summation", "growing degree days gdd", "gdd"], "ans": "Growing degree days", "exp": "Ten degrees is the threshold below which the vine does essentially nothing, so only the warmth above it is counted. The measure is blind to how the heat arrived, which is its weakness: one brutal August week and a long even summer can total the same and ripen fruit quite differently."},
{"id": "c-udaqvft6", "cat": "Terroir: Climate & Soil", "q": "Rather than a full-year mean, the classification most used in wine climatology today averages temperature over the seven months from April to October in the north. Name that average.", "sa": 1, "accept": ["growing season temperature", "mean growing season temperature", "growing season mean temperature", "growing season average temperature", "average growing season temperature", "mean temperature of the growing season", "average temperature of the growing season", "growing season temperature gst", "gst"], "ans": "Growing season temperature", "exp": "Averaging only the months the vine is awake removes the winter noise that makes annual means useless for comparing regions. The bands it produces, from cool through intermediate and warm to hot, map onto variety suitability far better than latitude does."},
{"id": "c-ixwug9tk", "cat": "Terroir: Climate & Soil", "q": "Two coastal regions share a narrow annual temperature range, yet one bakes dry every summer while the other faces rot pressure at picking. Which variable separates them?", "sa": 1, "accept": ["seasonal distribution of rainfall", "rainfall distribution", "seasonal rainfall distribution", "distribution of rainfall through the year", "when the rain falls", "when the rain comes", "when the rain arrives", "rainfall timing", "timing of rainfall", "rainfall seasonality", "seasonality of rainfall", "rainfall pattern"], "ans": "The seasonal distribution of rainfall", "exp": "Maritime and Mediterranean climates are both moderate, so temperature alone will not tell them apart. The Mediterranean model puts its rain in the winter and leaves the growing season dry, which is why irrigation and drought are its arguments while the maritime regions argue about fungicide and picking dates."},
{"id": "c-bqtnqt33", "cat": "Terroir: Climate & Soil", "q": "Water changes temperature far more slowly than the land beside it, and that single physical property is the whole of why a coastal vineyard is moderate. Name the property.", "sa": 1, "accept": ["high specific heat capacity", "specific heat capacity", "specific heat capacity of water", "high specific heat capacity of water", "water's high specific heat capacity", "water has a high specific heat capacity", "specific heat", "high specific heat", "heat capacity", "high heat capacity", "thermal inertia", "high thermal inertia", "thermal mass", "high thermal mass", "thermal mass of water"], "ans": "High specific heat capacity", "ex": 1, "exp": "It takes roughly five times as much energy to warm a mass of water by one degree as it does the same mass of rock, so a large body of water lags the air around it in both directions. That lag is what shortens winters, delays autumn and blunts heat spikes; depth matters more than surface area, which is why a deep lake moderates better than a shallow one of the same size."},
{"id": "c-5kuzfy6n", "cat": "Terroir: Climate & Soil", "q": "Tilting the ground toward the sun buys far more energy at fifty degrees of latitude than at thirty. What accounts for the difference?", "opts": ["Days are shorter at high latitude, so each hour of sunshine must do more work", "High-latitude air holds more moisture, which traps heat against the slope", "The sun sits lower at high latitude, so a slope faces it more squarely", "Soils at high latitude are darker and absorb more of the energy reaching them"], "a": 2, "exp": "Energy per square metre depends on the angle at which light strikes the ground, and the closer that angle comes to perpendicular the more of the beam a given patch of ground collects. Near the equator the sun is close to overhead and a slope gains almost nothing, which is why aspect is an obsession on the Mosel and an irrelevance in Mendoza, where elevation does the work instead."},
{"id": "c-ow0jvwiv", "cat": "Terroir: Climate & Soil", "q": "Set sunlight aside: the celebrated sites in steep regions still sit on the slope rather than on the flat ground below it. What has gravity done to those two soils over the centuries?", "opts": ["Slopes accumulate a deeper topsoil than the ground below them", "Fine material has washed downhill from the slope to the flat", "Slopes hold more organic matter, so hillside vines are better fed", "Rainfall totals are higher on slopes than on valley floors"], "a": 1, "exp": "Erosion strips clay and organic matter off a gradient and dumps it at the bottom, so the slope keeps a thin, stony, poor profile and the valley floor collects the richness. Poor and thin is what restrains vigour, which is why the hillside is planted and the fertile flat is left to other crops."},
{"id": "c-734zathl", "cat": "Terroir: Climate & Soil", "q": "Vineyards planted within a few degrees of the equator ought to lose all their acidity, and above two thousand metres they do not. Which feature of high tropical sites rescues them?", "opts": ["A short growing season", "A very wide diurnal swing", "A pronounced winter dormancy", "Long summer daylight hours"], "a": 1, "exp": "Thin air at altitude radiates its heat away fast after sunset, so tropical highland sites can run twenty degrees between afternoon and dawn. Nothing else is available to them: there is no winter to enforce dormancy and no seasonal variation in day length at all, so the diurnal swing is doing all of the work."},
{"id": "c-e7y8l4ey", "cat": "Terroir: Climate & Soil", "q": "Climbing a hillside costs a vineyard about six-tenths of a degree of mean temperature for every hundred metres gained. Name that rate of cooling with height.", "sa": 1, "accept": ["lapse rate", "environmental lapse rate", "adiabatic lapse rate", "temperature lapse rate"], "ans": "The lapse rate", "exp": "The figure is why elevation substitutes for latitude: three hundred metres up is worth roughly two degrees, which is a large slice of the difference between one growing season band and the next. It is also why altitude is the standard answer to a warming climate in regions that have run out of cooler latitudes to move to."},
{"id": "c-2gu7khk6", "cat": "Terroir: Climate & Soil", "q": "On a still clear night the coldest air in a valley collects on the floor, while the ridge top cools by exposure, leaving a warmer band lying between them. What do growers call that band?", "sa": 1, "accept": ["thermal belt", "thermal zone", "thermal belt of the slope", "the warm thermal belt"], "ans": "The thermal belt", "exp": "Mid-slope sits above the pooled cold air and below the exposed summit, which is why the oldest vineyards on a hillside are so often in the middle third of it. The belt is a frost-season phenomenon and it moves with the depth of the cold pool, so its lower boundary is worth marking in a bad spring rather than assuming."},
{"id": "c-m32ctkj0", "cat": "Terroir: Climate & Soil", "q": "Dense cold air slides downhill under gravity on a windless night, behaving far more like water than like wind. Meteorology has a name for that downslope flow. Give it.", "sa": 1, "accept": ["katabatic flow", "katabatic wind", "katabatic drainage", "katabatic"], "ans": "Katabatic flow", "exp": "Because it behaves like a fluid, anything that dams it matters: a solid wall, a dense hedge or an embankment across the bottom of a slope will pond cold air behind it and turn a safe site into a frost trap. The remedy is usually to open a gap rather than to buy machinery."},
{"id": "c-um4lztcu", "cat": "Terroir: Climate & Soil", "q": "Rainfall on the seaward flank of a coastal range routinely runs to three times the total recorded a short distance inland. Which process concentrates it there?", "opts": ["Convection over warm ground", "Orographic lift", "A collision of warm and cold fronts", "Katabatic drainage"], "a": 1, "exp": "Air forced up over the barrier cools as it expands, passes its dew point and drops its moisture on the windward side. Everything downwind is then working with air that has already been wrung out, which is the whole mechanism behind a rain shadow."},
{"id": "c-g0c7uwbx", "cat": "Terroir: Climate & Soil", "q": "A summer marine layer pushes through gaps in a coast range and lies over the vineyards until late morning. What does that fog most directly buy the fruit?", "opts": ["A rise in ultraviolet exposure that thickens the skins", "A supply of nitrogen deposited out of the marine air", "A cooler, shorter effective day", "A measurable increase in growing-season rainfall"], "a": 2, "exp": "The fog caps the temperature and cuts the hours of full sun, so sugar accumulates slowly and acid holds while flavour and tannin catch up. It is a cooling mechanism that works in a region with no rain at all in summer, which is why the coldest sites in California can sit at the latitude of North Africa."},
{"id": "c-ep6h3a2y", "cat": "Terroir: Climate & Soil", "q": "Winter survival in Ontario's Niagara Peninsula depends on Lake Ontario, but the moderated air has to be held over the vineyards by a landform standing behind them. Name it.", "sa": 1, "accept": ["niagara escarpment", "escarpment", "niagara escarpment in ontario"], "ans": "The Niagara Escarpment", "exp": "The escarpment traps lake-warmed air on the bench between rock face and shoreline and sets up a circulation that keeps it moving over the vines. Water alone is not enough this far into a continental winter: without the wall behind it the moderated air would simply drain away inland."},
{"id": "c-2ly0cteh", "cat": "Terroir: Climate & Soil", "q": "Air that has already dumped its moisture climbing the windward slope arrives on the far side warm, dry and gusting, and the Alpine name for that wind is used across the wine world. Give it.", "sa": 1, "accept": ["foehn", "fohn", "foehn wind", "fohn wind"], "ans": "Foehn", "exp": "The air warms as it descends and is compressed, and having lost its water on the way up it arrives far drier than it began. Alto Adige and the Valais both bank on it to dry the canopy and finish ripening, and it is the same physics as the Chinook and the Zonda under different names."},
{"id": "c-ocnnjqrr", "cat": "Terroir: Climate & Soil", "q": "Moist air moving horizontally over a surface colder than its own dew point produces fog with no overnight cooling of the ground involved at all. Name that class of fog.", "sa": 1, "accept": ["advection fog", "advective fog", "sea fog"], "ans": "Advection fog", "exp": "Advection fog needs wind to keep the moist air arriving, so it forms and persists in conditions that would blow radiation fog away. That is why coastal fog rolls in during the afternoon and evening while river-valley radiation fog appears at dawn and burns off by mid-morning."},
{"id": "c-673jqr0b", "cat": "Terroir: Climate & Soil", "q": "A wind machine turned all night and the crop froze anyway, because the cold had arrived as a freezing air mass under cloud with a stiff breeze behind it. What did the machine have nothing to work with?", "opts": ["An outlet at the base of the slope for cold air to escape through", "Enough fuel to run through to dawn", "Sprinkler nozzles at ground level", "A warmer layer of air sitting above the vineyard for it to pull down"], "a": 3, "exp": "A wind machine does not heat anything; it mixes down the warm air of a nocturnal inversion. An advective freeze is a whole cold air mass arriving horizontally, so the air aloft is cold too and there is nothing above the vineyard worth fetching, which is why advective events are the ones nobody can defend against."},
{"id": "c-7fwdk153", "cat": "Terroir: Climate & Soil", "q": "Once ice has formed on the buds the sprinklers must not be switched off until it thaws, and stopping early does more damage than never starting. Why?", "opts": ["The ice sheet cracks and severs the shoot", "Wet buds attract downy mildew before dawn", "Melting and evaporation then pull heat out of the bud", "The added water washes sugars out through the bud scales"], "a": 2, "exp": "Protection comes from the latent heat given up as water freezes, which holds the bud at about zero as long as fresh water keeps arriving and keeps freezing. Cut the supply and the latent heat runs the other way: evaporation from the wet ice, and melting behind it, take heat back out of the bud they were protecting and drive it below the temperature it would have reached unprotected."},
{"id": "c-ivvc067h", "cat": "Terroir: Climate & Soil", "q": "A run of forty-degree afternoons in midsummer stalls a vineyard rather than pushing it forward. Which response of the vine produces the stall?", "opts": ["Root growth accelerates in search of water", "Malic acid is synthesised rather than respired", "Stomata close and carbon uptake stops", "The vine flowers for a second time"], "a": 2, "exp": "Above the mid-thirties the vine closes its stomata to defend against losing water it cannot replace, and that shuts down carbon dioxide uptake at the same time. Sugar accumulation therefore pauses while acid continues to be burnt off, which is how a heatwave manages to deliver unripe flavours and flabby wines together."},
{"id": "c-85zmax1r", "cat": "Terroir: Climate & Soil", "q": "Clear sky, dry air and no wind: the ground gives up its heat to space, bud height falls below zero, and the air a few metres up stays mild. What kind of frost is that?", "sa": 1, "accept": ["radiation frost", "radiative frost", "radiational frost", "frost by radiation"], "ans": "Radiation frost", "exp": "Longwave radiation escapes to space unimpeded on a clear night, cooling the surface faster than the air above it and setting up an inversion. That inversion is what every defence exploits, whether by mixing the warm layer down with fans and helicopters or by adding heat underneath it with burners."},
{"id": "c-t05ojbk2", "cat": "Terroir: Climate & Soil", "q": "Silver iodide fired into an approaching storm cell is meant to multiply the ice nuclei so that whatever forms stays small. Which vineyard hazard is being fought?", "sa": 1, "accept": ["hail", "hailstorm", "hailstorms", "hail storm", "hail storms", "hailstone", "hailstones", "hail stone", "hail stones", "hail damage", "damage from hail"], "ans": "Hail", "ex": 1, "exp": "Seeding does not stop the storm; it tries to share the available moisture among more and therefore smaller stones that melt before landing. The evidence for it is contested, which is why growers who can afford the outlay put the money into netting instead, a physical barrier over the fruit being the one defence whose effect can actually be measured."},
{"id": "c-ph8amorf", "cat": "Terroir: Climate & Soil", "q": "A region whose growing-season weather barely shifts from year to year makes dependable wine but lacks something collectors prize in Burgundy and the Mosel. Name what it lacks.", "sa": 1, "accept": ["~vintage variation", "~vintage variations", "~vintage variability", "~variation between vintages", "~variability between vintages", "~variation between years", "~variability between years", "~year to year variation", "~year to year variability", "~variation from year to year", "~variability from year to year", "~vintage to vintage variation", "~variation from vintage to vintage", "~variability from vintage to vintage"], "ans": "Vintage variation", "ex": 1, "exp": "Marginal climates sit near the edge of ripening, so a degree either way rewrites the whole harvest and the vintage chart becomes worth reading. Reliability and vintage character are two ends of one trade, which is why the same weather pattern is a commercial virtue in one region and a collector's disappointment in another."},
{"id": "c-igbu723i", "cat": "Terroir: Climate & Soil", "q": "Roots in a chalk soil never drown, though the rock beneath them is holding a great deal of water. Which combination of properties allows both to be true?", "opts": ["Strong alkalinity, which stops roots taking up excess water", "A dark colour, which evaporates surface water quickly", "A high clay fraction, which binds water into a gel", "Very high porosity, with fissures that drain freely"], "a": 3, "exp": "Chalk can hold a third of its volume as water in pores too fine to release it to gravity, while the joints and fissures running through it carry surplus water straight down. The vine therefore gets a slow reserve through a dry summer without ever sitting in standing water, which is the combination almost no other rock offers."},
{"id": "c-gbagfwra", "cat": "Terroir: Climate & Soil", "q": "A Burgundian points at a bed of roughly equal parts limestone and clay and calls it the best ground he has. Which rock has he named?", "opts": ["Marl", "Flysch", "Gypsum", "Loess"], "a": 0, "exp": "Marl is a limestone and clay mixture, and it combines the water reserve and nutrient holding of clay with the drainage and structure of limestone. Pure clay would be too cold and too wet and pure limestone too thin, which is why the marl bands on a slope so often carry the best-regarded parcels."},
{"id": "c-z2cgtx9p", "cat": "Terroir: Climate & Soil", "q": "Leaves yellow between veins that stay green, on a block where the active lime reads very high, and no fertiliser regime corrects it. Name the disorder.", "sa": 1, "accept": ["iron chlorosis", "lime induced chlorosis", "lime induced iron chlorosis", "iron deficiency", "iron deficiency chlorosis", "ferric chlorosis", "chlorosis from lime", "lime chlorosis"], "ans": "Iron chlorosis", "exp": "Iron is present in the soil but locked into forms the root cannot take up at high pH, so adding more of it to the ground achieves nothing. The durable fix is a lime-tolerant rootstock at replanting, which is why chalk regions rely on a narrow group of berlandieri crosses rather than on the whole rootstock catalogue."},
{"id": "c-7tr9pb82", "cat": "Terroir: Climate & Soil", "q": "A grey marl studded with small comma-shaped fossil oysters runs from Chablis northeast into the Aube and surfaces again on the Dorset coast. Name the geological stage.", "sa": 1, "accept": ["kimmeridgian", "kimmeridgian marl", "kimmeridgien", "kimmeridgian limestone"], "ans": "Kimmeridgian", "exp": "The stage is named for Kimmeridge in Dorset, and the little oyster is Exogyra virgula, which is why the soil is sometimes described by the fossil rather than the age. The younger Portlandian limestone lying above it is harder and purer and gives a leaner, less generous wine, and the boundary between the two is argued over vineyard by vineyard."},
{"id": "c-jj8hsh1r", "cat": "Terroir: Climate & Soil", "q": "A brilliant white soil in Jerez crusts over as it dries, sealing the winter rain beneath it through a rainless summer. Name that soil.", "sa": 1, "accept": ["albariza", "albariza soil", "albarizas", "albariza chalk"], "ans": "Albariza", "exp": "The crust cuts evaporation from a profile that may hold most of a year's water by March, in a region that will get almost none between May and September. Its whiteness does a second job, bouncing light back into a low canopy, and the clay barros and the sandy arenas around it do neither well."},
{"id": "c-fy8xti6w", "cat": "Terroir: Climate & Soil", "q": "Deep gravel banks were chosen in the Medoc for reasons that have nothing to do with what the stones contain. Which reason?", "opts": ["They are the one soil phylloxera cannot enter", "They are unusually rich in potassium", "They drain fast and warm quickly", "They hold water far into a dry summer"], "a": 2, "exp": "Gravel is chemically close to inert; its contribution is physical. Fast drainage forces roots deep to find the clay beneath, and a stony surface warms early and stays warm, which is precisely what a variety that ripens late and hates wet feet needs."},
{"id": "c-jekizo8c", "cat": "Terroir: Climate & Soil", "q": "Planted on heavy clay, an early-ripening variety comes in later and fleshier than the same variety on the gravel next to it. Which property of clay causes the delay?", "opts": ["It confines roots to the top twenty centimetres", "It holds water and warms slowly", "It reflects light back into the canopy", "It raises soil pH sharply"], "a": 1, "exp": "Water has a high heat capacity, so a wet soil takes far longer to warm than a dry stony one, the root zone stays cold well into spring and the whole cycle from budbreak onward is pushed back. The same water reserve is what fills the berry and gives the wine its flesh, so the delay and the texture arrive together."},
{"id": "c-fw8ciiuo", "cat": "Terroir: Climate & Soil", "q": "Ungrafted vinifera survives in a handful of European pockets where every neighbouring vineyard had to be replanted on American roots. Which soil explains those pockets?", "opts": ["Heavy clay, which is airless", "Chalk, whose high pH kills the louse", "Deep sand the louse cannot cross", "Volcanic ash, which is sterile"], "a": 2, "exp": "Phylloxera needs to tunnel through soil to reach roots, and sand collapses behind it so the galleries cannot hold. The protection is a matter of physics rather than chemistry, and it fails as soon as the sand is mixed with enough silt or clay to hold a structure."},
{"id": "c-57evzatn", "cat": "Terroir: Climate & Soil", "q": "Wind-blown silt piled up during the ice ages gives deep, pale, free-draining soils that are easy to work, along the Danube and in eastern Washington. Name that material.", "sa": 1, "accept": ["loess", "loess soil", "aeolian loess", "loess deposit"], "ans": "Loess", "exp": "Loess is a windborne dust deposit, so its particles are uniformly fine and unsorted by water, which is why it stands in vertical faces when cut and why it drains well despite being fine-grained. It is fertile and deep, so vigour rather than drought is the problem it sets a grower."},
{"id": "c-2vk2rxzo", "cat": "Terroir: Climate & Soil", "q": "A thin layer of iron-stained red clay sitting straight on a limestone pan is the whole of Coonawarra's reputation. Name that soil.", "sa": 1, "accept": ["terra rossa", "terra rosa", "terra rossa soil", "red earth over limestone"], "ans": "Terra rossa", "exp": "The red comes from iron oxide left behind as the limestone beneath weathers away, and the layer is often only a few tens of centimetres deep. Its value is the combination of a shallow warm rooting zone above a limestone reservoir the roots can crack into, and the strip where it occurs is narrow enough to be mapped by colour from the road."},
{"id": "c-5sbnyeyd", "cat": "Terroir: Climate & Soil", "q": "The Medoc's gravel was not laid down by the Gironde itself: ice-age rivers carried it from the Pyrenees and the Massif Central. What is the general term for a river-laid deposit of that kind?", "sa": 1, "accept": ["alluvium", "alluvial deposit", "alluvial gravel", "alluvial", "fluvial deposit"], "ans": "Alluvium", "exp": "Alluvium is anything a river drops when it loses the energy to carry it, and the coarsest material travels furthest only when the flow is strongest. Successive glacial melt pulses laid the Medoc terraces at different heights, which is why the oldest and highest gravel banks are also the poorest and the most highly rated."},
{"id": "c-o8ez64tu", "cat": "Terroir: Climate & Soil", "q": "Blue-black slate on a Mosel slope stores heat, and the way the rock has fractured does a second job for a region living on the edge of ripening. What is that second job?", "opts": ["Rain drains through the fissures and roots follow", "It supplies nitrogen to the vine", "It shields the fruit from ultraviolet light", "It buffers the soil to a high pH"], "a": 0, "exp": "Slate splits along cleavage planes, so a weathered slope is a mass of tilted plates with routes between them. Water disappears fast and roots go a long way down, which is how vines on a slope with almost no soil survive a dry summer; the rock is acidic, so any talk of high pH belongs to limestone instead."},
{"id": "c-w2i16ymz", "cat": "Terroir: Climate & Soil", "q": "Weathered granite gives a coarse, pale, acidic sand that is quick to warm and holds very little. Which consequence for the vine follows most directly?", "opts": ["Restrained vigour and small berries", "A pronounced delay in budbreak", "High vigour and large berries", "Chlorosis from excess active lime"], "a": 0, "exp": "Granite weathers into gruss, a gritty sand with poor water and nutrient holding, so the vine is naturally held in check without any intervention. It is acidic ground, so lime-induced chlorosis is the one disorder it will not produce, and rootstocks chosen for granite are picked for drought tolerance rather than lime tolerance."},
{"id": "c-n041mrkw", "cat": "Terroir: Climate & Soil", "q": "Volcanic soils get the credit for smoke and salinity in the glass, but their reliable agronomic advantage is a good deal more prosaic. What is it?", "opts": ["They are deep and free-draining but still hold water", "They are strongly alkaline", "They suppress fungal disease in the canopy", "They are rich in both nitrogen and available phosphorus"], "a": 0, "exp": "Ash and pumice weather into a light, open profile that takes water in fast and gives it back slowly, which is a rare combination. Fresh ejecta carry almost no nitrogen, and the allophane that forms as they weather binds phosphate so hard that phosphorus availability is the classic limit on volcanic ground; the flavour claims made for these soils are far harder to demonstrate than the drainage is."},
{"id": "c-88611nvd", "cat": "Terroir: Climate & Soil", "q": "Slate taken deeper, under more heat and pressure, recrystallises into a coarser rock whose mica flakes catch the light, and it carries Priorat and the Douro. Name it.", "sa": 1, "accept": ["schist", "schist rock", "mica schist", "metamorphic schist"], "ans": "Schist", "exp": "Slate, schist and gneiss are one metamorphic sequence at increasing grade, so the practical difference is grain size and how the rock breaks. Schist splits into plates a root can force apart, which is what lets vines reach water through several metres of rock in regions with almost no summer rain. Priorat's llicorella sits nearer the slate end of that sequence and is called schist in the trade anyway, which is a fair warning that vineyard soil names are usage rather than petrology."},
{"id": "c-k85n3zdx", "cat": "Terroir: Climate & Soil", "q": "A dark soil and a pale soil take in the same sunshine, and the dark one runs several degrees warmer at the surface. Name the measurable property that differs.", "sa": 1, "accept": ["albedo", "reflectivity", "surface albedo", "solar reflectance"], "ans": "Albedo", "exp": "Albedo is the fraction of incoming radiation a surface throws back, so a low-albedo dark soil converts more of it into heat and a high-albedo pale one returns it. The returned light is not wasted: chalk and albariza bounce it up into a low canopy, which is a real advantage where the sun angle is poor or the vines are trained close to the ground."},
{"id": "c-6s64nam3", "cat": "Terroir: Climate & Soil", "q": "Mild water shortage after veraison is sought deliberately in red wine vineyards rather than avoided. What does the shortage do to the berry?", "opts": ["Skins thin, so colour extracts faster", "A second flowering is triggered", "Malic acid rises sharply", "Berry expansion stops early"], "a": 3, "exp": "A berry that stops swelling ends up small, so its skin-to-pulp ratio is high and there is proportionally more colour and tannin per unit of juice. Timing is the whole art: a deficit before veraison works on shoot growth and berry size rather than on ripening, and a severe one at any stage shuts photosynthesis down and leaves the fruit unripe."},
{"id": "c-u5kdwqn4", "cat": "Terroir: Climate & Soil", "q": "Fruit buried in an over-large canopy stays herbaceous even in a warm season. Which soil description most often lies behind a canopy like that?", "opts": ["A coarse sand with almost no organic matter", "Fertile and deep, with a reliable water supply", "A very high active-lime content", "A shallow stony profile over fractured rock"], "a": 1, "exp": "Water and nitrogen together drive shoot growth, and a vine that keeps growing after veraison shades its own fruit and competes with it for sugar. Shaded bunches keep their methoxypyrazines and never build colour, which is why vigour control on rich sites matters more than any cellar decision taken afterwards."},
{"id": "c-vbpxowg9", "cat": "Terroir: Climate & Soil", "q": "Not all the water a soil holds is available to the vine. Which pair of measurements brackets the portion that is?", "opts": ["Bulk density and total porosity", "Cation exchange capacity and soil pH", "Surface albedo and infiltration", "Field capacity and permanent wilting point"], "a": 3, "exp": "Field capacity is what a soil retains after gravity has drained it; the permanent wilting point is where the remaining water is held too tightly for roots to extract. The gap between them is the reserve a vine can actually draw on, and it is why a deep clay can carry a vine through a drought that kills one on shallow gravel."},
{"id": "c-6aj8kbd5", "cat": "Terroir: Climate & Soil", "q": "Clay's ability to hold nutrients as well as water comes from an electrical charge on the surface of its platelets, and soil analysis reports it as a single figure. Name that figure.", "sa": 1, "accept": ["cation exchange capacity", "cation exchange", "cation exchange capacity of the soil", "cation exchange capacity cec", "base exchange capacity", "cec"], "ans": "Cation exchange capacity", "exp": "Clay platelets carry a net negative charge, so they hold positively charged nutrients such as potassium, calcium and magnesium against being washed out. Sand and gravel have almost none of it, which is why nutrition on a gravel bank has to be managed rather than assumed and why clay is the fertility half of any soil description."},
{"id": "c-6e6g9pm1", "cat": "Terroir: Climate & Soil", "q": "Water is applied at less than the vine's full demand from fruit set onward, holding it under mild stress rather than relieving it. Name that irrigation strategy.", "sa": 1, "accept": ["regulated deficit irrigation", "deficit irrigation", "controlled deficit irrigation", "regulated deficit", "regulated deficit irrigation rdi", "rdi"], "ans": "Regulated deficit irrigation", "ex": 1, "exp": "The point is to keep the vine slightly short of water at the stages when shoot growth should stop, then hold it there rather than letting it swing between drought and flood. It demands real measurement, whether by soil probe or by reading the vine's own water status, because the margin between useful stress and shutdown is narrow."},
{"id": "c-wbl4uhgq", "cat": "Terroir: Climate & Soil", "q": "A block on very high active lime yellows between the veins year after year, and replanting is the only remedy left. Which rootstock property should the new vines be chosen for?", "opts": ["The ability to confer high vigour", "Tolerance of active lime", "Drought tolerance", "Nematode resistance"], "a": 1, "exp": "Lime tolerance is a species trait: Vitis berlandieri evolved on Texan limestone and carries it, while riparia and rupestris parentage does not. That is why chalk and limestone regions plant a narrow group of berlandieri crosses, and why importing a rootstock that performs well on granite is a reliable way to produce a chlorotic vineyard."},
{"id": "c-mroc35fq", "cat": "Terroir: Climate & Soil", "q": "Replanting a deep, fertile, irrigated site is one of the few situations where a high-vigour rootstock is the wrong call. Which of these is the vigorous choice to avoid?", "opts": ["Riparia Gloire", "420A", "101-14", "110R"], "a": 3, "exp": "110 Richter is a berlandieri and rupestris cross bred for drought tolerance and deep rooting, and it pushes growth hard on a site that does not need pushing. Riparia Gloire, 420A and 101-14 are all low-vigour rootstocks, which is exactly what a rich, well-watered soil calls for."},
{"id": "c-lzcqpkro", "cat": "Terroir: Climate & Soil", "q": "Sandy soils suit a family of microscopic roundworms that feed on vine roots, the worst of which also carry fanleaf virus between them, and rootstock choice is the standard defence. Name the pest.", "sa": 1, "accept": ["nematodes", "nematode", "root knot nematodes", "dagger nematodes", "xiphinema", "xiphinema index"], "ans": "Nematodes", "exp": "Root-knot nematodes damage the root system directly, while the dagger nematode does its real harm as a vector for grapevine fanleaf virus. Sand is the classic problem soil because the pest moves through it easily, which is the irony of a soil that keeps phylloxera out."},
{"id": "c-a2fk9ht0", "cat": "Terroir: Climate & Soil", "q": "Vines take up almost none of what a taster calls minerality, which is the strongest objection to reading terroir straight off a geological map. Which account does the evidence support instead?", "opts": ["Soil acts on wine through water supply and vigour", "Flavour compounds pass from stone into the berry through the leaves", "Dissolved rock travels up the sap and reaches the glass directly", "Soil has no measurable effect on the finished wine"], "a": 0, "exp": "Mineral ions taken up by the root are present in wine at concentrations far below any sensory threshold, so the stone is not being tasted. What the soil demonstrably controls is how much water and nitrogen the vine gets and therefore how vigorous it is, and vigour drives berry size, canopy density and ripeness, which are tasted very clearly indeed."},
{"id": "c-wrsx696m", "cat": "Terroir: Climate & Soil", "q": "European law folds into terroir something that is neither weather nor rock: the accumulated local decisions about variety, training, pruning and picking date. Name that component.", "sa": 1, "accept": ["human factor", "human element", "savoir faire", "the human component"], "ans": "The human factor", "exp": "The INAO definition explicitly includes human practices, which is why an appellation can specify pruning method and yield alongside its boundary. It also settles an old argument honestly: a delimitation records where growers have historically succeeded, so the map is partly a record of human choice rather than a pure reading of the ground."},
{"id": "c-2xwxdyrb", "cat": "Terroir: Climate & Soil", "q": "Of everything gathered under the word terroir, one component has by far the largest measured effect on wine style, and it is not the rock. Name it.", "sa": 1, "accept": ["climate", "climate of the site", "site climate", "growing season climate"], "ans": "Climate", "ex": 1, "exp": "Move a variety across a growing season temperature band and the wine changes beyond recognition; move it across a soil type within one climate and the change is real but far smaller. Soil earns its reputation because within a single climate it is the variable that remains, which is exactly the situation on a Burgundian slope where every other factor is held constant."},
{"id": "c-cgbw3uqu", "cat": "Viticulture & Winemaking", "q": "Neither post nor wire runs through an old Grenache vineyard on a windy, rainless Mediterranean plain, and the growers see no reason to change. What is the free-standing bush buying them?", "opts": ["A vine that carries itself, shades its own fruit and stands up to the wind, with nothing spent on posts or wire", "Faster ripening, because a free-standing bush exposes every bunch to full sun", "A larger crop than any trellised row could ripen, since every arm of the head is free to fruit", "Rows a mechanical harvester can straddle at speed, with no wires to snag its beaters on the way through"], "a": 0, "exp": "Gobelet suits the dry and the windswept: a low, self-supporting head shrugs off gusts that would strain a trellis, and its umbrella of foliage keeps the worst of the sun off the bunches in a drought year. The costs are the mirror image - modest yields, awkward mechanisation, and in a damp climate a huddled canopy that invites rot - which is why the system stays southern."},
{"id": "c-rar7x59l", "cat": "Viticulture & Winemaking", "q": "Every winter a pair of one-year canes is bent along the fruiting wire, one to each side of the head, and the rest of the wood is cut away. Name that training.", "sa": 1, "accept": ["double guyot", "guyot double", "the double guyot system", "double guyot training", "double guyot cane training"], "ans": "Double guyot", "exp": "Guyot in either form is cane pruning: no permanent arm, the whole fruiting structure rebuilt from scratch each winter. The double form spreads the crop across two canes and suits wider spacing, which is why the Medoc classically trains it, while the single-cane form carries a smaller load on one wire and is the Cote d'Or's habit."},
{"id": "c-ft4jwsrq", "cat": "Viticulture & Winemaking", "q": "One permanent horizontal arm carries a row of short spurs, and Champagne leans on it to hold Pinot Noir's natural yield down. Name the system.", "sa": 1, "accept": ["cordon de royat", "royat", "the cordon de royat system", "cordon de royat training", "en cordon de royat", "trained en cordon de royat", "single cordon de royat", "royat cordon"], "ans": "Cordon de Royat", "ex": 1, "exp": "The permanent cordon stores old wood and metes the vine out through spurs, which restrains vigour and holds the fruiting zone at one even height. Champagne permits four trainings and reaches for this spur-pruned one chiefly for its black grapes; a hard winter is its weakness, since a killed cordon takes years to rebuild where a cane system simply starts again."},
{"id": "c-cdfdacg5", "cat": "Viticulture & Winemaking", "q": "Splitting one over-vigorous canopy down the middle, a trellis lifts the shoots in twin tilted curtains with a corridor of light between them. Name it.", "sa": 1, "accept": ["lyre", "the lyre system", "lyre trellis", "lyre training", "open lyre"], "ans": "Lyre", "exp": "The divided canopy is an answer to fertile ground: rather than fight vigour, it doubles the leaf wall and opens the middle so light reaches fruit on both faces. Alain Carbonneau developed it in Bordeaux for exactly the deep soils that overwhelm a single curtain, and its price is a wide, expensive trellis that most machines cannot straddle."},
{"id": "c-9oopzjj0", "cat": "Viticulture & Winemaking", "q": "From Marlborough to Alsace the default trellis is the same: shoots tucked upward between paired foliage wires into one narrow green wall. Give its name.", "sa": 1, "accept": ["vertical shoot positioning", "vsp", "vertical shoot positioning vsp", "vertical shoot position", "vertical positioning", "vsp trellis", "vertical shoot positioning trellis", "vertically shoot positioned"], "ans": "Vertical shoot positioning (VSP)", "exp": "One flat wall presents the fruit at a fixed height for spraying, trimming and machine picking, which is why it swept the world's moderate-vigour vineyards. Its limit is the same as its virtue: on rich ground a single plane cannot carry the growth, the wall stuffs itself with shade, and that is where the divided systems begin to pay."},
{"id": "c-pr2h9gq2", "cat": "Viticulture & Winemaking", "q": "Cool, rain-fed and lime-free: a grower replanting close-set Pinot Noir on deep loam asks the nursery for modest vigour and an early cycle. Which rootstock answers the brief?", "opts": ["1103 Paulsen", "3309 Couderc", "140 Ruggeri", "110 Richter"], "a": 1, "exp": "3309C is a riparia and rupestris cross that damps growth and brings the fruit in early, which is what a cool site and close spacing want; in return it asks for reliable water and tolerates little active lime (about ten per cent), neither of which troubles this site. The other three are berlandieri and rupestris crosses built for drought and heat, and on a deep, watered soil they push growth the site never asked for."},
{"id": "c-0rrhd4br", "cat": "Viticulture & Winemaking", "q": "Pure chalk with active lime beyond what almost any rootstock can stand made Champagne settle on a berlandieri cross whose other parent is a fruiting vinifera, Chasselas. Name it.", "sa": 1, "accept": ["41b", "41 b", "rootstock 41b", "41b rootstock", "41 b rootstock", "41b millardet et de grasset", "millardet et de grasset 41b", "41b mgt", "mgt 41b"], "ans": "41B", "ex": 1, "exp": "The vinifera half lifts its tolerance to roughly forty per cent active lime, far beyond the standard catalogue, and the berlandieri half brings enough phylloxera resistance for chalk, where the louse is in any case less aggressive. It is the price of the ground: a conventional American cross yellows and fails on such soils, so nearly the whole region sits on this one stock."},
{"id": "c-u9egle7b", "cat": "Viticulture & Winemaking", "q": "Out of Sigmund Teleki's berlandieri-riparia seedlings, a German viticultural school selected the workhorse stock that now fills nursery catalogues worldwide, and its initials record the school's town. Give the designation.", "sa": 1, "accept": ["so4", "so 4", "selection oppenheim 4", "selection oppenheim no 4", "selection oppenheim number 4", "oppenheim 4", "so4 rootstock", "rootstock so4", "oppenheim selection 4", "s o 4", "selektion oppenheim 4", "selektion oppenheim no 4"], "ans": "SO4", "ex": 1, "exp": "Selection Oppenheim 4 took Teleki's Hungarian material and fixed a stock that grafts easily, takes most soils and advances ripening, which is what made it the default order. Its habits still matter at the margin: it roots shallow and runs thirsty in drought, and it is notorious for magnesium deficiency on light soils, which is why the default is not universal."},
{"id": "c-ss6ahhuh", "cat": "Viticulture & Winemaking", "q": "Instead of ordering a thousand plants of one certified number, a grower spends the winter tagging his own best old vines and has the nursery graft cuttings from all of them. Name the practice.", "sa": 1, "accept": ["massal selection", "selection massale", "mass selection", "massale selection", "massal", "massale", "field selection"], "ans": "Massal selection", "exp": "The bet is diversity: dozens of subtly different vines ripen, crop and fail differently, which steadies the whole block and keeps traits no single clone carries. The risk travels with the wood, since a tagged mother vine passes its viruses on, which is why serious estates test the marked vines before a knife touches them."},
{"id": "c-0i9hmyl0", "cat": "Viticulture & Winemaking", "q": "Rather than pull out a healthy vineyard of the wrong grape, the crew saws every vine back in spring and grafts buds of the new variety onto the established trunks, cropping again the season after. Name the operation.", "sa": 1, "accept": ["top working", "top work", "top grafting", "field grafting", "grafting over", "graft over", "grafting the vineyard over", "reworking the vineyard", "vineyard reworking", "t budding", "chip budding", "changing variety by grafting"], "ans": "Top-working", "exp": "The roots and trunk stay, so the vine carries a small crop of the new variety in its second season, against the three or four barren years a replant costs. The trade is a graft union out in the weather on every single vine: takes fail, and a botched pass leaves a vineyard that is neither one thing nor the other."},
{"id": "c-g8beeudi", "cat": "Viticulture & Winemaking", "q": "A June walk shows an obvious overcrop, yet the estate books its dropping pass for the week the berries turn colour. What does the delay buy?", "opts": ["Discarded fruit ripe enough to be sold off in bulk at the gate, so the pass pays for a share of its own labour instead of none of it", "Sweeter fruit left hanging, as sugar drains back out of the cut bunches into the vine", "A quicker job for the crew, since coloured bunches twist free of the shoot by hand where green ones must be cut", "A vine past compensating by swelling what it keeps, and laggard bunches that show themselves against the coloured crop"], "a": 3, "exp": "Thinned early, a vine simply redirects into the crop it keeps, and berry size swells until much of the yield returns; at veraison that door is closing, and the bunches still green against coloured neighbours identify themselves as the ones to cut. The pass is priced accordingly - it is paid-for fruit dropped on the ground - which is why the decision is argued every year it is made."},
{"id": "c-jwib4l8j", "cat": "Viticulture & Winemaking", "q": "Morning-side leaves come off the fruiting zone in a hot region while the western face of every row keeps its cover. Which injury is the kept canopy there to prevent?", "sa": 1, "accept": ["sunburn", "sun burn", "sunscald", "sun scald", "sunburn of the fruit", "berry sunburn", "fruit sunburn", "sunburn damage", "sunburnt fruit", "sunburned fruit", "sun scorch", "sun scorching"], "ans": "Sunburn", "exp": "East-facing fruit meets gentle light in the cool of the morning; the west side takes full sun in mid-afternoon, when air and berry are already at the day's peak heat, and exposed bunches cook. Stripping only the morning side buys the airflow and spray penetration the grower wanted while the afternoon face keeps its parasol, at no cost beyond telling the crew which side is which."},
{"id": "c-td9x0v0j", "cat": "Viticulture & Winemaking", "q": "Pulled at fruit set rather than at ripeness, fruiting-zone leaves leave the young berries in full light from the start, and their skins quietly prepare for the summer ahead. Name that response.", "sa": 1, "accept": ["acclimatisation", "acclimatization", "acclimation", "sun acclimatisation", "sun acclimatization", "sun acclimation", "hardened", "hardening", "sun hardening", "hardening off", "skin hardening", "the skins acclimatise", "they acclimatise", "acclimatising", "acclimatizing", "uv acclimation", "acclimatise", "acclimatize", "acclimatised", "acclimatized", "the berries acclimatise", "the skins harden"], "ans": "Acclimatisation", "exp": "Skins exposed young thicken their cuticle and load protective pigments against ultraviolet, so the heat spike of the ripening weeks finds fruit already dressed for it. Unveil a shaded bunch at veraison and it has none of that armour, which is why the calendar of a leaf-pull matters as much as the fact of one."},
{"id": "c-1rlk4mk5", "cat": "Viticulture & Winemaking", "q": "Weeks after budbreak, workers walk the rows rubbing surplus young shoots off head and trunk while the wood is still soft. Name the operation.", "sa": 1, "accept": ["shoot thinning", "shoot thinning ebourgeonnage", "ebourgeonnage", "disbudding", "debudding", "desuckering", "suckering", "epamprage", "bud rubbing", "shoot removal", "removing surplus shoots", "thinning the shoots", "removing shoots", "rubbing off shoots", "shoot thinning disbudding"], "ans": "Shoot thinning (ebourgeonnage)", "ex": 1, "exp": "It is the cheapest yield and balance decision of the year: a shoot rubbed off in spring costs a thumb's pressure, while the same correction made months later means cutting hardened wood or dropping grown fruit. The pass also chooses the vine's shape, since every shoot kept is a candidate cane or spur for next winter."},
{"id": "c-z9uw2j41", "cat": "Viticulture & Winemaking", "q": "High summer finds a tractor shearing the tops and sides of every row where shoots have overgrown the wires and begun to flop. Name that operation.", "sa": 1, "accept": ["hedging", "rognage", "trimming", "shoot trimming", "summer trimming", "canopy trimming", "topping", "summer pruning", "hedging the canopy", "ecimage"], "ans": "Hedging (rognage)", "exp": "A flopping canopy shades its own fruiting wire, so the trim keeps the wall upright and the light where it belongs, and it stops the vine spending on tips that no longer feed the bunches below. It is not free of consequence: every pass provokes lateral shoots, so a warm wet year can put the machine through four times, and each pass is diesel and hours."},
{"id": "c-y3pdmsgq", "cat": "Viticulture & Winemaking", "q": "Minute by minute as the cycle climbs, the cellar master stands at the pan below the press tasting the Chenin as it runs. What is the tasting deciding?", "opts": ["Whether the load was ripe enough to be pressed at all, before the house commits the rest of the picking bins behind it", "How much rainwater the fruit took on board in the final week, and so how far the juice will need concentrating", "When the last of the sugar has been squeezed from the skins, which is the signal that the press can finally stop and open", "Where one fraction ends and the next begins, as the juice turns broader, coarser and more phenolic"], "a": 3, "exp": "Early juice runs bright and delicate and the late squeeze turns broad and grippy, and no gauge reads that transition as reliably as a mouth. The cut diverts the flow to a separate tank, which keeps the decision reversible: fractions kept apart can be reunited at blending, while a coarse tail let into the fine tank can never be taken out again."},
{"id": "c-0qj7ofum", "cat": "Viticulture & Winemaking", "q": "Days short of dryness, a couple of degrees Baume still on the gauge, a Syrah is pressed off its skins and run straight to barrel to finish. What is the cellar after?", "opts": ["More colour, since the skins give up their final charge of pigment only in the very last days before the wine falls dry", "A sweeter style, since pressing that early strands the last of the sugar in the wine unfermented", "A ferment that ends inside the wood, knitting the oak in while the wine is still warm and working", "Cleaner barrels at racking, because the yeast stay behind in the press with the skins rather than travelling"], "a": 2, "exp": "Finishing the last of the sugar in barrel puts the most active phase of yeast work inside the wood, and wines handled that way tend to swallow their oak rather than wear it. The cost is vigilance, because a barrel is a poor place to warm or feed a ferment that falters, so the cellar commits only wines it trusts to run dry."},
{"id": "c-hugx0wgh", "cat": "Viticulture & Winemaking", "q": "After the free-run has drained away, what the red press then yields is dark, structured and coarse, and it goes to a tank of its own under its own French name. Give that name.", "sa": 1, "accept": ["~vin de presse", "~vins de presse", "~vin de presses", "~vin de press", "~vin de pressee", "~press wine", "~press wines", "~press fraction", "~press fractions", "~pressed wine", "~pressed wines", "pressings"], "ans": "Vin de presse", "ex": 1, "exp": "One pressing can itself be split into first and hard fractions, each tasted on its own through the winter. The name matters at the blending bench: how much of it the final wine takes, and from which fraction, is decided cuvee by cuvee, and in a light year the answer is often more rather than less."},
{"id": "c-6o1bpnyz", "cat": "Viticulture & Winemaking", "q": "Fermentation done, the valve opens and the new wine drains away from the soaked skins by gravity before anything goes near the press. Give the French cellar term for that running-off.", "sa": 1, "accept": ["ecoulage", "decuvage", "devatting", "drawing off"], "ans": "Ecoulage", "exp": "What runs off under gravity is the vin de goutte, and everything the skins still hold goes to the press afterwards, so this is the moment the two identities part. Timing it is a real decision rather than housekeeping, because the day it happens ends the maceration as surely as any pressing schedule does."},
{"id": "c-ro3ojrrv", "cat": "Viticulture & Winemaking", "q": "Side by side in one cellar stand small open-top vats of delicate Pinot Noir and a sixty-tonne closed tank of contract Cabernet. Which cap regime belongs to which vessel?", "opts": ["Punch-downs for the small open Pinot vats, pump-overs for the sixty-tonne tank", "Pump-overs for the Pinot and punch-downs for the tank, since a plunger tells you more the bigger the cap it works", "Rack-and-return for the Pinot and nothing for the tank, whose sheer depth keeps the cap wet without any help", "Pump-overs for both wines, since one regime across the whole cellar keeps the crew on a single routine"], "a": 0, "exp": "A plunger is a gentle, human-scaled tool: it needs an open top and a cap it can actually reach through, which is what a small vat of delicate fruit offers, and putting the hose on that vat instead would work its fruit harder for nothing. At sixty tonnes no arm reaches anything, and the tank's own pump moving wine from valve to spray head is the cap work that scales, so the vessel and the wine's constitution make the choice together."},
{"id": "c-kc02esjj", "cat": "Viticulture & Winemaking", "q": "Lying on its side, a closed steel drum turns the whole red ferment on a programmed schedule, tumbling skins through wine with no cellar hand near it. Name the vessel.", "sa": 1, "accept": ["rotary fermenter", "rotary fermenters", "roto fermenter", "rotary fermentation tank", "rotary vinifier", "roto vinifier", "rotary fermentor", "roto fermentor", "rotary tank", "rotary drum fermenter", "rotating fermenter", "vinimatic"], "ans": "Rotary fermenter", "exp": "Tumbling is relentless, so extraction runs fast and complete, and one operator can run a battery of drums through a vintage, which is why the machine lives in high-volume red programmes. What it cannot do is be gentle: fruit meant for perfume and silk is worked far too hard in a drum, which is why the same building often keeps open vats standing beside them."},
{"id": "c-yras1m93", "cat": "Viticulture & Winemaking", "q": "Snapping and chewing a stem from every block, the winemaker sets this year's whole-bunch percentage only after the green has gone out of the wood. Name what the stems have done.", "sa": 1, "accept": ["lignification", "lignified", "stem lignification", "lignifying", "become lignified", "turned woody", "gone woody", "become woody", "stem ripening", "stem ripeness", "ripened"], "ans": "Lignification", "exp": "Green stems trade in bitterness and a vegetal edge; brown, woody ones give the spice, lift and structural frame that make cluster work worth doing at all. That is why the number is set vat by vat and year by year rather than by recipe, and why a cold season can push a habitual sixty per cent down to twenty."},
{"id": "c-449qz9ys", "cat": "Viticulture & Winemaking", "q": "Twice a day through the ferment, someone floats a weighted glass spindle in a cylinder of must and charts how deep it sits. Name the instrument.", "sa": 1, "accept": ["hydrometer", "densimeter", "density meter", "mustimeter", "saccharometer", "areometer"], "ans": "Hydrometer", "exp": "Density falls as sugar becomes alcohol, so the readings draw the fermentation curve, and a curve that flattens early is the first warning of a ferment about to stick. The refractometer that served at picking is useless here, because alcohol bends light on its own account and wrecks the reading."},
{"id": "c-0vbo2xfb", "cat": "Viticulture & Winemaking", "q": "Less grip from the wood but more roast and spice in the nose: a winemaker orders the same barrels a level darker in toast. Why is that order not a contradiction?", "opts": ["Toast and tannin come from different staves in the barrel, blended to order by the cooper", "Deep toasting breaks the wood's own tannins down even as it cooks up the roasted aromatics", "The longer fire dries the staves far harder, and bone-dry wood keeps its tannin locked away from the wine", "Darker toast chars a seal onto the inside of the stave, so the wood gives the wine nothing at all"], "a": 1, "exp": "Fire degrades the tannins in the surface layers of the stave while it cooks sugars and lignin into vanilla, spice and smoke, so grip and toast character move in opposite directions as the flame runs longer. The same toast scale is quoted on the chips and staves the EU cleared in 2006, which sell the flavour spectrum without the barrel or its slow oxygen, at a fraction of the cost."},
{"id": "c-w0noct4y", "cat": "Viticulture & Winemaking", "q": "Planted on Colbert's orders to grow ship timber for the navy, one forest in the Allier now sells the slowest-grown, finest-grained oak a cooper can buy. Name it.", "sa": 1, "accept": ["troncais", "foret de troncais", "troncais forest", "troncais oak"], "ans": "Troncais", "exp": "The plantation outlived the age of sail and became cooperage's benchmark: sessile oak crowded tight on poor soil grows slowly, and slow growth lays down the narrow rings that release aroma and tannin gently over an elevage. Bought stave by stave, the name on the invoice is as much a price as a place."},
{"id": "c-ry9iqu3v", "cat": "Viticulture & Winemaking", "q": "Fast-grown pedunculate oak from one region of western France is so wide-ringed and tannin-rich that fine-wine coopers pass it over, and the brandy houses take nearly the whole harvest. Name the region.", "sa": 1, "accept": ["limousin", "limousin oak", "limousin forest", "limousin region"], "ans": "Limousin", "exp": "Open stands on richer ground grow fast, and fast growth means wide rings, coarse grain and a heavy load of extractable tannin, which is an asset in a spirit that will sit in wood for decades and a liability in most wine. Cognac's cellars absorb the supply, which is why the name appears far more often on a brandy specification than on a wine cellar's barrel bill."},
{"id": "c-yd9ghjfm", "cat": "Viticulture & Winemaking", "q": "Stacked in open pallets in the cooper's yard, rough-sawn staves sit under rain, sun and frost for a couple of years before a saw or a flame touches them. Name that stage.", "sa": 1, "accept": ["seasoning", "air seasoning", "open air seasoning", "natural seasoning", "air drying", "open air drying", "weathering", "stave seasoning", "seasoning the staves", "yard seasoning"], "ans": "Seasoning", "exp": "The yard does two jobs at once: the wood dries to workable moisture, and rain and resident fungi leach and soften the harshest of its raw tannins, mellowing what the barrel will later give. A kiln can manage only the first job in a fraction of the time, which is why yard-seasoned wood commands the premium and specifications quote the months spent out in the weather."},
{"id": "c-71ptmz2m", "cat": "Viticulture & Winemaking", "q": "More than double a barrique in one cask, the 500-litre format lets Syrah producers buy oak's slow breathing without its vanilla shouting. Name the format.", "sa": 1, "accept": ["puncheon", "puncheons", "puncheon cask", "puncheon casks", "puncheon barrel", "puncheon barrels"], "ans": "Puncheon", "exp": "More than doubling the volume cuts the wood surface each litre of wine touches by roughly a quarter, so flavour and oxygen both arrive at a gentler pace and the fruit stays in front. Syrah cellars from the northern Rhone to the Barossa lean on the size for exactly that restraint, often buying it new where a new barrique would shout."},
{"id": "c-doqzv6kv", "cat": "Viticulture & Winemaking", "q": "Creamy and broad by the new year, the barrels of Chardonnay lose their weekly stirring, and the rod is put away until the next vintage. What is the cellar protecting by stopping?", "opts": ["The lees themselves, which too much stirring would exhaust long before the wine has taken everything they have to give", "The malolactic bacteria, which the rod would scatter before the conversion has run its course", "The acid line and the aromatic lift, which every further pass of the rod would trade away for breadth", "The staves, which the rod scores a little more with every pass until the barrel begins to weep"], "a": 2, "exp": "Stirred lees keep feeding texture, and past a point the wine grows broader than it is long, so the stopping date is a style decision made by taste rather than by calendar. Each pass also lifts the oxygen the wine sees, and a barrel roused too long and too often ends up rounder, deeper in colour and shorter-lived than the wine the vineyard sent in."},
{"id": "c-3abj3ct8", "cat": "Wine Fundamentals", "q": "Analysed the week after picking and again after two years in barrel, one of a red's acids still anchors both reports while the others have vanished or appeared, and the only thing that has taken any of it is a cold cellar. Which property of that acid accounts for it?", "opts": ["Neither the yeast nor the malolactic bacteria consume it", "The yeast regenerate it as fast as the bacteria remove it", "It is the only acid the vine puts into the berry at all", "It cannot dissolve at cellar temperature"], "a": 0, "exp": "Tartaric acid is the one the cellar's microbes leave alone, which is why it anchors a wine's acidity while malic disappears and lactic appears. What it does lose goes into crystals of potassium bitartrate on the coldest nights rather than into any organism, so the figure eases rather than collapses. The exception is a spoilage organism rather than a working one: certain Lactobacillus will degrade tartaric in a neglected, high-pH wine, and the resulting flat, dull fault is old enough to have a name of its own in French cellars."},
{"id": "c-j96rr81x", "cat": "Wine Fundamentals", "q": "Fermentation leaves behind an acid the grape never carried, and tasters meet it as a bitter, faintly salty edge under the fruit of a dry wine. Name that acid.", "sa": 1, "accept": ["succinic acid", "succinic", "succinate"], "ans": "Succinic acid", "exp": "Yeast make it in quantity during the alcoholic ferment, typically around a gram a litre, and no amount of it comes in on the fruit. Its taste is unlike the other acids in the glass, closer to a savoury salinity than to sourness, which is part of why a fermented drink tastes different from sweetened acidified juice."},
{"id": "c-9fdblnkp", "cat": "Wine Fundamentals", "q": "Adding one of the minor grape acids to a red before its bacterial conversion is a bad idea, because the bacteria break it down into vinegar and a buttery ketone. Name the acid that must not be there.", "sa": 1, "accept": ["citric acid", "citric", "citrate", "citric acid c6h8o7"], "ans": "Citric acid", "ex": 1, "exp": "The grape carries only a few tenths of a gram a litre of it, and lactic acid bacteria metabolise what there is into acetic acid and a strongly buttery by-product. That is why the addition is made after the conversion has finished, if at all, and why it is used more often to hold iron in solution than to sharpen a wine."},
{"id": "c-w6iocbf3", "cat": "Wine Fundamentals", "q": "Steam driven through a wine carries one of its acids over into the distillate and leaves the rest behind, which is why the laboratory reports that one on a line of its own. Name it.", "sa": 1, "accept": ["acetic acid", "acetic", "ethanoic acid", "ethanoic", "acetic acid vinegar", "acetic acid ethanoic acid", "ethanoic acid acetic acid", "acetic acid ch3cooh", "ch3cooh"], "ans": "Acetic acid", "ex": 1, "exp": "The distillable fraction is what a certificate calls volatile acidity, and acetic acid supplies almost all of it. Every sound wine holds a little, because the ferment itself makes some, and the legal ceilings sit far above that background but close to the point at which a taster starts calling a wine volatile, so the limit is a backstop against the undrinkable rather than a guarantee that the wine is clean."},
{"id": "c-06m3hqlt", "cat": "Wine Fundamentals", "q": "Six and a half grams per litre on the titration and 3.85 on the meter: the first figure looks healthy and the second is alarming. What is the meter reporting that the titration is not?", "opts": ["The share of the acidity contributed by the volatile acids", "The total weight of acid the wine contains", "The concentration of hydrogen ions actually free in the wine", "The proportion of the acid that has already precipitated"], "a": 2, "exp": "A titration neutralises every acid group in the sample and reports the total, whether those groups were doing anything or not. The meter reports only the hydrogen ions loose in solution, and that is the number that governs microbial stability, colour and how hard the preservative works, which is why a wine can be generously acidic on paper and defenceless in practice."},
{"id": "c-w8qh6t5h", "cat": "Wine Fundamentals", "q": "A hot-climate red comes back from the laboratory with respectable total acidity and a pH of 3.9, and the cause is a cation the vine drew out of the soil and packed into the fruit. Name that element.", "sa": 1, "accept": ["potassium", "potassium ion", "potassium ions", "potassium cation", "potassium cations", "element potassium", "potassium k", "k potassium", "k"], "ans": "Potassium", "ex": 1, "exp": "Potassium taken up by the vine neutralises part of the wine's acid, and a neutralised acid group is lost to the titration just as it is lost to the meter. What keeps the grams per litre respectable is that tartaric acid carries two acid groups and potassium takes only the first: the bitartrate ion left behind still holds the second, and the titration counts that one in full to its endpoint. So half the tartaric acidity survives the exchange, while the meter records the whole of the swing. Warm regions, high yields, shaded canopies and late picking all push potassium up, and none of them bring in extra acid to cover it, which is why acidification in such places is aimed at the meter and not at the titration."},
{"id": "c-82ruybr4", "cat": "Wine Fundamentals", "q": "An identical dose of tartaric acid moves one wine's pH by a fifth of a unit and another's by barely half that. Name the property of a wine that resists the change.", "sa": 1, "accept": ["buffering capacity", "buffer capacity", "buffering", "buffering power", "buffering ability", "high buffering capacity", "good buffering capacity", "strong buffering capacity", "high buffer capacity", "high buffering", "buffering capacity of the wine", "the wine's buffering capacity", "its buffering capacity", "buffering capacity buffer capacity", "it has a high buffering capacity", "the wine has a high buffering capacity", "the wine is well buffered", "well buffered", "buffering capacity is high", "buffer", "buffered", "it is well buffered", "the wine's buffer capacity", "its buffer capacity", "buffer capacity of the wine", "buffering effect", "buffer strength"], "ans": "Buffering capacity", "ex": 1, "exp": "A wine is a buffer because it holds weak acids alongside their own salts, and that pairing soaks up added hydrogen ions rather than letting them show on the meter. It is why acid trials are run on a bench sample rather than calculated, and why a heavily buffered wine can take a large addition and taste sharper without reading much lower."},
{"id": "c-yyq1vir0", "cat": "Wine Fundamentals", "q": "One red reads pH 3.4 and another pH 4.4. By what factor do their hydrogen ion concentrations differ? State the factor.", "sa": 1, "accept": ["tenfold", "ten fold", "ten times", "factor of ten", "by a factor of ten", "ten", "10", "10 times", "10 fold", "ten times higher", "ten times more", "ten times greater", "tenfold difference", "10 times higher", "10x", "x10", "factor of 10", "by a factor of 10", "10 times greater", "10 times more", "10 fold difference", "ten fold difference", "tenfold 10x", "order of magnitude", "one order of magnitude", "times ten", "times 10", "by ten", "by 10"], "ans": "Tenfold", "ex": 1, "exp": "The scale is logarithmic, so each whole unit is a decade and the gap between a fine white at 3.1 and a slack red at 4.1 is a factor of ten in the thing that actually matters. It also explains why cellar targets are argued over in hundredths: a shift of a tenth of a unit is a change of about a quarter in free hydrogen ions, which is enough to move both microbial risk and the working strength of any preservative added."},
{"id": "c-sejpnqvw", "cat": "Wine Fundamentals", "q": "Dropping a young red from pH 3.7 to pH 3.4 makes it look brighter and redder in the glass, and not one milligram of pigment has been added. What has the acid done to the colour?", "opts": ["Bleached the brown compounds that had been masking it", "Dissolved more pigment out of the suspended solids", "Bound the pigment onto tannin and deepened the hue", "Shifted the pigment into its red-coloured form"], "a": 3, "exp": "Anthocyanins exist as several forms in equilibrium, and only one of them is strongly red; acid conditions push the balance toward it and a rising pH pushes it back toward colourless and blue-tinged forms. This is why a high-pH red looks dull and slightly blue however much pigment it holds, and why acidification is a colour decision as much as a taste one."},
{"id": "c-rp804444", "cat": "Wine Fundamentals", "q": "Twenty years turn a red paler and softer at once, as pigment and tannin join into ever larger molecules that eventually fall out as sediment. Name that reaction.", "sa": 1, "accept": ["polymerisation", "polymerization", "polymerise", "polymerize", "polymerising", "polymerizing", "condensation", "condensation reaction", "tannin polymerisation", "tannin polymerization", "polymerisation of tannins", "polymerization of tannins", "they polymerise", "they polymerize", "the tannins polymerise", "the tannins polymerize", "polymerisation of tannin", "polymerization of tannin", "polymerization of pigment and tannin", "tannin condensation", "condensation of tannins", "polymerisation condensation", "polymerisation of pigment and tannin", "polymerisation and precipitation", "polymerisation and condensation", "polymerization and condensation", "condensation and polymerisation", "polymerised", "polymerized", "polymerisation reaction", "polymerization reaction", "tannin polymerisation and precipitation"], "ans": "Polymerisation", "ex": 1, "exp": "It takes a molecule with several points of attachment to bind the proteins that lubricate the mouth, so it is the mid-sized tannins that grip hardest and the single units that are merely bitter. Keep joining them and two things happen at once: pigment locks onto the chain and blunts its reactivity toward those proteins, and the chain eventually grows past the size at which it stays in solution and drops out of the wine altogether. The pigment goes with it, which is why softening and fading are one process rather than two, and why the deposit in an old bottle is coloured."},
{"id": "c-ltjxxw2u", "cat": "Wine Fundamentals", "q": "Condensed tannin is a chain of repeating flavan-3-ol units, and a single one of them free in the wine tastes bitter rather than astringent. Name that unit.", "sa": 1, "accept": ["catechin", "catechins", "epicatechin", "epicatechins", "catechin unit", "catechin units", "catechin monomer", "catechin monomers", "catechin and epicatechin", "epicatechin and catechin", "catechin or epicatechin", "single catechin", "monomeric catechin", "it is catechin", "that is catechin", "it is called catechin", "the unit is catechin", "the monomer is catechin", "catechin monomer unit"], "ans": "Catechin", "ex": 1, "exp": "Catechin and epicatechin, its epimer at the third carbon rather than its mirror image, are the building blocks, and the number of them strung together decides what the mouth feels: single units and pairs read as bitterness on the tongue, while chains of five or more are what dries the mouth. The chain is a mixture rather than one unit repeated, and its make-up is diagnostic: gallate esters ride on it, and skin tannin carries a fourth unit, epigallocatechin, that seed tannin does not. Bitterness and astringency therefore come from the same family of compounds at different sizes, which is why they can move in opposite directions as a wine ages."},
{"id": "c-agg8mhfn", "cat": "Wine Fundamentals", "q": "Squeezed hard at the end of the press cycle, a red picks up a green, bitter drying quality that a gentle cycle avoids altogether. Which fraction of the wine's tannin has just been added?", "sa": 1, "accept": ["seed tannin", "seed tannins", "grape seed tannin", "grape seed tannins", "pip tannin", "pip tannins", "seed derived tannin", "seed derived tannins", "tannin from the seed", "tannin from the seeds", "tannins from the seeds", "tannin from the pips", "tannins from the pips", "seed tannin fraction", "seed tannins fraction", "tannin fraction from the seeds", "tannins from the seed", "tannin from grape seeds", "tannins from grape seeds"], "ans": "Seed tannin", "ex": 1, "exp": "Seed tannins are smaller, more heavily decorated with gallic acid and markedly more bitter than the tannins in the skin, and the seeds only give them up once there is alcohol in the vat or a press has cracked them. It is why press fractions are kept apart and tasted before any of them is blended back, and why a slow press and an intact seed are worth the extra hours."},
{"id": "c-nhng7g13", "cat": "Wine Fundamentals", "q": "A fermenting vat gets measurably lighter as it works, because sugar leaves it as two products and only one of them stays in the wine. Which figure comes closest to the share of the sugar's weight that departs as gas?", "opts": ["About half of it", "Almost all of it, since the gas escapes and the liquid stays", "About a quarter of it", "Under a tenth"], "a": 0, "exp": "A molecule of sugar gives two of ethanol and two of carbon dioxide, and the two products come out at roughly the same weight, so close to half the sugar leaves the building. That is also why an enclosed fermentation hall is genuinely dangerous and why a sealed tank must be vented: the gas is heavy, invisible and produced by the tonne."},
{"id": "c-r7d5apwy", "cat": "Wine Fundamentals", "q": "Cellars turn grams of sugar per litre into potential alcohol by dividing by a single figure, close enough for planning a harvest. Give that divisor.", "sa": 1, "accept": ["about seventeen grams per litre", "seventeen grams per litre", "about 17 grams per litre", "17 grams per litre", "seventeen", "17", "about 17", "about seventeen", "roughly 17", "16 83", "17 g l", "17g l", "divide by 17", "divide by seventeen", "about 17 g l", "17 grams litre", "17 grams per litre of sugar", "seventeen grams of sugar per litre", "17 g per litre", "roughly seventeen grams per litre", "roughly 17 grams per litre", "approximately 17 grams per litre", "about 17 grams of sugar per litre", "17 g l of sugar", "divide by about 17", "seventeen grams a litre", "about seventeen grams a litre", "16 83 g l"], "ans": "About seventeen grams per litre", "ex": 1, "exp": "Stoichiometry alone would ask for about fifteen and a half grams a litre, since a gram of sugar yields at most 0.51 grams of ethanol. A real ferment returns only about ninety-two per cent of that, because some of the sugar goes to glycerol, biomass and the ferment's own acids, so the sugar actually needed for each per cent climbs to a shade under seventeen and cellars round it. Two hundred and twenty grams a litre therefore points at around thirteen per cent, which is why a refractometer reading at the vineyard gate is enough to say whether a lot will need correcting before it is picked."},
{"id": "c-j8fnd42e", "cat": "Wine Fundamentals", "q": "A tech sheet gives total sulphur dioxide at 110 milligrams per litre and free at 28, and the winemaker says the missing 82 is gone for good. What has happened to it, and why can it not be recovered?", "opts": ["It has settled into the lees and is racked away", "It has escaped as gas through the bung, and the only remedy is to top the barrel up more often than this cellar has been doing", "It has been consumed by the yeast as a nutrient and turned into cell material during the ferment", "It has combined with carbonyl compounds the ferment left behind, and almost none of it returns"], "a": 3, "exp": "Sulphur dioxide reacts with several compounds a ferment leaves behind, and the strongest of those bonds is effectively permanent: that sulphur neither preserves nor can be counted on. The weaker adducts, on pigment and on the keto acids, hand a little back as the free fraction is used up, which is why bound sulphur is discounted rather than ignored. A wine that binds heavily needs a larger total addition to reach the same free reading, which is why dirty or rot-affected fruit is expensive in sulphur long before anyone tastes the wine."},
{"id": "c-0bz1dqbi", "cat": "Wine Fundamentals", "q": "Only a few per cent of a wine's free sulphur dioxide is the undissociated species that actually kills a spoilage yeast, and how large that share is depends entirely on pH. Name that species.", "sa": 1, "accept": ["molecular sulphur dioxide", "molecular sulfur dioxide", "molecular so2", "molecular form", "molecular species", "molecular form of sulphur dioxide", "molecular sulphur dioxide so2", "molecular so2 molecular sulphur dioxide", "molecular sulphur dioxide molecular so2", "undissociated sulphur dioxide", "undissociated sulfur dioxide", "undissociated so2", "undissociated form", "undissociated molecule", "undissociated molecular sulphur dioxide", "molecular sulfur dioxide so2", "undissociated molecular so2", "molecular form of sulfur dioxide", "free molecular sulphur dioxide", "free molecular sulfur dioxide", "free molecular so2", "molecular so2 undissociated"], "ans": "Molecular sulphur dioxide", "ex": 1, "exp": "The free fraction sits in equilibrium between the undissociated molecule and its charged forms, and only the neutral molecule crosses a microbial cell membrane; the charged forms are turned back at the lipid bilayer, and what does get in meets a near-neutral interior that converts it to bisulphite, which cannot get out again. The share of it roughly halves for every three-tenths of a pH unit climbed, so a wine at 3.6 needs about twice the free sulphur of one at 3.3 and about four times that of one at 3.0 to be equally defended, which is the whole reason cellars dose from a table rather than to a habit."},
{"id": "c-zfauvzgc", "cat": "Wine Fundamentals", "q": "Sulphur dioxide added to a wine fresh off its fermentation vanishes from the free reading within hours, seized by a compound the yeast made on the way to ethanol and never finished reducing. Name that compound.", "sa": 1, "accept": ["acetaldehyde", "ethanal", "acetaldehyde ethanal", "ethanal acetaldehyde", "acetaldehyde ch3cho", "ch3cho", "ethanal ch3cho"], "ans": "Acetaldehyde", "ex": 1, "exp": "It is the strongest binder in wine, and the bond is effectively irreversible at cellar conditions. That cuts both ways: the sulphur is spent, but the acetaldehyde is also taken out of the aroma, which is why a lightly oxidised wine can be tidied up by an addition while a heavily bound one simply swallows everything it is given."},
{"id": "c-98nhwcnj", "cat": "Wine Fundamentals", "q": "Cellar hands weigh out a white powder by the gram rather than handling any gas, and it releases the preservative on contact with wine. Name that salt.", "sa": 1, "accept": ["potassium metabisulphite", "potassium metabisulfite", "potassium meta bisulphite", "potassium meta bisulfite", "pms", "potassium metabisulphite pms", "k2s2o5", "potassium metabisulphite powder", "kms", "potassium metabisulphite kms", "potassium pyrosulphite", "potassium pyrosulfite", "potassium metabisulfite pms", "potassium metabisulphite k2s2o5", "potassium metabisulfite k2s2o5", "potassium metabisulfite powder", "pms powder", "kms powder"], "ans": "Potassium metabisulphite", "ex": 1, "exp": "About 57 per cent of the weight of the powder becomes sulphur dioxide in the wine, so the arithmetic of a dose is never one for one, and many cellars work to a round half as a margin because stock that has been open to the air delivers less than the label says. The salt is chosen over its sodium equivalent because nobody wants to add sodium to a wine, and it is dissolved in a little wine before use rather than tipped into a full tank."},
{"id": "c-g7skhejs", "cat": "Wine Fundamentals", "q": "Titratable acidity falls after a red has been through its bacterial conversion, although every acid molecule removed has been replaced by another acid molecule. What accounts for the fall?", "opts": ["The acid lost carried two acid groups and the one replacing it carries one", "The wine warms as the bacteria work, driving acid off as vapour", "Alcohol made during the conversion dilutes what acid is left", "The bacteria neutralise part of the acidity with calcium released from the lees"], "a": 0, "exp": "A titration counts acid groups, so swapping a molecule with two of them for a molecule with one removes half the countable acidity at a stroke, and carbon dioxide is given off as the extra group leaves. The softening a taster notices is therefore partly a genuine loss of acid and partly the milder character of what remains, which is why the conversion is a far larger intervention in a cool-climate wine than in a warm one."},
{"id": "c-bsrh72vj", "cat": "Wine Fundamentals", "q": "One bacterial species does nearly all of the malolactic work in commercial cellars, because it tolerates low pH, high alcohol and sulphur better than its rivals. Name it.", "sa": 1, "accept": ["oenococcus oeni", "oenococcus", "o oeni", "leuconostoc oenos", "oenococcus oeni bacteria"], "ans": "Oenococcus oeni", "exp": "It was known for years under an older name before being reclassified, and either name still turns up in cellar literature. Its tolerance is the whole reason it is chosen: the other lactic acid bacteria found in wine will work in a soft, high-pH environment but bring spoilage characters with them, so a cellar that wants the conversion without the risk inoculates rather than waits."},
{"id": "c-sr7i8ae6", "cat": "Wine Fundamentals", "q": "A cellar wants the softening of malolactic conversion without the dairy note that often comes with it, so it co-inoculates early and leaves the wine on its yeast lees afterwards. Which compound is that regime aimed at?", "sa": 1, "accept": ["diacetyl", "2 3 butanedione", "butanedione", "diacetyl 2 3 butanedione", "diacetyl butanedione"], "ans": "Diacetyl", "exp": "Yeast reduce it to acetoin and then to butanediol, both of which are odourless at wine concentrations, so leaving the wine in contact with live yeast strips the character out again. Running the bacteria alongside the ferment rather than after it has the same effect for the same reason, which is why the buttery style is a choice rather than an inevitability."},
{"id": "c-0wq2siib", "cat": "Wine Fundamentals", "q": "Vitamin C goes into a white at bottling as an oxygen scavenger, and every textbook warns against using it in a wine short of sulphur dioxide. What is the danger?", "opts": ["It binds whatever free sulphur dioxide is left", "Scavenging leaves hydrogen peroxide behind, which does the worse damage", "It feeds any yeast that survived the filtration", "It strips the colour out of a white within days of bottling and leaves it looking tired"], "a": 1, "exp": "Ascorbic acid takes up oxygen readily, and the product of that reaction is a peroxide that goes on to oxidise the wine faster than the oxygen it removed would have. Sulphur dioxide mops the peroxide up, so the pair are used together or not at all, and a bottle dosed with the vitamin alone can brown within months."},
{"id": "c-m9bg74sb", "cat": "Wine Fundamentals", "q": "Oxygen does not attack a wine's alcohol directly. It is spent on the phenolics instead, producing a highly reactive product that browns a white and strips the aroma out of it. Name that product.", "sa": 1, "accept": ["quinones", "quinone", "o quinones", "o quinone", "ortho quinones", "ortho quinone", "orthoquinones", "orthoquinone", "quinone compounds", "phenolic quinones", "phenolic quinone", "quinones o quinones", "o quinones quinones"], "ans": "Quinones", "ex": 1, "exp": "Quinones are the fork in the road: they join up into the brown pigments that colour an old white, and they also seize on sulphur-bearing aroma compounds and take them out of the glass permanently. Making them is not a simple collision, because oxygen in its ordinary state is too unreactive to take a phenol on directly: the wine's traces of iron pass the electrons between the two, which is why metal content sets the pace at which a wine browns. That second reaction is why an oxidised aromatic white does not merely smell tired but smells of nothing, and why the loss cannot be reversed by any later addition."},
{"id": "c-rspxb203", "cat": "Wine Fundamentals", "q": "Closure suppliers sell screwcap liners and technical corks against a single published number, measured in milligrams a year. Name that specification.", "sa": 1, "accept": ["oxygen transmission rate", "oxygen transfer rate", "otr", "oxygen transmission rate otr", "oxygen ingress rate", "rate of oxygen transmission", "oxygen transmission", "oxygen ingress", "otr oxygen transmission rate", "oxygen transfer rate otr"], "ans": "Oxygen transmission rate", "ex": 1, "exp": "Quoting a figure lets a producer match the closure to the wine rather than to a tradition: an aromatic white wants the tightest liner available, while a structured red is often given a more permissive one on the argument that a trickle of air helps the tannin settle. It also made consistency measurable, which was the real complaint against natural cork rather than the average level of ingress."},
{"id": "c-qveh175l", "cat": "Wine Fundamentals", "q": "Musty bottles keep appearing from one winery under every closure it uses, and the trail runs back to a chlorine-based cleaner sprayed on the cellar timbers years earlier. Which sequence turned that cleaner into a taint?", "opts": ["Chlorine reacted directly with the wine's own alcohol in bottle to form a chlorinated ester with a musty smell", "Chlorine made chlorophenols in the wood, and moulds then methylated those into a haloanisole", "Chlorine killed the cellar's flora, and the taint came from their decay", "Chlorine bleached the wine's phenolics, and the musty smell is what was left once the colour had gone"], "a": 1, "exp": "Chlorine attacks the phenolic compounds in timber and cardboard to give chlorophenols, which are not especially smelly; the damage is done when ordinary cellar moulds add a methyl group and turn them into anisoles detectable at parts per trillion. The bromine equivalent works the same way off flame retardants and wood preservatives, which is why a building can taint every wine that passes through it whatever the bottles are sealed with."},
{"id": "c-y765sa0j", "cat": "Wine Fundamentals", "q": "Beetroot and damp earth on a wine made from rot-affected fruit is not a cork problem at all, but a compound made by moulds and soil bacteria out in the vineyard. Name it.", "sa": 1, "accept": ["geosmin", "geosmine", "geosmin taint"], "ans": "Geosmin", "exp": "It is the same molecule that gives soil its smell after rain, and the nose finds it at a few parts per trillion in water and at a few tens of parts per trillion in wine, where the matrix hides some of it. Because it arrives on the fruit rather than through the cellar, the defence is sorting and speed at the crusher: activated carbon will pull some of it out afterwards and takes the wine's own aroma with it, which is why nobody counts that as a cure."},
{"id": "c-fzvm469u", "cat": "Wine Fundamentals", "q": "Asked to confirm Brettanomyces in a suspect barrel, a laboratory reports the volatile phenol that carries the horse-and-farmyard note, in micrograms per litre. Name that compound.", "sa": 1, "accept": ["4 ethylphenol", "ethylphenol", "4 ethyl phenol", "ethyl phenol", "4ep", "4 ep", "four ethylphenol", "para ethylphenol", "4 ethylphenol 4 ep", "4 ep 4 ethylphenol"], "ans": "4-ethylphenol", "ex": 1, "exp": "The yeast decarboxylates a hydroxycinnamic acid that every red already carries and then reduces the product, and the analysis is far more reliable than a plate count because the cells can be scarce while the compound is not. Its partner reads as smoke and clove rather than farmyard, and the ratio between the two is roughly constant, which is why a laboratory can report one figure and a cellar can act on it."},
{"id": "c-c1otfgd5", "cat": "Wine Fundamentals", "q": "Vinegar and nail varnish arrive together on a red left in an ullaged barrel, and the laboratory reports an acid and its ethyl ester side by side. Which organism made them, and out of what?", "opts": ["Brettanomyces, working on the wine's glycerol", "Acetobacter, from ethanol and air", "Wine yeast, out of the sulphur compounds sitting in the lees", "Lactic acid bacteria, out of the last grams of residual sugar left in the barrel"], "a": 1, "exp": "Acetobacter and its relatives need oxygen, so the fault is a storage failure rather than a fermentation one: a barrel left short, a tank with a leaking valve, a cap allowed to dry out. The ester that smells of solvent is formed afterwards from the acid and the wine's own alcohol, which is why the two markers climb together and why the solvent note is often the first thing a taster catches."},
{"id": "c-4ix5bb61", "cat": "Wine Fundamentals", "q": "A length of copper wire dropped into a tank that smells of rotten eggs clears the smell within minutes, leaving a black precipitate behind. Name the compound the copper has taken out.", "sa": 1, "accept": ["hydrogen sulphide", "hydrogen sulfide", "h2s", "hydrogen sulphide h2s", "hydrogen sulfide h2s"], "ans": "Hydrogen sulphide", "exp": "Copper and sulphide form an insoluble black salt that drops out of solution, which is the whole of the trick. The treatment is far less reliable than it looks, because the heavier thiols and disulphides that give struck rubber and drains are not removed the same way and some of them are only masked, so a trial is run on a bench sample and the copper left in the wine is capped by law."},
{"id": "c-n4d36zds", "cat": "Wine Fundamentals", "q": "Left standing under a retailer's fluorescent tubes in clear glass, a rose picks up cooked cabbage and wet wool within weeks, and the reaction starts from a vitamin the wine carries. Name that fault.", "sa": 1, "accept": ["lightstrike", "light strike", "light struck", "lightstruck", "light strike taint", "gout de lumiere"], "ans": "Lightstrike", "exp": "Riboflavin absorbs light in the blue and near-ultraviolet, and the excited molecule pulls a sulphur-bearing amino acid apart into compounds that smell of boiled vegetables. Green and brown glass filter most of the damaging wavelengths and flint glass filters almost none, which is why the fault is commonest in exactly the pale wines most often bottled in clear glass."},
{"id": "c-1u498g4s", "cat": "Wine Fundamentals", "q": "Fifteen years under screwcap leave a Riesling honeyed and complex, and the total oxygen admitted over that time would not fill a teaspoon. What does that establish about maturation in glass?", "opts": ["A screwcap admits far more oxygen than a cork does over that span", "Oxygen must be passing through the glass itself", "Most of it is rearrangement among compounds already in the wine, not reaction with air", "The wine had to have been oxidised deliberately before bottling"], "a": 2, "exp": "Aroma compounds sit in a young wine bound to sugars and hidden, and the wine's own acidity slowly cuts them loose without any oxygen involved; acids and alcohols also drift toward an equilibrium of esters over years. Oxygen matters at the margin and matters enormously once it is excessive, but the honeyed development of a well-sealed white is a rearrangement of what was already in the bottle."},
{"id": "c-ri93099f", "cat": "Wine Fundamentals", "q": "Sun exposure in the vineyard and years in bottle together build the petrol note of a mature Riesling out of carotenoid precursors laid down in the berry. Give the name of the compound responsible, or its usual abbreviation.", "sa": 1, "accept": ["tdn", "t d n", "trimethyldihydronaphthalene", "trimethyl dihydronaphthalene", "tdn trimethyldihydronaphthalene", "1 1 6 trimethyl 1 2 dihydronaphthalene", "1 1 6 trimethyldihydronaphthalene", "1 1 6 trimethyl dihydronaphthalene", "trimethyldihydronaphthalene tdn", "trimethyl dihydronaphthalene tdn", "1 1 6 trimethyl 1 2 dihydronaphthalene tdn", "1 1 6 trimethyldihydronaphthalene tdn", "1 1 6 trimethyl dihydronaphthalene tdn", "1 1 6 trimethyl 1 2 dihydronaphthalene or tdn"], "ans": "TDN", "ex": 1, "exp": "The precursor is odourless and accumulates in the skin under strong light and mild water stress, then converts slowly in the acid conditions of the bottle, which is why the character appears with age rather than at bottling and why a warm, exposed site delivers more of it. Shading the fruit and a cooler site both hold it down, and it is one of the few tertiary characters a grower can influence in the vineyard."},
{"id": "c-hpi2lzhe", "cat": "Wine Trade & Aging", "q": "Selling a case of a blue-chip vintage, a merchant weighs entering it in an auction against posting an offer on the trade's exchange. What does the exchange route give that the saleroom cannot?", "opts": ["A standing market: the case can be offered at the merchant's own price on any day of the year", "A guaranteed buyer, because the exchange itself takes in any case that fails to find a bid within the month", "An immediate cash advance, secured against the case while it waits to sell", "A wider audience, since exchanges are open to the public while salerooms admit only registered trade buyers"], "a": 0, "exp": "An exchange holds standing bids and offers the way a stock market does, so a seller names a price and waits for it to be lifted, with no consignment deadline, no sale calendar and a flat transaction charge. The saleroom's strengths run the other way: theatre, a worldwide audience gathered on one afternoon, and the chance that two bidders push each other past any listed price."},
{"id": "c-x3u080vz", "cat": "Wine Trade & Aging", "q": "Offered a parcel by a private client, one firm pays the same week and takes the cases into its own stock; another circulates the offer to its customers and pays the client only when a buyer signs. What is the second firm doing?", "opts": ["Underwriting it, guaranteeing the client a floor price whatever a buyer eventually pays", "Consigning it to auction on the client's behalf, with a reserve set at the level of the first firm's offer", "Broking the parcel: it never takes ownership, earns a commission on the sale, and leaves the waiting and the price risk with the seller", "Warehousing it, charging rent until the market catches up with the asking price"], "a": 2, "exp": "A merchant buys stock outright, so the client is paid at once and the firm's margin is whatever the market later allows; a broker sells first and settles after, keeping a cut without ever owning a bottle. The broker's client usually nets more and always waits longer, and the merchant's client trades a slice of the price for certainty and speed."},
{"id": "c-zz898pv5", "cat": "Wine Trade & Aging", "q": "The seller's settlement from a saleroom is built down from the figure at which the bidding stopped, and the buyer's invoice is built up from the same figure. What is that figure called?", "sa": 1, "accept": ["hammer price", "hammer prices", "hammer", "final hammer price", "its hammer price", "the hammer price of the lot", "the hammer figure", "it is the hammer price", "it's the hammer price", "that is the hammer price", "knock down price", "knockdown price"], "ans": "The hammer price", "ex": 1, "exp": "Everything in an auction settles around it: the seller is typically paid it minus the house's selling commission, and the buyer pays it plus the house's charges, so the number called out in the room is usually one that neither side pays or receives exactly. Estimates and reserves are quoted against it too, which is why one lot can be honestly reported at three different figures: what the room heard, what the seller banked and what the buyer finally paid."},
{"id": "c-4o414ulz", "cat": "Wine Trade & Aging", "q": "A winning bid of ten thousand becomes an invoice for twelve and a half before delivery has even been arranged. Name the charge that grew it.", "sa": 1, "accept": ["buyer's premium", "buyers premium", "buyer premium", "premium", "premiums", "buyer's premiums", "buyers premiums", "the auction house's premium", "auction house premium", "the auction house's buyer's premium", "auction premium", "the house's premium", "the house premium", "it is the buyer's premium", "it's the buyer's premium", "that is the buyer's premium"], "ans": "The buyer's premium", "ex": 1, "exp": "It is the house's charge to the winning bidder, added as a percentage on top of the bid, and at the major houses it runs to a fifth or a quarter of it. Comparing an auction result against a merchant's list price without adding it on is the classic way to overstate what the saleroom saves."},
{"id": "c-dqqat266", "cat": "Wine Trade & Aging", "q": "One word on a catalogue page carries where a bottle has spent its life, in whose hands and in what conditions, and it moves the price more than the tasting note beside it. Give the word.", "sa": 1, "accept": ["provenance", "its provenance", "good provenance", "documented provenance", "~the wine's provenance", "~the bottle's provenance", "~provenance of the bottle"], "ans": "Provenance", "exp": "It is the record of custody and keeping: who bought the bottle, where it lay, how it travelled. Two physically identical bottles can part on price several times over on the strength of that record, because storage cannot be tasted in advance and the written history is the only forecast a buyer gets without pulling the cork."},
{"id": "c-550ln3ph", "cat": "Wine Trade & Aging", "q": "Back vintages released by the producing estate itself, having never left its own walls, are listed under a hyphenated term that reliably commands a premium. Give the term.", "sa": 1, "accept": ["ex cellar", "ex cellars", "ex cellar release", "ex cellar stock", "released ex cellar", "sold ex cellar", "ex chateau"], "ans": "Ex-cellar", "exp": "The premium is for certainty: the storage history is a single line, the labels and corks are beyond argument, and the market has had no chance to substitute or damage anything. Estates have learned to bank that certainty, releasing old vintages in measured parcels at prices the trade reads as the wine's new floor."},
{"id": "c-z8sl4xdz", "cat": "Wine Trade & Aging", "q": "Under a loupe, the label of a supposed 1920s bottle resolves into the tidy rosette of dots a modern press lays down. What has the examiner established?", "opts": ["That the paper was artificially aged, regular dots being the mark bleach leaves as it breaks down the fibres of a modern sheet", "That the label was printed by a modern process never used on wine labels of the claimed era", "That the label is a legitimate replacement, reissued by the estate for damaged stock", "That the ink has faded evenly, which is what six decades in a dark cellar produces"], "a": 1, "exp": "Labels of that era were printed by letterpress or stone lithography, which lay down solid areas of ink; the even rosette of dots is the mark of modern offset and digital presses, which wine labels only met decades later. The finding condemns the label absolutely and the bottle almost as surely, since a genuine bottle has little reason to wear paper from the wrong half of the century, and it is the kind of physical evidence no story about the wine can argue with."},
{"id": "c-66uj3dd1", "cat": "Wine Trade & Aging", "q": "A magnum surfaces carrying a celebrated estate's label and a vintage twenty years before the estate's own records show it first made that wine. What has the check against the records established?", "opts": ["That the label has merely been misdated, leaving the wine inside above suspicion", "That a lost bottling has surfaced, ledgers of that era being too patchy to prove a negative", "That an old cellar mix-up occurred, the magnum having been dressed in a neighbouring estate's labels before shipping", "That the bottle is a fake, since the wine it claims to be was never made"], "a": 3, "exp": "A producer's own registers are the one reference a forger cannot fully study in advance, and a vintage that predates the wine's existence is the cleanest verdict there is: no tasting, no laboratory and no argument. Several celebrated counterfeiting cases broke on exactly this check, on large formats of vintages the estate never bottled in that size or never made at all."},
{"id": "c-v1lvd476", "cat": "Wine Trade & Aging", "q": "Ends of service in serious restaurants can finish with the night's grandest empties scored, smashed or stripped before the bins go out. What use is being denied to somebody?", "sa": 1, "accept": ["refilling them as counterfeits", "refilling", "refilling them", "refills", "refilled", "being refilled", "refilling them with lesser wine", "refilling with cheap wine", "counterfeit refills", "refilling and reselling", "passing them off refilled", "making fakes", "making counterfeits", "making fake wine from them", "making counterfeit wine from them", "~to make fakes", "~to make counterfeits", "~to make fake wine", "~to make counterfeit wine", "~to fake wine", "~to counterfeit wine", "~for fakes", "~for counterfeits", "~for counterfeiting", "~for faking", "~for making fakes", "~for making counterfeits", "~refill and resell", "~refill them"], "ans": "Refilling them as counterfeits", "exp": "A convincing fake starts from a genuine bottle, and an intact empty of a great name, its label and capsule undamaged, is worth real money to the wrong buyer. Defacing the shell costs the restaurant nothing and removes the raw material, which is why some cellars log and destroy their empties as carefully as they logged the full bottles in."},
{"id": "c-y6n1y7m5", "cat": "Wine Trade & Aging", "q": "Before a large cellar is catalogued, a specialist walks it bottle by bottle, noting fills, labels, capsules and cases. Name the document that comes out of that visit.", "sa": 1, "accept": ["condition report", "condition reports", "inspection report", "condition notes", "cellar condition report", "condition survey", "report on condition"], "ans": "A condition report", "exp": "Every serious sale rests on it: the catalogue's fill levels, label descriptions and case notes are lifted from that inspection, and the buyer's remedies afterwards reach only as far as what it disclosed. It is also the moment doubtful bottles are quietly pulled, because a house's name suffers more from one fake sold than from a hundred lots declined."},
{"id": "c-k8s66xpl", "cat": "Wine Trade & Aging", "q": "Sixty years old yet filled high into the neck, a bottle escapes suspicion because its back label records a visit to the estate, where it was opened, assessed, brought back to level and resealed. What is that service called?", "sa": 1, "accept": ["reconditioning", "reconditioned", "being reconditioned", "recorking", "recorked", "re corking", "re corked", "a recorking clinic", "recorking and topping up", "topping up and recorking", "estate reconditioning"], "ans": "Reconditioning", "exp": "A few estates run clinics for exactly this, certifying what they refresh, and an honest catalogue always says when a bottle has been through one. Opinion divides on the result: the level and the seal are renewed, but a little young wine has entered an old bottle, and some buyers discount the intervention more steeply than they would have discounted the risk."},
{"id": "c-g226ujae", "cat": "Wine Trade & Aging", "q": "Priced side by side, a case at 800 in bond and the same case at 990 with taxes paid are nearer in true cost than the gap suggests. What narrows it?", "opts": ["Nothing narrows it, wine in bond being the cheaper route in every circumstance", "The taxes-paid price includes insurance and delivery, which the warehouse bills separately", "Storage and insurance charges on the bonded case, which mount year after year until they have swallowed the whole of the difference", "Duty and sales tax fall due on withdrawal, so the saving is real only for a buyer who sells on in bond"], "a": 3, "exp": "In bond means the case has never had duty or sales tax paid on it, and both charges crystallise the moment it is withdrawn, calculated at whatever rates then apply. For a buyer who means to drink the wine the two offers are nearly level; for one who may resell, the untaxed case is worth more, because the next buyer inherits the same deferral and an export never triggers the charges at all."},
{"id": "c-cw08b6ui", "cat": "Wine Trade & Aging", "q": "Three owners in a decade, and the case has never once left its rack: the trade counts that a virtue. Why?", "opts": ["Wine sold at auction may not travel until every earlier owner has signed off its release, which can take years", "Every journey risks heat, shock and a break in the storage record, so ownership moves across the keeper's books while the wine sits still", "Each move triggers a fresh round of duty, so a case that travels is taxed three times over", "Moving a case voids the insurance under which the first owner stored it, and cover cannot be cheaply rebought"], "a": 1, "exp": "A case is a physical object whose value rests partly on how it has been kept, so the fewer vans and hands it meets the better, and a keeper who records each change of owner lets title move while the wine does not. Staying put also keeps the storage history unbroken under one roof, which is precisely the thing the next buyer will pay for."},
{"id": "c-ivrzbpoy", "cat": "Wine Trade & Aging", "q": "A case can lie for thirty years under a roof the revenue treats as though it were outside the country, its keeper standing surety for the tax on everything stored there. Name the building.", "sa": 1, "accept": ["~bonded warehouse", "~bonded warehouses", "~bonded wine warehouse", "~customs warehouse", "~excise warehouse", "~bonded store", "~bonded storage", "~bonded warehousing", "freeport", "free port"], "ans": "A bonded warehouse", "ex": 1, "exp": "The name is literal: the keeper's bond is a guarantee lodged with the revenue, and behind it the duty and sales tax sit as a liability carried by the case rather than a cost already paid. A sale from one account to another inside the walls hands that liability on with the wine, which is why so much fine wine spends its entire life under one roof, changing hands on paper and never on a pallet."},
{"id": "c-kcqu7r6o", "cat": "Wine Trade & Aging", "q": "After a warehouse fire, a collection insured for what it originally cost cannot be rebought at today's prices. Which basis should the policy have been written on?", "sa": 1, "accept": ["~replacement value", "~replacement cost", "~replacement price", "market value", "current market value", "today's market value", "todays market value", "current market price", "market price", "today's market price", "todays market price", "present market value", "current value", "market valuation", "current market valuation", "todays value", "today's value"], "ans": "Replacement value", "ex": 1, "exp": "Fine wine appreciates, so a policy indexed to old invoices is quietly underinsured a little more each year, and the gap surfaces on the worst possible day. Professional storage policies track a market valuation and move with it, which is why insurers ask for a cellar to be revalued from time to time rather than merely listed once."},
{"id": "c-96upusir", "cat": "Wine Trade & Aging", "q": "Listings compress it to three letters, and twelve bottles still in one outsell the same twelve repacked into cardboard. What do the letters OWC stand for?", "sa": 1, "accept": ["original wooden case", "original wood case", "original wooden cases", "in its original wooden case", "its original wooden case"], "ans": "Original wooden case", "exp": "The branded case is part of the object: it protects the bottles, carries the estate's marks, and implies the parcel has stayed together and undisturbed since it left the property. Auction convention states it in the catalogue line, and a case broken up or repacked surrenders a measurable slice of the price."},
{"id": "c-b9r30bx0", "cat": "Wine Trade & Aging", "q": "Forty years from the vintage, four bottles of one claret show fills at base of neck, top shoulder, mid shoulder and low shoulder. Which one does the trade refuse, and why?", "opts": ["Base of neck, a fill that high after forty years being possible only in a bottle that has been opened and topped back up", "Top shoulder, any fill below the base of the neck meaning the seal has already given way", "Low shoulder, loss on that scale pointing to a failed cork rather than to age", "Mid shoulder, the halfway mark on the scale being where buyers draw the line whatever the age"], "a": 2, "exp": "Gentle loss is the normal work of four decades, so base of neck is excellent, top shoulder unremarkable, and even mid shoulder within the range a cataloguer will describe rather than reject. Low shoulder is different in kind: that much wine has not slipped slowly past a sound cork, it has escaped past a failing one, and air has been taking its place the whole time."},
{"id": "c-yqxiozm7", "cat": "Wine Trade & Aging", "q": "Catalogues grade every mature lot by the gap that has opened between the bottom of the cork and the surface of the wine. What is the gap called?", "sa": 1, "accept": ["ullage", "its ullage", "ullage level"], "ans": "Ullage", "exp": "The word covers both the space itself and the scale of descriptions built on it, and a little of it is the expected cost of decades under cork. What a cataloguer actually reads is the rate: a level normal for fifty years is alarming at fifteen, and two bottles of one vintage with very different levels have led different lives."},
{"id": "c-kuhjqepm", "cat": "Wine Trade & Aging", "q": "Slope-shouldered bottles give the shoulder scale nothing to point at, so the fill of an old Burgundy is reported another way. How?", "sa": 1, "accept": ["in centimetres below the cork", "centimetres below the cork", "in centimeters below the cork", "centimeters below the cork", "cm below the cork", "in cm below the cork", "centimetres from the cork", "centimeters from the cork", "cm from the cork", "distance below the cork", "distance from the cork", "as a distance below the cork", "~below the base of the cork", "~from the base of the cork", "~centimetres of ullage", "~centimeters of ullage", "~cm of ullage", "ullage in centimetres below the cork", "ullage in cm below the cork", "~measured below the cork", "~measured from the cork"], "ans": "In centimetres below the cork", "exp": "A Bordeaux bottle's straight shoulder gives the scale its named stations, and a Burgundy has none, so the trade states the plain distance from the base of the cork to the wine. Up to three centimetres is unremarkable in a mature bottle, four or five earns a cautionary note, and beyond that the price is expected to answer for the risk."},
{"id": "c-85w76jrn", "cat": "Wine Trade & Aging", "q": "Same case, same cellar, ten years on: one bottle sings and its neighbour is tired, and an old trade saying blames the bottles rather than the wine. Name the phenomenon.", "sa": 1, "accept": ["bottle variation", "bottle variance", "~bottle to bottle variation", "~bottle by bottle variation", "~variation between bottles", "~variation from bottle to bottle"], "ans": "Bottle variation", "exp": "Corks are natural and individual, so every bottle has been running its own experiment down the years, and the differences compound with age. It is why the saying goes that there are no great old wines, only great old bottles, and why a serious tasting of an old vintage opens several and judges the wine on the best of them."},
{"id": "c-sgjvv9vx", "cat": "Wine Trade & Aging", "q": "Beside its score for a young Medoc, a critic prints the range 2030-2055. What is that range actually claiming?", "opts": ["The span during which the producer has undertaken to replace any bottle that turns out corked", "An estimate of the years in which the wine should show its best, revisable as it evolves", "A warranty that the wine remains sound until the second date printed, and turns undrinkable once that year has passed", "The period in which the vintage may lawfully be resold at auction"], "a": 1, "exp": "A window is a forecast of trajectory: when the structure should have knitted, how long the fruit should hold, and when the balance is likeliest to please. Critics revise them at re-tastings, sometimes by a decade, and a wine at the far edge of its window has not expired; it has merely entered the years in which decline becomes the way to bet."},
{"id": "c-4cnz8erc", "cat": "Wine Trade & Aging", "q": "Twenty years into a case, the fruit is drying out while the tannin still rasps. What should the owner conclude about the bottles that remain?", "opts": ["Drink or sell them now, because lost fruit does not come back and the structure will outlast what is left of it", "Serve the next bottle warmer, since tannin always reads harder in a cold glass", "Decant the next bottle for several hours, the rasp being travel shock rather than maturity", "Hold them for another decade at least, tannin that still rasps being the surest sign that the wine has not yet arrived in its drinking window"], "a": 0, "exp": "Maturity is a race between the softening of structure and the fading of fruit, and once the fruit is losing there is nothing later years can add: tannin outliving flavour is the classic profile of a wine going downhill. The response is commercial as much as sensory, because the market pays for wine approaching its best years and discounts wine leaving them."},
{"id": "c-s2k65qwc", "cat": "Wine Trade & Aging", "q": "Midway between vibrant youth and mature complexity, a serious red can spend years offering hardly any aroma at all. What does the trade call that stretch?", "sa": 1, "accept": ["dumb phase", "dumb period", "dumb stage", "its dumb phase", "closed phase", "closed period", "closed stage", "shut down phase", "~it is closed", "~it's closed", "~its closed", "~wine is closed", "~bottle is closed", "it has shut down", "closed down", "awkward phase", "adolescent phase", "the sulk", "sulking"], "ans": "The dumb phase", "exp": "Primary fruit recedes before the rewards of age arrive to replace it, and in that trough the wine can taste of remarkably little without anything being wrong. Opening a great vintage during the sulk is the classic way to conclude, wrongly, that it was overrated, which is why the windows on serious wines often start a surprising number of years out."},
{"id": "c-ieisl83l", "cat": "Wine Trade & Aging", "q": "Built to repay keeping rather than to charm on release, such a wine goes under a three-word French term every buyer of fine lists knows. Give the term.", "sa": 1, "accept": ["vin de garde", "vins de garde"], "ans": "Vin de garde", "exp": "The phrase means a wine for keeping, and it marks out the minority built with the concentration and structure to be better in ten years than now. Its opposite number is the wine made for the year of its release, which does not improve however carefully it is stored: cellaring can only ripen what was put in the bottle to begin with."},
{"id": "c-gu3rksdg", "cat": "Wine Trade & Aging", "q": "Opened together at twenty years, the half bottles of a vintage are fading while the magnums are barely ready. What explains the spread?", "opts": ["Cork and headspace hardly change with bottle size, so the smaller volume feels their influence sooner", "Half bottles spend more of their lives standing upright on shelves and in fridges, and standing up wears a wine out early", "Thicker magnum glass shuts out light and temperature swings entirely", "Magnums are traditionally filled from the best barrels in the cellar, a custom the leading estates keep to this day"], "a": 0, "exp": "Every size is stoppered with much the same cork over much the same gap of air, so the ration of air per litre shrinks as the format grows, and the wine in a magnum has more of itself to share the work across. That is why large formats are the collector's choice for the long haul, and why halves are opened early to find out what a vintage has in it."},
{"id": "c-6u4gp8ug", "cat": "Wine Trade & Aging", "q": "Certain Californian cellars sell nothing through shops: a customer waits years to be offered a place, and once admitted must take up every release or lose the spot. What is the customer's name finally on?", "sa": 1, "accept": ["~mailing list", "~mailing lists", "~allocation list"], "ans": "The mailing list", "ex": 1, "exp": "The list is the whole route to market for the American cult wine: no merchant, no shelf, just an offer sent to each name and a file of hopefuls waiting for a name to drop off. Skipping a release forfeits the place, which is how weak vintages sell out as quickly as great ones, and a spot on the best lists has itself become something collectors boast of."},
{"id": "c-y2qlzsay", "cat": "Wine Trade & Aging", "q": "Money handed over long before the bottles exist can be lost without the price ever moving. Which failure does a futures buyer actually need to fear?", "sa": 1, "accept": ["~merchant's", "~seller's", "~counterparty's", "~merchant insolvency", "~merchant insolvent", "~merchant bankruptcy", "~merchant bankrupt", "~merchant failure", "~merchant liquidation", "~merchant administration", "~merchant receivership", "~merchant collapse", "~merchant default", "~merchants insolvency", "~merchants bankruptcy", "~merchants failure", "~merchants collapse", "~seller insolvency", "~seller bankruptcy", "~seller failure", "~seller collapse", "~seller default", "~counterparty insolvency", "~counterparty bankruptcy", "~counterparty failure", "~counterparty collapse", "~counterparty default", "~counterparty risk", "~merchant going", "~merchant goes", "~merchant becoming", "~merchant becomes", "~merchant fails", "~merchant failing", "~merchant collapses", "~merchant collapsing", "~merchant defaults", "~merchant defaulting", "~merchant folds", "~merchant folding", "~merchant ceasing", "~seller going", "~seller goes", "~seller becoming", "~seller becomes", "~seller fails", "~seller failing", "~seller collapses", "~seller collapsing", "~seller defaults", "~seller defaulting", "~counterparty going", "~counterparty goes", "~counterparty fails", "~counterparty failing", "~counterparty defaults", "~counterparty defaulting", "~of the merchant", "~of the seller", "~wine merchant", "~merchant you paid", "~merchant i paid"], "ans": "The merchant's insolvency", "ex": 1, "exp": "Until specific cases are identified as the buyer's property, the money is only an unsecured claim on the firm, and wine ordered but never segregated goes into the pot for all the creditors. Merchant collapses have burned futures buyers in exactly this way, which is why the careful ones ask where their wine will lie, and in whose name, before they pay."}
];
